(function()
  function GetMyId()
    local ds = DsTable.Find("BaseClient.GroupMemberData")
    if ds then
      return ds:GetData(0, 1)
    end
  end
  function GuiOnSave()
    GuiSaver:Begin()
    GuiSaver:SaveAppWindowPosition("wndChat")
    GuiSaver:End()
  end
  function GuiSetWindowPositions()
    GuiRestoreAppWindowPosition("wndChat")
  end
  GuiVars = {StartupWindowShown = 0}
  function GuiOnInit()
    guiInitModule("Main")
    local W = Window.Find("Main.wndChat")
    if W then
      W:Show()
    end
    clear()
    GuiSetWindowPositions()
    Ui.SetTheme("FreeRealms")
    InitChatBubble()
    GaqItemManager:Init()
    chatHandler:Init()
    View.SetCameraFov(65)
    Startup()
  end
  SceneText = {
    OnResize = function(self)
      local sw, sh = Window.GetCanvasSize()
      Window.Find("Main.wndSceneText"):SetSizeScaled(sw, sh)
    end,
    Init = function(self)
      local sw, sh = Window.GetCanvasSize()
      Window.Find("Main.wndSceneText"):Show()
      Window.Find("Main.wndSceneText"):SetSizeScaled(sw, sh)
      NonModalContext:AddContext(SceneText)
      GfxCtrl.Find("Main.wndSceneText.swfSceneText"):Invoke("SetLocalPlayer", Ui.GetPlayerGuid())
      if GfxCtrl.SetLimitAdvance then
        GfxCtrl.Find("Main.wndSceneText.swfSceneText"):SetLimitAdvance(true, 0.01)
      end
    end
  }
  function Main_wndSceneText_swfSceneText_OnUserEvent(a, b, c)
    Logger:print("startup.lua", a .. " " .. b .. " " .. c)
  end
  function Startup()
    local sw, sh = Window.GetCanvasSize()
    DsTable.Find("BaseClient.ClosestInteractionTargetData"):EnableScriptEvents()
    DsTable.Find("BaseClient.CurrentPOI"):EnableScriptEvents()
    DsTable.Find("BaseClient.Matchmaking.Requests"):EnableScriptEvents()
    DataSourceConnection:Connect("BaseClient.PetList", PetsFte, "FirstPetFTECheck")
    local showMyNamePlate = Options:CheckStoredOption("NamePlateSettings", "ShowMyNamePlate", 1)
    local showAllNamePlates = Options:CheckStoredOption("NamePlateSettings", "ShowAllNamePlates", 1)
    local invertMouse = Options:CheckStoredOption("MouseSettings", "InvertMouse", 0)
    if showMyNamePlate == "1" then
      Ui.ShowMyNamePlate()
    else
      Ui.HideMyNamePlate()
    end
    if showAllNamePlates == "1" then
      Ui.ShowNamePlates()
    else
      Ui.HideNamePlates()
    end
    if invertMouse == "1" then
      Ui.SetMouseInvert(1)
    else
      Ui.SetMouseInvert(0)
    end
    if QuestScreen.GetSelectedQuest then
      QuestHelper.helperCurrentQuest = QuestScreen.GetSelectedQuest()
    end
    DsTable.Find("BaseClient.MiniGame"):EnableScriptEvents()
    MiniGameStatusHandler:Populate()
    SceneText:Init()
    EmoteHandler:Init()
  end
  function GuiOnShutdown()
    if DesignTools_OnShutdown then
      DesignTools_OnShutdown()
    end
    collectgarbage()
  end
  if systemDoFile == nil then
    systemDoFile = dofile
    function dofileInternalOnlyCommand(theFile)
      print("/dofile " .. Client.PathScripts .. theFile)
      print("---------------------------------------")
      print("Include new *.lua file in scripts.txt.")
      systemDoFile(Client.PathScripts .. theFile)
    end
  end
end)()
;(function()
  Client.ContextDepth = 0
  Context = {
    mList = {},
    GetCurrent = function(self)
      if Client.ContextDepth > 0 then
        return self.mList[Client.ContextDepth].Name
      end
    end,
    IsCurrent = function(self, testContextName)
      return testContextName == self:GetCurrent()
    end,
    Includes = function(self, testContextName)
      local index = Client.ContextDepth
      while index > 0 do
        if self.mList[index].Name == testContextName then
          return true
        end
        index = index - 1
      end
      return false
    end,
    RemoveByName = function(self, testContextName)
      if Client.ContextDepth == 0 then
        return
      end
      local newList = {}
      local newDepth = 0
      local index = Client.ContextDepth
      for index = 1, Client.ContextDepth do
        if self.mList[index].Name == testContextName then
          if Client.ContextDepth > 0 then
            Ui.SetKeyboardEnabled(self.mList[index].Movement)
            Ui.SetMovementEnabled(self.mList[index].Movement)
          else
            Ui.SetMovementEnabled(1)
            Ui.SetKeyboardEnabled(1)
          end
          self:CallOptionalOnPop(index)
        else
          newDepth = newDepth + 1
          newList[newDepth] = self.mList[index]
        end
      end
      self.mList = newList
      Client.ContextDepth = newDepth
    end,
    ClearToInclusive = function(self, testContextName)
      local done
      while Client.ContextDepth > 0 and not done do
        if self.mList[Client.ContextDepth].Name == testContextName then
          done = true
        end
        local previousName = self:GetCurrent()
        local previousDepth = Client.ContextDepth
        self:CallQuit()
        if Client.ContextDepth == previousDepth then
          self:Pop()
        end
      end
    end,
    Clear = function(self, doNotRun)
      while Client.ContextDepth > 0 do
        local previousName = self:GetCurrent()
        local previousDepth = Client.ContextDepth
        if doNotRun == true then
        else
          self:CallQuit()
        end
        if Client.ContextDepth == previousDepth then
          self:Pop()
        end
      end
    end,
    Push = function(self, theName, escapeFunction, optionalPopFunction, optionalAllowMovement)
      if self:Includes(theName) then
        return
      end
      Client.ContextDepth = Client.ContextDepth + 1
      local mTemp = 1
      mTemp = Ui.GetMovementEnabled()
      self.mList[Client.ContextDepth] = {
        Name = theName,
        Function = escapeFunction,
        OptionalOnPopFunction = optionalPopFunction,
        Movement = mTemp
      }
      if optionalAllowMovement then
        Ui.SetKeyboardEnabled(1)
        Ui.SetMovementEnabled(1)
      else
        Ui.SetMovementEnabled(0)
      end
    end,
    CallOptionalOnPop = function(self, index)
      if index ~= nil and self.mList[index] and self.mList[index].OptionalOnPopFunction then
        self.mList[index].OptionalOnPopFunction()
      end
    end,
    Pop = function(self, indexOverride)
      local i = Client.ContextDepth
      if Client.ContextDepth > 0 then
        Client.ContextDepth = Client.ContextDepth - 1
      end
      if Client.ContextDepth > 0 then
        Ui.SetKeyboardEnabled(self.mList[i].Movement)
        Ui.SetMovementEnabled(self.mList[i].Movement)
      else
        Ui.SetMovementEnabled(1)
        Ui.SetKeyboardEnabled(1)
      end
      self:CallOptionalOnPop(i)
    end,
    CallQuit = function(self)
      if Client.ContextDepth > 0 then
        Logger:print("context.lua", "Context: CallQuit() " .. self.mList[Client.ContextDepth].Name)
        self.mList[Client.ContextDepth].Function()
      end
      self:CallOptionalOnPop(Client.ContextDepth)
    end,
    Show = function(self)
      print("Context has " .. tostring(Client.ContextDepth) .. " level(s)")
      local i = 1
      while i <= Client.ContextDepth do
        print(tostring(i) .. ":" .. self.mList[i].Name)
        i = i + 1
      end
    end
  }
end)()
;(function()
  FunctionStack = {
    m_stackListDepth = 0,
    m_stackList = {},
    Push = function(self, stackName, functionName, theFunction)
      if not self:StackExists(stackName) then
        local newStack = {Depth = 1}
        self.m_stackListDepth = self.m_stackListDepth + 1
        self.m_stackList[self.m_stackListDepth] = {
          StackName = stackName,
          Stack = newStack,
          Depth = 0
        }
      end
      local stackTable = self:GetStackTable(stackName)
      stackTable.Stack[stackTable.Depth] = {Name = functionName, Function = theFunction}
      stackTable.Depth = stackTable.Depth + 1
    end,
    Pop = function(self, stackName)
      local stackTable = self:GetStackTable(stackName)
      if stackTable.Depth > 0 then
        stackTable.Depth = stackTable.Depth - 1
        return stackTable.Stack[stackTable.Depth].Function
      end
      return false
    end,
    StackExists = function(self, stackName)
      local index = self.m_stackListDepth
      while index > 0 do
        if self.m_stackList[index].StackName == stackName then
          return true
        end
        index = index - 1
      end
      return false
    end,
    GetStackTable = function(self, stackName)
      local index = self.m_stackListDepth
      while index > 0 do
        if self.m_stackList[index].StackName == stackName then
          return self.m_stackList[index]
        end
        index = index - 1
      end
      return nil
    end,
    GetStackDepth = function(self, stackName)
      local index = self.m_stackListDepth
      while index > 0 do
        if self.m_stackList[index].StackName == stackName then
          return self.m_stackList[index].Depth
        end
        index = index - 1
      end
      return 0
    end,
    PopIfExists = function(self, stackName)
      if self:GetStackDepth(stackName) > 0 then
        return self:Pop(stackName)
      end
      return false
    end,
    PopAndRun = function(self, stackName)
      if self:GetStackDepth(stackName) > 0 then
        local func = self:Pop(stackName)
        if func then
          func()
        end
        return true
      end
      return false
    end
  }
end)()
;(function()
  NonModalContext = {
    mContextList = {},
    mWidth = -1234,
    mHeight = -1234,
    Show = function(self)
      print("NonModalContext:Show")
      for k, v in pairs(self.mContextList) do
        print("    -> " .. tostring(k) .. ", " .. tostring(v))
      end
    end,
    OnResize = function(self)
      local w, h = Window.GetCanvasSize()
      if w ~= self.mWidth or h ~= self.mHeight then
        self.mWidth = w
        self.mHeight = h
        for k, v in pairs(self.mContextList) do
          v:OnResize()
        end
      end
    end,
    AddContext = function(self, context)
      if context.OnResize then
        self.mContextList[context] = context
      end
    end,
    RemoveContext = function(self, context)
      if self.mContextList[context] then
        self.mContextList[context] = nil
      end
    end
  }
  function SetUiScale(uiscale)
    Ui.SetScale(uiscale)
    NonModalContext.mWidth = 100
    NonModalContext:OnResize()
  end
end)()
;(function()
  UpdateList = {}
  function OnUpdate()
    for x in pairs(UpdateList) do
      UpdateList[x]:Update()
    end
  end
end)()
;(function()
  Delegate = {
    AddSupportToClassObject = function(self, classObject, className)
      classObject.connectedObject = nil
      classObject.className = className
      function classObject:Connect(listener)
        if self.connectedObject then
          Logger:print("delegate.lua", "(lua) warning! object not disconnected from " .. self.className)
        end
        self.connectedObject = listener
      end
      function classObject:Disconnect(listener)
        if self.connectedObject == listener then
          self.connectedObject = nil
        end
      end
      function classObject:CallDelegate(functionName, ...)
        if self.connectedObject then
          local f = self.connectedObject[functionName]
          if f then
            f(self.connectedObject, ...)
          end
        end
      end
    end
  }
end)()
;(function()
  LUABroadcaster = {
    hashBroadcaster = {},
    addListener = function(self, broadcaster, event, func, functable)
      broadcaster = tostring(broadcaster)
      if not self.hashBroadcaster[broadcaster] then
        self.hashBroadcaster[broadcaster] = {}
      end
      if not self.hashBroadcaster[broadcaster][event] then
        self.hashBroadcaster[broadcaster][event] = {}
      end
      self.hashBroadcaster[broadcaster][event][#self.hashBroadcaster[broadcaster][event] + 1] = {func, functable}
    end,
    removeListener = function(self, broadcaster, event, func)
      broadcaster = tostring(broadcaster)
      if not self.hashBroadcaster[broadcaster] or not self.hashBroadcaster[broadcaster][event] then
        return
      end
      local i
      for k, v in pairs(self.hashBroadcaster[broadcaster][event]) do
        local callback = v[1]
        if callback == func then
          self.hashBroadcaster[broadcaster][event][k] = nil
        end
      end
    end,
    dispatchEvent = function(self, broadcaster, event, ...)
      broadcaster = tostring(broadcaster)
      if not self.hashBroadcaster[broadcaster] or not self.hashBroadcaster[broadcaster][event] then
        return
      end
      local i
      for k, v in pairs(self.hashBroadcaster[broadcaster][event]) do
        local obj = v
        local callback = obj[1]
        local functable = obj[2]
        if callback then
          if functable then
            callback(functable, unpack(arg))
          else
            callback(unpack(arg))
          end
        end
      end
    end
  }
end)()
