;(function()
  BindCommandToLua("var", "ShowClientVar")
  BindCommandToLua("listvars", "ListClientVars")
  function ShowClientVar(v)
    local notfound
    notfound = true
    for k in pairs(Client) do
      if k == v then
        notfound = false
        local t
        t = type(Client[k])
        if t == "number" or t == "boolean" or t == "nil" then
          Logger:print("clientvars.lua", string.format("%s=%s", tostring(k), tostring(Client[k])))
        elseif t == "string" then
          Logger:print("clientvars.lua", string.format("%s=\"%s\"", tostring(k), tostring(Client[k])))
        elseif t == "table" then
          Logger:print("clientvars.lua", string.format("%s={table}", tostring(k)))
        elseif t == "function" then
          Logger:print("clientvars.lua", string.format("%s={function}", tostring(k)))
        end
      end
    end
    if notfound then
      Logger:print("clientvars.lua", [[
Not defined!
Try /listvars]])
    end
  end
  function ListClientVars()
    Logger:print("clientvars.lua", "Listing vars for Client.*")
    for k in pairs(Client) do
      local t = type(Client[k])
      if t == "number" or t == "boolean" or t == "nil" then
        Logger:print("clientvars.lua", string.format("%s=%s", tostring(k), tostring(Client[k])))
      elseif t == "string" then
        Logger:print("clientvars.lua", string.format("%s=\"%s\"", tostring(k), tostring(Client[k])))
      elseif t == "table" then
        Logger:print("clientvars.lua", string.format("%s={table}", tostring(k)))
      elseif t == "function" then
        Logger:print("clientvars.lua", string.format("%s={function}", tostring(k)))
      end
    end
  end
end)()
