  }
  DataSourceMethods = {
    ParseDs = function(self, ds, rowDelim, colDelim, propDelim)
      if rowDelim == nil then
        rowDelim = "~~"
      end
      if colDelim == nil then
        colDelim = "|"
      end
      if propDelim == nil then
        propDelim = "::"
      end
      local ds = DsTable.Find(ds)
      local res_final = {}
      local res = {}
      if ds then
        local rows = ds:GetRowCount()
        local columns = ds:GetColumnCount()
        local column = 0
        row = 0
        while rows > row do
          column = 0
          res = {}
          res_final[row] = self:SerializeRow(ds, row, propDelim, colDelim)
          row = row + 1
        end
      else
        return false
      end
      local count = 0
      for k, v in pairs(res_final) do
        count = count + 1
      end
      if count == 1 then
        return res_final[0]
      end
      return strjoin(rowDelim, res_final)
    end,
    SerializeRow = function(self, ds, row, propDelim, colDelim)
      if not ds then
        return nil
      end
      local cols = ds:GetColumnCount()
      local col = 0
      local res = {}
      while cols > col do
        res[col] = ds:GetColumnName(col) .. propDelim .. ds:GetData(row, col)
        col = col + 1
      end
      return strjoin(colDelim, res)
    end,
    GetDsVal = function(self, ds, row, colName)
      ds = DsTable.Find(ds)
      if ds then
        local numCols = ds:GetColumnCount()
        local numRows = ds:GetRowCount()
        local col = 0
        while numCols > col do
          if ds:GetColumnName(col) == colName then
            return ds:GetData(row, col)
          end
          col = col + 1
        end
      end
      return nil
    end,
    GetRowWhere = function(self, ds, key, value)
      if ds then
        local rows = ds:GetRowCount()
        local cols = ds:GetColumnCount()
        local row = 0
        local col = 0
        while rows > row do
          col = 0
          while cols > col do
            if ds:GetColumnName(col) == key and ds:GetData(row, col) == value then
              return {
                row = row,
                col = col,
                serialized = self:SerializeRow(ds, row, "%%", "|")
              }
            end
            col = col + 1
          end
          row = row + 1
        end
      end
      return nil
    end
  }
