  function strjoin(delimiter, list)
    local len = 0
    for k, v in pairs(list) do
      len = len + 1
    end
    if len == 0 then
      return ""
    end
    local string = list[0]
    for i = 1, len - 1 do
      string = string .. delimiter .. list[i]
    end
    return string
  end
