      ds = DsTable.Find("BaseClient.MiniGame.ActionBar")
      if ds then
        ds:DisableScriptEvents()
      end
    end,
    GetCurrentlyEquippedWeapon = function(self, sendToSwf)
      local iconId = 3938
      local tint = -1
      local ds = DsTable.Find("BaseClient.Inventory.CurrentlyEquipped")
      if ds then
        local numRows = tonumber(ds:GetRowCount())
        if numRows >= 7 then
          iconId = tonumber(ds:GetData(7, 1))
          tint = tonumber(ds:GetData(7, 6))
        end
      end
      if sendToSwf == true then
      end
      return iconId, tint
    end,
    ActionBarUpdated = function(self)
    end,
    PopulateActionBar = function(self, minigameActionBar)
      self:resetButtons()
      local ds
      self.isUsingFishingAbilities = false
      self.isUsingMinigameAbilities = minigameActionBar
      if not minigameActionBar then
        ds = DsTable.Find("BaseClient.ActionBar")
      else
        ds = DsTable.Find("BaseClient.MiniGame.ActionBar")
      end
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          if i > 3 then
            break
          end
          if not minigameActionBar then
            local index = i + 1
            local assigned = tonumber(ds:GetData(i, 0))
            local iconId = tonumber(ds:GetData(i, 1))
            local name = tostring(ds:GetData(i, 2))
            local desc = tostring(ds:GetData(i, 3))
            local quantity = tonumber(ds:GetData(i, 4))
            local manaCost = tonumber(ds:GetData(i, 5))
            local tintValue = tonumber(ds:GetData(i, 6))
            if assigned == 1 then
              self:setButtonData(i, iconId, 4, name, false, true, -1)
            end
          else
            local index = i
            local isEmpty = tonumber(ds:GetData(i, 0))
            local iconId = tonumber(ds:GetData(i, 1))
            local name = tostring(ds:GetData(i, 2))
            local enabled = tostring(ds:GetData(i, 3))
            if tonumber(isEmpty) == 0 and tonumber(enabled) == 1 then
              self:setButtonData(index, iconId, 4, name, true, true, -1)
            end
          end
        end
      end
    end,
    setButtonData = function(self, id, iconId, bgImageSetId, name, minigameAbility, dontShow, tint)
      if id and id == 0 then
        self:resetButtons()
      end
      if id ~= nil and id < 5 then
        if id ~= GraphicActionBar.abilityNum then
          return
        end
        if self.isUsingMinigameAbilities == true and minigameAbility ~= true then
          return
        end
        tint = tint or -1
        if tonumber(iconId) == 3938 then
          iconId, tint = self:GetCurrentlyEquippedWeapon()
        end
        local ps3movie = ActionDock_PS3:GetSwf()
        if ps3movie ~= nil then
          if bgImageSetId == 0 and self.lastBGs[id] then
            bgImageSetId = tonumber(self.lastBGs[id])
          else
            self.lastBGs[id] = tonumber(bgImageSetId)
          end
          if bgImageSetId == 0 and self.lastBGs[id - 1] then
            bgImageSetId = tonumber(self.lastBGs[id - 1])
            self.lastBGs[id] = tonumber(bgImageSetId)
          end
          if bgImageSetId == 0 then
            bgImageSetId = 4
          end
          ps3movie:Invoke("setAbilityButtonData", id, iconId, tint, bgImageSetId, name)
        end
        self.abilityNum = self.abilityNum + 1
      end
