;(function()
  radialMenu = {
    isDebug = false,
    isShown = false,
    offsetX = -500,
    offsetY = -200,
    hasContext = 0,
    WindowName = "Main.wndRadialMenu",
    MovieName = "Main.wndRadialMenu.swfRadial",
    onInit = function(self)
    end,
    Pop = function(self)
      if self.hasContext > 0 then
        Context:Pop()
        self.hasContext = 0
      end
      radialMenu:hide()
    end,
    setButtonCount = function(self, buttonCount)
      local theCtrl = GfxCtrl.Find(self.MovieName)
      if theCtrl ~= nil then
        theCtrl:Invoke("setButtonCount", tonumber(buttonCount))
      end
    end,
    setButton = function(self, buttonIndex, iconId, buttonText, buttonEventId)
      local theCtrl = GfxCtrl.Find(self.MovieName)
      if theCtrl ~= nil then
        theCtrl:Invoke("setButton", tonumber(buttonIndex), tonumber(iconId), buttonText, tonumber(buttonEventId))
      end
    end,
    onDeactivate = function(self)
      local theCtrl = GfxCtrl.Find("Main.wndRadialMenu.swfRadial")
      if self.isShown and theCtrl ~= nil then
        theCtrl:Invoke("FR_startCloseEffect")
      end
    end,
    setTutorialMode = function(self, mode)
      local theCtrl = GfxCtrl.Find("Main.wndRadialMenu.swfRadial")
      theCtrl:Invoke("SetTutorialMode", mode)
    end,
    onPopup = function(self, x, y, name, guid)
      if Tutorial.radialMenuTutorialShowing == true then
        Tutorial:ClearAllTutorialElements()
        Tutorial.radialMenuTutorialShowing = nil
      end
      if self.hasContext > 0 then
        return
      end
      if not HUD.mainShown then
        return
      end
      Main_wndRadialMenu_swfRadial_OnUserEvent = radialMenu.OnUserEvent
      Main_wndRadialMenu_OnActivate = radialMenu.OnActivate
      Main_wndRadialMenu_swfRadial_OnKeyDown = radialMenu.OnKeyDown
      local theWindow = Window.Find(self.WindowName)
      if theWindow ~= nil then
        if not self.tutorialMode then
          Context:Push("RadialMenu", function()
            radialMenu:Pop()
          end)
          self.hasContext = self.hasContext + 1
        end
        if tonumber(x) <= 50 then
          local w, h = theWindow:GetSize()
          local sw, sh = Window.GetCanvasSize()
          x = sw / 2
          y = sh - 310
        end
        theWindow:Show()
        theWindow:SetFocus()
        theWindow:MoveToFront()
        theWindow:SetPosition(x + self.offsetX, y + self.offsetY)
        self.isShown = true
        local theCtrl = GfxCtrl.Find(self.MovieName)
        if theCtrl ~= nil then
          theCtrl:Invoke("FR_startOpenEffect", 350)
        end
        InteractionPrompt:Disable()
      end
    end,
    hide = function(self)
      InteractionPrompt:Enable()
      self.isShown = false
      local w1 = Window.Find("Main.wndRadialMenu")
      w1:Hide()
      w1:SetPosition(-500, -500)
      local theCtrl = GfxCtrl.Find(self.MovieName)
      if theCtrl ~= nil then
        theCtrl:Unload()
      end
      Window.SetFocus()
    end,
    toggleDebug = function(self)
      self.isDebug = not self.isDebug
    end,
    showDebugText = function(self, t)
      if self.isDebug then
      end
    end,
    OnUserEvent = function(a, b)
      if radialMenu.tutorialMode then
        return
      end
      if a == "radialMenuOpenStarted" then
        radialMenu.isOpening = true
      elseif a == "radialMenuOpenFinished" then
        radialMenu.isOpening = false
      elseif a == "radialMenuCloseFinished" then
        radialMenu:Pop()
      elseif a == "radialMenuClick" and b ~= nil then
        if radialMenu.isDebug then
          radialMenu:showDebugText("TestRME(action#" .. b .. ")")
        end
        Ui.RadialMenuClicked(tonumber(b))
        radialMenu:Pop()
      end
      if a == "PlaySound" then
        HUD:PlaySound(b)
      end
      if a == "ASPrint" then
      end
    end,
    OnActivate = function(a, b, c, d, e, f)
      if radialMenu.tutorialMode then
        return
      end
      if tonumber(a) == 0 then
        radialMenu:onDeactivate()
      end
    end,
    OnKeyDown = function(a, b)
      if radialMenu.tutorialMode then
        return
      end
      if Client.ReverseKeyName(a) == "Escape" then
        radialMenu:onDeactivate()
      end
    end
  }
  Client.HandlerRadialMenu = "radialMenu"
end)()
;(function()
  ChatColor = {
    mapChatColorsToStyles = {
      White = "Bubble",
      Black = "Black",
      Pink = "Pink",
      Green = "Green",
      Blue = "Blue",
      Red = "Red",
      Purple = "Purple",
      Yellow = "Yellow"
    },
    mapChatColorsToIndex = {
      White = 1,
      Black = 2,
      Pink = 3,
      Green = 4,
      Blue = 5,
      Red = 6,
      Purple = 7,
      Yellow = 8
    },
    mapIndexToColors = {
      [1] = "White",
      [2] = "Black",
      [3] = "Pink",
      [4] = "Green",
      [5] = "Blue",
      [6] = "Red",
      [7] = "Purple",
      [8] = "Yellow"
    },
    mChatColor = "White",
    GetStyle = function(self)
      return self.mapChatColorsToStyles[self.mChatColor]
    end,
    GetColor = function(self)
      return self.mChatColor
    end,
    GetIndex = function(self)
      return self.mapChatColorsToIndex[self.mChatColor]
    end,
    GetColorForIndex = function(self, index)
      return self.mapIndexToColors[index]
    end,
    GetStyleForIndex = function(self, index)
      local color = self.mapIndexToColors[index]
      return self.mapChatColorsToStyles[color]
    end,
    set = function(self, color)
      if color ~= nil and self.mapChatColorsToStyles[color] ~= nil then
        self.mChatColor = color
        Logger:print("chatcolor.lua", "Changed your chat bubbles to " .. color .. ".")
      else
        if color ~= nil then
          Logger:print("chatcolor.lua", "The color \"" .. color .. "\" is not supported.  Try one of the following:")
        else
          Logger:print("chatcolor.lua", "Try /chatcolor with one of the following:")
        end
        for k, v in pairs(self.mapChatColorsToStyles) do
          Logger:print("chatcolor.lua", k)
        end
      end
    end
  }
end)()
;(function()
  MiniMap = {
    windowName = Ui.GetName("Main.wndMiniMap"),
    miniMap = Ui.GetName("Main.wndMiniMap.swfMiniMap"),
    enabled = true,
    shown = false,
    pathEnabled = 1,
    atlasButtonShown = true,
    GetWindowStr = function(self)
      if HUD.isInStartingZone then
        return "Main.wndMiniMapNot"
      else
        return "Main.wndMiniMap"
      end
    end,
    GetWindow = function(self)
      return Window.Find(Ui.GetName(self:GetWindowStr()))
    end,
    GetSwf = function(self)
    end,
    Show = function(self)
      if MiniMap.enabled == false then
        return
      end
      self:Configure()
      local w1 = self:GetWindow()
      if w1 ~= nil then
        w1:Show()
        WindowTweener:Create(self:GetWindowStr(), "Y", nil, 56, 0.3)
      end
      self.shown = true
      self:OnResize()
      NonModalContext:AddContext(self)
      DsTable.Find("BaseClient.Breadcrumb"):EnableScriptEvents()
      DsTable.Find("BaseClient.ObjectiveTarget"):EnableScriptEvents()
      HUD:ShowHudButtons(true)
    end,
    ToggleEnabled = function(self)
      if self.enabled then
        self.enabled = false
        if self.shown then
          self:Hide()
          self:Show()
        end
      else
        self.enabled = true
        if self.shown then
          self:Show()
        end
      end
    end,
    Hide = function(self)
      local w1 = self:GetWindow()
      if w1 ~= nil then
        WindowTweener:Create(self:GetWindowStr(), "Y", nil, -400, 0.3)
      end
      self.shown = false
      HUD:ShowHudButtons(false)
    end,
    OnResize = function(self)
      local w1 = self:GetWindow()
      local x, y = w1:GetPosition()
      local w, h = w1:GetSize()
      local sw, sh = Window.GetCanvasSize()
      if sw < 1200 then
        w1:SetPosition(sw - w - 76, y)
      else
        w1:SetPosition(sw - w - 96, y)
      end
      if self.shown == false then
        self:Hide()
      end
    end,
    Init = function(self)
    end,
    PlaceIndicator = function(self, id, type, sName, locX, locY, sSubtext, sIcon, guid, combatNpc)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("placeMapIndicator", id, type, sName, locY, -locX, sSubtext, sIcon, guid, combatNpc)
    end,
    UpdateIndicatorLocation = function(self, id, locX, locY, speed)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("updateMapIndicatorPosition", id, locY, -locX, speed / 1000)
    end,
    KillIndicator = function(self, id)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("killIndicator", id)
    end,
    SelectIndicator = function(self, id, locX, locZ, guid)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("SelectIndicator", id, locX, locZ, guid)
      HUD.selectedQuestIndicator = guid
    end,
    ClearSelectedIndicator = function(self)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("ClearSelectedIndicator")
      HUD.selectedQuestIndicator = 0
    end,
    SetObjectiveTarget = function(self)
      local mov = GfxCtrl.Find(self.miniMap)
      local ds = DsTable.Find("BaseClient.ObjectiveTarget")
      if tonumber(ds:GetData(0, 0)) == 1 then
        QuestHelper:ShowTakeMeThere(1)
        local name = ds:GetData(0, 2)
        if name == nil or name == "" then
          name = Ui.GetString(139655)
        end
        mov:Invoke("RemoveObjectiveTarget")
        mov:Invoke("SetObjectiveTarget", ds:GetData(0, 1), name, tonumber(ds:GetData(0, 3)), tonumber(ds:GetData(0, 4)), tonumber(ds:GetData(0, 6)))
      else
        QuestHelper:ShowTakeMeThere(0)
        mov:Invoke("RemoveObjectiveTarget")
      end
    end,
    SetSunlightColor = function(self, r, g, b)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("setShadeColor", r, g, b)
    end,
    AddImage = function(self, name, iconId, xloc, zloc, w, h)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("AddImage", name, iconId, xloc, zloc, w, h)
    end,
    RemoveImage = function(self, name)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("RemoveImage", name)
    end,
    PingReceived = function(self, x, y, tint)
      local f = GfxCtrl.Find(self.miniMap)
      f:Invoke("placePing", x, y, tint)
    end,
    Reset = function(self)
      local f = GfxCtrl.Find(self.miniMap)
      f:SoftInvoke("ClearMap")
      self:Configure()
    end,
    Configure = function(self)
      local f = GfxCtrl.Find(self.miniMap)
      local showShops = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "ShowShops", 1))
      local showQuests = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "ShowQuests", 1))
      local showCombat = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "ShowCombat", 1))
      local showGroup = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "ShowGroup", 1))
      local showFriends = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "ShowFriends", 1))
      local showMinigames = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "ShowMinigames", 1))
      local showTrainers = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "ShowTrainers", 1))
      local showGuildMembers = tonumber(Ui.GetUserOptionsValue("MinimapOptions", "showGuildMembers", 1))
      f:Invoke("defineMapIndicatorOption", 1, showShops)
      f:Invoke("defineMapIndicatorOption", 2, showQuests)
      f:Invoke("defineMapIndicatorOption", 3, showCombat)
      f:Invoke("defineMapIndicatorOption", 4, showGroup)
      f:Invoke("defineMapIndicatorOption", 5, showFriends)
      f:Invoke("defineMapIndicatorOption", 6, showMinigames)
      f:Invoke("defineMapIndicatorOption", 7, showTrainers)
      if SocialHandler:SetGuild() == 1 then
        f:Invoke("defineMapIndicatorOption", 8, showGuildMembers)
      end
      f:Invoke("SetRestoreButtonState", Ui.GetWindowed())
      f:Invoke("configComplete")
      local zoom = Ui.GetUserOptionsValue("MinimapOptions", "Zoom", 75)
      f:Invoke("setCurrentZoom", tonumber(zoom))
      local indicatorsEnabled = Ui.GetUserOptionsValue("MinimapOptions", "Indicators", "true")
      if indicatorsEnabled == "false" then
        HUD:DisableIndicators()
      else
        HUD:EnableIndicators()
      end
      if HUD.inMiniGame or Ui.IsInHub() or Ui.IsInSnowballFight() or Tutorial.inTutorial or PetTutorial.enabled or Housing.isInInstance or MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.FISHING_TYPE or HUD.isInStartingZone then
        self:EnableButtons(0)
      else
        self:EnableButtons(1)
      end
    end,
    ClearPath = function(self)
      local mov = GfxCtrl.Find(self.miniMap)
      mov:Invoke("clearPath")
    end,
    EnableButtons = function(self, is)
      HotKeyEvents.enableAtlas = is == 1
      local mov = GfxCtrl.Find(self.miniMap)
      mov:Invoke("EnableButtons", is)
    end,
    UpdatePath = function(self)
      if Ui.GetUserOptionsValue("MinimapOptions", "PathEnabled", "true") == "true" then
        self:EnablePath()
      else
        self:DisablePath()
      end
    end,
    DrawPath = function(self)
      self:ClearPath()
      local mov = GfxCtrl.Find(self.miniMap)
      local ds = DsTable.Find("BaseClient.Breadcrumb")
      local fx, fy, cx, cy, x, y
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 20 then
          numRows = 20
        end
        for i = 0, numRows - 1 do
          x = tonumber(ds:GetData(i, 2))
          y = tonumber(ds:GetData(i, 0))
          if i == 0 or i == numRows - 1 then
            fx = x
            fy = y
            cx = x
            cy = y
            mov:Invoke("addPathCoordinate", x, y)
          elseif math.abs(cx - x) + math.abs(cy - y) > 8 then
            mov:Invoke("addPathCoordinate", x, y)
            cx = x
            cy = y
            if math.abs(x - fx) + math.abs(y - fy) > 175 then
              break
            end
          end
        end
      end
      mov:Invoke("drawPath")
    end,
    DisablePath = function(self)
      Ui.EnableBreadcrumbs(0)
      self:ClearPath()
    end,
    EnablePath = function(self)
      Ui.EnableBreadcrumbs(1)
      self:DrawPath()
    end
  }
  function BaseClient_Breadcrumb_OnDataUpdate()
    MiniMap:UpdatePath()
    Atlas:CreateQuestPath()
  end
  MoveMiniMap = {
    miniMap = Ui.GetName("Main.wndMiniMap.swfMiniMap"),
    elapsedTime = 0,
    uf = 2000,
    lx = -1000,
    lz = -1000,
    lh = -1000,
    lpov = -1000,
    lbu = true,
    Update = function(self)
      if MiniMap.enabled == false then
        return
      end
      local x, y, z = Ui.GetPlayerLoc()
      local dx = self.lx - x
      local dz = self.lz - z
      local umm = false
      if dx * dx + dz * dz > 25 then
        umm = true
        self.lbu = false
        self.elapsedTime = 0
      else
        self.elapsedTime = self.elapsedTime + Ui.GetFrameTime()
        if self.elapsedTime >= self.uf then
          if self.lbu then
            umm = true
            self.lbu = false
          end
          self.elapsedTime = 0
        end
      end
      if umm and Ui.UpdateMiniMap(x - 150, z - 274, x + 260, z + 150) ~= 1 then
        self.lbu = true
      end
      local f = GfxCtrl.Find(self.miniMap)
      h = 90 - Ui.GetPlayerHeading() * 180 / 3.1415926
      local pov = 180 - Ui.GetCameraHeading() * 180 / 3.1415926
      if self.lx ~= x or self.lz ~= z then
        self.lbu = true
        f:Invoke("scrollMap", z, -x)
        self.lx = x
        self.lz = z
      end
      if self.lh ~= h then
        self.lh = h
        f:Invoke("setPlayerHeading", h)
      end
      if self.lpov ~= pov then
        self.lpov = pov
        f:Invoke("setPOV", pov)
      end
    end
  }
  UpdateList.MoveMiniMap = MoveMiniMap
  function Main_wndMiniMap_swfMiniMap_OnUserEvent(a, b, c)
    if a == "config" then
      MiniMap:Configure()
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "openAtlas" then
      if not HUD.miniGameHUDVisible then
        Atlas:Show()
      end
    elseif a == "showWelcomeScreen" then
      WelcomeHandler:Show()
    elseif a == "AS_Print" then
      print(">[" .. a .. "]-" .. b)
    elseif a == "ASPrint" then
      print("ASPrint[" .. b .. "]")
    elseif a == "setZoom" then
      Ui.SetUserOptionsValue("MinimapOptions", "Zoom", tonumber(b))
    elseif a == "sendMapPing" then
      Ui.SendMapPing(tonumber(b), tonumber(c))
    elseif a == "exitButtonClicked" then
      Options:Show()
    elseif a == "helpButtonClicked" then
      WebBrowserHandler:Show()
    elseif a == "settingsButtonClicked" then
      if Options.mIsUp ~= true then
        Options:ShowPanel()
      else
        Options:HidePanel()
      end
    elseif a == "maximizeButtonClicked" then
      if Ui.GetWindowed() == 1 then
        Ui.SetWindowed(0)
        Ui.SaveUserOptions()
      end
    elseif a == "restoreButtonClicked" and Ui.GetWindowed() == 0 then
      Ui.SetWindowed(1)
      Ui.SaveUserOptions()
    end
  end
  function Main_wndMiniMap_swfMiniMap_OnFocus(a, b)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function BaseClient_ObjectiveTarget_OnDataUpdate()
    QuestHelper:PopulateAtlasActiveQuest()
    MiniMap:SetObjectiveTarget()
  end
  function Main_wndMiniMapNot_swfMiniMapNot_OnFocus(a, b)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndMiniMapNot_swfMiniMapNot_OnUserEvent(a, b, c)
    if a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "ASPrint" then
      print("ASPrint[" .. b .. "]")
    elseif a == "exitButtonClicked" then
      Options:Show()
    elseif a == "helpButtonClicked" then
      WebBrowserHandler:Show()
    elseif a == "settingsButtonClicked" then
      if Options.mIsUp ~= true then
        Options:ShowPanel()
      else
        Options:HidePanel()
      end
    elseif a == "maximizeButtonClicked" then
      if Ui.GetWindowed() == 1 then
        Ui.SetWindowed(0)
        Ui.SaveUserOptions()
      end
    elseif a == "restoreButtonClicked" and Ui.GetWindowed() == 0 then
      Ui.SetWindowed(1)
      Ui.SaveUserOptions()
    end
  end
end)()
