  Target = {
    isEnabled = true,
    lastTarget = " ",
    isShown = false,
    Show = function(self)
      if self.isEnabled == false then
        return
      end
      if self.isShown then
        return
      end
      self.isShown = true
      if Tutorial.inTutorial or PetTutorial.enabled then
        return
      end
      print("target show 1")
      self:OnResize()
      self:RegisterDS()
      NonModalContext:AddContext(self)
      self:setHealth(0, 0)
      self:setPower(0, 0)
      self:onDS(true)
    end,
    Hide = function(self)
      if not self.isShown then
        return
      end
      self.isShown = false
      NonModalContext:RemoveContext(self)
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create("Main.wndTarget", "Y", nil, -50, 0.3, function()
        Window.Find("Main.wndTarget"):Hide()
        GfxCtrl:Find("Main.wndTarget.swfTarget"):Unload()
      end)
    end,
    OnResize = function(self)
      if self.isEnabled == false then
        return
      end
      local sw, sh = Window.GetCanvasSize()
      local window = Window.Find(Ui.GetName("Main.wndTarget"))
      local w, h = window:GetSize()
      window:Show()
      window:SetPosition(sw / 2 - w / 2, -50)
      WindowTweener:Create("Main.wndTarget", "Y", nil, 50, 0.3)
    end,
    RegisterDS = function(self)
      local ds = DsTable.Find("BaseClient.Bosses")
      ds:EnableScriptEvents()
    end,
    UnRegisterDS = function(self)
      local ds = DsTable.Find("BaseClient.Bosses")
      ds:DisableScriptEvents()
    end,
    setTarget = function(self, target)
      print("target set " .. tostring(target))
      if tostring(target) == "-1" then
        return
      end
      self.lastTarget = target
      if self.isEnabled == false then
        return
      end
      swf = GfxCtrl.Find("Main.wndTarget.swfTarget")
      swf:Invoke("setTarget", target)
    end,
    setHealth = function(self, x, y)
      if self.isEnabled == false then
        return
      end
      if y == 0 then
        y = 100
      end
      swf = GfxCtrl.Find("Main.wndTarget.swfTarget")
      swf:Invoke("setHealth", x, y)
    end,
    setPower = function(self, x, y)
      if self.isEnabled == false then
        return
      end
      swf = GfxCtrl.Find("Main.wndTarget.swfTarget")
      if y == 0 and x == 100 then
        swf:Invoke("setPower", 0, 0)
      else
        if y == 0 then
          y = 100
        end
        swf:Invoke("setPower", x, y)
      end
    end,
    setPortrait = function(self, guid)
      if self.isEnabled == false then
        return
      end
      if guid and tonumber(guid) > 0 then
        swf = GfxCtrl.Find("Main.wndTarget.swfTarget")
        swf:Invoke("setPortrait", guid)
      end
    end,
    onDS = function(self, dontCallShow)
      local ds = DsTable.Find("BaseClient.Bosses")
      local rows = 0
      if ds then
        rows = ds:GetRowCount()
        if rows and rows > 0 then
          if dontCallShow then
          else
            self:Show(true)
          end
          self:setTarget(ds:GetData(0, 1))
          self:setHealth(tonumber(ds:GetData(0, 2)), tonumber(ds:GetData(0, 3)))
          self:setPower(tonumber(ds:GetData(0, 4)), tonumber(ds:GetData(0, 5)))
          self:setPortrait(ds:GetData(0, 0))
        end
      end
      if rows == 0 then
        self:Hide()
      end
    end
  }
