  ObjectiveWindow = {
    windowName = Ui.GetName("Main.wndObjectives"),
    movieName = Ui.GetName("Main.wndObjectives.swfObjectives"),
    isShown = false,
    isInitialized = false,
    disabled = false,
    objectiveCount = 0,
    shouldShow = false,
    showInHub = false,
    Check = function(self)
      if self.isShown == true then
        return false
      end
      if GameTutorial.windowVisible == true then
        return false
      end
      if self.disabled == true then
        return false
      end
      if Tutorial.inTutorial or PetTutorial.enabled then
        return false
      end
      if MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.PIRATES_TYPE then
        return false
      end
      if MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.SOCCER_TYPE and ObjectiveWindow.objectiveCount <= 1 then
        return false
      end
      return true
    end,
    RegisterDS = function(self)
      local ds = DsTable.Find("BaseClient.ObjectiveHelper")
      ds:EnableScriptEvents()
      NonModalContext:AddContext(self)
    end,
    UnRegisterDS = function(self)
      local ds = DsTable.Find("BaseClient.ObjectiveHelper")
      ds:DisableScriptEvents()
      NonModalContext:RemoveContext(self)
    end,
    SetShowInHub = function(self, flag)
      if flag == nil then
        flag = true
      end
      self.showInHub = flag
    end,
    Show = function(self)
      Logger:print("minigame.lua", "OBJECTIVE WINDOW SHOW " .. tostring(self.isShown))
      if self:Check() == false then
        return
      end
      self.shouldShow = false
      local w1 = Window.Find(self.windowName)
      if w1 ~= nil then
        w1:Show()
        self:OnResize()
        self:RegisterDS()
        self:ObjectiveListPopulate()
      end
    end,
    Hide = function(self)
      if self.isShown == false then
        return
      end
      local w1 = Window.Find(self.windowName)
      if w1 ~= nil then
        local sw, sh = Window.GetCanvasSize()
        WindowTweener:Create("Main.wndObjectives", "X", nil, sw + 300, 0.3, function()
          Window.Find(self.windowName):Hide()
        end)
        self.isShown = false
        self:UnRegisterDS()
      end
      local s1 = GfxCtrl.Find(self.movieName)
      if s1 ~= nil then
        s1:Unload()
      end
    end,
    AddOrUpdateObjective = function(self, row)
      local theObjectives = GfxCtrl.Find(self.movieName)
      local ds = DsTable.Find("BaseClient.ObjectiveHelper")
      if ds then
        local guid = tostring(ds:GetData(row, 0))
        local desc = tostring(ds:GetData(row, 1))
        local membersOnly = tonumber(ds:GetData(row, 5))
        local iconState = tonumber(ds:GetData(row, 4))
        self.objectiveCount = self.objectiveCount + 1
        if self.shouldShow == true then
          self:Show()
        end
        theObjectives:Invoke("addObjective", row, guid, tostring(iconState), desc, tostring(membersOnly))
        if MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.SOCCER_TYPE then
          if 1 >= ObjectiveWindow.objectiveCount then
            self:Hide()
          end
        elseif self.isShown == false then
          self:Show()
        end
      end
    end,
    ObjectiveListPopulate = function(self)
      local theObjectives = GfxCtrl.Find(self.movieName)
      theObjectives:Invoke("setMemberStatus", tostring(Ui.IsMember()))
      local ds = DsTable.Find("BaseClient.ObjectiveHelper")
      if ds then
        local oData = ""
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        if tonumber(numRows) <= 0 then
          self:Hide()
          return
        end
        if self.isShown == false then
          self:Show()
        end
        for i = 0, numRows - 1 do
          self:AddOrUpdateObjective(i)
        end
        if MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.SOCCER_TYPE and 1 >= ObjectiveWindow.objectiveCount then
          self:Hide()
        end
      end
    end,
    SelectTask = function(self, id)
      if id ~= nil then
        local theTasks = GfxCtrl.Find(self.movieName)
        theTasks:Invoke("SelectTask", id)
      end
    end,
    Clear = function(self)
      self:Hide()
      self.isInitialized = false
      self.objectiveCount = 0
      self.shouldShow = false
    end,
    OnResize = function(self)
      Logger:print("minigame.lua", "    ObjectiveHelper:OnResize()")
      self.isShown = true
      local sw, sh = Window.GetCanvasSize()
      local w1 = Window.Find(self.windowName)
      local w, h = w1:GetSize()
      w1:SetPosition(sw + 280, 260)
      if MiniGameStatusHandler.currentMiniGameType == 6 or MiniGameStatusHandler.currentMiniGameType == 7 then
        w1:SetPosition(sw + 280, 75)
      elseif MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.TOWER_DEFENSE_TYPE then
        w1:SetPosition(sw + 280, sh / 2 - h / 2)
      elseif MiniGameStatusHandler.currentMiniGameType == 10 then
        w1:SetPosition(sw + 280, 560)
      end
      WindowTweener:Create("Main.wndObjectives", "X", nil, sw - w - 90, 0.3)
      return true
    end,
    Initialize = function(self, noshow)
      if self:Check() == false then
        return
      end
      local theObjectives = GfxCtrl.Find(self.movieName)
      theObjectives:Reset()
      self.objectiveCount = 0
      self.shouldShow = false
      MiniGameFlash:SetWindowRequired("ObjectiveWindow", 1)
      self.isInitialized = true
      theObjectives:Invoke("setMemberStatus", tostring(Ui.IsMember()))
    end
  }
  function BaseClient_ObjectiveHelper_OnDataUpdate()
    ObjectiveWindow:Clear()
  end
  function BaseClient_ObjectiveHelper_OnDataChanged(row, col, newData)
    ObjectiveWindow:AddOrUpdateObjective(row)
  end
