  GameTutorial = {
    windowName = Ui.GetName("Main.wndMiniGameTutorial"),
    movieName = Ui.GetName("Main.wndMiniGameTutorial.swf"),
    windowVisible = false,
    mTutorialId = 0,
    mShowAgain = 1,
    mDontHide = 0,
    Show = function(self)
      if self.windowVisible == false then
        self.mDontHide = 1
        HUD:hideMinigame(true)
        self.mDontHide = 0
        local w1 = Window.Find(self.windowName)
        if w1 ~= nil then
          w1:Show()
        end
        GameTutorial:Center()
        Context:Push("GameTutorial", function()
          GameTutorial:Hide()
        end)
        self.windowVisible = true
        self.mShowAgain = 1
      end
    end,
    Hide = function(self, quitGameAfter)
      if self.mDontHide == 1 then
        return
      end
      if self.windowVisible then
        Context:Pop()
