    Hide2 = function(self, quitGameAfter)
      GameTutorial:Done()
      if self.windowVisible == false then
        Window.Find(GameTutorial.windowName):Hide()
        GfxCtrl.Find(GameTutorial.movieName):Unload()
      else
        GameTutorial:Center()
      end
      if quitGameAfter == true then
        MiniGameHandler:QuitGame()
      elseif HUD.mMiniGameFlash == true then
        HUD:showMinigame()
      end
    end,
    Done = function(self)
      MiniGameFlash:TutorialClosed(self.mTutorialId, self.mShowAgain)
