        PetTutorial:CheckShowEquipArrow()
      end)
    end,
    Init = function(self, tutorialId, gametxt, forceShow)
      self.mTutorialId = tutorialId
      if tutorialId == 0 then
        GameTutorial:Done()
      end
      local helpswf, iconid, titletxt, again = Ui.GameTutorialGetInfo(tutorialId)
      if gametxt ~= nil then
        titletxt = gametxt
      end
      self.mShowAgain = again
      if self.mShowAgain == 1 or forceShow == true then
        local theMovie = GfxCtrl.Find(self.movieName)
        theMovie:Invoke("Init", iconid, titletxt, helpswf, again)
        GameTutorial:Show()
      else
        GameTutorial:Done()
      end
    end,
    GotoLabel = function(self, label)
      local theMovie = GfxCtrl.Find(self.movieName)
      theMovie:Invoke("SetPageByLabel", label)
    end,
    OnUserEvent = function(self, a, b)
      if a == "Close" then
        self.mShowAgain = tonumber(b)
        Ui.GameTutorialShowAgain(self.mTutorialId, self.mShowAgain)
        GameTutorial:Hide()
      elseif tostring(a) == "PlaySound" then
        HUD:PlaySound(b)
      end
    end
  }
