        TaskWindow:CompleteTask(tonumber(id), text)
      end
      function MiniGameFlash.commands.TaskSelect(id)
      end
      function MiniGameFlash.commands.TaskUpdate(id, text)
        TaskWindow:UpdateTask(tonumber(id), text)
      end
      function MiniGameFlash.commands.ShowLevelEndScreen()
        levelEndScreenText = ""
        local ds = DsTable.Find("BaseClient.MiniGame")
        MiniGameHandler:setMiniGameInfoDataFromDs(77, ds:GetData(i, MiniGameDsColumn.Name), -1, "Level stats go here...", -1, 0, ds:GetData(i, MiniGameDsColumn.IconId), 0)
        MiniGameHandler:ShowRoundEndScreen()
      end
      function MiniGameFlash.commands.AddLevelEndScreenData(text)
        levelEndScreenText = levelEndScreenText .. text .. "\n"
        local ds = DsTable.Find("BaseClient.MiniGame")
        MiniGameHandler:setMiniGameInfoDataFromDs(77, ds:GetData(i, MiniGameDsColumn.Name), -1, levelEndScreenText, -1, 0, ds:GetData(i, MiniGameDsColumn.IconId), 0)
      end
      function MiniGameFlash.commands.HideLevelEndScreen()
        MiniGameHandler:CloseRoundEndScreen()
      end
      function MiniGameFlash.commands.DebugMsg(txt)
        Logger:print("minigameflash.lua", txt)
      end
      function MiniGameFlash.commands.Version(txt)
        print("Version: " .. txt)
      end
    end
    MiniGameFlash.commands[cmd](paramA, paramB, paramC, paramD, paramE, paramF, paramG, paramH, paramI, paramJ, paramK, paramL, paramM)
  end
  function Main_wndMiniGameFlash_swf_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndMiniGameFlash_swf_OnLeave(a, b, c)
    local myMovie = GfxCtrl.Find(MiniGameFlash.movieName)
    myMovie:Invoke("HideCursor")
    if MiniGameFlash.mHasCursor == 1 then
      Ui.ShowCursor()
    end
    MiniGameFlash.mInside = 0
  end
  function Main_wndMiniGameFlash_swf_OnEnter(a, b, c)
    local myMovie = GfxCtrl.Find(MiniGameFlash.movieName)
    myMovie:Invoke("ShowCursor")
    if MiniGameFlash.mHasCursor == 1 then
      Ui.HideCursor()
    end
    MiniGameFlash.mInside = 1
  end
end)()
;(function()
  ProfileDsColumns = {
    ID = 0,
    Name = 1,
    Description = 2,
    Type = 3,
    Rank = 4,
    AvailablePoints = 5,
    Icon = 6,
    BadgeImgSet = 7,
    ButtonImgSet = 8,
    AbilityBgImgSet = 9,
    MembersOnly = 10,
    StarsEarned = 11,
    RankPercent = 12,
    Hint = 13,
    Trial = 14,
    TrialExpired = 15
  }
  JobBrowser = {
    browserHidePos = -400,
    m_ProfileType = nil,
    isShown = false,
    Populate = function(self, swfName)
      if tonumber(self.m_ProfileType) == 0 then
        self.m_ProfileType = nil
        self:Hide()
        return
      end
      local swf = GfxCtrl.Find(Ui.GetName(swfName))
      local ds = DsTable.Find("BaseClient.Profiles.Filtered")
      swf:Invoke("SetMode", 1)
      swf:Invoke("hideCloseButton")
      local activeProfileID = Ui.GetActiveProfileId()
      if ds then
        local rows = ds:GetRowCount()
        for index = 0, rows - 1 do
          local id = ds:GetData(index, ProfileDsColumns.ID)
          local name = ds:GetData(index, ProfileDsColumns.Name)
          local desc = ds:GetData(index, ProfileDsColumns.Description)
          local typeof = ds:GetData(index, ProfileDsColumns.Type)
          local rank = ds:GetData(index, ProfileDsColumns.Rank)
          local avlP = ds:GetData(index, ProfileDsColumns.AvailablePoints)
          local icon = ds:GetData(index, ProfileDsColumns.Icon)
          local bdg = ds:GetData(index, ProfileDsColumns.BadgeImgSet)
          local btn = ds:GetData(index, ProfileDsColumns.ButtonImgSet)
          local abl = ds:GetData(index, ProfileDsColumns.AbilityBgImgSet)
          local mem = ds:GetData(index, ProfileDsColumns.MembersOnly)
          local tstars = ds:GetData(index, ProfileDsColumns.StarsEarned)
          local exp = ds:GetData(index, ProfileDsColumns.RankPercent)
          local hint = ds:GetData(index, ProfileDsColumns.Hint)
          local trial = ds:GetData(index, ProfileDsColumns.Trial)
          local trialExpired = ds:GetData(index, ProfileDsColumns.TrialExpired)
          if tonumber(rank) == 20 then
            exp = 100
          end
          local showJob = self:ValidateJobForStartScreen(tonumber(self.m_ProfileType), tonumber(typeof), tonumber(trialExpired))
          if showJob then
            swf:Invoke("AddClass", tonumber(id), tonumber(typeof), tostring(name), tostring(desc), tonumber(avlP), tonumber(rank), tonumber(exp), tonumber(icon), tonumber(bdg), tonumber(btn), tonumber(mem), tostring(hint), tonumber(trial), tonumber(trialExpired))
          end
        end
      end
      BrowserHandler:SelectItem(activeProfileID)
      LevelProgressBar:SetData(activeProfileID)
      self.m_ProfileType = nil
    end,
    GetCurrentJobIcon = function(self)
      local activeProfileID = Ui.GetActiveProfileId()
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      local rows = ds:GetRowCount()
      for index = 0, rows - 1 do
        local id = ds:GetData(index, ProfileDsColumns.ID)
        local icon = ds:GetData(index, ProfileDsColumns.Icon)
        if tonumber(id) == activeProfileID then
          return tonumber(icon)
        end
      end
      return false
    end,
    GetCurrentJobType = function(self)
      local activeProfileID = Ui.GetActiveProfileId()
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      local rows = ds:GetRowCount()
      for index = 0, rows - 1 do
        local id = ds:GetData(index, ProfileDsColumns.ID)
        local typeof = ds:GetData(index, ProfileDsColumns.Type)
        if tonumber(id) == activeProfileID then
          return tonumber(typeof)
        end
      end
      return false
    end,
    ValidateJobForStartScreen = function(self, profileType, typeof, trialExpired)
      if profileType == nil then
        return true
      end
      if trialExpired ~= 1 or Ui.IsMember() then
        return true
      end
      return false
    end,
    Show = function(self, profileType, xPosMod)
      if profileType ~= nil then
        self.m_ProfileType = profileType
      end
      self.isShown = true
      BrowserHandler.windowName = "Jobs"
      BrowserHandler:Show(JobBrowser, "", Ui.GetString("UI_Browser_JobSubtext"), Ui.GetString("UI_Browser_ClickSwitchJobs"), xPosMod)
      BrowserHandler:Connect(self)
      BrowserHandler:SetString(3, Ui.GetString("jobTrial"))
    end,
    CloseBrowser = function(self)
      BrowserHandler:CompressBrowser()
    end,
    LockBrowser = function(self)
      BrowserHandler:LockBrowser(true)
    end,
    ShowBrowser = function(self)
      BrowserHandler:ExpandBrowser()
    end,
    Hide = function(self)
      self.isShown = false
      BrowserHandler:Hide(nil, 1)
      BrowserHandler:Disconnect(self)
      GameDock_PS3:SetVisibility(1)
    end,
    BrowserOnUserEvent = function(self, a, b)
      self:CallDelegate("BrowserOnUserEvent", a, b)
      if a == "SelectJob" then
        if Ui.GetActiveProfileId() ~= tonumber(b) then
          JobScreen.SelectJob(b)
        end
        JobBrowser:Hide()
      elseif a == "CloseBrowser" then
        JobBrowser:Hide()
      elseif a == "ExpandedBrowserComplete" then
        BrowserHandler:SelectItem(Ui.GetActiveProfileId())
      elseif a == "onStartQuest" then
        self:StartJobQuest(b)
      end
    end,
    StartJobQuest = function(self, profileID)
      local ds = DsTable.Find(DataSources[DS_ACTIVITY_FINDER])
      if not ds then
        return
      end
      local rowCount = ds:GetRowCount() - 1
      for i = 0, rowCount do
        if profileID == ds:GetData(i, 0) then
          print("found " .. tostring(ds:GetData(i, 0)))
          Ui.StartBreadcrumbQuest(ds:GetData(i, 4))
          JobBrowser:CloseBrowser()
          return
        end
      end
    end,
    GetTypeById = function(self, jobId)
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      if ds then
        local rows = ds:GetRowCount()
        for index = 0, rows - 1 do
          local id = ds:GetData(index, ProfileDsColumns.ID)
          local typeof = ds:GetData(index, ProfileDsColumns.Type)
          if tonumber(jobId) == tonumber(id) then
            return typeof
          end
        end
      end
      return nil
    end,
    GetProfileData = function(profileId, column)
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      if ds then
        local rows = ds:GetRowCount()
        for index = 0, rows - 1 do
          local id = ds:GetData(index, ProfileDsColumns.ID)
          local data = ds:GetData(index, column)
          if tonumber(profileId) == tonumber(id) then
            return data
          end
        end
      end
      print("Error: Profile not found for id( " .. tostring(profileId) .. " ) or invalid column( " .. tostring(column) .. " ) requested.")
      return ""
    end
  }
  Delegate:AddSupportToClassObject(JobBrowser, "JobBrowser")
end)()
