    ShowAboutMe = function(self)
      local swf = GfxCtrl.Find(self.swfAboutMe)
      local wnd = Window.Find(self.wndAboutMe)
      local wndX, wndY = wnd:GetPosition()
      local wndWidth, wndHeight = wnd:GetSize()
      local sw, sh = Window.GetCanvasSize()
      local xloc = 54
      swf:Reset()
      if xloc < 0 then
        xloc = 0
      end
      local message = ""
      if not self.aboutmeshown then
        InGamePurchaseStoreScreen.GetWalletInfo()
        self.aboutmeshown = true
      end
      local ds = DsTable.Find("BaseClient.PlayerInfo")
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          local numCols = ds:GetColumnCount()
          message = ds:GetData(0, 0)
          for i = 1, numCols - 1 do
            message = message .. "^" .. ds:GetData(0, i)
          end
        end
      end
      swf:Invoke("setData", message)
      local statMessage = self:BuildStatString()
      swf:Invoke("setData", statMessage, 1)
      swf:Invoke("DeleteTitles")
      local dsPlayerTitles = DsTable.Find("BaseClient.PlayerTitles")
      if dsPlayerTitles then
        local rowCount = dsPlayerTitles:GetRowCount()
        for i = 0, rowCount - 1 do
          local id = tonumber(dsPlayerTitles:GetData(i, 0))
          local title = dsPlayerTitles:GetData(i, 4)
          swf:Invoke("AddPossibleTitle", id, title)
          if tonumber(dsPlayerTitles:GetData(i, 3)) == 1 then
            swf:Invoke("SetCharacterName", title)
          end
        end
        swf:Invoke("UpdateComboBox")
      end
      if sw < 1200 then
        swf:Invoke("resetLineHeight", 23)
      else
        swf:Invoke("resetLineHeight", 18.7)
      end
      wnd:SetPosition(-wndWidth, sh / 2 - wndHeight / 2 - 30)
      wnd:Show()
      wnd:MoveToFront()
      WindowTweener:Create("Main.wndAboutMe", "X", nil, xloc, 0.3)
    end,
    HideAboutMe = function(self)
      local wnd = Window.Find(self.wndAboutMe)
