      self.aboutmeshown = nil
      WindowTweener:Create("Main.wndAboutMe", "X", nil, -wndWidth, 0.3, function()
        local swf = GfxCtrl.Find(JobHandler.swfAboutMe)
        local wnd = Window.Find(JobHandler.wndAboutMe)
        swf:Unload()
        wnd:Hide()
      end)
    end,
    UpdateWalletInfo = function(self)
      if not self.screenActive then
        return
      end
      local swf = GfxCtrl.Find(JobHandler.swfAboutMe)
      local wInfo = ""
      local ds = DsTable.Find("BaseClient.PlayerInfo")
      if ds then
        wInfo = ds:GetData(0, 2)
      end
      if swf then
        swf:Invoke("setWalletData", wInfo)
      end
    end,
    BuildStatString = function(self, id)
      local statDS = DsTable.Find(DataSources[DS_STAT_DEFINITIONS])
      local ds = DsTable.Find(DataSources[DS_PLAYER_STATS])
      local statMessage = ""
      if ds and statDS then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          for i = 0, numRows - 1 do
            local iconID = 0
            local statName = ""
            local rowCount = statDS:GetRowCount()
            statID = tonumber(ds:GetData(i, 0))
            iconID = statDS:GetData(statID, 1)
            statName = statDS:GetData(statID, 2)
            statMessage = statMessage .. iconID .. "^" .. statName .. "^" .. ds:GetData(i, 1) .. ";"
          end
        end
      end
      return statMessage
    end,
