    EquipmentPaneOnUserEvent = function(self, a, b, c, d, e, f)
      local SlotToQuickChatNodeMappingTable = {
        165,
        164,
        162,
        166,
        163,
        167
      }
      if a == "requestData" then
        EquipmentHandler:RequestData(b, c)
      elseif a == "onMembersOnly" then
        JobHandler:ExitToMarketPlace()
      elseif a == "changeSelectedCategory" then
        EquipmentHandler.selectedSlot = tonumber(b)
      elseif a == "changeSelectedJob" then
        if Ui.GetActiveProfileId() ~= tonumber(b) then
          EquipmentHandler.m_selectedJob = tonumber(b)
          JobHandler.currentActiveProfileID = Ui.GetActiveProfileId()
          UpdateList.JobHandler = JobHandler
          JobScreen.SelectJob(b)
          self.isPreviewingItem = false
        end
      elseif a == "previewItem" then
        if EquipmentHandler.selectedSlotMapID < 8 and b ~= "0" then
          EquipScreen.ClearPreviewEquipItem()
          if tonumber(c) < 7 then
            Ui.ProcessQuickChatCommand(SlotToQuickChatNodeMappingTable[tonumber(c)])
          end
          print(b)
          EquipScreen.PreviewEquipItemByGuid(b)
        end
        Ui.SetDialogCameraOffset2D(390, -150)
      elseif a == "clearPreview" then
        EquipScreen.ClearPreviewEquipItem()
      elseif a == "equipItem" then
        HUD:PlaySound("Selected")
        if tonumber(c) == 0 then
          c = EquipmentHandler.selectedSlot
        end
        if EquipmentHandler.selectedSlotMapID == 17 then
          Ui.ClearItemNewFlag(b)
          Ui.AssignToItemActionBar(tonumber(c) - EquipmentHandler.selectedSlotMapID, b)
        else
          if tonumber(c) < 7 then
            Ui.ProcessQuickChatCommand(SlotToQuickChatNodeMappingTable[tonumber(c)])
          end
          Ui.ClearItemNewFlag(b)
          EquipScreen.EquipItem(b, c)
        end
        if FirstTimeEventHandler.EquipmentTut == true then
          FirstTimeEventHandler:EquipmentEquipItem()
        end
      elseif a == "changeViewMode" then
        if b == "undefined" then
          return
        end
        EquipmentHandler.currentViewMode = b
        Ui.SetUserOptionsValue("MyCharacterWindowOptions", "LastSelectedViewMode_" .. tostring(self.NavigationLabels[self.toggledMode]), b)
      elseif a == "PlaySound" then
        HUD:PlaySound(b)
      elseif a == "AS_Print" then
      else
        if a == "CloseWindowPS3" and Ui.IsSwitchingProfile() == false then
          Logger:print("jobhandler.lua", "Close Equipment Screen")
          EquipmentHandler:Hide()
          JobHandler:ModeSwitch(0)
        else
        end
      end
