    EquipmentPaneOnRequestData = function(self, offset, count)
      local dsString
      if EquipmentHandler.selectedSlot then
        if tonumber(EquipmentHandler.selectedSlot) <= #self.InventorySlotMap then
          dsString = tostring("BaseClient.Inventory.") .. tostring(EquipmentHandler.selectedSlotMap[tonumber(EquipmentHandler.selectedSlot)])
        end
        if dsString ~= nil then
          local ds = DsTable.Find(dsString)
          if ds then
            EquipmentHandler:Populate(offset, count, ds)
          end
        end
      end
    end,
    CanEquipNone = function(self, slotID)
      if tonumber(slotID) == 3 or tonumber(slotID) == 4 then
        return false
      elseif tonumber(slotID) == 7 and JobBrowser:GetCurrentJobType() == 2 then
        return false
      end
      return true
    end,
    EquipmentPaneOnPopulate = function(self, offset, count, ds)
      local slotID = EquipmentHandler.selectedSlot
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          count = tonumber(count)
          local offset = math.max(offset, 0)
          if self:CanEquipNone(slotID) then
            if offset == 0 then
              str = self.BuildNoneItem(slotID)
              count = count - 1
            else
              offset = offset - 1
            end
            numRows = numRows + 1
          end
          local countTo = math.min(offset + count, ds:GetRowCount())
          for i = offset, countTo - 1 do
            str = str .. self:BuildItemString(ds, i)
          end
        else
          str = self.BuildNoneItem(slotID)
        end
        EquipmentHandler:PopulateWindow(str, numRows)
      else
        str = self.BuildNoneItem(slotID)
        EquipmentHandler:PopulateWindow(str, 1)
      end
    end,
    EquipmentPaneOnSetCurrentEquip = function(self)
      local countTo = 0
      local str = ""
      if EquipmentHandler.selectedSlotMapID and EquipmentHandler.selectedSlotMapID < 17 then
        local ds = DsTable.Find(EquipmentHandler.selectedEquippedDatasource)
        local numRows = ds:GetRowCount()
        if ds and numRows > 0 and EquipmentHandler.selectedSlotMapID ~= nil then
          local countTo = EquipmentHandler.selectedSlotMapID + EquipmentHandler.selectedSlotMapCount - 1
          local offset = EquipmentHandler.selectedSlotMapID
          for i = offset, math.min(countTo, numRows - 1) do
            if EquipmentHandler.selectedSlotMapID ~= 8 and EquipmentHandler.selectedSlotMapID ~= 11 or (EquipmentHandler.selectedSlotMapID == 8 or EquipmentHandler.selectedSlotMapID == 11) and i ~= 11 and i ~= 10 and i ~= 9 and i ~= 16 and i ~= 14 and i ~= 15 then
              if ds:GetData(i, 0) ~= "-1" then
                str = str .. self:BuildCategoryItemString(ds, i)
              else
                str = str .. self.BuildNoneItem(i)
              end
            end
          end
          EquipmentHandler:PopulateWindowCategories(str, numRows)
        end
      elseif EquipmentHandler.selectedSlotMapID then
        local ds = DsTable.Find(EquipmentHandler.selectedEquippedDatasource)
        if ds then
          local str = ""
          local numRows = ds:GetRowCount()
          if numRows > 0 then
            for i = 0, numRows - 1 do
              if ds:GetData(i, 1) ~= "-1" then
                str = str .. self.BuildConsumableString(ds, i)
              else
                str = str .. self.BuildNoneItem(i + EquipmentHandler.selectedSlotMapID)
              end
            end
          end
          EquipmentHandler:PopulateWindowCategories(str, numRows)
        end
      end
    end,
    EquipmentPaneOnSetCurrentEquipforCarousel = function(self)
      if EquipmentHandler.selectedEquippedDatasource then
        local countTo = 0
        local str = ""
        local ds = DsTable.Find(EquipmentHandler.selectedEquippedDatasource)
        local numRows = ds:GetRowCount()
        if ds and numRows > 0 and EquipmentHandler.selectedSlotMapID ~= nil then
          local countTo = EquipmentHandler.selectedSlotMapID + EquipmentHandler.selectedSlotMapCount - 1
          local offset = EquipmentHandler.selectedSlotMapID
          for i = offset, math.min(countTo, numRows - 1) do
            if EquipmentHandler.selectedSlotMapID ~= 8 and EquipmentHandler.selectedSlotMapID ~= 11 or (EquipmentHandler.selectedSlotMapID == 8 or EquipmentHandler.selectedSlotMapID == 11) and i ~= 11 and i ~= 10 and i ~= 9 and i ~= 16 and i ~= 14 and i ~= 15 then
              if ds:GetData(i, 0) ~= "-1" then
                str = str .. self:BuildCategoryItemString(ds, i)
              else
                str = str .. self.BuildNoneItem(i)
              end
            end
          end
          EquipmentHandler:PopulateWindowCategories(str, numRows)
        end
      end
    end,
    BuildNoneItem = function(slotID)
      local item = "000000000000000^" .. EquipmentHandler.noneItemIcon .. "^" .. Ui.GetString("NoneItem") .. "^^^^-1^^" .. slotID .. ";"
      return item
    end,
    BuildCategoryItemString = function(self, ds, row)
      local item = ds:GetData(row, 0)
      for i = 1, ds:GetColumnCount() - 1 do
        if i ~= 19 then
          item = item .. "^" .. ds:GetData(row, i)
        else
          item = item .. "^^"
        end
      end
      return item .. ";"
    end,
    BuildItemString = function(self, ds, row)
      local item = ds:GetData(row, 0)
      for i = 1, ds:GetColumnCount() - 1 do
        if i ~= 19 then
          item = item .. "^" .. ds:GetData(row, i)
        elseif tonumber(ds:GetData(row, i)) ~= nil then
          if 0 < tonumber(ds:GetData(row, i)) then
            local statDS = DsTable.Find(DataSources[DS_STAT_DEFINITIONS])
            if statDS then
              local rowCount = statDS:GetRowCount()
              if rowCount > 0 then
                item = item .. "^" .. statDS:GetData(tonumber(ds:GetData(row, i)) - 1, 1)
                item = item .. "^" .. statDS:GetData(tonumber(ds:GetData(row, i)) - 1, 2)
              end
            end
          else
            item = item .. "^^"
          end
        else
          item = item .. "^^"
        end
      end
      item = item .. ";"
      return item
    end,
    BuildConsumableString = function(ds, row)
      local item = ""
      for i = 0, 3 do
        item = item .. ds:GetData(row, i) .. "^"
      end
      item = item .. "^" .. ds:GetData(row, 6)
      item = item .. "^" .. ds:GetData(row, 8)
      item = item .. "^^" .. row + EquipmentHandler.selectedSlotMapID .. "^^^^^^^;"
      return item
    end,
