;(function()
  TooltipConnect = {
    tooltipOnChangedTable = nil,
    UnregisterOnChangedFunction = function(self)
      self.tooltipOnChanged = nil
    end,
    connectedDs = nil,
    callPrevious = nil,
    connected = false,
    Connect = function(self, theDsName, onChangedObj)
      if self.connected then
        self:Disconnect()
      end
      self.tooltipOnChangedTable = onChangedObj
      ds = DsTable.Find(theDsName)
      if ds then
        ds:EnableScriptEvents()
        self.connectedDs = theDsName
        self.callPrevious = _G[theDsName .. "_OnDataUpdate"]
        _G[theDsName .. "_OnDataUpdate"] = function()
          if TooltipConnect.callPrevious then
            TooltipConnect.callPrevious()
          end
          if TooltipConnect.tooltipOnChangedTable and TooltipConnect.tooltipOnChangedTable.OnUpdate then
            TooltipConnect.tooltipOnChangedTable:OnUpdate()
          end
        end
        self.connected = true
      end
    end,
    Disconnect = function(self)
      if self.connected then
        if self.callPrevious then
          _G[self.connectedDs .. "_OnDataUpdate"] = self.callPrevious
        else
          _G[self.connectedDs .. "_OnDataUpdate"] = nil
        end
        self.connectedDs = nil
        self.connected = false
        self.tooltipOnChanged = nil
      end
    end
  }
end)()
;(function()
  EquipmentModes = {
    DEFAULT = 0,
    GARAGE = 1,
    STYLE_CARDS = 2,
    PETS = 3,
    PETS_TRICKS = 4
  }
  EquipmentHandler = {
    wndName = "Main.wndEquipmentPane",
    swfName = "Main.wndEquipmentPane.swfEquipmentPane",
    wndGroomName = "Main.wndEquipmentPaneGroom",
    swfGroomName = "Main.wndEquipmentPaneGroom.swfEquipmentPane",
    wndFeedName = "Main.wndEquipmentPaneFeed",
    swfFeedName = "Main.wndEquipmentPaneFeed.swfEquipmentPane",
    visible = false,
    selectedSlot = nil,
    selectedSlotMapID = nil,
    selectedSlotMap = nil,
    populateCurrentEquippedFunction = nil,
    currentEquipItemFunction = nil,
    align = 0,
    cameraXPos = 0,
    windowTweenSpeed = 0.3,
    leftSelected = nil,
    rightSelected = nil,
    noneItemIcon = 0,
    currentMode = EquipmentModes.DEFAULT,
    groomMode = 0,
    feedMode = 0,
    m_ProfileType = nil,
    m_isEquipScreen = false,
    m_selectedJob = nil,
    GetWindow = function()
      if EquipmentHandler.groomMode == 1 then
        return Window.Find(Ui.GetName(EquipmentHandler.wndGroomName))
      elseif EquipmentHandler.feedMode == 1 then
        return Window.Find(Ui.GetName(EquipmentHandler.wndFeedName))
      else
        return Window.Find(Ui.GetName(EquipmentHandler.wndName))
      end
    end,
    GetSwf = function()
      if EquipmentHandler.groomMode == 1 then
        return GfxCtrl.Find(Ui.GetName(EquipmentHandler.swfGroomName))
      elseif EquipmentHandler.feedMode == 1 then
        return GfxCtrl.Find(Ui.GetName(EquipmentHandler.swfFeedName))
      else
        return GfxCtrl.Find(Ui.GetName(EquipmentHandler.swfName))
      end
    end,
    Show = function(self, selectedSlotMap, selectedSlotMapID, selectedSlotMapCount, selectedSlot, activeDs, selectedEquippedDatasource, columnNames, restrictable, viewMode, labels, isEquipScreen)
      self.noCameraShift = nil
      if self.visible == false and self.GetWindow() then
        self.selectedSlotMapID = selectedSlotMapID
        self.selectedSlotMapCount = selectedSlotMapCount
        self.selectedSlot = selectedSlot
        self.activeDs = activeDs
        self.selectedEquippedDatasource = selectedEquippedDatasource
        self.selectedSlotMap = selectedSlotMap
        NonModalContext:AddContext(self)
        self.GetWindow():Show()
        self.visible = true
        if self.GetSwf() then
          self.GetSwf():Reset()
          self.GetSwf():Invoke("setIsEquipScreen_lua", isEquipScreen)
          self.m_isEquipScreen = isEquipScreen == 1
          if self.m_isEquipScreen then
            self:PopulateJobs()
          else
            self.m_selectedJob = nil
          end
          for i = 1, #EquipmentHandlerStrings do
            self.GetSwf():Invoke("setString", i - 1, EquipmentHandlerStrings[i])
          end
          if labels then
            self:SetCategoryLabels(labels, "^")
          end
          if restrictable then
            self:SetEquipmentSlotRestrictions()
          end
          self.GetSwf():Invoke("setMemberStatus", tostring(Ui.IsMember()))
          self.GetSwf():Invoke("setIconType", HUD.supressIconTint)
          local LastViewModeSelected = Ui.GetUserOptionsValue("EquipmentWindowOptions", "LastViewModeSelected", "0")
          if columnNames ~= nil then
            self.GetSwf():Invoke("setColumnNames", columnNames, "^")
          end
          if viewMode == nil then
            self.currentViewMode = LastViewModeSelected
          else
            self.currentViewMode = viewMode
          end
          self.GetSwf():Invoke("setMode", self.currentViewMode)
          self.GetSwf():Invoke("setMembershipStatus", tostring(Ui.IsMember()))
        end
        self:RegisterDatasources()
        self:SetCurrentEquip()
        self:OnResize()
        if HUD.inMiniGame then
          Logger:print("equipscreen.lua", "Disabling Jobs")
          self.GetSwf():Invoke("setIsJobsDisabled_lua", 1)
        else
          Logger:print("equipscreen.lua", "Enabling Jobs")
          self.GetSwf():Invoke("setIsJobsDisabled_lua", 0)
        end
      end
    end,
    EnableCategory = function(self, id, enabled)
      self.GetSwf():Invoke("enableCategoryButton", id, tostring(enabled))
    end,
    DisableAllCategoriesExcept = function(self, activeSlotID, value)
      for i = 1, 7 do
        if activeSlotID ~= i then
          self:EnableCategory(i, value)
        end
      end
    end,
    SetMode = function(self, modeID)
      self.currentMode = modeID
      Logger:print("equipscreen.lua", "Setting Mode: " .. self.currentMode)
      if self.GetSwf() then
        self.GetSwf():Invoke("setEquipmentMode", modeID)
      end
      if self.groomMode == 0 and self.feedMode == 0 and self.currentMode == EquipmentModes.STYLE_CARDS then
        Logger:print("equipscreen.lua", "Setting Legend for style cards")
        self.GetWindow():SetProperty("Legend", 86)
      end
    end,
    SetRequiredSlots = function(self, ...)
      if self.GetSwf() then
        self.GetSwf():Invoke("setRequiredSlots", ...)
      end
    end,
    ShowActionButton = function(self, label)
      if self.GetSwf() then
        self.GetSwf():Invoke("displayActionButton", label)
      end
    end,
    SetActionButtonToolTip = function(self, tip)
      if self.GetSwf() then
        self.GetSwf():Invoke("setActionButtonToolTip", tip)
      end
    end,
    PetMode = function(self, mode)
      if self.GetSwf() then
        if mode == 2 then
          self:ShowActionButton(Ui.GetString("EquipUIPetsClean"))
          self:SetActionButtonToolTip(Ui.GetString("GroomTip"))
          self:SetRequiredSlots(1, 2)
        elseif mode == 3 then
          self:ShowActionButton(Ui.GetString("EquipUIPetsFeed"))
          self:SetActionButtonToolTip(Ui.GetString("FeedTip"))
          if not PetTutorial.enabled then
            self:SetRequiredSlots(1, 2)
          else
            self:SetRequiredSlots(1, 2, 3)
          end
        elseif mode == 4 then
          self:SetMode(EquipmentModes.PETS_TRICKS)
          return
        end
        self:SetMode(EquipmentModes.PETS)
      end
