      if self.GetSwf() then
        local message = ""
        local ds = DsTable.Find("BaseClient.EquipmentSlots")
        if ds then
          local numRows = ds:GetRowCount()
          local numCols = ds:GetColumnCount()
          if numRows > 0 and numCols > 0 then
            for i = 0, numRows - 1 do
              message = message .. ds:GetData(i, 0)
              for c = 1, numCols - 1 do
