    end,
    PopulateWindow = function(self, message, numRows)
      if self.GetSwf() then
        self.GetSwf():Invoke("setData", message, numRows)
      end
    end,
    PopulateWindowCategories = function(self, message, numRows)
      if self.GetSwf() then
        if self.m_isEquipScreen then
          self.GetSwf():Invoke("setCategoryDataForEquip_lua", message, numRows)
        else
          self.GetSwf():Invoke("setCategoryData_lua", message, numRows)
        end
      end
    end,
    BuildItemString = function(ds, row)
      local item = ds:GetData(row, 0)
