        for i = self.endIndex, count do
          if self.history[i] ~= nil then
            if i ~= self.endIndex then
              message = message .. "\n"
            end
            message = message .. self.history[i]
          end
        end
        for i = 0, self.endIndex - 1 do
          if self.history[i] ~= nil then
            message = message .. "\n"
