    end,
    Show = function(self)
      if not self.isShown then
        NonModalContext:AddContext(self)
        self:OnResize()
        self.isShown = true
        self:SetFocus()
        if UpdateList.Console ~= self then
          UpdateList.Console = self
        end
      end
    end,
    Hide = function(self)
      if self.isShown then
        NonModalContext:RemoveContext(self)
        self.isShown = false
        local wnd = Window.Find(self.nameWnd)
        if wnd then
          wnd:Hide()
        end
        UpdateList.Console = nil
      end
    end,
    SetFocus = function(self)
      local wnd = Window.Find(self.nameWnd)
      local swf = GfxCtrl.Find(self.nameSwf)
      if wnd then
        wnd:SetFocus()
      end
      if swf then
        swf:Invoke("SetInputFocus")
      end
    end,
    OnResize = function(self)
      local wnd = Window.Find(self.nameWnd)
      local sw, sh = Window.GetCanvasSize()
      local h = sh * 0.3
      if wnd then
        wnd:SetSize(sw, h)
        wnd:SetPosition(0, 0)
        wnd:Show()
      end
      local swf = GfxCtrl.Find(self.nameSwf)
      if swf then
        swf:Invoke("SetSize", sw, h)
        swf:SetProperty("X", -500)
        swf:SetProperty("Y", 0)
        swf:SetProperty("Width", sw)
        swf:SetProperty("Height", h)
      end
    end,
    ShowMessage = function(self, guid, from, msg, sizeChat, fgColor, bgColor)
      if msg ~= nil and msg ~= "" and msg ~= " " then
        self.history[self.endIndex] = msg
        self.endIndex = self.endIndex + 1
        if self.endIndex >= self.maxHistory then
          self.endIndex = 0
        end
        if self.endIndex == self.startIndex then
          self.startIndex = self.startIndex + 1
        end
        if self.startIndex >= self.maxHistory then
          self.startIndex = 0
        end
        if self.isLocked then
          return
        end
        self.dirty = true
        if self.loggingEnabled then
          self.LogToFile(msg)
        end
      end
    end,
    SetText = function(self, newText)
      local swf = GfxCtrl.Find(self.nameSwf)
      if swf then
        swf:Invoke("SetText", newText)
      end
    end,
    ClearHistory = function(self)
      local swf = GfxCtrl.Find(self.nameSwf)
      if swf then
        swf:Reset()
      end
      if self.loggingEnabled then
        print("/clear")
      end
      self.history = {}
      self.startIndex = 0
      self.endIndex = 0
      self.isShown = false
      self.dirty = true
      self:Show()
    end,
    SetHistory = function(self, maxHistory)
      local oldHistory = self.maxHistory
      if not maxHistory or type(tonumber(maxHistory)) ~= "number" then
        print("Console history value is not a valid number. Please enter a valid number to set as the max history ( Defualt: 300 ).")
        return
      end
      self:ClearHistory()
      self.maxHistory = tonumber(maxHistory)
      print("Console history has been changed from '" .. tostring(oldHistory) .. "' to '" .. tostring(self.maxHistory) .. "'.")
    end,
    SetConsoleLocked = function(lock)
      local status = "unlocked"
      if lock == "0" then
        lock = false
        Console.dirty = true
      elseif lock == "1" then
        lock = true
        status = "locked"
      else
        return Console.isLocked
      end
      print("Console is now '" .. status .. "'.")
      Console.isLocked = lock
    end,
    DumpHistory = function(filename)
      if not Admin then
        return
      end
      filename = filename or "FRConsoleDump.txt"
      io.output(io.open(filename, "w"))
      io.write("File Dumped at [" .. os.date() .. [[
].

]])
      local count = #Console.history
      for i = Console.endIndex, count - 1 do
        if Console.history[i] ~= nil then
          io.write(Console.history[i] .. "\n")
        end
      end
      for i = 0, Console.endIndex - 1 do
        if Console.history[i] ~= nil then
          io.write(Console.history[i] .. "\n")
        end
      end
      io.flush()
      io.close()
      print("Console history written to file '" .. tostring(filename) .. "'.")
    end,
    LogToFile = function(message)
      if not Admin then
        return
      end
      io.output(io.open(Console.logFileName, "a+"))
      io.write(message .. "\n")
