      io.close()
    end,
    ClearLog = function()
      print([[
--		Console Logging Info		--
	Action:			Log File Cleared
	Log Filename:		]] .. tostring(Console.logFileName) .. "")
      io.output(io.open(Console.logFileName, "w+"))
      io.close()
    end,
    Log = function(filename)
      local enabled = true
      if Console.loggingEnabled and not filename then
        enabled = false
      end
      if filename then
        Console.logFileName = filename
      end
      Console.loggingEnabled = enabled
      print([[
--		Console Logging Info		--
	Action:			Toggle Console Logging
	Logging Enabled:	]] .. tostring(Console.loggingEnabled) .. [[

	Log Filename:		]] .. tostring(Console.logFileName) .. "")
    end
  }
  function Main_wndConsole_swfConsole_OnUserEvent(a, b, c, d)
