  end
  function Main_wndConsole_swfConsole_OnFocus(a)
    local swf = GfxCtrl.Find(Console.nameSwf)
    if a == "0" and swf then
      swf:Invoke("LostFocus")
    elseif swf then
      swf:Invoke("SetInputFocus")
    end
  end
  function OnPrintConsole(text, colorIndex)
    Console:ShowMessage(nil, "Message", text, 0, 16777215)
  end
end)()
