        if tonumber(parentId) > 128 and tonumber(parentId) < 135 then
          m:Invoke("createChatOption", row, id, displayStringId, Type, parentId, sayStringId, animId)
        end
        if tonumber(parentId) == 13 then
          m:Invoke("createChatOption", row, id, displayStringId, Type, 0, sayStringId, animId)
        end
      else
        if tonumber(id) < 5 then
        end
        if tonumber(parentId) ~= 13 and tonumber(id) ~= 13 then
          m:Invoke("createChatOption", row, id, displayStringId, Type, parentId, sayStringId, animId)
        end
      end
    end,
    AddQuickChatPhrases = function(self, emote)
      local ds = DsTable.Find("BaseClient.QuickChatData")
      local nanVal = "String#0 not found"
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          if tonumber(ds:GetData(i, 0)) < 5 then
            chatHandler:CreateQuickChatPhrase(i, ds:GetData(i, 0), ds:GetData(i, 2), 2, ds:GetData(i, 1), ds:GetData(i, 3), ds:GetData(i, 4))
          elseif ds:GetData(i, 3) ~= nanVal or ds:GetData(i, 3) == nanVal and ds:GetData(i, 4) ~= "0" then
            chatHandler:CreateQuickChatPhrase(i, ds:GetData(i, 0), ds:GetData(i, 2), 1, ds:GetData(i, 1), ds:GetData(i, 3), ds:GetData(i, 4))
          else
            chatHandler:CreateQuickChatPhrase(i, ds:GetData(i, 0), ds:GetData(i, 2), 3, ds:GetData(i, 1), ds:GetData(i, 3), ds:GetData(i, 4))
          end
        end
        self:GetRecentPhrases()
        for i = self.maxRecentPhrases - 1, 0, -1 do
          local row = self.recentPhrasesArray[i]
          if row ~= -1 and row < numRows - 1 then
            chatHandler:CreateQuickChatPhrase(row, ds:GetData(row, 0), ds:GetData(row, 2), 1, self.favoriteNodeId, ds:GetData(row, 1), ds:GetData(row, 4))
          end
        end
      end
    end,
    AddMockupPhrases = function(self)
      chatHandler:CreateCannedChatPhrase(1, self.LastUsedTable[1], 2, 0)
      chatHandler:CreateCannedChatPhrase(2, self.LastUsedTable[2], 2, 0)
      chatHandler:CreateCannedChatPhrase(3, self.LastUsedTable[3], 2, 0)
      chatHandler:CreateCannedChatPhrase(4, self.LastUsedTable[4], 2, 0)
    end,
    KeyDown = function(self, a)
      local edit, otherEdit
      if self.chatMode == self.chatModeChatLog then
        edit = chatHandler.nameInEdit
        otherEdit = chatHandler.nameFloatingEdit
      else
        edit = chatHandler.nameFloatingEdit
        otherEdit = chatHandler.nameInEdit
      end
      local key = Client.ReverseKeyName(a)
      if key == "Return" then
        local editInput = EditControl.find(edit)
        local strInput
        if editInput:getCharCount() > 0 then
          strInput = editInput:getText()
          Ui.ProcessChatCommand(strInput)
        end
        editInput:clear()
        editInput = EditControl.find(otherEdit)
        editInput:clear()
        Window.SetFocus()
      elseif key == "Escape" then
        local editInput = EditControl.find(edit)
        if editInput:getCharCount() > 0 then
          editInput:clear()
        else
          Window.SetFocus()
        end
      elseif key == "Up" then
        Ui.ChatSetPreviousCommand()
      elseif key == "Down" then
        Ui.ChatSetNextCommand()
      end
    end,
    GetRecentPhrases = function(self)
      for i = 0, self.maxRecentPhrases do
        self.recentPhrasesArray[i] = tonumber(Ui.GetUserOptionsValue("QuickChatRecentPhrases", "Recent" .. i, "-1"))
      end
    end,
    ResetRecentPhrases = function(self)
      for i = 0, self.maxRecentPhrases do
        Ui.SetUserOptionsValue("QuickChatRecentPhrases", "Recent" .. i, 0)
      end
    end,
    AddPhraseToRecents = function(self, phraseId)
      self:GetRecentPhrases()
      local newRecentPhrases = {}
      newRecentPhrases[0] = tonumber(phraseId)
      local skip = 0
      local i = 0
      while i <= self.maxRecentPhrases do
        if newRecentPhrases[0] ~= self.recentPhrasesArray[i + skip] then
          newRecentPhrases[i + 1] = self.recentPhrasesArray[i + skip]
          i = i + 1
        else
          skip = skip + 1
        end
      end
      for i = 0, self.maxRecentPhrases do
        if newRecentPhrases[i] == nil then
          newRecentPhrases[i] = -1
        end
        Ui.SetUserOptionsValue("QuickChatRecentPhrases", "Recent" .. i, newRecentPhrases[i])
      end
      self.recentPhrasesArray = newRecentPhrases
    end,
    processQuickChat = function(self, nodeId, name)
      if name ~= "" then
        Ui.ProcessQuickTellCommand(nodeId, name)
      elseif ChatLog.currentFilter == nil or ChatLog.currentFilter == ChatLog.ALL_CHANNEL then
        Ui.ProcessQuickChatCommand(nodeId)
      elseif ChatLog.currentFilter == ChatLog.GROUP_CHANNEL then
        Ui.ProcessQuickGroupChatCommand(nodeId)
      elseif ChatLog.currentFilter == ChatLog.GUILD_CHANNEL then
        Ui.ProcessQuickGuildChatCommand(nodeId)
      elseif ChatLog.currentFilter == ChatLog.AREA_CHANNEL or ChatLog.currentFilter == ChatLog.TRADE_CHANNEL or ChatLog.currentFilter == ChatLog.LFG_CHANNEL or ChatLog.currentFilter == ChatLog.MO_CHANNEL then
        Ui.ProcessQuickChatChannelCommand(nodeId, ChatLog.currentFilter)
      else
        Ui.ProcessQuickTellCommand(nodeId, ChatLog.currentFilter)
      end
    end
  }
  UpdateList.chatHandler = chatHandler
  function Main_wndCannedChat_swfCannedChat_OnUserEvent(a, b, c, d)
    if a == "cannedChatSend" then
      chatHandler:processQuickChat(b, d)
      if chatHandler.emotesShown ~= 1 then
        chatHandler:AddPhraseToRecents(c)
      end
      chatHandler:HideCannedChat()
    elseif a == "CloseWindowPS3" then
      Logger:print("minchat.lua", "closing PS3")
      chatHandler:HideCannedChat()
      NavigationHandler:EnableBar()
    elseif a == "playSound" then
      HUD:PlaySound(b)
    elseif a == "AS_Print" then
    end
  end
  function Main_wndCannedChat_swfCannedChat_OnFocus(a, b, c, d, e, f)
    if tonumber(a) == 0 and chatHandler.m_onFocusEnabled then
      chatHandler:HideCannedChat()
    end
  end
  Client.ChatHandler = "chatHandler"
end)()
