;(function()
  CuteMode = {
    value = 1,
    toValue = 1,
    change = 0.1,
    Big = function(self)
      if self.toValue > 1 then
        self:Deflate(1)
      else
        self:Inflate(3.2)
      end
    end,
    Small = function(self)
      if self.toValue < 1 then
        self:Deflate(1)
      else
        self:Inflate(0.4)
      end
    end,
    Update = function(self)
      local bChanged = false
      if self.value < self.toValue + self.change and self.value > self.toValue - self.change then
        self.value = self.toValue
        bChanged = true
      end
      if self.value < self.toValue then
        self.value = self.value + self.change
        bChanged = true
      end
      if self.value > self.toValue then
        self.value = self.value - self.change
        bChanged = true
      end
      if bChanged then
        Ui.SetHeadSize(self.value)
      else
        UpdateList.CuteMode = nil
      end
    end,
    Inflate = function(self, value)
      if value == nil then
        if self.toValue < 3.2 then
          self.toValue = 3.2
        elseif self.toValue < 5 then
          self.toValue = self.toValue + 2
        end
        self:SetSize(self.toValue)
      else
        self:SetSize(tonumber(value))
      end
    end,
    Deflate = function(self, value)
      self:SetSize(1)
    end,
    SetSize = function(self, theSize)
      self.toValue = theSize
      if self.value ~= self.toValue then
        UpdateList.CuteMode = CuteMode
      end
    end,
    SetSizeInstant = function(self, value)
      self.value = value
      self.toValue = value
      Ui.SetHeadSize(self.value)
      UpdateList.CuteMode = nil
    end
  }
end)()
