;(function()
  WindowTweener = {
    tweenerCount = 0,
    theFrameTimeMs = 0.001,
    Create = function(self, theWindowName, theProperty, startValue, endValue, theSpeed, onComplete)
      local newTweener = {}
      setmetatable(newTweener, self)
      self.__index = self
      newTweener.wndName = Ui.GetName(theWindowName)
      newTweener.theProperty = theProperty
      newTweener.startValue = startValue
      newTweener.endValue = endValue
      newTweener.theValue = startValue
      newTweener.theSpeed = theSpeed
      newTweener.frames = 0
      newTweener.onComplete = onComplete
      self.tweenerCount = self.tweenerCount + 1
      newTweener.theName = "wt-" .. theWindowName .. "-" .. theProperty
      local w = Window.Find(newTweener.wndName)
      if w then
        if UpdateList[newTweener.theName] ~= nil then
          newTweener.wasMoveable = UpdateList[newTweener.theName].wasMoveable
        elseif w:GetProperty("Moveable") == "True" then
          newTweener.wasMoveable = 1
        end
        UpdateList[newTweener.theName] = newTweener
        w:SetProperty("Moveable", "False")
      end
    end,
    QuitTween = function(self)
      if self.wasMoveable then
        local w = Window.Find(self.wndName)
        w:SetProperty("Moveable", "True")
      end
      UpdateList[self.theName] = nil
    end,
    Tween = function(self)
      self.frames = self.frames + 1
      if self.frames == 1 then
        local w = Window.Find(self.wndName)
        self.startValue = tonumber(w:GetProperty(self.theProperty))
        self.theValue = self.startValue
      elseif self.frames > 1 then
        local rate = Ui.GetFrameTime()
        if rate < 1.0E-5 then
          rate = 1.0E-5
        elseif rate > 0.1 then
          rate = 0.1
        end
        rate = rate * 10 * self.theSpeed
        if rate > 1 then
          rate = 1
        end
        self.theValue = self.theValue + rate * (self.endValue - self.theValue)
        if 1 > math.abs(self.endValue - self.theValue) then
          self.theValue = self.endValue
          self:QuitTween()
          if self.onComplete then
            self.onComplete()
          end
        end
      end
    end,
    Update = function(self)
      local w = Window.Find(self.wndName)
      if w == nil then
        self:QuitTween()
        return
      end
      self:Tween()
      w:SetProperty(self.theProperty, tostring(self.theValue))
    end
  }
  CameraTweener = {
    tweenerCount = 0,
    theFrameTimeMs = 0.001,
    Create = function(self, newX, oldX, newY, oldY, theSpeed, onComplete)
      local newTweener = {}
      setmetatable(newTweener, self)
      self.__index = self
      newTweener.newX = newX
      newTweener.newY = newY
      newTweener.oldX = oldX
      newTweener.oldY = oldY
      newTweener.theSpeed = theSpeed
      newTweener.frames = 0
      newTweener.onComplete = onComplete
      self.tweenerCount = self.tweenerCount + 1
      newTweener.theName = "ct-camera"
      UpdateList[newTweener.theName] = newTweener
    end,
    QuitTween = function(self)
      UpdateList[self.theName] = nil
    end,
    Tween = function(self)
      self.frames = self.frames + 1
      if self.frames == 1 then
        self.theValueX = self.oldX
        self.theValueY = self.oldY
      elseif self.frames > 1 then
        local rate = Ui.GetFrameTime()
        if rate < 1.0E-5 then
          rate = 1.0E-5
        elseif rate > 0.1 then
          rate = 0.1
        end
        rate = rate * 10 * self.theSpeed
        if rate > 1 then
          rate = 1
        end
        self.theValueX = self.theValueX + rate * (self.newX - self.theValueX)
        self.theValueY = self.theValueY + rate * (self.newY - self.theValueY)
        if 1 > math.abs(self.newX - self.theValueX) then
          self.theValueX = self.newX
          self.theValueY = self.newY
          if self.onComplete then
            self.onComplete()
          end
          self:QuitTween()
        end
      end
    end,
    Update = function(self)
      self:Tween()
      Ui.SetDialogCameraOffset2D(tostring(self.theValueX), tostring(self.theValueY))
    end
  }
end)()
