;(function()
  CollectionHandler = {
    wndCollectionDetails = Ui.GetName("Main.wndCollectionDetails"),
    swfCollectionDetails = Ui.GetName("Main.wndCollectionDetails.swfCollectionDetails"),
    collectionDisplayed = false,
    screenActive = false,
    activeCategory = 1.5,
    GetSwf = function()
      return GfxCtrl.Find(CollectionHandler.swfCollectionDetails)
    end,
    Populate = function(self, swfName)
      local swf = GfxCtrl.Find(Ui.GetName(swfName))
      local ds = DsTable.Find(DataSources[DS_COLLECTIONS])
      swf:Invoke("SetString", 2, Ui.GetString("CollectionBrowserCollected"))
      swf:Invoke("SetMode", 3)
      swf:Invoke("setIconType", HUD.supressIconTint)
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local paramstbl = {}
          for c = 1, numCols do
            paramstbl[c] = ds:GetData(i, c - 1)
          end
          local paramsCount = #paramstbl
          if paramsCount < 16 then
            for c = paramsCount, 16 do
              paramstbl[c] = -1
            end
          end
          swf:Invoke("AddCollection", tonumber(paramstbl[1]), tostring(paramstbl[2]), tostring(paramstbl[3]), tonumber(paramstbl[4]), tonumber(paramstbl[5]), tostring(paramstbl[6]), tonumber(paramstbl[7]), tonumber(paramstbl[8]), tonumber(paramstbl[9]), tonumber(paramstbl[10]), tonumber(paramstbl[11]), tonumber(paramstbl[12]), tonumber(paramstbl[13]), tonumber(paramstbl[14]), tonumber(paramstbl[15]), tonumber(paramstbl[16]), tonumber(paramstbl[17]))
        end
      end
    end,
    Show = function(self, category)
      if tonumber(category) == JobHandler.MODE_COLLECTIONS then
        category = 0
      end
      self.activeCategory = category
      self.screenActive = true
      Ui.SetCollectionFilterByCategory(math.floor(self.activeCategory))
      self:ShowBrowser()
    end,
    ShowBrowser = function(self, CollectionID)
      if CollectionDetails.visible then
        CollectionDetails:Hide()
      end
      BrowserHandler.windowName = "Collections"
      BrowserHandler.isInSubMenu = true
      BrowserHandler:Show(self, Ui.GetString(16431), Ui.GetString("UI_Browser_CollectionSubtext"), Ui.GetString("UI_Browser_ClickSwitchCollections"), 0, BrowserHandler.visible)
      BrowserHandler:Connect(self)
      BrowserHandler:HideCloseButton()
      if CollectionID == nil then
        self:SelectFirstCollection()
        BrowserHandler:ExpandBrowser()
      elseif self.selectedCollection ~= nil then
        BrowserHandler:SelectItem(self.selectedCollection)
        BrowserHandler:ExpandBrowser()
      end
    end,
    Hide = function(self, noAudio)
      self:HideCollection()
      BrowserHandler:Hide(noAudio, 1)
      BrowserHandler:Disconnect(self)
      self.screenActive = false
    end,
    BrowserOnUserEvent = function(self, a, b)
      if a == "SelectCollection" then
        ToolTipHandler:HideToolTip()
        self.selectedCollection = tonumber(b)
        self:ShowCollection(self.selectedCollection)
      elseif a == "ExpandedBrowser" then
        CollectionDetails:Hide()
      elseif a == "CompressBrowser" then
        self:ShowCollection(self.selectedCollection)
      elseif a == "CloseBrowser" then
        ToolTipHandler:HideToolTip()
        self:Hide()
        JobHandler:ModeSwitch(0)
      end
    end,
    SelectFirstCollection = function(self)
      local ds = DsTable.Find(DataSources[DS_COLLECTIONS])
      if ds and ds:GetRowCount() > 0 then
        local id = tonumber(ds:GetData(0, 0))
        if id ~= nil then
          BrowserHandler:SelectItem(id)
          self.selectedCollection = id
        end
      end
    end,
    ShowCollection = function(self, ID, override)
      BrowserHandler:CompressBrowser()
      CollectionDetails:Show(ID)
    end,
    ReturnToBrowser = function(self)
      self:ShowBrowser(self.selectedCollection)
    end,
    HideCollection = function(self)
      if CollectionDetails.visible then
        CollectionDetails:Hide()
      end
    end,
    ListenToCollectionsDs = function(self)
      DataSourceConnection:Connect("BaseClient.CollectionEntriesData", CollectionHandler, "TutorialDataUpdate")
    end,
    TutorialDataUpdate = function()
      GameDockTutorial:AddCollections()
      DataSourceConnection:Disconnect("BaseClient.CollectionEntriesData", CollectionHandler)
    end
  }
end)()
