      Logger:print("quests.lua", "***building quest nav bar***")
      NavigationHandler:Disconnect(self)
      NavigationHandler:Connect(self)
      NavigationHandler:Show(nil, nil, 0)
      NavigationHandler:AddButton(22653, Ui.GetString("Calendar"), NavButtons.Calendar)
      NavigationHandler:AddButton(20996, Ui.GetString("ActivityFinder"), NavButtons.ActivityFinder)
      NavigationHandler:AddButton(454, Ui.GetString("Quests"), NavButtons.Quests)
      NavigationHandler:AddButton(21215, Ui.GetString("Matchmaking"), NavButtons.MATCHMAKING)
      NavigationHandler:SelectButton(1)
    end,
    NavigationOnUserEvent = function(self, a, b, c)
      TutorialDialog:Hide()
      if a == "SwitchTo" then
        if math.floor(tonumber(b)) == tonumber(b) then
          self:ModeSwitch(tonumber(b))
        else
        end
      elseif a == "exitScreen" then
        if ActivityPortal.isShow then
          QuestHandler:DismissAll()
        else
          QuestHandler:Hide()
        end
      end
    end,
    DismissAll = function(self)
      if ActivityPortal.isTweeningIn == false then
        QuestHandler:Hide()
        ActivityPortal:Hide()
        if not ActivityPortal.launchedMinigame then
          GameDock:SetState(GameDock.NORMAL_STATE)
          HUD:showMain()
          FunctionStack:PopAndRun("NagStack")
        end
        TutorialDialog:Hide()
      end
    end,
    ModeSwitch = function(self, mode)
      HUD:PlaySound("ShowWindow")
      if Context:GetCurrent() == self.CONTEXT_HIDE or Context:GetCurrent() == self.CONTEXT_CARDHIDE or Context:GetCurrent() == Lobby.CONTEXT_HIDE then
        self.hideCalledFromNav = true
        Context:CallQuit()
      end
      self.activeMode = mode
      Context:Push(self.CONTEXT_HIDE, function()
        QuestHandler:Hide()
      end)
      ActivityPortal:Enable(false)
      if mode == NavButtons.ActivityFinder then
        ActivityFinderHandler:ShowFromNav()
      elseif mode == NavButtons.Quests then
        self:ShowQuestsMode()
      elseif mode == NavButtons.Calendar then
        ActivityCalendar:Show()
      elseif mode == NavButtons.WelcomeScreen then
        WelcomeHandler:Show()
      elseif mode == NavButtons.CardGame then
