      if Ui.IsMember() then
        isa = 1
      end
      squests:Invoke("SetIsMember", isa)
      local ds = DsTable.Find("BaseClient.QuestData")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        local firstItem = 0
        local lastItem = numRows
        if firstItem > numRows - 1 or firstItem < 0 then
          firstItem = 0
          lastItem = 3
          self.currentPage = 1
        end
        if lastItem > numRows - 1 then
          lastItem = numRows - 1
        end
        if lastItem < 0 then
          lastItem = 0
        end
        local index = 1
        for i = firstItem, lastItem do
          if i < numRows and numRows > 0 then
            local selectQuest = 0
            if tonumber(QuestHelper.helperCurrentQuest) == tonumber(ds:GetData(i, QuestDsColumn.ID)) then
              selectQuest = 1
            end
            squests:Invoke("addQuest", index, ds:GetData(i, QuestDsColumn.ID), ds:GetData(i, QuestDsColumn.Name), ds:GetData(i, QuestDsColumn.Description), ds:GetData(i, QuestDsColumn.TimeStarted), ds:GetData(i, QuestDsColumn.CompletionPercentage), ds:GetData(i, QuestDsColumn.ObjectiveCount), ds:GetData(i, QuestDsColumn.ProfileBadge), ds:GetData(i, QuestDsColumn.ProfileLevel), ds:GetData(i, QuestDsColumn.ProfileIcon), ds:GetData(i, QuestDsColumn.MembersOnly), ds:GetData(i, QuestDsColumn.IconId), selectQuest)
            index = index + 1
          end
        end
        squests:Invoke("SetQuestLimit", numRows, QuestScreen.GetQuestLimit())
      end
    end,
    SelectQuest = function(self, id)
      QuestScreen.SelectQuest(id)
      local squests = GfxCtrl.Find(self.swfQuests)
      local ds = DsTable.Find("BaseClient.QuestObjectiveData")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          squests:Invoke("addObjective", id, i + 1, ds:GetData(i, QuestObjectiveDsColumn.Name), ds:GetData(i, QuestObjectiveDsColumn.Status), ds:GetData(i, QuestObjectiveDsColumn.Description))
        end
      end
      squests:Invoke("SelectQuest", id)
      squests:Invoke("receivedObjectives", id)
      HUD:PlaySound("Selected")
      QuestScreen.SelectQuest(QuestHelper.helperCurrentQuest)
    end,
    UpdateObjective = function(self, questID, objectiveID)
      local ds = DsTable.Find("BaseClient.QuestObjectiveData")
      if ds then
        local row = ds:FindRow(objectiveID)
        if row > -1 then
          local status = ds:GetData(row, QuestObjectiveDsColumn.Status)
          local statusText = ds:GetData(row, QuestObjectiveDsColumn.Name)
          local shelper = GfxCtrl.Find(QuestHelper.swfQuestHelper)
          local squests = GfxCtrl.Find(self.swfQuests)
          shelper:Invoke("updateObjective", questID, objectiveID, status, statusText)
          squests:SoftInvoke("updateObjective", questID, row, status, statusText)
