        Window.Find(wndUpgrade):Hide()
      end)
    end
  }
  function Main_wndQuestScreen_swfQuestScreen_OnUserEvent(a, b)
    if a == "selectQuest" then
      QuestHandler:SelectQuest(tonumber(b))
    elseif a == "onUpgrade" then
      QuestHandler:Hide()
      MarketplaceHandler:Show(1)
    elseif a == "close" then
      QuestHandler:HideQuestsMode()
      NavigationHandler:EnableBar()
    elseif a == "selectHelperQuest" then
      QuestHelper:PopulateHelper(tonumber(b))
      HUD:PlaySound("ShowWindow")
    elseif a == "removeHelperQuest" then
      QuestHelper:CloseHelper()
      HUD:PlaySound("MenuDown")
    elseif a == "abandonQuest" then
      QuestScreen.AbandonQuest(b)
    elseif a == "setCurrentPage" then
      Ui.SetUserOptionsValue("questOptions", "currentPage", b)
      QuestHandler.currentPage = tonumber(b)
      QuestHandler:Populate()
    elseif a == "ExitButtonClicked" then
      QuestHandler:Hide()
    elseif a == "debugPrint" or a == "ASPrint" then
    end
  end
  function Main_wndUpgradeDialog_swfUpgradeDialog_OnUserEvent(a, b)
    if a == "CloseUpgradeDialog" then
      QuestHandler:HideUpgradeDialog()
    elseif a == "onUpgrade" then
      QuestHandler:HideUpgradeDialog()
      MarketplaceHandler:Show("1")
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    end
  end
  function Main_wndQuestScreen_swfQuestScreen_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndUpgradeDialog_swfUpgradeDialog_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function BaseClient_QuestData_OnDataUpdate()
    local squests = GfxCtrl.Find(QuestHandler.swfQuests)
    if QuestHandler.isQuestWindowShown then
      squests:Reset()
      QuestHandler:Populate()
    end
  end
  function BaseClient_QuestData_OnQuestAdded(a)
    local squests = GfxCtrl.Find(QuestHandler.swfQuests)
    squests:Reset()
    if QuestHandler.isQuestWindowShown then
      QuestHandler:Populate()
    end
    if QuestHelper.isHelperShown ~= 1 then
      QuestHelper:PopulateHelper(QuestHelper.helperCurrentQuest)
      QuestHelper:ShowHelper()
      QuestHelper:MaximizeHelper()
    end
  end
  function BaseClient_QuestObjectiveData_OnDataUpdate()
    QuestHelper:PopulateHelper(QuestHelper.helperCurrentQuest)
  end
end)()
