      Window.SetFocus()
    end
  end
  function Main_wndQuestStart_swfQuestStart_OnUserEvent(a, b, c, d)
    QuestStartHandler.visible = false
    if a == "responseOption" then
      if tonumber(b) == 1 then
        QuestScreen.AcceptQuest()
        QuestStartHandler:Hide(true)
      elseif tonumber(b) == 2 then
        QuestStartHandler:Hide()
      elseif tonumber(b) == 3 then
        QuestStartHandler:HideEnd()
      end
    elseif a == "rewardItemChosen" then
    elseif a == "onUpgrade" then
      QuestStartHandler.dontShowMain = true
      QuestStartHandler:Hide()
      MarketplaceHandler:Show(1)
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "AS_Print" or a == "ASPrint" then
    elseif a == "expandedDetails" then
      QuestStartHandler:SetLegend(81, false)
    elseif a == "closedDetails" then
      QuestStartHandler:SetLegend(52, false)
    end
    Window.SetFocus()
  end
  function Main_wndQuestEnd_swfQuestStart_OnUserEvent(a, b, c, d)
    QuestStartHandler.visible = false
    if a == "responseOption" then
      if tonumber(b) == 1 then
        QuestScreen.AcceptQuest()
        QuestStartHandler:HideEnd(true)
      elseif tonumber(b) == 2 then
        QuestStartHandler:HideEnd()
      elseif tonumber(b) == 3 then
        QuestScreen.EndQuest(true)
        QuestStartHandler:HideEnd(true)
      end
    elseif a == "rewardItemChosen" then
    elseif a == "onUpgrade" then
      QuestStartHandler.dontShowMain = true
      QuestStartHandler:HideEnd()
      MarketplaceHandler:Show(1)
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "AS_Print" then
      Logger:print("queststart.lua", "AS_Print: " .. b .. ", " .. c .. ", " .. d)
    elseif a == "expandedDetails" then
      QuestStartHandler:SetLegend(81, true)
    elseif a == "closedDetails" then
      QuestStartHandler:SetLegend(80, true)
    end
    Window.SetFocus()
  end
end)()
