      local swf = GfxCtrl.Find(self.movieName)
      local ds = DsTable.Find(DsName)
      local itemInfo = ""
      local statsDefData = DataSourceMethods:ParseDs("BaseClient.StatDefinitions", "~~", "|", "%%")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local firstItemId = ds:GetData(i, 19)
          local numItems = ds:GetData(i, 17)
          Ui.SelectItemDefinition(tonumber(firstItemId))
          local ds2 = DsTable.Find("BaseClient.ItemDefinitionSelect")
          local rank = ds2:GetData(0, 19)
          local profile = ds2:GetData(0, 18)
          itemInfo = itemInfo .. "FirstItemId%%" .. firstItemId .. "|Rank%%" .. rank .. "|" .. "Profile%%" .. profile
          local row = Ui.GetItemDefinitionStatRow(tonumber(firstItemId))
          local statsData
          if row ~= nil then
            statsData = ToolTipHandler:ParseDs("BaseClient.ItemStats", "*rowsep*", "*colsep*", "*keyvalue*", tonumber(row))
          end
          if statsData then
            itemInfo = itemInfo .. "|StatsData%%" .. statsData
          end
          if i < numRows - 1 then
            itemInfo = itemInfo .. "~~"
          end
        end
      end
      local funcName
      if group == 4 then
        if mode == true then
          funcName = "updateMarketplaceData"
        else
          funcName = "setMarketplaceData"
        end
      elseif mode == true then
        funcName = "updateMarketplaceNewItemsData"
      else
        funcName = "setMarketplaceNewItemsData"
      end
      swf:Invoke(funcName, res, itemInfo, statsDefData)
    end,
