  function Main_wndWelcome_swfWelcome_OnUserEvent(a, b, c, d)
    Logger:print("welcome.lua ", tostring(a) .. ", " .. tostring(b))
    if a ~= "debugPrint" and a ~= "AS_Print" and a ~= "closeWindow" and a ~= "PlaySound" then
      Ui.IncrementClientLuaMetric("WelcomeScreen_" .. tostring(a))
    end
    if a == "closeWindow" then
      WelcomeHandler:HideAndPopNext()
    elseif a == "onUpgrade" then
      MarketplaceHandler:Show(1)
    elseif a == "openQuestPane" then
      WelcomeHandler:Hide()
      QuestHelper:PopulateHelper(b)
    elseif a == "openMarketplacePane" then
      WelcomeHandler.skipFTE = true
      MarketplaceHandler:Show()
    elseif a == "updatePet" then
      WelcomeHandler:UpdatePetData(b)
    elseif a == "SelectPet" then
      Pet.Summon(b)
    elseif a == "addFunds" then
      WelcomeHandler.skipFTE = true
      MarketplaceHandler:Show(MarketplaceEnum.STORE_SC)
    elseif a == "newItemSelected" then
      MarketplaceHandler:Show(MarketplaceEnum.STORE_SC, MarketplaceCategoryIds.NEW_ITEMS)
    elseif a == "selectMarketItem" then
      WelcomeHandler.skipFTE = true
      MarketplaceHandler:Show(MarketplaceEnum.STORE_SC, MarketplaceStoreCategoryEnum.POTIONS)
    elseif a == "selectMarketplaceItem" then
      WelcomeHandler.skipFTE = true
      MarketplaceHandler:Show("2", b, c)
      Ui.IncrementClientLuaMetric("WelcomeScreen_selectMarketplaceItem_" .. tostring(b) .. "_" .. tostring(c))
    elseif a == "redeemCode" then
      CodeRedemptionHandler:RedeemCodeThroughSWF(b)
    elseif a == "startWheelMinigame" then
      WelcomeHandler:Hide()
      MiniGameFlashC.StartWheel()
    elseif a == "calendarButtonPressed" then
      WelcomeHandler:Hide()
      QuestHandler:ShowAndSelectCalendar()
    elseif a == "gotoCoinStore" then
      MarketplaceHandler:Show(MarketplaceEnum.COIN_STORE)
    elseif a == "gotoSCStore" then
      MarketplaceHandler:Show(MarketplaceEnum.PORTAL)
    elseif a == "gotoActivityPortal" then
      WelcomeHandler:Hide()
      QuestHandler:Show()
    elseif a == "iotdButtonPressed" then
      MarketplaceHandler:Show(MarketplaceEnum.STORE_SC)
      MarketplaceHandler:SetMode(MarketplaceEnum.STORE_SC, b, c, d)
    elseif a == "debugPrint" then
      Logger:print("welcome.lua", b)
    elseif a == "AS_Print" or a == "ASPrint" then
      print("Welcome ASPrint: " .. b)
    end
  end
  function Main_wndWelcome_swfWelcome_OnKeyDown(a, b)
    if Client.ReverseKeyName(a) == "Escape" then
      WelcomeHandler:Hide()
    end
  end
  function Main_wndWelcome_swfWelcome_OnFocus(a)
    if a == "0" then
      Window.SetFocus()
    end
  end
  function OnShowWelcomeScreen(firstLogin, secondsSinceLastLogin, startingScWalletBalance)
    ShowWelcomeScreen()
  end
  function ShowWelcomeScreen()
    MarketplaceHandler.referrerId = 0
    MarketplaceHandler.referrerContext = 0
    if WelcomeHandler.notShown == true and Tutorial.inTutorial == false and Ui.IsInCombat() == false then
      WelcomeHandler.notShown = nil
      WelcomeHandler:Show()
    else
      HUD:showMain()
    end
  end
  function YetAnotherSplitFunction(str, patt)
    vals = {}
    valindex = 0
    word = ""
    str = str .. patt
    for i = 1, string.len(str) do
      cha = string.sub(str, i, i)
      if cha ~= patt then
        word = word .. cha
      elseif word ~= nil then
        vals[valindex] = word
        valindex = valindex + 1
        word = ""
      else
        break
      end
    end
    return vals
  end
end)()
