      if self.isExpiredMode == 1 then
        HUD:showMain()
      else
        FunctionStack:PopAndRun("NagStack")
      end
    end,
    Hide = function(self)
      if self.isShown == false then
        return
      end
      self.isShown = false
      Context:Pop()
      local screenWidth, screenHeight = Window.GetCanvasSize()
      NonModalContext:RemoveContext(self)
      WindowTweener:Create("Main.wndMembershipRem", "Y", nil, screenHeight, 0.3, function()
        MembershipRem:HideFinal()
      end)
    end,
    HideFinal = function(self)
      self.isShown = false
      local w1 = Window.Find(self.windowName)
      local m = GfxCtrl.Find(self.movieName)
      m:Unload()
      w1:Hide()
    end,
    ShowNormalMode = function(self)
      self.isExpiredMode = 0
      self:Show()
    end,
    ShowExpiredMode = function(self)
      self.isExpiredMode = 1
      self:Show()
    end
  }
  function Main_wndMembershipRem_swfMembershipRem_OnFocus(a)
    if a == "0" then
      Window.SetFocus()
    end
  end
  function Main_wndMembershipRem_swfMembershipRem_OnUserEvent(a, b, c)
    if a == "ExitButtonClicked" then
      MembershipRem:HideAndPopNext()
    elseif a == "onUpgrade" then
      MembershipRem:Hide()
      HUD:showMain()
      MembershipHandler:Show()
    end
  end
end)()
