    GoToStep = function(self, step)
      local enum = MarketplaceTutorialEnum
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local sw, sh = Window.GetCanvasSize()
      local centerX = sw / 2
      local centerY = sh / 2
      if self.steps[self.currentStep + 1][1] ~= step and step ~= enum.START then
        return
      end
      self.currentStep = self.currentStep + 1
      self:ShowDialog()
      swf:Invoke("setTutorialStep", step)
      if step == enum.CLICK_SC then
        Tutorial:ShowArrow(centerX + 155, centerY - 125, 90)
      elseif step == enum.CLICK_MARKETPLACE then
        Tutorial:ShowArrow(centerX + 108, centerY + 280, 180)
      elseif step == enum.CLICK_CATEGORY then
        Tutorial:ShowArrow(centerX - 110, centerY - 110, 90)
      elseif step == enum.CLICK_ITEM then
        Tutorial:ShowArrow(centerX + 330, centerY + 230, 180)
      elseif step == enum.CLICK_ADD_FUNDS then
        Tutorial:ShowArrow(centerX + 335, centerY + 150, 90)
      elseif step == enum.CLICK_BUY then
        self:Finish()
      end
    end,
    Start = function(self)
      local enum = MarketplaceTutorialEnum
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local gamedockWnd = Window.Find(GameDock.windowName)
