        {
          enum.CLICK_MARKETPLACE,
          "MarketplaceTut0003"
        },
        {
          enum.CLICK_CATEGORY,
          "MarketplaceTut0004"
        },
        {
          enum.CLICK_ITEM,
          "MarketplaceTut0005"
        },
        {
          enum.CLICK_ADD_FUNDS,
          "MarketplaceTut0006"
        },
        {
          enum.CLICK_BUY,
          ""
        }
      }
      swf:Invoke("setTutorialMode", "1")
      self.currentStep = 0
      self:ShowDialog("MarketplaceTut0001")
      Tutorial:ShowArrow(gdX + 435, gdY - 80, 180)
    end,
    CloseDialog = function(self)
      Window.Find(Tutorial.wndTutorialDialog):Hide()
