    Init = function(self, mode)
      MarketplaceHandler:SetCategoryTree()
      CoinStoreHandler:SetCategoryTree()
      self:GetMembershipStatus()
      self:GetCurrencyString()
      if InGamePurchaseStoreScreen.IsMarketplaceEnabled() then
        MarketplaceHandler:SlashCommands("on")
      end
      AffiliateGroup.currentGroup = "-1"
      InGamePurchaseStoreScreen.SelectStoreItemGroup(1)
      local ds = DsTable.Find(MarketplaceHandler.dsGroupStoreItems)
      if ds:GetRowCount() > 0 then
        AffiliateGroup.currentGroup = MarketplaceGroups.MINICLIP
        AffiliateGroup.rowIndex = 0
        return
      end
      InGamePurchaseStoreScreen.SelectStoreItemGroup(2)
      local ds = DsTable.Find(MarketplaceHandler.dsGroupStoreItems)
      if ds:GetRowCount() > 0 then
        AffiliateGroup.currentGroup = MarketplaceGroups.BIGPOINT
        AffiliateGroup.rowIndex = 1
      end
    end,
    BundleTesting = function(self)
      InGamePurchaseStoreScreen.SelectStoreItemCategory(0)
      local ds = DsTable.Find(self.dsStoreItems)
      local rows = ds:GetRowCount()
      local row = 0
      local cnt = 0
      while rows > row do
        local val = ds:GetData(row, 20)
        if val == "1" then
          cnt = cnt + 1
        end
        row = row + 1
      end
    end,
    Show = function(self, mode, tocategory, bundleid, isGroup)
      if mode == MarketplaceEnum.COIN_STORE then
        self.windowName = self.windowNameCoin
        self.swfName = self.swfNameCoin
      else
        self.windowName = self.windowNameStore
        self.swfName = self.swfNameStore
      end
      Logger:print("marketplace.lua", "jump to category" .. tostring(tocategory))
      if tocategory ~= nil then
        self.displayCategory = tocategory
      else
        self.displayCategory = "-1"
      end
      if bundleid ~= nil then
        self.displayBundleId = bundleid
      else
        self.displayBundleId = "-1"
      end
      if Fishing.underwater == true then
        return
      end
      Logger:print("marketplace.lua", "self.boolMarketplaceReady" .. tostring(self.boolMarketplaceReady) .. " " .. tostring(InGamePurchaseStoreScreen.IsMarketplaceReady()))
      if mode == MarketplaceEnum.STORE_SC and self.boolMarketplaceReady == false then
        Logger:print("marketplace.lua", "stall for InitializeMarketplaceSupportSystem")
        self:ShowBlocker()
        MarketplaceHandler:InitMarketplace()
        self.futCatId = tocategory
        self.futBundleId = bundleid
        self.futIsGroup = isGroup
        return
      end
      self.boolIsShown = true
      HudWindowManager:HideSidePanels()
      if Ui.OnObjectiveEvent then
        Ui.OnObjectiveEvent("onMarketplaceOpen")
      end
      if VehicleGarage.visible then
        VehicleGarage:Conceal()
      end
      NonModalContext:AddContext(self)
      ConfirmationWindow:Connect(CoinStoreHandler)
      Context:Push("MarketPlace", function()
        MarketplaceHandler:Hide()
      end)
      local swf = GfxCtrl.Find(self.swfName)
      swf:Reset()
      if mode == MarketplaceEnum.STORE_SC then
        swf:Invoke("setData", "-", 0)
      end
      local w = Window.Find(self.windowName)
      local swf = GfxCtrl.Find(self.swfName)
      local width, height = w:GetSize()
      local screenWidth, screenHeight = Window.GetCanvasSize()
      w:SetProperty("Width", screenWidth)
      w:SetProperty("Height", screenHeight)
      swf:SetProperty("Width", screenWidth)
      swf:SetProperty("Height", screenHeight)
      w:SetPosition(0, -height)
      w:Show()
      local ds = DsTable.Find(self.dsStoreItems)
      if ds ~= nil then
        ds:EnableScriptEvents()
      end
      ds = DsTable.Find(self.dsPetPreview)
      if ds ~= nil then
        ds:EnableScriptEvents()
      end
      ds = DsTable.Find("BaseClient.ClaimSystem.AvailableItems")
      if ds ~= nil then
        ds:EnableScriptEvents()
      end
      ds = DsTable.Find("BaseClient.InGamePurchase.MannequinStoreItems")
      if ds ~= nil then
        ds:EnableScriptEvents()
      end
      ds = DsTable.Find(MarketplaceHandler.dsSearchItems)
      if ds ~= nil then
        ds:EnableScriptEvents()
      end
      ds = DsTable.Find(CoinStoreHandler.dsCoinStoreItems)
      if ds ~= nil then
        ds:EnableScriptEvents()
      end
      ds = DsTable.Find(CoinStoreHandler.dsCoinStoreItemsSell)
      if ds ~= nil then
        ds:EnableScriptEvents()
      end
      BaseClient_InGamePurchase_StoreItems_OnDataUpdate = self.handleDataUpdate
      BaseClient_InGamePurchase_StoreItemSearchResults_OnDataUpdate = self.handleDataUpdate
      BaseClient_InGamePurchase_StoreItemPreview_OnDataUpdate = self.handleDataUpdate
      BaseClient_InGamePurchase_MannequinStoreItems_OnDataUpdate = self.handleDataUpdate
      BaseClient_CoinStore_CoinStoreItems_OnDataUpdate = CoinStoreHandler.handleDataUpdate
      BaseClient_ClaimSystem_AvailableItems_OnDataUpdate = ClaimHandler.RefreshClaimItems
      BaseClient_CoinStore_CoinStoreItems_OnDataChanged = CoinStoreHandler.handleDataChanged
      MarketplaceHandler:Init(mode)
      self:SetMode(mode, self.displayCategory, self.displayBundleId, isGroup)
      HUD:PlaySound("ShowWindow")
      if mode == MarketplaceEnum.COIN_STORE then
        WindowTweener:Create("Main.wndMarketplaceCoin", "Y", nil, 0, 0.3)
      else
        WindowTweener:Create("Main.wndMarketplace", "Y", nil, 0, 0.3)
      end
    end,
    ShowBlocker = function(self)
      Logger:print("marketplace.lua", "showing blocker")
      local swf = GfxCtrl.Find(self.swfNameBlocker)
      if swf then
        swf:Reset()
      end
      boolBlockerVisible = true
      local w = Window.Find(self.windowNameBlocker)
      local swf = GfxCtrl.Find(self.swfNameBlocker)
      local width, height = 0, nil
      local screenWidth, screenHeight = 0, nil
      if w then
        width, height = w:GetSize()
        screenWidth, screenHeight = Window.GetCanvasSize()
        w:SetProperty("Width", screenWidth)
        w:SetProperty("Height", screenHeight)
      end
      if swf then
        swf:SetProperty("Width", screenWidth)
        swf:SetProperty("Height", screenHeight)
      end
      if w then
        w:SetPosition(width / 2 - screenWidth / 2, 0)
        w:Show()
      end
    end,
    HideBlocker = function(self)
      Logger:print("marketplace.lua", "hiding blocker")
      boolBlockerVisible = false
      local w = Window.Find(self.windowNameBlocker)
