    GetMembershipStatus = function(self)
      local swf = GfxCtrl.Find(self.swfName)
      Logger:print("marketplace.lua", "IsMember " .. tostring(Ui.IsMember()))
      swf:Invoke("setMembershipStatus", tostring(Ui.IsMember()))
