    GetCurrencyString = function(self)
      local swf = GfxCtrl.Find(self.swfName)
      Logger:print("marketplace.lua", "CurrencyString " .. Ui.GetString("Currency_PS3"))
      swf:Invoke("setCurrencyString", tostring(Ui.GetString("Currency_PS3")))
    end,
    SetMode = function(self, mode, displayCategory, displayBundleId, isGroup)
      local swf = GfxCtrl.Find(self.swfName)
      if mode ~= nil then
        self.selectedMode = tostring(mode)
      else
        self.selectedMode = MarketplaceEnum.PORTAL
        self:SubmitTracking(MarketplaceTrackingEnum.GAMEDOCK_SC_CLICK)
        if MarketplaceTutorialHandler.boolActive then
          MarketplaceTutorialHandler:GoToStep(MarketplaceTutorialEnum.CLICK_SC)
        end
      end
      swf:Invoke("setCategory", MarketplaceStrings.MARKETPLACE_ITEMS, " ", 1)
      if mode ~= MarketplaceEnum.PORTAL then
        self:BuildNavigation(1)
      end
      if isGroup == "1" then
        MarketplaceViewMode.currentMode = MarketplaceViewMode.GROUP
        MarketplaceGroups.currentMode = displayCategory
      end
      MarketplaceHandler:SetMarketplaceState(self.selectedMode, true, displayCategory, displayBundleId)
    end,
    SubmitTracking = function(self, trackingId, identifier)
      if MarketplacePortalScreen.OnStoreScreenOpen == nil then
        return
      end
      if trackingId == MarketplaceTrackingEnum.MARKETPLACE_OPEN then
        MarketplacePortalScreen.OnStoreScreenOpen(MarketplaceHandler.referrerId, MarketplaceHandler.referrerContext)
      elseif trackingId == MarketplaceTrackingEnum.MARKETPLACE_CLOSE then
        MarketplacePortalScreen.OnStoreScreenClose()
      elseif trackingId == MarketplaceTrackingEnum.MARKETPLACE_CATEGORY_SELECT then
        InGamePurchaseStoreScreen.OnCategorySelect(tonumber(identifier))
      elseif trackingId == MarketplaceTrackingEnum.MARKETPLACE_ITEM_PREVIEW then
        InGamePurchaseStoreScreen.OnStoreItemPreview(1, tonumber(identifier))
      elseif trackingId == MarketplaceTrackingEnum.ADD_CREDIT_CARD_OPEN then
        InGamePurchaseStoreScreen.OnAddCreditCardScreenOpen()
      elseif trackingId == MarketplaceTrackingEnum.FUND_WALLET_OPEN then
        InGamePurchaseStoreScreen.OnFundWalletScreenOpen()
      elseif trackingId == MarketplaceTrackingEnum.PORTAL_OPEN then
        MarketplacePortalScreen.OnMarketplacePortalScreenOpened()
      elseif trackingId == MarketplaceTrackingEnum.CLAIM_OPEN then
        MarketplacePortalScreen.OnClaimScreenOpened()
      elseif trackingId == MarketplaceTrackingEnum.MEMBERSHIP_OPEN then
        MarketplacePortalScreen.OnMembershipScreenOpened()
      elseif trackingId == MarketplaceTrackingEnum.PORTAL_CLOSE then
        MarketplacePortalScreen.OnMarketplacePortalScreenClosed()
      elseif trackingId == MarketplaceTrackingEnum.CLAIM_CLOSE then
        MarketplacePortalScreen.OnClaimScreenClosed()
      elseif trackingId == MarketplaceTrackingEnum.MEMBERSHIP_CLOSE then
        MarketplacePortalScreen.OnMembershipScreenClosed()
      elseif trackingId == MarketplaceTrackingEnum.GAMEDOCK_SC_CLICK then
        MarketplacePortalScreen.OnMarketplaceGamedockOpen()
      elseif trackingId == MarketplaceTrackingEnum.EXIT_SWF then
        MarketplacePortalScreen.OnMarketplaceExit()
      elseif trackingId == MarketplaceTrackingEnum.EDIT_CREDIT_CARD_OPEN then
        InGamePurchaseStoreScreen.OnUpdateCreditCardScreenOpen()
      elseif trackingId == MarketplaceTrackingEnum.DELETE_CREDIT_CARD_OPEN then
        InGamePurchaseStoreScreen.OnDeleteCreditCardScreenOpen()
      end
    end,
    DisplayStoreItemIds = function(self, display)
      local swf = GfxCtrl.Find(self.swfName)
      swf:Invoke("displayStoreItemIds", display)
    end,
    OnResize = function(self)
      self:Hide()
    end,
    ShowPreview = function(self, mode, itemid, tintid, state)
      if MarketplaceHandler.boolIsShown == false then
        return
      end
      Logger:print("marketplace.lua", "ShowPreview: " .. tostring(mode))
      local nav = Window.Find("Main.wndNavigationBar")
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = nav:GetSize()
      if mode == 0 then
        local wnd = Window.Find(self.windowName)
        if wnd then
          wnd:SetProperty("EnableCamera", 0)
        end
        MarketplaceHandler.winFocus = 1
        MarketplaceHandler:StealFocus()
        Logger:print("marketplace.lua", "close preview")
        EquipScreen.ClearPreviewEquipBundle()
        MarketplaceHandler.boolItemPreview = false
        Context:Pop()
      else
        local wnd = Window.Find(self.windowName)
        if wnd then
          wnd:SetProperty("EnableCamera", 1)
        end
        if state == "enter" then
          MarketplaceHandler.winFocus = 0
          MarketplaceHandler:StealFocus()
          Context:Push("MarketplaceItemPreview", function()
            MarketplaceHandler:HideItemPreview()
          end)
        end
        self:SubmitTracking(MarketplaceTrackingEnum.MARKETPLACE_ITEM_PREVIEW, itemid)
        Logger:print("marketplace.lua", "new preview, hide old")
        EquipScreen.ClearPreviewStyleCard()
        local type = EquipScreen.GetBundlePreviewType(1, tonumber(itemid))
        if type == 2 then
          if HUD.inMiniGame then
            HUD:hideMinigame()
            Ui.QuitMiniGame()
          end
          HousingPreviewHandler.bundleId = tonumber(itemid)
          HousingPreviewHandler.catId = self.curCatId
          self:Hide()
          local wnd = Window.Find(MarketplaceHandler.windowName)
          wnd:Hide()
          GameDock_PS3:NavigationExit()
          GameDock_PS3:SetVisibility(0)
        end
        Logger:print("marketplace.lua", "show preview: " .. tostring(itemid) .. ", " .. tostring(tintid) .. " = " .. tostring(res))
        local res = EquipScreen.PreviewEquipBundleById(1, tonumber(itemid), tonumber(tintid))
        Ui.SetCameraOffset2D(-150, 300)
