    SetCategoryTree = function(self)
      local datasource = MarketplaceHandler.dsItemCategories
      local ds = DsTree.Find(datasource)
      local data = ""
      local swf = GfxCtrl.Find(self.swfName)
      self.treeData = ""
      self.treeData = self.treeData .. self:SerializeTreeItem(tostring(MarketplaceCategoryIds.ALL), MarketplaceStrings.ALL_ITEMS, "798", 0, 1, "0")
      self.treeData = self.treeData .. self:SerializeTreeItem(tostring(MarketplaceCategoryIds.NEW_ITEMS), Ui.GetString("newItemsCat"), "30572", 0, 1, "0")
      self:TreeRecursion(ds:GetRootNode())
      self.treeData = self.treeData .. self:SerializeTreeItem(MarketplaceGroups.MEMBERS_ONLY, MarketplaceStrings.MEMBERS_ONLY, "703", "0", 0, 1, "1")
      if AffiliateGroup.currentGroup ~= "-1" then
        local groupds = DsTable.Find(self.dsStoreItemGroups)
        local groupIconId = groupds:GetData(AffiliateGroup.rowIndex, 2)
        local groupText = groupds:GetData(AffiliateGroup.rowIndex, 1)
        self.treeData = self.treeData .. self:SerializeTreeItem(tostring(AffiliateGroup.currentGroup), groupText, groupIconId, "0", 0, 1, "1")
      end
      swf:Invoke("setCategoryTree", self.treeData)
    end,
    TreeRecursion = function(self, node)
      if not node or node:GetChildCount() == 0 then
        return
      end
      for i = 0, node:GetChildCount() - 1 do
        local child = node:GetChildNode(i)
        local catText = child:GetText()
        local catIcon = child:GetBitmapIndex()
        local tint = child:GetData(2)
        local itemCount = child:GetData(1)
        local catID = child:GetData(0)
        self.treeData = self.treeData .. self:SerializeTreeItem(catID, catText, catIcon, tint, itemCount, node:GetData(0))
        self:TreeRecursion(child)
      end
    end,
    SerializeTreeItem = function(self, catID, catText, catIcon, tint, itemCount, parentCatId, isGroup)
      local s = ""
      if isGroup == nil then
        isGroup = "0"
      end
      if tonumber(itemCount) > 0 then
        s = "catId~" .. tostring(catID) .. "|catText~" .. tostring(catText) .. "|catIcon~" .. tostring(catIcon) .. "|tint~" .. tostring(tint) .. "|itemCount~" .. tostring(itemCount) .. "|parentCatId~" .. tostring(parentCatId) .. "|isGroup~" .. isGroup .. "~~"
      end
      return s
    end,
