    GetGroupInfoById = function(self, id)
      local ds = DsTable.Find(self.dsStoreItemGroups)
      local rowCount = ds:GetRowCount()
      local i = 0
      while rowCount > i do
        if ds:GetData(i, 0) == id then
          return {
            id = id,
            name = ds:GetData(i, 1)
          }
        end
        i = i + 1
      end
      return {}
    end,
    SetMarketplaceState = function(self, type, boolWithoutClick, displayCategory, displayBundleId)
      InGamePurchaseStoreScreen.EnableNewStoreItemFilter(0)
      local swf = GfxCtrl.Find(self.swfName)
      type = tostring(type)
      if displayCategory then
        self.displayCategory = displayCategory
      else
        self.displayCategory = "-1"
      end
      if displayBundleId then
        self.displayBundleId = displayBundleId
      else
        self.displayBundleId = "-1"
      end
      if type == MarketplaceEnum.CLAIM then
        swf:Invoke("setMainMode", "claim")
        ClaimHandler:Init()
        MarketplaceViewMode.currentMode = MarketplaceViewMode.NORMAL
        MarketplaceHandler.displayMode = MarketplaceEnum.CLAIM
      elseif type == MarketplaceEnum.COIN_STORE then
        swf:Invoke("setMainMode", "coinstore")
        CoinStoreHandler:Init()
      elseif type == MarketplaceEnum.PORTAL then
        Ui.TriggerFirstTimeEvent("GamedockStore")
        swf:Invoke("setMainMode", "portal")
        PortalHandler:Init()
        local sw, sh = Window.GetCanvasSize()
        local ww, wh = Window.Find(MarketplaceHandler.windowName):GetSize()
      else
        MarketplaceHandler.displayMode = MarketplaceEnum.STORE_SC
        swf:Invoke("setMainMode", "marketplace")
        Logger:print("marketplacelua", "SELECT MARKETPLACE type: " .. type .. " di" .. self.displayCategory)
        if MarketplaceViewMode.currentMode == MarketplaceViewMode.PETPURCHASE then
          swf:Invoke("setCategory", MarketplaceStrings.PET_PURCHASE, type)
          swf:Invoke("selectMarketplaceCategory", type)
        elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.MANNEQUIN then
          swf:Invoke("setCategory", MarketplaceStrings.MANNEQUIN_ITEMS, type)
          swf:Invoke("selectMarketplaceCategory", type)
        elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.CUSTOM_DS then
          swf:Invoke("setCategory", MarketplaceCustomView.title, type)
          swf:Invoke("selectMarketplaceCategory", type)
        elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.GROUP then
          InGamePurchaseStoreScreen.SelectStoreItemGroup(MarketplaceGroups.currentMode)
          local t = self:GetGroupInfoById(MarketplaceGroups.currentMode)
          if t.name then
            swf:Invoke("setCategory", t.name)
            swf:Invoke("selectMarketplaceCategory", type)
            self:RefreshSWF()
          end
        end
        if MarketplaceViewMode.currentMode == MarketplaceViewMode.NORMAL or MarketplaceViewMode.currentMode == MarketplaceViewMode.GROUP then
          Logger:print("marketplacelua", "SELECT MARKETPLACE CATEGORY: " .. tostring(self.displayCategory))
          swf:Invoke("selectMarketplaceCategory", self.displayCategory)
        end
      end
      self.displayCategory = "-1"
    end,
