    ParseDs = function(self, ds)
      local ds = DsTable.Find(ds)
      local res_final = {}
      local res = {}
      if ds then
        local rows = ds:GetRowCount()
        local columns = ds:GetColumnCount()
        local column = 0
        row = 0
        repeat
          while rows > row do
            column = 0
            res = {}
            while columns > column do
              res[column] = ds:GetColumnName(column) .. "~" .. ds:GetData(row, column)
              column = column + 1
            end
            res_final[row] = strjoin("|", res)
            row = row + 1
          end
        until ds:GetData(row, 0) ~= -1
      else
        return false
      end
      local count = 0
      for k, v in pairs(res_final) do
        count = count + 1
      end
      if count == 1 then
        return res_final[0]
      end
      return strjoin("~~", res_final)
    end,
    GetRowIndex = function(self, ds, key, value)
      local ds = DsTable.Find(ds)
      if ds then
        local rows = ds:GetRowCount()
        local columns = ds:GetColumnCount()
        local column = 0
        row = 0
        while rows > row do
          column = 0
          while columns > column do
            local k = ds:GetColumnName(column)
            local v = ds:GetData(row, column)
            if key == k and value == v then
              return row
            end
            column = column + 1
          end
          row = row + 1
        end
      end
      return -1
    end,
    HandleGetItNow = function(self, noItemsEquipped, playerItemEquipped, petSummoned, petItemEquipped, consumableEquipped, tcgItemEquipped)
