        w:SetFocus()
      end
    end,
    GetNodeById = function(self, id)
      local catds = DsTree.Find(MarketplaceHandler.dsItemCategories)
      return self:TreeWalk(catds:GetRootNode(), id)
    end,
    TreeWalk = function(self, node, id)
      if not node then
        return nil
      end
      local catID = node:GetData(0)
      if catID == id then
        return node
      end
      for i = 0, node:GetChildCount() - 1 do
        local child = node:GetChildNode(i)
        local returnVal = self:TreeWalk(child, id)
        if returnVal then
          return returnVal
        end
      end
    end,
