      local fakeNewItemsCat = "Id%%" .. MarketplaceCategoryIds.NEW_ITEMS .. "|Name%%" .. Ui.GetString("newItemsCat") .. "|Description%%" .. Ui.GetString("newItemPortalDesc") .. "|ImageSetId%%6314" .. "|TintValue%%-1" .. "|ShortcutType%%3" .. "|ShortcutValue%%" .. MarketplaceCategoryIds.NEW_ITEMS .. "|ShortcutStoreId%%1~~"
      local data = fakeNewItemsCat
      for i = 0, numRows - 1 do
        if not self:IsCatEmpty(dsTable:GetData(i, PortalCatCol.ShortcutValue)) then
          data = data .. DataSourceMethods:SerializeRow(dsTable, i, "%%", "|") .. "~~"
