    strsplit = function(self, inSplitPattern, myStr)
      local outResults = {}
      local theStart = 1
      local theSplitStart, theSplitEnd = string.find(myStr, inSplitPattern, theStart)
      if theSplitEnd == 0 then
        return outResults
      end
      while theSplitStart do
        table.insert(outResults, string.sub(myStr, theStart, theSplitStart - 1))
        theStart = theSplitEnd + 1
        theSplitStart, theSplitEnd = string.find(myStr, inSplitPattern, theStart)
      end
      table.insert(outResults, string.sub(myStr, theStart))
      return outResults
    end,
    InitializeFilters = function(self)
      Logger:print("marketplace.lua", "init search engine")
      InGamePurchaseStoreScreen.InitializeSearchEngine()
      return true
    end,
    GetFilterData = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local ds = DsTable.Find(MarketplaceHandler.dsFilters)
      local filterTypeCount = ds:GetRowCount()
      local i = 0
      while filterTypeCount > i do
        local colCount = ds:GetColumnCount()
        local filterTypeIndex = ds:GetData(i, 0)
        local filterTypeName = ds:GetData(i, 1)
        if filterTypeName == nil or filterTypeName == "" then
          filterTypeName = "S##18216"
        end
        swf:Invoke("addFilterType", filterTypeIndex, filterTypeName)
        swf:Invoke("addFilterData", filterTypeIndex, "", "-1")
        local filt = ds:GetData(i, 3)
        local j = 1
        local filterSplit = self:strsplit("##", filt)
        while j - 1 < #filterSplit do
          local stringSplit = self:strsplit("::", filterSplit[j])
          if #stringSplit > 2 then
            local idSplit = self:strsplit("%^", stringSplit[1])
            local idValue = "0"
            local nameSplit = self:strsplit("%^", stringSplit[2])
            local nameValue
            if #idSplit > 1 then
              idValue = idSplit[2]
            end
            if #nameSplit > 1 and 1 < #nameSplit[2] then
              nameValue = nameSplit[2]
            elseif filterTypeIndex == "2" then
              if idValue == "3" then
                nameValue = "Male"
              elseif idValue == "4" then
                nameValue = "Female"
              end
            end
            if nameValue ~= nil then
              Logger:print("marketplace.lua", "filtering " .. nameValue .. " " .. idValue)
              swf:Invoke("addFilterData", filterTypeIndex, nameValue, idValue)
            end
          end
          j = j + 1
        end
        i = i + 1
      end
    end,
    GetFilterState = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local dsName = MarketplaceHandler.dsFilterState
      local res = DataSourceMethods:ParseDs(dsName, ItemDisplay.itemDelim, ItemDisplay.propDelim, ItemDisplay.keyvalDelim)
      swf:Invoke("setFilterState", res)
