    RequestDataForPreview = function(self, row, isUpdate)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local str = ""
      local ds = self:GetCurrentViewDatasourceString()
      self.curPreviewRow = row
      if swf then
        str = self:BuildItemStringForPreview(DsTable.Find(ds), row)
        swf:Invoke("setPreviewData", str, isUpdate)
      end
    end,
    GetCurrentViewDatasource = function(self)
      return DsTable.Find(self:GetCurrentViewDatasourceString())
    end,
    GetCurrentViewDatasourceString = function(self)
      local ds
      if MarketplaceViewMode.currentMode == MarketplaceViewMode.PETPURCHASE then
        ds = MarketplaceHandler.dsPetPreview
      elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.ITEMPURCHASE then
        ds = MarketplaceHandler.dsPetPreview
      elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.MANNEQUIN then
        ds = MarketplaceHandler.dsMannequinItems
      elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.CUSTOM_DS then
        ds = MarketplaceCustomView.ds
      elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.GROUP or MarketplaceViewMode.currentMode == MarketplaceViewMode.MEMBERS_ONLY then
        ds = MarketplaceHandler.dsGroupStoreItems
      elseif MarketplaceViewMode.currentMode == MarketplaceViewMode.SEARCH then
        ds = MarketplaceHandler.dsSearchItems
      else
        ds = MarketplaceHandler.dsStoreItems
      end
      return ds
    end,
    RequestData = function(self, offset, count)
      local ds = self:GetCurrentViewDatasource()
      self:Populate(tonumber(offset), tonumber(count), ds, "setData")
    end,
    UpdateData = function(self)
      local ds = self:GetCurrentViewDatasource()
      self:Populate(self.curOffset, self.curRowCount, ds, "updateData")
    end,
    BuildItemString = function(self, ds, row)
      local item = ds:GetColumnName(0) .. ItemDisplay.keyvalDelim .. ds:GetData(row, 0)
      self.hashItemsInView[tostring(ds:GetData(row, 0))] = true
      for i = 1, ds:GetColumnCount() - 1 do
        item = item .. ItemDisplay.propDelim .. ds:GetColumnName(i) .. ItemDisplay.keyvalDelim .. ds:GetData(row, i)
      end
      Ui.SelectItemDefinition(tonumber(ds:GetData(row, 19)))
      local res = DataSourceMethods:ParseDs("BaseClient.ItemDefinitionSelect", "*item*", "*col*", "*prop*")
      item = item .. ItemDisplay.propDelim .. "ItemDef" .. ItemDisplay.keyvalDelim .. res .. ItemDisplay.itemDelim
      return item
    end,
    BuildItemStringForPreview = function(self, ds, row)
      if not row or row < 0 or row > ds:GetRowCount() - 1 then
        return
      end
      local item = ""
      local i
      for i = 0, ds:GetColumnCount() - 1 do
        item = item .. ds:GetColumnName(i) .. ItemDisplay.keyvalDelim .. ds:GetData(row, i)
        if i < ds:GetColumnCount() - 1 then
          item = item .. ItemDisplay.propDelim
        end
      end
      local id = ds:GetData(row, 0)
      local canpreviewitem = EquipScreen.CanPreviewBundle(1, tonumber(id))
      local equipstate = EquipScreen.GetBundleEquippableState(1, tonumber(id))
      local maxitemspurchasable = EquipScreen.GetMaxBundlesPurchasable(1, tonumber(id))
      if canpreviewitem == true then
        canpreviewitem = 1
      else
        canpreviewitem = 0
      end
      Ui.SelectItemDefinition(tonumber(ds:GetData(row, 19)))
      local res = DataSourceMethods:ParseDs("BaseClient.ItemDefinitionSelect", "*item*", "*col*", "*prop*")
      item = item .. ItemDisplay.propDelim .. "CanPreview" .. ItemDisplay.keyvalDelim .. canpreviewitem .. ItemDisplay.propDelim .. "EquippableState" .. ItemDisplay.keyvalDelim .. equipstate .. ItemDisplay.propDelim .. "MaxItemsPurchasable" .. ItemDisplay.keyvalDelim .. maxitemspurchasable .. ItemDisplay.propDelim .. "ItemDef" .. ItemDisplay.keyvalDelim .. res
      return item
    end,
    Populate = function(self, offset, count, ds, funcName)
      self.hashItemsInView = {}
      self.curOffset = offset
      self.curRowCount = count
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      if offset == nil or count == nil or MarketplaceHandler.boolMarketplaceReady == false or MarketplaceHandler.boolCanShowMarketplace == false then
        Logger:print("marketplace.lua", "not ready  ")
        swf:Invoke(funcName, str, -1)
        return
      end
      local str = ""
      if swf then
        if ds then
          local numRows = ds:GetRowCount()
          if numRows == 0 then
            swf:Invoke("setEmptyData", "1")
          else
            swf:Invoke("setEmptyData", "0")
          end
          local numCols = ds:GetColumnCount()
          if numCols <= 0 then
            swf:Invoke(funcName, str, -1)
            return
          end
          if numRows > 0 then
            local offset = math.max(offset, 0)
            local countTo = math.min(offset + count, numRows)
            for i = offset, countTo - 1 do
              str = str .. self:BuildItemString(ds, i)
            end
          end
          swf:Invoke(funcName, str, numRows)
        else
          swf:Invoke(funcName, str, 0)
        end
      end
    end,
