    PurchaseItemPreview = function(self, storeID, itemID, tintId, quantity, coupon, isRental)
      if self.boolInputLocked == false then
        return
      end
      isRental = tonumber(isRental)
      Logger:print("marketplace.lua", "purchase item preview: " .. storeID .. ", " .. itemID .. ", " .. tintId .. ", " .. quantity .. ", " .. isRental)
      InGamePurchaseStoreScreen.CreateNewOrder(0)
      local res = InGamePurchaseStoreScreen.AddStoreItemToOrder(storeID, itemID, quantity, isRental, tintId)
      if res == false then
        local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
        Logger:print("marketplace.lua", "PurchaseItemPreview fail")
        swf:Invoke("setItemPurchaseError", MarketplaceStrings.ERROR_REQUEST_UNAVAILABLE)
        return
      end
      if tostring(coupon) ~= "0" and coupon ~= nil then
        InGamePurchaseStoreScreen.AddCouponCodeToOrder(tostring(coupon))
      end
      self.boolHasPreviewOrder = true
      InGamePurchaseStoreScreen.PreviewOrder()
    end,
    PurchaseItem = function(self, storeID, itemID, tintId, quantity, isRental, name)
      isRental = tonumber(isRental)
      if self.boolInputLocked == false then
        return
      end
      Logger:print("marketplace.lua", "purchasing item: " .. storeID .. ", " .. itemID .. ", " .. tintId .. ", " .. quantity .. ", " .. ", " .. isRental .. tostring(self.boolHasPreviewOrder))
      if self.boolHasPreviewOrder == false then
        InGamePurchaseStoreScreen.CreateNewOrder(0)
        local b = InGamePurchaseStoreScreen.AddStoreItemToOrder(storeID, itemID, quantity, isRental, tintId)
        Logger:print("marketplace.lua", " want to purchase " .. name)
        self.lastPurchasedItemName = name
        if b == false then
          local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
          Logger:print("marketplace.lua", "AddStoreItemToOrder fail")
          swf:Invoke("setItemPurchaseError", MarketplaceStrings.ERROR_REQUEST_UNAVAILABLE)
          return
        end
      end
      local res = InGamePurchaseStoreScreen.PlaceOrder()
      self.lastPurchasedBundleId = itemID
      MarketplaceHandler:LockPages()
      self.boolHasPreviewOrder = false
    end,
    GetItNow = function(self, storeID, itemID, tintID)
      if InGamePurchaseStoreScreen.EquipStoreItem then
        InGamePurchaseStoreScreen.EquipStoreItem(tonumber(storeID), tonumber(itemID), tonumber(tintID))
      end
    end
  }
