    OnOrderPreviewResponse = function(self, result, tax, discount, total, msg)
      Logger:print("marketplace.lua", "OnOrderPreviewResponse: result: " .. result .. ", tax: " .. tax .. ", discount: " .. discount .. ", total: " .. total .. ", msg: " .. msg)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      if result == 1 then
        swf:Invoke("setOrderPreviewInfo", tax, discount, total)
      else
        if msg == "" or msg == nil then
          msg = MarketplaceStrings.ERROR_REQUEST_UNAVAILABLE
        end
        swf:Invoke("setItemPurchaseError", msg)
      end
    end,
    OnOrderResponse = function(self, result, orderID, tax, discount, total, msg)
      Logger:print("marketplace.lua", "on Order Response" .. tostring(result))
      if tonumber(result) == 1 then
        Logger:print("marketplace.lua", "setting item purchase complete on swf")
        Logger:print("marketplace.lua", StoreHandler.lastPurchasedItemName)
        NotificationHandler:ItemReceived(StoreHandler.lastPurchasedItemName .. " " .. MarketplaceStrings.MARKETPLACE_PSN_PURCHASE_SUCCESSFUL)
        local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
        swf:Invoke("showInquiryPanel", orderID)
      else
        Logger:print("marketplace.lua", "failed result")
      end
      LUABroadcaster:dispatchEvent(MarketplaceCallbackHandler, "OnOrderResponse", result, orderID, tax, discount, total, msg)
      if MarketplaceHandler.boolIsShown == false then
        return
      end
      local maxPurchasable = EquipScreen.GetMaxBundlesPurchasable(1, StoreHandler.lastPurchasedBundleId)
      if maxPurchasable >= 0 then
        if result == 1 and not self.inventoryDataUpdated then
          self.queuedItemOrderResult = {
            result = result,
            orderID = orderID,
            tax = tax,
            discount = discount,
            total = total,
            msg = msg
          }
          local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
          swf:Invoke("reselectItem")
          Logger:print("marketplace.lua", "reselectItem on swf to update purchasable state")
          return
        elseif self.queuedItemOrderResult then
          result = self.queuedItemOrderResult.result
          orderID = self.queuedItemOrderResult.orderID
          tax = self.queuedItemOrderResult.tax
          discount = self.queuedItemOrderResult.discount
          total = self.queuedItemOrderResult.total
          msg = self.queuedItemOrderResult.msg
        end
      end
      self.inventoryDataUpdated = nil
      self.queuedItemOrderResult = nil
      MarketplaceHandler:UnlockPages()
      StoreHandler:GetWalletInfo()
      StoreHandler:UpdateData()
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("reselectItem")
      Logger:print("marketplace.lua", "reselectItem to update purchasable state")
    end,
    OnEquipStoreItem = function(self, storeId, storeItemId, noItemsEquipped, playerItemEquipped, petSummoned, petItemEquipped, consumableEquipped, tcgItemEquipped)
      MarketplaceHandler:HandleGetItNow(noItemsEquipped, playerItemEquipped, petSummoned, petItemEquipped, consumableEquipped, tcgItemEquipped)
