  CodeRedemptionHandler = {
    RedeemCode = function(self, keyCode)
      local res = PromotionalScreen.RedeemCode(keyCode)
      if res == true then
        MarketplaceHandler:LockPages()
      end
    end,
    RedeemCodeThroughSWF = function(self, keyCode)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      MarketplaceHandler:Show(MarketplaceEnum.CLAIM)
      swf:Invoke("redeemCodeThroughSWF", keyCode)
    end,
    OnCodeRedemption = function(self, success, msg, shortTerms, longTerms)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      MarketplaceHandler:UnlockPages()
      if success == 1 or success == true then
        NotificationHandler:ItemReceived(MarketplaceStrings.MSG_CODE_SUCCESS)
        if MarketplaceHandler.boolIsShown == false then
          return
        end
        local res = MarketplaceHandler:ParseDs(MarketplaceHandler.dsLastPromotionalAward)
        longTerms = ""
        swf:Invoke("setCodeRedemptionCompleted", res, shortTerms, longTerms)
      else
        if MarketplaceHandler.boolIsShown == false then
          return
        end
        swf:Invoke("setCodeRedemptionError", msg)
      end
    end,
    OnKeyCodeAwardReceived = function(self)
      if MarketplaceHandler.boolIsShown == false then
        return
      end
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      res = MarketplaceHandler:ParseDs(MarketplaceHandler.dsLastPromotionalAward)
      swf:Invoke("setCodeRedemptionCompleted", res)
    end
  }
  ClaimHandler = {
    Init = function(self)
      self:RequestDataExternal()
      MarketplaceViewMode.currentMode = MarketplaceViewMode.NORMAL
    end,
    StartClaim = function(self)
      return ClaimScreen:StartClaim()
    end,
    FinishClaim = function(self)
      return ClaimScreen:FinishClaim()
    end,
    RefreshClaimItems = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("refreshClaim")
    end,
    ClaimItem = function(self, id, qty)
      local res = true
      ClaimHandler.StartClaim()
      res = ClaimScreen.AddClaimItem(tonumber(id), tonumber(qty))
      if res == false then
        local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
        swf:Invoke("setClaimError", MarketplaceStrings.ERROR_CLAIM_GENERIC)
        return
      else
        MarketplaceHandler:LockPages()
      end
      ClaimHandler.FinishClaim()
    end,
    OnClaimItems = function(self, success)
      MarketplaceHandler:UnlockPages()
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      if success == 1 or success == true then
        NotificationHandler:ItemReceived(MarketplaceStrings.MSG_CLAIM_SUCCESS)
        if MarketplaceHandler.boolIsShown == false then
          return
        end
        swf:Invoke("setClaimComplete")
      else
        if MarketplaceHandler.boolIsShown == false then
          return
        end
        swf:Invoke("setClaimError", MarketplaceStrings.ERROR_CLAIM_GENERIC)
      end
    end,
    OnClaimItemContents = function(self, claimItemId)
    end,
    GetItNow = function(self)
      ClaimScreen.GetLastClaimItemNow(0)
    end,
    OnEquipClaimItem = function(self, requestId, noItemsEquipped, playerItemEquipped, petSummoned, petItemEquipped, consumableEquipped, tcgItemEquipped)
      MarketplaceHandler:HandleGetItNow(noItemsEquipped, playerItemEquipped, petSummoned, petItemEquipped, consumableEquipped, tcgItemEquipped)
    end,
    RequestData = function(self, offset, count)
      local ds = DsTable.Find(MarketplaceHandler.dsClaimItems)
      self:Populate(tonumber(offset), tonumber(count), ds)
    end,
    RequestDataExternal = function(self)
      self:RequestData(0, 4)
    end,
    BuildItemString = function(self, ds, row)
      local item = ds:GetData(row, 0)
      for i = 1, ds:GetColumnCount() - 1 do
        item = item .. ItemDisplay.propDelim .. ds:GetData(row, i)
      end
      item = item .. ItemDisplay.itemDelim
      return item
    end,
    Populate = function(self, offset, count, ds)
      if offset == nil or count == nil then
        return
      end
      local rowCount = 0
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local str = ""
      if swf then
        if ds then
          local numRows = ds:GetRowCount()
          if numRows > 0 then
            local offset = math.max(offset, 0)
            local countTo = math.min(offset + count, numRows)
            for i = offset, countTo - 1 do
              str = str .. self:BuildItemString(ds, i)
            end
          end
          swf:Invoke("setClaimData", str, numRows)
          rowCount = numRows
        else
          swf:Invoke("setClaimData", str, 0)
        end
      end
      if WelcomeHandler.notShown ~= true then
        WelcomeHandler:SetNumClaimItems(rowCount)
      end
    end
  }
  HousingPreviewHandler = {
    wndName = "Main.wndHousingPreview",
    swfName = "Main.wndHousingPreview.swfHousingPreview",
    catId = nil,
    bundleId = nil,
    inInstance = false,
    displayMarketplace = true,
    isBuyingFromHousingPreview = false,
    SetIsInInstance = function(self, inInstance, isPreview)
      if not self.catId or not self.bundleId then
        return
      end
      if inInstance and isPreview then
        NavigationHandler:Hide()
        GameDock_PS3:ExitNavigation()
        GameDock_PS3:SetVisibility(0)
      elseif not inInstance and self.inInstance then
        self:Hide()
      end
    end,
    Show = function(self)
      local wnd = Window.Find(self.wndName)
      local swf = GfxCtrl.Find(self.swfName)
      local w, h = Window.GetCanvasSize()
      self.inInstance = true
      self.displayMarketplace = true
      LUABroadcaster:addListener(MarketplaceCallbackHandler, "OnOrderResponse", self.OnOrderResponse, self)
      LUABroadcaster:addListener(MarketplaceCallbackHandler, "OnWalletInfo", self.OnWalletInfo, self)
      wnd:Show()
      swf:Show()
      wnd:SetProperty("Width", w)
      wnd:SetProperty("Height", h)
      wnd:SetProperty("X", -250)
      wnd:SetProperty("Y", 180)
      WindowTweener:Create("Main.wndHousingPreview", "X", 0, 0, 0.04)
    end,
    Hide = function(self)
      local wnd = Window.Find(self.wndName)
      self.inInstance = false
      LUABroadcaster:removeListener(MarketplaceCallbackHandler, "OnOrderResponse", self.OnOrderResponse, self)
      LUABroadcaster:removeListener(MarketplaceCallbackHandler, "OnWalletInfo", self.OnWalletInfo, self)
      WindowTweener:Create("Main.wndHousingPreview", "X", -300, -300, 0.3, function()
        Window.Find(HousingPreviewHandler.wndName):Hide()
        GfxCtrl.Find(HousingPreviewHandler.swfName):Unload()
        if HousingPreviewHandler.displayMarketplace then
          MarketplaceHandler:Show(MarketplaceEnum.STORE_SC, tostring(HousingPreviewHandler.catId), tostring(HousingPreviewHandler.bundleId))
        end
      end)
    end,
    SetData = function(self)
      local res = DataSourceMethods:GetRowWhere(StoreHandler:GetCurrentViewDatasource(), "ItemId", tostring(self.bundleId))
      local swf = GfxCtrl.Find(self.swfName)
      swf:Invoke("setData", res.serialized)
      StoreHandler:GetWalletInfo()
    end,
    TweenForBuy = function(self)
      local wnd = Window.Find(self.wndName)
      local ww, wh = wnd:GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create("Main.wndHousingPreview", "X", nil, (sw - 220) / 2, 0.15)
    end,
    TweenDocked = function(self)
      Ui.SetKeyboardEnabled(1)
      WindowTweener:Create("Main.wndHousingPreview", "X", 0, 0, 0.15)
    end,
    BuyItem = function(self, bundleId, tintId)
      self.isBuyingFromHousingPreview = true
      InGamePurchaseStoreScreen.CreateNewOrder(0)
      InGamePurchaseStoreScreen.AddStoreItemToOrder(1, bundleId, 1, 0, tintId)
      local res = InGamePurchaseStoreScreen.PlaceOrder()
      local swf = self.swfName
      if not res then
        NotificationHandler:ErrorMessage(MarketplaceStrings.MARKETPLACE_LABEL_HOUSING_BUY_ERROR)
        swf:Invoke("setPurchaseComplete", 0)
        self.isBuyingFromHousingPreview = false
        self:TweenDocked()
      else
        self:TweenForBuy()
      end
    end,
    OnOrderResponse = function(self, result, orderID, tax, discount, total, msg)
      if not self.isBuyingFromHousingPreview then
        return
      end
      local swf = GfxCtrl.Find(self.swfName)
      self:TweenDocked()
      if result == 1 then
        NotificationHandler:AlertMessage(MarketplaceStrings.MARKETPLACE_LABEL_HOUSING_BUY_SUCCESSFUL)
        HousingPreviewHandler.displayMarketplace = false
      else
        NotificationHandler:ErrorMessage(MarketplaceStrings.MARKETPLACE_LABEL_HOUSING_BUY_ERROR)
      end
      swf:Invoke("setPurchaseComplete", result)
      self.isBuyingFromHousingPreview = false
      StoreHandler:GetWalletInfo()
    end,
    OnWalletInfo = function(self, success, accountActive, accountBalance)
      local swf = GfxCtrl.Find(self.swfName)
      swf:Invoke("setWalletBalance", accountBalance)
    end,
    setUseItNow = function(self, itemId)
      StoreHandler:GetItNow(1, itemId)
    end,
    ASPrint = function(self, s)
      print("AS Print From Housing Preview: " .. s)
    end
  }
