  CreditCardManager = {
    sourceId = nil,
    OnConfirmationResponse = nil,
    OnDeleteConfirmationResponse = function(self, response, password)
      if response == 1 then
        if password == "undefined" then
          password = ""
        end
        local result = InGamePurchaseStoreScreen.DeleteCreditCard(tonumber(self.sourceId), password)
        if not result then
          local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
          swf:Invoke("setDeleteCreditCardError", "Card deletion failed. Please check your password if required and try again.")
        else
          MarketplaceHandler:LockPages()
        end
      else
      end
      ConfirmationWindow:Disconnect(self)
      self:Reset()
    end,
    Reset = function(self)
      self.sourceId = nil
      self.OnConfirmationResponse = nil
    end,
    AddCreditCard = function(self, typeid, number, month, year, cvv, name, address1, address2, city, zip, state, country, password, issuer, startdatemonth, startdateyear)
      if MarketplaceHandler:IsNaN(password) then
        password = ""
      end
      if MarketplaceHandler:IsNaN(address2) then
        address2 = ""
      end
      if MarketplaceHandler:IsNaN(issuer) then
        issuer = ""
      end
      if MarketplaceHandler:IsNaN(startdatemonth) then
        startdatemonth = 0
      end
      if MarketplaceHandler:IsNaN(cvv) then
        cvv = ""
      end
      if MarketplaceHandler:IsNaN(startdateyear) then
        startdateyear = 0
      else
        startdateyear = tonumber(startdateyear) + 2000
      end
      if MarketplaceHandler:IsNaN(year) then
        year = 0
      else
        year = year + 2000
      end
      local locale = ""
      local res = InGamePurchaseStoreScreen.AddCreditCard(tonumber(typeid), tostring(number), tonumber(month), tonumber(year), tostring(cvv), name, address1, address2, city, zip, state, country, locale, tostring(issuer), tonumber(startdatemonth), tonumber(startdateyear), password)
      if tostring(res) == "false" then
        local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
        swf:Invoke("setAddCreditCardError", MarketplaceStrings.ERROR_INVALID_CC_CREDENTIALS)
      else
        MarketplaceHandler:LockPages()
      end
    end,
    EditCreditCard = function(self, sourceId, ccNum, expM, expY, cvv, name, address1, address2, city, postalCode, stateOrProvince, country, locale, issuer, startdatemonth, startdateyear, password)
      if MarketplaceHandler:IsNaN(password) then
        password = ""
      end
      if MarketplaceHandler:IsNaN(address2) then
        address2 = ""
      end
      if MarketplaceHandler:IsNaN(issuer) then
        issuer = ""
      end
      if MarketplaceHandler:IsNaN(startdatemonth) then
        startdatemonth = 0
      end
      if MarketplaceHandler:IsNaN(cvv) then
        cvv = ""
      end
      if MarketplaceHandler:IsNaN(startdateyear) then
        startdateyear = 0
      else
        startdateyear = tonumber(startdateyear) + 2000
      end
      if MarketplaceHandler:IsNaN(year) then
        year = 0
      else
        year = year + 2000
      end
      local locale = ""
      local result = InGamePurchaseStoreScreen.UpdateCreditCard(tonumber(sourceId), tostring(ccNum), tonumber(expM), tonumber(expY), tostring(cvv), name, address1, address2, city, postalCode, state, country, locale, tostring(issuer), tonumber(startdatemonth), tonumber(startdateyear), password)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke(callback, "edit", tostring(result))
    end,
    DeleteCreditCard = function(self, sourceId)
      self.sourceId = sourceId
      self.OnConfirmationResponse = self.OnDeleteConfirmationResponse
      ConfirmationWindow:Connect(self)
      ConfirmationWindow:Show("Are you sure you want to remove your card from the account?")
      ConfirmationWindow:SetPasswordRequired(InGamePurchaseStoreScreen.IsParentalPasswordEnabled())
    end
  }
  LUABroadcaster:addListener(Housing, "SetIsInInstance", HousingPreviewHandler.SetIsInInstance, HousingPreviewHandler)
  Client.HandlerPromotions = "CodeRedemptionHandler"
  Client.HandlerInGamePurchase = "MarketplaceCallbackHandler"
