  Client.HandlerClaimSystem = "ClaimHandler"
end)()
;(function()
  ErrorWindow = {
    errorType = -1,
    onComplete = nil,
    ShowErrorMessage = function(self, msgText, labelText, iconId, errorType, callback)
      NonModalContext:AddContext(self)
      local m = GfxCtrl.Find(Ui.GetName("Main.wndError.swfError"))
      m:Invoke("setErrorText", msgText, labelText, iconId)
      self.errorType = errorType
      self.onComplete = callback
      if self.errorType == "popupDisconnected" then
        HUD:hideMain()
        HUD:hideMinigame()
      end
      self:OnResize()
      Ui.ObscureScene(0.7, 1000)
    end,
    HideErrorMessage = function(self)
      NonModalContext:RemoveContext(self)
      Ui.ObscureScene(0, 1000)
      if self.errorType == "popupDisconnected" then
        Ui.Quit()
      end
      if self.onComplete then
        self.onComplete()
      end
      local w = Window.Find(Ui.GetName("Main.wndError"))
      w:Hide()
    end,
    OnResize = function(self)
      local w = Window.Find(Ui.GetName("Main.wndError"))
      local width, height = w:GetSize()
      local sw, sh = Window.GetCanvasSize()
      w:Show()
      w:SetPosition((sw - width) / 2, (sh - height) / 2)
      if self.errorType == "popupDisconnected" then
        Tutorial:GobblerShow()
      end
    end
  }
  function Main_wndError_swfError_OnUserEvent(a, b)
    if a == "exitScreen" then
      ErrorWindow:HideErrorMessage()
    end
  end
end)()
