    Animate = function(self)
      local wnd = Window.Find("Main.wndPowerHourButton")
      wnd:Show()
      local sw, sh = Window.GetCanvasSize()
      n_wndWidth, n_wndHeight = wnd:GetSize()
      wnd:SetPosition((sw - n_wndWidth) / 2, (sh - n_wndHeight) / 2)
      WindowTweener:Create("Main.wndPowerHourButton", "Width", nil, n_wndWidth * 2, 0.1)
      WindowTweener:Create("Main.wndPowerHourButton", "Height", nil, n_wndHeight * 2, 0.1)
