        WindowTweener:Create("Main.wndPowerHourButton", "Height", nil, n_wndHeight, 0.3)
        WindowTweener:Create("Main.wndPowerHourButton", "X", nil, 1010, 0.4)
        WindowTweener:Create("Main.wndPowerHourButton", "Y", nil, 373, 0.4, function()
          PowerHourButton:SetUpActivityPortalButton()
        end)
      end
    end,
    SetUpActivityPortalButton = function(self)
