        return
      end
      if Fishing.underwater == true then
        return
      end
      if self.miniGameHUDinit == false then
        self.miniGameHUDinit = true
      end
      local sw, sh = Window.GetCanvasSize()
      HudWindowManager:HideSidePanels()
      MiniMap:Show()
      MiniGameHandler:CloseStatusScreen()
      SocialHandler:Hide()
      GroupHandler.EncounterTimerActive = false
      StarCounter:Show()
      if MiniGameStatusHandler.currentMiniGameType ~= 12 then
        GroupHandler:Show(1)
      end
      if FlashTimer.isShown then
        FlashTimer:Show()
      end
      Logger:print("hud.lua", "SHOWING OBJECTIVE WINDOW NORMAL")
      if MiniGameStatusHandler.currentMiniGameType ~= 12 then
        ObjectiveWindow:Show()
      end
      Target:Show()
      Window.SetFocus()
      if not Tutorial.inTutorial and not PetTutorial.enabled then
        GameDock:SetState(GameDock.MINIGAME_STATE)
      end
      self.miniGameHUDVisible = true
      PowerHourButton:Hide()
    end,
    showMinigame = function(self, showStarCounter, showStatusIcon, showActionBar, startupInCombat)
      if Housing.isInInstance then
        return
      end
      InteractionPrompt:Enable()
      if ActivityPortal.isShown then
        QuestHandler:DismissAll()
      end
      npxTutorial:FtesCombatSplash01()
      Logger:print("hud.lua", "hud:showMinigame() minigametype(" .. tostring(MiniGameStatusHandler.currentMiniGameType) .. ") isInHub(" .. tostring(Ui.IsInHub()) .. ")")
      if MiniGameStatusHandler.isMoving then
        return
      end
      if PetTutorial.enabled == true or VehicleGarage.isActive then
        return
      end
      if not Context:IsCurrent("MiniGameHandlerOpenStatusScreen") and not Context:IsCurrent("MiniGameStatusHandlerHide") then
        Context:CallQuit()
      end
      Ui.SetMovementEnabled(1)
      Ui.SetKeyboardEnabled(1)
      if Tutorial.inTutorial or PetTutorial.enabled then
        Tutorial:ClearAllTutorialElements()
      end
      if self.miniGameHUDinit == false then
        GroupHandler:SetKO()
        MiniGameStatusHandler:Populate()
        if MiniGameStatusHandler.currentMiniGameType == 10 or MiniGameStatusHandler.currentMiniGameType == 11 or MiniGameStatusHandler.currentMiniGameType == 12 or MiniGameStatusHandler.currentMiniGameType == 13 then
          self.miniGameHUDinit = true
        else
          FlashTimer.enabled = true
          GameDock:InitDockInMinigame()
          ChatLog:Show()
        end
      end
      if (MiniGameStatusHandler.currentMiniGameType == 4 or MiniGameStatusHandler.currentMiniGameType == -1) and Ui.IsInHub() then
        HUD:showMain()
        return
      end
      if MiniGameStatusHandler.currentMiniGameType == 21 then
        HUD:showMain()
        MiniMap:Show()
        Fishing:Show()
        return
      end
      while Context:Includes("ShowMain") and not Context:IsCurrent("ShowMain") and 1 < Client.ContextDepth do
        Context:CallQuit()
      end
      while (Context:Includes("QuestStart") or Context:Includes("DialogHandler") or Context:Includes("QuestEnd")) and not Context:IsCurrent("ShowMain") do
        Context:CallQuit()
      end
      HUD:hideMain()
      GroupHandler:SetJobSwitchOnOrOff(false)
      Lobby:Hide(true)
      if MiniGameStatusHandler.currentMiniGameType == 4 then
        Logger:print("hud.lua", "hud.lua showminigame camera restore")
        PetsHandler:CancelPetTrick()
      end
      self.inMiniGame = true
      if self.mMiniGameFlash then
        self:ShowMiniGameFlash()
      else
        if startupInCombat == true then
          GroupHandler.Mode = 1
          GroupHandler:ModeSwitch(1)
        end
        self:ShowMiniGameNormal()
      end
      PowerHourButton:Hide()
    end,
    ClearContextAndPreservePanes = function(self)
      Logger:print("hud.lua", "ClearContextAndPreservePanes start")
      local oldPanesUp = MiniGameStatusHandler.panesUp
      if self.inMiniGame == true then
        if not Context:Includes("ShowMinigame") then
          MiniGameStatusHandler:HidePanes()
          BrowserHandler:Hide()
          Context:Pop()
        end
      else
        Context:Clear()
      end
      if Context:Includes("Options") then
        Options:Hide(true)
      end
      Context:Clear(true)
      if self.inMiniGame == true then
        if oldPanesUp == true then
          if not Context:Includes("MiniGameHandlerOpenStatusScreenHUD") then
          end
        elseif not Context:Includes("ShowMinigame") and not PetTutorial.enabled and not Tutorial.inTutorial then
          Context:Push("ShowMinigame", function()
            Context:Pop()
            HUD:showMinigame()
          end, nil, 1)
        end
      else
        Context:Push("ShowMain", function()
          Context:Pop()
          HUD:showMain()
        end, nil, 1)
      end
      Logger:print("hud.lua", "ClearContextAndPreservePanes end")
    end,
    wndLoadingProgress = Ui.GetName("Main.wndLoadingProgress"),
    swfLoadingProgress = Ui.GetName("Main.wndLoadingProgress.swfLoadingProgress"),
    UpdateLoadingIndicator = function(self, count)
      local loadingProgress = Window.Find(self.wndLoadingProgress)
      local loadingProgressSwf = GfxCtrl.Find(self.swfLoadingProgress)
      if tonumber(count) == 0 then
        loadingProgress:Hide()
      else
        loadingProgress:Show()
        loadingProgress:SetPosition(330, 50)
        loadingProgressSwf:Invoke("setDownloadQueue", count)
      end
    end,
    Update = function(self)
      self:UpdateIndicators()
    end,
    swfSceneText = Ui.GetName("Main.wndSceneText.swfSceneText"),
    UpdateIndicators = function(self)
      if self.IndicatorsEnabled == "false" or self.isInStartingZone or Ui.ShouldDrawDirectionIndicators() == false then
        return
      end
      local ds = DsTable.Find("BaseClient.ScreenDirectionIndicatorData")
      local ds2 = DsTable.Find("BaseClient.ObjectiveTarget")
      local swf = GfxCtrl.Find(self.swfSceneText)
      if ds then
        local numRows = ds:GetRowCount() - 1
        local i = 0
        while numRows > i do
          local d6 = ds:GetData(i, 6)
          if i < 5 and d6 ~= self.selectedQuestIndicator then
            local d4 = math.floor(ds:GetData(i, 4))
            if d4 < 150 and d4 > 8 then
              swf:Invoke("ShowDirectionalIndicator", d6, ds:GetData(i, 0), math.floor(ds:GetData(i, 3) + 90), d4, ds:GetData(i, 5), 0)
            end
          end
          i = i + 1
        end
      end
      if ds2 and tonumber(ds2:GetData(0, 0)) == 1 then
        local x1, y1, z1 = Ui.GetPlayerLoc()
        local x2 = ds2:GetData(i, 3)
        local z2 = ds2:GetData(i, 4)
        local distance = math.sqrt((x2 - x1) ^ 2 + (z2 - z1) ^ 2)
        if distance > 10 then
          swf:Invoke("ShowDirectionalIndicator", ds2:GetData(0, 1), ds2:GetData(i, 2), math.floor(ds2:GetData(i, 7) + 90), math.floor(distance), 2, 1)
        end
      end
    end,
    GetIndicatorEnabled = function(self)
      return self.IndicatorsEnabled
    end,
    EnableIndicators = function(self)
      UpdateList.HUDUpdate = HUD
      self.IndicatorsEnabled = "true"
    end,
    DisableIndicators = function(self)
      UpdateList.HUDUpdate = nil
      self.IndicatorsEnabled = "false"
    end,
    InterceptMouseWheel = function(self, wheel)
      ChatLog:InterceptMouseWheel(wheel / 64)
      return tonumber(self.MouseWheelConsumed) == 1
    end,
    ShowHudButtons = function(self, should)
      if should == nil then
        should = true
      end
      if should then
        if Ui.GetUserOptionsValue("VideoCapture", "ShowVideoCaptureUI", "0") == "1" then
          VideoHandler:ShowVideoCaptureHud()
        end
      else
        VideoHandler:HideVideoCaptureHud()
      end
    end,
    SetIsInStartingZone = function(self, is)
      if self.inMiniGame == false and Client.ContextDepth == 0 and not Ui.IsInLobby() then
        local isNormal = 1
        if is then
          isNormal = 0
        end
        self:SetShowNormalState(isNormal)
      end
      if self.isInStartingZone then
        Ui.StartClientTimer("StartingZoneTimerStart")
        Ui.SetUserOptionsValue("fteOptions", "downloadComplete", 0)
        Ui.SetUserOptionsValue("fteOptions", "newPlayerFTE", 0)
        Ui.SetUserOptionsValue("fteOptions", "fiveMinuteTimer", 0)
      end
    end,
    SetShowNormalState = function(self, is)
      self:hideMain()
      self.isInStartingZone = tonumber(is) == 0
      self:showMain()
      GameDock:SetMountButtonEnabledState()
      if self.nagsNotShown then
        self.nagsNotShown = false
        OnShowWelcomeScreen(1, -1, SCAvailable.startingScWalletBalance)
      end
    end,
    PowerHourStart = function(self)
      PowerHourButton:DetermineShow()
    end,
    PowerHourStop = function(self)
      PowerHourButton:Hide()
    end,
    FiveMinutesInZone = function(self)
      Ui.SetUserOptionsValue("fteOptions", "fiveMinuteTimer", 1)
      HUD:EverythingComplete()
    end,
    StartingZoneLoaded = function(self)
      if FirstTimeEvent.ShowDownloadCompleteMessage == true then
        FirstTimeEvent.ShowDownloadCompleteMessage = nil
        Ui.SetUserOptionsValue("fteOptions", "downloadComplete", 1)
        Ui.TriggerFirstTimeEvent("FtesDownloadComplete")
      else
        FirstTimeEvent.DownloadCompleteButFirstPanelNOTClosedYet = true
      end
      HUD:EverythingComplete()
    end,
    EverythingComplete = function(self)
      local fiveMinuteTimer = Ui.GetUserOptionsValue("fteOptions", "fiveMinuteTimer", 0)
      local downloadComplete = Ui.GetUserOptionsValue("fteOptions", "downloadComplete", 0)
      local newPlayerFTE = Ui.GetUserOptionsValue("fteOptions", "newPlayerFTE", 0)
      if tonumber(fiveMinuteTimer) == 1 and tonumber(downloadComplete) == 1 and tonumber(newPlayerFTE) == 1 then
        Ui.StartClientTimer("JoinOverworldReminder")
      end
    end,
    LeaveStartingZone = function(self)
      Ui.SetUserOptionsValue("fteOptions", "downloadComplete", 0)
      Ui.SetUserOptionsValue("fteOptions", "fiveMinuteTimer", 0)
      Ui.SetUserOptionsValue("fteOptions", "newPlayerFTE", 0)
      Ui.TeleportToSafePoint()
      HUD:SetShowNormalState(1)
      Tutorial:ClearAllTutorialElements()
      local groupSwf = GfxCtrl.Find(GroupHandler.m_movieName)
      groupSwf:Unload()
      local minimapSwf = GfxCtrl.Find(MiniMap.miniMap)
      minimapSwf:Unload()
      local questHelperSwf = GfxCtrl.Find(QuestHelper.swfQuestHelper)
      questHelperSwf:Unload()
      local atlasSwf = GfxCtrl.Find(Atlas.swfAtlas)
      atlasSwf:Unload()
      local radial = GfxCtrl.Find(radialMenu.MovieName)
      radial:Unload()
      local marketplace = GfxCtrl.Find(MarketplaceHandler.swfName)
      marketplace:Unload()
      local miniGameIndicator = GfxCtrl.Find(ObjectiveWindow.movieName)
      miniGameIndicator:Unload()
      local lobbyleftNormal = GfxCtrl.Find(Lobby.swfLeftNormal)
      lobbyleftNormal:Unload()
      local lobbyleftSoccer = GfxCtrl.Find(Lobby.swfLeftSoccer)
      lobbyleftSoccer:Unload()
      local lobbyBottom = GfxCtrl.Find(Lobby.swfBottom)
      lobbyBottom:Unload()
      local lobbyTop = GfxCtrl.Find(Lobby.swfTop)
      lobbyTop:Unload()
      local quickMatch = GfxCtrl.Find(QuickMatch.swf)
      quickMatch:Unload()
    end,
    ShowCoinWheel = function(self)
      if self.mainShown then
        Ui.SetMovementEnabled(0)
        MiniGameFlashC.StartWheel()
      else
        self.needToShowCoinWheel = true
      end
    end
  }
  HUD:LoadSounds()
  function OnShowMemberExpired(self)
    MembershipRem:ShowExpiredMode()
  end
end)()
