  NpcMerchantHandler = {
    debug = false,
    datasources = {
      "BaseClient.MerchantBuyInventoryData",
      "BaseClient.MerchantSellInventoryData"
    },
    wndNpcMerchant = Ui.GetName("Main.wndNpcMerchant"),
    swfNpcMerchant = Ui.GetName("Main.wndNpcMerchant.swfNpcMerchant"),
    merchantDatasource = "BaseClient.MerchantSellInventoryData",
    inventoryDatasource = "BaseClient.MerchantBuyInventoryData",
    mode = 1,
    m_Offset = 0,
