      end)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      swf:Invoke("setIconType", HUD.supressIconTint)
      swf:Invoke("SetModeBuy", Ui.GetUserOptionsValue("MerchantWindowOptions", "LastSelectedViewMode_Buy", "1"))
      self:RegisterDatasources()
      self:OnResize()
