      HUD:PlaySound("ShowWindow")
      self.screenActive = true
      if self.dialogAdded ~= true then
        swf:Invoke("setDialogResponse", 18, 453, Ui.GetString(1106776), 1)
        swf:Invoke("setDialogResponse", 18, 302, Ui.GetString(8075), 2)
        self.dialogAdded = true
      end
      MerchantSell.Populate()
    end,
    SelectItem = function(self, itemid, itemType)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      local boolCanPreview = EquipScreen.CanPreviewItem(tonumber(itemid))
      if itemType == 12 then
        boolCanPreview = true
      end
      if boolCanPreview then
        swf:Invoke("setPreview", "1")
      else
        swf:Invoke("setPreview", "0")
      end
    end,
    SetPreviewItem = function(self, itemid, itemType)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      local boolCanPreview = EquipScreen.CanPreviewItem(tonumber(itemid))
      if itemType == 12 then
        boolCanPreview = true
      end
      if boolCanPreview then
        if itemType ~= 12 then
          local tintId = 0
          EquipScreen.PreviewEquipItemById(tonumber(itemid), tintId)
        else
          EquipScreen.PreviewStyleCard(itemid)
        end
        swf:Invoke("setPreview", "1")
      else
        if itemType ~= 12 then
          EquipScreen.ClearPreviewEquipItem()
        else
          EquipScreen.ClearPreviewStyleCard()
        end
        swf:Invoke("setPreview", "0")
      end
      Ui.SetDialogCameraOffset2D(390, -150)
    end,
    ShowPreview = function(self)
      MerchantSell.Close()
      Ui.CameraLookAtSelf("HEAD")
      Ui.SetDialogCameraOffset2D(350, -150)
      Context:Push("MerchantItemPreview", function()
        NpcMerchantHandler:HidePreview()
      end)
      self.boolItemPreview = true
    end,
    HidePreview = function(self)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      swf:Invoke("closePreview")
      Ui.CameraRestore()
      EquipScreen.ClearPreviewEquipItem()
      EquipScreen.ClearPreviewStyleCard()
      MerchantSell.Populate()
      Context:Pop()
      self.boolItemPreview = false
    end,
    RegisterDatasources = function(self)
      for i, v in pairs(self.datasources) do
        local ds = DsTable.Find(v)
        if ds then
          ds:EnableScriptEvents()
        end
      end
    end,
    UnRegisterDatasources = function(self)
      for i, v in pairs(self.datasources) do
        local ds = DsTable.Find(v)
        if ds then
          ds:DisableScriptEvents()
        end
      end
    end,
    OnResize = function(self)
      local wnd = Window.Find(self.wndNpcMerchant)
      local wndW, wndH = wnd:GetSize()
      local sw, sh = Window.GetCanvasSize()
      wnd:SetPosition(20, sh / 2 - wndH / 2)
      wnd:Show()
    end,
    Hide = function(self)
      if self.boolItemPreview then
        self:HidePreview()
      end
      Context:Pop()
      local sw, sh = Window.GetCanvasSize()
      local wnd = Window.Find(self.wndNpcMerchant)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      HUD:PlaySound("HideWindow")
      wnd:Hide()
      swf:Unload()
      HUD:showMain()
      NavigationHandler:Hide()
      self.screenActive = false
      self.dialogAdded = false
      self.mode = 1
      MerchantSell.Close()
      self.boolItemPreview = false
    end,
    SetPlayerCoin = function(self, value, playsound)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      swf:Invoke("SetPlayerCoinCount", value)
    end,
    ModeSwitch = function(self)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      if self.mode == 0 then
        self.mode = 1
        swf:Invoke("SetModeBuy", Ui.GetUserOptionsValue("MerchantWindowOptions", "LastSelectedViewMode_Buy", "1"))
        NavigationHandler:Hide()
      elseif self.mode == 1 then
        self.mode = 0
        self:BuildNavigation()
        swf:Invoke("SetModeSell", Ui.GetUserOptionsValue("MerchantWindowOptions", "LastSelectedViewMode_Sell", "1"))
      end
    end,
    NavigationOnUserEvent = function(self, a, b)
      if a == "SwitchTo" then
        NpcMerchantHandler:SetInventoryCategory(b)
      elseif a == "exitScreen" then
        NpcMerchantHandler:ModeSwitch()
      end
    end,
    OnNavigationShown = function(self)
      local LastSelectedCategory = Ui.GetUserOptionsValue("MerchantWindowOptions", "LastSelectedCategory", "8")
      NavigationHandler:SelectButton(tostring(LastSelectedCategory), 1)
    end,
    BuildNavigation = function(self)
      NavigationHandler:Connect(self)
      local nav = Window.Find("Main.wndNavigationBar")
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = nav:GetSize()
      local wnd = Window.Find(self.wndNpcMerchant)
      NavigationHandler:Show(-85, sh / 2 - wh / 2 - 70)
      local datasource = "BaseClient.InventoryCategoriesData"
      local ds = DsTree.Find(datasource)
      if ds then
        local root = ds:GetRootNode()
        for i = 0, root:GetChildCount() - 1 do
          local child = root:GetChildNode(i)
          local catText = child:GetText()
          local catIcon = child:GetBitmapIndex()
          local catID = child:GetData(0)
          NavigationHandler:AddCategoryButton(catIcon, catText, catID)
          local firstChildCatID
          local dontAdd = false
          for c = 0, child:GetChildCount() - 1 do
            local subChild = child:GetChildNode(c)
            local catText = subChild:GetText()
            local catIcon = subChild:GetBitmapIndex()
            local catID = subChild:GetData(0)
            if catID == firstChildCatID then
              dontAdd = true
            end
            if firstChildCatID == nil then
              firstChildCatID = catID
            end
            if dontAdd == false then
              NavigationHandler:AddSubCategoryButton(i, catIcon, catText, catID)
            end
          end
        end
      end
    end,
    SetInventoryCategory = function(self, cat)
      Logger:print("npcmerchant.lua", "SetInventoryCategory: " .. tostring(cat))
      self.changedCat = true
      MerchantBuy.SelectInventoryCategory(cat)
      Ui.SetUserOptionsValue("MerchantWindowOptions", "LastSelectedCategory", tostring(cat))
      Ui.SaveUserOptions()
    end,
    RefreshDisplayList = function()
      if NpcMerchantHandler.screenActive == true then
        local swf = GfxCtrl.Find(NpcMerchantHandler.swfNpcMerchant)
        swf:Invoke("refresh", tostring(NpcMerchantHandler.changedCat))
        NpcMerchantHandler.changedCat = nil
      end
    end,
    RequestData = function(self, offset, count)
      local ds
      if self.mode == 1 then
        ds = self.datasources[2]
      elseif self.mode == 0 then
        ds = self.datasources[1]
      end
      self:Populate(tonumber(offset), tonumber(count), ds)
    end,
    Populate = function(self, offset, count, ds)
      if offset == nil or count == nil then
        return
      end
      local tblMap = {}
      if ds == self.datasources[2] then
        tblMap = MerchantItemColumns.Buy
      elseif ds == self.datasources[1] then
        tblMap = MerchantItemColumns.Sell
      end
      ds = DsTable.Find(ds)
      local swf = GfxCtrl.Find(self.swfNpcMerchant)
      local str = ""
      if swf then
        if ds then
          local numRows = ds:GetRowCount()
          if numRows > 0 then
            local offset = math.max(offset, 0)
            local countTo = math.min(offset + count, numRows)
            for i = offset, countTo - 1 do
              str = str .. self:BuildResult(ds, i, tblMap)
            end
          end
          swf:Invoke("setData", str, numRows)
        else
          swf:Invoke("setData", str, 0)
        end
      end
    end,
    BuildResult = function(self, ds, row, tblMap)
      local message = ""
      for i = 1, #tblMap do
        if i == 1 then
          message = ds:GetData(row, tblMap[i])
        else
          message = message .. "^" .. ds:GetData(row, tblMap[i])
        end
      end
      return message .. ";"
    end,
    UpdateItemCounts = function(self)
      local m = GfxCtrl.Find(self.swfNpcMerchant)
      local datasource = "BaseClient.MerchantSellInventoryData"
      local ds = DsTable.Find(datasource)
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          m:Invoke("SetItemQuantity", ds:GetData(i, 0), ds:GetData(i, 5))
        end
      end
    end,
    OnUserEvent = function(a, b, c, d, e, f)
      if a == "dialogResponse" then
        if b == "1" then
          NpcMerchantHandler:ModeSwitch()
        elseif b == "2" then
          NpcMerchantHandler:Hide()
        end
      elseif a == "purchaseItem" then
        local tintId = 0
        MerchantSell.BuyFromMerchant(b, c, tintId)
      elseif a == "sellItem" then
        MerchantBuy.SellToMerchant(b, c)
      elseif a == "onMembersOnly" then
        NpcMerchantHandler:Hide()
        MembershipHandler:Show()
      elseif a == "requestData" then
        NpcMerchantHandler:RequestData(b, c)
      elseif a == "playSound" or a == "PlaySound" then
        HUD:PlaySound(b)
      elseif a == "changeViewMode" then
        if NpcMerchantHandler.mode == 1 then
          Ui.SetUserOptionsValue("MerchantWindowOptions", "LastSelectedViewMode_Buy", b)
          Logger:print("npcmerchant.lua", a .. " ( " .. b .. " ) " .. NpcMerchantHandler.mode)
        elseif NpcMerchantHandler.mode == 0 then
          Ui.SetUserOptionsValue("MerchantWindowOptions", "LastSelectedViewMode_Sell", b)
          Logger:print("npcmerchant.lua", a .. " ( " .. b .. " ) " .. NpcMerchantHandler.mode)
        end
      elseif a == "showItemPreview" then
        NpcMerchantHandler:ShowPreview()
      elseif a == "hideItemPreview" then
        NpcMerchantHandler:HidePreview()
      elseif a == "setPreviewItem" then
        NpcMerchantHandler:print(a)
        NpcMerchantHandler:SetPreviewItem(b, tonumber(c))
      elseif a == "selectItem" then
        NpcMerchantHandler:SelectItem(b, tonumber(c))
      elseif a == "AS_Print" then
        NpcMerchantHandler:print(b)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[Merchant]\t" .. message)
      end
    end
  }
  Main_wndNpcMerchant_swfNpcMerchant_OnUserEvent = NpcMerchantHandler.OnUserEvent
  Main_wndNpcMerchant_swfNpcMerchant_OnFocus = NpcMerchantHandler.OnFocus
  BaseClient_MerchantBuyInventoryData_OnDataUpdate = NpcMerchantHandler.RefreshDisplayList
  BaseClient_MerchantSellInventoryData_OnDataUpdate = NpcMerchantHandler.RefreshDisplayList
end)()
