    SetPetEquipmentColumnNames = function(self, tbl)
      local count = #tbl
      local columnsString = tbl[1]
      for i = 2, count do
        columnsString = columnsString .. "^" .. tbl[i]
      end
      return columnsString
    end,
    Populate = function(self, swfName)
      local swf = GfxCtrl.Find(Ui.GetName(swfName))
      local ds = DsTable.Find(DataSources[DS_PET_LIST])
      swf:Invoke("SetMode", 2)
      swf:Invoke("SetWindowTitle", Ui.GetString(6761), Ui.GetString("UI_Browser_PetSubtext"), Ui.GetString("UI_Browser_ClickSwitchPets"))
      local numRows = ds:GetRowCount()
      local numCols = ds:GetColumnCount()
      if ds and numRows > 0 then
        for i = 0, numRows - 1 do
          local name = tostring(ds:GetData(i, 0))
          local gender = tonumber(ds:GetData(i, 1))
          local iconID = tonumber(ds:GetData(i, 9))
          local foodNeed = tonumber(ds:GetData(i, 3))
          local playNeed = tonumber(ds:GetData(i, 4))
          local groomNeed = tonumber(ds:GetData(i, 5))
          local mood = tonumber(ds:GetData(i, 6))
          local id = tonumber(ds:GetData(i, 7))
          local membersOnly = tonumber(ds:GetData(i, 8))
          local nameTitle = ""
          local nameBase = ""
          local tintValue = tonumber(ds:GetData(i, 10))
          local vanityPet = tonumber(ds:GetData(i, 11))
          if PetTutorial.enabled == true and Pet.GetActivePetId() == id or PetTutorial.enabled ~= true then
            Logger:print("pets.lua", "ADD PET:  Name:" .. name .. " Gender: " .. gender .. " IconID: " .. iconID .. " FoodNeed: " .. foodNeed .. " PlayNeed: " .. playNeed .. " GroomNeed: " .. groomNeed .. " Mood: " .. mood .. " ID: " .. id .. " MemberOnly: " .. membersOnly .. " NameTitle: " .. nameTitle .. " NameBase: " .. nameBase .. " TintValue: " .. tintValue .. " VanityPet: " .. vanityPet)
            swf:Invoke("AddPet", name, gender, iconID, foodNeed, playNeed, groomNeed, mood, id, membersOnly, nameTitle, nameBase, tintValue, vanityPet)
          end
        end
      end
      if not PetTutorial.enabled then
        local str = Ui.GetString("PetBrowserGetMorePets")
        swf:Invoke("AddPet", str, 0, 798, 0, 0, 0, 0, -1, 0)
      end
      local pID = Pet.GetActivePetId()
      if pID > 0 then
        swf:Invoke("ActivateItem", pID)
      else
        swf:Invoke("SelectItem", 1)
      end
      if PetsFte.queuedUpdate then
        PetsFte:FirstPetFTECheck()
      end
    end,
    ShowBrowser = function(self, update)
      BrowserHandler:Show(PetsHandler, Ui.GetString(6761), Ui.GetString("UI_Browser_PetSubtext"), Ui.GetString("UI_Browser_ClickSwitchPets"), 0, update)
      BrowserHandler:Connect(self)
      BrowserHandler:HideCloseButton()
      BrowserHandler:ExpandBrowser()
      local pID = Pet.GetActivePetId()
      if pID <= 0 then
        for i = 1, 6 do
          NavigationHandler:DisableNavigationButton(i, 1)
        end
      end
      if not update then
      end
      GameDock:SetState(GameDock.DISABLED_STATE)
    end,
