    BrowserOnUserEvent = function(self, a, b)
      local pID = Pet.GetActivePetId()
      Logger:print("pets.lua", a)
      if a == "SelectPet" then
        Logger:print("pets.lua", "Selecting Pet " .. b .. " pet out-> " .. pID)
        HUD:PlaySound("Selected")
        if PetTutorial.enabled == true then
          PetTutorial:Show(PetTutorial.tutorials[PetTutorial.BASIC_TUTORIAL], 3)
          return
        end
        if b == "-1" then
          PetsHandler:HideBrowser()
          PetsHandler:ModeSwitch(0)
          PetsHandler:Hide()
          MarketplaceHandler:Show(MarketplaceEnum.STORE_SC, 59)
        elseif pID == tonumber(b) then
          Pet.Dismiss()
          PetsHandler:HideBrowser()
          PetsHandler:ModeSwitch(0)
          PetsHandler:Hide()
        else
          if b ~= "-1" then
            Pet.Summon(b)
            PetsHandler:HideBrowser()
            PetsHandler:ModeSwitch(0)
            if PetsHandler.FirstPetFTECheckBrowser == true then
              Ui.TriggerFirstTimeEvent("FtesPet0002")
              PetsHandler.FirstPetFTECheckBrowser = nil
            end
            PetsHandler:Hide()
          else
            self.hideToMarketPlace = true
          end
          PetsHandler:ModeSwitch(0)
        end
      elseif a == "DismissPet" then
        Pet.Dismiss()
        PetsHandler:HideBrowser()
        PetsHandler:ModeSwitch(0)
        PetsHandler:Hide()
      elseif a == "SelectMarketplace" then
        PetsHandler:HideBrowser()
        PetsHandler:ModeSwitch(0)
        PetsHandler:Hide()
        MembershipHandler:Show()
      elseif a == "ExpandedBrowser" then
        PetsHandler:ShowBrowserExpand()
      elseif a == "CompressBrowser" then
        PetsHandler:HideBrowser()
        PetsHandler:ModeSwitch(0)
      elseif a == "CloseBrowser" then
        PetsHandler:HideBrowser()
        PetsHandler:ModeSwitch(0)
      elseif a == "AS_Print" then
        self:print(tostring(a) .. ", " .. tostring(b))
      end
    end,
    Show = function(self, button)
      HUD:hideMain()
      BrowserHandler.windowName = "Pets"
      if PetTutorial.enabled ~= true then
        Context:Push("PetsHandler", function()
          PetsHandler:Hide()
        end)
      end
      NonModalContext:AddContext(self)
      self.screenActive = true
      self.visible = true
      EquipmentHandler:Connect(self)
      self:FocusPet()
      self:RegisterDatasources()
      self:OnResize()
      HUD:PlaySound("ShowWindow")
      GameDock:SetState(GameDock.DISABLED_STATE)
      DataSourceConnection:Connect(DataSources[DS_PET_LIST], PetsHandler, "PetListUpdate")
      if DsTable.Find(DataSources[DS_PET_LIST]):GetRowCount() > 0 then
        Ui.TriggerFirstTimeEvent("FtesPet0001")
        PetsHandler.FirstPetFTECheckBrowser = true
      end
    end,
    Hide = function(self)
      HUD:PlaySound("HideWindow")
      if PetTutorial.enabled ~= true then
        Context:Pop()
      end
      NonModalContext:RemoveContext(self)
      Pet.CameraRestore()
      local sw, sh = Window.GetCanvasSize()
      self.screenActive = false
      self.visible = false
      PetsHandler:HideAboutPet()
      PetsHandler:HideProgress()
      PetsHandler:HideBrowser()
      EquipmentHandler:Hide()
      NavigationHandler:Hide()
      EquipmentHandler:Disconnect(self)
      NavigationHandler:Disconnect(self)
      PetsHandler:Hide2()
      if PetTutorial.enabled ~= true then
        HUD:showMain()
      end
      DataSourceConnection:Disconnect(DataSources[DS_PET_LIST], PetsHandler)
    end,
    Hide2 = function(self)
      local w1 = Window.Find(self.wndPetDetails)
      w1:Hide()
      if PetTutorial.enabled == true or Pet.GetActivePetId() > 0 then
      end
      PetNameBar:Hide()
    end,
