      self:BuildNavigation()
      local pID = Pet.GetActivePetId()
      if pID <= 0 then
        for i = 1, 6 do
          NavigationHandler:DisableNavigationButton(i, 1)
        end
      end
      if PetTutorial.enabled ~= true then
      end
    end,
    BuildNavigation = function(self)
      NavigationHandler:Disconnect(self)
      NavigationHandler:Connect(self)
      NavigationHandler:Show(nil, nil, -40)
      NavigationHandler:AddButton(652, Ui.GetString(self.NavigationLabels[self.MODE_ABOUT]), self.MODE_ABOUT)
      NavigationHandler:AddButton(654, Ui.GetString(self.NavigationLabels[self.MODE_GROOM]), self.MODE_GROOM)
      NavigationHandler:AddButton(655, Ui.GetString(self.NavigationLabels[self.MODE_FEED]), self.MODE_FEED)
      NavigationHandler:AddButton(635, Ui.GetString(self.NavigationLabels[self.MODE_EQUIP]), self.MODE_EQUIP)
      NavigationHandler:AddButton(28871, Ui.GetString(self.NavigationLabels[self.MODE_DISMISS]), self.MODE_DISMISS)
      NavigationHandler:AddButton(398, Ui.GetString(self.NavigationLabels[self.MODE_BROWSER]), self.MODE_BROWSER)
      if self:IsVanityPet() == 1 then
        NavigationHandler:DisableNavigationButton(self.MODE_GROOM, 1)
        NavigationHandler:DisableNavigationButton(self.MODE_FEED, 1)
        NavigationHandler:DisableNavigationButton(self.MODE_EQUIP, 1)
      end
    end,
    IsVanityPet = function()
      if Pet.GetActivePetId() > 0 then
        return tonumber(PetsHandler:GetPetTableByID(Pet.GetActivePetId()).vanityPet)
      end
      return 0
    end,
    OnNavigationShown = function(self)
      NavigationHandler:HighlightButton(1, 0)
      NavigationHandler:HighlightButton(7, 1)
    end,
    RegisterDatasources = function(self)
      local ds = DsTable.Find(DataSources[DS_PET_EQUIPPED_ITEMS])
      if ds then
        ds:EnableScriptEvents()
      end
    end,
    PlaySound = function(self, soundName)
      if not HUD.mMiniGameFlash then
        Ui.PlaySound(self.SoundsList[soundName], 1, 1)
      end
    end,
