    ModeSwitch = function(self, mode)
      local CategoryLabels = self.GetCategoryLabels()
      local sw, sh = Window.GetCanvasSize()
      self:HideBrowser()
      EquipmentHandler:Hide()
      ToolTipHandler:HideToolTip()
      self:HideAboutPet()
      if PetTutorial.PetTutorialOnlyNav == true then
        return
      end
      if mode == 0 then
        NavigationHandler:EnableBar()
      elseif mode ~= self.MODE_DISMISS then
        NavigationHandler:DisableBar()
      end
      HUD:PlaySound("MenuFlip")
      self.activeMode = mode
      Pet.ModeSwitch(self.activeMode)
      if FirstTimeEventHandler.activePane == true then
        Tutorial:HideArrow()
        BrowserHandler:HideTutorialArrow()
        TutorialDialog:Hide()
      end
      if mode == self.MODE_ABOUT then
        Logger:print("pets.lua", "Setting About Mode")
        self:ShowAboutPet()
        self:PopulatePetTricks()
        PetsHandler:HideProgress()
        if PetsHandler:IsVanityPet() == 1 then
          Ui.TriggerFirstTimeEvent("FtesPet0003andaHalf")
          return
        elseif FirstTimeEvent.ForTricks == true then
          Ui.TriggerFirstTimeEvent("FtesPet0005")
        end
      elseif mode == self.MODE_GROOM then
        self:HideAboutPet()
        EquipmentHandler:GroomMode()
        EquipmentHandler:Show(self.PetUtitlitiesSlotMap, 1, 4, 1, "BaseClient.PetInventory.", DataSources[DS_PET_EQUIPPED_UTILITY_DATA], self:SetPetEquipmentColumnNames(self.PetEquipmentColumnsTable), false, Ui.GetUserOptionsValue("PetWindowOptions", "LastSelectedViewMode_" .. tostring(Ui.GetString(self.NavigationLabels[self.activeMode])), "1"), CategoryLabels)
        local wnd = Window.Find(Ui.GetName(EquipmentHandler.wndName))
        PetsHandler:HideProgress()
        Ui.TriggerFirstTimeEvent("FtesPet0004")
      elseif mode == self.MODE_FEED then
        self:HideAboutPet()
        EquipmentHandler:FeedMode()
        EquipmentHandler:Show(self.PetUtitlitiesSlotMap, 5, 3, 5, "BaseClient.PetInventory.", DataSources[DS_PET_EQUIPPED_UTILITY_DATA], self:SetPetEquipmentColumnNames(self.PetEquipmentColumnsTable), false, Ui.GetUserOptionsValue("PetWindowOptions", "LastSelectedViewMode_" .. tostring(Ui.GetString(self.NavigationLabels[self.activeMode])), "1"), CategoryLabels)
        local wnd = Window.Find(Ui.GetName(EquipmentHandler.wndName))
        PetsHandler:HideProgress()
        Ui.TriggerFirstTimeEvent("FtesPet0004")
      elseif mode == self.MODE_PLAY then
        self:HideAboutPet()
        EquipmentHandler:Show(self.PetInventorySlotMap, 8, 4, 8, "BaseClient.PetTricks.", DataSources[DS_PET_EQUIPPED_TRICKS_DATA], self:SetPetEquipmentColumnNames(self.PetEquipmentColumnsTable), false, Ui.GetUserOptionsValue("PetWindowOptions", "LastSelectedViewMode_" .. tostring(Ui.GetString(self.NavigationLabels[self.activeMode])), "1"), CategoryLabels)
        local wnd = Window.Find(Ui.GetName(EquipmentHandler.wndName))
        PetsHandler:HideProgress()
      elseif mode == self.MODE_EQUIP then
        self:HideAboutPet()
        EquipmentHandler:Show(self.PetInventorySlotMap, 1, 7, 1, "BaseClient.PetInventory.", DataSources[DS_PET_EQUIPPED_WEARABLES_DATA], self:SetPetEquipmentColumnNames(self.PetEquipmentColumnsTable), false, Ui.GetUserOptionsValue("PetWindowOptions", "LastSelectedViewMode_" .. tostring(Ui.GetString(self.NavigationLabels[self.activeMode])), "1"), CategoryLabels)
        local wnd = Window.Find(Ui.GetName(EquipmentHandler.wndName))
        PetsHandler:HideProgress()
      elseif mode == self.MODE_DISMISS then
        if 0 < Pet.GetActivePetId() then
          Pet.Dismiss()
          PetsHandler:ModeSwitch(0)
          PetsHandler:Hide()
        end
      elseif mode == self.MODE_BROWSER then
        PetsHandler:ShowBrowser()
      end
    end,
    EquipmentPaneOnUserEvent = function(self, a, b, c, d, e)
      if FirstTimeEventHandler.activePane == true then
        Tutorial:HideArrow()
      end
      if a == "requestData" then
        EquipmentHandler:RequestData(b, c)
      elseif a == "changeSelectedCategory" then
        self:print("original catID before mod: " .. b)
        if (self.activeMode == 2 or self.activeMode == 3) and tonumber(b) > 100 then
          b = tonumber(b) - 199
        end
        self:print("changeSelectedCategory: " .. tostring(b))
        EquipmentHandler.selectedSlot = tonumber(b)
      elseif a == "equipItem" and PetTutorial.enabled ~= true then
        if self.activeMode == 2 or self.activeMode == 3 then
          if tonumber(c) > 100 then
            c = tonumber(c) - 199
          end
          self:print("Equip Pet Utility: " .. tostring(c) .. ", " .. tostring(b))
          Ui.ClearItemNewFlag(b)
          Pet.EquipUtility(b, tonumber(c))
        elseif self.activeMode == 4 then
          Pet.SetFavoriteTrick(tonumber(c) + 1, b)
        elseif self.activeMode == 5 then
          self:print("Equip Pet Item: " .. tostring(c) .. ", " .. tostring(b))
          Ui.ClearItemNewFlag(b)
          Pet.EquipItem(b, c)
        end
      elseif a == "equipItem" and PetTutorial.enabled == true then
        PetTutorial:PetEquipItem(a, b, c)
      elseif a == "actionButton" then
        local action = 0
        if self.activeMode == 2 then
          action = Pet.StartGroom()
          if action then
            PetsHandler.isGrooming = true
            PetTutorial:StartGrooming()
          end
        elseif self.activeMode == 3 then
          action = Pet.StartFeed()
          if action then
            PetTutorial:StartFeeding()
          end
        end
      elseif a == "changeViewMode" then
        if b == "undefined" then
          return
        end
        EquipmentHandler.currentViewMode = b
        Ui.SetUserOptionsValue("PetWindowOptions", "LastSelectedViewMode_" .. tostring(Ui.GetString(self.NavigationLabels[self.activeMode])), b)
      elseif a == "PlaySound" then
        HUD:PlaySound(b)
      else
        if a == "CloseWindowPS3" then
          EquipmentHandler:Hide()
          PetsHandler:ModeSwitch(0)
        else
        end
      end
    end,
    EquipmentPaneOnRequestData = function(self, offset, count)
      local dsString
      if EquipmentHandler.selectedSlot then
        if self.activeMode == 4 then
          dsString = tostring(EquipmentHandler.activeDs) .. tostring(EquipmentHandler.selectedSlotMap[tonumber(EquipmentHandler.selectedSlotMapID)])
        elseif self.activeMode == 5 then
          dsString = tostring(EquipmentHandler.activeDs) .. tostring(EquipmentHandler.selectedSlotMap[tonumber(EquipmentHandler.selectedSlot)])
        else
          dsString = tostring(EquipmentHandler.activeDs) .. tostring(EquipmentHandler.selectedSlotMap[tonumber(EquipmentHandler.selectedSlot)])
        end
        if dsString == nil then
          return
        end
        local ds = DsTable.Find(dsString)
        if ds then
          EquipmentHandler:Populate(offset, count, ds)
        end
      end
    end,
    EquipmentPaneOnPopulate = function(self, offset, count, ds)
      local slotID = EquipmentHandler.selectedSlot
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          count = tonumber(count)
          local offset = math.max(offset, 0)
          if offset == 0 then
            if self.activeMode == 2 or self.activeMode == 3 then
              self:print(slotID .. " :> " .. self.PetUtitlitiesSlotsMap[slotID])
              slotID = self.PetUtitlitiesSlotsMap[slotID]
            end
            str = EquipmentHandler.BuildNoneItem(slotID)
            count = count - 1
          else
            offset = offset - 1
          end
          numRows = numRows + 1
          local countTo = math.min(offset + count, ds:GetRowCount())
          if PetTutorial.enabled ~= true then
            for i = offset, countTo - 1 do
              if self.activeMode == 4 then
                str = str .. self.BuildTrickItemString(ds, i, slotID)
              else
                str = str .. EquipmentHandler.BuildItemString(ds, i)
              end
            end
          else
            for i = 0, ds:GetRowCount() - 1 do
              local itemIDs = {
                30566,
                30567,
                30568,
                30569,
                30570,
                30571,
                30572
              }
              for iIDs = 1, #itemIDs do
                local itemID = tonumber(ds:GetData(i, 23))
                if itemIDs[iIDs] == itemID then
                  str = str .. EquipmentHandler.BuildItemString(ds, i)
                  numRows = 1
                  break
                end
              end
            end
          end
        else
          str = EquipmentHandler.BuildNoneItem(slotID)
        end
        EquipmentHandler:PopulateWindow(str, numRows)
      else
        str = EquipmentHandler.BuildNoneItem(slotID)
        EquipmentHandler:PopulateWindow(str, 1)
      end
    end,
    EquipmentPaneOnSetCurrentEquip = function(self)
      EquipmentHandler:PetMode(self.activeMode)
      if EquipmentHandler.selectedEquippedDatasource == nil then
        return
      end
      local ds = DsTable.Find(EquipmentHandler.selectedEquippedDatasource)
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          if self.activeMode ~= 4 and self.activeMode ~= 5 then
            if EquipmentHandler.selectedSlotMapID ~= nil then
              local countTo = EquipmentHandler.selectedSlotMapID + EquipmentHandler.selectedSlotMapCount - 1
              local offset = EquipmentHandler.selectedSlotMapID
              for i = offset, math.min(countTo, numRows - 1) do
                if self.PetUtitlitiesSlotsMap[i] ~= 202 and self.PetUtitlitiesSlotsMap[i] ~= 201 and self.PetUtitlitiesSlotsMap[i] ~= 206 then
                  if ds:GetData(i, 0) ~= "-1" then
                    str = str .. EquipmentHandler.BuildItemString(ds, i)
                  else
                    self:print("-->" .. self.PetUtitlitiesSlotsMap[i])
                    str = str .. EquipmentHandler.BuildNoneItem(self.PetUtitlitiesSlotsMap[i])
                  end
                end
              end
              EquipmentHandler:PopulateWindowCategories(str, numRows)
            end
          elseif self.activeMode == 5 then
            if EquipmentHandler.selectedSlotMapID ~= nil then
              local countTo = EquipmentHandler.selectedSlotMapID + EquipmentHandler.selectedSlotMapCount - 1
              local offset = EquipmentHandler.selectedSlotMapID
              for i = offset, math.min(countTo, numRows - 1) do
                if i ~= 2 and i ~= 4 and i ~= 7 then
                  if ds:GetData(i, 0) ~= "-1" then
                    str = str .. EquipmentHandler.BuildItemString(ds, i)
                  else
                    str = str .. EquipmentHandler.BuildNoneItem(i)
                  end
                end
              end
              EquipmentHandler:PopulateWindowCategories(str, numRows)
            end
          else
            for i = 0, numRows - 1 do
              if ds:GetData(i, 1) ~= "-1" then
                str = str .. self.BuildTrickItemString(ds, i, i)
              else
                str = str .. EquipmentHandler.BuildNoneItem(i)
              end
            end
            EquipmentHandler:PopulateWindowCategories(str, numRows)
          end
        end
      end
    end,
    BuildTrickItemString = function(ds, row, slotID)
      local item = ds:GetData(row, 0)
      for i = 1, ds:GetColumnCount() - 1 do
        if i == 8 then
          item = item .. "^" .. slotID
        elseif i == 6 then
          item = item .. "^"
        else
          local value = ds:GetData(row, i)
          if value == "" then
            value = "0"
          end
          item = item .. "^" .. value
        end
      end
      item = item .. ";"
      return item
    end,
    BeginInteraction = function(self)
      self:ModeSwitch(0)
    end,
    NavigationOnUserEvent = function(self, a, b)
      if a == "SwitchTo" then
        PetTutorial:PetsUiModeSwitch()
        PetsHandler:ModeSwitch(tonumber(b))
      elseif a == "exitScreen" then
        Logger:print("pets.lua", "exit screen received")
        if self.activeMode > 0 then
          PetsHandler:ModeSwitch(0)
        else
          PetsHandler:Hide()
          GameDock_PS3:SetVisibility(1)
        end
      end
    end,
    ShowAboutPet = function(self)
      self.ABOUT_PET_SHOWN = true
      if self:IsVanityPet() ~= 1 then
        PetDetails:Show()
      end
      PetNameBar:Show()
      local swf = GfxCtrl.Find(self.swfPetDetails)
      swf:Invoke("ShowTricks")
    end,
    HideAboutPet = function(self)
      self.ABOUT_PET_SHOWN = false
      if self:IsVanityPet() ~= 1 then
        PetDetails:Hide()
      end
      PetNameBar:Hide()
    end,
    PopulatePetTricks = function(self)
      self:GetTrickData("_level0.trickBar_mc.setData")
    end,
    GetTrickData = function(self, callback)
      local message = DataSourceMethods:ParseDs(DataSources[DS_PET_TRICKS])
      local swf = GfxCtrl.Find(self.swfPetDetails)
