    end,
    GetPetTableByID = function(self, petID)
      if petID <= 0 then
        return 0
      end
      local ds = DsTable.Find(DataSources[DS_PET_LIST])
      local petIndex
      local numRows = ds:GetRowCount()
      local numCols = ds:GetColumnCount()
      for i = 0, numRows - 1 do
        local id = tonumber(ds:GetData(i, 7))
        if id == tonumber(petID) then
          petIndex = i
          break
        end
      end
      local petTbl = {}
      petTbl.name = ds:GetData(petIndex, 0)
      petTbl.sex = ds:GetData(petIndex, 1)
      petTbl.icon = ds:GetData(petIndex, 9)
      petTbl.food = ds:GetData(petIndex, 3)
      petTbl.play = ds:GetData(petIndex, 4)
      petTbl.groom = ds:GetData(petIndex, 5)
      petTbl.mood = ds:GetData(petIndex, 6)
      petTbl.id = ds:GetData(petIndex, 7)
      petTbl.tintValue = ds:GetData(petIndex, 10)
      petTbl.vanityPet = ds:GetData(petIndex, 11)
      if PetsFte.queuedUpdate then
        PetsFte:FirstPetFTECheck()
      end
      return petTbl
    end,
    PetListUpdate = function(self)
      if self.ABOUT_PET_SHOWN then
        self:PetStatusUpdated()
      end
    end,
    PetDataUpdated = function(self, forced)
      if self.despawningPetID ~= nil and self.despawningPetID > 0 then
        self.despawningPetID = nil
      end
      if forced == nil then
        BrowserHandler:Update(self)
      end
      if 0 < Pet.GetActivePetId() then
        PetNameBar:Populate()
        PetDetails:Populate()
      end
    end,
    PetStatusUpdated = function(self)
      if Pet.GetActivePetId() >= 0 then
        PetNameBar:Populate()
        PetDetails:Populate()
      end
    end,
    PetTookAction = function(self, evtID, evtString)
    end,
