      for i = 1, 6 do
        NavigationHandler:DisableNavigationButton(i, 0)
      end
    end,
    SetProgress = function(self, progress)
      local pb = GfxCtrl.Find(self.swfPetProgress)
      pb:Invoke("setProgress", progress)
    end,
    ShowProgress = function(self, mode)
      local w = Window.Find(self.wndPetProgress)
      local width, height = w:GetSize()
      local sw, sh = Window.GetCanvasSize()
      local pb = GfxCtrl.Find(self.swfPetProgress)
      pb:Reset()
      pb:Invoke("setMode", mode)
      w:SetPosition(sw / 2 - width / 2, sh + 100)
