      WindowTweener:Create("Main.wndFRProgressBar", "Y", nil, sh - 300, 0.3)
    end,
    HideProgress = function(self)
      local w = Window.Find(self.wndPetProgress)
      local width, height = w:GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create("Main.wndFRProgressBar", "Y", nil, sh + 100, 0.3, function()
        local w = Window.Find(self.wndPetProgress)
        w:Hide()
      end)
    end,
    CheckUtilitiesLocked = function(self)
      if not Pet.IsBusy() or self.utilitiesLocked == false then
      else
      end
    end,
    UnlockUtilities = function(self)
      if self.isGrooming == true then
        self.isGrooming = false
      end
      self.utilitiesLocked = false
      PetTutorial:UtilitiesUnlocked()
      if PetTutorial.enabled == true then
        return
      end
      NavigationHandler:DisableNavigationButton(self.MODE_ABOUT, 0)
      if self:IsVanityPet() ~= 1 then
        NavigationHandler:DisableNavigationButton(self.MODE_GROOM, 0)
        NavigationHandler:DisableNavigationButton(self.MODE_FEED, 0)
        NavigationHandler:DisableNavigationButton(self.MODE_EQUIP, 0)
      end
      NavigationHandler:DisableNavigationButton(self.MODE_DISMISS, 0)
      NavigationHandler:DisableNavigationButton(self.MODE_BROWSER, 0)
      if self.GameDockState then
        GameDock:SetState(self.GameDockState)
        self.GameDockState = nil
      end
    end,
    LockUtilities = function(self)
      local sw, sh = Window.GetCanvasSize()
      self.utilitiesLocked = true
      if self.screenActive then
        PetsHandler:Hide()
      end
      Tutorial:HideArrow()
      NavigationHandler:DisableNavigationButton(self.MODE_ABOUT, 1)
      if self:IsVanityPet() ~= 1 then
        NavigationHandler:DisableNavigationButton(self.MODE_GROOM, 1)
        NavigationHandler:DisableNavigationButton(self.MODE_FEED, 1)
        NavigationHandler:DisableNavigationButton(self.MODE_EQUIP, 1)
      end
      NavigationHandler:DisableNavigationButton(self.MODE_DISMISS, 1)
      NavigationHandler:DisableNavigationButton(self.MODE_BROWSER, 1)
      self.GameDockState = GameDock:GetState()
      GameDock:SetState(GameDock.DISABLED_STATE)
    end,
    UnlockTricks = function(self)
    end,
    RaiseNeed = function(self, need)
      if Pet.GetActivePetId() > 0 then
        Pet.RaiseNeed(tonumber(need))
        PetsHandler:ShowProgress(need)
        local petData = PetsHandler:GetPetTableByID(Pet.GetActivePetId())
        if tonumber(need) == 1 then
          PetsHandler:SetProgress(tonumber(petData.food))
        elseif tonumber(need) == 2 then
          PetsHandler:SetProgress(petData.groom)
        elseif tonumber(need) == 3 then
          PetsHandler:SetProgress(petData.play)
        end
      end
    end,
    FocusPet = function(self)
      Pet.CameraAtPet("HEAD")
    end,
    PetCanDraw = function(self)
      if self.screenActive then
        PetsHandler:FocusPet()
        PetsHandler.ShowCount = 0
        UpdateList.PetShowUpdate = self
      elseif PetController.visible == false and not WelcomeHandler.isShown then
      elseif WelcomeHandler.isShown then
        PetsHandler.welcomePetSummons = nil
      end
    end,
    Update = function(self)
      PetsHandler.ShowCount = PetsHandler.ShowCount + 1
      if PetsHandler.ShowCount > 10 then
        UpdateList.PetShowUpdate = nil
        PetsHandler:FocusPet()
      end
    end,
    ActionStarted = function()
    end,
    initializeExpireTime = nil,
    TrialPetPurchased = function(self)
      self.initializeExpireTime = nil
    end,
    PetExpireTime = function(self, ID, time)
      local textColor = 15790080
      local minutes = time / 60
      if time <= 0 then
        NotificationHandler:SystemMessage("Pet Trial has ended.", nil, textColor)
        self.initializeExpireTime = false
      elseif Pet.GetActivePetId() == ID and time % 60 == 0 then
        if minutes == 20 or minutes == 10 or minutes == 5 or minutes == 2 then
          local str = Ui.GetString("petTrialPercentMinutes")
          str = string.gsub(str, "%%timeLeft", tostring(minutes))
          NotificationHandler:SystemMessage(str, nil, textColor)
        elseif minutes == 1 then
          local str = Ui.GetString("petTrialPercentSeconds")
          str = string.gsub(str, "%%timeLeft", tostring(time))
          NotificationHandler:SystemMessage(str, nil, textColor)
        end
      end
    end,
    CancelPetTrick = function(self)
      Pet.CameraRestore()
      Pet.StopGestureGame()
    end,
    print = function(self, message)
      if self.debug then
        print("[PetsHandler]\t" .. tostring(message))
      end
    end
  }
  PetsFte = {
    queuedUpdate = nil,
    FirstPetFTECheck = function(self)
      if DsTable.Find(DataSources[DS_PET_LIST]):GetRowCount() < 1 or WelcomeHandler.isShown == true or MarketplaceHandler.boolIsShown == true then
        self.queuedUpdate = true
        return
      end
    end
  }
end)()
