          Ui.LoadSound("PETS", v)
        end
      end
    end,
    OnResize = function(self, min)
      local wnd = self.GetWindow()
      if wnd ~= nil and self.visible == true and Pet.GetActivePetId() > 0 and self.isLocked ~= true then
        local sw, sh = Window.GetCanvasSize()
        local pc_w, pc_h = wnd:GetSize()
        wnd:Show()
        self.GetSwf():Invoke("LockController")
        self.isMoving = true
        WindowTweener:Create(self.wndName, "X", nil, sw - pc_w - 20, 0.3, function()
          local pconX, pconY = wnd:GetPosition()
          local pconW, pconH = wnd:GetSize()
          self.GetSwf():Invoke("UnlockController")
          self.isMoving = false
          if self.queuedEvent ~= nil then
            self:PetEventReceived(self.queuedEvent.string, self.queuedEvent.id)
