    Hide = function(self)
      local sw, sh = Window.GetCanvasSize()
      self.visible = false
      self.GetSwf():Invoke("LockController")
      DsTable.Find(DataSources[DS_PET_TRICKS]):DisableScriptEvents()
      NonModalContext:RemoveContext(self)
