    end,
    ShowTricks = function(self)
      if self.tricksShown then
        self:PopulatePetController()
        self.GetSwf():SoftInvoke("rollOutTrickPanel", 1)
        self.tricksShown = nil
      end
    end,
    HideTricks = function(self)
      self.GetSwf():SoftInvoke("petbtn.trickBar_mc.hide")
    end,
    LockTricks = function(self, lockForTut)
      self.IsDoingTrick = true
      self.GetSwf():SoftInvoke("SetDismissButtonEnabled", 0)
    end,
    UnlockTricks = function(self)
      local swf = self.GetSwf()
      swf:SoftInvoke("unlockPetTricks")
      swf:SoftInvoke("SetDismissButtonEnabled", 1)
      self.IsDoingTrick = false
      self:UpdateTrickData()
      if self.isLocked == true then
        self.isLocked = false
        self.visible = false
        HUD:showMain()
        if self.lockedForTutorial ~= true then
          self:Show()
        else
          self.lockedForTutorial = nil
          Pet.Dismiss()
        end
      end
    end,
    PopulatePetController = function(self)
    end,
    GetControllerHeight = function(self)
      local lHeight = 130
      if self.minimized then
        lHeight = 50
      end
      if self.visible ~= true then
        lHeight = 0
      end
      return lHeight
    end,
    MinimizeController = function(self)
      local movie = GfxCtrl.Find(Ui.GetName(self.swfName))
      movie:Invoke("minimizePetController")
    end,
    PetEventReceived = function(self, eventString, eventId)
      if self.isMoving ~= true then
        local pc = GfxCtrl.Find(Ui.GetName(self.swfName))
        pc:Invoke("ActivatePanel", eventString, eventId)
      else
        self.queuedEvent = {string = eventString, id = eventId}
      end
    end,
    isShown = 0,
    isMinimized = 0,
    actualHeight = 0,
    actualX = 0,
    actualY = 0,
    GetIsShown = function(self)
      return self.isShown
    end,
    GetIsMinimized = function(self)
      return self.isMinimized
    end,
    SetMinimized = function(self)
      if self.isMinimized ~= 1 then
        self.isMinimized = 1
        self:MinimizeController()
      end
    end,
    GetHeight = function(self)
      if self.isMinimized == 1 then
        return 60
      end
      return 110
    end,
    SetHeight = function(self, h)
      self.actualHeight = h
    end,
    GetY = function(self)
      return self.actualY
    end,
    SetY = function(self, y)
      self.actualY = y
      WindowTweener:Create(self.wndName, "Y", nil, y, 0.3)
    end,
    UpdateTrickData = function(self)
    end,
    GetTrickData = function(self, callback)
    end,
    OnUserEvent = function(a, b, ...)
      PetController:print(a)
      if PetTutorial.enabled == true then
        PetTutorial:PetControllerUserEvent(a, b)
        return
      end
      if a == "good" then
        Pet.WasGood(b)
      elseif a == "bad" then
        Pet.WasBad(b)
      elseif a == "showPets" or a == "doTrick" and tonumber(b) < 0 then
        b = tonumber(b)
        if b then
          if b < -9 then
            PetsHandler:Show(4)
            EquipmentHandler:SelectCategory((b + 10) * -1)
          elseif b == -2 then
            PetsHandler:Show(5)
            EquipmentHandler:SelectCategory(5)
          end
        else
          PetsHandler:Show()
        end
      elseif a == "TricksDisplay" and FirstTimeEvent.PetTricksFTEtoClosetheDialog == true then
        FirstTimeEvent.PetTricksFTEtoClosetheDialog = nil
        TutorialDialog:Hide()
      elseif a == "doTrick" then
        PetController:LockTricks()
        if tonumber(b) == 0 then
          Pet.PlayWithToy()
        elseif tonumber(b) > 0 then
          local didTrick = Pet.PerformTrick(b)
          if didTrick then
            PetsHandler:PlaySound("Whistle" .. math.random(1, 3))
          else
            WindowTweener:Create(PetController.wndName, "Y", nil, PetController.actualY, 1.4, function()
              local swf = GfxCtrl.Find(Ui.GetName(PetController.swfName))
              swf:SoftInvoke("unlockPetTricks")
              swf:SoftInvoke("SetDismissButtonEnabled", 1)
              PetController.isLocked = false
              PetController.visible = false
            end)
          end
        end
      elseif a == "maximizePetController" then
        PetController.minimized = nil
        PetController.isMinimized = 0
        HudWindowManager:OnMaximizeWindow(PetController)
      elseif a == "minimizePetController" then
        PetController.minimized = 1
        PetController.isMinimized = 1
        HudWindowManager:OnMinimizeWindow(PetController)
      elseif a == "dismissPetController" then
        PetController:CloseController()
      elseif a == "PlaySound" or a == "playSound" then
        HUD:PlaySound(b)
      elseif a == "AS_Print" then
      elseif PetController[a] then
        PetController[a](PetController, b, ...)
      else
        PetController:print(a)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[PetController]\t" .. message)
      end
    end
  }
  Delegate:AddSupportToClassObject(PetController, "PetController")
  Main_wndPetController_swfPetController_OnUserEvent = PetController.OnUserEvent
  Main_wndPetController_swfPetController_OnFocus = PetController.OnFocus
end)()
