      if b == "undefined" then
        Ui.LuaRequestVirtualKeyboard(1, "", "Bug Description")
      else
        Ui.LuaRequestVirtualKeyboard(1, b, "Bug Description")
      end
      BugHandler.waitingForKeyboard = 1
    elseif a == "SubmitBugMessage" then
      BugHandler:Hide()
      Ui.OnBugReportUiSubmit(b)
    end
  end
end)()
