        local child = node:GetChildNode(i)
        local catText = child:GetText()
        local catIcon = child:GetBitmapIndex()
        local catID = child:GetData(0)
        if tonumber(catID) ~= Housing.HOUSING_FIXTURE_ID and tonumber(catID) ~= self.TICKET_ID then
          self.treeData = self.treeData .. self:SerializeTreeItem(catID, catText, catIcon, node:GetData(0))
        end
        self:TreeRecursion(child)
      end
    end,
    SerializeTreeItem = function(self, catID, catText, catIcon, parentCatId)
      return "catId~" .. tostring(catID) .. "|catText~" .. tostring(catText) .. "|catIcon~" .. tostring(catIcon) .. "|parentCatId~" .. tostring(parentCatId) .. "~~"
    end,
    SetCurrentCategory = function(self, id)
      if id ~= "-1" then
        if self.m_newItems then
          InventoryHandler.ClearNewFlagQueue:Clear()
        end
        self.m_newItems = nil
        InventoryScreen.SelectInventoryCategory(math.floor(id))
      else
        self.m_newItems = true
      end
      self:RefreshSWF(1)
      Ui.SetUserOptionsValue("InventoryOptions", "LastSelectedCategory", tostring(id))
    end,
    SelectTreeCategory = function(self, catId)
      self.GetSwf():Invoke("m_tree_mc.expandAndSelectCategory", tostring(catId))
    end,
    SetInventoryCategory = function(self, type)
      local catPath = ""
      if type ~= "-1" then
        if self.m_newItems then
          InventoryHandler.ClearNewFlagQueue:Clear()
        end
        self.m_newItems = nil
        catPath = NavigationHandler:GetInventoryCategoryPath(type)
        InventoryScreen.SelectInventoryCategory(type)
      else
        self.m_newItems = true
        catPath = Ui.GetString("InventoryUINavigationNewItems")
      end
      self:RefreshSWF(1)
      Ui.SetUserOptionsValue("InventoryOptions", "LastSelectedCategory", tostring(type))
    end,
    RequestData = function(self, offset, count)
      local ds = DataSources[DS_INVENTORY_ITEMS_DATA]
      if self.m_newItems == true then
        ds = DataSources[DS_NEW_ITEMS_DATA]
      end
      self:Populate(tonumber(offset), tonumber(count), DsTable.Find(ds))
    end,
    Populate = function(self, offset, count, ds)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          str = self:SerializeData(ds, offset, count)
          self.GetSwf():Invoke("setData", str, numRows)
        else
          self.GetSwf():Invoke("setData", str, 0)
        end
      else
        self.GetSwf():Invoke("setData", str, 0)
      end
    end,
    SetColumnsForSWF = function(self)
      local count = #self.ColumnsTable
      local catString = self.ColumnsTable[1]
      for i = 2, count do
        catString = catString .. "^" .. self.ColumnsTable[i]
      end
      return catString
    end,
    SerializeData = function(self, ds, offset, count)
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      local offset = math.max(offset, 0)
      local countTo = math.min(offset + count, ds:GetRowCount())
      for i = offset, countTo - 1 do
        for c = 0, ds:GetColumnCount() - 1 do
          if c > 0 then
            data = data .. propDelim
          end
          data = data .. ds:GetColumnName(c) .. valueDelim .. ds:GetData(i, c)
        end
        if i < ds:GetRowCount() - 1 and count > 1 then
          data = data .. itemDelim
        end
      end
      return data
    end,
    RefreshSWF = function(self, catChanged)
      if not self.visible then
        return
      end
      local LastSelectedViewMode = Ui.GetUserOptionsValue("InventoryOptions", "LastSelectedViewMode", "1")
      self.GetSwf():Invoke("changeCategory", catChanged, LastSelectedViewMode)
      self.GetSwf():Invoke("UpdateSelectedItem")
    end,
    UpdateWalletInfo = function(self, walletBalance)
      if not self.visible then
        return
      end
      self.GetSwf():Invoke("CoinsAndCash.setStationCash", walletBalance)
    end,
    SetItemQuantity = function(self, item, quantity)
      if not self.visible then
        return
      end
      self.GetSwf():Invoke("SetItemQuantity", item, quantity)
    end,
    SelectItem = function(self, index, callback)
      if index == nil then
        self.GetSwf():Invoke(callback, "")
        return
      end
      local ds = DataSources[DS_INVENTORY_ITEMS_DATA]
      if self.m_newItems == true then
        ds = DataSources[DS_NEW_ITEMS_DATA]
      end
      local data = self:SerializeData(DsTable.Find(ds), index, 1)
      self.GetSwf():Invoke(callback, index, self:GetLastSelectedCategory(), data)
    end,
    UpdateItem = function(self, index, catId, callback)
      if index == nil then
        self.GetSwf():Invoke(callback, "")
        return
      end
      local ds = DataSources[DS_INVENTORY_ITEMS_DATA]
      if self.m_newItems == true then
        ds = DataSources[DS_NEW_ITEMS_DATA]
      end
      local data = self:SerializeData(DsTable.Find(ds), index, 1)
      self.GetSwf():Invoke(callback, index, category, data)
    end,
    SetRentalTimeRemainingMessage = function(self, secondsRemaining, callback)
      local data = Ui.GetString("ItemRental_TimeLeft_Expired")
      if secondsRemaining == nil or secondsRemaining < 0 then
        self.GetSwf():Invoke(callback, data)
        return
      end
      local message = data
      local value = secondsRemaining
      local days = math.floor(value / 86400)
      value = value - days * 86400
      local hours = math.floor(value / 3600)
      value = value - hours * 3600
      local minutes = math.floor(value / 60)
      value = value - minutes * 60
      local seconds = value
      if days > 0 then
        message = Ui.GetString("ItemRental_TimeLeft_Days")
        message = string.gsub(message, "%%days", days)
      elseif hours > 0 then
        message = Ui.GetString("ItemRental_TimeLeft_HoursAndMinutes")
        message = string.gsub(message, "%%hours", hours)
        message = string.gsub(message, "%%minutes", minutes)
      elseif minutes > 0 then
        if minutes < 2 then
          message = Ui.GetString("ItemRental_TimeLeft_MinutesAndSeconds")
          message = string.gsub(message, "%%minutes", minutes)
          message = string.gsub(message, "%%seconds", seconds)
        else
          message = Ui.GetString("ItemRental_TimeLeft_Minutes")
          message = string.gsub(message, "%%minutes", minutes)
        end
      elseif value > 0 then
        message = Ui.GetString("ItemRental_TimeLeft_Seconds")
        message = string.gsub(message, "%%seconds", seconds)
      end
      data = message
      self.GetSwf():Invoke(callback, data)
    end,
    OnUserEvent = function(a, b, c, d, ...)
      if a == "SelectItem" then
        InventoryHandler:SelectItem(tonumber(b), c)
      elseif a == "UpdateItem" then
        InventoryHandler:UpdateItem(tonumber(b), tonumber(c), d)
      elseif a == "ItemExpiredUpdate" then
        InventoryHandler:RefreshSWF()
      elseif a == "GetRentalItemTimeString" then
        InventoryHandler:SetRentalTimeRemainingMessage(tonumber(b), c)
      elseif a == "onBuyRental" then
        InventoryHandler:print(a .. "( " .. tostring(b) .. " )")
        InventoryHandler:Hide()
        InGamePurchaseStoreScreen.DisplayStoreItemsContainingExpiredRentalGameItem(tonumber(b))
      elseif a == "ItemAdded" then
        Trade.OfferItems(b, c)
      elseif a == "onMembersOnly" then
        InventoryHandler:Hide()
        MarketplaceHandler:Show(MarketplaceEnum.STORE_SC)
      elseif a == "playSound" or a == "PlaySound" then
        HUD:PlaySound(b)
      elseif a == "equipItem" then
        EquipScreen.EquipItem(b, c)
      elseif a == "requestData" then
        InventoryHandler:RequestData(b, c)
      elseif a == "addStationCash" then
        InventoryHandler:Hide()
        MarketplaceHandler:Show(MarketplaceEnum.STORE_SC)
      elseif a == "clearNewItemFlag" then
        if InventoryHandler.m_newItems then
          InventoryHandler.ClearNewFlagQueue:Add(b)
        else
          Ui.ClearItemNewFlag(b)
        end
      elseif a == "changeViewMode" then
        Ui.SetUserOptionsValue("InventoryOptions", "LastSelectedViewMode", b)
      elseif a == "AddToLiveGamer" then
        LiveGamerHandler:ShowConfirmation(b, c, d)
      elseif a == "setFocus" then
        if b == "true" then
          InventoryHandler.inputFocus = true
          InventoryHandler.GetWindow():SetFocus()
        else
          InventoryHandler.inputFocus = false
          Window.SetFocus()
        end
      elseif a == "AS_Print" then
        InventoryHandler:print(b)
      elseif a == "CloseWindowPS3" then
        InventoryHandler:Hide()
        JobHandler:ModeSwitch(0)
      else
        if InventoryHandler[a] then
          InventoryHandler[a](InventoryHandler, b, c, d, ...)
        else
        end
      end
    end,
    OnFocus = function(focus)
      if focus == "1" and InventoryHandler.inputFocus == false then
        Window.SetFocus()
      end
    end,
    ClearNewFlagQueue = {
      m_queue = {},
      length = 0,
      Add = function(self, id)
        for i = 1, self.length do
          if id == self.m_queue[i] then
            return
          end
        end
        table.insert(self.m_queue, id)
        self.length = #self.m_queue
      end,
      Clear = function(self)
        for i = 1, self.length do
          Ui.ClearItemNewFlag(self.m_queue[i])
        end
        self.m_queue = {}
        self.length = 0
      end,
      Show = function(self)
        local message = "**> Showing ClearNewFlagQueue <**"
        message = message .. [[

	Total Items: ]] .. tostring(self.length)
        for i = 1, self.length do
          message = message .. [[

			Item ]] .. i .. " GUID: " .. tostring(self.m_queue[i])
        end
        message = message .. [[

**> End Showing ClearNewFlagQueue <**]]
        print(message)
      end
    },
    print = function(self, message)
      if self.debug then
        print("[InventoryHandler]\t" .. tostring(message))
      end
    end
  }
  Main_wndInventory_swfInventory_OnUserEvent = InventoryHandler.OnUserEvent
  Main_wndInventory_swfInventory_OnFocus = InventoryHandler.OnFocus
  LiveGamerHandler = {
    visible = false,
    debug = false,
    InvalidAccount = function(self)
      MessageWindow:Show()
      local title = Ui.GetString("LIVEGAMER_INVALID_ACCOUNT_TITLE")
      local message = Ui.GetString("LIVEGAMER_INVALID_ACCOUNT_MESSAGE")
      local hyperlink = "\"asfunction:handleLink,onLiveGamer,0\""
      message = string.gsub(message, "%%hyperlink", hyperlink)
      MessageWindow:SetText(title, message, 1)
    end,
    OpenLiveGamerSite = function(self, page)
      LiveGamer.GoToLiveGamerSite(page)
      MessageWindow:Hide()
    end,
    ShowConfirmation = function(self, index, itemId, quantity)
      local ds = DataSources[DS_INVENTORY_ITEMS_DATA]
      if InventoryHandler.m_newItems == true then
        ds = DataSources[DS_NEW_ITEMS_DATA]
      end
      local data = InventoryHandler:SerializeData(DsTable.Find(ds), index, 1)
      self._ItemId = itemId
      self._Quantity = quantity
      ConfirmationWindow:Connect(LiveGamerHandler)
      self.OnConfirmationResponse = self.HideConfirmation
      local message = Ui.GetString("UI_LIVE_GAMER_CONFIRMATION")
      ConfirmationWindow:Show(message, data, quantity, LiveGamerHandler.HideConfirmation)
      local sw, sh = Window.GetCanvasSize()
      NavigationHandler:Move(nil, sh)
    end,
    HideConfirmation = function(self, response)
      ConfirmationWindow:Disconnect(LiveGamerHandler)
      self.OnConfirmationResponse = nil
      if response == 1 then
        LiveGamer.PostItem(self._ItemId, self._Quantity)
      elseif response == 0 then
      end
      self._ItemId = nil
      self._Quantity = nil
      local sw, sh = Window.GetCanvasSize()
      NavigationHandler:Move(nil, sh - 250)
    end,
    AddItem = function(self, index, itemId, quantity)
      LiveGamer.PostItem(itemId, quantity)
    end,
    print = function(self, message)
      if self.debug then
        print("[Inventory]\t" .. tostring(message))
      end
    end
  }
end)()
;(function()
  NavigationHandler = {
    wndName = "Main.wndNavigationBar",
    swfName = "Main.wndNavigationBar.swfNavigationBar",
