    end,
    SetBarButtonToolTip = function(self, ID, tooltip)
      if self.GetSwf() then
        self.GetSwf():Invoke("SetBarButtonToolTip", ID, tooltip)
      end
    end,
    EnableBar = function(self)
      if self.GetSwf() then
        self.GetSwf():Invoke("enableBar")
      end
    end,
    DisableBar = function(self)
      if self.GetSwf() then
        self.GetSwf():Invoke("disableBar")
      end
    end,
    DockToWindow = function(self, wnd)
      local nw, nh = self.GetWindow():GetSize()
      local sw, sh = Window.GetCanvasSize()
      local wx, wy = wnd:GetPosition()
      local ww, wh = wnd:GetSize()
      local xPos = wx + nw / 4
      local yPos = wy - nh / 2 + wh / 2
      self:Move(xPos, yPos)
    end,
    Move = function(self, x, y)
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      local wndPositionX = x
      local wndPositionY = y
      if x == nil then
        wndPositionX = sw / 2 - 640
      end
      if y == nil then
        wndPositionY = sh - wh
      end
      wndPositionY = wndPositionY - 30
      WindowTweener:Create(self.wndName, "X", nil, wndPositionX, 0.3)
      WindowTweener:Create(self.wndName, "Y", nil, wndPositionY, 0.3)
    end,
    Show = function(self, x, y, offsetY, speed)
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      local wndPositionX = sw / 2 - ww / 2
      local wndPositionY = sh + wh
      self.GetWindow():SetPosition(wndPositionX, wndPositionY)
      wndPositionY = sh - wh
      self.GetSwf():Reset()
      if x then
        wndPositionX = x
      end
      if y then
        wndPositionY = y
      end
      speed = speed or 0.3
      if offsetY then
        wndPositionY = wndPositionY - 40
      end
      self.GetWindow():Show()
      wndPositionY = wndPositionY - 38
      self.isTweening = true
      WindowTweener:Create(self.wndName, "Y", nil, wndPositionY - 10, speed, function()
        self.isTweening = false
        NavigationHandler:ShowNavigation()
        if self.pendingHighlightId > -1 then
          self:HighlightButton(self.pendingHighlightId, self.pendingHighlight)
        end
      end)
      WindowTweener:Create(self.wndName, "X", nil, wndPositionX, speed)
      if MiniGameStatusHandler.currentMiniGameType == -1 then
        GameDock:SetState(GameDock.SUBMENU_STATE)
      else
        GameDock:SetState(GameDock.MINIGAME_SUBMENU_STATE)
