      if self.isTweening == true then
        Logger:print("navigationhandler.lua", "Delaying Button Highlight " .. id .. " " .. tostring(highlight))
        self.pendingHighlightId = id
        self.pendingHighlight = highlight
        return
      end
      if self.GetSwf() then
        self.GetSwf():Invoke("HighlightButton", id, highlight)
      end
    end,
    SelectButton = function(self, id, eventDisabled)
      if self.GetSwf() then
        self.GetSwf():Invoke("SelectButton", id, eventDisabled)
      end
    end,
    Deselect = function(self)
      self.GetSwf():Invoke("Deselect")
    end,
    Hide = function(self, obj, windowSwitch, yoffset, speed)
      Logger:print("navigationhandler.lua", "hiding ->" .. debug.traceback())
      local sw, sh = Window.GetCanvasSize()
      yoffset = yoffset or -140
      speed = speed or 0.3
      WindowTweener:Create("Main.wndNavigationBar", "Y", nil, sh + yoffset, speed, function()
        NavigationHandler:HideNavigation(windowSwitch)
      end)
      if obj then
        NavigationHandler:Disconnect(obj)
      end
      GameDock:DetermineButtonSelection()
      ToolTipHandler:HideToolTip()
      if Context:IsCurrent("NavigationHandler") then
        Context:Pop()
      end
      Ui.SetKeyboardEnabled(1)
      self.pendingHighlightId = -1
      self.pendingHightlight = -1
    end,
    ShowNavigation = function(self)
      self:CallDelegate("OnNavigationShown")
    end,
    HideNavigation = function(self, windowSwitch)
      if windowSwitch == nil then
        if self.GetWindow() then
          self.GetWindow():Hide()
        end
        if self.GetSwf() then
          self.GetSwf():Unload()
        end
      end
      self:CallDelegate("OnNavigationHidden")
      if MiniGameStatusHandler.currentMiniGameType == -1 then
        GameDock:SetState(GameDock.NORMAL_STATE)
      else
        GameDock:SetState(GameDock.MINIGAME_STATE)
      end
    end,
    BuildInventoryNavigation = function(self, newItems)
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      local datasource = DataSourceTrees[DST_INVENTORY_CATEGORIES_DATA]
      local ds = DsTree.Find(datasource)
      if ds then
        local root = ds:GetRootNode()
        if newItems then
          NavigationHandler:AddCategoryButton(4638, Ui.GetString("InventoryUINavigationNewItems"), "-1")
        end
        for i = 0, root:GetChildCount() - 1 do
          local child = root:GetChildNode(i)
          local catText = child:GetText()
          local catIcon = child:GetBitmapIndex()
          local catID = child:GetData(0)
          if tonumber(catID) ~= 50 or HUD.showHousing then
            NavigationHandler:AddCategoryButton(catIcon, catText, catID)
            local firstChildCatID
            local dontAdd = false
            for c = 0, child:GetChildCount() - 1 do
              local subChild = child:GetChildNode(c)
              local catText = subChild:GetText()
              local catIcon = subChild:GetBitmapIndex()
              local catID = subChild:GetData(0)
              if catID == firstChildCatID then
                dontAdd = true
              end
              if firstChildCatID == nil then
                firstChildCatID = catID
              end
              if dontAdd == false then
                NavigationHandler:AddSubCategoryButton(i + 1, catIcon, catText, catID)
              end
            end
          end
        end
      end
    end,
    GetInventoryCategoryPath = function(self, id)
      local ds = DsTree.Find(DataSourceTrees[DST_INVENTORY_CATEGORIES_DATA])
      if ds then
        local root = ds:GetRootNode()
        for i = 0, root:GetChildCount() - 1 do
          local child = root:GetChildNode(i)
          local catText = child:GetText()
          local catIcon = child:GetBitmapIndex()
          local catID = child:GetData(0)
          if catID == id then
            return catText
          end
          for c = 0, child:GetChildCount() - 1 do
            local parentCatText = catText
            local subChild = child:GetChildNode(c)
            local catText = subChild:GetText()
            local catIcon = subChild:GetBitmapIndex()
            local catID = subChild:GetData(0)
            if catID == id then
              return parentCatText .. " : " .. catText
            end
          end
        end
      end
    end,
    OnUserEvent = function(a, b)
      if a == "playSound" then
        HUD:PlaySound(b)
      elseif a == "AS_Print" then
        NavigationHandler:print(b)
      elseif a == "exitScreen" then
      elseif a == "SwitchTo" then
        ToolTipHandler:HideToolTip()
      end
      NavigationHandler:CallDelegate("NavigationOnUserEvent", a, b)
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[VehicleBrowser]\t" .. tostring(message))
      end
    end
  }
  Delegate:AddSupportToClassObject(NavigationHandler, "NavigationHandler")
  Main_wndNavigationBar_swfNavigationBar_OnUserEvent = NavigationHandler.OnUserEvent
  Main_wndNavigationBar_swfNavigationBar_OnFocus = NavigationHandler.OnFocus
end)()
;(function()
  UIWindowResize = {
    SetWindowSize = function(self, winName, swfName)
      local sw, sh = Window.GetCanvasSize()
      local win = Window.Find(winName)
      local swf = GfxCtrl.Find(swfName)
      local yPos = 0
      if sh <= 981 then
        swf:Invoke("resize", 0)
        win:SetSize(1280, 818)
        yPos = -30
      elseif sh < 1299 then
        swf:Invoke("resize", 1)
        win:SetSize(1230, 1199)
        yPos = -200
      else
        swf:Invoke("resize", 2)
        win:SetSize(1574, 1648)
        yPos = -400
      end
      return yPos
    end
  }
  Delegate:AddSupportToClassObject(UIWindowResize, "UIWindowResize")
end)()
