    Check = function(self)
      if MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.PIRATES_TYPE then
        return false
      end
      return true
    end,
    Init = function(self)
      if self.isInitialized == false then
        self:SetJobSwitchOnOrOff(false)
      end
      self.isInitialized = true
      self.buttonsDisabled = false
      local ds = DsTable.Find(self.GroupMemberDsName)
      local movie = self:GetSwf()
      if ds and movie then
        Logger:print("group.lua", "GroupHandler INIT: got ds and movie")
        self:GroupMemberDataUpdated()
      end
      local gWND = Window.Find(self.m_windowName)
      if gWND then
        gWND:SetPosition(96, -260)
        gWND:Show()
      end
      self:ModeSwitch(self.Mode)
    end,
    Show = function(self, showButton)
      if HUD.isInStartingZone or not self:Check() then
        return
      end
      if self.isInitialized == false then
        self:Init()
      end
      local ds = DsTable.Find("BaseClient.MiniGameScore")
      ds:EnableScriptEvents()
      ds = DsTable.Find(self.BuffsDsName)
      ds:EnableScriptEvents()
      GroupHandler:BuffsUpdated()
      if MiniGameStatusHandler.panesUp == true then
        return
      end
      if not Client.UiScale then
        WindowTweener:Create("Main.wndCombatGroup", "Y", nil, 54, 0.3)
      else
        WindowTweener:Create("Main.wndCombatGroup", "Y", nil, 54 * Client.UiScale, 0.3)
      end
      LevelProgressBar:RegisterDatasource()
      LevelProgressBar:SetData(Ui.GetActiveProfileId())
      self:SetKO()
    end,
    getGroupSize = function(self)
      local ds = DsTable.Find("BaseClient.GroupMemberData")
      if ds then
        local numRows = ds:GetRowCount()
        return numRows
      else
        return 0
      end
    end,
    HideGroupMembers = function(self)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("hideGroupMembers")
      end
    end,
    ShowGroupMembers = function(self)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("showGroupMembers")
      end
    end,
    SetKO = function(self)
      if not Ui.GetPlayerKnockoutInfo then
        return
      end
      local gotKOs = false
      if MiniGameStatusHandler.currentMiniGameType == 4 then
        local KOs, KOmax = Ui.GetPlayerKnockoutInfo()
        if KOs and KOmax then
          local newKOs = KOmax - KOs
          if newKOs < 0 then
            newKOs = 0
          end
          local newKOsNumber = newKOs
          newKOs = string.gsub(Ui.GetString("KnockoutsRemaining"), "@1", tostring(newKOs), 1)
          local movie = self:GetSwf()
          if movie then
            movie:Invoke("setKnockouts", newKOsNumber, newKOs)
          end
          gotKOs = true
        end
      end
      if gotKOs == false then
        local movie = self:GetSwf()
        if movie then
          movie:Invoke("setKnockouts", -1)
        end
      end
    end,
    SetJobLevelExp = function(self, title, rank, pct)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("setPlayerLevelExp", title, rank, pct)
      end
      MiniGameStatusHandler:SetJobLevel(rank)
    end,
    SetEncounterData = function(self)
      local ds = DsTable.Find("BaseClient.MiniGame")
      if ds then
        local dsData
        dsData = tostring(ds:GetData(0, MiniGameDsColumn.Name))
        local movie = self:GetSwf()
        if tostring(dsData) ~= "-1" and movie then
          movie:Invoke("SetEncounterTitle", dsData)
        end
      end
    end,
    StatusButtonEnabled = function(self, value)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("StatusButtonEnabled", tostring(value))
      end
    end,
    Hide = function(self, mode)
      WindowTweener:Create("Main.wndCombatGroup", "Y", nil, -560, 0.3, function()
        GroupHandler:Hide2()
        self:CallDelegate("GroupWindowHidden")
      end)
      local ds = DsTable.Find("BaseClient.MiniGameScore")
      ds:DisableScriptEvents()
      ds = DsTable.Find(self.BuffsDsName)
      ds:DisableScriptEvents()
      self.buttonsDisabled = false
    end,
    Hide2 = function(self)
      self.buttonsDisabled = false
    end,
    EncounterButtonModeSwitch = function(self, mode)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("SetEncounterButtonMode", mode)
      end
      self.buttonsDisabled = false
    end,
    ModeSwitch = function(self, mode)
      local movie = self:GetSwf()
      self.Mode = mode
      if movie then
        movie:Invoke("SetMode", mode)
      end
      self.buttonsDisabled = false
      self:GroupMemberDataUpdated()
    end,
    ActivateEncounterRequest = function(self, timeout, encounterName, encounterIcon)
      self:Show(1)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("SetEncounterStartTimer", timeout)
        if encounterName ~= nil then
          movie:Invoke("SetEncounterTitle", tostring(encounterName))
        end
        if encounterIcon ~= nil then
          movie:Invoke("SetEncounterIcon", encounterIcon)
        end
      end
      self.EncounterTimerActive = true
    end,
    DeactivateEncounterRequest = function(self, accepted)
      if accepted == 1 then
        GroupScreen.ActivateEncounter()
      else
        self:EncounterButtonModeSwitch(1)
      end
      self.EncounterTimerActive = false
    end,
    InvitationIsRejected = function(self)
      self.EncounterTimerActive = false
      if MarketplaceHandler.boolIsShown == false then
        self:Show()
      end
    end,
    KickMember = function(self, index)
      GroupScreen.RemovePlayerFromGroupByGuid(index)
    end,
    LeaveGroup = function(self)
      GroupScreen.DepartGroup()
    end,
    AddPlayer = function(self, index, guid, playerName, playerPortrait, memberRank)
      if playerName ~= self.tempPlayerName then
        local movie = self:GetSwf()
        if movie then
          movie:Invoke("GroupDataUpdate", index, "GUID:" .. tostring(guid), playerName, playerPortrait, memberRank)
        end
      end
    end,
    RemovePlayer = function(self, index)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("RemovePlayer", index)
      end
    end,
    MuteMember = function(self, index)
      GroupScreen.MutePlayerByGuid(index)
    end,
    SetHealth = function(self, guid, currentHealth, maxHealth, doAlert)
      if maxHealth == 0 then
        return
      end
      if Ui.IsInCombat() == true or MiniGameStatusHandler.currentMiniGameType == 4 then
        local movie = self:GetSwf()
        if movie then
          if not maxHealth then
            movie:Invoke("SetHealth", "GUID:" .. tostring(guid), 0, 0)
          else
            movie:Invoke("SetHealth", "GUID:" .. tostring(guid), currentHealth, maxHealth, doAlert)
          end
        end
      end
    end,
    SetPower = function(self, guid, currentPower, maxPower)
      if maxPower == 0 then
        return
      end
      if Ui.IsInCombat() == true or MiniGameStatusHandler.currentMiniGameType == 4 then
        local movie = self:GetSwf()
        if movie then
          movie:Invoke("SetPower", "GUID:" .. tostring(guid), currentPower, maxPower)
        end
      end
    end,
    BuffsUpdated = function(self)
      for k, v in pairs(self.buffs) do
        v.stale = true
      end
      local ds = DsTable.Find(self.BuffsDsName)
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local instanceID = ds:GetData(i, 0)
          if self.buffs[instanceID] then
            self.buffs[instanceID].stale = false
          end
        end
      end
      for k, v in pairs(self.buffs) do
        if v.stale == true then
          self:RemoveAbilityEffect(Ui.GetPlayerGuid(), k, true)
          self.buffs[k] = nil
        end
      end
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local instanceID = ds:GetData(i, 0)
          if self.buffs[instanceID] then
            self.buffs[instanceID].stale = false
          else
            local iconID = ds:GetData(i, 1)
            local duration = ds:GetData(i, 2)
            local timeLeft = ds:GetData(i, 3)
            local name = ds:GetData(i, 4)
            self:AddAbilityEffect(Ui.GetPlayerGuid(), instanceID, iconID, name, true, timeLeft)
            self.buffs[instanceID] = {stale = false, name = name}
          end
        end
      end
    end,
    AddAbilityEffect = function(self, guid, effectID, icon, name, selfOverride, timeLeft)
      if tonumber(icon) == 0 then
        return
      end
      if selfOverride ~= true and tonumber(guid) == tonumber(Ui.GetPlayerGuid()) then
        return
      end
      local movie = self:GetSwf()
      if movie then
        Logger:print("group.lua", "Add Ability Effect: " .. timeLeft)
        if name == "Power Hour Coin Boost" or name == "Pet Happiness Speed Buff" then
          timeLeft = -1
        end
        movie:Invoke("AddStatusEffect", guid, effectID, icon, name, timeLeft)
      end
    end,
    RemoveAbilityEffect = function(self, guid, effectID, selfOverride)
      if selfOverride ~= true and tonumber(guid) == tonumber(Ui.GetPlayerGuid()) then
        return
      end
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("RemoveStatusEffect", guid, effectID)
      end
    end,
    ResetAllStatusEffects = function(self)
      local movie = self:GetSwf()
      if movie then
        movie:Invoke("ResetAllStatusEffects")
      end
    end,
    GroupDataUpdated = function(self)
      local ds = DsTable.Find("BaseClient.GroupData")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
        end
      end
    end,
    GroupMemberRowDataUpdated = function(self, index)
      if self.isInitialized == false then
        return
      end
      local movie = self:GetSwf()
      if MiniGameStatusHandler.panesUp then
        MiniGameStatusHandler:SetGroupMembers(index)
      end
      local ds = DsTable.Find("BaseClient.GroupMemberData")
      if ds then
        self:SetHealth(ds:GetData(index, 1), tonumber(ds:GetData(index, 9)), tonumber(ds:GetData(index, 10)), 1)
        self:SetPower(ds:GetData(index, 1), tonumber(ds:GetData(index, 11)), tonumber(ds:GetData(index, 12)))
        local Name = ds:GetData(index, 0)
        local Guid = tostring(ds:GetData(index, 1))
        local JobID = tonumber(ds:GetData(index, 2))
        local JobBackgroundIconID = tonumber(ds:GetData(index, 3))
        local JobIconID = tonumber(ds:GetData(index, 4))
        local JobRank = tonumber(ds:GetData(index, 5))
        local StatusMessage = ds:GetData(index, 6)
        local Rank = tostring(ds:GetData(index, 7))
        local InMiniGame = ds:GetData(index, 8)
        local CurrentHP = tonumber(ds:GetData(index, 9))
        local MaxHP = tonumber(ds:GetData(index, 10))
        local CurrentMana = tonumber(ds:GetData(index, 11))
        local MaxMana = tonumber(ds:GetData(index, 12))
        local CurrentLives = tonumber(ds:GetData(index, 13))
        local MaxLives = tonumber(ds:GetData(index, 14))
        local IsChangingJob = tonumber(ds:GetData(index, 15))
        local updateNow = 1
        if #Name <= 1 then
          updateNow = 0
        end
        local solo = Ui.GetString("GroupStatusSolo")
        local leader = Ui.GetString("GroupStatusLeader")
        local member = Ui.GetString("GroupStatusMember")
        local rank = "Solo"
        if Rank == leader or Rank == "Leader" then
          rank = "Leader"
        elseif Rank == member or Rank == "Member" or Rank == "Group" then
          rank = "Group"
        end
        Rank = rank
        if movie then
          movie:Invoke("GroupDataUpdate", index, Name, "GUID:" .. tostring(Guid), JobID, JobBackgroundIconID, JobIconID, JobRank, StatusMessage, Rank, InMiniGame, CurrentHP, MaxHP, CurrentMana, MaxMana, CurrentLives, MaxLives, IsChangingJob, InMiniGame, updateNow)
        end
      end
    end,
    GroupMemberDataUpdated = function(self)
      if self.isInitialized == false then
        return
      end
      local movie = self:GetSwf()
      local ds = DsTable.Find("BaseClient.GroupMemberData")
      if ds then
        local numRows = ds:GetRowCount()
        ChatLog:SetGroupFilter(ds:GetData(0, 7))
        local numCols = ds:GetColumnCount()
        local memberRemoval = false
        if movie then
          movie:Invoke("GroupDataUpdateStart", numRows)
          local solo = Ui.GetString("GroupStatusSolo")
          if ds:GetData(0, 7) == solo or ds:GetData(0, 7) == "Solo" then
            movie:Invoke("ClearGroupMembers")
          end
          for i = 0, numRows - 1 do
            local Name = ds:GetData(i, 0)
            local Guid = tostring(ds:GetData(i, 1))
            local JobID = tonumber(ds:GetData(i, 2))
            local JobBackgroundIconID = tonumber(ds:GetData(i, 3))
            local JobIconID = tonumber(ds:GetData(i, 4))
            local JobRank = tonumber(ds:GetData(i, 5))
            local StatusMessage = ds:GetData(i, 6)
            local Rank = tostring(ds:GetData(i, 7))
            local InMiniGame = ds:GetData(i, 8)
            local CurrentHP = tonumber(ds:GetData(i, 9))
            local MaxHP = tonumber(ds:GetData(i, 10))
            local CurrentMana = tonumber(ds:GetData(i, 11))
            local MaxMana = tonumber(ds:GetData(i, 12))
            local CurrentLives = tonumber(ds:GetData(i, 13))
            local MaxLives = tonumber(ds:GetData(i, 14))
            local IsChangingJob = tonumber(ds:GetData(i, 15))
            local updateNow = 0
            local solo = Ui.GetString("GroupStatusSolo")
            local leader = Ui.GetString("GroupStatusLeader")
            local member = Ui.GetString("GroupStatusMember")
            local rank = "Solo"
            if Rank == leader or Rank == "Leader" then
              rank = "Leader"
            elseif Rank == member or Rank == "Member" or Rank == "Group" then
              rank = "Group"
            end
            Rank = rank
            movie:Invoke("GroupDataUpdate", i, Name, "GUID:" .. tostring(Guid), JobID, JobBackgroundIconID, JobIconID, JobRank, StatusMessage, Rank, InMiniGame, CurrentHP, MaxHP, CurrentMana, MaxMana, CurrentLives, MaxLives, IsChangingJob, InMiniGame, updateNow)
          end
          movie:Invoke("GroupDataUpdateComplete")
        end
      end
    end,
    SetJobSwitchOnOrOff = function(self, OnOrOff)
      local movie = self:GetSwf()
      if movie then
        if (OnOrOff == true or OnOrOff == 1) and Ui.GetActiveProfileId() ~= self:GetNextJob(0) then
          movie:Invoke("setJobSwitch", 1)
        else
          movie:Invoke("setJobSwitch", 0)
        end
      end
    end,
    CycleJobs = function(self, directionFlag)
      local newJobID = self:GetNextJob(directionFlag)
      JobScreen.SelectJob(newJobID)
    end,
    GetNextJob = function(self, directionFlag)
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      if ds then
        local rows = ds:GetRowCount()
        local gotCurrentProfile = false
        local myMembership = 0
        if Ui.IsMember() then
          myMembership = 1
        end
        local gotID = false
        local startN = -1
        local endN = -1
        local modN = -1
        if directionFlag == 0 then
          startN = rows - 1
          endN = 0
          modN = -1
        else
          startN = 0
          endN = rows - 1
          modN = 1
        end
        while gotID == false do
          for index = startN, endN, modN do
            local id = tonumber(ds:GetData(index, ProfileDsColumns.ID))
            local rank = tonumber(ds:GetData(index, ProfileDsColumns.Rank))
            local mem = tonumber(ds:GetData(index, ProfileDsColumns.MembersOnly))
            local trial = tonumber(ds:GetData(index, ProfileDsColumns.Trial))
            local trialExpired = tonumber(ds:GetData(index, ProfileDsColumns.TrialExpired))
            if gotCurrentProfile and rank > 0 then
              gotID = true
              return id
            end
            if id == tonumber(Ui.GetActiveProfileId()) then
              gotCurrentProfile = true
            end
          end
        end
      end
    end,
    SetVoiceIndicator = function(self, guid, OnOrOff)
      local movie = self:GetSwf()
      if movie then
        if OnOrOff == true or OnOrOff == 1 then
          movie:Invoke("ShowVoiceIndicator", guid)
        else
          movie:Invoke("HideVoiceIndicator", guid)
        end
      end
    end,
    OnUserEvent = function(self, a, b, c)
      if self.buttonsDisabled == true then
        return
      end
      if a == "AcceptEncounter" then
        GroupScreen.ActivateEncounter()
      elseif a == "DeclineEncounter" then
        GroupHandler:DeactivateEncounterRequest()
      elseif a == "KickMember" then
        GroupHandler:KickMember(b)
      elseif a == "LeaveGroup" then
        GroupHandler:LeaveGroup()
      elseif a == "ShowStatus" then
        if Context:Includes("MiniGameHandlerOpenStatusScreen") == false then
          self.buttonsDisabled = true
          MiniGameHandler:OpenStatusScreen()
        else
          if Context:IsCurrent("MiniGameHandlerOpenStatusScreen") then
            self.buttonsDisabled = true
          end
          Context:CallQuit()
        end
      elseif a == "QuitGame" then
        self.buttonsDisabled = true
        MiniGameHandler:QuitGame()
      elseif a == "targetGroupMember" then
        local guid = string.sub(b, 5, -1)
        Ui.TargetGroupMember(guid)
      elseif a == "CancelBuff" then
        if not b then
          return
        end
        Ui.RequestStripEffect(tonumber(b))
      elseif a == "CycleJobs" then
        GroupHandler:CycleJobs(tonumber(b))
      elseif a == "JobBrowser" then
        if HUD.inMiniGame == false then
          HotKeyEvents:ToggleJobBrowser()
        end
      elseif a == "playSound" then
        if b == "targetGroupMember" then
          HUD:PlaySound("ButtonPress")
        elseif b == "ButtonPress" then
          HUD:PlaySound("ButtonPress")
        elseif b == "DockSelect" then
          HUD:PlaySound("ButtonPress")
        elseif b == "DockOver" then
          HUD:PlaySound("ButtonOver")
        elseif b == "ButtonOver" then
          HUD:PlaySound("ButtonOver")
        elseif b == "select" then
        elseif b == "confirm" then
          HUD:PlaySound("ButtonPress")
        elseif b == "display" then
          HUD:PlaySound("ButtonAppear")
        elseif b == "leaveGroup" then
          HUD:PlaySound("ExpandMenu2")
        elseif b == "removePlayer" then
          HUD:PlaySound("BubblePop")
        elseif b == "acceptEncounter" then
          HUD:PlaySound("ExpandMenu2")
        elseif b == "youLeftGroup" then
          HUD:PlaySound("ExpandMenu2")
        elseif b == "newGroupMember" then
          HUD:PlaySound("ExpandMenu2")
        elseif b == "buttonClick" then
          HUD:PlaySound("ButtonPress")
        elseif b == "buttonScale" then
          HUD:PlaySound("ExpandMenu2")
        else
          if b == "LowHealth" and Ui.IsInCombat() == true then
            HUD:PlaySound("LowHealth")
          else
          end
        end
      else
        if a == "AS_Print" then
          self:print(b)
        else
        end
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[StyleCardHandler]\t" .. tostring(message))
      end
    end
  }
  Client.HandlerGroupScreen = "GroupHandler"
  Delegate:AddSupportToClassObject(GroupHandler, "GroupHandler")
  function Main_wndCombatGroup_swfCombatGroup_OnUserEvent(a, b)
    GroupHandler:OnUserEvent(a, b)
  end
  function Main_wndCombatGroup_swfCombatGroup_OnFocus(a, b)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
