    end,
    SetColumnsForSWF = function(self, columnsTable)
      local count = #columnsTable
      local columnsString = columnsTable[1]
      for i = 2, count do
        columnsString = columnsString .. "^" .. columnsTable[i]
      end
      return columnsString
    end,
    Populate = function(self, offset, count, dsID, mode)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      if swf then
        local ds = DsTable.Find(DataSources[dsID])
        if ds then
          local numRows = ds:GetRowCount()
          if numRows > 0 then
            count = tonumber(count)
            local offset = math.max(offset, 0)
            local countTo = math.min(offset + count, numRows)
            for i = offset, countTo - 1 do
              str = str .. self:BuildItemString(ds, i)
            end
          end
          swf:Invoke("setData", mode, str, numRows)
        else
          swf:Invoke("setData", mode, str, 0)
        end
      end
    end,
    BuildItemString = function(self, ds, row)
      local item = ds:GetData(row, 0)
      for i = 1, ds:GetColumnCount() - 1 do
        if i ~= 19 then
          item = item .. "^" .. ds:GetData(row, i)
        else
          item = item .. "^^"
        end
      end
      item = item .. ";"
      return item
    end,
    BuildInventoryItemString = function(self, ds, row)
      local item = ds:GetData(row, 0)
      item = item .. "^" .. ds:GetData(row, 1)
      item = item .. "^" .. ds:GetData(row, 2)
      item = item .. "^" .. ds:GetData(row, 3)
      item = item .. "^" .. ds:GetData(row, 4)
      item = item .. "^" .. ds:GetData(row, 6)
      item = item .. "^" .. ds:GetData(row, 21)
      item = item .. "^" .. ds:GetData(row, 22)
      item = item .. "^" .. ds:GetData(row, 5)
      return item .. ";"
    end,
    OnNavigationShown = function(self)
      self:print("OnNavigationShown()")
      local LastSelectedCategory = Ui.GetUserOptionsValue("InventoryOptions", "LastSelectedCategory", "8")
      NavigationHandler:SelectButton(LastSelectedCategory, 1)
    end,
    BuildNavigation = function(self)
      self:print("BuildNavigation()")
      NavigationHandler:Connect(self)
      local nav = Window.Find("Main.wndNavigationBar")
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = nav:GetSize()
      local datasource = "BaseClient.InventoryCategoriesData"
      local ds = DsTree.Find(datasource)
      if ds then
        local root = ds:GetRootNode()
        NavigationHandler:Show(nil, nil, 30)
        for i = 0, root:GetChildCount() - 1 do
          local child = root:GetChildNode(i)
          local catText = child:GetText()
          local catIcon = child:GetBitmapIndex()
          local catID = child:GetData(0)
          if tonumber(catID) ~= Housing.HOUSING_FIXTURE_ID then
            NavigationHandler:AddCategoryButton(catIcon, catText, catID)
            local firstChildCatID
            local dontAdd = false
            for c = 0, child:GetChildCount() - 1 do
              local subChild = child:GetChildNode(c)
              local catText = subChild:GetText()
              local catIcon = subChild:GetBitmapIndex()
              local catID = subChild:GetData(0)
              if catID == firstChildCatID then
                dontAdd = true
              end
              if firstChildCatID == nil then
                firstChildCatID = catID
              end
              if dontAdd == false then
                NavigationHandler:AddSubCategoryButton(i, catIcon, catText, catID)
              end
            end
          end
        end
      end
      NavigationHandler:AddBarButton(3, 3, nil, 1)
      NavigationHandler:SetBarButtonGraphics(1, "X", "RED")
      NavigationHandler:AddBarButton(3, 3, nil, 2)
      NavigationHandler:SetBarButtonGraphics(2, "CHECK", "GREEN")
    end,
    NavigationOnUserEvent = function(self, a, b)
      if a == "SwitchTo" then
        self:SetInventoryCategory(b)
      elseif a == "exitScreen" then
        b = tonumber(b)
        if b == 1 then
          if InventoryHandler.TradeMode ~= nil then
            self:HideInventoryForTrade()
          else
            Trade.Cancel()
          end
        elseif b == 2 then
          if InventoryHandler.TradeMode then
            self:HideInventoryForTrade()
          else
            Trade.Accept()
            local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
            swf:Invoke("PlayerAccept")
          end
        end
      end
    end,
    OnUserEvent = function(a, b, c)
      if a == "OpenInventoryForTrade" then
      elseif a == "ItemAdded" then
        Trade.OfferItems(b, c)
      elseif a == "CoinOffer" then
        Trade.OfferCoins(b)
        TradeHandler:CancelAccept()
      elseif a == "requestInventoryData" then
        TradeHandler:Populate(tonumber(b), tonumber(c), DS_TRADE_INVENTORY_ITEMS, TradeHandler.MODE_INVENTORY)
      elseif a == "requestOffersData" then
        TradeHandler:Populate(tonumber(b), tonumber(c), DS_TRADE_MY_ITEMS, TradeHandler.MODE_OFFERS)
      elseif a == "requestOthersData" then
        TradeHandler:Populate(tonumber(b), tonumber(c), DS_TRADE_PARTNER_ITEMS, TradeHandler.MODE_OTHERS)
      elseif a == "changeViewMode" then
        Ui.SetUserOptionsValue("TradeWindowOptions", TradeHandler.Views[tonumber(c) + 1], b)
      elseif a == "SwitchTo" then
        TradeHandler:SetInventoryCategory(b)
      elseif a == "exitScreen" then
        b = tonumber(b)
        if b == 1 then
          Trade.Cancel()
        elseif b == 2 then
          Trade.Accept()
          local swf = GfxCtrl.Find(Ui.GetName(TradeHandler.swfName))
          swf:Invoke("PlayerAccept")
        end
      elseif TradeHandler[a] then
        TradeHandler[a](TradeHandler, b, c)
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[TradeHandler]\t" .. message)
      end
    end
  }
  Main_wndPlayerTradePS3_swfPlayerTradePS3_OnUserEvent = TradeHandler.OnUserEvent
end)()
