  function Main_wndGuildDialog_swfGuildDialog_OnUserEvent(a, b, c, d, e)
    if a == "closeWindow" then
      GuildDialog:Hide()
    elseif a == "sendGuildName" then
      Guild.Create(b)
      GuildDialog:Hide()
    elseif a == "renameGuild" then
      if b then
        Guild.Rename(SocialHandler.guildGuid, b)
        GuildDialog:Hide()
      else
      end
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    end
  end
  function Main_wndSocial_swfSocial_OnUserEvent(a, b, c, d, e)
    if a == "closeWindow" then
      SocialHandler:Hide()
    elseif a == "heightSet" then
      SocialHandler.height = b
      SocialHandler.actualHeight = tonumber(b)
      HudWindowManager:OnResizeWindow(SocialHandler)
    elseif a == "minimizeSocialWindow" then
      SocialHandler.minimized = 1
      SocialHandler.isMinimized = 1
      HudWindowManager:OnMinimizeWindow(SocialHandler)
    elseif a == "maximizeSocialWindow" then
      SocialHandler.minimized = nil
      SocialHandler.isMinimized = 0
      HudWindowManager:OnMaximizeWindow(SocialHandler)
    elseif a == "flipped" then
      HudWindowManager:OnResizeWindow(SocialHandler)
    elseif a == "inviteToHouse" then
      House.InviteToHouse(string.sub(b, 2))
    elseif a == "goToHouse" then
      House.RequestPlayerHouses(string.sub(b, 2), c)
    elseif a == "onFlyoutClose" then
      HousingSubMenu:Hide()
    elseif a == "startChat" then
      if Ui.IsUnderage() then
        chatHandler:ShowCannedChat(b)
      else
        GameDock:SetTextEntry(1, "/tell \"" .. b .. "\" ", 0)
      end
    elseif a == "locate" then
      Atlas:Show()
      Atlas:LocateFriend(b)
    elseif a == "teleportPlayerToFriend" then
      if Ui.TeleportToFriend then
        Ui.TeleportToFriend(b)
      end
    elseif a == "addFriend" then
      if Ui.AddFriend then
        SocialHandler:SetToFront()
        Ui.AddFriend(b)
      end
    elseif a == "removeFriend" then
      if Ui.RemoveFriend then
        SocialHandler:SetToFront()
        Ui.RemoveFriend(b)
      end
    elseif a == "ignore" then
      Ui.IgnorePlayer(b)
    elseif a == "unignore" then
      Ui.StopIgnoringPlayer(b)
    elseif a == "inviteToGroup" then
      Ui.InviteToGroup(b)
    elseif a == "getFriends" then
      SocialHandler:PopulateFriendsList()
    elseif a == "getAquaintances" then
      SocialHandler:PopulateAquaintancesList()
    elseif a == "getIgnored" then
      SocialHandler:PopulateIgnoredList()
    elseif a == "getGuild" then
      Ui.TriggerFirstTimeEvent("FtesGuild")
      SocialHandler:PopulateGuildList()
    elseif a == "inviteToGuild" then
      Guild.Invite(SocialHandler.guildGuid, string.sub(b, 2), 0)
    elseif a == "inviteToGuildByName" then
      Guild.Invite(SocialHandler.guildGuid, 0, b)
    elseif a == "removeFromGuild" then
      if Ui.GetPlayerGuid() == string.sub(b, 2) then
        Guild.Quit(SocialHandler.guildGuid)
        SocialHandler:ReturnToList()
      else
        Guild.Kick(SocialHandler.guildGuid, string.sub(b, 2))
      end
    elseif a == "promoteInGuild" then
      Guild.Promote(SocialHandler.guildGuid, string.sub(b, 2))
    elseif a == "demoteInGuild" then
      Guild.Demote(SocialHandler.guildGuid, string.sub(b, 2))
    elseif a == "showCreateGuild" then
      GuildDialog:Show()
    elseif a == "giveProp" then
    elseif a == "textFocus" then
      SocialHandler.textFocus = 1
      SocialHandler:StealFocus()
    elseif a == "textUnfocus" then
      SocialHandler.textFocus = 0
      SocialHandler:StealFocus()
    elseif a == "giveProp" then
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "init" then
      SocialHandler:Init()
    elseif a == "setSavedHeight" then
      Ui.SetUserOptionsValue("socialOptions", "savedSize", b)
    elseif a == "ASPrint" then
      print(a .. ": " .. b)
    end
  end
