  end
end)()
;(function()
  AvailableBuddiesListDsColumn = {Name = 0, Guid = 1}
  FriendPicker = {
    movieName = Ui.GetName("Main.wndFriendPicker.swfFriendPicker"),
    lobbySlotID = -1,
    visibleFriends = 0,
    isShown = false,
    Show = function(self, x, y, slotID)
      self.isShown = true
      if slotID ~= nil then
        self.lobbySlotID = slotID
      end
      local window = Window.Find(Ui.GetName("Main.wndFriendPicker"))
      local width, height = window:GetSize()
      window:SetPosition(x, y - height / 2)
      window:Show()
      WindowTweener:Create("Main.wndFriendPicker", "Width", nil, 250, 0.3)
      self.visibleFriends = 0
      self:PopulateList()
      NonModalContext:AddContext(self)
      Context:Push("FriendPicker", function()
        self:Hide()
      end)
      local guildsDs = DsTable.Find("BaseClient.Guilds")
      if guildsDs then
        local gnumRows = guildsDs:GetRowCount()
        if gnumRows > 0 then
          local m = GfxCtrl.Find(self.movieName)
          m:Invoke("ShowButtons")
        end
      end
      return self.visibleFriends
    end,
    Hide = function(self)
      if self.isShown == false then
        return
      end
      self.isShown = false
      WindowTweener:Create("Main.wndFriendPicker", "Width", nil, 0, 0.5, function()
        local w1 = Window.Find(Ui.GetName("Main.wndFriendPicker"))
        w1:Hide()
        NonModalContext:RemoveContext(self)
        Context:Pop()
        local m1 = GfxCtrl.Find(self.movieName)
        m1:Unload()
      end)
    end,
    OnResize = function(self)
    end,
    PopulateList = function(self)
      local ds = DsTable.Find("BaseClient.Matchmaking.AvailableBuddies")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        local m = GfxCtrl.Find(self.movieName)
        m:Invoke("deleteList")
        for i = 0, numRows - 1 do
          if Ui.GetPlayerGuid() ~= ds:GetData(i, AvailableBuddiesListDsColumn.Guid) then
            self.visibleFriends = self.visibleFriends + 1
            m:Invoke("addPickerFriend", i, ds:GetData(i, AvailableBuddiesListDsColumn.Name), "g" .. ds:GetData(i, AvailableBuddiesListDsColumn.Guid))
          end
        end
      end
    end
  }
  function Main_wndFriendPicker_swfFriendPicker_OnFocus(a, b, c, d)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndFriendPicker_swfFriendPicker_OnUserEvent(a, b, c, d, e)
    if a == "CloseWindow" then
      FriendPicker:Hide()
    elseif a == "FriendSelected" then
      FriendPicker:Hide()
      Lobby:FinishInviteOnSlot(FriendPicker.lobbySlotID, b, c)
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "ASPrint" then
      print(b)
    end
  end
end)()
;(function()
  Tutorial = {
    wndClickGobbler = Ui.GetName("Main.wndTutorialClickGobbler"),
    swfClickGobbler = Ui.GetName("Main.wndTutorialClickGobbler.swfClickGobbler"),
    swfTutorialMouse = Ui.GetName("Main.wndTutorialMouse.swfTutorialMouse"),
    wndTutorialMouse = Ui.GetName("Main.wndTutorialMouse"),
    swfTutorialWasd = Ui.GetName("Main.wndTutorialWasd.swfTutorialWasd"),
    wndTutorialWasd = Ui.GetName("Main.wndTutorialWasd"),
    swfTutorialDialog = Ui.GetName("Main.wndTutorialDialog.swfTutorialDialog"),
    wndTutorialDialog = Ui.GetName("Main.wndTutorialDialog"),
    swfTutorialArrow = Ui.GetName("Main.wndTutorialArrow.swfTutorialArrow"),
    wndTutorialArrow = Ui.GetName("Main.wndTutorialArrow"),
    MouseDirection = 1,
    m_ActiveTutorialObject = nil,
    wasInTutorial = false,
    inTutorial = false,
    questHelperIsShown = false,
    minimapIsShown = false,
    noDecline = nil,
    tutorialDialogLockForVO = nil,
    playSound = true,
    groupWindowShown = nil,
    NoAudioCardWaitTime = 15,
    StartTutorial = function(self)
      Logger:print("tutorial.lua", "+++StartTutorial+++")
      self.wasInTutorial = true
      self.inTutorial = true
      self.noDecline = 0
      self.minimapIsShown = false
      Tutorial.QuestHelperHide = true
      Tutorial:ClearMovementTutorialElements()
      GameDock:SlideOffScreen()
      MiniMap:Hide()
      SocialHandler:Hide()
      StarCounter:Hide()
      ObjectiveWindow:Clear()
      ObjectiveWindow:Hide()
      QuickItem:Hide()
      QuestHelper:HideHelper()
      LevelProgressBar:Hide()
      self.questHelperIsShown = false
      QuickItemTutorial.isShown = false
      WelcomeHandler.notShown = true
      GameDock.dockInitialized = 0
      Ui.CameraRotateOnce(10000, 4, 0.2)
      Context:Pop()
      GroupHandler:Hide()
      GameDockTutorial:Initialize()
      CollectionHandler:ListenToCollectionsDs()
      MiniMap:EnableButtons(0)
      HUD.inMiniGame = false
      MiniGameStatusHandler.currentMiniGameType = -1
      self.tutorialDialogLockForVO = nil
      self.CheckingCombatArrow1 = nil
      self.CheckingCombatArrow2 = nil
      NonModalContext:AddContext(self)
      self:RegisterQuestHelperDataSource()
      self:ContextAdd()
    end,
    GroupHandlerShow = function(self)
      GroupHandler:Init()
      GroupHandler:EncounterButtonModeSwitch(1)
      GroupHandler.Mode = 0
      GroupHandler:ModeSwitch(0)
      GroupHandler:Show()
    end,
    RestartTutorial = function(self, progress, movementTutorialComplete)
      self.wasInTutorial = true
      self.inTutorial = true
      Tutorial.QuestHelperHide = true
      QuickItemTutorial.isShown = false
      GameDockTutorial:Initialize()
      CollectionHandler:ListenToCollectionsDs()
      if progress ~= nil then
        if progress == 1 then
          self.questHelperIsShown = true
        elseif progress == 2 then
          self.questHelperIsShown = true
          self.minimapIsShown = true
          self.groupWindowShown = true
        elseif progress == 3 then
          self.questHelperIsShown = true
          self.dockTutorialShown = true
          self.minimapIsShown = true
          self.groupWindowShown = true
        end
        if self.questHelperIsShown == true then
          local ds = DsTable.Find("BaseClient.QuestData")
          if ds and ds:GetRowCount() > 0 then
            QuestHelper:PopulateHelper(tonumber(ds:GetData(0, 0)))
            QuestHelper:ShowHelper()
          end
        end
      end
      self.noDecline = 0
      Tutorial:RestoreUI()
      MiniMap:EnableButtons(0)
      Context:Pop()
      HUD.inMiniGame = false
      MiniGameStatusHandler.currentMiniGameType = -1
      NonModalContext:AddContext(self)
      self:RegisterQuestHelperDataSource()
      if movementTutorialComplete ~= nil then
        if movementTutorialComplete < 1 then
          self.tutorialDialogLockForVO = false
          self:ContextAdd()
        else
          self.tutorialDialogLockForVO = true
        end
      end
    end,
    RestartCombatTutorial = function(self)
      Context:Pop()
      self.tutorialDialogLockForVO = true
    end,
    EndTutorial = function(self)
      GameDock.tutorialMode = false
      Tutorial.inTutorial = false
      self.CheckingCombatArrow1 = nil
      self.CheckingCombatArrow2 = nil
      self.noDecline = nil
      self.tutorialDialogLockForVO = nil
      NonModalContext:RemoveContext(self)
    end,
    OnResize = function(self)
      if self.mouseIconVisible then
        self:MouseIcon()
      end
      if self.wasdIconVisible then
        self:CenterControls()
      end
    end,
    HideUI = function(self)
      QuickItem:Hide()
      Tutorial:HideQuestHelper()
      MiniMap:Hide()
      GroupHandler:Hide()
      GameDock:SlideOffScreen()
    end,
    RestoreUI = function(self)
      if self.groupWindowShown == true then
        self:GroupHandlerShow()
      else
        GroupHandler:Hide()
      end
      LevelProgressBar:Hide()
      ObjectiveWindow:Clear()
      StarCounter:Hide()
      SocialHandler:Hide()
      HUD.inMiniGame = false
      MiniGameStatusHandler.currentMiniGameType = -1
      if QuickItemTutorial.isShown == true then
        QuickItem:Show()
      end
      if self.questHelperIsShown == true and QuestHelper.gotoQuestNum ~= 0 then
        QuestHelper:ShowHelper()
      end
      if self.minimapIsShown == true then
        MiniMap.enabled = true
        MiniMap:Show()
      end
      if self.dockTutorialShown == true then
        GameDock:SlideOnScreen()
      else
        GameDock:SlideOffScreen()
      end
    end,
    SelectLastQuest = function(self)
      if self.questHelperIsShown == true then
        local ds = DsTable.Find("BaseClient.QuestData")
        if ds and ds:GetRowCount() > 1 then
          QuestHelper:PopulateHelper(tonumber(ds:GetData(1, 0)))
          QuestHelper:ShowHelper()
        end
      end
    end,
    SetQuestProgression = function(self, progress)
      if progress >= 3 then
        self.noDecline = nil
        return
      end
      self.noDecline = progress
    end,
    ContextAdd = function(self)
      Context:Push("tutorialmovementlock", function()
        return
      end)
    end,
    ContextRemove = function(self)
      Context:Pop()
    end,
    GobblerShow = function(self)
      local gobble = Window.Find(self.wndClickGobbler)
      local sw, sh = Window.GetCanvasSize()
      Ui.SetMovementEnabled(0)
      gobble:Show()
      gobble:SetPosition(0, 0)
      gobble:SetSize(sw, sh)
    end,
    GobblerHide = function(self)
      local gobble = Window.Find(self.wndClickGobbler)
      if self.tutorialDialogLockForVO == true then
        self:ContextRemove()
        Ui.SetKeyboardEnabled(1)
        if Client.ContextDepth == 0 then
          Ui.SetMovementEnabled(1)
        else
          Ui.SetMovementEnabled(Context.mList[1].Movement)
        end
      end
      gobble:Hide()
      GfxCtrl.Find(Ui.GetName("Main.wndClickGobbler.swfClickGobbler")):Unload()
    end,
    CinematicStart = function(self)
      Ui.SetKeyboardEnabled(0)
      Ui.SetMovementEnabled(0)
      Cinematic.Start()
    end,
    CinematicLookAt = function(self, x, y, z, time)
      if x ~= nil and y ~= nil and z ~= nil and time ~= nil then
        Cinematic.LookAt(x, y, z, time)
      end
    end,
    CinematicStop = function(self)
      Cinematic.End()
    end,
    RegisterQuestHelperDataSource = function(self)
      local ds = DsTable.Find("BaseClient.QuestObjectiveData")
      if ds then
        ds:EnableScriptEvents()
      end
    end,
    Grow = function(self, windowName, scale)
      local w = Window.Find(Ui.GetName(windowName))
      local width, height = w:GetSize()
      WindowTweener:Create(windowName, "Width", nil, width * scale, 0.3)
      WindowTweener:Create(windowName, "Height", nil, height * scale, 0.3)
    end,
    ShowArrow = function(self, x, y, rotation)
      local aw = Window.Find(self.wndTutorialArrow)
      local am = GfxCtrl.Find(self.swfTutorialArrow)
      am:Reset()
      local width, height = aw:GetSize()
      local xMod = width / 2
      local yMod = height / 2
      aw:SetPosition(x - xMod, y - yMod)
      if rotation ~= nil then
        am:Invoke("rotateArrow", rotation)
      end
      aw:Show()
      am:Invoke("point")
    end,
    HideArrow = function(self)
      local aw = Window.Find(self.wndTutorialArrow)
      aw:Hide()
    end,
    MouseIcon = function(self)
      local mw = Window.Find(self.wndTutorialMouse)
      local width, height = mw:GetSize()
      local sw, sh = Window.GetCanvasSize()
      if sw < 1280 then
        mw:SetPosition(sw - width - 15, sh / 2 - height / 2 + 10)
      else
        mw:SetPosition(sw - width + 25, sh / 2 - height / 2 + 150)
      end
      self.mouseIconVisible = true
    end,
    WasdIcon = function(self)
      local kw = Window.Find(self.wndTutorialWasd)
      local width2, height2 = kw:GetSize()
      local sw, sh = Window.GetCanvasSize()
      kw:SetPosition(25, sh / 2 - height2 / 2 + 150)
      self.wasdIconVisible = true
    end,
    CenterControls = function(self)
      local mw = Window.Find(self.wndTutorialMouse)
      local kw = Window.Find(self.wndTutorialWasd)
      local width, height = mw:GetSize()
      local width2, height2 = kw:GetSize()
      local sw, sh = Window.GetCanvasSize()
      mw:SetPosition(sw - width + 5, sh / 2 - height / 2)
      kw:SetPosition(sw - width + 25, sh / 2 - height2 / 2 + 300)
      self.mouseIconVisible = true
      self.wasdIconVisible = true
    end,
    w = 1,
    ReverseMovementMove = function(self)
      if self.inTutorial == true or FirstTimeEvent.CameraTutorial == true then
        local mm = GfxCtrl.Find(self.swfTutorialMouse)
        local km = GfxCtrl.Find(self.swfTutorialWasd)
        self.MouseDirection = self.MouseDirection * -1
        if self.MovingMouse == true then
          mm:Invoke("MoveMouse", 100 * self.MouseDirection, 1, "MouseMoveCompleted")
        else
          mm:Invoke("MoveMouse", 0 * self.MouseDirection, 1, "MouseMoveCompleted")
        end
        if self.w == 1 and self.MovingMouse ~= true and SoccerTutorial.RightClickOnly ~= true then
          km:Invoke("PressKey", "w")
          mm:Invoke("ReleaseButton", "left")
        end
        if self.w > 3 and self.MovingMouse ~= true and SoccerTutorial.RightClickOnly ~= true then
          self.w = 0
          km:Invoke("ReleaseKey", "w")
          mm:Invoke("ClickButton", "left")
        end
        if self.w == 1 and SoccerTutorial.RightClickOnly == true then
          mm:Invoke("ClickButton", "right")
          mm:Invoke("ReleaseButton", "left")
        end
        if self.w > 3 and SoccerTutorial.RightClickOnly == true then
          self.w = 0
          mm:Invoke("ReleaseButton", "right")
        end
        self.w = self.w + 1
      end
    end,
    ShowDialog = function(self, dialogString, callBackId, callBackIndex, callBackIndexMax, X, Y)
      Logger:print("tutorial.lua", dialogString)
      if MiniGameStatusHandler.panesUp then
        HUD:ShowMiniGameNormal()
      end
      local dw = Window.Find(self.wndTutorialDialog)
      local dm = GfxCtrl.Find(self.swfTutorialDialog)
      local width, height = dw:GetSize()
      local sw, sh = Window.GetCanvasSize()
      if X == nil then
        X = 10
      end
      if Y == nil then
        Y = sh / 2 - height / 2 + 25
      end
      local windowName = "Main.wndTutorialDialog"
      WindowTweener:Create(windowName, "X", nil, X, 0.3)
      WindowTweener:Create(windowName, "Y", nil, Y, 0.3)
      dw:Show()
      dm:Invoke("SetDialog", dialogString, callBackId, callBackIndex, callBackIndexMax)
      self:GobblerShow()
      if callBackIndex == 1 and self.playSound == true then
        self.playSound = nil
        Ui.StopSoundEmitter(self.dingName)
        self.dingName = Ui.PlaySoundFromDefinition(15656, -1, -1, 0)
        Ui.ChangeSoundEmitterVolume(self.dingName, 1)
      end
      self.dialogVisible = true
    end,
    CheckingCombatArrow = function(self)
      local sw, sh = Window.GetCanvasSize()
      local comBarWnd = Window.Find(GraphicActionBar.windowName)
      local comX, comY = comBarWnd:GetPosition()
      local comW, comH = comBarWnd:GetSize()
      if self.CheckingCombatArrow1 == true then
        Logger:print("tutorial.lua", "FIRST ARROW!")
        Tutorial:ShowArrow(comX + 55, sh - 75, 180)
      end
      if self.CheckingCombatArrow2 == true then
        Logger:print("tutorial.lua", "SECOND ARROW!")
        Tutorial:ShowArrow(comX + 138, sh - 75, 180)
      end
    end,
    OnVoComplete = function(self, sName)
      print("--> " .. tostring(self.VoName) .. " : " .. tostring(sName))
      self.VoName = nil
      local sw, sh = Window.GetCanvasSize()
      local windowName = "Main.wndQuestHelper"
      local w = Window.Find(Ui.GetName(windowName))
      local questX, questY = w:GetPosition()
      local questW, questH = w:GetSize()
      if self.tutorialDialogLockForVO == true then
        self:ContextRemove()
      end
      if self.firstArrowStopVo == true then
        Tutorial:ShowArrow(5, sh / 2 - sh / 3, 270)
        self.firstArrowStopVo = nil
      end
      if self.secondArrowStopVo == true then
        Tutorial:ShowArrow(sw - 5, sh / 2 - sh / 3, 90)
        self.secondArrowStopVo = nil
      end
      if self.firstCombatArrowStopVo == true then
        Tutorial:ShowArrow(comX + 55, sh - 75, 180)
        self.firstCombatArrowStopVo = nil
      end
      if self.secondCombatArrowStopVo == true then
        Tutorial:ShowArrow(comX + 138, sh - 75, 180)
        self.secondCombatArrowStopVo = nil
      end
      if self.NoEnableClose ~= true then
        self:EnableDialogClose()
      end
      self.NoEnableClose = nil
      self:GobblerHide()
    end,
    HideDialog = function(self)
      local dm = GfxCtrl.Find(self.swfTutorialDialog)
      dm:Invoke("HideDialog")
    end,
    CloseDialog = function(self)
      local dw = Window.Find(self.wndTutorialDialog)
      local dm = GfxCtrl.Find(self.swfTutorialDialog)
      dm:Reset()
      dw:Hide()
      self.playSound = true
      self.dialogVisible = false
    end,
    ClearAllTutorialElements = function(self)
      if self.tutorialDialogLockForVO == true then
        self:ContextRemove()
      end
      if PetsHandler.screenActive == true then
        PetsHandler:Hide()
      end
      if JobHandler.screenActive == true then
        JobHandler:Hide()
      end
      self:GobblerHide()
      CombatTutorial.needtochangeme = false
      self:CloseDialog()
      self:ResetMouse()
      self:ResetKeys()
      self:HideArrow()
      if self.questHelperExpanded then
        self:QuestHelperRestore()
      end
      if GameDockTutorial.m_GameDockExpanded then
        GameDockTutorial:GameDockRestore()
      end
      if self.miniMapExpanded then
        self:MiniMapRestore()
      end
      if self.m_ActiveTutorialObject ~= nil and self.m_ActiveTutorialObject.Complete ~= nil then
        self.m_ActiveTutorialObject:Complete()
        self.m_ActiveTutorialObject = nil
      end
      self:ClearMovementTutorialElements()
      self:HideRadialMenu()
      CombatFTEWindow:Hide()
    end,
    ClearMovementTutorialElements = function(self)
      self:ResetMouse()
      self:ResetKeys()
    end,
    QuestHelperExpand = function(self)
      Logger:print("tutorial.lua", "==>Quest Helper Expanding")
      NonModalContext:AddContext(FirstTimeEventHandler)
      Tutorial.QuestHelperHide = false
      local windowName = "Main.wndQuestHelper"
      local sw, sh = Window.GetCanvasSize()
      local w = Window.Find(Ui.GetName(windowName))
      local width, height = w:GetSize()
      local X = sw / 2 - width / 2
      local Y = sh / 2 - 270
      w:SetPosition(sw + width, Y)
      w:SetSize(300, 720)
      w:Show()
      WindowTweener:Create(windowName, "X", nil, X, 0.3)
      WindowTweener:Create(windowName, "Y", nil, Y, 0.3)
      WindowTweener:Create(windowName, "Width", nil, 450, 0.3)
      WindowTweener:Create(windowName, "Height", nil, 1080, 0.3, function()
        print("Function FUNC")
      end)
      self.questHelperExpanded = true
    end,
    QuestHelperRestore = function(self)
      Logger:print("tutorial.lua", "==>Quest Helper Restoring")
      NonModalContext:RemoveContext(FirstTimeEventHandler)
      local questHelper = "Main.wndQuestHelper"
      local w = Window.Find(Ui.GetName(questHelper))
      local width, height = w:GetSize()
      local sw, sh = Window.GetCanvasSize()
      local helperX = sw - 310
      w:Show()
      WindowTweener:Create(questHelper, "Width", nil, 300, 0.3)
      WindowTweener:Create(questHelper, "Height", nil, 720, 0.3)
      WindowTweener:Create(questHelper, "X", nil, helperX, 0.3)
      WindowTweener:Create(questHelper, "Y", nil, 305, 0.3)
      self.questHelperExpanded = false
