      radialMenu:setButton(0, 453, "Shop", nil)
      radialMenu:setButton(1, 138, "Talk", whocares)
      radialMenu:setButton(2, 1311, "Play Game", whocares)
      radialMenu:setButton(3, 20, "Quest", whocares)
