      WindowTweener:Create(windowName, "X", nil, X, 0.3)
      WindowTweener:Create(windowName, "Y", nil, Y, 0.3)
      WindowTweener:Create(windowName, "Width", nil, 1080, 0.3)
      WindowTweener:Create(windowName, "Height", nil, 1080, 0.3)
    end,
    SetIcon = function(self, iconID, followText)
      local swf = GfxCtrl.Find(self.swfTutorialDialog)
      swf:Invoke("SetIcon", iconID, followText)
    end,
    HideRadialMenu = function(self)
      radialMenu:setTutorialMode(0)
      radialMenuWnd = "Main.wndRadialMenu"
      local w = Window.Find(Ui.GetName(radialMenuWnd))
      w:SetProperty("Width", 1000)
      w:SetProperty("Height", 400)
      radialMenu:hide()
      radialMenu.tutorialMode = nil
    end,
    DisplayAdventurerUnlocked = function(self)
      NotificationHandler:JobLevelUp(19, Ui.GetString(2836), 1334, 1, 19)
    end,
    ResetMouse = function(self)
      local mw = Window.Find(self.wndTutorialMouse)
