      Logger:print("tutorial.lua", "*==>DisableDialogClose")
      dm:Invoke("DisableButton")
    end,
    Freedom = function(self)
      self.dontDisable = true
    end,
    EnableDialogClose = function(self, time)
      local dm = GfxCtrl.Find(self.swfTutorialDialog)
      Logger:print("tutorial.lua", "*==>EnableDialogClose")
      dm:Invoke("EnableButton", time)
    end,
    WelcomeMessage = function(self)
      GroupHandler:Hide()
      self:DisableDialogClose()
      self.NoEnableClose = true
      self:ShowTutorialDialog("PS3_STR_Move", 1)
    end,
    WelcomeAbbrev = function(self)
      GroupHandler:Hide()
      self:DisableDialogClose()
      self.NoEnableClose = true
      self:ShowTutorialDialog("Welcome2", 1)
    end,
    CameraFirstMovementTutorial = function(self)
      GroupHandler:Hide()
      self:ContextAdd()
      self.MovingMouse = true
      self:DisableDialogClose()
      self.firstArrowStopVo = true
      self.NoEnableClose = true
      self:ShowTutorialDialog("CameraFirst", 1)
    end,
    CameraMovementTutorial = function(self)
