    TutorialDialogEvent = function(self, a, b, c)
      if self.inTutorial ~= true then
        self:CallDelegate("TutorialDialogOnUserEvent", a, b, c)
      elseif a == "CloseDialog" then
        Tutorial:ClearAllTutorialElements()
      elseif a == "ShowTutorialDialog" then
        if tonumber(c) == 0 then
          return
        end
        Tutorial:ShowTutorialDialog(b, tonumber(c))
      end
    end
  }
  TutorialDialog = {
    wndName = "Main.wndTutorialDialog",
    swfName = "Main.wndTutorialDialog.swfTutorialDialog",
    Show = function(self)
