        wnd:SetProperty("ZLayer", SoccerTutorial.TutorialZLayer)
        wnd:SetProperty("Legend", SoccerTutorial.TutorialLegend)
      end
      swf:Unload()
      wnd:Hide()
    end,
    SetDialog = function(self, dialogString, callBackId, callBackIndex, callBackIndexMax)
      local swf = GfxCtrl.Find(Ui.GetName(TutorialDialog.swfName))
      if not swf then
        return
      end
      swf:Invoke("SetDialog", dialogString, callBackId, callBackIndex, callBackIndexMax)
    end,
    SetMultiIcons = function(self, ...)
      local swf = GfxCtrl.Find(Ui.GetName(TutorialDialog.swfName))
      if not swf then
        return
      end
      swf:Invoke("nextPageDD5Icons", ...)
    end,
