      self:SetMultiIcons(11986, Ui.GetString("DdIcons1"), 11984, Ui.GetString("DdIcons2"), 11983, Ui.GetString("DdIcons3"))
      self:SetDialog("SetDialog", 1, 1, 1)
    end
  }
  Delegate:AddSupportToClassObject(Tutorial, "Tutorial")
  function Main_wndTutorialDialog_swfTutorialDialog_OnUserEvent(...)
    Tutorial:TutorialDialogEvent(...)
  end
  function Main_wndTutorialDialog_swfTutorialDialog_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndTutorialClickGobbler_swfClickGobbler_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  TutorialDistanceCheck = {
    x = 0,
    y = 0,
    z = 0,
    closeDistSqr = 225,
    theCloseFunction = nil,
    SetCloseDistance = function(self, d)
      closeDistSqr = d * d
    end,
    SetCloseFunction = function(self, f)
      self.theCloseFunction = f
    end,
    StartTracking = function(self, f)
      x, y, z = Ui.GetPlayerLoc()
      if f then
        self:SetCloseFunction(f)
      end
      UpdateList.TutorialDistanceCheck = TutorialDistanceCheck
    end,
    ClearTracking = function(self)
      UpdateList.TutorialDistanceCheck = nil
    end,
    Update = function(self)
      local px, py, pz = Ui.GetPlayerLoc()
      local dsqr = (px - x) * (px - x) + (py - y) * (py - y) + (pz - z) * (pz - z)
      if dsqr > self.closeDistSqr and self.theCloseFunction then
        self.theCloseFunction()
        UpdateList.TutorialDistanceCheck = nil
      end
    end
  }
end)()
