      elseif a == "doTrick" and self.activeTutorial.id == self.tutorials[self.TRICK_TUTORIAL] then
        if self.activeTutorial.page == 2 and self.activeTutorial.id == PetTutorial.tutorials[PetTutorial.TRICK_TUTORIAL] then
