        local km = GfxCtrl.Find(Tutorial.swfTutorialWasd)
        local cs = GfxCtrl.Find(self.swfTutorialCtrl)
        local ss = GfxCtrl.Find(self.swfTutorialSpaceBar)
        self.MouseDirection = self.MouseDirection * -1
        mm:Invoke("MoveMouse", 0 * self.MouseDirection, 1, "MouseMoveCompleted")
        if self.w == 1 then
          mm:Invoke("ReleaseButton", "left")
          mm:Invoke("ClickButton", "right")
          km:Invoke("PressKey", "w")
          km:Invoke("ReleaseKey", "a")
          cs:Invoke("Release")
          ss:Invoke("Press")
          FishBoostBar:SetBoost(33)
          if self.DemoDerbTut2Active == true and self.doNotRepeatDDTut2 == false then
            DemoScore:Set(2)
          end
        elseif self.w == 3 then
          mm:Invoke("ClickButton", "left")
          mm:Invoke("ReleaseButton", "right")
          km:Invoke("ReleaseKey", "w")
          km:Invoke("PressKey", "d")
          cs:Invoke("Press")
          ss:Invoke("Release")
          FishBoostBar:SetBoost(66)
          if self.DemoDerbTut2Active == true and self.doNotRepeatDDTut2 == false then
            DemoScore:Set(4)
          end
        elseif self.w == 5 then
          mm:Invoke("ReleaseButton", "left")
          mm:Invoke("ClickButton", "right")
          km:Invoke("ReleaseKey", "d")
          km:Invoke("PressKey", "s")
          cs:Invoke("Release")
          ss:Invoke("Press")
          FishBoostBar:SetBoost(100)
          if self.DemoDerbTut2Active == true and self.doNotRepeatDDTut2 == false then
            DemoScore:Set(7)
          end
        elseif self.w >= 7 then
          self.w = -1
          mm:Invoke("ClickButton", "left")
          mm:Invoke("ReleaseButton", "right")
          km:Invoke("ReleaseKey", "s")
          km:Invoke("PressKey", "a")
          cs:Invoke("Press")
          ss:Invoke("Release")
          FishBoostBar:SetBoost(0)
          FishItemSlots:AddItem(5)
          if self.DemoDerbTut2Active == true and self.doNotRepeatDDTut2 == false then
            DemoScore:Set(6)
            self.doNotRepeatDDTut2 = true
            self.w = 0
            self:ClearFishingTutorialElements()
          end
        end
        self.w = self.w + 1
        self.MouseMoveCount = self.MouseMoveCount + 1
      end
    end,
    ResetMouse = function(self)
      local mw = Window.Find(Tutorial.wndTutorialMouse)
      local mm = GfxCtrl.Find(Tutorial.swfTutorialMouse)
      mw:Hide()
      mm:Unload()
    end,
    ResetKeys = function(self)
      local ww = Window.Find(Tutorial.wndTutorialWasd)
      local wm = GfxCtrl.Find(Tutorial.swfTutorialWasd)
      ww:Hide()
      wm:Unload()
    end,
    ResetSpaceBar = function(self)
      local sbw = Window.Find(self.wndTutorialSpaceBar)
      local ss = GfxCtrl.Find(self.swfTutorialSpaceBar)
      sbw:Hide()
      ss:Unload()
    end,
    ResetCtrl = function(self)
      local cw = Window.Find(self.wndTutorialCtrl)
      local cs = GfxCtrl.Find(self.swfTutorialCtrl)
      cw:Hide()
      cs:Unload()
    end,
    ClearFishingTutorialElements = function(self)
      self:ResetMouse()
      self:ResetKeys()
      self:ResetSpaceBar()
      self:ResetCtrl()
    end,
    DisplayAnimatedSplat = function(self)
      local sw, sh = Window.GetCanvasSize()
      local wndSplat = Window.Find(Ui.GetName("Main.wndFishingTutorialSplat"))
      wndSplat:SetPosition(sw / 3, sh / 3)
      wndSplat:Show()
