      local swfSplat = GfxCtrl.Find(Ui.GetName("Main.wndFishingTutorialSplat.swfFishingTutorialSplat"))
      wndSplat:Hide()
      swfSplat:Unload()
    end,
    FishingTutorial1 = function(self, index)
      pageCount = 8
      local sw, sh = Window.GetCanvasSize()
      local dw = Window.Find(Tutorial.wndTutorialDialog)
      local dm = GfxCtrl.Find(Tutorial.swfTutorialDialog)
      local width, height = dw:GetSize()
      local wndSplat = Window.Find("Main.wndFishingTutorialSplat")
      local wSplat, hSplat = wndSplat:GetSize()
      local xSplat, YSplat = wndSplat:GetPosition()
      local mm = GfxCtrl.Find(Tutorial.swfTutorialMouse)
      local km = GfxCtrl.Find(Tutorial.swfTutorialWasd)
      local cs = GfxCtrl.Find(self.swfTutorialCtrl)
      local ss = GfxCtrl.Find(self.swfTutorialSpaceBar)
      local wff = Window.Find(self.wndFishFinder)
      local x, y = wff:GetPosition()
      local w, h = wff:GetSize()
      if index == nil then
        index = 1
      end
      self.pageAt = index
      if index == 1 then
        FishFinder:Show()
        self:FishingArrow()
        self:ShowDialog(Ui.GetString("fishingTutorial0001"), "FishingTutorial1", index, pageCount)
      elseif index == 2 then
        FishingTutorial:HideImageLoader()
        self:FishingArrow()
        print("Showing Arrow")
        self:ShowDialog(Ui.GetString("fishingTutorial0002"), "FishingTutorial1", index, pageCount)
      elseif index == 3 then
        self:RemoveAnimatedSplat()
        FishingTutorial:ShowImageLoader(1)
        Tutorial:HideArrow()
        self:ShowDialog(Ui.GetString("fishingTutorial0003"), "FishingTutorial1", index, pageCount)
      elseif index == 4 then
        FishingTutorial:HideImageLoader()
        self:DisplayAnimatedSplat()
        self:FishingArrow()
        self:ShowDialog(Ui.GetString("fishingTutorial0004"), "FishingTutorial1", index, pageCount)
      elseif index == 5 then
        self:RemoveAnimatedSplat()
        self:ShowDialog(Ui.GetString("fishingTutorial0005"), "FishingTutorial1", index, pageCount)
      elseif index == 6 then
        FishingDistanceMeter:Hide()
        self:ShowDialog(Ui.GetString("fishingTutorial0006"), "FishingTutorial1", index, pageCount)
      elseif index == 7 then
        FishingTensionMeter:Hide()
        FishingReel:Hide()
        FishingDistanceMeter:Show()
        self:ShowDialog(Ui.GetString("fishingTutorial0007"), "FishingTutorial1", index, pageCount, sw / 2 - 200, sh / 2)
      elseif index == 8 then
        FishingDistanceMeter:Hide()
        FishingTensionMeter:Show()
        self:ShowDialog(Ui.GetString("fishingTutorial0008"), "FishingTutorial1", index, pageCount)
      end
    end,
    FishingArrow = function(self, index)
      if FishingTutorial.FishingIsActive ~= true then
        return
      end
      local dw = Window.Find(Tutorial.wndTutorialDialog)
      local dm = GfxCtrl.Find(Tutorial.swfTutorialDialog)
      local width, height = dw:GetSize()
      local wndSplat = Window.Find(Ui.GetName("Main.wndFishingTutorialSplat"))
      local wSplat, hSplat = wndSplat:GetSize()
      local xSplat, YSplat = wndSplat:GetPosition()
      local mm = GfxCtrl.Find(Tutorial.swfTutorialMouse)
      local km = GfxCtrl.Find(Tutorial.swfTutorialWasd)
      local cs = GfxCtrl.Find(self.swfTutorialCtrl)
      local ss = GfxCtrl.Find(self.swfTutorialSpaceBar)
      local wff = Window.Find(self.wndFishFinder)
      local x, y = wff:GetPosition()
      local w, h = wff:GetSize()
      if self.pageAt == 1 then
        print("Showing Arrow 1")
        Tutorial:ShowArrow(x + 78, h / 4 + 50, 0)
      elseif self.pageAt == 2 then
        print("Showing Arrow for step 2!")
        Tutorial:ShowArrow(x + 130, h / 4 + 50, 0)
      end
    end
  }
end)()
