;(function()
  GameDockTutorial = {
    m_GameDockExpanded = false,
    Initialize = function(self)
      local swf = GfxCtrl.Find(GameDock.swfName)
      swf:Reset()
      GameDock:Init()
    end,
    Show = function(self, index)
      self:GameDockExpand()
      Tutorial.dockTutorialShown = true
      Tutorial:ShowDialog(Ui.GetString(1238237), "GameDock", 1, 1)
      TutorialDistanceCheck:StartTracking(function()
        Tutorial:ClearAllTutorialElements()
      end)
    end,
    GameDockExpand = function(self)
      if self.m_GameDockExpanded == true then
        return
      end
      local w = Window.Find(Ui.GetName(GameDock.wndName))
      local sw, sh = Window.GetCanvasSize()
      local width, height = w:GetSize()
      local expandedWidth = 1280
      local expandedHeight = 320
      w:Show()
      WindowTweener:Create("Main.wndGameDock", "X", nil, sw / 2 - expandedWidth / 2, 0.3)
      WindowTweener:Create("Main.wndGameDock", "Y", nil, sh / 2 - expandedHeight / 2, 0.3)
      WindowTweener:Create("Main.wndGameDock", "Width", nil, expandedWidth, 0.3)
      WindowTweener:Create("Main.wndGameDock", "Height", nil, expandedHeight, 0.3)
      self.m_GameDockExpanded = true
      GameDock.tutorialMode = true
    end,
    GameDockRestore = function(self)
      if self.m_GameDockExpanded == false then
        return
      end
      Tutorial:HideArrow()
      local w = Window.Find(Ui.GetName(GameDock.wndName))
      local width, height = w:GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create("Main.wndGameDock", "X", nil, sw / 2 - 400, 0.3)
      WindowTweener:Create("Main.wndGameDock", "Y", nil, sh - 240, 0.3)
      WindowTweener:Create("Main.wndGameDock", "Width", nil, 800, 0.3)
      WindowTweener:Create("Main.wndGameDock", "Height", nil, 240, 0.3)
      self.m_GameDockExpanded = false
      GameDock.tutorialMode = false
    end,
    AddCollections = function(self)
    end,
    AddMyPets = function(self)
    end,
    Complete = function(self)
      Logger:print("gamedocktutorial.lua", "Gamedock Tutorial Complete")
      GameDock.tutorialMode = false
      self:GameDockRestore()
    end
  }
end)()
;(function()
  MiniMapTutorial = {
    mapWindow = "Main.wndMiniMap",
    m_MiniMapExpanded = false,
