      local sw, sh = Window.GetCanvasSize()
      local dw = Window.Find(Tutorial.wndTutorialDialog)
      local wWidth, wHeight = dw:GetSize()
      local TutorialWindow = Window.Find(Tutorial.wndTutorialDialog)
      local twndW, twndH = TutorialWindow:GetSize()
      if index == nil then
        index = 1
      end
      self.isShown = true
      if index == 1 then
        self:MiniMapExpand()
        Tutorial:ShowDialog(Ui.GetString(1238236), "MiniMap", index, pageCount)
      end
    end,
    ShowMiniMap = function(self)
      if self.tutorialDone == true then
        local sw, sh = Window.GetCanvasSize()
        local w = Window.Find(Ui.GetName(self.mapWindow))
        local width, height = w:GetSize()
        w:SetPosition(nil, -20)
        self:MiniMapRestore(1)
      end
    end,
    HideMiniMap = function(self)
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create(self.mapWindow, "Y", nil, -400, 0.3, function()
        local w = Window.Find(Ui.GetName(self.mapWindow))
        w:Hide()
      end)
    end,
    MiniMapExpand = function(self)
      local sw, sh = Window.GetCanvasSize()
      local windowName = "Main.wndMiniMap"
      local w = Window.Find(Ui.GetName(windowName))
      local width, height = w:GetSize()
      local X = sw - 600 - 10
      local Y = sh / 2 - 300
      local mapRadius = 600
      local centerPoint = sw / 2 - mapRadius / 2
      local swf = GfxCtrl.Find(MiniMap.miniMap)
      w:SetPosition(sw + width, Y)
      w:SetSize(300, 720)
      w:Show()
      WindowTweener:Create(windowName, "X", nil, X, 0.3, function()
        FirstTimeEventHandler:CheckArrow()
      end)
      WindowTweener:Create(windowName, "Y", nil, Y, 0.3, function()
        FirstTimeEventHandler:CheckArrow()
      end)
      WindowTweener:Create(windowName, "Width", nil, mapRadius, 0.3, function()
        FirstTimeEventHandler:CheckArrow()
      end)
      WindowTweener:Create(windowName, "Height", nil, mapRadius - 100, 0.3, function()
        FirstTimeEventHandler:CheckArrow()
      end)
      self.m_MiniMapExpanded = true
      if QuestHelper.isHelperShown == 1 then
        self.m_QuestHelperStateMinimized = QuestHelper.isHelperMinimized
        if self.m_QuestHelperStateMinimized == 1 then
          return
        end
        QuestHelper:MinimizeHelper()
      end
    end,
    MiniMapRestore = function(self)
      local w = Window.Find(Ui.GetName(self.mapWindow))
      local width, height = w:GetSize()
      w:Show()
      local swf = GfxCtrl.Find(MiniMap.miniMap)
      if swf then
        swf:Invoke("TutorialModeOff")
      end
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create(self.mapWindow, "X", nil, sw - 380, 0.3)
      WindowTweener:Create(self.mapWindow, "Y", nil, -20, 0.3)
      WindowTweener:Create(self.mapWindow, "Width", nil, 400, 0.3)
      WindowTweener:Create(self.mapWindow, "Height", nil, 300, 0.3)
      if forced then
        return
      end
      self.m_MiniMapExpanded = false
      if QuestHelper.isHelperShown == 1 then
        if self.m_QuestHelperStateMinimized == 1 then
          return
        end
        QuestHelper:MaximizeHelper()
      end
    end,
    Complete = function(self)
      Logger:print("minimaptutorial.lua", "MiniMap Tutorial Complete")
      self.tutorialDone = true
      self:MiniMapRestore()
      MiniMap:OnResize()
      self.m_QuestHelperStateMinimized = nil
      Tutorial.minimapIsShown = true
    end
  }
end)()
