    OnVideoCaptureReinit = function(self, err)
      Logger:print("video.lua", "Video Capture Reinit..." .. err)
    end,
    InitializeVideoLibrary = function(self)
      local s = VideoCapture.GetVideoLibraryMyVideosDirectory()
      if s == "" then
        s = "Videos"
      else
        s = s .. "\\FreeRealms"
      end
      VideoCapture.SetVideoLibraryWorkingDirectory(s)
      VideoCapture.SetVideoLibraryRootFilename(Ui.GetUserOptionsValue("VideoUpload", "VideoPrefix", VideoStrings.VIDEO_LABEL_DEFAULT_PREFIX))
      VideoCapture.ScanVideoLibraryWorkingDirectory(false)
    end,
    OnVideoCaptureStart = function(self, err)
      Logger:print("video.lua", "Video Capture Start..." .. err)
    end,
    OnVideoCaptureStop = function(self, err)
      Logger:print("video.lua", "Video Capture Stop..." .. err)
    end,
    GetVideoList = function(self)
      local video_count = VideoCapture.GetVideoLibraryVideoInfoCount()
      local video_list = {}
      local res = ""
      for var = 0, video_count - 1 do
        video_list[var] = VideoCapture.GetVideoLibraryVideoInfo(var)
        local s = ""
        for k, v in pairs(video_list[var]) do
          s = s .. k .. "~" .. v .. "|"
        end
        s = string.sub(s, -string.len(s), -2)
        res = res .. s .. "~~"
      end
      res = string.sub(res, -string.len(res), -3)
    end,
    OnVideoCaptureStatus = function(self, msecElapsed)
    end,
    OnVideoCaptureDestFileDone = function(self, videoInfoIndex)
      Logger:print("video.lua", "Video Capture DestFileDone..." .. videoInfoIndex)
      VideoHandler:GetVideoList()
    end,
    AuthenticateUser = function(self, username, password)
      return false
    end,
    OnVideoUploadAuthenticate = function(self, err)
    end,
    SetVideoPath = function(self)
    end,
    UploadVideo = function(self, index, file, title, username, password)
      if VideoHandler.isUploadBusy ~= true then
        VideoHandler.curFile = VideoCapture.GetVideoLibraryWorkingDirectory() .. "\\" .. file .. ".avi"
        VideoHandler.curIndex = index
        VideoHandler.curTitle = title
        VideoHandler.curUsername = username
        VideoHandler.curPassword = password
        m = GfxCtrl.Find(self.swfVideoCaptureHud)
        VideoHandler:AuthenticateUser(username, password)
      else
        Logger:print("video.lua", "Upload object busy...cannot send request at this time")
      end
    end,
    OnVideoUploadProgress = function(self, pcnt)
      m = GfxCtrl.Find(self.swfVideoCaptureHud)
      m:Invoke("handleYoutubeUploadProgress", pcnt)
    end,
    OnVideoUploadPost = function(self, err)
      Logger:print("video.lua", "OnVideoUploadPost: " .. tostring(err))
      VideoHandler.isUploadBusy = false
      m = GfxCtrl.Find(self.swfVideoCaptureHud)
      if err == -19 then
        return
      end
      if err == -17 or err == -11 then
        Logger:print("video.lua", self:GetError(err))
        m:Invoke("handleYoutubeBadLogin")
      elseif err ~= 0 then
        Logger:print("video.lua", self:GetError(err))
        m:Invoke("handleError", self:GetError(err))
      else
        Logger:print("video.lua", "Video succesfully uploaded to YouTube.")
        VideoCapture.SetVideoLibraryVideoInfoParam(VideoHandler.curIndex, "isUploaded", "1")
        VideoCapture.SaveVideoLibraryVideoInfo(VideoHandler.curIndex)
        m:Invoke("handleYoutubeUploadComplete")
      end
    end,
    OnVideoUploadUninit = function(self, err)
      Logger:print("video.lua", "Youtube Upload Object Deinitialized")
    end,
    StopUpload = function(self)
      VideoUpload.VideoUploadCancelAllRequests()
      m = GfxCtrl.Find(self.swfVideoCaptureHud)
      m:Invoke("handleYoutubeUploadStop")
    end,
    DeleteVideo = function(self, index)
      val = VideoCapture.DeleteVideoLibraryVideo(index)
      VideoHandler:GetVideoList()
    end,
    SetUserOptions = function(self)
      m = GfxCtrl.Find(self.swfVideoCaptureHud)
      username = Ui.GetUserOptionsValue("VideoUpload", "YoutubeUsername", VideoStrings.VIDEO_LABEL_DEFAULT_USERNAME)
      filename_prefix = Ui.GetUserOptionsValue("VideoUpload", "VideoPrefix", VideoStrings.VIDEO_LABEL_DEFAULT_PREFIX)
    end,
    IsAdminClient = function()
      if Admin ~= nil then
        return true
      end
      return false
    end,
    StealFocus = function(self)
      if VideoHandler.winFocus == 0 then
        Window.SetFocus()
      else
        local w = Window.Find(Ui.GetName("Main.wndVideoCaptureHud"))
        w:SetFocus()
      end
    end
  }
  function Main_wndVideoCaptureHud_swfVideoCaptureHud_OnUserEvent(a, b, c, d, e, f, g)
    if a == "StartRecording" then
      local next_filename = VideoCapture.GetNextVideoLibraryFileName()
      VideoCapture.SetVideoCaptureOutputFile(VideoCapture.GetVideoLibraryWorkingDirectory() .. "\\" .. next_filename)
      VideoCapture.StartVideoCapture()
    elseif a == "StopRecording" then
      VideoCapture.StopVideoCapture()
    elseif a == "StopUploading" then
      Logger:print("video.lua", "stop uploading!")
      VideoHandler:StopUpload()
    elseif a == "SetVideoCaptureResolution" then
      VideoCapture.SetVideoCaptureResolution(b)
      Ui.SaveUserOptions()
    elseif a == "init" then
      VideoCapture.InitVideoCapture()
    elseif a == "getvideolist" then
      VideoHandler:GetVideoList()
    elseif a == "deinit" then
      VideoCapture.UninitVideoCapture()
    elseif a == "init_upload" then
      VideoUpload.VideoUploadInit()
    elseif a == "deinit_upload" then
      VideoUpload.VideoUploadUninit()
    elseif a == "setYoutubeUsername" then
      Ui.SetUserOptionsValue("VideoUpload", "YoutubeUsername", b)
      Ui.SaveUserOptions()
    elseif a == "setYoutubePrefix" then
      Ui.SetUserOptionsValue("VideoUpload", "VideoPrefix", b)
      Ui.SaveUserOptions()
      VideoHandler:InitializeVideoLibrary()
    elseif a == "getYoutubeUserOptions" then
      VideoHandler:SetUserOptions()
    elseif a == "UploadVideo" then
      VideoHandler:UploadVideo(b, c, d, e, f)
    elseif a == "handleDeleteVideo" then
      VideoHandler:DeleteVideo(b)
    elseif a == "setVideoExpanded" then
      VideoHandler:SetPos(1)
    elseif a == "setVideoCollapsed" then
      VideoHandler:SetPos(0)
    elseif a == "winFocus" then
      VideoHandler.winFocus = 1
      VideoHandler:StealFocus()
    elseif a == "winUnfocus" then
      VideoHandler.winFocus = 0
      VideoHandler:StealFocus()
    elseif a == "AS_Print" then
      Logger:print("video.lua", "[AS_Print]> " .. b)
    end
  end
  function Main_wndVideoCaptureHud_swfVideoCaptureHud_OnFocus(a, b, c, d, e, f, g)
    if a == "1" and VideoHandler.winFocus == 0 then
      Window.SetFocus()
    end
  end
end)()
;(function()
  RecipeHandler = {
    wndDetails = Ui.GetName("Main.wndCollectionCookingDetails"),
    swfDetails = Ui.GetName("Main.wndCollectionCookingDetails.swfCollectionDetails"),
    recipeDsName = "BaseClient.Recipes",
    recipeDetailsDsName = "BaseClient.RecipeComponents",
    recipeDisplayed = false,
    screenActive = nil,
    GetWindow = function()
      return Window.Find(RecipeHandler.wndDetails)
    end,
    GetSwf = function()
      return GfxCtrl.Find(RecipeHandler.swfDetails)
    end,
    Populate = function(self, swfName)
      local swf = GfxCtrl.Find(Ui.GetName(swfName))
      local ds = DsTable.Find(self.recipeDsName)
      swf:Invoke("SetString", 0, Ui.GetString("RecipeBrowserIngredients"))
      swf:Invoke("SetString", 1, "/")
      swf:Invoke("SetMode", 4)
      swf:Invoke("setIconType", HUD.supressIconTint)
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          swf:Invoke("AddRecipe", tonumber(ds:GetData(i, 0)), tostring(ds:GetData(i, 1)), tostring(ds:GetData(i, 2)), tonumber(ds:GetData(i, 3)), tonumber(ds:GetData(i, 4)), tostring(ds:GetData(i, 5)), tonumber(ds:GetData(i, 7)), tonumber(ds:GetData(i, 9)), tonumber(ds:GetData(i, 10)), tonumber(ds:GetData(i, 11)), tonumber(ds:GetData(i, 12)), tonumber(ds:GetData(i, 13)), tonumber(ds:GetData(i, 14)), tonumber(ds:GetData(i, 15)), tonumber(ds:GetData(i, 16)))
        end
      end
    end,
    Show = function(self)
      if self.screenActive ~= true or self.recipeDisplayed == true then
        Context:Push("RecipeHandler", function()
          RecipeHandler:ReturnToBrowser()
        end)
        self:SelectFirstRecipe()
        BrowserHandler.windowName = "Recipes"
        BrowserHandler:Show(RecipeHandler, Ui.GetString(200801), Ui.GetString("UI_Browser_RecipeSubtext"), Ui.GetString("UI_Browser_ClickSwitchRecipes"))
        BrowserHandler:ExpandBrowser()
        BrowserHandler:Connect(self)
        self.screenActive = true
        HUD:hideMain()
        self.EventHandler()
        Ui.TriggerFirstTimeEvent("FtesRecipes")
      end
    end,
    Hide = function(self)
      Context:Pop()
      RecipeHandler:HideRecipe()
      HUD:showMain()
      BrowserHandler:Hide()
      BrowserHandler:Disconnect(self)
      self.screenActive = false
    end,
    BrowserOnUserEvent = function(self, a, b)
      if a == "SelectRecipe" then
        RecipeHandler:ShowRecipe(tonumber(b))
      elseif a == "ExpandedBrowser" then
        Logger:print("recipe.lua", "browser expaned")
        RecipeHandler:MinRecipe()
      elseif a == "CompressBrowser" then
        if self.recipeDisplayed ~= true then
          RecipeHandler:CloseRecipes()
        end
      elseif a == "CloseBrowser" then
        Logger:print("recipe.lua", "closing browser")
        RecipeHandler:CloseRecipes()
      else
        Logger:print("recipe.lua", a)
      end
    end,
    SelectFirstRecipe = function(self)
      local ds = DsTable.Find(self.recipeDsName)
      if ds and ds:GetRowCount() > 0 then
        local id = tonumber(ds:GetData(0, 0))
        if id ~= nil then
          RecipeHandler:ShowRecipe(id, true)
        end
      end
    end,
    ShowRecipe = function(self, ID, override)
      local needID = false
      if ID then
      else
        needID = true
      end
      local mdetail = GfxCtrl.Find(self.swfDetails)
      if self.recipeDisplayed == true then
        return
      end
      mdetail:Reset()
      mdetail:Invoke("setIconType", HUD.supressIconTint)
      local ds = DsTable.Find(self.recipeDsName)
      if ds then
        if needID then
          ID = tonumber(ds:GetData(0, 0))
        end
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local id = tonumber(ds:GetData(i, 0))
          if ID == id then
            mdetail:Invoke("displayRecipeData", ds:GetData(i, 0), ds:GetData(i, 1), ds:GetData(i, 2), ds:GetData(i, 3), ds:GetData(i, 4), ds:GetData(i, 7), ds:GetData(i, 8))
            break
          end
        end
      end
      Recipe.SelectRecipe(ID)
      local ds = DsTable.Find(self.recipeDetailsDsName)
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          mdetail:Invoke("setRecipeData", ds:GetData(i, 0), ds:GetData(i, 1), ds:GetData(i, 2), ds:GetData(i, 3), tonumber(ds:GetData(i, 4)), tonumber(ds:GetData(i, 5)), tonumber(ds:GetData(i, 6)))
        end
      end
      if override then
        return
      end
      self.recipeDisplayed = true
      local w1 = Window.Find(self.wndDetails)
      local width1, height1 = w1:GetSize()
      local sw, sh = Window.GetCanvasSize()
      w1:SetPosition(sw / 2 - width1 / 2, sh)
      w1:Show()
      BrowserHandler:Hide(1, 1)
      BrowserHandler:Disconnect(self)
      self.screenActive = false
      WindowTweener:Create("Main.wndCollectionCookingDetails", "Y", nil, sh / 2 - height1 / 2 + 25, 0.3)
      HUD:PlaySound("ShowWindow")
    end,
    ReturnToBrowser = function(self)
      Logger:print("recipe.lua", "returning to browser")
      self.screenActive = true
      RecipeHandler:HideRecipe()
      BrowserHandler.windowName = "Recipes"
      BrowserHandler:Show(RecipeHandler, Ui.GetString(200801), Ui.GetString("UI_Browser_RecipeSubtext"), Ui.GetString("UI_Browser_ClickSwitchRecipes"))
      BrowserHandler:ExpandBrowser()
      BrowserHandler:Connect(self)
    end,
    CloseRecipes = function(self)
      Context:Pop()
      self.screenActive = false
      if self.recipeDisplayed == true then
        RecipeHandler:HideRecipe()
      end
      RecipeHandler:Hide()
    end,
    HideRecipe = function(self)
      local w1 = Window.Find(self.wndDetails)
      local width1, height1 = w1:GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create("Main.wndCollectionCookingDetails", "Y", nil, sh, 0.3, function()
        RecipeHandler.GetSwf():Unload()
        RecipeHandler.GetWindow():Hide()
      end)
      self.recipeDisplayed = false
      HUD:PlaySound("HideWindow")
    end,
    MinRecipe = function(self)
      local w1 = Window.Find(self.wndDetails)
      local width1, height1 = w1:GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create("Main.wndCollectionCookingDetails", "Y", nil, sh, 0.3)
      self.recipeDisplayed = false
    end,
    EventHandler = function(self)
      function Main_wndCollectionCookingDetails_swfCollectionDetails_OnUserEvent(a, b, c)
        if a == "selectRecipe" then
          RecipeHandler:CloseRecipes()
          Ui.RecipeStart(b)
        elseif a == "openCollectionsBrowser" then
          if RecipeHandler.screenActive == false then
            Logger:print("recipe.lua", "returning to browser")
            RecipeHandler:ReturnToBrowser()
          end
        elseif a == "PlaySound" then
          HUD:PlaySound(b)
        elseif a == "AS_Print" then
          Logger:print("recipe.lua", b)
        end
      end
      function Main_wndCollectionCookingDetails_swfCollectionDetails_OnFocus(a)
        if a == "1" then
          Window.SetFocus()
        end
      end
    end
  }
end)()
