;(function()
  GamePanels = {
    isUp = {},
    wndName = {
      nil,
      Ui.GetName("Mockups.wndBubbles"),
      Ui.GetName("Mockups.wndInventory"),
      Ui.GetName("Mockups.wndMiniMap"),
      Ui.GetName("Main.wndJobs"),
      Ui.GetName("Mockups.wndColl"),
      Ui.GetName("Mockups.wndSocials"),
      Ui.GetName("Mockups.wndPets"),
      Ui.GetName("Mockups.wndCards")
    },
    Realname = {
      nil,
      "Chat bubbles",
      "Inventory",
      "Minimap",
      "Jobs",
      "Collections",
      "Socials",
      "Pets",
      "Card Game"
    },
    pos = {
      "lt",
      "cc",
      "lt",
      "rt",
      "lt",
      "lt",
      "rc",
      "lt",
      "lt"
    },
    onlyOne = {
      1,
      0,
      1,
      0,
      1,
      1,
      2,
      1,
      1
    }
  }
  function GamePanels:Toggle(x)
    if x ~= nil then
      x = tonumber(x)
      local w = Window.Find(self.wndName[x])
      if w ~= nil then
        if self.isUp[x] then
          w:Hide()
          self.isUp[x] = false
        else
          local WindowWidth, WindowHeight = w:GetSize()
          local ScreenWidth, ScreenHeight = Window.GetCanvasSize()
          self.isUp[x] = true
          w:Show()
          if self.onlyOne[x] ~= 0 then
            local i
            for i = 1, 8 do
              if i ~= x and self.onlyOne[i] == self.onlyOne[x] and self.isUp[i] then
                local w = Window.Find(self.wndName[i])
                if w ~= nil then
                  w:Hide()
                  self.isUp[i] = false
                end
              end
            end
          end
          if self.pos[x] == "lt" then
            w:setPosition(0, 0)
          elseif self.pos[x] == "cc" then
            w:setPosition((ScreenWidth - WindowWidth) / 2, (ScreenHeight - WindowHeight / 2) / 2)
          elseif self.pos[x] == "rt" then
            w:setPosition(ScreenWidth - WindowWidth, 0)
          elseif self.pos[x] == "cb" then
            w:setPosition((ScreenWidth - WindowWidth) / 2, ScreenHeight - WindowHeight)
          elseif self.pos[x] == "rc" then
            w:setPosition(ScreenWidth - WindowWidth, (ScreenHeight - WindowHeight / 2) / 2)
          end
          w:moveToFront()
        end
      end
    end
  end
  function Mockups_wndColl_OnClose(a, b)
    GamePanels.isUp[6] = false
  end
  function Mockups_wndInventory_OnClose(a, b)
    GamePanels.isUp[3] = false
  end
  function Mockups_wndCards_OnClose(a, b)
    GamePanels.isUp[9] = false
  end
end)()
