      if theItemWindow ~= nil then
        theItemWindow:Show()
      end
      theMovie:Reset()
      self:OnResize()
      self:SetVisibility(0)
      self:ShowItemDock()
      ActionDock_PS3:ShowDock()
      theWindow:SetProperty("Legend", 0)
      theWindow:SetProperty("ZLayer", 16)
      theMovie:Invoke("SetPortrait", tostring(GetMyId()))
    end,
    Hide = function(self)
      ToolTipHandler:HideToolTip()
      local theWindow = Window.Find(self.windowName)
      if theWindow ~= nil then
        theWindow:Hide()
      end
      local theItemWindow = Window.Find(self.itemWindowName)
      if theItemWindow ~= nil then
        theItemWindow:Hide()
      end
    end,
    SetVisibility = function(self, visible, fromFlash)
      Logger:print("gamedock.lua", "Setting ps3dock visibility to " .. visible)
      if MinigameStartScreen.visible == true then
        ToolTipHandler:HideToolTip()
        GameDock:KillFocus()
        return
      end
      if fromFlash ~= true then
        Logger:print("gamedock.lua", "Setting Visibility in Flash")
        local theMovie = GfxCtrl.Find(self.movieName)
        theMovie:Invoke("luaSetVisibility", visible)
      end
      if visible == 1 then
        self:HideItemDock()
        ActionDock_PS3:HideDock()
        self:ShowLegend()
      else
        self:ShowItemDock()
        ActionDock_PS3:ShowDock()
        self:HideLegend()
        ToolTipHandler:HideToolTip()
      end
    end,
    ShowItemDock = function(self)
      local theMovie = GfxCtrl.Find(self.itemSwfName)
      theMovie:Invoke("showWindow")
    end,
    HideItemDock = function(self)
