      if mode == 1 then
        if currentNavSelection == 3 then
          FriendsWidget:Hide()
        end
        if currentNavSelection == 4 then
        end
        chatHandler:ToggleCannedChat(0)
        chatHandler:SelectCurrentCannedChatOption(1)
      elseif mode == 2 then
        if currentNavSelection == 3 then
          FriendsWidget:Hide()
        end
        if currentNavSelection == 4 then
        end
        chatHandler:ToggleCannedChat(1)
        chatHandler:SelectCurrentCannedChatOption(129)
      elseif mode == 3 then
        if currentNavSelection == 1 or currentNavSelection == 2 then
          chatHandler:HideCannedChat()
        end
        if currentNavSelection == 4 then
        end
        FriendsWidget:Show()
      elseif mode == 4 then
        if currentNavSelection == 1 or currentNavSelection == 2 then
          chatHandler:HideCannedChat()
        end
        if currentNavSelection == 3 then
          FriendsWidget:Hide()
        end
        Ui.LuaRequestVirtualKeyboard()
      end
