    NavigationExit = function(self)
      NavigationHandler:Hide()
      NavigationHandler:Disconnect(self)
      if NavigationHandler.currentNavMode == 1 then
        chatHandler:HideCannedChat()
        SocialHandler:Toggle()
      elseif NavigationHandler.currentNavMode == 2 then
        MarketplaceHandler:Hide(nil, true)
      elseif NavigationHandler.currentNavMode == 3 then
      end
      NavigationHandler.currentNavMode = 0
      NavigationHandler.currentNavSelection = 0
    end,
    NavigationOnUserEvent = function(self, a, b)
      if a == "exitScreen" then
        self:NavigationExit()
        GameDock_PS3:SetVisibility(1)
      elseif a == "SwitchTo" then
        if self.currentNavMode == 1 then
          GameDock_PS3:ChatMode(tonumber(b))
        elseif self.currentNavMode == 2 then
          GameDock_PS3:StoreMode(tonumber(b))
        elseif self.currentNavMode == 3 then
          GameDock_PS3:QuestsMode(tonumber(b))
        end
      end
    end,
    OnNavigationShown = function(self)
      NavigationHandler:HighlightButton(1, 1)
    end,
    BrowserOnUserEvent = function(self, a, b)
      if a == "SelectJob" then
        Logger:print("gamedock.lua", "job selected")
        JobHandler.currentActiveProfileID = Ui.GetActiveProfileId()
        JobBrowser:CloseBrowser()
        JobBrowser:Hide()
        JobBrowser:Disconnect()
        GameDock_PS3:SetVisibility(1)
      elseif a == "CloseBrowser" then
        Logger:print("gamedock.lua", "job browser exited")
        JobBrowser:CloseBrowser()
        JobBrowser:Hide()
        JobBrowser:Disconnect()
        GameDock_PS3:SetVisibility(1)
      end
    end
  }
