  GameDock = {
    DISABLED_STATE = 0,
    NORMAL_STATE = 1,
    SUBMENU_STATE = 2,
    MINIGAME_STATE = 3,
    MINIGAME_SUBMENU_STATE = 4,
    state = 0,
    MIN_RES_HEIGHT = 720,
    wndName = "Main.wndGameDock",
    swfName = "Main.wndGameDock.swfGameDock",
    dockInitialized = 0,
    isShown = 0,
    isOnScreen = 0,
    screenAlignment = "center",
    disabled = false,
    lockedOut = false,
    dockMode = -1,
    dockModeFull = 1,
    dockModeMinigame = 2,
    dockModeCombat = 3,
    countUpSc = 1,
    walletValue = 0,
    m_indexOfCash = nil,
    m_isFocused = 0,
    m_startText = "",
