    m_isProcessingChatCommand = false,
    GetWindow = function(self)
      return Window.Find(self.wndName)
    end,
    GetSwf = function(self)
      return GfxCtrl.Find(self.swfName)
    end,
    SetState = function(self, s)
      local prevState = self.state
      self.state = s
      if Fishing.underwater == true then
        return
      end
      HotKeyEvents.override = false
      if HUD.isInStartingZone then
        self:ShowTopPart(1)
        self:SetButtonsEnabled(0, 1, 0, 0, 0, 0)
        return
      end
      GameDock_PS3:EnableButton(0)
      GameDock_PS3:EnableButton(1)
      GameDock_PS3:EnableButton(2)
      GameDock_PS3:EnableButton(3)
      GameDock_PS3:EnableButton(4)
      GameDock_PS3:EnableButton(5)
      GameDock_PS3:EnableButton(6)
      GameDock_PS3:EnableButton(7)
      GameDock_PS3:EnableButton(8)
      if s == self.DISABLED_STATE then
        HotKeyEvents.override = true
        self:ShowTopPart(0)
        self:SetButtonsEnabled(0, 0, 0, 0, 0, 0)
        GameDock_PS3:DisableButton(0)
        GameDock_PS3:DisableButton(1)
        GameDock_PS3:DisableButton(2)
        GameDock_PS3:DisableButton(3)
        GameDock_PS3:DisableButton(4)
        GameDock_PS3:DisableButton(5)
        GameDock_PS3:DisableButton(6)
        GameDock_PS3:DisableButton(7)
        GameDock_PS3:DisableButton(8)
      elseif s == self.NORMAL_STATE or s == self.SUBMENU_STATE then
        self:ShowTopPart(1)
        if Housing.isInInstance and Housing.editMode then
          self:ShowTopPart(0)
          self:SetButtonsEnabled(0, 0, 0, 0, 0, 0)
          GameDock_PS3:DisableButton(0)
          GameDock_PS3:DisableButton(7)
        elseif MarketplaceHandler.boolIsShown then
          self:ShowTopPart(0)
          self:SetButtonsEnabled(0, 0, 0, 0, 0, 0)
        elseif Housing.isInInstance then
          self:SetButtonsEnabled(1, 1, 1, 1, 1, 0)
          GameDock_PS3:DisableButton(1)
          GameDock_PS3:DisableButton(7)
        else
          self:SetButtonsEnabled(1, 1, 1, 1, 1, 1)
        end
        if s == self.SUBMENU_STATE then
          self:ShowTopPart(0)
        end
      elseif s == self.MINIGAME_STATE then
        local mgsh = MiniGameStatusHandler
        if (mgsh:GetCurrentMiniGameType() == mgsh.FISHING_TYPE or ObjectiveWindow.showInHub == true) and SnowballFight.inSnowballFight == false then
          self:ShowTopPart(1)
          self:SetButtonsEnabled(1, 0, 1, 0, 1, 0)
          GameDock_PS3:DisableButton(1)
          GameDock_PS3:DisableButton(3)
          GameDock_PS3:DisableButton(4)
          GameDock_PS3:DisableButton(6)
          GameDock_PS3:DisableButton(7)
          GameDock_PS3:DisableButton(8)
        elseif mgsh.currentMiniGameType == mgsh.SCAVENGER_HUNT_TYPE or mgsh.currentMiniGameType == mgsh.SAMPLE_TYPE then
          self:ShowTopPart(1)
          self:SetButtonsEnabled(0, 0, 1, 0, 0, 0)
          GameDock_PS3:DisableButton(0)
          GameDock_PS3:DisableButton(1)
          GameDock_PS3:DisableButton(2)
          GameDock_PS3:DisableButton(3)
          GameDock_PS3:DisableButton(4)
          GameDock_PS3:DisableButton(5)
          GameDock_PS3:DisableButton(6)
          GameDock_PS3:DisableButton(7)
          GameDock_PS3:DisableButton(8)
          if 0 < Pet.GetActivePetId() then
            Pet.Dismiss()
          end
        elseif mgsh.currentMiniGameType == mgsh.FLASH_TYPE or mgsh.currentMiniGameType == mgsh.CHESS_TYPE or mgsh.currentMiniGameType == mgsh.CHECKERS_TYPE or mgsh.currentMiniGameType == mgsh.MATCH_THREE_TYPE or mgsh.currentMiniGameType == mgsh.MIMIC_TYPE or mgsh.currentMiniGameType == mgsh.TOWER_DEFENSE_TYPE or mgsh.currentMiniGameType == mgsh.TILE_MATCHING_TYPE then
          self:ShowTopPart(0)
          self:SetButtonsEnabled(0, 0, 0, 0, 0, 0)
        elseif mgsh.currentMiniGameType == mgsh.COMBAT_TYPE then
          self:ShowTopPart(1)
          self:SetButtonsEnabled(1, 0, 1, 0, 0, 0)
          GameDock_PS3:DisableButton(1)
          GameDock_PS3:DisableButton(3)
          GameDock_PS3:DisableButton(4)
          GameDock_PS3:DisableButton(5)
          GameDock_PS3:DisableButton(6)
          GameDock_PS3:DisableButton(7)
          GameDock_PS3:DisableButton(8)
        elseif mgsh.currentMiniGameType == mgsh.RACING_TYPE or mgsh.currentMiniGameType == mgsh.DEMO_DERBY_TYPE then
          GameDock:Hide()
        elseif mgsh.currentMiniGameType == mgsh.SOCCER_TYPE or mgsh.currentMiniGameType == mgsh.PIRATES_TYPE then
          GameDock:Hide()
        end
      elseif s == self.MINIGAME_SUBMENU_STATE then
        self:ShowTopPart(0)
        self:SetButtonsEnabled(0, 0, 1, 0, 0, 0)
      end
      self:DetermineButtonSelection()
      self:SetMountButtonEnabledState()
    end,
