    Init = function(self)
      if Tutorial.inTutorial == true then
        return
      end
      QuickItem:Show()
      self.screenAlignment = "center"
      GameDock_PS3:GetSwf():Invoke("SetPortrait", tostring(GetMyId()))
      self.isOnScreen = 0
      self.dockMode = self.dockModeFull
      NonModalContext:AddContext(self)
      self:Restore()
      DsTable.Find("BaseClient.QuickChat.AutoComplete"):EnableScriptEvents()
      DsTable.Find("BaseClient.CurrentMount"):EnableScriptEvents()
    end,
    UpdateWalletInfo = function(self, walletValue)
    end,
    SlideOffScreen = function(self)
    end,
    SlideOnScreen = function(self)
      if Tutorial.inTutorial == true or VehicleGarage.isActive or self.disabled == true or self.isOnScreen == 1 or HUD.mMiniGameFlash or MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.RACING_TYPE or MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.DEMO_DERBY_TYPE or MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.SOCCER_TYPE or MiniGameStatusHandler.currentMiniGameType == MiniGameStatusHandler.PIRATES_TYPE then
        return
      end
      if self.isShown == 0 then
        self:Show(true)
      end
      self.isOnScreen = 1
      self.lockedOut = false
      NonModalContext:AddContext(self)
      local w1 = Window.Find(self.wndName)
      local x, y = w1:GetPosition()
      local w, h = w1:GetSize()
      local sw, sh = Window.GetCanvasSize()
      NonModalContext:AddContext(self)
    end,
    Show = function(self, dontSlide)
      if VehicleGarage.isActive == false then
        GameDock_PS3:Show()
        ActionDock_PS3:Show()
        self:SetMountButtonData()
      end
      ChatLog:Show()
      if Tutorial.inTutorial == true then
        return
      end
      if self.disabled == true then
        return
      end
      if self.dockInitialized == 0 then
        GameDock:Init()
        self.dockInitialized = 1
      end
      local w1 = Window.Find(self.wndName)
      if w1 ~= nil then
        self.isShown = 1
      end
    end,
    Hide = function(self)
      GameDock_PS3:Hide()
      ActionDock_PS3:Hide()
      ChatLog:Hide()
      local w1 = Window.Find(self.wndName)
      if w1 ~= nil then
        w1:Hide()
        self.isShown = 0
        QuickItem:Hide()
        self.lockedOut = false
      end
    end,
    OnResize = function(self)
      if Tutorial.inTutorial == true then
        return
      end
      local heightRatio = 240 / self.MIN_RES_HEIGHT
      local gameDockWindow = Window.Find(self.wndName)
      local w, h = gameDockWindow:GetSize()
      local swfRatio = w / h
      local sw, sh = Window.GetCanvasSize()
      local diff = sh - self.MIN_RES_HEIGHT
      local newHeight = self.MIN_RES_HEIGHT * heightRatio + diff / 2 * heightRatio
      local newWidth = newHeight * swfRatio
      gameDockWindow:SetPosition(sw / 2 - w / 2, sh - h)
    end,
    SetText = function(self, newText)
      self:GetSwf():Invoke("SetChatText", newText)
    end,
    KillFocus = function(self)
      Window.SetFocus()
    end,
    FocusKilled = function(self)
      self:GetSwf():Invoke("KillCursor")
      HousingSubMenu:Hide()
    end,
    SetTextEntry = function(self, isFocused, startText)
      if isFocused == 1 then
        self:GetWindow():SetFocus()
      else
        Window.SetFocus()
      end
      local isFromGame = 0
      if startText == nil then
        isFromGame = 1
      end
      self:GetSwf():Invoke("SetTextEntry", isFocused, startText, isFromGame)
      if m_isFocused ~= 1 then
        QuickChat.RequestPossibleMatches("")
      end
    end,
