      self.m_isProcessingChatCommand = true
    end,
    SetMountButtonEnabledState = function(self)
      local enableButton = 0
      if MiniGameStatusHandler:GetCurrentMiniGameType() == -1 and not HUD.isInStartingZone then
        enableButton = 1
      end
      if enableButton == 1 then
        GameDock_PS3:EnableButton(4)
      else
        GameDock_PS3:DisableButton(4)
      end
    end,
    SetMountButtonData = function(self)
      local m = GameDock_PS3:GetSwf()
      local ds = DsTable.Find("BaseClient.CurrentMount")
      if ds and ds:GetRowCount() > 0 then
        GraphicActionBar:setAllDisabled()
        m:Invoke("SetMountButtonData", ds:GetData(0, CurrentMountCol.CurrentMountGuid), ds:GetData(0, CurrentMountCol.Name), ds:GetData(0, CurrentMountCol.ImageSetId), 13421772)
      else
        GraphicActionBar:setAllEnabled()
        m:Invoke("SetMountButtonToMountIcon")
      end
    end,
    PopulateHousingSelector = function(self)
      Logger:print("gamedock.lua", "adding houses")
      local m = GameDock_PS3:GetSwf()
      m:Invoke("ResetMounts")
      ds = DsTable.Find("BaseClient.Housing.MyHouseList")
      local numRows = ds:GetRowCount()
      if numRows == 1 then
        if ds:GetData(0, 0) ~= Housing.currentInstance then
          Housing.currentInstance = ds:GetData(0, 0)
          GameDock_PS3:SetVisibility(0)
          House.Enter(ds:GetData(0, 0))
        end
      else
        m:Invoke("ResetMounts")
        m:Invoke("resetItemScroller")
        for i = 0, numRows - 1 do
          Logger:print("gamedock.lua", "PopulateHousingSelector -> Guid: " .. ds:GetData(i, 0) .. " Icon: " .. ds:GetData(i, 4) .. " Name: " .. ds:GetData(i, 3))
          m:Invoke("AddHousingItem", ds:GetData(i, 0), ds:GetData(i, 4), ds:GetData(i, 3))
        end
        m:Invoke("ShowHousingSelector")
      end
    end,
    PopulateMountSelector = function(self)
      Logger:print("gamedock.lua", "adding mounts")
      local m = GameDock_PS3:GetSwf()
      local ds = DsTable.Find("BaseClient.MountList")
      m:Invoke("ResetMounts")
      if ds then
        numRows = ds:GetRowCount()
        if numRows == 0 then
          m:Invoke("MakeItemSelectorInvisible")
          if Ui.IsMember() then
            MarketplaceHandler:Show(MarketplaceEnum.STORE_SC, 139)
          else
            MembershipHandler:Show()
          end
        elseif numRows == 1 then
          if not Ui.IsMember() then
            m:Invoke("MakeItemSelectorInvisible")
            MembershipHandler:Show()
          elseif Mount.CanSpawnMount() then
            m:Invoke("MakeItemSelectorInvisible")
            Mount.Spawn(ds:GetData(0, MountListCol.Id))
          end
        elseif not Ui.IsMember() then
          m:Invoke("MakeItemSelectorInvisible")
          MembershipHandler:Show()
        else
          m:Invoke("ResetMounts")
          m:Invoke("resetItemScroller")
          for i = 0, numRows - 1 do
            local iconTint = ds:GetData(i, MountListCol.Tint)
            if iconTint == "" or 0 > tonumber(iconTint) then
              iconTint = "13421772"
            end
            Logger:print("gamedock.lua", "PopulateMountSelector -> Id: " .. ds:GetData(i, MountListCol.Id) .. " Icon: " .. ds:GetData(i, MountListCol.ImageSetId) .. " Tint: " .. iconTint .. " Name: " .. ds:GetData(i, MountListCol.Name))
            m:Invoke("AddMount", ds:GetData(i, MountListCol.Id), ds:GetData(i, MountListCol.ImageSetId), ds:GetData(i, MountListCol.Name), ds:GetData(i, MountListCol.IsCurrentlySpawned), ds:GetData(i, MountListCol.IsCurrentlyMounted), tonumber(iconTint))
          end
          m:Invoke("ShowMountSelector")
        end
      end
    end,
    Dismount = function(self)
    end,
    ShowJobBrowser = function(self)
      JobHandler:Show(JobHandler.MODE_EQUIPMENT)
    end,
    ShowMainCalled = function(self)
      self:SetState(self.state)
    end,
    Restore = function(self)
      self:SetState(self.NORMAL_STATE)
    end,
    OnUserEvent = function(a, b, c)
      if GameDock.tutorialMode then
        return
      end
      if a == "activateAbility" then
        b = tonumber(b)
        if GraphicActionBar.isUsingMinigameAbilities == true then
          Ui.ClickedAbility(b, 3)
        elseif GraphicActionBar.isUsingFishingAbilities == true then
          Fishing:ClickedAbility(b)
        else
          Ui.ClickedAbility(b)
        end
        GameDock:KillFocus()
        TutorialDialog:Hide()
      elseif a == "activateItem" then
        Ui.ClickedAbility(tonumber(b) - 5, 2)
        GameDock:KillFocus()
      elseif a == "EquipItem" then
        Ui.AssignToItemActionBar(tonumber(c) - 5, tostring(b))
        GameDock:KillFocus()
      elseif a == "equipConsumablesMode" then
        JobHandler:Show(5)
      elseif a == "refreshConsumables" then
        QuickItem:PopulateSelectors()
      elseif a == "closeConsumables" then
        GameDock:KillFocus()
      elseif a == "disabledMountButtonSelected" then
        GameDock:KillFocus()
      elseif a == "mountButtonSelected" then
        GameDock:PopulateMountSelector()
      elseif a == "dismountButtonSelected" then
        Mount.Dismount()
        GameDock:KillFocus()
      elseif a == "mountSelected" then
        if Mount.CanSpawnMount() then
          Mount.Spawn(b)
          GameDock:KillFocus()
        end
      elseif a == "housingItemSelected" then
        Logger:print("gamedock.lua", "Entering Housing instance: " .. b)
        if b ~= Housing.currentInstance then
          if Housing.isInInstance == true then
            Housing:Reset()
          end
          Housing.currentInstance = b
          GameDock_PS3:SetVisibility(0)
          House.Enter(b)
        end
      elseif a == "sendChatMessage" then
        if Ui.IsUnderage() == false then
          Ui.ProcessChatCommand(b)
          GameDock:SetTextEntry(0, "")
        end
      elseif a == "killFocus" then
        GameDock:KillFocus()
      elseif a == "keyUp" then
        Ui.ChatSetPreviousCommand()
      elseif a == "keyDown" then
        Ui.ChatSetNextCommand()
      elseif a == "RequestPossibleMatches" then
        QuickChat.RequestPossibleMatches(b)
      elseif a == "autoCompleteItemSelected" then
        GameDock:AutoCompleteItemSelected(b, c)
      elseif a == "gameDockClick" then
        if GameDock.lockedOut == true then
          return
        end
        if DialogHandler.isDialogShown then
          Ui.DialogEnd()
        end
        if b == "1" then
          if Context:GetCurrent() ~= "JobHandler" then
            Context:CallQuit()
          end
          GameDock:KillFocus()
          GameDock_PS3:SetVisibility(0)
          HotKeyEvents:ToggleCharacter()
        elseif b == "2" then
          GameDock_PS3:SetVisibility(0)
          FriendsWidget:Show()
        elseif b == "3" then
          GameDock_PS3:SetVisibility(0)
          GameDock_PS3:SetNavMode(2)
          GameDock_PS3:BuildNavigation()
        elseif b == "4" then
          GameDock:PopulateHousingSelector()
        elseif b == "5" then
          GameDock_PS3:SetVisibility(0)
          GameDock:KillFocus()
          if not PetsHandler.visible then
            Context:CallQuit()
          end
          if Pet.IsBusy() == nil then
            if PetsHandler.visible then
              PetsHandler:Hide()
            else
              PetsHandler:Show()
            end
          end
        elseif b == "6" then
          GameDock_PS3:SetVisibility(0)
          GameDock_PS3:SetNavMode(3)
          GameDock_PS3:BuildNavigation()
        elseif b == "7" then
          Logger:print("gamedock.lua", "showing jobs window")
          GameDock_PS3:SetVisibility(0)
          GameDock:KillFocus()
          JobBrowser:Show(nil, -90)
          JobBrowser:Connect(GameDock_PS3)
          JobBrowser:ShowBrowser()
          if JobHandler.isFromTCG or HUD.inMiniGame then
            JobBrowser:LockBrowser()
          end
        end
      elseif a == "playSound" then
        Ui.PlaySound(b)
      elseif a == "PlaySound" then
        HUD:PlaySound(b)
      elseif a == "ASPrint" then
      elseif a == "openAtlas" then
        GameDock_PS3:SetVisibility(0)
        Atlas:Show()
      elseif a == "showingWindow" then
        GameDock_PS3:SetVisibility(1, true)
      elseif a == "hidingWindow" then
        GameDock_PS3:SetVisibility(0, true)
      end
    end
  }
  function SetPositionGameDock()
  end
  Main_wndGameDock_swfGameDock_OnUserEvent = GameDock.OnUserEvent
  Main_wndGameDock_PS3_swfGameDock_PS3_OnUserEvent = GameDock.OnUserEvent
  Main_wndItemDock_PS3_swfItemDock_PS3_OnUserEvent = GameDock.OnUserEvent
  function Main_wndGameDock_swfGameDock_OnFocus(a)
    if a == "0" then
      GameDock:FocusKilled()
    elseif a == "1" then
    end
  end
  function BaseClient_QuickChat_AutoComplete_OnDataUpdate()
    if GameDock.m_isProcessingChatCommand then
      GameDock.m_isProcessingChatCommand = false
    else
      GameDock:UpdateAutoCompleteList()
    end
  end
  function BaseClient_CurrentMount_OnDataUpdate()
    GameDock:SetMountButtonData()
  end
end)()
;(function()
  function InitChatBubble()
    ChatBubbles:Init()
