    SetMouse = function(x, y)
      ChatQueue.MouseMoveX = x - ChatQueue.MouseX
      ChatQueue.MouseMoveY = y - ChatQueue.MouseY
      ChatQueue.MouseX = x
      ChatQueue.MouseY = y
    end,
    ClearMouse = function()
      ChatQueue.MouseMoveX = 0
      ChatQueue.MouseMoveY = 0
    end,
    DebugPrint = function(self)
      Logger:print("bub.lua", self.mFromName .. " said...")
      local node = self.mList
      while node do
        Logger:print("bub.lua", "\"" .. node.mText .. "\" " .. "(" .. node.mLifetime .. " ms rem.)")
        node = node.mNext
      end
    end,
    ShowBubble = function(self, node, ofsy)
      local e
      if node.mBubble then
        e = EditControl.find(node.mBubble)
        if e then
          local x, y = Ui.GetPlayerScreenPos(self.mFromGuid)
          if ofsy then
            y = y + ofsy
          end
          y = y - node.h
          node.y = node.y + (y - node.y) * 0.2
          local Left = node.ox + node.x + x - node.w / 2
          local Top = node.oy + node.y
          local Width = node.w
          local Height = node.h
          local mx = ChatQueue.MouseX
          local my = ChatQueue.MouseY
          local bx = ChatQueue.BubStickyRange * math.min(1, math.abs(ChatQueue.MouseMoveX) / 20)
          local by = ChatQueue.BubStickyRange * math.min(1, math.abs(ChatQueue.MouseMoveY) / 20)
          if node.g then
            if not (Left <= mx + bx) or not (mx - bx < Left + Width) or not (Top < my + by) or not (my - by < Top + Height) then
              node.g = false
            end
          elseif Left <= mx and mx < Left + Width and Top < my and my < Top + Height then
            node.g = true
          end
          if node.g then
            local mx = ChatQueue.MouseMoveX * 0.4
            local my = ChatQueue.MouseMoveY * 0.4
            node.ox = node.ox + mx
            node.oy = node.oy + my
            node.mLifetime = math.max(node.mLifetime, ChatBubbleManager.ChatBubbleLifetime / 2)
          else
            node.ox = node.ox * 0.9
            node.oy = node.oy * 0.9
          end
          node.mg = false
          Left = node.ox + node.x + x - node.w / 2
          Top = node.oy + node.y
          e:setPlacementLTWH(Left, Top, Width, Height)
          local md = ChatBubbleManager.downList
          while md do
            if node.mBubble == md.mCtrlName then
              node.mLifetime = 0
