          HUD:PlaySound("BubbleAppear")
          e = EditControl.find(node.mBubble)
          e:setProperty("Style", node.mStyle)
          e:show()
          e:setText(node.mText)
          e:setSize(400, 100)
          local l, h, w = e:getInfo()
          node.w = w + 58
          node.h = h + 52
          e:setSize(node.w, node.h)
          local x, y = Ui.GetPlayerScreenPos(self.mFromGuid)
          if ofsy then
            y = y + ofsy
          end
          y = y - node.h
          node.y = node.y + (y - node.y) * 0.2
          local Left = node.x + x - node.w / 2
          local Top = node.y
          local Width = node.w
          local Height = node.h
          node.mLifetime = math.max(node.mLifetime, ChatBubbleManager.ChatBubbleLifetime / 2)
          e:setPlacementLTWH(Left, Top, Width, Height)
        end
      end
      if e ~= nil then
        local alphaMax = 255 * node.mAge / 600
        local alpha = 255 * node.mLifetime / 1000
        e:setAlpha(math.min(math.min(self.mMaxAlpha, alpha), alphaMax))
