      end
    end,
    SetBubsAlpha = function(self)
      if self.mMaxAlpha <= 0 then
        local node = self.mList
        while node do
          self:HideBubble(node)
          node = node.mNext
        end
      else
        local node = self.mList
        local ofsy = -40
        while node do
          ofsy = ofsy - self:ShowBubble(node, ofsy)
          node = node.mNext
        end
      end
    end,
    ShowBubs = function(self)
      if self.mMaxAlpha < 255 then
        self.mMaxAlpha = self.mMaxAlpha + 20
        if self.mMaxAlpha > 255 then
          self.mMaxAlpha = 255
        end
      end
      self:SetBubsAlpha()
    end,
    HideBubs = function(self)
      if self.mMaxAlpha > 0 then
        self.mMaxAlpha = 0
        if self.mMaxAlpha <= 0 then
          self.mMaxAlpha = 0
        end
      end
      self:SetBubsAlpha()
    end,
    Update = function(self, timeMs)
      local node = self.mList
      local nodePrev
      while node do
        node.mLifetime = node.mLifetime - timeMs
        node.mAge = node.mAge + timeMs
        if node.mLifetime <= 0 then
          self:HideBubble(node)
          if nodePrev then
            node = node.mNext
            nodePrev.mNext = node
          else
            node = node.mNext
            self.mList = node
          end
        else
          nodePrev = node
          node = node.mNext
        end
      end
      if not self:Empty() then
        if Ui.LosPlayer(self.mFromGuid) then
          self:ShowBubs()
        else
          self:HideBubs()
        end
      end
    end,
    Empty = function(self)
      return self.mList == nil
    end
  }
  ChatBubbles = {
    WORLDSAY_CHANNEL = "WorldSay",
    GROUPSAY_CHANNEL = "GroupSay",
    GUILDSAY_CHANNEL = "GuildSay",
    QUICKCHAT_WORLDSAY_CHANNEL = "QuickChatWorldSay",
    AREASAY_CHANNEL = "WorldArea",
    WORLDTRADE_CHANNEL = "WorldTrade",
