    MOSAY_CHANNEL = "WorldMembersOnly",
    WORLDSHOUT_CHANNEL = "WorldShout",
    mQueue = {},
    Init = function(self)
      ChatBubbleManager:Init()
    end,
    GetQueue = function(self, fromGuid, fromName)
      if self.mQueue[fromGuid] == nil then
