    end,
    Say = function(self, fromGuid, fromName, msg, sizeChat, fgColor, bgColor)
      Ui.ShowChatBubble(tostring(fromGuid), msg, bgColor, sizeChat, fgColor)
    end,
    Update = function(self)
      local w, h = Window.GetCanvasSize()
      ChatQueue.BubStickyRange = w * 200 / 1500
      local x, y = Ui.GetMousePos()
      ChatQueue.SetMouse(x, y)
      local timeMs = Ui.GetFrameTime()
      for k, v in pairs(self.mQueue) do
        v:Update(timeMs)
        if v:Empty() then
          self.mQueue[k] = nil
        end
      end
      ChatQueue.ClearMouse()
      ChatBubbleManager.downList = nil
    end
  }
  function OnReceiveSay(fromGuid, fromName, msg, isChatLogged, sizeChat, fgColor, bgColor, channelName, isNPC, isRef, isFriend, areaName)
    if fromGuid ~= Ui.GetPlayerGuid() then
      local dfUseTheirColors = Ui.GetUserOptionsValue("chatOptions", "dfUseTheirColors", "false")
      if dfUseTheirColors ~= "true" then
        fgColor = tonumber(Ui.GetUserOptionsValue("chatOptions", "dfTextColor", 13158))
        bgColor = tonumber(Ui.GetUserOptionsValue("chatOptions", "dfBubbleColor", 13434879))
        sizeChat = tonumber(Ui.GetUserOptionsValue("chatOptions", "dfTextSize", 2))
      end
    end
    if channelName ~= ChatBubbles.AREASAY_CHANNEL and channelName ~= ChatBubbles.WORLDTRADE_CHANNEL and channelName ~= ChatBubbles.LFGSAY_CHANNEL and channelName ~= ChatBubbles.GUILDSAY_CHANNEL and channelName ~= ChatBubbles.MOSAY_CHANNEL then
      ChatBubbles:Say(fromGuid, fromName, msg, sizeChat, fgColor, bgColor)
    end
    if isChatLogged then
      ChatLog:AddChatMessage(fromGuid, fromName, msg, sizeChat, fgColor, bgColor, channelName, isNPC, isRef, areaName, isFriend)
    end
    yeOldOnReceiveSay(fromName, msg)
  end
  function OnReceiveEmote(fromGuid, fromName, msg, isChatLogged, sizeChat, fgColor, bgColor)
    ChatBubbles:Say(fromGuid, fromName, msg, sizeChat, fgColor, bgColor)
    if isChatLogged then
    end
    yeOldOnReceiveSay(nil, msg)
  end
  function OnReceiveWhisper(fromGuid, fromName, msg, isChatLogged, sizeChat, fgColor, bgColor, channelName, isNPC, isRef)
    if isChatLogged then
      ChatLog:AddWhisper(fromGuid, fromName, msg, sizeChat, fgColor, bgColor, channelName, isNPC, isRef)
    end
    return true
  end
  function ChatBubbleClass_OnFocus(name, a, b, c, d)
    if tonumber(a) == 1 then
      ChatBubbleManager.downList = {
        next = downList,
        mCtrlName = tonumber(name)
      }
    end
  end
end)()
;(function()
  Atlas = {
