        local ds = DsTable.Find("BaseClient.Breadcrumb")
        if ds then
          local fx, fy, cx, cy, x, y
          local numRows = ds:GetRowCount()
          if numRows > 200 then
            numRows = 200
          end
          for i = 0, numRows - 1 do
            x = tonumber(ds:GetData(i, 2))
            y = tonumber(ds:GetData(i, 0))
            if i == 0 or i == numRows - 1 then
              fx = x
              fy = y
              cx = x
              cy = y
              matlas:Invoke("addPathCoordinate", x, y)
            elseif math.abs(cx - x) + math.abs(cy - y) > 20 then
              matlas:Invoke("addPathCoordinate", x, y)
              cx = x
              cy = y
            end
          end
          matlas:Invoke("drawPath")
        end
      end
    end
  }
  function Main_wndAtlas_swfAtlas_OnFocus(a, b, c)
    if tonumber(a) == 1 then
      Window.SetFocus()
    end
  end
  function Main_wndAtlas_swfAtlas_OnUserEvent(a, b, c)
    if a == "exitScreen" then
      Atlas:Hide()
      GameDock_PS3:SetVisibility(1)
    elseif a == "playSound" or a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "saveRadioState" then
      Atlas:SaveRadioState(tonumber(b), tonumber(c))
    elseif a == "teleportPlayerToFriend" then
      if Ui.TeleportToFriend then
        HUD:PlaySound("BubblePop")
        Ui.TeleportToFriend(b)
      end
    elseif a == "teleportPlayerToPointOfInterest" then
      if Ui.TeleportToPointOfInterest then
        HUD:PlaySound("BubblePop")
        Ui.TeleportToPointOfInterest(b)
      end
    elseif a == "showPOIBreadcrumbs" then
      Ui.StartBreadcrumbQuest(b)
    elseif a == "prevQuest" then
      QuestHelper:SelectPrevQuest()
    elseif a == "nextQuest" then
      QuestHelper:SelectNextQuest()
    elseif a == "ASPrint" then
    elseif a == "RequestQuestData" then
      QuestHelper:PopulateAtlasActiveQuest()
    end
  end
end)()
;(function()
  GaqItemManager = {
    mActions = nil,
    FreeListGaqItems = nil,
    Init = function(self)
      local e = GfxCtrl.Find("GaqSwf1")
      if e == nil then
        local i = 1
        while i < 20 do
          local theName = "GaqSwf" .. tostring(i)
          GfxCtrl.Create(theName, "UI/gaqitem.swf", 2500, 2500, 500, 100)
          local c = GfxCtrl.Find(theName)
          c:SetProperty("Class", "GaqItemClass")
          c:SetProperty("Zlayer", "224")
          self.FreeListGaqItems = {
            next = self.FreeListGaqItems,
            name = Ui.GetName(theName)
          }
          local swf = GfxCtrl.Find(theName)
          swf:Hide()
          i = i + 1
        end
      end
    end,
    GetGaqItem = function(self)
      if self.FreeListGaqItems then
        local theGaqItem = self.FreeListGaqItems
        self.FreeListGaqItems = self.FreeListGaqItems.next
        if theGaqItem then
          return theGaqItem.name
        end
      end
    end,
    Release = function(self, theName)
      self.FreeListGaqItems = {
        next = self.FreeListGaqItems,
        name = theName
      }
    end
  }
  MiniGaq = {
    wndMinGaq = Ui.GetName("Main.wndMinGaq"),
    swfMinGaq = Ui.GetName("Main.wndMinGaq.swfMinGaq"),
    ow = nil,
    oh = nil,
    isShown = false,
    Show = function(self)
      if not self.isShown then
        self.isShown = true
        self:OnResize()
        NonModalContext:AddContext(self)
      end
    end,
    OnResize = function(self)
      local sw, sh = Window.GetCanvasSize()
      local win = Window.Find(self.wndMinGaq)
      if self.ow == nil then
        self.ow, self.oh = win:GetSize()
      end
      local w = self.ow
      local h = self.oh
      local x = 0
      local y = 0
      local widthRatio = (sw / 1280 - 1) * 0.5 + 1
      local heightRatio = (sh / 720 - 1) * 0.5 + 1
      w = widthRatio * w
      h = heightRatio * h
      win:SetSizeScaled(w, h)
      if Ui.IsMember() then
        x = sw - w - 5
      else
        x = sw - w - 120
      end
      y = sh - h - 5
      win:SetPosition(x, sh + w)
      win:Show()
      WindowTweener:Create("Main.wndMinGaq", "Y", nil, y, 0.3)
    end,
    Hide = function(self)
      if self.isShown then
        self.isShown = false
        local sw, sh = Window.GetCanvasSize()
        local w = Window.Find(self.wndMinGaq)
        WindowTweener:Create("Main.wndMinGaq", "Y", nil, sh + 100, 0.3, function()
          local w = Window.Find(self.wndMinGaq)
          w:Hide()
          local m = GfxCtrl.Find(self.swfMinGaq)
          m:Unload()
        end)
        NonModalContext:RemoveContext(self)
