  Gaq = {
    mItems = nil,
    mGaqItemCount = 0,
    encounterGaqItems = {},
    ShowItem = function(self, item)
      if not item.isVisible then
        item.isVisible = true
        item.displayLife = item.fullDisplayLife
        item.life = item.fullLife
        c = GfxCtrl.Find(item.name)
        if c then
          c:Show()
        end
      end
    end,
    HideItem = function(self, item)
      if item.isVisible then
        item.isVisible = false
        c = GfxCtrl.Find(item.name)
        if c then
          c:Hide()
        end
      end
    end,
    ShowAll = function(self)
      local item = self.mItems
      while item do
        if not item.isVisible then
          self:ShowItem(item)
        end
        item = item.next
      end
    end,
    HideAll = function(self)
      local item = self.mItems
      while item do
        if item.isVisible then
          self:HideItem(item)
        end
        item = item.next
      end
    end,
    OnMiniGaqClick = function(self)
      local countVisible = 0
      local countAll = 0
      local item = self.mItems
      while item do
        if item.isVisible then
          countVisible = countVisible + 1
        end
        countAll = countAll + 1
        item = item.next
      end
      if countAll > 0 then
        if countVisible > 0 and countAll > 0 and countVisible ~= countAll then
          self:HideAll()
        elseif countAll > 0 and countAll == countVisible then
          self:HideAll()
        elseif countVisible == 0 then
          self:ShowAll()
        end
      end
    end,
    Update = function(self)
      local sx, sy = Window.GetCanvasSize()
      if self.mItems then
        local item = self.mItems
        local itemNumber = 1
        if MiniGaq.isShown then
          itemNumber = 2
        end
        local timeMs = Ui.GetFrameTime()
        local lastitem
        while true do
          if item then
            item.life = item.life - timeMs
            item.displayLife = item.displayLife - timeMs
            if item.life <= 0 then
              self:HideItem(item)
              local autodecline = true
              if autodecline then
                local timedOutResponse = 2
                GameActionQueue.Respond(item.cookie, timedOutResponse)
                self.mGaqItemCount = self.mGaqItemCount - 1
                GaqItemManager:Release(item.name)
                if lastitem then
                  lastitem.next = item.next
                else
                  self.mItems = item.next
                end
                if self.mGaqItemCount == 0 then
                  MiniGaq:Hide()
                else
                  MiniGaq:SetNumber(self.mGaqItemCount)
                end
                item = item.next
              end
            elseif item.displayLife <= 0 then
              self:HideItem(item)
              lastitem = item
              item = item.next
            end
            do
              local c = GfxCtrl.Find(item.name)
              if c then
                local w = 500
                local h = 110
                local sw, sh = Window.GetCanvasSize()
                local widthRatio = sw / 1024
                local heightRatio = sh / 768
                w = widthRatio * w
                h = heightRatio * h
                c:SetProperty("Width", w)
                c:SetProperty("Height", h)
                item.x = sx - w - 100
                item.y = sy - h - 300
                c:SetProperty("X", item.x)
                c:SetProperty("Y", item.y)
              end
              lastitem = item
              item = item.next
              itemNumber = itemNumber + 1
            end
            else
              UpdateList.Gaq = nil
            end
          end
        end
    end,
    Release = function(self, name)
      local item = self.mItems
      local lastitem
      while item do
        if item.name == name then
          local c = GfxCtrl.Find(item.name)
          if c then
            c:Hide()
          end
          self.mGaqItemCount = self.mGaqItemCount - 1
          GaqItemManager:Release(item.name)
          if lastitem then
            lastitem.next = item.next
          else
            self.mItems = item.next
          end
        else
          lastitem = item
        end
        item = item.next
      end
      if self.mGaqItemCount == 0 then
        MiniGaq:Hide()
      else
        MiniGaq:SetNumber(self.mGaqItemCount)
      end
    end,
    AddGaqItem = function(self, theText, theCookie, iconImageId, bgImageSetId, displayTimeout, lifeTimeout)
      local i = GaqItemManager:GetGaqItem()
      if i then
        local displayMs = displayTimeout * 1000
        local lifeMs = displayTimeout * 1000
        local nextItem = {
          name = i,
          next = self.mItems,
          x = 20,
          y = 1600,
          theType = 1,
          displayLife = displayMs,
          fullDisplayLife = displayMs,
          life = lifeMs,
          fullLife = lifeMs,
          cookie = theCookie,
          isVisible = true
        }
        self.mItems = nextItem
        local c = GfxCtrl.Find(i)
        if c then
          c:Show()
          c:Reset()
          c:SetProperty("X", nextItem.x)
          c:SetProperty("Y", nextItem.y)
          c:SetProperty("ZLayer", 250)
          c:Invoke("setDialogData", theText, iconImageId, bgImageSetId, tostring(theCookie))
        end
        UpdateList.Gaq = Gaq
      end
      self.mGaqItemCount = self.mGaqItemCount + 1
      MiniGaq:Show()
      MiniGaq:SetNumber(self.mGaqItemCount)
      self:Notify()
      return i
    end,
    Notify = function(self)
      HUD:PlaySound("Notification")
      local sw, sh = Window.GetCanvasSize()
      local wnd = Window.Find("Main.wndPayAttention")
      wnd:Show()
