  function GaqItemClass_OnUserEvent(hashCtrlName, theCommand, gaqItemId)
    if theCommand == "accept" then
      if HUD.inited then
        local acceptResponse = 0
        GameActionQueue.Respond(tonumber(gaqItemId), acceptResponse)
        Gaq:Release(tonumber(hashCtrlName))
        ToolTipHandler:HideToolTip()
      end
    elseif theCommand == "cancel" and HUD.inited then
      local declineResponse = 1
      for i, v in ipairs(Gaq.encounterGaqItems) do
        if tonumber(v) == tonumber(gaqItemId) then
          table.remove(Gaq.encounterGaqItems, position)
          MiniGameHandler.ignoreEncounterCancelled = true
        end
      end
      GameActionQueue.Respond(tonumber(gaqItemId), declineResponse)
      Gaq:Release(tonumber(hashCtrlName))
    end
  end
  function Main_wndMinGaq_swfMinGaq_OnUserEvent(a, b)
    if a == "toggleGaqDisplay" then
      MiniGaq:OnClick()
    end
  end
  function Main_wndPayAttention_swfPayAttention_OnUserEvent(a, b)
    local wnd = Window.Find("Main.wndPayAttention")
    wnd:Hide()
    GfxCtrl.Find("Main.wndPayAttention.swfPayAttention"):Unload()
  end
end)()
;(function()
  OptionsDSColumns = {
    Id = 0,
    Section = 1,
    DisplayName = 2,
    Tooltip = 3,
    HasSubMenu = 4,
    SubMenuName = 5,
    Value = 6,
    OptionName = 7,
    OptionType = 8,
    Callback = 9,
    Disabled = 10,
    IntParam1 = 11,
    DefaultValue = 12
  }
  Options = {
    mIsUp = false,
    resCount = 0,
    optionsPanelWindow = Ui.GetName("Main.wndOptionsPanel"),
    optionsPanelSwf = Ui.GetName("Main.wndOptionsPanel.swfOptionsPanel"),
    Show = function(self, optionalPopFunction)
      ExitPanel:Show(optionalPopFunction)
    end,
    Hide = function(self)
      local myShowQuestHelper = tonumber(Ui.GetUserOptionsValue("QuestHelperOptions", "QuestHelperEnabled", 0))
      Ui.SaveUserOptions()
      ExitPanel:Hide()
      self:HidePanel()
      if myShowQuestHelper == 0 then
        QuestHelper:HideHelper()
      else
        QuestHelper:ShowHelper()
      end
    end,
    ShowPanel = function(self, optionalPopFunction)
      if self.mIsUp then
        return
      end
      NonModalContext:AddContext(self)
      MiniGameFlash:Pause()
      local w = Window.Find(self.optionsPanelWindow)
      if w then
        self.mIsUp = true
        local m = GfxCtrl.Find(self.optionsPanelSwf)
        m:Unload()
        m:Load()
        self:UpdateSettings()
        Context:Push("Options", function()
          Options:HidePanel()
        end, optionalPopFunction)
        HUD:PlaySound("ShowWindow")
        w:Show()
        self:OnResize()
      end
    end,
    OnResize = function(self)
      local w = Window.Find(self.optionsPanelWindow)
      local width, height = w:GetSize()
      local sw, sh = Window.GetCanvasSize()
      w:SetPosition((sw - width) / 2, -height)
      if not Client.UiScale then
        WindowTweener:Create("Main.wndOptionsPanel", "X", nil, (sw - width) / 2, 0.4)
        WindowTweener:Create("Main.wndOptionsPanel", "Y", nil, (sh - height) / 3, 0.4)
      else
        WindowTweener:Create("Main.wndOptionsPanel", "X", nil, (sw - Client.UiScale * width) / 2, 0.4)
        WindowTweener:Create("Main.wndOptionsPanel", "Y", nil, (sh - Client.UiScale * height) / 3, 0.4)
      end
    end,
    HidePanel = function(self, hideOnly)
      if self.mIsUp then
        Context:Pop()
        local w = Window.Find(self.optionsPanelWindow)
        MiniGameFlash:Resume()
        if w then
          self.mIsUp = false
          local width, height = w:GetSize()
          local sw, sh = Window.GetCanvasSize()
          WindowTweener:Create("Main.wndOptionsPanel", "X", nil, (sw - width) / 2, 0.4)
          WindowTweener:Create("Main.wndOptionsPanel", "Y", nil, -height, 0.4, function()
            Window.Find(Ui.GetName("Main.wndOptionsPanel")):Hide()
          end)
          NonModalContext:RemoveContext(self)
        end
      end
    end,
    AddScreenResolution = function(self, WidthxHeight, current)
      local isSelected = 0
      if current == 1 then
        isSelected = 1
      end
      local m = GfxCtrl.Find(self.optionsPanelSwf)
      if m then
        m:Invoke("AddMenuOption", "res" .. tostring(self.resCount), "screenres", WidthxHeight, nil, 0, 0, isSelected, "setScreenResolution", "radio", WidthxHeight, 0, self.resCount, 0)
        self.resCount = self.resCount + 1
      end
    end,
    ShowChatSettings = function(self)
    end,
    LoadChatSetting = function(self)
    end,
    SetFlags = function(self)
      local ds = DsTable.Find("BaseClient.Language")
      if ds then
        local mov = GfxCtrl.Find(self.optionsPanelSwf)
        mov:Invoke("ResetLanguages")
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          mov:Invoke("AddLanguage", ds:GetData(i, LocaleDsColumn.ID), ds:GetData(i, LocaleDsColumn.Location), ds:GetData(i, LocaleDsColumn.Language), tonumber(ds:GetData(i, LocaleDsColumn.LocationFlag)), tonumber(ds:GetData(i, LocaleDsColumn.Filtered)), tonumber(ds:GetData(i, LocaleDsColumn.IsDefault)))
        end
      end
    end,
    setChannelsShowing = function(self)
      Logger:print("options.lua", "setChannelsShowing")
      local mov = GfxCtrl.Find(self.optionsPanelSwf)
      if self:GetChatOptionArea() then
        mov:Invoke("SetChatOptionArea", 1)
      else
        mov:Invoke("SetChatOptionArea", 0)
      end
      if self:GetChatOptionTrade() then
        Logger:print("options.lua", "WorldTrade true")
        mov:Invoke("SetChatOptionTrade", 1)
      else
        Logger:print("options.lua", "WorldTrade false")
        mov:Invoke("SetChatOptionTrade", 0)
      end
      if self:GetChatOptionLfg() then
        mov:Invoke("SetChatOptionLfg", 1)
      else
        mov:Invoke("SetChatOptionLfg", 0)
      end
      if self:GetChatOptionMO() and Ui.IsMember() then
        mov:Invoke("SetChatOptionMO", 1)
      else
        mov:Invoke("SetChatOptionMO", 0)
      end
    end,
    SaveColorInDB = function(self, color, isMe, isFriend, isText)
      local prefix = self:GetUserOptionsPrefix(isMe, isFriend)
      local keyString = "BubbleColor"
      if isText then
        keyString = "TextColor"
        if prefix == "my" then
          self.fgColor = color
          self:saveMySettings()
        end
      elseif prefix == "my" then
        self.bgColor = color
        self:saveMySettings()
      end
      Ui.SetUserOptionsValue("chatOptions", prefix .. keyString, tostring(color))
    end,
    SaveSizeInDB = function(self, size, isMe, isFriend)
      if self:GetUserOptionsPrefix(isMe, isFriend) == "my" then
        self.fontSize = size
        self:saveMySettings()
      end
      Ui.SetUserOptionsValue("chatOptions", self:GetUserOptionsPrefix(isMe, isFriend) .. "TextSize", tostring(size))
    end,
    SetShowPortrait = function(self, should, isMe, isFriend)
      local prefix = self:GetUserOptionsPrefix(isMe, isFriend)
      Ui.SetUserOptionsValue("chatOptions", prefix .. "ShowPortrait", should)
    end,
    SetUseTheirColors = function(self, should, isFriend)
      local prefix = self:GetUserOptionsPrefix(false, isFriend)
      Ui.SetUserOptionsValue("chatOptions", prefix .. "UseTheirColors", should)
    end,
    GetUserOptionsPrefix = function(self, isMe, isFriend)
      if isMe == "false" then
        isMe = false
      end
      if isFriend == "false" then
        isFriend = false
      end
      local prefix = "df"
      if isMe then
        prefix = "my"
      elseif isFriend then
        prefix = "fr"
      end
      return prefix
    end,
    SetShowSimple = function(self, show)
      Ui.SetUserOptionsValue("chatOptions", "showSimple", show)
    end,
    saveMySettings = function(self)
      Ui.SetChatColorFgBgSz(self.fgColor, self.bgColor, self.fontSize)
    end,
    CheckVideoCaptureResolution = function(self, res)
      if tonumber(VideoCapture.GetVideoCaptureResolution()) == tonumber(res) then
        return 1
      end
      return 0
    end,
    CheckStoredOption = function(self, sectionString, keyString, default)
      return Ui.GetUserOptionsValue(sectionString, keyString, default)
    end,
    GetQuestAutoSwitchToggled = function(self)
      if QuestScreen.GetAutoSwitchSelectedQuest() == true then
        return 1
      end
      return 0
    end,
    GetGammaPercent = function(self)
      return math.floor((Ui.GetGamma() + 1) * 50)
    end,
    GetGraphicsQuality = function(self)
      return Ui.GetGraphicsQuality()
    end,
    GetTextureQuality = function(self)
      return tostring(math.abs(2 - tonumber(Ui.GetTextureQuality())))
    end,
    CheckShowMinimapPath = function(self)
      return self:CheckBooleanStrOption("MinimapOptions", "PathEnabled", "true")
    end,
    CheckShowIndicators = function(self)
      return self:CheckBooleanStrOption("MinimapOptions", "Indicators", "true")
    end,
    GetChatOptionLog = function(self)
      return self:CheckBooleanStrOption("chatOptions", "SetShowChatLog", "false")
    end,
    GetChatOptionArea = function(self)
      return self:CheckBooleanStrOption("chatOptions", "WorldArea", "true")
    end,
    GetChatOptionTrade = function(self)
      return self:CheckBooleanStrOption("chatOptions", "WorldTrade", "false")
    end,
    GetChatOptionLfg = function(self)
      return self:CheckBooleanStrOption("chatOptions", "WorldLfg", "false")
    end,
    GetChatOptionMO = function(self)
      return self:CheckBooleanStrOption("chatOptions", "WorldMembersOnly", "false")
    end,
    GetChatOptionVoice = function(self)
      return self:CheckBooleanStrOption("chatOptions", "VoiceChatEnabled", "true")
    end,
    GetAutoRefuse = function(self, type)
      return Ui.GetAutoRefuse(tonumber(type))
    end,
    GetAutoRefuseF10 = function(self)
      c = tonumber(Ui.GetAutoRefuse(3))
      if c == 1 then
        c = 0
      else
        c = 1
      end
      return c
    end,
    SetAutoRefuse = function(self, type, bool)
      Ui.SetAutoRefuse(tonumber(type), tonumber(bool))
    end,
    GetKeyName = function(self, key)
      if key ~= "0" then
        return Ui.GetString("key_" .. Client.ReverseKeyName(key))
      end
      return ""
    end,
    CheckBooleanStrOption = function(self, section, name, default)
      local boolStr = Ui.GetUserOptionsValue(section, name, default)
      if boolStr == "true" then
        return 1
      else
        return 0
      end
    end,
    UpdateSettings = function(self)
      local m = GfxCtrl.Find(self.optionsPanelSwf)
      if m then
        Logger:print("options.lua", "Update Settings: movie found")
        m:Reset()
        local ds = DsTable.Find("BaseClient.Options")
        if ds then
          local optionsCount = ds:GetRowCount() - 1
          Logger:print("options.lua", "Update Settings: ds found (" .. optionsCount .. ")")
          for i = 0, optionsCount do
            if ds:GetData(i, OptionsDSColumns.Id) == "chat" and not Ui.IsChatAllowed() then
