      if DemoDerbyTutorial.m_CurrentMode ~= nil then
        DemoDerbyTutorial:HideOnExit()
      end
      if Housing.isInInstance == true then
        Housing:Leave()
      elseif VehicleGarage.isActive == true then
        VehicleGarage:End(1)
