      local w = Window.Find(self.mWindow)
      local width, height = w:GetSize()
      local sw, sh = Window.GetCanvasSize()
      w:SetProperty("Width", 0)
      w:SetProperty("Height", 0)
      WindowTweener:Create("Main.wndKeyBinds", "Width", nil, 376, 0.4)
      WindowTweener:Create("Main.wndKeyBinds", "Height", nil, 576, 0.4)
      w:SetPosition(sw / 2, 0)
      WindowTweener:Create("Main.wndKeyBinds", "X", sw / 2, (sw - 376) / 2, 0.4)
      WindowTweener:Create("Main.wndKeyBinds", "Y", 0, (sh - 576) / 3, 0.4)
    end,
    Hide = function(self)
      Context:Pop()
      local w = Window.Find(self.mWindow)
      if w then
        local sw, sh = Window.GetCanvasSize()
        WindowTweener:Create("Main.wndKeyBinds", "Width", nil, 0, 0.4)
        WindowTweener:Create("Main.wndKeyBinds", "Height", nil, 0, 0.4)
        WindowTweener:Create("Main.wndKeyBinds", "X", (sw - 400) / 2, sw / 2, 0.4)
        WindowTweener:Create("Main.wndKeyBinds", "Y", (sh - 800) / 3, 0, 0.4, function()
          Window.Find(Ui.GetName("Main.wndKeyBinds")):Hide()
          HotKeyEvents:SetEnabledAll(true)
        end)
        NonModalContext:RemoveContext(self)
      end
    end,
    GetKeyName = function(self, key)
      if key ~= "0" then
        return Ui.GetString("key_" .. Client.ReverseKeyName(key))
      end
      return ""
    end,
    KeyPressed = function(self, key)
      local m = GfxCtrl.Find(self.mSwf)
      if not self:IsExcluded(key) then
        m:Invoke("SetKey", self:GetKeyName(key), key)
      else
        m:Invoke("ExcludedKeyPressed", self:GetKeyName(key), key)
      end
      return 1
    end,
    SavedKeyNeedsSetting = function(self, newOptionName)
      if self.savedOptionName ~= nil then
        if self.savedOldOptionValue ~= self.savedOptionValue then
          Ui.ChangeKeyBinding(self.savedOptionValue, self.savedOptionName)
        else
          Ui.SwitchKeyBinding(self.savedOptionName, newOptionName)
        end
        self.savedOptionName = nil
        self.savedOptionValue = nil
        self.savedOldOptionValue = nil
      end
    end,
    IsExcluded = function(self, key)
      for k, v in pairs(KeyCodes) do
        if v == key then
          return true
        end
      end
      return false
    end
  }
  function Main_wndKeyBinds_swfKeyBinds_OnFocus(a, b)
    if tonumber(a) == 1 then
      Window.SetFocus()
    end
  end
  function Main_wndKeyBinds_swfKeyBinds_OnUserEvent(a, b, c, d)
    if a == "goBack" then
      KeyBinds:Hide()
      Options:ShowPanel()
    elseif a == "setAllToDefault" then
    elseif a == "close" then
      KeyBinds:Hide()
    elseif a == "setToDefault" then
      KeyBinds.savedOldOptionValue = c
      if KeyBinds.savedOldOptionValue ~= KeyBinds.savedOptionValue then
        Ui.ResetKeyBinding(b)
      end
      KeyBinds:SavedKeyNeedsSetting(b)
      InteractionPrompt:Update()
    elseif a == "setKey" then
      KeyBinds.savedOldOptionValue = d
      if KeyBinds.savedOldOptionValue ~= KeyBinds.savedOptionValue then
        Ui.ChangeKeyBinding(b, c)
      end
      KeyBinds:SavedKeyNeedsSetting(c)
      InteractionPrompt:Update()
    elseif a == "saveKeytoSetLater" then
      KeyBinds.savedOptionValue = b
      KeyBinds.savedOptionName = c
    elseif a == "startKeyListening" then
      Ui.SetKeyboardIntercept("KeyBinds:KeyPressed")
    elseif a == "stopKeyListening" then
      Ui.ClearKeyboardIntercept()
    elseif a == "ASPrint" then
      Logger:print("options.lua", b)
    end
  end
end)()
;(function()
  ChatLogQueue = {}
