        if rank == solo or rank == "Solo" then
          if groupFilterShown then
            m:Invoke("RemoveGroupFilter")
            groupFilterShown = false
          end
        elseif not groupFilterShown then
          m:Invoke("AddGroupFilter")
          groupFilterShown = true
        end
      end
    end,
    SetGuildFilter = function(self)
      if self.inited == true then
        local m = GfxCtrl.Find(self.nameChatSwf)
        if SocialHandler:SetGuild() == 1 then
          m:Invoke("AddGuildFilter")
        else
          m:Invoke("RemoveGuildFilter")
        end
      end
