    AddChatMessage = function(self, guid, from, msg, sizeChat, fgColor, bgColor, channelName, isNPC, isRef, areaName, isFriend)
      local htmlSafe = Ui.MakeHtmlSafe(msg)
      self:AddMessage(guid, from, htmlSafe, sizeChat, fgColor, bgColor, channelName, tostring(isNPC), tostring(isRef), areaName, tostring(isFriend))
    end,
    AddMessage = function(self, guid, from, msg, sizeChat, fgColor, bgColor, channelName, isNPC, isRef, areaName, isFriend)
      if not ChatLog.isLoaded then
        local obj = {}
        obj.guid = guid
        obj.from = from
        obj.msg = msg
        obj.sizeChat = sizeChat
        obj.fgColor = fgColor
        obj.bgColor = bgColor
        obj.channelName = channelName
        obj.isNPC = isNPC
        obj.isRef = isRef
        obj.areaName = areaName
        obj.isWhisper = false
        obj.isFriend = isFriend
        table.insert(ChatLogQueue, obj)
        return
      end
      self:ShowList()
      local m = GfxCtrl.Find(self.nameChatSwf)
      if guid then
        m:Invoke("addChatMessege", "_" .. tostring(guid), from, msg, sizeChat, fgColor, bgColor, channelName, 0, isNPC, isRef, areaName, self:GetMessageCount(), isFriend)
      else
        m:Invoke("addSystemMessage", "_", from, msg, fgColor, bgColor, self:GetMessageCount())
      end
    end,
    AddWhisper = function(self, guid, from, msg, sizeChat, fgColor, bgColor, channelName, isNPC, isRef)
      if not ChatLog.isLoaded then
        local obj = {}
        obj.guid = guid
        obj.from = from
        obj.msg = msg
        obj.sizeChat = sizeChat
        obj.fgColor = fgColor
        obj.bgColor = bgColor
        obj.channelName = channelName
        obj.isNPC = isNPC
        obj.isRef = isRef
        obj.isWhisper = true
        table.insert(ChatLogQueue, obj)
        return
      end
      HUD:PlaySound("TellReceived")
      self:ShowList()
      local m = GfxCtrl.Find(self.nameChatSwf)
      local htmlSafe = Ui.MakeHtmlSafe(msg)
      m:Invoke("AddWhisper", "_" .. tostring(guid), from, htmlSafe, sizeChat, fgColor, bgColor, channelName, tostring(isNPC), tostring(isRef), self:GetMessageCount())
      if self.isNotHidden and self.isTextOpen ~= 1 then
        Logger:print("chatlog.lua", "makeLogActive")
        m:Invoke("makeLogActive")
      end
    end,
    GetMessageCount = function(self)
      self.messageCount = self.messageCount + 1
      return self.messageCount
    end,
    ParseQueuedMessages = function(self)
      if not ChatLogQueue then
        return
      end
      local msgCount = #ChatLogQueue
      if msgCount then
        for i = 1, msgCount do
          local msg = ChatLogQueue[i]
          if msg.isWhisper then
            self:AddWhisper(msg.guid, msg.from, msg.msg, msg.sizeChat, msg.fgColor, msg.bgColor, msg.channelName, msg.isNPC, msg.isRef)
          else
            self:AddMessage(msg.guid, msg.from, msg.msg, msg.sizeChat, msg.fgColor, msg.bgColor, msg.channelName, msg.isNPC, msg.isRef, msg.areaName, msg.isFriend)
          end
        end
      end
      ChatLogQueue = nil
    end,
    showQueue = function(self)
      if not ChatLogQueue then
        return
      end
      local output = ""
      local msgCount = #ChatLogQueue
      output = "[ Message Queue has " .. msgCount .. " number of entries. ]"
      if #ChatLogQueue then
        for i = 1, msgCount do
          local msg = ChatLogQueue[i]
          output = output .. "[ Message " .. i .. " ]\n"
          output = output .. "\t" .. "guid: " .. tostring(msg.guid) .. "\n"
          output = output .. "\t" .. "from: " .. tostring(msg.from) .. "\n"
          output = output .. "\t" .. "msg: " .. tostring(msg.msg) .. "\n"
          output = output .. "\t" .. "sizeChat: " .. tostring(msg.sizeChat) .. "\n"
          output = output .. "\t" .. "fgColor: " .. tostring(msg.fgColor) .. "\n"
          output = output .. "\t" .. "bgColor: " .. tostring(msg.bgColor) .. "\n"
          output = output .. "\t" .. "channelName: " .. tostring(msg.channelName) .. "\n"
          output = output .. "\t" .. "isNPC: " .. tostring(msg.isNPC) .. "\n"
          output = output .. "\t" .. "isRef: " .. tostring(msg.isRef) .. "\n"
          output = output .. "\t" .. "areaName: " .. tostring(msg.areaName) .. "\n"
          output = output .. "\t" .. "isWhisper: " .. tostring(msg.isWhisper) .. "\n"
        end
      end
    end,
    EchoWhisperFromQuickChat = function(self, to, msg)
