      local texBoxW = Ui.GetUserOptionsValue("chatOptions", "TextBoxW", 370)
      local texBoxH = Ui.GetUserOptionsValue("chatOptions", "TextBoxH", 370)
      mov:Invoke("SetTextBoxSize", tonumber(texBoxW), tonumber(texBoxH))
