      mov:Invoke("CreateString", "GUILD_CHANNEL", Ui.GetString("Guild"))
      mov:Invoke("CreateString", "AREA_CHANNEL", Ui.GetString("1Area"))
      mov:Invoke("CreateString", "TRADE_CHANNEL", Ui.GetString("2Trade"))
      mov:Invoke("CreateString", "LFG_CHANNEL", Ui.GetString("3LFG"))
      mov:Invoke("CreateString", "MO_CHANNEL", Ui.GetString("4MembersOnly"))
      mov:Invoke("CreateString", "m_yellingStr", Ui.GetString("Yelling"))
      mov:Invoke("CreateString", "m_youWhisperingStr", Ui.GetString("YouWhispering"))
      mov:Invoke("CreateString", "m_whisperingStr", Ui.GetString("Whispering"))
    end,
    setChannelsShowing = function(self)
      local mov = GfxCtrl.Find(self.nameChatSwf)
      if Ui.GetUserOptionsValue("chatOptions", self.AREA_CHANNEL, "true") == "true" then
        Ui.ChannelOn(self.AREA_CHANNEL)
        mov:Invoke("AddAreaFilter")
      else
        Ui.ChannelOff(self.AREA_CHANNEL)
        mov:Invoke("RemoveAreaFilter")
      end
      if Ui.GetUserOptionsValue("chatOptions", self.TRADE_CHANNEL, "false") == "true" then
        Ui.ChannelOn(self.TRADE_CHANNEL)
        mov:Invoke("AddTradeFilter")
      else
        Ui.ChannelOff(self.TRADE_CHANNEL)
        mov:Invoke("RemoveTradeFilter")
      end
      if Ui.GetUserOptionsValue("chatOptions", self.LFG_CHANNEL, "false") == "true" then
