      mov:Invoke("SetShowChatLog", Ui.GetUserOptionsValue("chatOptions", "SetShowChatLog", "false"))
    end,
    saveMySettings = function(self)
      Ui.SetChatColorFgBgSz(self.fgColor, self.bgColor, self.fontSize)
    end,
    SetFadable = function(self, fadable)
      local mov = GfxCtrl.Find(self.nameChatSwf)
      mov:Invoke("SetFadable", tonumber(fadable))
    end,
    SaveTextBoxSize = function(self, w, h)
      Ui.SetUserOptionsValue("chatOptions", "TextBoxW", w)
