      Logger:print("chatlog.lua", "width" .. sw .. " scale " .. Ui.GetFontScalePercent())
      if Ui.GetFontScalePercent() > 101 then
        m:Invoke("resetLineHeight", 23)
      else
        m:Invoke("resetLineHeight", 18.7)
      end
    end
  }
  function Main_wndChatLog_swfChatLog_OnUserEvent(a, b, c, d)
    if a == "setShowChannel" then
      Ui.SetUserOptionsValue("chatOptions", b, c)
      ChatLog:setChannelsShowing()
    elseif a == "toggleCannedChat" then
      if ChatLog.isNotHidden then
        if Ui.IsChatAllowed() then
          chatHandler:ToggleCannedChat(0)
        else
          PopUpPrompt:Show()
          PopUpPrompt:SetLayout(PopUpPrompt.LT_CHAT_DISABLED)
        end
      end
    elseif a == "toggleEmotes" then
      if ChatLog.isNotHidden then
        chatHandler:ToggleCannedChat(1)
      end
    elseif a == "toggleShowLog" then
      if ChatLog.isNotHidden then
        ChatLog:SetShowChatLog(b)
        Logger:print("chatlog.lua", "toggleShowLog " .. tostring(b))
        if b == "true" then
          Logger:print("chatlog.lua", "isTextOpen true")
          ChatLog.isTextOpen = 1
        else
          ChatLog.isTextOpen = 0
        end
        local win = Window.Find(ChatLog.nameChatWnd)
        if win then
          win:SetProperty("ZLayer", 16)
          win:SetProperty("Legend", 0)
        end
      end
    elseif a == "expandingLog" then
      ChatLog:ExpandLog()
    elseif a == "showVKeyboard" then
      if ChatLog.isNotHidden then
        if Ui.IsChatAllowed() then
          if b and b ~= "" and b ~= " " then
            local text = b .. " "
            Ui.LuaRequestVirtualKeyboard(0, text, "Chat")
          else
            Ui.LuaRequestVirtualKeyboard(0, "", "Chat")
          end
        else
          PopUpPrompt:Show()
          PopUpPrompt:SetLayout(PopUpPrompt.LT_CHAT_DISABLED)
        end
      end
    elseif a == "setGameDockFilter" then
      GameDock:SetFilter(b, c)
    elseif a == "loadSettings" then
      ChatLog:LoadSetting()
      if ChatLog.needToSetGroupFilter ~= nil then
        ChatLog:SetGroupFilter(ChatLog.needToSetGroupFilter)
        ChatLog.needToSetGroupFilter = nil
      end
      ChatLog:SetGuildFilter()
      ChatLog:SetIsMember()
      ChatLog:ParseQueuedMessages()
    elseif a == "saveTextBoxSize" then
      ChatLog:SaveTextBoxSize(b, c)
    elseif a == "onNameClicked" then
    elseif a == "addFriend" then
      if Ui.AddFriend then
        SocialHandler:SetToFront()
        Ui.AddFriend(b)
      end
    elseif a == "removeFriend" then
      if Ui.RemoveFriend then
        SocialHandler:SetToFront()
        Ui.RemoveFriend(b)
      end
    elseif a == "ignore" then
      Ui.IgnorePlayer(b)
    elseif a == "report" then
      Ui.ReportAsOffensive(b)
    elseif a == "startChat" then
      if Ui.IsChatAllowed() then
        Ui.LuaRequestVirtualKeyboard(0, "/tell \"" .. b .. "\" ", "Chat")
      else
        PopUpPrompt:Show()
        PopUpPrompt:SetLayout(PopUpPrompt.LT_CHAT_DISABLED)
      end
    elseif a == "setCurrentFilter" then
      ChatLog.currentFilter = b
    elseif a == "killFocus" then
      Window.SetFocus()
    elseif a == "onLoad" then
      ChatLog:ShowList()
      ChatLog.isLoaded = true
    elseif a == "playSound" then
      HUD:PlaySound(b)
    elseif a == "onWhisperReply" then
      GameDock:SetTextEntry(1, "/tell \"" .. b .. "\" ")
    elseif a == "ASPrint" then
      print("ASPrint: " .. b)
    elseif a == "GetMousePosition" then
      ChatLog:GetMousePosition()
    elseif a == "SetInterceptMouseWheel" then
      HUD.MouseWheelConsumed = b
    elseif a == "enableOnUnFocus" then
      chatHandler:EnableOnUnFocus(tonumber(b))
    end
  end
  function Main_wndChatLog_swfChatLog_OnFocus(a, b)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndChatLog_swfChatLog_OnLeave(a, b, c)
    ChatLog:OnLeave()
  end
  function Main_wndChatLog_swfChatLog_OnEnter(a, b, c)
    ChatLog:OnEnter()
  end
  Client.ChatLog = "ChatLog"
  function OnPrint(text, sizeChat, fgColor, bgColor, noReturn)
    _G[Client.ChatLog]:AddMessage(nil, nil, text, sizeChat, fgColor, bgColor)
    OnPrintConsole(text, noReturn)
  end
end)()
;(function()
  ItemActionBarCol = {
    IsEmpty = 0,
    IconID = 1,
    Name = 2,
    IsEnabled = 3,
    RefreshTimeLeft = 4,
    TotalRefreshTime = 5,
    Quantity = 6,
    IsTargeting = 7,
    IconTintValue = 8
  }
  QuickItem = {
    firstSlotPopulated = false,
    isShowing = false,
    m_columns = {
      "IsEmpty",
      "IconId",
      "Name",
      "IsEnabled",
      "RefreshTimeRemaining",
      "TotalRefreshTime",
      "Quantity",
      "IsTargeting"
    },
    Show = function(self)
      if not self.isShowing then
        self.isShowing = true
        DsTable.Find("BaseClient.ItemActionBar"):EnableScriptEvents()
        self:Populate()
      end
    end,
    OnResize = function(self)
    end,
    Hide = function(self)
    end,
    Populate = function(self, rowId)
      local m_ps3 = GameDock_PS3:GetItemSwf()
      local ds = DsTable.Find("BaseClient.ItemActionBar")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        if rowId then
          if rowId == 0 then
            if tonumber(ds:GetData(i, ItemActionBarCol.IsEmpty)) == 0 then
              self.firstSlotPopulated = true
            else
              self.firstSlotPopulated = false
            end
          end
          m_ps3:Invoke("setButtonData", rowId + 5, tonumber(ds:GetData(rowId, ItemActionBarCol.IconID)), ds:GetData(rowId, ItemActionBarCol.Name), tonumber(ds:GetData(rowId, ItemActionBarCol.Quantity)), tonumber(ds:GetData(rowId, ItemActionBarCol.IconTintValue)), tonumber(ds:GetData(rowId, ItemActionBarCol.IsEnabled)))
          m_ps3:Invoke("setItemCountForButton", rowId + 5, ds:GetData(rowId, ItemActionBarCol.Quantity))
        else
          for i = 0, numRows - 1 do
            if ds:GetData(i, ItemActionBarCol.IsEmpty) ~= "1" then
              if i == 0 then
                if tonumber(ds:GetData(i, ItemActionBarCol.IsEmpty)) == 0 then
                  self.firstSlotPopulated = true
                else
                  self.firstSlotPopulated = false
                end
              end
              m_ps3:Invoke("setButtonData", i + 5, tonumber(ds:GetData(i, ItemActionBarCol.IconID)), ds:GetData(i, ItemActionBarCol.Name), tonumber(ds:GetData(i, ItemActionBarCol.Quantity)), tonumber(ds:GetData(i, ItemActionBarCol.IconTintValue)), tonumber(ds:GetData(i, ItemActionBarCol.IsEnabled)))
            end
            if 0 < tonumber(ds:GetData(i, ItemActionBarCol.RefreshTimeLeft)) then
              QuickItem:setTimer(i, ds:GetData(i, ItemActionBarCol.TotalRefreshTime), tonumber(ds:GetData(i, ItemActionBarCol.TotalRefreshTime)) - tonumber(ds:GetData(i, ItemActionBarCol.RefreshTimeLeft)))
            end
            if ds:GetData(i, ItemActionBarCol.IsEnabled) == "1" then
              QuickItem:itemEnabled(i)
            else
              QuickItem:itemDisabled(i)
            end
          end
        end
      end
    end,
    PopulateSelectors = function(self)
    end,
    setTimer = function(self, index, duration, curProgress)
      local movie = GameDock_PS3:GetItemSwf()
      if movie ~= nil then
        movie:Invoke("buttonTimer", index + 5, tonumber(duration), tonumber(curProgress + 1))
      end
    end,
    itemDisabled = function(self, index)
      local movie = GameDock_PS3:GetItemSwf()
      if movie ~= nil then
        movie:Invoke("iconDisable", index + 5)
      end
    end,
    itemEnabled = function(self, index)
      local movie = GameDock_PS3:GetItemSwf()
      if movie ~= nil then
        movie:Invoke("iconEnable", index + 5)
      end
    end,
    ActivateItem = function(self, index)
      Ui.ClickedAbility(tonumber(index) - 5, 2)
      local ds = DsTable.Find("BaseClient.ItemActionBar")
    end
  }
  function BaseClient_ItemActionBar_OnDataChanged(row, col, newValue)
    local ds = DsTable.Find("BaseClient.ItemActionBar")
    if tonumber(col) == 0 or tonumber(col) == 6 or tonumber(col) == 3 then
      if newValue == 0 then
        QuickItem:setTimer(row, 250, 1)
      end
      QuickItem:Populate(row)
      QuickItem:setTimer(row, ds:GetData(row, 5), tonumber(ds:GetData(row, 5) - ds:GetData(row, 4)))
    end
    if tonumber(col) == 4 then
      QuickItem:setTimer(row, ds:GetData(row, 5), tonumber(ds:GetData(row, 5) - ds:GetData(row, 4)))
    end
    EquipmentHandler:SetCurrentEquip(1)
    if FishFinder.usingLure == true then
      FishFinder:LureEquipped()
    elseif 0 < FishFinder.numItems then
      FishFinder:DataUpdated()
    end
  end
  function Main_wndNonCombatItemBar_swfNonCombatItemBar_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
;(function()
  HousingAccessListColumn = {
    InstanceGuid = 0,
    OwnerGuid = 1,
    OwnerName = 2,
    HouseName = 3,
    IconId = 4
  }
  HousingSubMenu = {
    subMenuWindowName = Ui.GetName("Main.wndHousingSubMenu"),
    subMenuSwfName = Ui.GetName("Main.wndHousingSubMenu.swfHousingSubMenu"),
    isUp = false,
    isStoreNav = false,
    isPlayerHouses = false,
    stopKill = false,
    Show = function(self)
      Logger:print("HousingSubMenu.lua", "Show")
      local subMenuWindow = Window.Find(self.subMenuWindowName)
      if subMenuWindow then
        Logger:print("HousingSubMenu.lua", "Show Window Found")
        self.isStoreNav = false
        local xm, ym = Ui.GetMousePos()
        local sw, sh = Window.GetCanvasSize()
        local wndW, wndH = subMenuWindow:GetSize()
        if self.isPlayerHouses then
          subMenuWindow:SetPosition(sw / 2 - wndW / 2, sh / 2 - wndH / 2)
        else
          subMenuWindow:SetPosition(sw / 2 - wndW / 2, sh / 2 - wndH / 2)
        end
        self:Populate()
        if self.isPlayerHouses then
        else
          WindowTweener:Create("Main.wndHousingSubMenu", "Y", nil, sh - 175, 0.3)
        end
        subMenuWindow:Show()
        GameDock.lockedOut = false
        self.isUp = true
        NonModalContext:AddContext(self)
        GameDock:DetermineButtonSelection()
      end
    end,
    ShowMyHouses = function(self)
      self.isPlayerHouses = false
      self:Show()
    end,
    ShowPlayerHouses = function(self)
      self.isPlayerHouses = true
      self:Show()
    end,
    Hide = function(self)
      local subMenuWindow = Window.Find(self.subMenuWindowName)
      subMenuWindow:Hide()
    end,
    OnResize = function(self)
      self:Hide()
    end,
    Populate = function(self)
      local ds
      local mov = GfxCtrl.Find(self.subMenuSwfName)
      Logger:print("HousingSubMenu.lua", "Populate Called")
      mov:Invoke("ResetItems")
      mov:Invoke("SetModeToStoreNav", 0)
      if self.isPlayerHouses then
        ds = DsTable.Find("BaseClient.Housing.PlayerHouseList")
      else
        ds = DsTable.Find("BaseClient.Housing.MyHouseList")
      end
      local numRows = ds:GetRowCount()
      for i = 0, numRows - 1 do
        mov:Invoke("AddItem", ds:GetData(i, HousingAccessListColumn.InstanceGuid), ds:GetData(i, HousingAccessListColumn.IconId), ds:GetData(i, HousingAccessListColumn.HouseName))
        Logger:print("HousingSubMenu.lua", "InstanceGuid: " .. ds:GetData(i, HousingAccessListColumn.InstanceGuid) .. " IconId: " .. ds:GetData(i, HousingAccessListColumn.IconId) .. " HouseName: " .. ds:GetData(i, HousingAccessListColumn.HouseName))
      end
    end,
    ShowAsStoreNav = function(self)
      local subMenuWindow = Window.Find(self.subMenuWindowName)
      if subMenuWindow then
        self.isStoreNav = true
        local xm, ym = Ui.GetMousePos()
        local sw, sh = Window.GetCanvasSize()
        local wndW, wndH = subMenuWindow:GetSize()
        subMenuWindow:SetPosition(xm - wndW / 2, sh + 100)
        local mov = GfxCtrl.Find(self.subMenuSwfName)
        mov:Invoke("ResetItems")
        mov:Invoke("SetModeToStoreNav", 1)
        mov:Invoke("AddItem", MarketplaceEnum.PORTAL, 798, MarketplaceStrings.MARKETPLACE)
        mov:Invoke("AddItem", MarketplaceEnum.COIN_STORE, 22665, MarketplaceStrings.COINSHOP_LABEL_TITLE)
        mov:Invoke("AddItem", MarketplaceEnum.MEMBERSHIP, 703, MarketplaceStrings.MEMBERSHIP)
        mov:Invoke("AddItem", MarketplaceEnum.CLAIM, 28546, MarketplaceStrings.CLAIM)
        subMenuWindow:Show()
        WindowTweener:Create("Main.wndHousingSubMenu", "Y", nil, sh - 175, 0.3)
        GameDock.lockedOut = false
        self.isUp = true
        if FirstTimeEventHandler.activePane == true then
          TutorialDialog:Hide()
        end
        GameDock:DetermineButtonSelection()
      end
    end
  }
  function Main_wndHousingSubMenu_swfHousingSubMenu_OnUserEvent(a, b, c, d)
    if a == "housingItemSelected" then
      FriendsWidget:Hide()
      HousingSubMenu:Hide()
      HUD:PlaySound("DockSelect")
      House.Enter(b)
    elseif a == "storeNavItemSelected" then
      CoinStoreHandler.referrerId = 0
      CoinStoreHandler.referrerContext = CoinStoreReferrerElementEnum.GAME_DOCK
      MarketplaceHandler:Show(b)
      HUD:PlaySound("DockSelect")
      HousingSubMenu:Hide()
    elseif a == "onHoverOver" then
      HousingSubMenu.stopKill = true
    elseif a == "onHoverOut" then
      HousingSubMenu.stopKill = false
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "ASPrint" then
      print("ASPrint:" .. b)
    elseif a == "cancelHouseSelection" then
      HousingSubMenu:Hide()
    end
  end
  function Main_wndHousingSubMenu_swfHousingSubMenu_OnFocus(a, b, c)
    if tonumber(a) == 1 and not HousingSubMenu.stopKill then
      Window.SetFocus()
    elseif tonumber(a) == 0 then
      HousingSubMenu:Hide()
      Window.SetFocus()
    end
  end
end)()
