      return GfxCtrl.Find(self.exploreButtonSwfName)
    end,
    SetIsInInstance = function(self, n, p)
      if self.isInInstance == n then
        return
      end
      JobHandler:Hide()
      if n == false then
        self.currentInstance = nil
      end
      self.isInInstance = n
      if Housing.isInInstance then
        if HUD.inMiniGame then
          Ui.QuitMiniGame()
        else
          self:ShowHousingUiTasks()
        end
        GameDock_PS3:SetVisibility(0)
      else
        editMode = false
        self.isEditButtonTweening = 0
        self:HideUi()
        GameDock_PS3:Show()
      end
      if not HUD.inMiniGame then
        GameDock:SetState(GameDock.NORMAL_STATE)
      end
      LUABroadcaster:dispatchEvent(Housing, "SetIsInInstance", n, p)
    end,
    Leave = function(self)
      if self.isInInstance then
        Logger:print("housing.lua", "Leaving House Instance")
        if self.housingMode == 1 then
