        QuestHelper:CloseHelper()
      end
      self:OnUpdateHousingInstanceInfo()
    end,
    ShowHouses = function(self)
      if HUD.showHousing then
        local ds = DsTable.Find("BaseClient.Housing.MyHouseList")
        local numRows = ds:GetRowCount()
        if ds and numRows == 1 then
          House.Enter(ds:GetData(numRows - 1, HousingAccessListColumn.InstanceGuid))
        elseif numRows > 1 then
          HousingSubMenu:ShowMyHouses()
        else
          GameDock.lockedOut = false
        end
      end
    end,
    ShowUi = function(self)
      Window.SetFocus()
      self:OnUpdateHousingInstance()
      local ds = DsTable.Find("BaseClient.Housing.Instance")
      if ds then
        ds:EnableScriptEvents()
