      local ds2 = DsTable.Find("BaseClient.Housing.Instance.SelectedFixture")
      if ds2 then
        ds2:EnableScriptEvents()
      end
      local ds3 = DsTable.Find("BaseClient.InventoryItemsData")
      if ds3 then
        ds3:EnableScriptEvents()
      end
      local ds4 = DsTable.Find("BaseClient.Housing.InstanceInfo")
