      local exploreButtonWindow = Window.Find(self.exploreButtonWindowName)
      local exploreButtonSwf = GfxCtrl.Find(self.exploreButtonSwfName)
      exploreButtonWindow:Hide()
      exploreButtonSwf:Unload()
      local editPanelWindow = self:GetEditPanelWindow()
      local editPanelSwf = self:GetEditPanelSwf()
      editPanelWindow:Hide()
      editPanelSwf:Unload()
