        self.m_questHelperWasClosed = false
        QuestHelper.isHelperShown = 1
      end
    end,
    OnResize = function(self)
      local sw, sh = Window.GetCanvasSize()
      if self.editMode == true then
        local editPanelWindow = self:GetEditPanelWindow()
        if editPanelWindow then
          local panelW, panelH = editPanelWindow:GetSize()
          WindowTweener:Create("Main.wndHousingEditPanel", "X", nil, (sw - panelW) / 2, 0.3)
          WindowTweener:Create("Main.wndHousingEditPanel", "Y", nil, sh - panelH - 88, 0.3)
        end
      elseif self.housingMode == 1 then
        local editButtonWindow = Window.Find(self.editButtonWindowName)
        if editButtonWindow then
          local buttonW, buttonH = editButtonWindow:GetSize()
          WindowTweener:Create("Main.wndHousingEditButton", "X", nil, (sw - buttonW) / 2, 0.3)
          WindowTweener:Create("Main.wndHousingEditButton", "Y", nil, 60, 0.3)
        end
      else
        local exploreButtonWindow = Window.Find(self.exploreButtonWindowName)
        if exploreButtonWindow then
          local buttonW, buttonH = exploreButtonWindow:GetSize()
          WindowTweener:Create("Main.wndHousingExploreButton", "X", nil, (sw - buttonW) / 2, 0.3)
          WindowTweener:Create("Main.wndHousingExploreButton", "Y", nil, 60, 0.3)
        end
      end
    end,
    MainShown = function(self, is)
      if self.isInInstance then
        if is then
          self:ShowUi()
        else
          self:Reset()
        end
      end
    end,
    ShowEditButton = function(self)
      if self.housingMode == 1 then
        local editButtonWindow = Window.Find(self.editButtonWindowName)
        if editButtonWindow then
          Logger:print("housing.lua", "showing edit button")
          self.editButtonShown = 1
          local sw, sh = Window.GetCanvasSize()
          local wndW, wndH = editButtonWindow:GetSize()
          editButtonWindow:SetPosition((sw - wndW) / 2, 60)
          editButtonWindow:Show()
          self:OnResize()
        end
      else
        local exploreButtonWindow = Window.Find(self.exploreButtonWindowName)
        if exploreButtonWindow then
          Logger:print("housing.lua", "showing explore button")
          self.exploreButtonShown = 1
          local sw, sh = Window.GetCanvasSize()
          local wndW, wndH = exploreButtonWindow:GetSize()
          exploreButtonWindow:SetPosition((sw - wndW) / 2, 60)
          exploreButtonWindow:Show()
          self:OnResize()
        end
      end
    end,
    HideEditButton = function(self)
      if self.housingMode == 1 then
        do
          local editButtonWindow = Window.Find(self.editButtonWindowName)
          local editButtonSwf = GfxCtrl.Find(self.editButtonSwfName)
          if editButtonWindow then
            Logger:print("housing.lua", "hiding edit button")
            self.editButtonShown = 0
            local sw, sh = Window.GetCanvasSize()
            WindowTweener:Create("Main.wndHousingEditButton", "Y", nil, -100, 0.3, function()
              print("clearing tween")
              self.isEditButtonTweening = 0
              editButtonWindow:Hide()
              editButtonSwf:Unload()
            end)
          end
        end
      else
        do
          local exploreButtonWindow = Window.Find(self.exploreButtonWindowName)
          local exploreButtonSwf = GfxCtrl.Find(self.exploreButtonSwfName)
          if exploreButtonWindow then
            Logger:print("housing.lua", "hiding explore button")
            self.exploreButtonShown = 0
            local sw, sh = Window.GetCanvasSize()
            WindowTweener:Create("Main.wndHousingExploreButton", "Y", nil, -100, 0.3, function()
              print("clearing tween")
              self.isEditButtonTweening = 0
              exploreButtonWindow:Hide()
              exploreButtonSwf:Unload()
            end)
          end
        end
      end
    end,
    ShowEditPanel = function(self)
      if not self.editMode then
        self.editMode = true
        local editPanelWindow = self:GetEditPanelWindow()
        if editPanelWindow and self.allowEdit then
          local sw, sh = Window.GetCanvasSize()
          local wndW, wndH = editPanelWindow:GetSize()
          editPanelWindow:SetPosition((sw - wndW) / 2, sh - wndH - 90)
          editPanelWindow:Show()
          self:PopulateEditPanel()
          self:OnResize()
          GameDock_PS3:SetVisibility(0)
          GameDock_PS3:HideItemDock()
          ActionDock_PS3:HideDock()
        end
      end
    end,
    HideEditPanel = function(self)
      self.editMode = false
      Context:Pop()
      local editPanelWindow = self:GetEditPanelWindow()
      local editPanelSwf = self:GetEditPanelSwf()
      if editPanelWindow then
        local sw, sh = Window.GetCanvasSize()
        WindowTweener:Create("Main.wndHousingEditPanel", "Y", nil, sh + 50, 0.3, function()
          editPanelWindow:Hide()
          editPanelSwf:Unload()
        end)
      end
      GameDock_PS3:SetVisibility(0)
    end,
    PopulateEditPanel = function(self, achievementID)
      self:PopulateCategories()
      self:PopulateItems()
      self:SetData()
    end,
    PopulateCategories = function(self)
      local mov = self:GetEditPanelSwf()
      mov:Invoke("ResetCategories")
      local ds = DsTree.Find(DataSourceTrees[DST_INVENTORY_CATEGORIES_DATA])
      if ds then
        local root = ds:GetRootNode()
        for i = 0, root:GetChildCount() - 1 do
          local child = root:GetChildNode(i)
          if tonumber(child:GetData(0)) == self.HOUSING_FIXTURE_ID then
            mov:Invoke("AddCategoryItem", tonumber(child:GetData(0)), tonumber(child:GetBitmapIndex()), child:GetText())
          end
          if tonumber(child:GetData(0)) == self.HOUSING_CAT_ID then
            for j = 0, child:GetChildCount() - 1 do
              local subChild = child:GetChildNode(j)
              local tooltip = subChild:GetText()
              if tonumber(subChild:GetData(0)) == self.CATID_ROOF then
                tooltip = Ui.GetString("housingRoofTooltip")
              end
              mov:Invoke("AddCategoryItem", tonumber(subChild:GetData(0)), tonumber(subChild:GetBitmapIndex()), tooltip)
            end
          end
        end
      end
      mov:Invoke("AddCategoryItem", 1001, 33372, "Lock House")
      mov:Invoke("AddCategoryItem", 1002, 33373, "Snap To Grid")
      mov:Invoke("SelectCategoryByIndex", 0)
    end,
    SelectCategory = function(self, categoryId)
      self.m_categoryPressed = true
      self.m_categoryId = tonumber(categoryId)
      if categoryId ~= nil then
        InventoryScreen.SelectInventoryCategory(categoryId)
      end
    end,
    PopulateItems = function(self)
      local mov = self:GetEditPanelSwf()
      mov:Invoke("ResetItems")
      if self.m_categoryId == self.CATID_WALL or self.m_categoryId == self.CATID_FLOOR or self.m_categoryId == self.CATID_ROOF then
        mov:Invoke("AddItem", 0, self.NONE_ICON, Ui.GetString("NoneItem"), "", 0, 0, -1)
      end
      local ds = DsTable.Find("BaseClient.InventoryItemsData")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          Logger:print("housing.lua", "Adding Item: " .. ds:GetData(i, HousingItemColumn.Name) .. "(" .. ds:GetData(i, HousingItemColumn.IconID) .. ") with Tint of " .. ds:GetData(i, HousingItemColumn.TintValue))
          mov:Invoke("AddItem", ds:GetData(i, HousingItemColumn.ItemGuid), tonumber(ds:GetData(i, HousingItemColumn.IconID)), ds:GetData(i, HousingItemColumn.Name), ds:GetData(i, HousingItemColumn.Description), tonumber(ds:GetData(i, HousingItemColumn.Quantity)), tonumber(ds:GetData(i, HousingItemColumn.MembersOnly)), tonumber(ds:GetData(i, HousingItemColumn.TintValue)))
        end
        if self.m_categoryPressed then
          mov:Invoke("DisplayItems")
        else
          mov:Invoke("SetToSavedPage")
        end
        self.m_categoryPressed = false
      end
      self:SetGrid()
    end,
    SetData = function(self)
      local ds = DsTable.Find("BaseClient.Housing.Instance")
      if ds then
        local curFixtureCount = tonumber(ds:GetData(0, HousingInstanceColumn.CurFixtureCount))
        local maxFixtureCount = tonumber(ds:GetData(0, HousingInstanceColumn.MaxFixtureCount))
        local curLandMarkCount = tonumber(ds:GetData(0, HousingInstanceColumn.CurLandmarkCount))
        local maxLandMarkCount = tonumber(ds:GetData(0, HousingInstanceColumn.MaxLandmarkCount))
        self:GetEditPanelSwf():Invoke("SetCounts", curFixtureCount, maxFixtureCount, curLandMarkCount, maxLandMarkCount)
        self:GetEditPanelSwf():Invoke("SetLock", tonumber(ds:GetData(0, HousingInstanceColumn.IsLocked)))
      end
    end,
    ToggleEditMode = function(self)
      if self.housingMode == 0 then
        self.isEditButtonTweening = 1
        self:HideEditButton()
        Mount.Dismount()
        self.housingMode = 1
        self:ShowEditButton()
        GameDock_PS3:Hide()
        if self:GetButtonPanelSwf() then
          self:GetButtonPanelSwf():Invoke("setMode", self.housingMode)
        end
      else
        self.isEditButtonTweening = 1
        self:HideEditButton()
        self.housingMode = 0
        self:ShowEditButton()
        GameDock_PS3:Show()
        if self:GetExploreButtonPanelSwf() then
          self:GetExploreButtonPanelSwf():Invoke("setMode", self.housingMode)
        end
      end
      House.ToggleEditMode()
    end,
    TogglePanelModePS3 = function(self)
      if self.editPanelMode == 0 then
        self.editPanelMode = 1
        self:ShowEditPanel()
        self:HideEditButton()
      else
        self.editPanelMode = 0
        self:HideEditPanel()
        self:ShowEditButton()
        ToolTipHandler:HideToolTip()
        if self:GetButtonPanelSwf() then
          self:GetButtonPanelSwf():Invoke("setMode", self.housingMode)
        end
      end
      Logger:print("housing.lua", "setting panel mode to " .. self.editPanelMode)
      House.ToggleEditPanelModePS3()
    end,
    TogglePanelModePS3FromSelection = function(self)
      self.editPanelMode = 0
      self.editMode = false
      Context:Pop()
      local editPanelWindow = self:GetEditPanelWindow()
      local editPanelSwf = self:GetEditPanelSwf()
      if editPanelWindow then
        local sw, sh = Window.GetCanvasSize()
        WindowTweener:Create("Main.wndHousingEditPanel", "Y", nil, sh + 50, 0.3, function()
          editPanelWindow:Hide()
          editPanelSwf:Unload()
          GameDock_PS3:SetVisibility(0)
        end)
      end
      self:ShowEditButton()
      ToolTipHandler:HideToolTip()
      if self:GetButtonPanelSwf() then
        self:GetButtonPanelSwf():Invoke("setMode", self.housingMode)
      end
      Logger:print("housing.lua", "setting panel mode (from selection) to " .. self.editPanelMode)
      House.ToggleEditPanelModePS3()
    end,
    ToggleGrid = function(self)
      if self.gridSpacing == self.GRID_SIZE_OFF then
        self.gridSpacing = self.GRID_SIZE_ON
      else
        self.gridSpacing = self.GRID_SIZE_OFF
      end
      Ui.SetUserOptionsValue("Housing", "gridSpacing", self.gridSpacing)
      self:SetGrid()
    end,
    SetGrid = function(self)
      self.gridSpacing = tonumber(Ui.GetUserOptionsValue("Housing", "gridSpacing", self.GRID_SIZE_OFF))
      local toggleOn = 1
      if self.gridSpacing == self.GRID_SIZE_OFF then
        toggleOn = 0
      end
      print("self.gridSpacing: " .. tostring(self.gridSpacing))
      print("toggleOn: " .. tostring(toggleOn))
      self:GetEditPanelSwf():Invoke("setGrid_lua", toggleOn)
      if House.SetGridSpacingInCentimeters then
        House.SetGridSpacingInCentimeters(self.gridSpacing)
      end
    end,
    OnUpdateHousingInstanceInfo = function(self)
      local ds = DsTable.Find("BaseClient.Housing.InstanceInfo")
      if not ds or not (ds:GetRowCount() > 0) or self.isInInstance then
      end
    end,
    OnUpdateHousingInstance = function(self)
      local ds = DsTable.Find("BaseClient.Housing.Instance")
      if ds and self.isInInstance then
        self.allowEdit = tonumber(ds:GetData(0, HousingInstanceColumn.CanEdit)) == 1
        if self.allowEdit then
          SocialHandler:SetIsInHouse(1, 1)
          if tonumber(ds:GetData(0, HousingInstanceColumn.InEditMode)) == 0 then
          else
            self:SetData()
          end
          if self.editPanelMode == 0 then
            if self.housingMode == 1 then
              if self.editButtonShown == 0 then
                Logger:print("housing.lua", "showing edit button in OnUpdate")
                self:ShowEditButton()
              end
            elseif self.exploreButtonShown == 0 then
              Logger:print("housing.lua", "showing edit button in OnUpdate")
              self:ShowEditButton()
            end
          elseif self.housingMode == 0 then
            if self.editButtonShown == 1 then
              Logger:print("housing.lua", "hiding edit button in OnUpdate")
              self:HideEditButton()
            end
          elseif self.exploreButtonShown == 1 then
            Logger:print("housing.lua", "hiding edit button in OnUpdate")
            self:HideEditButton()
          end
        else
          SocialHandler:SetIsInHouse(1, 0)
          self:HideEditButton()
          self:HideEditPanel()
        end
      end
      GameDock:SetState(GameDock.NORMAL_STATE)
      MiniMap:Configure()
    end,
    OnRadialMenuClick = function(self, buttonId)
      if buttonId == self.INTERACTION_PICK_UP then
        House.PickupFixture(currentItemGuid)
      elseif buttonId == self.INTERACTION_MOVE then
        House.MoveFixture(currentItemGuid)
      elseif buttonId == self.INTERACTION_ROTATE_RIGHT then
        House.RotateFixtureClockwise(currentItemGuid)
      elseif buttonId == self.INTERACTION_ROTATE_LEFT then
        House.RotateFixtureCounterClockwise(currentItemGuid)
      else
        if buttonId == self.INTERACTION_VERTICAL_MOVE then
          House.MoveFixtureVertically(currentItemGuid)
        else
        end
      end
    end,
    OnRadialMenuClosed = function(self)
    end,
    ItemSelected = function(self, id)
      if self.m_categoryId == self.CATID_WALL or self.m_categoryId == self.CATID_FLOOR or self.m_categoryId == self.CATID_ROOF then
        self:ApplyFixtureCustomization(id)
      else
        House.PlaceFixture(id)
      end
    end,
    ShowBoundToHouseRestrictionMessage = function()
      MessageWindow:RegisterCaller(Housing)
      MessageWindow:Show()
      MessageWindow:SetText(Ui.GetString("MoneyTreeMessageTitle"), Ui.GetString("OnMoneyTreeMessageOkay"), 0)
      MessageWindow:SetButton(Ui.GetString("MoneyTreeMessageOkay"), "OnRestrictionMessageOkay")
      MessageWindow:SetButton(Ui.GetString("MoneyTreeMessageCancel"), "OnRestrictionMessageCancel")
    end,
    OnRestrictionMessageOkay = function(self)
      MessageWindow:Hide()
      if House.PlacePendingFixture then
        House.PlacePendingFixture()
        Ui.TriggerFirstTimeEvent("FtesCoinPlant")
      end
    end,
    OnRestrictionMessageCancel = function(self)
      MessageWindow:Hide()
      if House.CancelPendingFixture then
        House.CancelPendingFixture()
      end
    end,
    ApplyFixtureCustomization = function(self, id)
      local group = House.GetFixtureGroupByType(CatStrs[self.CATID_FLOOR])
      if group == "" then
        group = self.GROUPID_EXT
      end
      if House.DoesGroupHaveCustomizableFixture(group, CatStrs[self.m_categoryId]) == 0 then
        if self.m_categoryId == self.CATID_ROOF then
          NotificationHandler:AlertMessage(Ui.GetString("housingRoofNotification"))
          return
        end
        if self.m_categoryId == self.CATID_FLOOR then
          return
        end
      end
      if tonumber(id) == 0 then
        House.RemoveFixtureCustomizationFromGroup(group, CatStrs[self.m_categoryId])
      else
        House.ApplyFixtureCustomizationToGroup(group, CatStrs[self.m_categoryId], id)
      end
    end
  }
  function Main_wndHousingEditButton_swfHousingEditButton_OnUserEvent(a, b)
    if a == "housingEditButtonRelease" and Housing.isEditButtonTweening == 0 then
      Housing:ToggleEditMode()
      Logger:print("housing.lua", "Decorate (Edit Mode) Button Pressed -> Entering Explore mode")
    elseif a == "housingExploreButtonRelease" and Housing.isEditButtonTweening == 0 then
      Housing:ToggleEditMode()
      Logger:print("housing.lua", "Decorate (EXplore Mode) Button Pressed -> Entering Decorate mode")
    elseif a == "selectButtonRelease" then
      Housing:TogglePanelModePS3()
      Logger:print("housing.lua", "Edit Select Button Pressed -> Entering Edit mode")
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    end
  end
  function Main_wndHousingExploreButton_swfHousingExploreButton_OnUserEvent(a, b)
    if a == "housingEditButtonRelease" and Housing.isEditButtonTweening == 0 then
      Housing:ToggleEditMode()
      Logger:print("housing.lua", "Explore (Edit Mode) Button Pressed -> Entering Explore mode")
    elseif a == "housingExploreButtonRelease" and Housing.isEditButtonTweening == 0 then
      Housing:ToggleEditMode()
      Logger:print("housing.lua", "Explore (Explore Mode) Button Pressed -> Entering Decorate mode")
    elseif a == "selectButtonRelease" then
      Housing:TogglePanelModePS3()
      Logger:print("housing.lua", "Explore Select Button Pressed -> Entering Edit mode")
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    end
  end
  function Main_wndHousingEditPanel_swfHousingEditPanel_OnUserEvent(a, b)
    if a == "itemSelected" then
      Housing:ItemSelected(b)
      Housing:TogglePanelModePS3FromSelection()
    elseif a == "CategorySelected" then
      Housing:SelectCategory(b)
    elseif a == "ExitButtonClicked" then
      Housing:TogglePanelModePS3()
    elseif a == "ToggleLock" then
      House.ToggleIsHouseLocked()
    elseif a == "ToggleGrid" then
      Housing:ToggleGrid()
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "ASPrint" then
      print("ASPrint: " .. tostring(b))
    end
  end
  function Main_wndHousingEditButton_swfHousingEditButton_OnFocus(a, b, c)
    if tonumber(a) == 1 then
      Window.SetFocus()
    end
  end
  function Main_wndHousingEditPanel_swfHousingEditPanel_OnFocus(a, b, c)
    if tonumber(a) == 1 then
      Window.SetFocus()
    end
  end
  function BaseClient_Housing_Instance_OnDataChanged()
    Housing:OnUpdateHousingInstance()
  end
  function BaseClient_Housing_Instance_OnDataUpdate()
    Housing:OnUpdateHousingInstance()
  end
  function BaseClient_Housing_InstanceInfo_OnDataUpdate()
    Housing:OnUpdateHousingInstanceInfo()
  end
  function BaseClient_Housing_Instance_Fixtures_OnDataInserted()
    Housing:SetData()
  end
  function BaseClient_Housing_Instance_Fixtures_OnDataRemoved()
    Housing:SetData()
  end
  function BaseClient_Housing_Instance_SelectedFixture_OnDataUpdate()
    local ds = DsTable.Find("BaseClient.Housing.Instance.SelectedFixture")
    currentItemGuid = ds:GetData(0, 0)
    if tonumber(currentItemGuid) == -1 then
      HousingRadialMenu:OnDeactivate()
    else
      local allowRemove = 0
      if House.IsActionPermitted and House.IsActionPermitted(currentItemGuid, "RemoveFixture") == 1 then
        allowRemove = 1
      end
      local xm, ym = Ui.GetMousePos()
      HousingRadialMenu:onPopup(xm, ym, "housing", 1234567890)
      HousingRadialMenu:setButtonCount(4 + allowRemove)
      HousingRadialMenu:setButton(0, 31249, Ui.GetString("Housing_Radial_Up"), Housing.INTERACTION_VERTICAL_MOVE, false)
      HousingRadialMenu:setButton(1, 22562, Ui.GetString("Housing_Radial_Rotate_Left"), Housing.INTERACTION_ROTATE_LEFT, true)
      HousingRadialMenu:setButton(2, 22556, Ui.GetString("Housing_Radial_Move"), Housing.INTERACTION_MOVE, false)
      if allowRemove == 1 then
        HousingRadialMenu:setButton(3, 22559, Ui.GetString("Housing_Radial_Remove"), Housing.INTERACTION_PICK_UP, false)
      end
      HousingRadialMenu:setButton(3 + allowRemove, 22565, Ui.GetString("Housing_Radial_Rotate_Right"), Housing.INTERACTION_ROTATE_RIGHT, true)
    end
  end
end)()
;(function()
  HousingRadialMenu = {
    activeArray = {},
    isDebug = false,
    isShown = false,
    offsetX = -500,
    offsetY = -200,
    hasContext = 0,
    WindowName = "Main.wndRadialMenu",
    MovieName = "Main.wndRadialMenu.swfRadial",
    onInit = function(self)
    end,
    Pop = function(self)
      if self.hasContext > 0 then
        Context:Pop()
        self.hasContext = 0
      end
      self:hide()
      Housing:OnRadialMenuClosed()
    end,
    setButtonCount = function(self, buttonCount)
      local theCtrl = GfxCtrl.Find(self.MovieName)
      if theCtrl ~= nil then
        theCtrl:Invoke("setButtonCount", tonumber(buttonCount))
      end
    end,
    setButton = function(self, buttonIndex, iconId, buttonText, buttonEventId, keepActive)
      self.activeArray[tonumber(buttonEventId)] = keepActive
      local theCtrl = GfxCtrl.Find(self.MovieName)
      if theCtrl ~= nil then
        theCtrl:Invoke("setButton", tonumber(buttonIndex), tonumber(iconId), buttonText, tonumber(buttonEventId))
      end
    end,
    OnDeactivate = function(self)
      local theCtrl = GfxCtrl.Find("Main.wndRadialMenu.swfRadial")
      if self.isShown and theCtrl ~= nil then
        theCtrl:Invoke("FR_startCloseEffect")
      end
    end,
    onPopup = function(self, x, y)
      local theWindow = Window.Find(self.WindowName)
      if theWindow ~= nil then
        Main_wndRadialMenu_swfRadial_OnUserEvent = HousingRadialMenu.OnUserEvent
        Main_wndRadialMenu_OnActivate = HousingRadialMenu.OnActivate
        Main_wndRadialMenu_swfRadial_OnKeyDown = HousingRadialMenu.OnKeyDown
        theWindow:Show()
        theWindow:SetFocus()
        theWindow:MoveToFront()
        theWindow:SetPosition(x + self.offsetX, y + self.offsetY)
        self.isShown = true
        local theCtrl = GfxCtrl.Find(self.MovieName)
        if theCtrl ~= nil then
          theCtrl:Invoke("SetIsInHousing", 1)
          theCtrl:Invoke("FR_startOpenEffect", 350)
        end
        Ui.SetMovementEnabled(0)
      end
    end,
    hide = function(self)
      self.isShown = false
      local theCtrl = GfxCtrl.Find(self.MovieName)
      theCtrl:Invoke("SetIsInHousing", 0)
      local w1 = Window.Find("Main.wndRadialMenu")
      w1:Hide()
      w1:SetPosition(-500, -500)
      Window.SetFocus()
      Ui.SetMovementEnabled(1)
    end,
    toggleDebug = function(self)
      self.isDebug = not self.isDebug
    end,
    showDebugText = function(self, t)
      if self.isDebug then
      end
    end,
    OnUserEvent = function(a, b)
      if a == "radialMenuOpenStarted" then
        HousingRadialMenu.isOpening = true
      elseif a == "radialMenuOpenFinished" then
        HousingRadialMenu.isOpening = false
      elseif a == "radialMenuCloseFinished" then
        HousingRadialMenu:Pop()
      elseif a == "radialMenuClick" then
        if b ~= nil then
          if not HousingRadialMenu.activeArray[tonumber(b)] then
            HousingRadialMenu:OnDeactivate()
          end
          Housing:OnRadialMenuClick(tonumber(b))
        end
      elseif a == "PlaySound" then
        HUD:PlaySound(b)
      elseif a == "ASPrint" then
      end
    end,
    OnActivate = function(a, b, c, d, e, f)
      if tonumber(a) == 0 then
        HousingRadialMenu:OnDeactivate()
      end
    end,
    OnKeyDown = function(a, b)
      if Client.ReverseKeyName(a) == "Escape" then
        HousingRadialMenu:OnDeactivate()
      end
    end
  }
end)()
;(function()
  BrowserHandler = {
    wndName = "Main.wndBrowser",
    swfName = "Main.wndBrowser.swfBrowser",
