      if target == CollectionHandler then
        self.wndName = self.wndCollectionsName
        self.swfName = self.swfCollectionsName
      elseif target == JobBrowser then
        self.wndName = self.wndJobsName
        self.swfName = self.swfJobsName
      elseif target == PetsHandler then
        self.wndName = self.wndPetsName
        self.swfName = self.swfPetsName
      elseif target == RecipeHandler then
        self.wndName = self.wndRecipesName
