      wnd:SetSize(850, 740)
      local ww, wh = wnd:GetSize()
      local sw, sh = Window.GetCanvasSize()
      local xmod = self.xPosMod
      if xmod == nil then
        xmod = sw / 2 - ww / 2
      end
      xmod = xmod - 200
      wnd:SetPosition(xmod, ypos)
      wnd:Show()
      if self.targetObject == CollectionHandler and sh < 800 then
        ypos = ypos - 30
