;(function()
  AbilitiesHandler = {
    wndName = "Main.wndAbilityDesc",
    swfName = "Main.wndAbilityDesc.swfAbilityDesc",
    windowTweenSpeed = 0.3,
    align = 0,
    visible = false,
    debug = false,
    Show = function(self)
      if self.visible == false then
        self.visible = true
        NonModalContext:AddContext(self)
        local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
        swf:Reset()
        self:Populate()
        self:UpdateSkillPoints()
        self:OnResize()
        Ui.TriggerFirstTimeEvent("JobsAbilities")
        local ds = DsTable.Find(DataSources[DS_ABILITY_LINES])
        if ds then
          ds:EnableScriptEvents()
        end
      end
    end,
    OnResize = function(self)
      local wnd = Window.Find(Ui.GetName(self.wndName))
      if wnd then
        local sw, sh = Window.GetCanvasSize()
        local wndX, wndY = wnd:GetPosition()
        local wndW, wndH = wnd:GetSize()
        local toX
        local yValue = sh / 2 - wndH / 2
        if self.align == 0 then
          toX = 30
          wnd:SetPosition(-350, yValue)
        else
          toX = sw - 30 - wndW
          wnd:SetPosition(sw + 350, yValue)
        end
        wnd:Show()
        self:CallDelegate("AbilitiesOnShowDescriptionPane")
        self:CallDelegate("AbilitiesHandlerOnShiftView", toX)
        WindowTweener:Create(self.wndName, "X", nil, toX, self.windowTweenSpeed)
      end
    end,
    Hide = function(self, noAbilities)
      self:CallDelegate("AbilitiesHandlerOnHide", noAbilities)
      local wnd = Window.Find(Ui.GetName(self.wndName))
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      swf:Invoke("sendPointChange", 1)
      self.visible = false
      if wnd then
        local sw, sh = Window.GetCanvasSize()
        local wndX, wndY = wnd:GetPosition()
        local wndW, wndH = wnd:GetSize()
        local toX
        if self.align == 0 then
          toX = -wndW
        else
          toX = sw + wndW
        end
        NonModalContext:RemoveContext(self)
        self:CallDelegate("AbilitiesHandlerOnShiftView", -1)
        WindowTweener:Create("Main.wndAbilityDesc", "X", nil, toX, 0.3, function()
          swf:Unload()
          wnd:Hide()
        end)
        local ds = DsTable.Find(DataSources[DS_ABILITY_LINES])
        if ds then
          ds:DisableScriptEvents()
        end
      end
    end,
    UpdateSkillPoints = function(self)
      if not self.visible then
        return
      end
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      if swf then
        local activeProfile = Ui.GetActiveProfileId()
        local availablePoints = self:GetProfileDSData(activeProfile, ProfileDsColumns.AvailablePoints)
        swf:Invoke("setSkillPoints", availablePoints)
      end
    end,
    GetProfileDSData = function(self, classID, column)
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      if ds then
        local rows = ds:GetRowCount()
        if rows > 0 then
          for index = 0, rows - 1 do
            local id = tonumber(ds:GetData(index, ProfileDsColumns.ID))
            if id == classID then
              return tonumber(ds:GetData(index, column))
            end
          end
        end
      end
    end,
    Populate = function(self)
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      local ds = DsTable.Find(DataSources[DS_ABILITY_LINES])
      local abilities = false
      if ds then
        local classID = Ui.GetActiveProfileId()
        local rowCount = ds:GetRowCount()
        if rowCount > 0 then
          local abilityIndex = 1
          local traitIndex = 5
          for i = 0, rowCount - 1 do
            if tonumber(ds:GetData(i, 5)) == classID then
              abilities = true
              local ID = ds:GetData(i, 0)
              local isActivateable = tonumber(ds:GetData(i, 1))
              local name = ds:GetData(i, 2)
              local desc = ds:GetData(i, 3)
              local icon = tonumber(ds:GetData(i, 4))
              local cID = ds:GetData(i, 5)
              local exp = tonumber(ds:GetData(i, 6))
              local rank = tonumber(ds:GetData(i, 7))
              local rExp = tonumber(ds:GetData(i, 8))
              local mExp = tonumber(ds:GetData(i, 9))
              local iconbg = self:GetProfileDSData(classID, ProfileDsColumns.AbilityBgImgSet)
              local requiredLevel = Ui.GetString("AbilityUnlockedAtLevel") .. tonumber(ds:GetData(i, 10))
              if isActivateable == 1 then
                swf:Invoke("setSkillData", abilityIndex, ID, name, rank, rExp, mExp, desc, icon, iconbg, requiredLevel)
                abilityIndex = abilityIndex + 1
              else
                swf:Invoke("setSkillData", traitIndex, ID, name, rank, rExp, mExp, desc, icon, iconbg, requiredLevel)
                traitIndex = traitIndex + 1
              end
            end
          end
          if abilities == true and JobHandler:CheckAbilitiesMode() then
            self.visible = true
            self:OnResize()
          else
            self:Hide(true)
          end
        end
      end
      self:CallDelegate("AbilitiesOnAbilitiesPopulate", abilities)
    end,
    GetHasAbilities = function(self)
      local ds = DsTable.Find(DataSources[DS_ABILITY_LINES])
      if ds then
        local classID = Ui.GetActiveProfileId()
        local rowCount = ds:GetRowCount()
        if rowCount > 0 then
          for i = 0, rowCount - 1 do
            if tonumber(ds:GetData(i, 5)) == classID then
              return true
            end
          end
        end
      end
      return false
    end,
    OnUserEvent = function(a, b, c, d)
      AbilitiesHandler:CallDelegate("AbilitiesOnUserEvent", a, b, c, d)
      if a == "addSkillPoint" and b ~= "undefined" then
        AbilitiesHandler:print("JobScreen.PurchaseAbility( " .. tostring(b) .. ", " .. tostring(c) .. " );")
        AbilitiesHandler:print("-- Total For Skill: " .. tostring(d))
        JobScreen.PurchaseAbility(b, c)
      elseif a == "PlaySound" then
        HUD:PlaySound(b)
      elseif a == "AS_Print" then
        AbilitiesHandler:print(tostring(a) .. ", " .. tostring(b) .. ", " .. tostring(c) .. ", " .. tostring(d))
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[AbilitiesHandler]\t" .. message)
      end
    end
  }
  Delegate:AddSupportToClassObject(AbilitiesHandler, "AbilitiesHandler")
  Main_wndAbilityDesc_swfAbilityDesc_OnUserEvent = AbilitiesHandler.OnUserEvent
  function Main_wndAbilityDesc_swfAbilityDesc_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
;(function()
  WebBrowserHandler = {
    wndBrowser = Ui.GetName("Main.wndOnlineHelp"),
    wndClickGobblerPetition = Ui.GetName("Main.wndClickGobblerPetition"),
    boolShowFlag = false,
    Show = function(self)
      if Context:IsCurrent("Options") then
      end
      Ui.OnObjectiveEvent("onAskForHelpOpen")
      if HUD.inMiniGame == true then
        HUD:hideMinigame()
      else
        HUD:hideMain()
      end
      GameDock:Hide()
      self.boolShowFlag = true
      OnlineHelpWindow.Load()
      self:BuildNavigation()
      Window.SetFocus()
      Context:Push("WebBrowser", function()
        WebBrowserHandler:Hide()
      end)
      print(Context.Push)
    end,
    ShowBrowserWindow = function(self)
      OnlineHelpWindow.Show()
      local w = Window.Find(self.wndBrowser)
      local sw, sh = Window.GetCanvasSize()
      local i_w, i_h = w:GetSize()
      local toWidth = math.min(1280, sw)
      local toHeight = math.min(720, sh)
      w:SetProperty("Width", toWidth)
      w:SetProperty("Height", toHeight)
      w:SetPosition(sw / 2 - toWidth / 2, sh / 2 - toHeight / 2)
      w:Show()
      local wg = Window.Find(self.wndClickGobblerPetition)
      if wg then
        wg:Show()
        wg:SetPosition(0, 0)
        wg:SetSize(sw, sh)
      end
    end,
    BuildNavigation = function(self)
      NavigationHandler:Connect(self)
      NavigationHandler:Show()
      NavigationHandler:AddButton(1142, Ui.GetString(5587), 1)
      NavigationHandler:AddButton(1143, Ui.GetString(715201), 2)
      NavigationHandler:AddButton(1144, Ui.GetString(3835), 3)
      NavigationHandler:AddButton(1145, Ui.GetString(706006), 4)
      NavigationHandler:AddBarButton(3, 3, nil, 1)
      NavigationHandler:SetBarButtonGraphics(1, "X", "BEIGE")
    end,
    OnStatus = function(self, Status)
      if Status == true or Status == 1 and self.boolShowFlag == true then
        OnlineHelpWindow.NavigatePetitionUri()
        WebBrowserHandler:ShowBrowserWindow()
        Logger:print("webbrowser.lua", "status is ready")
      else
        Logger:print("webbrowser.lua", "status is not ready: " .. tostring(Status))
      end
    end,
    OnLoadProgress = function(self, Progress, Uri)
    end,
    NavigationOnUserEvent = function(self, a, b)
      Logger:print("webbrowser.lua", a .. b)
      if a == "SwitchTo" then
        if b == "1" then
          OnlineHelpWindow.Back()
        elseif b == "2" then
          OnlineHelpWindow.Forward()
        elseif b == "3" then
          OnlineHelpWindow.Refresh()
        elseif b == "4" then
          OnlineHelpWindow.Stop()
        end
        NavigationHandler:SelectButton()
      elseif a == "exitScreen" then
        WebBrowserHandler:Hide()
      end
    end,
    Hide = function(self)
      local wg = Window.Find(self.wndClickGobblerPetition)
      if wg then
        wg:Hide()
      end
      Context:Pop()
      NavigationHandler:Hide(self)
      local w = Window.Find(self.wndBrowser)
      local sw, sh = Window.GetCanvasSize()
      local i_w, i_h = w:GetSize()
      WindowTweener:Create("Main.wndOnlineHelp", "Y", nil, -i_h, 0.4, function()
        self:onHideComplete()
      end)
      Window.SetFocus()
    end,
    onHideComplete = function(self)
      self.boolShowFlag = false
      if HUD.inMiniGame == true then
        HUD:showMinigame()
      else
        HUD:showMain()
      end
      OnlineHelpWindow.Hide()
    end
  }
  Client.HandlerOnlineHelpWindow = "WebBrowserHandler"
end)()
