    swfGroupPane = Ui.GetName("Main.wndMinigameStatusGroupPane.swfMinigameStatusGroupPane"),
    swfClickGobbler = Ui.GetName("Main.wndClickGobbler.swfClickGobbler"),
    NONE_TYPE = -1,
    SAMPLE_TYPE = 1,
    SCAVENGER_HUNT_TYPE = 2,
    FLASH_TYPE = 3,
    COMBAT_TYPE = 4,
    HIDDEN_OBJECT_TYPE = 5,
    CHESS_TYPE = 6,
    CHECKERS_TYPE = 7,
