    SOCCER_TYPE = 12,
    PIRATES_TYPE = 13,
    TOWER_DEFENSE_TYPE = 14,
    TILE_MATCHING_TYPE = 15,
    TRADING_CARD_GAME_TYPE = 16,
    FISHING_TYPE = 21,
    panesUp = false,
    currentMode = 0,
    isMoving = false,
    currentMiniGameID = -1,
    currentMiniGameType = -1,
    currentMiniGameMembersOnly = 0,
    numGroupMembers = 0,
