    clickedObjective = -1,
    dontShowAnything = false,
    highScoreType = -1,
    highScoreOffset = 1,
    highScoresCheck = false,
    getRankCheck = false,
    myRank = -1,
    gotHighScores = false,
    SetReady = function(self)
      Logger:print("minigamestatushandler.lua", "set ready")
      local swf = GfxCtrl.Find(self.swfObjPane)
      swf:Invoke("setReady")
