          WindowTweener:Create("Main.wndMinigameStatusGroupPane", "X", nil, sw / 2 - width2 / 2 + width1 / 2 - 60 - width1 / 2, 0.3)
        end
      end
    end,
    Show = function(self, mode)
      Logger:print("minigamestatushandler.lua", "-MGSH Show: mode(" .. tostring(mode) .. ")")
      if Tutorial.inTutorial or PetTutorial.enabled then
        Logger:print("minigamestatushandler.lua", " we're in the tutorial")
        Tutorial:ClearAllTutorialElements()
      end
      if self.panesUp == true then
        return
      end
      if self.isMoving then
        return
      end
      Lobby:Hide(true)
      if HUD.mainShown == true then
        HUD:hideMain()
      end
      self.dontShowMain = false
      self.isMoving = true
      self.panesUp = true
      self.currentMode = tonumber(mode)
      if self:Populate() == -1 then
        return
      end
      if Context:Includes("MiniGameStatusHandlerHide") == false then
        Context:Push("MiniGameStatusHandlerHide", function()
          MiniGameStatusHandler:Hide()
          MiniGameStatusHandler:CallDelegate("StatusOnPop")
        end)
      end
      local ObjPane = GfxCtrl.Find(self.swfObjPane)
      local DescPane = GfxCtrl.Find(self.swfDescPane)
      if mode ~= 1 then
        ObjPane:Invoke("setReady")
      end
      if self.currentMode == 1 and Ui.IsMember() == false and self.currentMiniGameMembersOnly == 1 then
        Logger:print("minigamestatushandler.lua", "MEMBERS ONLY!!! SETTING MODE 4")
        self.currentMode = 4
      end
      ObjPane:Invoke("displayMode", self.currentMode)
      DescPane:Invoke("displayMode", self.currentMode)
      self:ShowPanes()
      self.highScoresCheck = true
      self:GetHighScores()
      if DialogHandler.isDialogShown == false and HUD.inMiniGame == true and not Tutorial.inTutorial and not PetTutorial.enabled and self.currentMiniGameType == self.COMBAT_TYPE then
        Logger:print("minigamestatushandler.lua", " ********** SHOWING GAME DOCK SINCE WE'RE IN MINIGAME")
        GameDock:SlideOffScreen()
        GameDock:InitDockInMinigame()
        GameDock:SlideOnScreen()
      end
      self.isMoving = false
    end,
    Hide = function(self)
      Logger:print("minigamestatushandler.lua", "-MGSH Hide panesUp(" .. tostring(self.panesUp) .. ") isMoving(" .. tostring(self.isMoving) .. ")")
      if Context:IsCurrent("MiniGameStatusHandlerHide") then
        Context:Pop()
      end
      if self.isMoving then
        return
      end
      self.isMoving = true
      self.panesUp = false
      self:HidePanes()
      if HUD.inMiniGame == true and HUD.isDockShown == true then
        Logger:print("minigamestatushandler.lua", " ********** HIDING GAME DOCK SINCE WE'RE IN A MINIGAME")
      end
      self.isMoving = false
    end,
    SetJobLevel = function(self, jobLevel)
      if jobLevel then
        self.myJobLevel = jobLevel
      end
      if MiniGameStatusHandler.panesUp == true then
