        DescPane:Invoke("setJobLevel", tonumber(jobLevel))
      end
    end,
    CurrentMiniGameType = function(self)
      return tonumber(self.currentMiniGameType)
    end,
    CurrentMiniGameType2 = function(self)
      local ds = DsTable.Find(self.MiniGameDsName)
      if ds then
        local Type = ds:GetData(0, 4)
        return tonumber(Type)
      end
      return -1
    end,
    Populate = function(self, dontShowAnything)
      if Housing.isInInstance then
        return
      end
      Logger:print("minigamestatushandler.lua", "-MGSH Populate")
      local ds = DsTable.Find(self.MiniGameDsName)
      local ObjPane = GfxCtrl.Find(self.swfObjPane)
      local DescPane = GfxCtrl.Find(self.swfDescPane)
      local GrpPane = GfxCtrl.Find(self.swfGroupPane)
      if dontShowAnything == true then
        self.dontShowAnything = true
      else
        self.dontShowAnything = false
      end
      if ds then
        local Name = ds:GetData(0, 0)
        local IconID = ds:GetData(0, 1)
        local Description = ds:GetData(0, 2)
        local Difficulty = ds:GetData(0, 3)
        local Type = ds:GetData(0, 4)
        local ElapsedTime = ds:GetData(0, 5)
        local EarnedStars = ds:GetData(0, 6)
        local MembersOnly = ds:GetData(0, 7)
        local ProfileType = ds:GetData(0, 8)
        local HasActionBar = ds:GetData(0, 9)
        local minigameID = ds:GetData(0, 11)
        if tonumber(Name) == -1 then
          Logger:print("minigamestatushandler.lua", "!!!!! -1 data, waiting on BaseClient.Minigame to be populated")
          ds:EnableScriptEvents()
          self.currentMiniGameType = self.NONE_TYPE
          return -1
        end
        if self.currentMiniGameID ~= minigameID or self.currentMiniGameType ~= tonumber(Type) then
          self.highScoreOffset = 1
          self.gotHighScores = false
        end
        self.currentMiniGameID = minigameID
        self.currentMiniGameType = tonumber(Type)
        self.currentMiniGameMembersOnly = tonumber(MembersOnly)
        Logger:print("minigamestatushandler.lua", "CURRENT MINI GAME TYPE: " .. self.currentMiniGameType)
        if self.panesUp == true then
          ObjPane:Invoke("setMiniGameInfoData", 0, Name, Difficulty, Description, ElapsedTime, EarnedStars, IconID, MembersOnly, Type)
          DescPane:Invoke("setMiniGameInfoData", 0, Name, Difficulty, Description, ElapsedTime, EarnedStars, IconID, MembersOnly, Type)
        end
        GraphicActionBar.isUsingMinigameAbilities = false
        if MiniGameHandler.m_Mode == nil then
          MiniGameHandler.m_Mode = 2
        end
        if self.currentMiniGameType == self.FLASH_TYPE or self.currentMiniGameType == self.HIDDEN_OBJECT_TYPE or self.currentMiniGameType == self.CHESS_TYPE or self.currentMiniGameType == self.CHECKERS_TYPE or self.currentMiniGameType == self.MATCH_THREE_TYPE or self.currentMiniGameType == self.MIMIC_TYPE or self.currentMiniGameType == self.TOWER_DEFENSE_TYPE or self.currentMiniGameType == self.TILE_MATCHING_TYPE then
          self.numGroupMembers = 1
        end
        self:SetGroupMembers()
        if self.currentMiniGameType == self.COMBAT_TYPE and Ui.IsInHub() then
          MiniMap:EnableButtons(0)
          return
        else
        end
        GameDock:SetState(GameDock.MINIGAME_STATE)
        ObjectiveWindow.disabled = false
        if self.currentMiniGameType == self.FISHING_TYPE then
          self.currentMiniGameID = minigameID
          self.currentMiniGameType = tonumber(Type)
          self.currentMiniGameMembersOnly = tonumber(MembersOnly)
          return
        end
        if tonumber(HasActionBar) == 1 then
          GraphicActionBar:PopulateAltActionBar()
        end
        if self.currentMiniGameType == self.RACING_TYPE or self.currentMiniGameType == self.SAMPLE_TYPE or self.currentMiniGameType == self.TRADING_CARD_GAME_TYPE then
          self.highScoreType = 2
        else
          self.highScoreType = 1
        end
        if self.dontShowAnything == false then
          GroupHandler:EncounterButtonModeSwitch(1)
          if self.currentMiniGameType == self.MIMIC_TYPE or self.currentMiniGameType == self.PIRATES_TYPE or self.currentMiniGameType == self.TOWER_DEFENSE_TYPE then
            Logger:print("minigamestatushandler.lua", "MiniGameStatusHandler:Populate() BUTTON ONLY MODE")
            GroupHandler:ModeSwitch(3)
            GroupHandler.Mode = 3
          elseif self.currentMiniGameType == self.RACING_TYPE or self.currentMiniGameType == self.DEMO_DERBY_TYPE or self.currentMiniGameType == self.SOCCER_TYPE then
          elseif self.currentMiniGameType == self.COMBAT_TYPE then
            Logger:print("minigamestatushandler.lua", "MiniGameStatusHandler:Populate() ENABLING HEALTH BARS")
            GroupHandler:ModeSwitch(1)
            GroupHandler.Mode = 1
          elseif self.currentMiniGameType == self.FLASH_TYPE or self.currentMiniGameType == self.MATCH_THREE_TYPE then
            GroupHandler:ModeSwitch(0)
            GroupHandler.Mode = 0
          elseif self.currentMiniGameType ~= self.NONE_TYPE then
            Logger:print("minigamestatushandler.lua", "MiniGameStatusHandler:Populate() DISABLING HEALTH BARS")
            GroupHandler:ModeSwitch(0)
            GroupHandler.Mode = 1
          end
        end
        if self.currentMiniGameType == self.SAMPLE_TYPE or self.currentMiniGameType == self.SCAVENGER_HUNT_TYPE or self.currentMiniGameType == self.COMBAT_TYPE then
          Logger:print("minigamestatushandler.lua", "       ENABLING MINI MAP")
          MiniMap.enabled = true
        else
          Logger:print("minigamestatushandler.lua", "       DISABLING MINI MAP")
          MiniMap.enabled = false
        end
        if self.currentMiniGameType == self.COMBAT_TYPE then
          Logger:print("minigamestatushandler.lua", "       ENABLING TARGET WINDOW")
          Target.isEnabled = true
        else
          Logger:print("minigamestatushandler.lua", "       DISABLING TARGET WINDOW")
          Target.isEnabled = false
        end
        if self.currentMiniGameType == self.SAMPLE_TYPE or self.currentMiniGameType == self.SCAVENGER_HUNT_TYPE then
          local dsObj = DsTable.Find("BaseClient.MiniGame.Reward")
          if dsObj then
            local numRows = dsObj:GetRowCount()
            local numCols = dsObj:GetColumnCount()
            local gotStars = false
            for i = 0, numRows - 1 do
              local ID = i * 999 * -1
              local Name = "Complete the game"
              local Bonus = 0
              local Description = "Complete the game"
              local RewardStars = dsObj:GetData(i, 2)
            end
          end
        end
        self.myRewardStars = 0
        self.myRewardCoins = 0
        if self.currentMiniGameType == self.SAMPLE_TYPE or self.currentMiniGameType == self.SCAVENGER_HUNT_TYPE then
          local dsObj = DsTable.Find("BaseClient.MiniGame.Reward")
          if dsObj then
            local numRows = dsObj:GetRowCount()
            local numCols = dsObj:GetColumnCount()
            local gotStars = false
            for i = 0, numRows - 1 do
              self.myRewardStars = self.myRewardStars + tonumber(dsObj:GetData(i, 2))
              self.myRewardCoins = self.myRewardCoins + tonumber(dsObj:GetData(i, 3))
            end
          end
          local myStatus = 1
          if MiniGameHandler.minigameStatus == 1 then
            myStatus = 3
          elseif MiniGameHandler.minigameStatus == 0 then
            myStatus = 4
          end
          Logger:print("minigamestatushandler.lua", "setMiniGameObjectiveData: ID(" .. 0 .. ") name(" .. 0 .. ") status(" .. 0 .. ") state(" .. myStatus .. ")")
          if self.panesUp == true then
            ObjPane:Invoke("setMiniGameObjectiveData", 0, Ui.GetString("Win"), 0, Ui.GetString("WinTheGame"), self.myRewardStars, "", myStatus, 0)
            DescPane:Invoke("setMiniGameObjectiveData", 0, Ui.GetString("Win"), 0, Ui.GetString("WinTheGame"), self.myRewardStars, "", myStatus, 0)
          end
        end
        local dsObj = DsTable.Find(self.MiniGameGoalsDsName)
        if dsObj then
          local numRows = dsObj:GetRowCount()
          local numCols = dsObj:GetColumnCount()
          local gotStars = false
          for i = 0, numRows - 1 do
            local ID = dsObj:GetData(i, MiniGameGoalsDsColumn.ID)
            local Name = dsObj:GetData(i, MiniGameGoalsDsColumn.Name)
            local Bonus = dsObj:GetData(i, MiniGameGoalsDsColumn.Bonus)
            local Description = dsObj:GetData(i, MiniGameGoalsDsColumn.Description)
            local RewardStars = dsObj:GetData(i, MiniGameGoalsDsColumn.RewardStars)
            local StatusMessage = dsObj:GetData(i, MiniGameGoalsDsColumn.StatusText)
            local State = dsObj:GetData(i, MiniGameGoalsDsColumn.State)
            local MembersOnly = dsObj:GetData(i, MiniGameGoalsDsColumn.MembersOnly)
            Logger:print("minigamestatushandler.lua", "setMiniGameObjectiveData: ID(" .. ID .. ") name(" .. Name .. ") status(" .. StatusMessage .. ") state(" .. State .. ")")
            if self.panesUp == true then
              ObjPane:Invoke("setMiniGameObjectiveData", tonumber(ID), Name, Bonus, Description, RewardStars, StatusMessage, State, tonumber(MembersOnly))
              DescPane:Invoke("setMiniGameObjectiveData", tonumber(ID), Name, Bonus, Description, RewardStars, StatusMessage, State, tonumber(MembersOnly))
            end
            if tostring(RewardStars) ~= "0" then
              gotStars = true
            end
          end
          if self.currentMiniGameType == self.RACING_TYPE or self.currentMiniGameType == self.DEMO_DERBY_TYPE or self.currentMiniGameType == self.SOCCER_TYPE or self.currentMiniGameType == self.PIRATES_TYPE then
            Logger:print("minigamestatushandler.lua", "MiniGameStatusHandler:Populate() " .. self.currentMiniGameType .. "1 DISABLING STARCOUNTER AND LEVELPROGRESSBAR")
            StarCounter.isEnabled = false
            LevelProgressBar.isEnabled = false
            if chatHandler.cannedChatShown == 1 or chatHandler.emotesShown == 1 then
              chatHandler:HideCannedChat()
            end
            Ui.LuaDismissVirtualKeyboard()
            if BugHandler.isVisible == 1 then
              BugHandler:Hide()
            end
            if JobHandler.screenActive == true then
              JobHandler:ModeSwitch(0)
              JobHandler:Hide()
            end
            if JobBrowser.isShown == true then
              JobBrowser:Hide()
            end
            if Atlas.active == true then
              Atlas:Hide()
            end
            if GameDock_PS3.currentNavMode == 2 then
              if GameDock_PS3.currentNavSelection == 1 or GameDock_PS3.currentNavSelection == 2 then
                MarketplaceHandler:Hide()
              end
              if GameDock_PS3.currentNavSelection == 3 then
                MembershipHandler:Hide()
              end
              GameDock_PS3:NavigationExit()
              GameDock_PS3:SetVisibility(0)
            end
            if PetsHandler.visible == true then
              PetsHandler:ModeSwitch(0)
              PetsHandler:Hide()
            end
            if FriendsWidget.isShown == 1 then
              FriendsWidget:Hide()
            end
            if GameDock_PS3.currentNavMode == 3 then
              if GameDock_PS3.currentNavSelection == 1 then
                ActivityPortalPS3:Hide()
              end
              if GameDock_PS3.currentNavSelection == 2 then
                ActivityCalendar:Hide()
              end
              if GameDock_PS3.currentNavSelection == 3 then
                ActivityFinderHandler:Hide()
              end
              if GameDock_PS3.currentNavSelection == 4 then
                QuestHandler:HideQuestsMode()
              end
              if GameDock_PS3.currentNavSelection == 5 then
                Lobby:Hide()
              end
              if GameDock_PS3.currentNavSelection == 6 then
                ActivityPortal:Hide()
              end
              GameDock_PS3:NavigationExit()
              GameDock_PS3:SetVisibility(0)
            end
            if TradeHandler.visible == true then
              Trade.Cancel()
            end
            if PlayerInspect.visible == true then
              PlayerInspect:Hide()
            end
          elseif gotStars == false and self.currentMiniGameType ~= self.NONE_TYPE and self.currentMiniGameType ~= self.COMBAT_TYPE then
            Logger:print("minigamestatushandler.lua", "MiniGameStatusHandler:Populate() " .. self.currentMiniGameType .. "2 DISABLING STARCOUNTER AND LEVELPROGRESSBAR")
            StarCounter.isEnabled = false
            LevelProgressBar.isEnabled = false
          elseif self.currentMiniGameType == self.COMBAT_TYPE then
            StarCounter.isEnabled = false
          else
            Logger:print("minigamestatushandler.lua", "MiniGameStatusHandler:Populate() " .. self.currentMiniGameType .. " SHOWING STARCOUNTER AND LEVELPROGRESSBAR")
            StarCounter.isEnabled = true
            LevelProgressBar.isEnabled = true
          end
        end
      end
      if self.currentMiniGameType == self.COMBAT_TYPE or self.currentMiniGameType == self.DEMO_DERBY_TYPE or self.currentMiniGameType == self.RACING_TYPE then
        MinigameStartScreen:SetLegend(70)
      else
        MinigameStartScreen:SetLegend(69)
      end
    end,
    OnResize = function(self, mode)
      Logger:print("minigamestatushandler.lua", "minigamestatushandler ON RESIZE() mode(" .. tostring(mode) .. ")")
      if self.currentMiniGameType == self.NONE_TYPE then
        Logger:print("minigamestatushandler.lua", "!!!!! -1 data, waiting on BaseClient.Minigame to be populated")
        local ds = DsTable.Find(self.MiniGameDsName)
        ds:EnableScriptEvents()
        return
      end
      self.panesUp = true
      NonModalContext:AddContext(self)
      local ObjPane = GfxCtrl.Find(self.swfObjPane)
      local DescPane = GfxCtrl.Find(self.swfDescPane)
      ObjPane:Invoke("displayMode", self.currentMode)
      DescPane:Invoke("displayMode", self.currentMode)
      local w1 = Window.Find(self.wndGroupPane)
      local w2 = Window.Find(self.wndDescPane)
      local w3 = Window.Find(self.wndObjPane)
      local w4 = Window.Find(self.wndClickGobbler)
      local width1, height1 = w1:GetSize()
      local width2, height2 = w2:GetSize()
      local width3, height3 = w3:GetSize()
      local sw, sh = Window.GetCanvasSize()
      if self.IsUiShown then
        Logger:print("minigamestatushandler.lua", "OnResize: UI IS SHOWN ")
        w2:Show()
        w3:Show()
        if mode then
          Logger:print("minigamestatushandler.lua", "OnResize: MODE: " .. tostring(mode))
          w2:SetPosition(sw + 500, sh / 2 - height2)
          w3:SetPosition(sw + 500, sh / 2)
          if 2 > self.numGroupMembers then
            WindowTweener:Create("Main.wndMinigameStatusDescPane", "X", nil, sw / 2 - width2 / 2, 0.3, function()
              self:JustShowPanes()
            end)
            WindowTweener:Create("Main.wndMinigameStatusObjPane", "X", nil, sw / 2 - width3 / 2, 0.3)
          else
            WindowTweener:Create("Main.wndMinigameStatusDescPane", "X", nil, sw / 2 - width2 / 2 + 10 + width1 / 2 - 30, 0.3, function()
              self:JustShowPanes()
            end)
            WindowTweener:Create("Main.wndMinigameStatusObjPane", "X", nil, sw / 2 - width3 / 2 + width1 / 2 - 30, 0.3)
          end
        else
          Logger:print("minigamestatushandler.lua", "OnResize: MODE: NULL")
          if 2 > self.numGroupMembers then
            w2:SetPosition(sw / 2 - width2 / 2, 0 - height2)
            w3:SetPosition(sw / 2 - width3 / 2, sh)
          else
            w2:SetPosition(sw / 2 - width2 / 2 + 10 + width1 / 2 - 30, 0 - height2)
            w3:SetPosition(sw / 2 - width3 / 2 + width1 / 2 - 30, sh)
          end
          WindowTweener:Create("Main.wndMinigameStatusDescPane", "Y", nil, sh / 2 - height2, 0.3, function()
            self:JustShowPanes()
          end)
          WindowTweener:Create("Main.wndMinigameStatusObjPane", "Y", nil, sh / 2, 0.3)
        end
      else
      end
      w4:Show()
      w4:SetPosition(0, 0)
      w4:SetSize(sw, sh)
      self:ShowGroupPane()
      Logger:print("minigamestatushandler.lua", "minigamestatushandler ON RESIZE() DONE")
    end,
    GetMyRank = function(self)
      self.getRankCheck = true
      self.myRank = -1
      local url = "login=false&leaderboardType=" .. self.highScoreType .. "&leaderboardId=" .. self.currentMiniGameID .. "&guids=5427539015819833569"
      Logger:print("minigamestatushandler.lua", "high scores url: " .. url)
      Ui.RequestLeaderBoardData(url)
    end,
    GetMyRankDone = function(self)
      if self.getRankCheck == false then
        return
      end
      self.getRankCheck = false
      self:GetHighScores()
    end,
    GetHighScores = function(self)
      Logger:print("minigamestatushandler.lua", "GetHighScores")
      local DescPane = GfxCtrl.Find(self.swfDescPane)
      if self.highScoresCheck == true and self.gotHighScores == false then
        DescPane:Invoke("setHighScoreButtonShown", "false")
      end
      if self.highScoreType == 1 then
        DescPane:Invoke("clearScores", Ui.GetString("3484"))
      elseif self.highScoreType == 2 then
        DescPane:Invoke("clearScores", Ui.GetString("FastestTime"))
      end
      if self.highScoreOffset <= 10 then
        self.highScoreOffset = 10
      end
      if self.highScoreOffset >= 500 then
        self.highScoreOffset = 500
      end
      DescPane:Invoke("toggleButton", "navArrowLeft", 0)
      DescPane:Invoke("toggleButton", "navArrowRight", 0)
      local ds = DsTable.Find(self.LeaderboardsBaseDsName)
      ds:EnableScriptEvents()
      local url = "login=false&leaderboardType=" .. self.highScoreType .. "&leaderboardId=" .. self.currentMiniGameID .. "&pageSize=10&page=" .. math.floor(self.highScoreOffset / 10)
      if self.highScoresCheck == true then
        url = url .. "&topRank=true"
      end
      Logger:print("minigamestatushandler.lua", "high scores url: " .. url)
      Ui.RequestLeaderBoardData(url)
    end,
    LoadHighScores = function(self)
      Logger:print("minigamestatushandler.lua", "LoadHighScores highScoresCheck(" .. tostring(self.highScoresCheck) .. ") getRankCheck(" .. tostring(self.getRankCheck) .. ")")
      local DescPane = GfxCtrl.Find(self.swfDescPane)
      DescPane:Invoke("scoresLoaded", self.highScoreOffset - 9 .. "-" .. self.highScoreOffset)
      local dsObj = DsTable.Find(self.LeaderboardsDsName)
      if dsObj then
        local numRows = dsObj:GetRowCount()
        local highScoreCount = 0
        for i = 0, numRows - 1 do
          local rank = dsObj:GetData(i, 0)
          local name = dsObj:GetData(i, 1)
          local guid = dsObj:GetData(i, 2)
          local score = dsObj:GetData(i, 3)
          if self.highScoresCheck == true then
            if 0 < tonumber(rank) then
              DescPane:Invoke("setHighScoreButtonShown", "true")
              self.highScoresCheck = false
              self.gotHighScores = true
              return
            end
          elseif self.getRankCheck == true then
            self.myRank = tonumber(rank)
            self.highScoreOffset = tonumber(rank)
          else
            local me = 0
            if tostring(guid) == tostring(Ui.GetPlayerGuid()) then
              me = 1
            end
            DescPane:Invoke("addHighScore", rank, name, "g" .. tostring(guid), score, me, self.highScoreType)
            highScoreCount = highScoreCount + 1
          end
        end
        Logger:print("minigamestatushandler.lua", "LoadHighScores: loaded " .. highScoreCount .. " scores")
        if self.highScoreOffset > 10 then
          DescPane:Invoke("toggleButton", "navArrowLeft", 1)
        end
        if highScoreCount == 10 and self.highScoreOffset < 500 then
          DescPane:Invoke("toggleButton", "navArrowRight", 1)
        end
        if highScoreCount <= 0 and self.highScoreOffset > 10 then
          self:OnUserEvent("previousScores")
        end
        self.highScoresCheck = false
        self:GetMyRankDone()
      end
    end,
    JustShowPanes = function(self)
      self.IsUiShown = true
      if self.numGroupMembers >= 2 then
        Window.Find(self.wndGroupPane):Show()
      end
      Window.Find(self.wndDescPane):Show()
      Window.Find(self.wndObjPane):Show()
    end,
    ShowPanes = function(self)
      Logger:print("minigamestatushandler.lua", "MGSH - ShowPanes()")
      self.IsUiShown = true
      if MinigameStartScreen.m_Enabled then
        MinigameStartScreen:Show()
      else
        self:OnResize()
      end
      HUD:PlaySound("MenuUp")
    end,
    ShowPanes2 = function(self)
      Logger:print("minigamestatushandler.lua", "MGSH - ShowPanes2()")
      self.IsUiShown = true
      if MinigameStartScreen.m_Enabled then
        MinigameStartScreen:Show()
      else
        self:OnResize(true)
      end
    end,
    HidePanes = function(self, dontunload)
      Logger:print("minigamestatushandler.lua", "MGSH-HidePanes dontunload(" .. tostring(dontunload) .. ")")
      self.IsUiShown = false
      self.panesUp = false
      NonModalContext:RemoveContext(self)
      MiniGameHandler.m_visible = false
      local w1 = Window.Find(self.wndGroupPane)
      local w2 = Window.Find(self.wndDescPane)
      local w3 = Window.Find(self.wndObjPane)
      local width1, height1 = w1:GetSize()
      local width2, height2 = w2:GetSize()
      local width3, height3 = w3:GetSize()
      local sw, sh = Window.GetCanvasSize()
      HUD:PlaySound("MenuDown")
      if dontunload then
        WindowTweener:Create("Main.wndMinigameStatusDescPane", "Y", nil, 0 - height2, 0.3, function()
          self:HideOnly()
        end)
      else
        WindowTweener:Create("Main.wndMinigameStatusDescPane", "Y", nil, 0 - height2, 0.3, function()
          self:Hide2()
        end)
      end
      WindowTweener:Create("Main.wndMinigameStatusGroupPane", "X", nil, 0 - width1, 0.3)
      WindowTweener:Create("Main.wndMinigameStatusObjPane", "Y", nil, sh, 0.3)
      local w4 = Window.Find(self.wndClickGobbler)
      w4:Hide()
      local ClickGobblerPane = GfxCtrl.Find(self.swfClickGobbler)
      ClickGobblerPane:Unload()
    end,
    HidePanes2 = function(self)
      Logger:print("minigamestatushandler.lua", "MGSH-HidePanes2")
      self.IsUiShown = false
      NonModalContext:RemoveContext(self)
      local w1 = Window.Find(self.wndGroupPane)
      local w2 = Window.Find(self.wndDescPane)
      local w3 = Window.Find(self.wndObjPane)
      local width1, height1 = w1:GetSize()
      local width2, height2 = w2:GetSize()
      local width3, height3 = w3:GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create("Main.wndMinigameStatusDescPane", "X", nil, sw + 500, 0.1, function()
        self:HideOnly()
      end)
      WindowTweener:Create("Main.wndMinigameStatusGroupPane", "X", nil, 0 - width1, 0.1)
      WindowTweener:Create("Main.wndMinigameStatusObjPane", "X", nil, sw + 500, 0.1)
    end,
    UnloadAndCallDelegate = function(self)
      Logger:print("minigamestatushandler.lua", "MGSH-UnloadAndCallDelegate")
      local ObjPane = GfxCtrl.Find(self.swfObjPane)
      local DescPane = GfxCtrl.Find(self.swfDescPane)
      local GrpPane = GfxCtrl.Find(self.swfGroupPane)
      ObjPane:Unload()
      DescPane:Unload()
      GrpPane:Unload()
      self:CallDelegate("StatusOnHide")
    end,
    HideOnly = function(self)
      Logger:print("minigamestatushandler.lua", "MGSH-HideOnly")
      self.IsUiShown = false
      local w1 = Window.Find(self.wndGroupPane)
      local w2 = Window.Find(self.wndDescPane)
      local w3 = Window.Find(self.wndObjPane)
      w1:Hide()
      w2:Hide()
      w3:Hide()
    end,
    Hide2 = function(self)
      Logger:print("minigamestatushandler.lua", "MGSH-Hide2")
