      self:UnloadAndCallDelegate()
    end,
    SetPlayerInfo = function(self, name, job)
      local movie = GfxCtrl.Find(self.swfGroupPane)
      local movie2 = GfxCtrl.Find(self.swfObjPane)
      movie:Invoke("clearGroupMembers")
      movie2:Invoke("clearGoals")
    end,
    SetGroupMembers = function(self, id)
      local gDs = DsTable.Find("BaseClient.GroupMemberData")
      if id == nil then
        self.numGroupMembers = 0
      end
      if gDs then
        local numRows = gDs:GetRowCount()
        local solo = Ui.GetString("GroupStatusSolo")
        if id == nil and gDs:GetData(0, 7) ~= solo and gDs:GetData(0, 7) ~= "Solo" then
          self.numGroupMembers = 1
        end
        if numRows > 1 then
          if id == nil then
            self.numGroupMembers = 1
          end
          local GrpPane = GfxCtrl.Find(self.swfGroupPane)
          GrpPane:Invoke("setPlayerInfo", " ", gDs:GetData(0, 1))
          for i = 1, numRows - 1 do
            if id == nil then
              self.numGroupMembers = self.numGroupMembers + 1
            end
            if id ~= nil and id ~= i then
            else
              Logger:print("minigamestatushandler.lua", "SetGroupMembers id(" .. i .. ") guid(" .. gDs:GetData(i, 1) .. ") name(" .. gDs:GetData(i, 0) .. ") icon(" .. gDs:GetData(i, 4) .. ")")
              GrpPane:Invoke("setGroupMember", i, gDs:GetData(i, 1), gDs:GetData(i, 0), gDs:GetData(i, 4), gDs:GetData(i, 3), gDs:GetData(i, 5))
            end
          end
        end
      end
    end,
    SetGroupMember = function(self, index, name, jobIconId, jobBadgeBgImageSetId, jobRank)
      Logger:print("minigamestatushandler.lua", "SetGroupMember: name(" .. name .. ") rank(" .. jobRank .. ") iconID(" .. jobIconId .. ") imageSetID(" .. jobBadgeBgImageSetId .. ")")
      local movie = GfxCtrl.Find(self.swfGroupPane)
      movie:Invoke("setGroupMember", index, name, jobIconId, jobBadgeBgImageSetId, jobRank)
    end,
    SetGroupMemberSelectingJob = function(self, index, on)
      local movie = GfxCtrl.Find(self.swfGroupPane)
      Logger:print("minigamestatushandler.lua", "SetGroupMemberSelectingJob")
      if on then
        movie:Invoke("groupMemberJobSelectingIndicatorOn", index)
      else
        movie:Invoke("groupMemberJobSelectingIndicatorOff", index)
      end
    end,
    GetRewardsFromDS = function(self)
      Logger:print("minigamestatushandler.lua", "GetRewardsFromDS")
      local ds
      if self.clickedObjective == 0 then
        ds = DsTable.Find("BaseClient.MiniGame.Reward")
      else
        ds = DsTable.Find("BaseClient.MiniGameGoal.Reward")
      end
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        local Coins = 0
        for i = 0, numRows - 1 do
          Coins = Coins + tonumber(ds:GetData(i, 3))
        end
        Logger:print("minigamestatushandler.lua", "addObjective Coin Reward: " .. Coins)
        if Coins > 0 then
          local movie = GfxCtrl.Find(self.swfDescPane)
          movie:Invoke("addObjectiveReward", Ui.GetString("9086"), 952, -1, Coins, -1)
        end
      end
      if self.clickedObjective == 0 then
        ds = DsTable.Find("BaseClient.MiniGame.Reward.Entries")
      else
        ds = DsTable.Find("BaseClient.MiniGameGoal.Reward.Entries")
      end
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local type = tonumber(ds:GetData(i, 0))
          if type == 1 then
            local name = ds:GetData(i, 1)
            local iconId = ds:GetData(i, 3)
            local tintValue = ds:GetData(i, 5)
            local quantity = ds:GetData(i, 4)
            local itemID = ds:GetData(i, 6)
            Logger:print("minigamestatushandler.lua", "addObjectiveReward: " .. tostring(name) .. "," .. tostring(iconId) .. "," .. tostring(tintValue) .. "," .. tostring(quantity))
            local movie = GfxCtrl.Find(self.swfDescPane)
            movie:Invoke("addObjectiveReward", name, iconId, tintValue, quantity, itemID)
          end
        end
      end
    end,
