      movie2:Invoke("objectiveSelected", id)
    end,
    SetBetweenRounds = function(self)
      local movie1 = GfxCtrl.Find(self.swfObjPane)
      local movie2 = GfxCtrl.Find(self.swfDescPane)
      movie1:Invoke("setMiniGameRound")
      movie2:Invoke("setMiniGameRound")
    end,
    GetCurrentMiniGameType = function(self)
      return self.currentMiniGameType
    end,
    OnUserEvent = function(self, a, b, c)
      self:CallDelegate("StatusOnUserEvent", tostring(a), tostring(b))
      if a == "memberClicked" then
        self.dontShowMain = true
        self:Hide()
        MiniGameHandler:CancelPendingGame()
        MembershipHandler:Show()
        self.dontShowMain = false
      elseif a == "showGameOptions" then
        MiniGameStatusHandler:HidePanes(1)
        Options:ShowPanel(function()
          MiniGameStatusHandler:ShowPanes()
        end)
      elseif a == "displayObjective" then
        self:DisplayObjectiveInformation(b)
      elseif a == "requestObjectiveRewardData" then
        self:GetRewardsFromDS()
      elseif a == "onUpgrade" then
        self.dontShowMain = true
        self:Hide()
        MiniGameHandler:CancelPendingGame()
        MembershipHandler:Show()
        self.dontShowMain = false
      elseif a == "getHighScores" then
        MiniGameStatusHandler.highScoresCheck = false
        MiniGameStatusHandler:GetHighScores()
      elseif a == "nextScores" then
        MiniGameStatusHandler.highScoreOffset = MiniGameStatusHandler.highScoreOffset + 10
        MiniGameStatusHandler:GetHighScores()
      else
        if a == "previousScores" then
          MiniGameStatusHandler.highScoreOffset = MiniGameStatusHandler.highScoreOffset - 10
          MiniGameStatusHandler:GetHighScores()
        else
        end
      end
    end
  }
  Delegate:AddSupportToClassObject(MiniGameStatusHandler, "MiniGameStatusHandler")
  function Main_wndMinigameStatusObjPane_swfMinigameStatusObjPane_OnUserEvent(a, b)
    MiniGameStatusHandler:OnUserEvent(a, b)
  end
  function Main_wndMinigameStatusDescPane_swfMinigameStatusDescPane_OnUserEvent(a, b)
    MiniGameStatusHandler:OnUserEvent(a, b)
  end
  function Main_wndMinigameStatusObjPane_swfMinigameStatusObjPane_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndMinigameStatusDescPane_swfMinigameStatusDescPane_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndMinigameStatusGroupPane_swfMinigameStatusGroupPane_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function Main_wndClickGobbler_swfClickGobbler_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
