    end,
    SetNotReady = function(self)
      Logger:print("minigamehandler.lua", "SetNotReady")
      MiniGameStatusHandler:SetNotReady()
    end,
    InvitationIsRejected = function(self)
      Logger:print("minigamehandler.lua", " ### InvitationIsRejected: Encounter Invitation has been rejected.")
      GroupHandler:InvitationIsRejected()
    end,
    EncounterCancelled = function(self)
      Logger:print("minigamehandler.lua", "### EncounterCancelled " .. tostring(ScoreScreen.screenShown))
      MiniGameStatusHandler.currentMiniGameType = -1
      self.m_Mode = nil
      HUD.inMiniGame = false
      Fishing.underwater = false
      ObjectiveWindow:SetShowInHub(false)
      if self.ignoreEncounterCancelled then
        self.ignoreEncounterCancelled = false
        return
      end
      if ScoreScreen.screenShown == true then
        return
      end
      if Ui.IsInLobby() == false then
        MiniGameHandler:CloseStartScreen()
      end
      if MiniGameStatusHandler.dontShowMain == false and Ui.IsInLobby() == false then
        Logger:print("minigamehandler.lua", "   EncounterCancelled: closing start screen and showing main")
        MinigameStartScreen:Hide()
        Context:Clear()
        MiniGameStatusHandler:Hide()
        Context:Clear(true)
        HUD.inMiniGame = false
        HUD.mainShown = false
        HUD:showMain()
      end
    end,
    CancelPendingGame = function(self)
      Logger:print("minigamehandler.lua", "### CancelPendingGame " .. tostring(ScoreScreen.screenShown))
      if ScoreScreen.screenShown == true or self.m_Mode ~= 1 then
        return
      end
      Ui.CancelPendingEncounter()
      GroupHandler:DeactivateEncounterRequest()
      ObjectiveWindow:SetShowInHub(false)
      self.m_Mode = nil
      if MiniGameStatusHandler.currentMiniGameType == 10 or MiniGameStatusHandler.currentMiniGameType == 11 or MiniGameStatusHandler.currentMiniGameType == 12 or MiniGameStatusHandler.currentMiniGameType == 13 or MiniGameStatusHandler.currentMiniGameType == 4 then
      else
        MiniGameHandler:CloseStartScreen()
        if MiniGameStatusHandler.dontShowMain == false then
          MiniGameStatusHandler.currentMiniGameType = -1
          HUD:showMain()
        end
      end
      MiniGameStatusHandler.currentMiniGameType = -1
    end,
    StartPendingGame = function(self)
      Logger:print("minigamehandler.lua", "MiniGameHandler StartPendingGame SHOWMINIGAME")
      Options:Hide()
      MiniGameHandler:CloseStartScreen()
      Ui.StartPendingEncounter()
    end,
    OpenStartScreen = function(self)
      Logger:print("minigamehandler.lua", "### OpenStartScreen")
      QuestStartHandler.dontShowMain = true
