        local ds = DsTable.Find(MiniGameStatusHandler.MiniGameDsName)
        if ds then
          return tonumber(ds:GetData(0, 8))
        end
      end
    end,
    GetMinigameType = function(self)
      if Ui.IsInLobby() and Lobby.lobbyGameType > 0 then
        return Lobby.lobbyGameType
      else
        local ds = DsTable.Find(MiniGameStatusHandler.MiniGameDsName)
        if ds then
          return tonumber(ds:GetData(0, 4))
        end
      end
    end,
    CloseStartScreen = function(self)
      Logger:print("minigamehandler.lua", "### CloseStartScreen")
      MiniGameStatusHandler:Disconnect(self)
      MiniGameStatusHandler:Hide()
      NonModalContext:RemoveContext(BrowserHandler)
      self.m_visible = false
    end,
    ClearContext = function(self)
      if Client.ContextDepth > 0 then
        for i = 1, Client.ContextDepth do
          Context.mList[i].Function()
        end
      end
    end,
    OpenStatusScreen = function(self)
      Logger:print("minigamehandler.lua", "### OpenStatusScreen")
      if MiniGameStatusHandler.isMoving then
        return
      end
      if self.m_visible == true then
        return
      end
      if tostring(Ui.GetMovementEnabled()) == "0" then
        return
      end
      if DialogHandler.isDialogShown == true then
        return
      end
      Context:Pop()
      self.m_Mode = 2
      self.m_visible = true
      MiniGameStatusHandler:Connect(self)
      MiniGameStatusHandler:Show(self.m_Mode)
      local sObjP = GfxCtrl.Find(MiniGameStatusHandler.swfObjPane)
      sObjP:Invoke("resetObjectiveCount")
      MiniGameFlash:Pause()
      HUD:hideMinigame()
    end,
    CloseStatusScreen = function(self, noPush)
      Logger:print("minigamehandler.lua", "minigamehandler:CloseStatusScreen()")
      if ScoreScreen.screenShown then
        return
      end
      if MiniGameStatusHandler.isMoving then
        return
      end
      if self.m_visible == true then
        MiniGameStatusHandler:Hide()
        MiniGameStatusHandler:Disconnect(self)
        self.m_visible = false
      end
      if noPush == nil then
        local allowControls = 1
        if Context:Includes("MiniGameHandlerOpenStatusScreen") == false then
        end
        MiniGameFlash:Resume()
      end
    end,
    QuitGameWithNoEndGameScreen = function(self)
      Logger:print("minigamehandler.lua", " QUIT GAME WITH NO END SCREEN")
      self.m_Mode = 9001
      self:QuitGame()
      HUD.mainShown = false
      if not MarketplaceHandler.boolIsShown then
        HUD:showMain()
      end
    end,
    QuitGame = function(self)
      Logger:print("minigamehandler.lua", "# ## # #### QUIT GAME ############# # # # ####")
      Logger:print("minigamehandler.lua", "context NOW: ")
      if not self.m_Mode then
        return
      end
      Options:Hide()
      Context:Pop()
      Tutorial:ClearAllTutorialElements()
      if SoccerTutorial.SoccerIsActive == true then
        SoccerTutorial:EndSoccerTutorial()
      end
      Fishing.underwater = false
      GameTutorial:Hide(true)
      MiniGameStatusHandler:Hide()
      MiniGameStatusHandler:Disconnect(self)
      ObjectiveWindow:SetShowInHub(false)
      self.m_Mode = nil
      self.m_visible = false
