      HUD.inMiniGame = false
    end,
    OpenEndScreen = function(self)
      Logger:print("minigamehandler.lua", "### OpenEndScreen")
      self.m_Mode = 3
      FlashTimer:Hide()
      MiniGameStatusHandler:Show(self.m_Mode)
      MiniGameStatusHandler:Connect(self)
      GameDock:SlideOffScreen()
    end,
    CloseEndScreen = function(self)
      Logger:print("minigamehandler.lua", "### CloseEndScreen " .. tostring(ScoreScreen.screenShown))
      if ScoreScreen.screenShown == true then
        return
      end
      if MiniGameStatusHandler.panesUp then
        MiniGameStatusHandler:Hide()
        MiniGameStatusHandler:Disconnect(self)
      end
      self.m_Mode = nil
      self.m_visible = false
      HUD.inMiniGame = false
      MiniGameStatusHandler.currentMiniGameType = -1
      GroupHandler:DeactivateEncounterRequest()
      Ui.LeaveMiniGameOrEncounter()
      if Ui.IsInLobby() == false then
        GameDock:Init()
        GameDock:Show()
        GameDock:SlideOnScreen()
        HUD:showMain()
      elseif MiniGameStatusHandler.currentMiniGameType == 6 or MiniGameStatusHandler.currentMiniGameType == 7 then
        Lobby:Show()
      end
    end,
    SetMiniGameEndData = function(self, status, goalsComp, bonusComp, timeRemain, starsEarned, totalScore)
      Logger:print("minigamehandler.lua", "### SetMiniGameEndData status(" .. status .. ")")
      local ds = DsTable.Find("BaseClient.MiniGame")
      Context:Show()
      Context:Pop()
      self.m_visible = true
      FlashTimer:Hide()
      HUD:hideMinigame(true)
      if ds then
        local Name = ds:GetData(0, 0)
        local IconID = ds:GetData(0, 1)
        local Description = ds:GetData(0, 2)
        local Difficulty = ds:GetData(0, 3)
        local Type = ds:GetData(0, 4)
        local ElapsedTime = ds:GetData(0, 5)
        local EarnedStars = ds:GetData(0, 6)
        local MembersOnly = ds:GetData(0, 7)
        local ProfileType = ds:GetData(0, 8)
        local HasActionBar = ds:GetData(0, 9)
        Logger:print("minigamehandler.lua", "SetMiniGameEndData: Set minigame end data called Type(" .. Type .. ")")
        if tonumber(Type) == 4 or tonumber(Type) == 1 then
          ScoreScreen:Show(status, 4)
        elseif tonumber(Type) == 10 then
          ScoreScreen.screenShown = false
          ScoreScreen.AllowExit = true
        elseif tonumber(Type) == 11 then
          ScoreScreen.screenShown = false
          ScoreScreen.AllowExit = true
        elseif tonumber(Type) == 14 then
          ScoreScreen:Show(status, 14)
        elseif tonumber(Type) == 8 then
          ScoreScreen:Show(status, 8)
        elseif tonumber(Type) == 7 then
          ScoreScreen:Show(status, 7)
        elseif tonumber(Type) == 6 then
          ScoreScreen:Show(status, 6)
        elseif tonumber(Type) == 16 then
          ScoreScreen:Show(status, 16)
        elseif tonumber(Type) == 9 then
          ScoreScreen:Show(status, 9)
        elseif tonumber(Type) == 12 then
        elseif tonumber(Type) == 13 then
          ScoreScreen:Show(status, 13)
        elseif tonumber(Type) == 21 then
          self:QuitGame()
          HUD:showMain()
        elseif tonumber(Type) == 2 then
          self:QuitGame()
          HUD:showMain()
        else
          self:QuitGame()
          HUD:showMain()
        end
      end
    end,
    OpenRoundEndScreen = function(self)
      if self.m_visible == true then
        return
      end
      Context:Pop()
      self.m_Mode = 2
      self.m_visible = true
      MiniGameStatusHandler:Connect(self)
      MiniGameStatusHandler:Show(self.m_Mode)
      MiniGameStatusHandler:SetBetweenRounds()
      local sObjP = GfxCtrl.Find(MiniGameStatusHandler.swfObjPane)
      sObjP:Invoke("resetObjectiveCount")
      self.m_Mode = 4
      HUD:hideMinigame()
      GameDock:SlideOffScreen()
    end,
    CloseRoundEndScreen = function(self, noPush)
      Logger:print("minigamehandler.lua", "MiniGameHandler CloseRoundEndScreen SHOWMINIGAME")
      MiniGameStatusHandler:Hide()
      MiniGameStatusHandler:Disconnect(self)
      MiniGameFlash:EndBetweenRounds()
      HUD:showMinigame()
      if noPush == nil then
      end
    end,
    SetMiniGameRoundData = function(self, status, goalsComp, bonusComp, timeRemain, starsEarned, totalScore)
      Logger:print("minigamehandler.lua", "### SetMiniGameRoundData status(" .. status .. ")")
      self.minigameStatus = tonumber(status)
      local movie = GfxCtrl.Find(MiniGameStatusHandler.swfDescPane)
      movie:Invoke("setMiniGameEndData", status, goalsComp, bonusComp, timeRemain, starsEarned, totalScore)
    end,
    StatusOnUserEvent = function(self, a, b)
      if a == "cancelPendingGame" then
        Context:CallQuit()
      elseif a == "startPendingGame" then
        MiniGameHandler:StartPendingGame()
      elseif a == "quitCurrentGame" then
        MiniGameHandler:QuitGame()
      elseif a == "returnToCurrentGame" then
        if self.m_Mode == 4 or self.m_Mode == 2 then
          Context:CallQuit()
        else
          Logger:print("minigamehandler.lua", "MiniGameHandler StatusOnUserEvent SHOWMINIGAME")
          HUD:showMinigame()
        end
      elseif a == "endCurrentGame" then
        MiniGameHandler:CloseEndScreen()
      elseif a == "memberClicked" then
        if self.m_Mode == 1 then
          MiniGameHandler:CancelPendingGame()
        end
      elseif a == "playSound" then
        if b == "ButtonPress" then
          HUD:PlaySound("ButtonPress")
        elseif b == "ButtonOver" then
          HUD:PlaySound("ButtonOver")
        elseif b == "DockSelect" then
          HUD:PlaySound("ButtonPress")
        elseif b == "DockOver" then
          HUD:PlaySound("ButtonOver")
        end
      end
    end,
    StatusOnPop = function(self)
      Logger:print("minigamehandler.lua", "************************************************* StatusOnPop Mode: " .. tostring(self.m_Mode))
      if self.m_Mode == 1 then
        MiniGameHandler:CancelPendingGame()
      elseif self.m_Mode == 2 then
        Logger:print("minigamehandler.lua", "MiniGameHandler StatusOnPop SHOWMINIGAME")
        HUD:showMinigame()
      elseif self.m_Mode == 3 then
        MiniGameHandler:CloseEndScreen()
      elseif self.m_Mode == 4 then
        MiniGameHandler:CloseRoundEndScreen()
      end
    end,
    BrowserOnUserEvent = function(self, a, b)
      Logger:print("minigamehandler.lua", "MINIGAMEHANDLER: BrowserOnUserEvent: " .. tostring(a))
      if a == "SelectJob" then
        JobScreen.SelectJob(b)
      elseif a == "ExpandedBrowser" then
        GroupScreen.SetChangingJob(true)
        MiniGameStatusHandler:HidePanes2()
      elseif a == "CompressBrowser" then
        GroupScreen.SetChangingJob(false)
        if MiniGameHandler.m_Mode ~= nil then
          MiniGameStatusHandler:ShowPanes2()
        end
      elseif a == "CloseBrowser" then
        if self:GetMinigameType() == 10 or self:GetMinigameType() == 11 then
          VehicleHandler:Hide()
          VehicleBrowser:Hide()
        else
          JobHandler:Hide()
          JobBrowser:Hide()
        end
      elseif a == "SelectVehicle" then
        VehicleBrowser:CloseBrowser()
      end
    end
  }
end)()
