        ScoreScreen:SetPlayerRaceResults(place, guid, sname, sbest, stotal, finished)
      end
    end,
    Populate = function(self)
      if ScoreScreen.screenShown == true then
        local ds = DsTable.Find("BaseClient.VehicleRaceProcessor.RaceResults")
        if ds then
          local rows = ds:GetRowCount()
          for i = 0, rows - 1 do
            local dsPlace = ds:GetData(i, 0)
            local dsGuid = ds:GetData(i, 1)
            local dsName = ds:GetData(i, 2)
            local dsBest = ds:GetData(i, 3)
            local dsTotal = ds:GetData(i, 4)
            local dsFinished = ds:GetData(i, 5)
            self:SetPlayerResults(dsPlace, dsGuid, dsName, dsBest, dsTotal, dsFinished)
          end
        end
      end
    end
  }
