      end
      local theMovie = GfxCtrl.Find(self.movieName)
      if theMovie ~= nil then
        theMovie:Unload()
      end
    end,
    OnResize = function(self)
      local theWindow = Window.Find(self.windowName)
      local x, y = theWindow:GetPosition()
      local w, h = theWindow:GetSize()
      if self.originalW == 0 then
        self.originalW = w
      end
      if self.originalH == 0 then
        self.originalH = h
      end
      local sw, sh = Window.GetCanvasSize()
      local widthRatio = sw / 1280
      local heightRatio = sh / 720
      theWindow:SetSizeScaled(widthRatio * tonumber(self.originalW), heightRatio * tonumber(self.originalH))
      local w, h = theWindow:GetSize()
      local xLoc = sw - 160
      Logger:print("soccergame.lua", "SoccerChargeMeter w(" .. tostring(w) .. ") h(" .. tostring(h) .. ") x(" .. tostring(xLoc) .. ") sw(" .. tostring(sw) .. ")")
      theWindow:SetPosition(xLoc, 75)
    end,
    SetMeter = function(self, percent)
      if self.lastCharge == percent then
        return
      end
      self.lastCharge = percent
      local theMovie = GfxCtrl.Find(self.movieName)
      theMovie:Invoke("setMeter", percent)
    end
  }
