  ToolTipHandler = {
    timerCounter = 0,
    boolShow = false,
    windowName = Ui.GetName("Main.wndToolTip"),
    swfName = Ui.GetName("Main.wndToolTip.swfToolTip"),
    InvokeShowToolTip = function(self, tooltipData)
      if self.boolShow == false then
        return
      end
      local wnd = Window.Find(self.windowName)
      local swf = GfxCtrl.Find(self.swfName)
      if not wnd then
        return
      end
      wnd:Show()
      UpdateList.ToolTipTimer = ToolTipHandler
      swf:Invoke("showToolTip", tooltipData.key, tooltipData.data, tooltipData.effectDuration)
    end,
    InvokeHideToolTip = function(self, identifier)
      if ToolTipInvoker.tooltipData.hashKey ~= identifier then
        return
      end
      local wnd = Window.Find(self.windowName)
      local swf = GfxCtrl.Find(self.swfName)
      swf:Invoke("hideToolTip")
      UpdateList.ToolTipTimer = nil
      wnd:Hide()
    end,
    HideToolTip = function(self)
      local wnd = Window.Find(self.windowName)
      local swf = GfxCtrl.Find(self.swfName)
      swf:Invoke("hideToolTip")
      UpdateList.ToolTipTimer = nil
      wnd:Hide()
    end,
    getDataArray = function(self, dsName)
      local ds = DsTable.Find(dsName)
      local str_array = {}
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          str_array[i] = ds:GetData(i, 0)
        end
      end
      return str_array
    end,
    IsNearCursor = function(self, tooltipData)
      local threshold = 60
      local x, y = Ui.GetMousePos()
      if threshold < math.abs(x - tooltipData.mouseX) or threshold < math.abs(y - tooltipData.mouseY) then
        return false
      end
      return true
    end,
    GetTooltipPos = function(self, obj)
      local HEADER_OFFSET = 16
      local SIDE_OFFSET = 5
      local centerX = obj.xt + obj.wt / 2
      local centerY = obj.yt + obj.ht / 2
      local alignOffsetX, alignOffsetY
      if obj.horizAlign == "left" then
        alignOffsetX = obj.offsetX
      elseif obj.horizAlign == "right" then
        alignOffsetX = obj.offsetX - obj.wtt
      else
        alignOffsetX = obj.offsetX - obj.wtt / 2
      end
      if obj.vertAlign == "top" then
        alignOffsetY = obj.offsetY
      elseif obj.vertAlign == "bottom" then
        alignOffsetY = obj.offsetY - obj.htt
      else
        alignOffsetY = obj.offsetY - obj.htt / 2
      end
      local toX, toY
      toX, toY = ToolTipHandler:AdjustBounds(centerX + alignOffsetX, centerY + alignOffsetY, obj.wtt, obj.htt)
      toX, toY = ToolTipHandler:DodgeMouse(toX, toY, obj.wtt, obj.htt)
      return toX, toY
    end,
    AdjustBounds = function(self, spawnX, spawnY, wtt, htt)
      local ws, hs = Window.GetCanvasSize()
      local xFinal = spawnX
      local yFinal = spawnY
      if ws <= spawnX + wtt then
        xFinal = ws - wtt
      elseif spawnX <= 0 then
        xFinal = 0
      end
      if hs <= spawnY + htt then
        yFinal = hs - htt
      elseif spawnY <= 0 then
        yFinal = 0
      end
      if xFinal ~= spawnX or yFinal ~= spawnY then
      end
      return xFinal, yFinal
    end,
    DodgeMouse = function(self, xtt, ytt, wtt, htt)
      local xm, ym = Ui.GetMousePos()
      local quad = self:GetQuadrant(xm, ym)
      if xtt <= xm and xm <= xtt + wtt and ytt <= ym and ym <= ytt + htt then
        if quad == 1 or quad == 2 then
          return xtt, ym + 5
        else
          return xtt, ym - htt - 5
        end
      end
      return xtt, ytt
    end,
    GetQuadrant = function(self, x, y)
      local sw, sh = Window.GetCanvasSize()
      if x >= sw / 2 and y <= sh / 2 then
        return 1
      elseif x <= sw / 2 and y <= sh / 2 then
        return 2
      elseif x <= sw / 2 and y >= sh / 2 then
        return 3
      else
        return 4
      end
    end,
    GetAutoTooltipPos = function(self, tooltipData)
      local xm, ym = Ui.GetMousePos()
      local quad = self:GetQuadrant(xm, ym)
      local x, y
      local PADDING_Y = 14
      x = xm - tooltipData.wtt / 2
      if quad == 1 then
        y = ym + PADDING_Y + 20
      elseif quad == 2 then
        y = ym + PADDING_Y + 20
      elseif quad == 3 then
        y = ym - PADDING_Y - tooltipData.htt
      else
        y = ym - PADDING_Y - tooltipData.htt
      end
      x, y = ToolTipHandler:DodgeMouse(x, y, tooltipData.wtt, tooltipData.htt)
      x, y = ToolTipHandler:AdjustBounds(x, y, tooltipData.wtt, tooltipData.htt)
      if self:IsInRect(xm, ym, x, y, tooltipData.wtt, tooltipData.htt) then
        x = xm - tooltipData.wtt - 6
      end
      if self:IsInRect(xm, ym, x, y, tooltipData.wtt, tooltipData.htt) then
        x = xm + 6
      end
      return x, y
    end,
    IsInRect = function(self, xtarget, ytarget, xbox, ybox, wbox, hbox)
      if xbox <= xtarget and xtarget <= xbox + wbox and ybox <= ytarget and ytarget <= ybox + hbox then
        return true
      end
      return false
    end,
    Update = function(self)
      local REFRESH_BUFFER = 0
      local x, y = Ui.GetMousePos()
      local v = ToolTipInvoker.tooltipData
      if v.isAutoMode ~= 1 and v.ignoreGarbageCollect == 0 and (x < v.xt - REFRESH_BUFFER or x > v.xt + v.wt + REFRESH_BUFFER or y < v.yt - REFRESH_BUFFER or y > v.yt + v.ht + REFRESH_BUFFER) then
        return
      end
    end,
    ParseDs = function(self, ds, delimRow, delimCol, delimKeyValue, targetrow, targetcolname, targetval)
      if delimCol == nil then
        delimCol = "|"
      end
      if delimRow == nil then
        delimRow = "~~"
      end
      if delimKeyValue == nil then
        delimKeyValue = "~"
      end
      local ds = DsTable.Find(ds)
      local res_final = {}
      local res = {}
      if ds then
        local rows = ds:GetRowCount()
        local columns = ds:GetColumnCount()
        local column = 0
        local row = 0
        if rows == 0 then
          return false
        end
        if targetrow ~= nil then
          if targetrow >= 0 then
            rows = targetrow + 1
            row = targetrow
          else
            return false
          end
        end
        while rows > row do
          column = 0
          res = {}
          local flag = 0
          while columns > column do
            res[column] = ds:GetColumnName(column) .. delimKeyValue .. ds:GetData(row, column)
            if targetcolname ~= nil and targetval ~= nil and ds:GetColumnName(column) == targetcolname and tostring(ds:GetData(row, column)) == tostring(targetval) then
              flag = 1
            end
            column = column + 1
          end
          res_final[row] = strjoin(delimCol, res)
          if targetcolname ~= nil and targetval ~= nil and row == rows - 1 and flag ~= 1 then
            res_final = {}
          elseif flag == 1 then
            do
              local t = {}
              t[0] = res_final[row]
              res_final = t
            end
          else
            row = row + 1
            end
          end
        end
      local count = 0
      for k, v in pairs(res_final) do
        count = count + 1
      end
      if count == 1 then
        if targetrow == nil then
          return res_final[0]
        else
          return res_final[targetrow]
        end
      end
      return strjoin(delimRow, res_final)
    end,
    GetDsVal = function(self, ds, row, colName)
      ds = DsTable.Find(ds)
      if ds then
        local numCols = ds:GetColumnCount()
        local numRows = ds:GetRowCount()
        local col = 0
        while numCols > col do
          if ds:GetColumnName(col) == colName then
            return ds:GetData(row, col)
          end
          col = col + 1
        end
      end
      return nil
    end,
    DebugPrint = function(self, tooltipData)
      for k, v in pairs(tooltipData) do
        Logger:print("tooltip.lua", k .. ": " .. v)
      end
    end
  }
  ToolTipInvoker = {
    tooltipData = {},
    executeInvoke = function(self)
      ToolTipHandler:InvokeShowToolTip(self.tooltipData)
    end
  }
  InventoryItemTooltip = {
    OnUpdateAbilities = function(self)
      Logger:print("tooltip.lua", "InventoryItemTooltip OnUpdateAbilities")
      InventoryItemTooltip:OnUpdate()
    end,
    OnUpdate = function(self)
      if ToolTipInvoker.tooltipData.key == 0 then
        return
      end
      local mainData = ToolTipHandler:ParseDs("TooltipData")
      local activeEffectsData = ToolTipHandler:ParseDs("Tooltips.ActiveAbilityEffects", "*rowsep*", "*colsep*", "*keyvalue*")
      local passiveEffectsData = ToolTipHandler:ParseDs("Tooltips.PassiveAbilityEffects", "*rowsep*", "*colsep*", "*keyvalue*")
      local row
      if ToolTipInvoker.tooltipData.key == TOOLTIP_ITEM_GUID then
        row = Ui.GetItemStatRow(ToolTipInvoker.tooltipData.itemidentifier)
      elseif Ui.GetItemDefinitionStatRow then
        row = Ui.GetItemDefinitionStatRow(ToolTipInvoker.tooltipData.itemidentifier)
      end
      local statsData, statsDefData, abilityData
      if row ~= nil then
        statsData = ToolTipHandler:ParseDs("BaseClient.ItemStats", "*rowsep*", "*colsep*", "*keyvalue*", tonumber(row))
        statsDefData = ToolTipHandler:ParseDs("BaseClient.StatDefinitions", "*rowsep*", "*colsep*", "*keyvalue*")
        abilityData = ToolTipHandler:ParseDs("BaseClient.ItemAbilities", "&&", "++", "<>")
      end
      if activeEffectsData then
        activeEffectsData = "ActiveEffects~" .. activeEffectsData
        mainData = mainData .. "|" .. activeEffectsData
      end
      if passiveEffectsData then
        passiveEffectsData = "PassiveEffects~" .. passiveEffectsData
        mainData = mainData .. "|" .. passiveEffectsData
      end
      if statsData then
        statsData = "StatsData~" .. statsData
        mainData = mainData .. "|" .. statsData
      end
      if statsDefData then
        statsDefData = "StatsDefData~" .. statsDefData
        mainData = mainData .. "|" .. statsDefData
      end
      if abilityData then
        abilityData = "Abilities~" .. abilityData
        local ds = DsTable.Find("BaseClient.ItemAbilities")
        if ds and 0 < ds:GetRowCount() and tonumber(ds:GetData(0, 1)) ~= -1 then
          mainData = mainData .. "|" .. abilityData
        end
      end
      ToolTipInvoker.tooltipData.data = mainData
      ToolTipInvoker:executeInvoke()
    end
  }
