  TooltipMethods = {
    Show = function(self, key, data, identifier, hitareaX, hitareaY, hitareaWidth, hitareaHeight, xOffset, yOffset, horizAlign, vertAlign, effectDuration, isAutoMode, ignoreGarbageCollect, mouseX, mouseY)
      if GameDock.tutorialMode then
        return
      end
      if identifier == nil or data == nil or data == "undefined" or data == "" then
        return
      end
      local CurToolTipData = {}
      ToolTipHandler.boolShow = true
      CurToolTipData.key = key
      CurToolTipData.itemidentifier = data
      CurToolTipData.xt = hitareaX
      CurToolTipData.yt = hitareaY
      CurToolTipData.wt = hitareaWidth
      CurToolTipData.ht = hitareaHeight
      CurToolTipData.offsetX = xOffset
      CurToolTipData.offsetY = yOffset
      CurToolTipData.hashKey = identifier
      CurToolTipData.effectDuration = effectDuration
      CurToolTipData.horizAlign = horizAlign
      CurToolTipData.vertAlign = vertAlign
      CurToolTipData.isAutoMode = isAutoMode
      CurToolTipData.ignoreGarbageCollect = ignoreGarbageCollect
      CurToolTipData.mouseX = mouseX
      CurToolTipData.mouseY = mouseY
      ToolTipInvoker.tooltipData = CurToolTipData
      local status = false
      if key == TOOLTIP_ITEM_GUID then
        local ds1 = DsTable.Find("Tooltips.ActiveAbilityEffects")
        local ds2 = DsTable.Find("Tooltips.PassiveAbilityEffects")
        ds1:EnableScriptEvents()
        ds2:EnableScriptEvents()
        _G.Tooltips_ActiveAbilityEffects_OnDataUpdate = InventoryItemTooltip.OnUpdate
        _G.Tooltips_PassiveAbilityEffects_OnDataUpdate = InventoryItemTooltip.OnUpdate
        DataSourceConnection:Connect("BaseClient.ItemAbilities", InventoryItemTooltip, "OnUpdateAbilities")
        TooltipConnect:Connect("TooltipData", InventoryItemTooltip)
        status = Ui.SetTooltipInventoryItem(data)
        if data == "0" then
          status = false
        end
      elseif key == TOOLTIP_ITEM_ID or key == TOOLTIP_MARKETPLACE_ITEM or key == TOOLTIP_ITEM_PLAYER_INSPECT then
        local ds1 = DsTable.Find("Tooltips.ActiveAbilityEffects")
        local ds2 = DsTable.Find("Tooltips.PassiveAbilityEffects")
        ds1:EnableScriptEvents()
        ds2:EnableScriptEvents()
        _G.Tooltips_ActiveAbilityEffects_OnDataUpdate = InventoryItemTooltip.OnUpdate
        _G.Tooltips_PassiveAbilityEffects_OnDataUpdate = InventoryItemTooltip.OnUpdate
        DataSourceConnection:Connect("BaseClient.ItemAbilities", InventoryItemTooltip, "OnUpdateAbilities")
        local tintId = 0
        TooltipConnect:Connect("TooltipData", InventoryItemTooltip)
        status = Ui.SetTooltipItemDefinition(data, tintId)
      elseif key == TOOLTIP_ABILITY then
        TooltipConnect:Connect("TooltipData", AbilityTooltipHandler)
        status = Ui.SetTooltipAbilityItem(data)
      elseif key == TOOLTIP_PETS then
        TooltipConnect:Connect("TooltipData", PetsTooltipHandler)
        status = Ui.SetTooltipPet(data)
      elseif key == TOOLTIP_JOB then
        TooltipConnect:Connect("TooltipData", JobsTooltipHandler)
        status = Ui.SetTooltipJob(data)
      elseif key == TOOLTIP_RECIPE then
        TooltipConnect:Connect("TooltipData", RecipeTooltipHandler)
        status = Ui.SetTooltipRecipe(data)
      elseif key == TOOLTIP_PETTRICKS then
        TooltipConnect:Connect("TooltipData", PettrickTooltipHandler)
        status = Ui.SetTooltipPetTrick(data)
      elseif key == TOOLTIP_COLLECTION then
        TooltipConnect:Connect("TooltipData", CollectionTooltipHandler)
        status = Ui.SetTooltipCollection(data)
      elseif key == TOOLTIP_MARKETPLACE_BUNDLE then
        TooltipConnect:Connect("TooltipData", MarketplaceTooltipHandler)
        status = Ui.SetTooltipStoreItem(1, tonumber(data))
      elseif key == TOOLTIP_CLAIM_BUNDLE then
        TooltipConnect:Connect("TooltipData", MarketplaceTooltipHandler)
        status = Ui.SetTooltipClaimItem(tonumber(data))
      elseif key == TOOLTIP_BUFF then
        BuffTooltipHandler:OnUpdate()
        status = true
      else
        CurToolTipData.data = data
        ToolTipInvoker:executeInvoke()
        status = true
      end
      if key ~= TOOLTIP_CLAIM_BUNDLE and tonumber(data) == 0 then
        status = false
      end
      if status ~= true then
        ToolTipHandler.boolShow = false
      end
    end,
    Hide = function(self, identifier)
      ToolTipHandler.boolShow = false
      ToolTipHandler:InvokeHideToolTip(identifier)
      TooltipConnect:Disconnect()
    end,
    split = function(self, str, pat)
      local t = {}
      local fpat = "(.-)" .. pat
      local last_end = 1
      local s, e, cap = str:find(fpat, 1)
      while s do
        if s ~= 1 or cap ~= "" then
          table.insert(t, cap)
        end
        last_end = e + 1
        s, e, cap = str:find(fpat, last_end)
      end
      if last_end <= #str then
        cap = str:sub(last_end)
        table.insert(t, cap)
      end
      return t
    end,
    checknan = function(self, val)
      if val == "undefined" or val == nil or val == -9999 or val == "null" or type(tonumber(val)) ~= "number" then
        return 0
      end
      return tonumber(val)
    end
  }
  function GlobalEvent_OnTooltip(mouseX, mouseY, rectL, rectT, rectR, rectB, xscale, yscale, command, a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q, r, s, t, u, v)
    if command == "showToolTip" then
      xscale = tonumber(xscale)
      yscale = tonumber(yscale)
      c = TooltipMethods:checknan(c)
      d = TooltipMethods:checknan(d)
      e = TooltipMethods:checknan(e)
      f = TooltipMethods:checknan(f)
      g = TooltipMethods:checknan(g)
      h = TooltipMethods:checknan(h)
      j = TooltipMethods:checknan(j)
      m = TooltipMethods:checknan(m)
      n = TooltipMethods:checknan(n)
      local tooltipstring = string.gsub(b, "&#44;", ",")
      local mouseX, mouseY = Ui.GetMousePos()
      mouseX = c
      mouseY = d
      TooltipMethods:Show(tonumber(a), tooltipstring, i, tonumber(c) * xscale + tonumber(rectL), tonumber(d) * yscale + tonumber(rectT), tonumber(e) * xscale, tonumber(f) * yscale, tonumber(g) * xscale, tonumber(h) * yscale, k, l, tonumber(j), tonumber(m), tonumber(n), tonumber(mouseX), tonumber(mouseY))
    elseif command == "hideToolTip" then
      TooltipMethods:Hide(a)
    elseif command == "setToolTipPos" then
      local swfName = a
      local CurToolTipData = ToolTipInvoker.tooltipData
      if CurToolTipData == nil then
        return
      end
      CurToolTipData.wtt = tonumber(b)
      CurToolTipData.htt = tonumber(c)
      local swf = GfxCtrl.Find(ToolTipHandler.swfName)
      if CurToolTipData.isAutoMode ~= 1 then
        toX, toY = ToolTipHandler:GetTooltipPos(CurToolTipData)
      else
        toX, toY = ToolTipHandler:GetAutoTooltipPos(CurToolTipData)
      end
      local w = Window.Find(ToolTipHandler.windowName)
      CurToolTipData.tooltipX = toX
      CurToolTipData.tooltipY = toY
      w:SetProperty("X", toX)
      w:SetProperty("Y", toY)
    elseif command == "hideFinished" then
    end
  end
  function Main_wndToolTip_swfToolTip_OnUserEvent(a, b, c, d)
    if a == "AS_Print" then
      Logger:print("tooltip.lua", b)
    elseif a == "print" then
    end
  end
  function Main_wndToolTip_swfToolTip_OnFocus(a, b)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
;(function()
  HotKeyEvents = {
    override = false,
    enableAtlas = true,
    enableAboutMe = true,
    enableFriends = true,
    enableShopping = true,
    enableHousing = true,
    enablePets = true,
    enableActivities = true,
    enableAll = true,
    SetEnabled = function(self, is1, is2, is3, is4, is5, is6)
      self.enableAboutMe = is1 == 1
      self.enableFriends = is2 == 1
      self.enableShopping = is3 == 1
      self.enableHousing = is4 == 1
      self.enablePets = is5 == 1
      self.enableActivities = is6 == 1
    end,
    SetEnabledAll = function(self, bool)
      self.enableAll = bool
    end,
    Check = function(self)
      if override then
        return false
      end
      if Context:Includes("ScoreScreenHide") then
        return true
      end
      if Context:Includes("MiniGameStatusHandlerHide") then
        MiniGameStatusHandler:Hide()
        MiniGameStatusHandler:CallDelegate("StatusOnPop")
      end
      if Tutorial.inTutorial or PetTutorial.enabled then
        return true
      end
      return false
    end,
    ToggleAtlas = function(self)
      if not self.enableAtlas or not self.enableAll then
        return
      end
      Atlas:GlobalToggle()
    end,
    ToggleJobBrowser = function(self)
      if not self.enableAboutMe or not self.enableAll then
        return
      end
      Logger:print("hotkeyevents.lua", "Toggle JobBrowser")
      if self:Check() then
        return
      end
      if JobHandler.screenActive then
        JobHandler:Hide()
      else
        GameDock:ShowJobBrowser()
      end
    end,
    HideCharacter = function(self)
      if not self.enableAboutMe or not self.enableAll then
        return
      end
      Logger:print("hotkeyevents.lua", "Hide Character")
      if self:Check() then
        return
      end
      if JobHandler.screenActive then
        JobHandler:Hide()
      end
    end,
    ToggleCharacter = function(self)
      if not self.enableAboutMe or not self.enableAll then
        return
      end
      Logger:print("hotkeyevents.lua", "Toggle Character")
      if self:Check() then
        return
      end
      if JobHandler.screenActive then
        JobHandler:Hide()
      else
        JobHandler:Show(JobHandler.MODE_EQUIPMENT)
      end
    end,
    TogglePets = function(self)
      if not self.enablePets or not self.enableAll then
        return
      end
      Logger:print("hotkeyevents.lua", "Toggle Pets")
      if self:Check() then
        return
      end
      if Context:Includes("BrowserHandlerPets") then
        Context:ClearToInclusive("BrowserHandlerPets")
      elseif Context:Includes("PetsHandler") then
        Context:ClearToInclusive("PetsHandler")
      elseif Pet.IsBusy() == nil then
        PetsHandler:Show()
      end
    end,
    ToggleQuests = function(self)
      if not self.enableActivities or not self.enableAll then
        return
      end
      Logger:print("hotkeyevents.lua", "Toggle Quests")
      if self:Check() then
        return
      end
      if Context:Includes("QuestWindow") then
        Context:ClearToInclusive("QuestWindow")
      else
        QuestHandler:ShowAndSelectQuests()
      end
    end,
    ToggleInventory = function(self)
      if not self.enableAboutMe or not self.enableAll then
        return
      end
      print("ToggleInventory self:Check(): " .. tostring(self:Check()))
      if self:Check() then
        return
      end
      if JobHandler.screenActive then
        JobHandler:Hide()
      else
        JobHandler:Show(JobHandler.MODE_INVENTORY)
      end
    end
  }
end)()
