        lobbyID = tonumber(Ui.GetLobbyGameType())
      end
      if lobbyID == 3 or lobbyID == 6 or lobbyID == -1 then
        self.swfLeft = self.swfLeftSoccer
        self.wndLeft = self.wndLeftSoccer
        self.nameLeft = self.nameLeftSoccer
      else
        self.swfLeft = self.swfLeftNormal
        self.wndLeft = self.wndLeftNormal
        self.nameLeft = self.nameLeftNormal
      end
      self:OnResize()
      self.paneLeft:SetLimitAdvance(true)
      self.paneTop:SetLimitAdvance(false)
      self.paneBottom:SetLimitAdvance(true)
      self.paneLeft:Reset()
      self.paneTop:Reset()
      self.paneBottom:Reset()
      if self.myMode == 7 then
        self.paneQuickTop:SetLimitAdvance(false)
        self.paneQuickTop:Reset()
      end
      local lobbyDescription = ""
      if not isMatchmaking then
        lobbyDescription = Ui.GetLobbyDescription()
        self.paneTop:Invoke("setButtonText", Ui.GetString("CreateNewGame"))
        self.paneTop:Invoke("setTitleCreate", Ui.GetString("CreateNewGame"))
        self.paneTop:Invoke("setButtonVisibleByString", "mode0.buttonCreate")
        self.paneTop:Invoke("setButtonHiddenByString", "mode2.buttonBack")
      else
        lobbyDescription = Ui.GetString("MatchmakingDescription")
        if self.myMode == 7 then
          self.paneQuickTop:Invoke("setButtonHiddenByString", "mode0.buttonCreate")
          self.paneQuickTop:Invoke("setButtonVisibleByString", "mode2.buttonBack")
        end
      end
      self.paneTop:Invoke("setTitle", lobbyDescription)
      if self.myMode == 7 then
        self.paneQuickTop:Invoke("setTitle", lobbyDescription)
      end
      Logger:print("lobby.lua", " in '" .. lobbyDescription .. "' type(" .. lobbyID .. ")")
      self.lobbyGameType = 0
      self.lobbyProfileType = 0
      if lobbyID == 1 then
        self.lobbyGameType = 10
        self.lobbyProfileType = 5
      elseif lobbyID == 2 then
        self.lobbyGameType = 11
        self.lobbyProfileType = 7
      end
      if self.lobbyGameType > 0 then
      end
      if not isMatchmaking then
        self.paneLeft:Invoke("setMatchmaking", "0")
        self:InitGameList()
        local gameID = Ui.GetLobbyGameId()
        if gameID and gameID > 0 then
          local gameIndex = self:GetGameIndexFromId(gameID)
          if gameIndex and gameIndex >= 0 then
            self:SelectedGame(gameID, gameIndex)
            self:JoinGame(true)
            if Ui.GetLobbyGameCreatorGuid() == Ui.GetPlayerGuid() and tonumber(Ui.GetPlayerGuid()) ~= 0 then
              self.myMode = 2
              self.paneTop:Invoke("setMode", 2)
              self.paneBottom:Invoke("setJoinFlashOn")
              self.paneBottom:Invoke("setJoinText", Ui.GetString("START!"))
              self.paneBottom:Invoke("setJoinButtonGreen")
              self.paneBottom:Invoke("setJoinButtonEnabled")
              self:EnableScriptEvents(self.groupDS)
              self.justCreatedGame = true
              self:GroupDataUpdated()
            else
              self.justCreatedGame = true
              self:GroupDataUpdated()
            end
          end
        end
      else
        self:InitQueues()
      end
    end,
    OnResize = function(self, resizeOnly)
      Logger:print("lobby.lua", " ### LOBBY OnResize() panesHidden(" .. tostring(self.panesHidden) .. ")")
      self.paneLeft = GfxCtrl.Find(self.swfLeft)
      self.paneBottom = GfxCtrl.Find(self.swfBottom)
      self.paneTop = GfxCtrl.Find(self.swfTop)
      self.paneQuickTop = GfxCtrl.Find(self.swfQuickTop)
      self.wLeft = Window.Find(self.wndLeft)
      self.wBottom = Window.Find(self.wndBottom)
      self.wTop = Window.Find(self.wndTop)
      self.wQuickTop = Window.Find(self.wndQuickTop)
      local widthLeft, heightLeft = self.wLeft:GetSize()
      local widthBottom, heightBottom = self.wBottom:GetSize()
      local widthTop, heightTop = self.wTop:GetSize()
      heightTop = heightTop / 2
      local sw, sh = Window.GetCanvasSize()
      if self.myMode == 7 then
        self.wBottom:Hide()
      else
        self.wBottom:Show()
      end
      if self.myMode == 7 then
        self.wQuickTop:Show()
        self.wTop:Hide()
        self.paneTop:Unload()
      else
        self.wTop:Show()
        self.wQuickTop:Hide()
        self.paneQuickTop:Unload()
      end
      if self.leftPaneShown == 0 then
        widthLeft = 30
      end
      if self.topX == 0 then
        self.topX = sw / 2 - widthTop / 2 + widthLeft / 2 - 30
        self.topY = 54
        self.botX = sw / 2 - widthBottom / 2 + widthLeft / 2 - 30
        self.botY = 332
        self.wTop:SetPosition(self.topX, self.topY)
        if self.myMode == 7 then
          self.wQuickTop:SetPosition(self.topX, self.topY)
        end
        self.wBottom:SetPosition(self.botX, self.botY)
      else
        self.topX = sw / 2 - widthTop / 2 + widthLeft / 2 - 30
        self.topY = 54
        self.botX = sw / 2 - widthBottom / 2 + widthLeft / 2 - 30
        self.botY = 332
      end
      if self.panesHidden == false then
        self.topY = 54
        self.botY = 332
      else
        self.topY = 0 - heightTop
        self.botY = 332
      end
      if self.myMode == 7 then
        WindowTweener:Create("Main.wndQuickTop", "Y", nil, self.topY, 0.3)
        WindowTweener:Create("Main.wndQuickTop", "X", nil, self.topX, 0.3)
      else
        WindowTweener:Create("Main.wndLobbyTop", "Y", nil, self.topY, 0.3)
        WindowTweener:Create("Main.wndLobbyTop", "X", nil, self.topX, 0.3)
      end
      WindowTweener:Create("Main.wndLobbyBottom", "Y", nil, self.botY, 0.3)
      WindowTweener:Create("Main.wndLobbyBottom", "X", nil, self.botX, 0.3)
      if resizeOnly == true then
      elseif self.leftPaneShown == 1 then
        self:ShowLeftPane(true)
      end
    end,
    ShowLeftPane = function(self, resizeOnly)
      self.leftPaneShown = 1
      self.wLeft:Show()
      local widthLeft, heightLeft = self.wLeft:GetSize()
      local widthTop, heightTop = self.wTop:GetSize()
      local sw, sh = Window.GetCanvasSize()
      self.paneLeftY = 72
      self.wLeft:SetPosition(0 - widthLeft, self.paneLeftY)
      if self.panesHidden == false then
        self.paneLeftX = sw / 2 - widthTop / 2 - widthLeft / 2 + 15
        WindowTweener:Create(self.nameLeft, "X", nil, self.paneLeftX, 0.3)
      end
      if resizeOnly == true then
      else
        self.paneLeft:Invoke("hideAllClips")
        self.paneLeft:Invoke("setSpinnerVisibility", "false")
        for i = self.maxPlayersInGame, 6 do
          self.paneLeft:Invoke("disableClip", i)
        end
      end
      self:OnResize(true)
    end,
    HideLeftPane = function(self)
      if self.leftPaneShown == 1 then
        local widthLeft, heightLeft = self.wLeft:GetSize()
        WindowTweener:Create(self.nameLeft, "X", nil, 0 - widthLeft, 0.3, function()
          self.wLeft:Hide()
          self.paneLeft:Unload()
        end)
        self.leftPaneShown = 0
        self:OnResize(true)
      end
    end,
    Hide = function(self, NoShowMainFlag, forceLeaveLobby)
      if self.myMode == -1 or self.myMode == 4 then
        return
      end
      FriendPicker:Hide()
      self.gameIsStarted = false
      self.justCreatedGame = false
      self.justJoinedGame = false
      self.waitingForMyGameInDS = false
      self.playerList = {}
      self.playerListPending = {}
      HUD:PlaySound("WindowHide")
      if not NoShowMainFlag and self.myMode ~= 0 and self.matchmaking == false then
        self:LeaveGame()
        return
      end
      if not self.wLeft or not self.wBottom or not self.wTop and not self.wQuickTop then
        return
      end
      Context:Pop()
      local widthLeft, heightLeft = self.wLeft:GetSize()
      local widthBottom, heightBottom = self.wBottom:GetSize()
      local widthTop, heightTop = self.wTop:GetSize()
      local sw, sh = Window.GetCanvasSize()
      local tPaneLeft = self.paneLeft
      WindowTweener:Create(self.nameLeft, "X", nil, 0 - widthLeft, 0.3, function()
        self.wLeft:Hide()
        tPaneLeft:Unload()
      end)
      self.leftPaneShown = 0
      if self.myMode == 7 then
        WindowTweener:Create("Main.wndQuickTop", "Y", nil, 0 - heightTop, 0.3, function()
          Window.Find(Ui.GetName("Main.wndQuickTop")):Hide()
          GfxCtrl.Find(Ui.GetName("Main.wndQuickTop.swfQuickTop")):Unload()
          GfxCtrl.Find(Ui.GetName("Main.wndLobbyTop.swfLobbyTop")):Unload()
        end)
      else
        WindowTweener:Create("Main.wndLobbyTop", "Y", nil, 0 - heightTop, 0.3, function()
          Window.Find(Ui.GetName("Main.wndLobbyTop")):Hide()
          GfxCtrl.Find(Ui.GetName("Main.wndLobbyTop.swfLobbyTop")):Unload()
        end)
      end
      WindowTweener:Create("Main.wndLobbyBottom", "Y", nil, sh, 0.3, function()
        Window.Find(Ui.GetName("Main.wndLobbyBottom")):Hide()
        GfxCtrl.Find(Ui.GetName("Main.wndLobbyBottom.swfLobbyBottom")):Unload()
      end)
      NonModalContext:RemoveContext(self)
      self.paneLeft = nil
      self.paneBottom = nil
      self.paneTop = nil
      self.paneQuickTop = nil
      self.isShown = false
      self.myMode = -1
      if NoShowMainFlag == true or ActivityPortal.isShown then
        if forceLeaveLobby == true then
          Ui.LeaveLobby()
          self.lobbyGameType = 0
          self.lobbyProfileType = 0
        end
      else
        if not self.matchmaking then
          Ui.LeaveLobby()
          HUD:showMain()
          GroupHandler:Show()
        elseif not HUD.mainShown then
          HUD:showMain()
          GroupHandler:Show()
        end
        self:DisableScriptEvents(self.lobbyDS)
        self:DisableScriptEvents(self.gameDS)
        self.justLeftLobby = true
        self.lobbyGameType = 0
        self.lobbyProfileType = 0
      end
    end,
    InitQueues = function(self)
      Logger:print("lobby.lua", "Lobby:InitQueues")
      self.myMode = 5
      Matchmaking.UpdateAllQueueStats()
      self:HideLeftPane()
      self:EnableScriptEvents(self.queuesDS)
      self:EnableScriptEvents(self.groupDS)
      self.paneLeft:Invoke("setMatchmaking", "1")
      self.paneTop:Invoke("setMatchmaking", "1")
      self.paneTop:Invoke("setMode", 0)
      self.paneTop:Invoke("setGameListMode", self.myMode)
      self.wTop:SetProperty("Legend", 11)
      self.paneBottom:Invoke("setJoinText", Ui.GetString("video_label_page_next"))
      self.paneBottom:Invoke("setJoinButtonGreen")
      if Context:Includes("QuestHandler") then
        self.paneBottom:Invoke("hideBackButton")
      else
        self.paneBottom:Invoke("showCloseButton")
      end
      self.paneBottom:Invoke("setGameDescription", Ui.GetString("MatchmakingGameDescription"))
      Matchmaking.PopulateQueues()
    end,
    QueuesUpdated = function(self)
      Logger:print("lobby.lua", "Lobby:QueuesUpdated")
      self:QueuesPopulate(self.lastOffset, self.lastCount)
    end,
    QueuesPopulate = function(self, _offset, _count)
      Logger:print("lobby.lua", "Lobby:QueuesPopulate " .. _offset .. ", " .. _count)
      if self.paneTop == nil and self.paneQuickTop == nil then
        return
      end
      self.lastOffset = _offset
      self.lastCount = _count
      local foundSelectedGame = false
      local numGames = 0
      local numGamesInDS = 0
      local gameData = ""
      local ds = DsTable.Find(self.queuesDS)
      if ds then
        local numRows = ds:GetRowCount()
        numGamesInDS = numRows
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          if self.selectedGame ~= nil and tostring(self.selectedGame) == tostring(ds:GetData(i, 0)) then
            foundSelectedGame = true
          end
        end
        if _offset >= numRows then
        else
          if numRows < _count + _offset then
            _count = numRows - _offset
          end
          for i = _offset, _offset + _count - 1 do
            numGames = numGames + 1
            local gameRow = ""
            local gameID = "GUID" .. tostring(ds:GetData(i, 0))
            local gameName = tostring(ds:GetData(i, 1))
            local gameHeader = Ui.GetString("InQueue")
            local minPlayers = tostring(ds:GetData(i, 3))
            local maxPlayers = tostring(ds:GetData(i, 4))
            local curPlayers = tostring(ds:GetData(i, 15))
            local waitTime = tostring(ds:GetData(i, 16))
            if waitTime == "0" then
              waitTime = "-"
            else
              gameName = gameName .. ", " .. Ui.GetString("AvgWait") .. ": " .. self:secondsToMinutes(waitTime)
            end
            gameHeader = string.gsub(gameHeader, "@1", curPlayers, 1)
            local timeDiff = QuickMatch:ImInQueue(ds:GetData(i, 0))
            if timeDiff >= 0 then
              gameName = gameName .. ", " .. Ui.GetString("WAITING") .. " "
            end
            if GroupHandler:getGroupSize() > tonumber(maxPlayers) then
              gameID = "GUID-99"
              gameName = gameName .. ": " .. string.gsub(Ui.GetString("GroupTooBig"), "@1", tostring(maxPlayers))
            end
            gameRow = tostring(i) .. "^" .. gameID .. "^" .. "0" .. "^" .. "0" .. "^" .. gameHeader .. "^" .. gameName .. "^" .. timeDiff
            gameData = gameData .. gameRow .. ";"
          end
        end
      end
      if numGamesInDS <= 0 then
        self.paneTop:Invoke("setGameListData", "", 0)
        self.paneTop:Invoke("setLoadingText", Ui.GetString("NoGamesFound"), Ui.GetString("YouShouldCreateOne"), "False")
      else
        self.paneTop:Invoke("setGameListData", gameData, numGamesInDS)
        if self.myMode == 7 then
        end
      end
      if foundSelectedGame == false and self.myMode ~= 6 then
        self.paneBottom:Invoke("setJoinButtonDisabled")
        self.paneBottom:Invoke("hideAllGameOptions")
        self.paneBottom:Invoke("setTitle", " ")
      end
      if 0 <= self.joiningQueue then
        self:JoinQueueWithID(self.joiningQueue)
      end
    end,
    GetQueueNameWithID = function(self, qID)
      local ds = DsTable.Find(self.queuesDS)
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          local gameID = tostring(ds:GetData(i, 0))
          local gameName = tostring(ds:GetData(i, 1))
          local avgWait = tostring(ds:GetData(i, 16))
          if tostring(qID) == gameID then
            return gameName, avgWait
          end
        end
      end
      return tostring(qID), 0
    end,
    JoinQueue = function(self)
      Logger:print("lobby.lua", "JoinQueue " .. tostring(self.selectedGame) .. ", " .. tostring(self.currentQueueName) .. ", " .. tostring(self.currentGameDescription) .. ", " .. tostring(self.currentGameIcon))
      self.myMode = 7
      self:OnResize()
      self.justCreatedGame = true
      self.playerList = {}
      self.playerListPending = {}
      self:HideLeftPane()
      self:GroupDataUpdated()
      if self.myMode == 7 then
        self.paneQuickTop:Invoke("setMode", self.myMode)
        self.paneQuickTop:Invoke("setQuickMatchInfo", self.currentQueueName, self.currentGameDescription, self.currentGameIcon)
      end
    end,
    JoinQueueMulti = function(self)
      Logger:print("lobby.lua", "Lobby:JoinQueueMulti")
      self.myMode = 6
      self:ShowLeftPane()
      self.paneLeft:Invoke("setMatchmaking", "1")
      self:GroupDataUpdated()
      self.paneTop:Invoke("setMode", 2)
      self.paneTop:Invoke("setGameDesc", self.currentGameDescription)
      self.paneTop:Invoke("setTitleCreated", self.currentQueueName)
      self.paneTop:Invoke("setGamePicture", self.currentGameIcon)
      if self.isLeader == true then
        self.paneBottom:Invoke("setGameDescription", Ui.GetString("MatchmakingGameDescription2"))
      else
        self.paneBottom:Invoke("setGameDescription", Ui.GetString("MatchmakingGameDescription3"))
      end
      self.paneBottom:Invoke("setJoinText", Ui.GetString("Join!"))
      self.paneBottom:Invoke("setJoinFlashOn")
      self.paneBottom:Invoke("setJoinButtonEnabled")
      self.paneBottom:Invoke("showBackButton")
    end,
    EnterQueue = function(self)
      if self.currentQueueID then
        Logger:print("lobby.lua", "EnterQueue(" .. tostring(self.currentQueueID) .. ")")
        if GroupHandler:getGroupSize() > self.currentQueueMaxGroupSize then
          local msg = string.gsub(Ui.GetString("GroupTooBig"), "@1", tostring(self.currentQueueMaxGroupSize))
          NotificationHandler:SystemMessage(msg, nil, "0xFF3333")
        else
          Matchmaking.JoinQueue(self.currentQueueID)
          self:Hide()
          NavigationHandler:EnableBar()
          GameDock_PS3:NavigationExit()
        end
      end
    end,
    JoinQueueWithID = function(self, qID)
      Logger:print("lobby.lua", "Lobby:JoinQueueWithID")
      Context:Push(self.CONTEXT_HIDE, function()
        Lobby:OnUserEvent("close")
      end)
      if self.paneTop == nil and self.paneQuickTop == nil then
        self:Show(true)
      end
      local ds = DsTable.Find(self.queuesDS)
      if ds then
        local rows = ds:GetRowCount()
        self.joiningQueue = -1
        for i = 0, rows - 1 do
          local qid = tonumber(ds:GetData(i, 0))
          if tonumber(qID) == qid then
            self:SelectedQueue("GUID" .. tostring(qid), i)
            if GroupHandler:getGroupSize() > self.currentQueueMaxGroupSize then
              local msg = string.gsub(Ui.GetString("GroupTooBig"), "@1", tostring(self.currentQueueMaxGroupSize))
              NotificationHandler:SystemMessage(msg, nil, "0xFF3333")
            else
              self:JoinQueue()
            end
            return
          end
        end
      end
      self.joiningQueue = qID
    end,
    SelectedQueue = function(self, gameID, gameIndex)
      Logger:print("lobby.lua", "Lobby:SelectedQueue")
      if not gameIndex or tonumber(gameIndex) < 0 then
        return
      end
      HUD:PlaySound("ButtonPress")
      gameID = tostring(gameID)
      gameIndex = tonumber(gameIndex)
      self.selectedGame = string.sub(gameID, 5, -1)
      self.paneBottom:Invoke("hideAllGameOptions")
      self:ResetBottomOptions()
      self.maxPlayersInGame = 0
      self.paneBottom:Invoke("setGameDescription", Ui.GetString("MatchmakingGameDescription"))
      if 0 > tonumber(self.selectedGame) then
        return
      end
      local ds = DsTable.Find(self.queuesDS)
      if ds then
        local i = gameIndex
        local numCols = ds:GetColumnCount()
        local gameName = ""
        local minigameName = ""
        local gameID = "GUID" .. tostring(ds:GetData(i, 0))
        local gameName = tostring(ds:GetData(i, 1))
        self.currentQueueName = gameName
        self.currentQueueID = ds:GetData(i, 0)
        self.currentGameDescription = ds:GetData(i, 17)
        self.currentGameIcon = ds:GetData(i, 18)
        self.currentQueueMaxGroupSize = tonumber(ds:GetData(i, 4))
        local gameHeader = Ui.GetString("InQueue")
        local minPlayers = tostring(ds:GetData(i, 3))
        local maxPlayers = tostring(ds:GetData(i, 4))
        local curPlayers = tostring(ds:GetData(i, 15))
        local waitTime = tostring(ds:GetData(i, 16))
        if waitTime == "0" then
          waitTime = "-"
        end
        gameHeader = string.gsub(gameHeader, "@1 ", "", 1)
        self.maxPlayersInGame = maxPlayers
        self.paneBottom:Invoke("setGameOption", 0, Ui.GetString("MaxPlayers"), maxPlayers)
        self.paneBottom:Invoke("setGameOption", 1, Ui.GetString("Min Players"), minPlayers)
        self.paneBottom:Invoke("setGameOption", 2, gameHeader, curPlayers)
        self.paneBottom:Invoke("setGameOption", 3, Ui.GetString("AvgWait"), waitTime)
        self.paneBottom:Invoke("setTitle", gameName)
        if GroupHandler:getGroupSize() > self.currentQueueMaxGroupSize then
          self.paneBottom:Invoke("setJoinFlashOff")
          self.paneBottom:Invoke("setJoinButtonDisabled")
        else
          self.paneBottom:Invoke("setJoinFlashOn")
          self.paneBottom:Invoke("setJoinButtonEnabled")
        end
      end
    end,
    SelectGameYouAreIn = function(self)
      Logger:print("lobby.lua", "######### SelectGameYouAreIn ###########")
      local gameID = Ui.GetLobbyGameId()
      Logger:print("lobby.lua", "      gameID(" .. tostring(gameID) .. ")")
      if gameID and gameID > 0 then
        self.selectedGame = gameID
        local gameIndex = self:GetGameIndexFromId(gameID)
        if gameIndex and gameIndex >= 0 then
          self:SelectedGame("GUID" .. tostring(gameID), gameIndex)
          self.waitingForMyGameInDS = false
          self:DisableScriptEvents(self.gameDS)
          return true
        end
      end
      return false
    end,
    QueueInviteHandler = function(self, numPeople)
      local slotsLeft = tonumber(self.maxPlayersInGame) - tonumber(numPeople)
      if slotsLeft < 0 then
        slotsLeft = 0
      end
      local tt = Ui.GetString("RoomForMore")
      tt = string.gsub(tt, "@1", tostring(slotsLeft), 1)
      if slotsLeft > 0 then
        self.paneLeft:Invoke("enableInvite", tt)
      else
        self.paneLeft:Invoke("disableInvite", tt)
      end
    end,
    StartInviteOnSlot = function(self, slotID)
      if slotID ~= nil then
        slotID = 0
      end
      local widthLeft, heightLeft = self.wLeft:GetSize()
      local numFriends = FriendPicker:Show(self.paneLeftX + widthLeft - 80, self.paneLeftY + 160 + slotID * 80, slotID)
      if numFriends <= 0 then
        FriendPicker:Hide()
        self.paneLeft:Invoke("toolTipOnClip", slotID, Ui.GetString("NoOnlineFriends"))
      end
    end,
    CancelInviteOnSlot = function(self, slotID)
      self.paneLeft:Invoke("removePlayer", slotID)
    end,
    FinishInviteOnSlot = function(self, slotID, guid, name)
      guid = string.sub(guid, 2)
      if self:IsAlreadyInGroup(guid, name) == true then
        return
      end
      local mySlot = self:GetExistingPlayerSlot(guid, name)
      if mySlot then
        slotID = mySlot
      end
      Ui.InviteToGroup(name)
    end,
    GameIsStarting = function(self)
      if Trade.RejectInvite then
        Trade.RejectInvite()
      end
      self.gameIsStarted = true
      self.paneBottom:SetLimitAdvance(false)
      self.paneBottom:Invoke("gameIsStarting")
      self.myMode = 4
      MiniGameStatusHandler:Populate(true)
    end,
    GameIsLaunching = function(self)
      if Trade.RejectInvite then
        Trade.RejectInvite()
      end
      self.myMode = 3
      self:Hide(true)
    end,
    GroupDataUpdated = function(self)
      if self.myMode == 7 then
        return
      end
      local gameID = Ui.GetLobbyGameId()
      if self.matchmaking == false and gameID == 0 and self.justCreatedGame == false and self.justJoinedGame == false then
        self:LeaveGame()
        return
      end
      local ds = DsTable.Find(self.groupDS)
      if ds then
        local numRows = ds:GetRowCount()
        self.playerCount = numRows
        if self.myMode == 5 or self.myMode == 6 then
          self:QueueInviteHandler(self.playerCount)
        end
        local numCols = ds:GetColumnCount()
        for i = 1, #self.playerList do
          local removed = true
          local slot
          for ii = 0, numRows - 1 do
            slot = i
            local playerGUID = ds:GetData(ii, 1)
            if self.playerList[i] ~= -1 and playerGUID == self.playerList[i] then
              removed = false
              break
            end
          end
          if removed == true and slot and self.playerList[i] ~= -1 then
            self:RemovePlayer(slot)
          end
        end
        local solo = Ui.GetString("GroupStatusSolo")
        local leader = Ui.GetString("GroupStatusLeader")
        local member = Ui.GetString("GroupStatusMember")
        local gotLeader = false
        local leaderGuid = 0
        for i = 0, numRows - 1 do
          local playerGUID = ds:GetData(i, 1)
          local playerNAME = ds:GetData(i, 0)
          local rank = ds:GetData(i, 7)
          if self:PlayerAlreadyInGroup(playerGUID) then
            if rank == leader or rank == "Leader" or rank == solo or rank == "Solo" then
              gotLeader = true
              leaderGuid = playerGUID
            end
          elseif rank == leader or rank == "Leader" or self.justCreatedGame == true and (rank == solo or rank == "Solo") then
            self:AddPlayer(playerGUID, playerNAME)
            gotLeader = true
            leaderGuid = playerGUID
            break
          end
        end
        if self.myMode == 5 or self.myMode == 6 then
          if leaderGuid == Ui.GetPlayerGuid() then
            self.isLeader = true
            self.paneLeft:Invoke("setGroupLeader")
            if self.myMode == 6 then
              self.paneBottom:Invoke("setGameDescription", Ui.GetString("MatchmakingGameDescription2"))
            end
          else
            self.isLeader = false
            self.paneLeft:Invoke("setNotGroupLeader", Ui.GetString("OnlyTheGroupLeaderCanInviteFriends"))
            if self.myMode == 6 then
              self.paneBottom:Invoke("setGameDescription", Ui.GetString("MatchmakingGameDescription3"))
            end
          end
        end
        if gotLeader == false then
          if self.matchmaking == false then
            self:LeaveGame()
          end
          return
        end
        for i = 0, numRows - 1 do
          local playerGUID = ds:GetData(i, 1)
          local playerNAME = ds:GetData(i, 0)
          local rank = ds:GetData(i, 7)
          if self:PlayerAlreadyInGroup(playerGUID) then
          elseif rank == member or rank == "Group" or rank == "Member" then
            self:AddPlayer(playerGUID, playerNAME)
          end
        end
        self:PrintPlayerList()
      end
      self.justJoinedGame = false
      if self.justCreatedGame == true then
        self.justCreatedGame = false
      end
    end,
    PrintPlayerList = function(self)
      for i = 1, #self.playerList do
        Logger:print("lobby.lua", "   PrintPlayerList: " .. i .. ": " .. self.playerList[i])
      end
    end,
    PlayerAlreadyInGroup = function(self, guid)
      for i = 0, #self.playerList do
        if guid == self.playerList[i] then
          return true
        end
      end
      return false
    end,
    AddPlayer = function(self, guid, name)
      if guid == -1 or guid == 0 or not guid or not name or not self.paneLeft then
        return
      end
      local mySlot = self:GetPlayerSlot(guid, name)
      if mySlot then
        self.playerList[mySlot] = guid
      end
      self.paneLeft:Invoke("addPlayer", "GUID" .. tostring(guid), tostring(name), mySlot)
    end,
    IsAlreadyInGroup = function(self, guid, name)
      for slot = 0, 5 do
        Logger:print("lobby.lua", tostring(slot) .. " playerListSlot(" .. tostring(self.playerList[slot]) .. ") playerListPendingSlot(" .. tostring(self.playerListPending[slot]) .. ")")
        if self.playerList[slot] == guid then
          Logger:print("lobby.lua", "    |__ found old player " .. guid .. " in slot " .. tostring(slot))
          mySlot = slot
          self.playerListPending[slot] = -1
          return true
        end
      end
      return false
    end,
    GetExistingPlayerSlot = function(self, guid, name)
      local mySlot
      for slot = 0, 5 do
        Logger:print("lobby.lua", tostring(slot) .. " playerListSlot(" .. tostring(self.playerList[slot]) .. ") playerListPendingSlot(" .. tostring(self.playerListPending[slot]) .. ")")
        if self.playerList[slot] == guid then
          Logger:print("lobby.lua", "    |__ found old player " .. guid .. " in slot " .. tostring(slot))
          mySlot = slot
          self.playerListPending[slot] = -1
          break
        elseif self.playerListPending[slot] == guid then
          Logger:print("lobby.lua", "    |__ found pending player " .. guid .. " in slot " .. tostring(slot))
          mySlot = slot
          break
        end
      end
      return mySlot
    end,
    GetPlayerSlot = function(self, guid, name)
      local mySlot
      mySlot = self:GetExistingPlayerSlot(guid, name)
      if mySlot == nil then
        for slot = 0, 5 do
          if not self.playerList[slot] or self.playerList[slot] == -1 then
            Logger:print("lobby.lua", "    |__ found new player " .. guid .. " an empty slot " .. tostring(slot))
            mySlot = slot
            break
          end
        end
      end
      return mySlot
    end,
    RemoveAllPlayers = function(self)
      for slot = 0, 5 do
        self:RemovePlayer(slot)
      end
    end,
    RemovePlayer = function(self, slot)
      Logger:print("lobby.lua", "removePlayer slot(" .. tostring(slot) .. ")")
      self.paneLeft:Invoke("removePlayer", tonumber(slot))
      self.playerList[slot] = -1
      self.playerListPending[slot] = -1
    end,
    LeaveGame = function(self, initGameListFlag)
      Logger:print("lobby.lua", "Leaving Game")
      if self.gameIsStarted == true then
        return
      end
      if self.paneLeft == nil then
        return
      end
      Ui.LeaveLobbyGame()
      self:HideLeftPane()
      self.paneLeft:Invoke("hideAllClips")
      self.playerList = {}
      self.playerListPending = {}
      self.optionIndexToOptionId = {}
      self:ResetBottomOptions()
      self.paneBottom:Invoke("setTitle", " ")
      self.paneBottom:Invoke("setGameDescription", " ")
      self.selectedGame = nil
      if initGameListFlag == true then
      else
        self:InitGameList()
      end
    end,
    StartGame = function(self)
      Logger:print("lobby.lua", "Starting Game")
      self.paneBottom:Invoke("setJoinButtonDisabled")
      Ui.StartLobbyGame()
    end,
    JoinGame = function(self, dontJoinFlag)
      Logger:print("lobby.lua", "Joining Game: " .. tostring(self.selectedGame))
      self:DisableScriptEvents(self.lobbyDS)
      self:DisableScriptEvents(self.gameDS)
      self.myMode = 3
      self.paneTop:Invoke("setMode", 2)
      if not dontJoinFlag then
        self.paneTop:Invoke("setTitleCreated", Ui.GetString("GameJoined"))
      end
      self.paneBottom:Invoke("setJoinButtonBeige")
      self.paneBottom:Invoke("setJoinButtonEnabled")
      self.paneBottom:Invoke("setJoinFlashOff")
      self.paneBottom:Invoke("setJoinText", Ui.GetString("LeaveGame"))
      self.paneBottom:Invoke("setNotWaiting")
      self.paneBottom:Invoke("showCloseButton")
      self:ShowLeftPane()
      self.paneLeft:Invoke("setSpinnerVisibility", "true")
      if not dontJoinFlag then
        self.justJoinedGame = true
        Ui.JoinLobbyGame(self.selectedGame)
      else
        self:JoinedGame()
      end
      self:EnableScriptEvents(self.groupDS)
    end,
    JoinedGame = function(self, x)
      local gameID = Ui.GetLobbyGameId()
      Logger:print("lobby.lua", " ###### JOINED GAME ##### " .. tostring(gameID))
      if x then
        self.paneTop:Invoke("setGamePicture", "GUID" .. tostring(x))
      end
      if tonumber(gameID) == 0 then
        return
      end
      if gameID then
        local gameDesc = Ui.GetLobbyGameDescription(gameID)
        local gameIcon = Ui.GetLobbyGameIcon(gameID)
        if gameDesc and tostring(gameDesc) ~= "0" then
          self.paneTop:Invoke("setGameDesc", gameDesc)
        else
          self.paneTop:Invoke("setGameDesc", "Error: Could not fetch game description")
        end
        if gameIcon and not x then
          self.paneTop:Invoke("setGamePicture", "GUID" .. tostring(gameIcon))
        else
        end
        if self.selectedGame == nil then
          self:SelectGameYouAreIn()
        end
        self:GroupDataUpdated()
      end
    end,
    BrowserOnUserEvent = function(self, a, b)
      Logger:print("lobby.lua", "LOBBY: BrowserOnUserEvent: " .. tostring(a))
      if a == "ExpandedBrowser" then
        GroupScreen.SetChangingJob(true)
        self.panesHidden = true
        self:OnResize()
      elseif a == "CompressBrowser" then
        GroupScreen.SetChangingJob(false)
        self.panesHidden = false
        self:OnResize()
      elseif a == "CloseBrowser" then
      elseif a == "SelectVehicle" then
      end
    end,
    ResetBottomOptions = function(self)
      self.myGameOptions = {}
      self.myGameOptionsValues = {}
      for i = 0, 3 do
        self.paneBottom:Invoke("setGameOption", i, " ", " ")
      end
      self.paneBottom:Invoke("setGameDescription", " ")
      self.paneBottom:Invoke("setTitle", " ")
    end,
    GetGameIndexFromId = function(self, gameID)
      gameID = tonumber(gameID)
      local ds = DsTable.Find(self.lobbyDS)
      if ds then
        local numCols = ds:GetColumnCount()
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          for ii = 0, numCols - 1 do
            local gameDataKey = ds:GetColumnName(ii)
            local gameDataValue = ds:GetData(i, ii)
            if gameDataKey == "GameId" then
              if tonumber(gameDataValue) == gameID then
                return i
              else
                break
              end
            end
          end
        end
      end
      Logger:print("lobby.lua", " #### GetGameIndexFromId(" .. gameID .. "): returning -1 cuz no matching game found")
      return -1
    end,
    GetStringFromColumn = function(self, colNum, colName)
      if colNum == 0 then
        return "GameId"
      end
      if colNum == 1 then
        return "Current Player Count"
      end
      if colNum == 2 then
        return "Host"
      end
      colNum = tonumber(colNum) - 3
      local dsName = "BaseClient.LobbyGameOption" .. tostring(colNum)
      local ds = DsTable.Find(dsName)
      if ds then
        local colName = ds:GetColumnName(0)
        local rows = ds:GetRowCount()
        if rows > 0 then
          local stringID = ds:GetData(0, 3)
          return self.stringMap[tonumber(stringID)]
        end
      end
      return "ERROR"
    end,
    SelectedGame = function(self, gameID, gameIndex)
      Logger:print("lobby.lua", "Game Index: " .. gameIndex)
      if tonumber(gameIndex) == nil then
        return
      end
      if tonumber(gameIndex) < 0 then
        return
      end
      if self.selectedGame == string.sub(gameID, 5, -1) then
        return
      end
      HUD:PlaySound("ButtonPress")
      gameID = tostring(gameID)
      gameIndex = tonumber(gameIndex)
      self.selectedGame = string.sub(gameID, 5, -1)
      self.paneBottom:Invoke("hideAllGameOptions")
      self:ResetBottomOptions()
      self.maxPlayersInGame = 0
      if 0 >= tonumber(self.selectedGame) then
        return
      end
      self.paneBottom:Invoke("setJoinFlashOn")
      self.paneBottom:Invoke("setJoinButtonEnabled")
      local ds = DsTable.Find(self.lobbyDS)
      if ds then
        local numCols = ds:GetColumnCount()
        local optionNumber = 0
        local gameName = ""
        local minigameName = ""
        for i = 0, numCols - 1 do
          local gameDataKeyString = self:Smallify(ds:GetColumnName(i))
          local gameDataValue = self:Smallify(ds:GetData(gameIndex, i))
          local gameDataKey = self:GetStringFromColumn(i, gameDataKeyString)
          if gameDataKey == "Max Players" then
            self.maxPlayersInGame = gameDataValue
          end
          if gameDataValue and gameDataKey ~= "GameId" and gameDataKey ~= "Required Profile Type" and gameDataKey ~= "Encounter" and gameDataKey ~= "Track" and gameDataKey ~= "Current Player Count" then
            self.paneBottom:Invoke("setGameOption", optionNumber, gameDataKeyString, gameDataValue)
            optionNumber = optionNumber + 1
          end
          local tempGameName = self:FilterGameName(tostring(gameDataKey), tostring(gameDataValue), tostring(gameDataKeyString))
          if tempGameName then
            gameName = gameName .. tempGameName
          end
          if gameDataValue and (gameDataKey == "Track" or gameDataKey == "Encounter") then
            self.paneBottom:Invoke("setGameDescription", gameDataValue)
          end
        end
        gameName = gameName and string.sub(gameName, 0, -3)
        self.paneBottom:Invoke("setTitle", gameName)
      end
    end,
    FilterGameName = function(self, key, value, keyString)
      if key and value and keyString and key ~= "GameId" and key ~= "Required Profile Type" and key ~= "Enable AI" and key ~= "Auto-Start" and key ~= "Target Score" and key ~= "Current Player Count" then
        return tostring(keyString) .. ": " .. tostring(value) .. " - "
      end
      return nil
    end,
    ConstructGameName = function(self)
      local gameName = ""
      for key, keyString in pairs(self.myGameOptions) do
        local value = self.myGameOptionsValues[key]
        local tempGameName = self:FilterGameName(key, value, keyString)
        if tempGameName then
          gameName = gameName .. tempGameName
        end
      end
      if string.len(gameName) > 3 then
        gameName = string.sub(gameName, 0, -3)
      end
      return gameName
    end,
    LobbyGameListUpdated = function(self)
      Logger:print("lobby.lua", "Lobby:LobbyGameListUpdated waitingForMyGameInDS(" .. tostring(self.waitingForMyGameInDS) .. ")")
      if self.waitingForMyGameInDS == true then
        if self:SelectGameYouAreIn() then
          self:DisableScriptEvents(self.gameDS)
        end
      else
        self:LobbyGameListPopulate(self.lastOffset, self.lastCount)
      end
    end,
    Smallify = function(self, str)
      if string.len(str) > 20 then
        return string.sub(str, 0, 18) .. ".."
      end
      return str
    end,
    LobbyGameListPopulate = function(self, _offset, _count)
      Logger:print("lobby.lua", "Lobby:LobbyGameListPopulate " .. _offset .. ", " .. _count)
      if self.paneTop == nil then
        return
      end
      self.lastOffset = _offset
      self.lastCount = _count
      local foundSelectedGame = false
      local numGames = 0
      local numGamesInDS = 0
      local gameData = ""
      local ds = DsTable.Find(self.lobbyDS)
      if ds then
        local numRows = ds:GetRowCount()
        numGamesInDS = numRows
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          if self.selectedGame ~= nil and tostring(self.selectedGame) == tostring(ds:GetData(i, 0)) then
            foundSelectedGame = true
          end
        end
        if _offset >= numRows then
        else
          if numRows < _count + _offset then
            _count = numRows - _offset
          end
          for i = _offset, _offset + _count - 1 do
            numGames = numGames + 1
            local gameRow = ""
            local gameName = ""
            local gameHeader = ""
            local maxPlayers = 0
            local curPlayers = 0
            local minigameName = ""
            local host
            for ii = 0, numCols - 1 do
              local gameDataKeyString = ds:GetColumnName(ii)
              local gameDataKey = self:GetStringFromColumn(ii, gameDataKeyString)
              local gameDataValue = ds:GetData(i, ii)
              if gameDataKey == "Max Players" then
                maxPlayers = tostring(gameDataValue)
              elseif gameDataKey == "Current Player Count" then
                curPlayers = tostring(gameDataValue)
              end
              if gameDataKey == "Track" or gameDataKey == "Encounter" then
                minigameName = tostring(gameDataValue)
              end
              if gameDataKey == "Host" then
                host = tostring(gameDataValue)
                host = self:Smallify(host)
              end
              if gameDataValue and gameDataKey and gameDataKeyString and gameDataKey ~= "GameId" and gameDataKey ~= "Max Players" and gameDataKey ~= "Required Profile Type" and gameDataKey ~= "Encounter" and gameDataKey ~= "Track" and gameDataKey ~= "Current Player Count" and gameDataKey ~= "Host" and gameDataKey ~= "Auto-Start" then
                gameDataKeyString = self:Smallify(gameDataKeyString)
                gameDataValue = self:Smallify(gameDataValue)
                gameName = gameName .. tostring(gameDataKeyString) .. ": " .. tostring(gameDataValue) .. " - "
              end
            end
            gameHeader = curPlayers .. " / " .. maxPlayers .. " " .. Ui.GetString("Players")
            gameName = gameName and string.sub(gameName, 0, -3)
            local gameID = "GUID" .. tostring(ds:GetData(i, 0))
            if host and host ~= "" and host ~= " " then
              minigameName = host .. ": " .. minigameName
            end
            gameRow = tostring(i) .. "^" .. gameID .. "^" .. "0" .. "^" .. "0" .. "^" .. gameHeader .. "^" .. minigameName .. " - " .. gameName .. "^-1"
            gameData = gameData .. gameRow .. ";"
          end
        end
      end
      local ds = DsTable.Find(self.gameDS)
      if ds then
        _count = self.lastCount - numGames
        if _count <= 0 then
        else
          _offset = self.lastOffset - numGamesInDS
          if _offset < 0 then
            _offset = 0
          end
          local numRows = ds:GetRowCount()
          numGamesInDS = numGamesInDS + tonumber(numRows)
          local numCols = ds:GetColumnCount()
          if _count > numRows then
            _count = numRows
            _offset = 0
          elseif numRows < _count + _offset then
            _count = numRows - _offset
          end
          for i = _offset, _offset + _count - 1 do
            local gameID = ds:GetData(i, 0)
            local numPlayers = ds:GetData(i, 1)
            local host = self:Smallify(ds:GetData(i, 2))
            local minigameName = self:Smallify(ds:GetData(i, 3))
            local difficulty = self:Smallify(ds:GetData(i, 4))
            local timeElapsed = ds:GetData(i, 5)
            gameID = "GUID" .. "-99"
            local gameName = "*" .. Ui.GetString("InProgress") .. "*" .. " " .. Ui.GetString("ElapsedTime") .. ": "
            local gameHeader = numPlayers .. " / " .. numPlayers .. " " .. Ui.GetString("Players")
            minigameName = host .. ": " .. minigameName
            local gameRow = tostring(i + numGames) .. "^" .. gameID .. "^" .. "0" .. "^" .. "0" .. "^" .. gameHeader .. "^" .. minigameName .. " - " .. gameName .. "^" .. tostring(timeElapsed)
            gameData = gameData .. gameRow .. ";"
          end
        end
      end
      if numGamesInDS <= 0 then
        self.paneTop:Invoke("setGameListData", "", 0)
        self.paneTop:Invoke("setLoadingText", Ui.GetString("NoGamesFound"), Ui.GetString("YouShouldCreateOne"), "False")
      else
        self.paneTop:Invoke("setGameListData", gameData, numGamesInDS)
      end
      ds = DsTable.Find(self.lobbyDS)
      if ds then
        numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          Logger:print("lobby.lua", "ds game: " .. tostring(ds:GetData(i, 0)))
          if self.selectedGame ~= nil and tostring(self.selectedGame) == tostring(ds:GetData(i, 0)) then
            foundSelectedGame = true
          end
        end
      end
      if foundSelectedGame == false then
        self.paneBottom:Invoke("setJoinButtonDisabled")
        self.paneBottom:Invoke("hideAllGameOptions")
        self.paneBottom:Invoke("setTitle", " ")
        self.paneBottom:Invoke("setGameDescription", " ")
      end
      self:EnableScriptEvents(self.lobbyDS)
      self:EnableScriptEvents(self.gameDS)
      self:DisableScriptEvents(self.groupDS)
    end,
    secondsToMinutes = function(self, seconds)
      seconds = tonumber(seconds)
      local minutes = math.floor(seconds / 60)
      seconds = seconds - minutes * 60
      if string.len(tostring(seconds)) == 1 then
        seconds = "0" .. tostring(seconds)
      end
      return minutes .. ":" .. seconds
    end,
    EnableScriptEvents = function(self, dsName)
      local ds = DsTable.Find(dsName)
      if ds then
        ds:EnableScriptEvents()
      end
    end,
    DisableScriptEvents = function(self, dsName)
      local ds = DsTable.Find(dsName)
      if ds then
        ds:DisableScriptEvents()
      end
    end,
    InitGameList = function(self, dontForceRefresh)
      Logger:print("lobby.lua", " ### LOBBY InitGameList()")
      self.myMode = 0
      self.selectedGame = nil
      self:RemoveAllPlayers()
      self.paneTop:Invoke("setMode", 0)
      self.paneBottom:Invoke("setTitle", " ")
      self.paneBottom:Invoke("setGameDescription", " ")
      self.paneBottom:Invoke("setJoinText", Ui.GetString("Join!"))
      self.paneBottom:Invoke("setJoinButtonGreen")
      self.paneBottom:Invoke("setJoinButtonDisabled")
      self.paneBottom:Invoke("showCloseButton")
      self.paneBottom:Invoke("hideAllGameOptions")
      self.paneLeft:Invoke("setSpinnerVisibility", "false")
      self.paneBottom:Invoke("setCountdownVisible", 0, "false")
      self.paneTop:Invoke("setGameListData", "", 0)
      self.paneTop:Invoke("setLoadingText", Ui.GetString("RetrievingGameList"), " ", "true")
      if dontForceRefresh == true then
        self:EnableScriptEvents(self.lobbyDS)
        self:EnableScriptEvents(self.gameDS)
        self:DisableScriptEvents(self.groupDS)
      else
        self.paneTop:Invoke("setGameListMode", 0)
      end
    end,
    CreateNewGameSubmit = function(self)
      Logger:print("lobby.lua", "### LOBBY create new game submit")
      local solo = true
      local ds = DsTable.Find(self.groupDS)
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 1 then
          solo = false
        end
      end
      self.justCreatedGame = true
      self.waitingForMyGameInDS = true
      self.myMode = 2
      self:ShowLeftPane()
      self.paneTop:Invoke("setMode", 2)
      self.paneTop:Invoke("setTitleCreated", Ui.GetString("GameCreated"))
      self.paneTop:Invoke("setGameDesc", "Error: Could not fetch game description")
      self.paneBottom:Invoke("setJoinFlashOn")
      self.paneBottom:Invoke("setJoinText", Ui.GetString("START!"))
      self.paneBottom:Invoke("setJoinButtonGreen")
      self.paneBottom:Invoke("setJoinButtonEnabled")
      self.paneBottom:Invoke("setGameDescription", " ")
      self.paneBottom:Invoke("showBackButton")
      self.paneLeft:Invoke("setSpinnerVisibility", "true")
      self:EnableScriptEvents(self.groupDS)
      self:EnableScriptEvents(self.gameDS)
      Ui.CreateNewLobbyGame()
      self:SelectGameYouAreIn()
      if solo then
        self:GroupDataUpdated()
      end
    end,
    SetTopOption = function(self, optionNumber, optionMode, optionName, optionStringID)
      self.paneTop:Invoke("setOptionMode", optionNumber, optionMode, optionName, optionStringID)
    end,
    SetTopOptionValue = function(self, optionNumber, optionSubNumber, optionSubName)
      self.paneTop:Invoke("setOptionValue", optionNumber, optionSubNumber, optionSubName)
    end,
    SetBottomOption = function(self, optionNumber, optionName, optionNameString, optionValue, optionValueIndex)
      local realOptionNumber = self.optionIndexToOptionId[tonumber(optionNumber)]
      local dsName = "BaseClient.LobbyGameOption" .. tostring(realOptionNumber)
      Logger:print("lobby.lua", "### LOBBY setting bottom option # " .. dsName .. " mode(" .. tostring(optionName) .. ") to " .. tostring(optionValue) .. ", " .. tostring(optionValueIndex))
      if optionName and optionName ~= "GameId" and optionName ~= "Required Profile Type" and optionName ~= "Encounter" and optionName ~= "Track" then
        self.paneBottom:Invoke("setGameOption", optionNumber, optionNameString, optionValue)
      end
      Ui.SubmitLobbyGameOptions(1, dsName, tonumber(optionValueIndex))
      self.myGameOptionsValues[tostring(optionName)] = tostring(optionValue)
      self.myGameOptions[tostring(optionName)] = tostring(optionNameString)
      if self.myMode == 1 then
        local myTitle = self:ConstructGameName()
        if myTitle then
          self.paneBottom:Invoke("setTitle", myTitle)
        end
      end
      if optionName == "Max Players" then
        self.maxPlayersInGame = tonumber(optionValue)
      end
    end,
    CreateNewGameStart = function(self)
      Logger:print("lobby.lua", "### LOBBY create new game start")
      self:DisableScriptEvents(self.lobbyDS)
      self:DisableScriptEvents(self.groupDS)
      if self.myMode == 3 or self.myMode == 4 then
        self:LeaveGame(true)
      end
      self.myMode = 1
      self.paneBottom:Invoke("setTitle", Ui.GetString("My New Game"))
      self.paneBottom:Invoke("setJoinFlashOn")
      self.paneBottom:Invoke("setJoinText", Ui.GetString("Create!"))
      self.paneBottom:Invoke("setJoinButtonGreen")
      self.paneBottom:Invoke("setJoinButtonEnabled")
      self.paneBottom:Invoke("showBackButton")
      self.optionIndexToOptionId = {}
      self.myGameOptions = {}
      self.myGameOptionsValues = {}
      self.maxPlayersInGame = 0
      self.paneBottom:Invoke("hideAllGameOptions")
      local skippedOptions = 0
      local gotOptions = 0
      for n = 0, 7 do
        nn = n - skippedOptions
        self.optionIndexToOptionId[nn] = n
        local dsName = "BaseClient.LobbyGameOption" .. tostring(n)
        local ds = DsTable.Find(dsName)
        if ds then
          local colName = ds:GetColumnName(0)
          local rows = ds:GetRowCount()
          local isConfig = ""
          if rows > 0 then
            gotOptions = 1
            local stringID = ds:GetData(0, 3)
            if rows == 1 then
              skippedOptions = skippedOptions + 1
              break
            elseif rows == 2 then
              if ds:GetData(0, 0) == "Yes" and ds:GetData(1, 0) == "No" then
                self:SetTopOption(nn, 1, colName, stringID)
                if ds:GetData(0, 2) == "1" then
                  self.paneTop:Invoke("setDefaultOption", nn, "Yes")
                else
                  self.paneTop:Invoke("setDefaultOption", nn, "No")
                end
              else
                self:SetTopOption(nn, 2, colName, stringID)
                self:SetTopOptionValue(nn, 0, ds:GetData(0, 0))
                self:SetTopOptionValue(nn, 1, ds:GetData(1, 0))
                if ds:GetData(0, 2) == "1" then
                  local defaultOption = ds:GetData(0, 0)
                  self.paneTop:Invoke("setDefaultOption", nn, defaultOption)
                else
                  local defaultOption = ds:GetData(1, 0)
                  self.paneTop:Invoke("setDefaultOption", nn, defaultOption)
                end
              end
            else
              self:SetTopOption(nn, 0, colName, stringID)
              local defaultOption
              for i = 0, rows - 1 do
                local optionValue = ds:GetData(i, 0)
                if ds:GetData(i, 2) == "1" then
                  defaultOption = tostring(optionValue)
                end
                self:SetTopOptionValue(nn, i, tostring(optionValue))
              end
              self.paneTop:Invoke("setDefaultOption", nn, defaultOption)
            end
          end
        end
      end
      if gotOptions == 0 then
        self:LeaveGame()
        self:Hide()
      end
    end,
    OnUserEvent = function(self, a, b, c, d, e, f)
      if a ~= "playSound" then
      end
      if a == "playSound" or a == "PlaySound" then
        if b == "ButtonPress" then
          HUD:PlaySound("ButtonPress")
        elseif b == "ButtonOver" then
          HUD:PlaySound("ButtonOver")
        elseif b == "DockOver" then
        elseif b == "MenuFlip" then
          HUD:PlaySound("MenuDown")
        elseif b == "FlipBack" then
          HUD:PlaySound("FlipBack")
        elseif b == "countdown" then
          HUD:PlaySound("CountdownBeep")
        elseif b == "countdown1SecondLeft" then
          HUD:PlaySound("CountdownBeep")
        elseif b == "countdownGO" then
          HUD:PlaySound("CountdownGo")
        else
          Logger:print("lobby.lua", "UNKNOWN SOUND! " .. b)
        end
      elseif a == "requestData" then
        if self.matchmaking then
          self:QueuesPopulate(tonumber(b), tonumber(c))
        else
          self:LobbyGameListPopulate(tonumber(b), tonumber(c))
        end
      elseif a == "selectedGame" then
        if self.matchmaking then
          self:SelectedQueue(b, c)
        else
          self:SelectedGame(b, c)
        end
      elseif a == "quickMatchSolo" then
        self:EnterQueue()
        if ActivityPortal.isShown and Context:GetCurrent() == QuestHandler.CONTEXT_HIDE then
          ActivityPortal:Enable(true)
          Context:Pop()
        end
      elseif a == "quickMatchMulti" then
        self:JoinQueueMulti()
        self.wTop:SetProperty("Legend", 10)
      elseif a == "close" or a == "ExitButtonClicked" then
        Logger:print("lobby.lua", "ExitButtonClicked!")
        self.wTop:SetProperty("Legend", 35)
        if ActivityPortal.isShown then
          QuestHandler:OnCloseLobby()
          return
        end
        self.paneLeft:Invoke("toolTipOnClip", -1)
        FriendPicker:Hide()
        if self.myMode == 0 then
          self:Hide()
        elseif self.myMode == 1 then
          self:InitGameList()
        elseif self.myMode == 2 then
          self:LeaveGame()
        elseif self.myMode == 3 then
          self:LeaveGame()
        elseif self.myMode == 5 then
          self:Hide()
        elseif self.myMode == 6 then
          self.paneLeft:Invoke("toolTipOnClip", -1)
          FriendPicker:Hide()
          self:JoinQueueWithID(self.currentQueueID)
        elseif self.myMode == 7 then
          self:Hide()
        end
        NavigationHandler:EnableBar()
      elseif a == "backToList" then
        self:InitGameList()
      elseif a == "backToQueues" then
        self.paneLeft:Invoke("toolTipOnClip", -1)
        FriendPicker:Hide()
        self:JoinQueueWithID(self.currentQueueID)
      elseif a == "createNewGame" then
        self:CreateNewGameStart()
      elseif a == "buttonJoinPressed" then
        self.wTop:SetProperty("Legend", 35)
        self.paneLeft:Invoke("toolTipOnClip", -1)
        FriendPicker:Hide()
        if self.myMode == 0 then
          self:JoinGame()
        elseif self.myMode == 1 then
          self:CreateNewGameSubmit()
        elseif self.myMode == 2 then
          self:StartGame()
        elseif self.myMode == 3 then
          self:LeaveGame()
        elseif self.myMode == 5 then
          self:JoinQueue()
        elseif self.myMode == 6 then
          self:EnterQueue()
        end
        if ActivityPortal.isShown and Context:GetCurrent() == QuestHandler.CONTEXT_HIDE then
          ActivityPortal:Enable(true)
          Context:Pop()
        end
      elseif a == "optionValue" then
        Logger:print("lobby.lua", "got option value for # " .. tostring(b) .. " || " .. tostring(c) .. " || " .. tostring(d) .. " || " .. tostring(e) .. " || " .. tostring(f))
        self:SetBottomOption(b, self.stringMap[tonumber(c)], d, e, f)
      elseif a == "invitePlayerStart" then
        self:StartInviteOnSlot(b)
      else
        Logger:print("lobby.lua", "UNKNOWN LOBBY EVENT: " .. a .. ": " .. b)
      end
    end
  }
  function Main_wndLobbyLeft_swfLobbyLeft_OnUserEvent(a, b, c, d, e, f)
    Lobby:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndLobbyLeftSoccer_swfLobbyLeftSoccer_OnUserEvent(a, b, c, d, e, f)
    Lobby:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndLobbyTop_swfLobbyTop_OnUserEvent(a, b, c, d, e, f)
    Lobby:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndQuickTop_swfQuickTop_OnUserEvent(a, b, c, d, e, f)
    Lobby:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndLobbyBottom_swfLobbyBottom_OnUserEvent(a, b, c, d, e, f)
    Lobby:OnUserEvent(a, b, c, d, e, f)
  end
end)()
