    movieDemoScore = Ui.GetName("Main.wndFlashScore.swfScore"),
    windowDemoCar = Ui.GetName("Main.wndTutorialDemoDerbCar"),
    swfTutorialDemoDerbCar = Ui.GetName("Main.wndTutorialDemoDerbCar.swfTutorialDemoDerbCar"),
    windowRaceMap = Ui.GetName("Main.wndRaceMiniMap"),
    movieRaceMap = Ui.GetName("Main.wndRaceMiniMap.swfRaceMiniMap"),
    doNotRepeatDDTut2 = false,
    MODE_BASIC = 1,
    MODE_ADVANCED = 2,
    m_CurrentMode = nil,
    m_CurrentPage = -1,
    StartRacingBasics = function(self)
      Ui.OnVehicleTutorialOpened()
      self:Show(self.MODE_BASIC)
    end,
    StartRacingAdvanced = function(self)
      Ui.OnVehicleTutorialOpened()
      self:Show(self.MODE_ADVANCED)
    end,
    Show = function(self, mode)
      local data
      if mode == self.MODE_BASIC then
        self.OnChangePageTutorialDialog = self.ChangeBasicPage
        data = self.GetBasicTutorial()
        PS3_tutorial:Show()
        PS3_tutorial:populateTutorial(10)
      elseif mode == self.MODE_ADVANCED then
        self.OnChangePageTutorialDialog = self.ChangeAdvancedPage
        data = self.GetAdvancedTutorial()
        local theWindow = Window.Find(self.windowName)
        local w, h = theWindow:GetSize()
        local sw, sh = Window.GetCanvasSize()
        TutorialDialog:Connect(self)
        TutorialDialog:Show(sw / 2 - w / 2, 60, true)
        TutorialDialog:SetData(data)
      else
        return
      end
      self.m_CurrentMode = mode
      self.OnHideTutorialDialog = self.Hide
      NonModalContext:AddContext(self)
      Ui.OnVehicleTutorialOpened()
    end,
    OnResize = function(self)
      if self.m_CurrentMode == self.MODE_BASIC then
        self:CenterControls()
      end
    end,
    Hide = function(self)
      self.m_CurrentPage = -1
      self.m_CurrentMode = nil
      PS3_tutorial:Hide()
      Tutorial:HideArrow()
      TutorialMouse:Hide()
      TutorialKeys:Hide()
      self:StopRaceBoost()
      self:RestoreRacingUi()
      GroupHandler:ModeSwitch(3)
      GroupHandler.Mode = 3
      GroupHandler:ActivateEncounterRequest(" ", 1)
      GroupHandler:EncounterButtonModeSwitch(1)
      NonModalContext:RemoveContext(self)
      Ui.OnVehicleTutorialClosed()
    end,
    HideOnExit = function(self)
      self.m_CurrentPage = -1
      self.m_CurrentMode = nil
      PS3_tutorial:Hide(true)
      Tutorial:HideArrow()
      TutorialMouse:Hide()
      TutorialKeys:Hide()
      self:StopRaceBoost()
      TutorialDialog:Disconnect(self)
      TutorialDialog:Hide()
      GroupHandler:ModeSwitch(3)
      GroupHandler.Mode = 3
      GroupHandler:ActivateEncounterRequest(" ", 1)
      GroupHandler:EncounterButtonModeSwitch(1)
      NonModalContext:RemoveContext(self)
    end,
    GetBasicTutorial = function()
      return Ui.GetString("Racing1")
    end,
    ChangeBasicPage = function(self, page)
      if self.m_CurrentPage ~= page and page == 1 then
        RaceItemSlots:Hide()
        Tutorial:HideArrow()
        self:CenterControls()
      end
      self.m_CurrentPage = page
    end,
    GetAdvancedTutorial = function()
      local tutTbl = {}
      local page1 = {
        message1 = Ui.GetString("RacingAdvanced1_PS3")
      }
      local page2 = {
        message1 = Ui.GetString("RacingAdvanced2")
      }
      local page3 = {
        message1 = Ui.GetString("RacingAdvanced3")
      }
      local page4 = {
        message1 = Ui.GetString("RacingAdvanced4")
      }
      local page5 = {
        message1 = Ui.GetString("RacingAdvanced5")
      }
      local page6 = {
        message1 = Ui.GetString("RacingAdvanced6")
      }
      table.insert(tutTbl, page1)
      table.insert(tutTbl, page2)
      table.insert(tutTbl, page3)
      table.insert(tutTbl, page4)
      table.insert(tutTbl, page5)
      table.insert(tutTbl, page6)
      return tutTbl
    end,
    ChangeAdvancedPage = function(self, page)
      if self.m_CurrentPage ~= page then
        local sw, sh = Window.GetCanvasSize()
        local km = GfxCtrl.Find(Tutorial.swfTutorialWasd)
        local raceInventory = Window.Find(self.windowName)
        local racX, racY = raceInventory:GetPosition()
        local racWidth, racHeight = raceInventory:GetSize()
        local racArrowYPos = racY + racHeight - 75
        if page == 1 then
          RaceItemSlots:Show()
          Tutorial:ShowArrow(racX + 90, racArrowYPos, 90)
        elseif page == 2 then
          RaceItemSlots:Show()
          RaceItemSlots:AddItem(1)
        elseif page == 3 then
          RaceItemSlots:Show()
          RaceItemSlots:AddItem(3)
        elseif page == 4 then
          RaceItemSlots:Show()
          RaceItemSlots:AddItem(4)
        elseif page == 5 then
          RaceItemSlots:Show()
          self:StopRaceBoost()
          RaceItemSlots:AddItem(5)
          Tutorial:ShowArrow(racX + 90, racArrowYPos, 90)
        elseif page == 6 then
          RaceItemSlots:Show()
          self:StartRaceBoost()
          TutorialMouse:StartMove()
          Tutorial:ShowArrow(racX + 90, racArrowYPos + 60, 90)
        end
      end
      self.m_CurrentPage = page
    end,
    StartDemoDerbBasics = function(self)
      self.DemoDerbTut1Active = true
      DemoDerbyTutorial:Show(DemoDerbyTutorial.MODE_BASIC)
    end,
    StartDemoDerbAdvanced = function(self)
      self.DemoDerbTut2Active = true
      DemoDerbyTutorial:Show(DemoDerbyTutorial.MODE_ADVANCED)
    end,
    CenterControls = function(self)
      local sw, sh = Window.GetCanvasSize()
      local width, height = TutorialMouse.GetWindow():GetSize()
      local mod = -50
      if sw < 1280 then
        mod = -200
      end
      TutorialMouse:Move(sw - width - 15, sh / 2 - height / 2 + mod)
      local kw = Window.Find(Tutorial.wndTutorialWasd)
      local width2, height2 = TutorialKeys.GetWindow(TutorialKeys.CHILD_WASD):GetSize()
      mod = 125
      if sw > 1280 then
        mod = 250
      end
      TutorialKeys:Move(TutorialKeys.CHILD_WASD, sw - width + 25, sh / 2 - height2 / 2 + mod)
      local width4, height4 = TutorialKeys.GetWindow(TutorialKeys.CHILD_CTRL):GetSize()
      TutorialKeys:Move(TutorialKeys.CHILD_CTRL, 100, sh * 0.5 - height2 * 0.5 + 310)
      local width3, height3 = TutorialKeys.GetWindow(TutorialKeys.CHILD_SPACE):GetSize()
      TutorialKeys:Move(TutorialKeys.CHILD_SPACE, sw * 0.5 - width * 0.5, sh * 0.5 - height2 * 0.5 + 300)
    end,
    StartRaceBoost = function(self)
      if UpdateList.RacingTutorial_RaceBoost == nil then
        UpdateList.RacingTutorial_RaceBoost = {}
        UpdateList.RacingTutorial_RaceBoost.currentBoost = 0
        UpdateList.RacingTutorial_RaceBoost.maxBoost = 100
        UpdateList.RacingTutorial_RaceBoost.boostMod = 0.6
        UpdateList.RacingTutorial_RaceBoost.Update = self.RaceBoostUpdate
      end
    end,
    SetBoostMod = function(self, value)
      if type(value) == "number" and UpdateList.RacingTutorial_RaceBoost ~= nil then
        UpdateList.RacingTutorial_RaceBoost.boostMod = value
      end
    end,
    RaceBoostUpdate = function(self)
      if self.currentBoost >= self.maxBoost then
        self.currentBoost = 0
        RaceItemSlots:Show()
        RaceItemSlots:AddItem(5)
      else
        self.currentBoost = self.currentBoost + self.boostMod
      end
      RaceBoostBar:SetBoost(self.currentBoost)
    end,
    StopRaceBoost = function(self)
      UpdateList.RacingTutorial_RaceBoost = nil
      RaceBoostBar:SetBoost(0)
    end,
    RestoreRacingUi = function(self)
      DemoScore:Hide()
      DemoHealthBar:Hide()
      RaceItemSlots:Show()
      RaceMiniMap:Show()
    end,
    RestoreDemoDerbUi = function(self)
      RaceItemSlots:Hide()
      DemoScore:Show()
      DemoHealthBar:Show()
      DemoHealthBar:SetHealthandBoost(100, 100)
    end,
    RestartRacingTutorial = function(self, progress)
      self:Show(self.MODE_BASIC)
    end,
    RestartDemoDerbTutorial = function(self, progress)
      self.doNotRepeatDDTut2 = false
      DemoDerbyTutorial:Show(DemoDerbyTutorial.MODE_BASIC)
    end
  }
end)()
