;(function()
  HudWindowManager = {
    sidePanelStartY = 200,
    SideWindows = {
      PetController,
      SocialHandler,
      QuestHelper
    },
    ShowSidePanels = function(self)
      Logger:print("HudWindowManager.lua", "ShowSidePanels QuestHelper:GetIsShown; " .. QuestHelper:GetIsShown())
      if QuestHelper:GetIsShown() ~= 1 then
        QuestHelper:ShowHelper()
      end
      if PetController:GetIsShown() ~= 1 then
        PetController:Show()
      end
      if SocialHandler:GetIsShown() ~= 1 then
        SocialHandler:Show()
      end
    end,
    HideSidePanels = function(self)
      if QuestHelper:GetIsShown() == 1 then
        QuestHelper:HideHelper()
      end
      if PetController:GetIsShown() == 1 then
        PetController:Hide()
      end
      if SocialHandler:GetIsShown() == 1 then
        SocialHandler:Hide()
      end
    end,
    OnShowWindow = function(self, window)
      if PetTutorial.enabled == true then
        return
      end
      self:checkSizeAndMinimize(window)
      self:redoYs()
    end,
    OnHideWindow = function(self, window)
      self:redoYs()
    end,
    OnMinimizeWindow = function(self, window)
      self:redoYs()
    end,
    OnMaximizeWindow = function(self, window)
      self:checkSizeAndMinimize(window)
      self:redoYs()
    end,
    OnResizeWindow = function(self, window)
      self:checkSizeAndMinimize(window)
      self:redoYs()
    end,
    checkSizeAndMinimize = function(self, window)
      local totalHeight = self:getTotalHeight()
      local screenW, screenH = Window.GetCanvasSize()
      if totalHeight > screenH then
        for i, v in ipairs(self.SideWindows) do
          if v:GetIsShown() == 1 and v ~= window then
            v:SetMinimized()
          end
        end
      end
      totalHeight = self:getTotalHeight()
      local difference = totalHeight - screenH
      local newHeight = window:GetHeight() - difference
      window:SetHeight(newHeight)
    end,
    redoYs = function(self)
      local runningY = self.sidePanelStartY
      for i, v in ipairs(self.SideWindows) do
        if v:GetIsShown() == 1 then
          v:SetY(runningY)
          runningY = runningY + v:GetHeight()
        end
      end
    end,
    getTotalHeight = function(self)
      local totalHeight = self.sidePanelStartY
      for i, v in ipairs(self.SideWindows) do
        if v:GetIsShown() == 1 then
          totalHeight = totalHeight + v:GetHeight()
        end
      end
      return totalHeight + 40
    end
  }
end)()
;(function()
  InteractionPrompt = {
    windowName = Ui.GetName("Main.wndInteractionPrompt"),
    swfName = Ui.GetName("Main.wndInteractionPrompt.swfInteractionPrompt"),
    isUp = false,
    lockMovement = false,
    isTweeningOut = false,
    Show = function(self, npcName)
      if tonumber(Options:CheckStoredOption("InteractionPrompt", "Shown", 1)) == 1 and Ui.GetInteractionEnabled() then
        NonModalContext:AddContext(self)
        if not self.lockMovement and not self.isUp then
          self.isUp = true
          self.lockMovement = true
          self:Display()
        end
        if self.isTweeningOut == true then
          self.isTweeningOut = false
          self:Display()
        end
        local swf = GfxCtrl.Find("Main.wndInteractionPrompt.swfInteractionPrompt")
        swf:Invoke("ResetTimer")
        swf:Invoke("SetName", npcName)
        swf:Invoke("SetKeyName", KeyBinds:GetInteractionKeyValueName())
      elseif self.isUp then
        self:Hide()
      end
    end,
    Display = function(self)
      local window = Window.Find(self.windowName)
      local w, h = window:GetSize()
      local sw, sh = Window.GetCanvasSize()
      window:SetPosition(sw / 2 - w / 2, sh)
      window:Show()
      local baseY = 210
      if Housing.isInInstance and Housing.allowEdit then
        if Housing.editMode then
          baseY = baseY + 150
        else
          baseY = baseY + 50
        end
      end
      WindowTweener:Create("Main.wndInteractionPrompt", "Y", nil, sh - baseY, 0.3)
    end,
    OnResize = function(self)
      self:Update()
    end,
    Hide = function(self)
      if not self.lockMovement then
        do
          local window = Window.Find(self.windowName)
          local sw, sh = Window.GetCanvasSize()
          self.isTweeningOut = true
          WindowTweener:Create("Main.wndInteractionPrompt", "Y", nil, sh + 50, 0.3, function()
            self.isUp = false
            window:Hide()
            self.isTweeningOut = false
          end)
        end
      end
    end,
    Update = function(self)
      local npcName = tostring(DsTable.Find("BaseClient.ClosestInteractionTargetData"):GetData(0, 0))
      if npcName == "-1" or ScoreScreen.screenShown then
        self:Hide()
      else
        self:Show(npcName)
      end
    end,
    ShowMouseImage = function(self, n)
      local swf = GfxCtrl.Find("Main.wndInteractionPrompt.swfInteractionPrompt")
      swf:Invoke("ShowMouseImage", n)
    end,
    Disable = function(self)
      if self.isUp then
        self:Hide()
      end
      Ui.SetInteractionEnabled(false)
    end,
    Enable = function(self)
      Ui.SetInteractionEnabled(true)
      InteractionPrompt:Update()
    end
  }
  function Main_wndInteractionPrompt_swfInteractionPrompt_OnUserEvent(a, b, c)
    if a == "CloseWindow" then
    elseif a == "timerDing" then
      InteractionPrompt.lockMovement = false
      InteractionPrompt:Update()
    elseif a == "PromptSelected" then
      if Ui.DoClosestInteraction then
        Ui.DoClosestInteraction()
      end
      HUD:PlaySound("DockSelect")
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "ASPrint" then
    end
  end
  function Main_wndInteractionPrompt_swfInteractionPrompt_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
  function BaseClient_ClosestInteractionTargetData_OnDataUpdate()
    InteractionPrompt:Update()
  end
end)()
