;(function()
  CreditsHandler = {
    swfName = "Main.wndCredits.swfCredits",
    wndName = "Main.wndCredits",
    visible = false,
    wndWidth = 0,
    wndHeight = 0,
    Show = function(self)
      local wnd = Window.Find(Ui.GetName(self.wndName))
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      if wnd and self.visible == false then
        local width, height = wnd:GetSize()
        if width > self.wndWidth then
          self.wndWidth = width
        end
        if height > self.wndHeight then
          self.wndHeight = height
        end
        self.visible = true
        Context:Push("Credits", function()
          CreditsHandler:Hide()
        end)
        NonModalContext:AddContext(self)
        MiniGameFlash:Pause()
        wnd:Show()
        self:OnResize()
        swf:Load()
      end
    end,
    OnResize = function(self)
      local wnd = Window.Find(Ui.GetName(self.wndName))
      if wnd then
        local sw, sh = Window.GetCanvasSize()
        wnd:SetProperty("Width", 0)
        wnd:SetProperty("Height", 0)
        wnd:SetPosition(sw / 2, 0)
        WindowTweener:Create(self.wndName, "Width", nil, self.wndWidth, 0.4)
        WindowTweener:Create(self.wndName, "Height", nil, self.wndHeight, 0.4)
        WindowTweener:Create(self.wndName, "X", sw / 2, (sw - self.wndWidth) / 2, 0.4)
        WindowTweener:Create(self.wndName, "Y", 0, (sh - self.wndHeight) / 3, 0.4)
      end
    end,
    Hide = function(self)
      local wnd = Window.Find(Ui.GetName(self.wndName))
      if wnd then
        MiniGameFlash:Resume()
        local sw, sh = Window.GetCanvasSize()
        WindowTweener:Create(self.wndName, "Width", nil, 0, 0.4)
        WindowTweener:Create(self.wndName, "Height", nil, 0, 0.4)
        WindowTweener:Create(self.wndName, "X", (sw - self.wndWidth) / 2, sw / 2, 0.4)
        WindowTweener:Create(self.wndName, "Y", (sh - self.wndHeight) / 3, 0, 0.39, function()
          GfxCtrl.Find(Ui.GetName(CreditsHandler.swfName)):Unload()
          Window.Find(Ui.GetName(CreditsHandler.wndName)):Hide()
        end)
        self.visible = false
        Context:Pop()
        NonModalContext:RemoveContext(self)
      end
    end,
    OnUserEvent = function(a)
      if a == "closeWindow" then
        CreditsHandler:Hide()
        MiniGameFlash:Resume()
      end
    end
  }
  Main_wndCredits_swfCredits_OnUserEvent = CreditsHandler.OnUserEvent
  BindCommandToLua("credits", "CreditsHandler:Show")
end)()
