        VehicleBrowser:Show(self.TYPE_RACING, self.NavigationLabels[self.MODE_RACECAR_BROWSER], true)
        self.LAST_SELECTED_BROWSER = self.MODE_RACECAR_BROWSER
      elseif mode == self.MODE_DEMODERB_BROWSER then
        self:print("ModeSwitch(" .. tostring(mode) .. ", MODE_DEMODERB_BROWSER )")
        VehicleBrowser:Show(self.TYPE_DEMO, self.NavigationLabels[self.MODE_DEMODERB_BROWSER], true)
        self.LAST_SELECTED_BROWSER = self.MODE_DEMODERB_BROWSER
      end
    end,
    RefreshEquipmentPane = function(self)
      if VehicleGarage.CURRENT_MODE == VehicleGarage.MODE_EQUIP and VehicleGarage.visible then
        EquipmentHandler:SelectCategory(1)
      end
    end,
    BrowserOnUserEvent = function(self, a, b)
      if a == "CompressBrowser" then
      elseif a == "SelectVehicle" then
        self:ModeSwitch(0)
      elseif a == "ExpandedBrowser" and self.CURRENT_MODE == self.MODE_EQUIP then
      elseif a == "CloseBrowser" then
        self:ModeSwitch(0)
        VehicleBrowser:Hide()
      end
    end,
    EquipmentPaneOnUserEvent = function(self, a, b, c, d, e)
      if a == "requestData" then
        EquipmentHandler:RequestData(b, c)
      elseif a == "changeSelectedCategory" then
        self:print("changeSelectedCategory: " .. tostring(b))
        EquipmentHandler.selectedSlot = self.AllowedSlots[math.min(tonumber(b), #self.AllowedSlots)]
      elseif a == "equipItem" then
        if b ~= "000000000000000" then
          EquipScreen.EquipVehicleItem(b)
        else
          EquipScreen.RemoveVehicleItem(tonumber(c) - 1)
        end
      elseif a == "changeViewMode" then
        if b == "undefined" then
          return
        end
        EquipmentHandler.currentViewMode = b
        Ui.SetUserOptionsValue("GarageWindowOptions", "LastSelectedViewMode_" .. tostring(self.NavigationLabels[self.CURRENT_MODE]), b)
      elseif a == "PlaySound" then
        HUD:PlaySound(b)
      else
        if a == "CloseWindowPS3" then
          EquipmentHandler:Hide()
          self:ModeSwitch(0)
        else
        end
      end
    end,
    EquipmentPaneOnRequestData = function(self, offset, count)
      if EquipmentHandler.selectedSlot then
        local dsString = tostring(EquipmentHandler.activeDs) .. tostring(EquipmentHandler.selectedSlotMap[tonumber(EquipmentHandler.selectedSlot)])
        if not dsString then
          return
        end
        local ds = DsTable.Find(dsString)
        if ds then
          EquipmentHandler:Populate(offset, count, ds)
        end
      end
    end,
    EquipmentPaneOnPopulate = function(self, offset, count, ds)
      local slotID = EquipmentHandler.selectedSlot
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          count = tonumber(count)
          local offset = math.max(offset, 0)
          if slotID == self.AllowedSlots[5] or slotID == self.AllowedSlots[6] or slotID == self.AllowedSlots[7] then
            if offset == 0 then
              str = EquipmentHandler.BuildNoneItem(slotID)
              count = count - 1
            else
              offset = offset - 1
            end
            numRows = numRows + 1
          end
          local countTo = math.min(offset + count, ds:GetRowCount())
          for i = offset, countTo - 1 do
            str = str .. self.BuildItemString(ds, i)
          end
        elseif slotID == self.AllowedSlots[5] or slotID == self.AllowedSlots[6] or slotID == self.AllowedSlots[7] then
          str = EquipmentHandler.BuildNoneItem(slotID)
        end
        EquipmentHandler:PopulateWindow(str, numRows)
      else
        str = EquipmentHandler.BuildNoneItem(slotID)
        EquipmentHandler:PopulateWindow(str, 1)
      end
    end,
    EquipmentPaneOnSetCurrentEquip = function(self)
      if EquipmentHandler.selectedEquippedDatasource == nil then
        return
      end
      local ds = DsTable.Find(EquipmentHandler.selectedEquippedDatasource)
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 and EquipmentHandler.selectedSlotMapID ~= nil then
          local countTo = EquipmentHandler.selectedSlotMapID + EquipmentHandler.selectedSlotMapCount - 1
          local offset = EquipmentHandler.selectedSlotMapID
          for i = offset, math.min(countTo, numRows - 1) do
            local canEquip = false
            for ii = 1, #self.AllowedSlots do
              if tostring(i) == tostring(self.AllowedSlots[ii] - 1) then
                canEquip = true
              end
            end
            if canEquip then
              str = str .. self.BuildItemString(ds, i)
            end
          end
          EquipmentHandler:PopulateWindowCategories(str, numRows)
        end
      end
      if self.LAST_EQUIPPED_VEHICLE == self.TYPE_DEMO + 8 then
        self:print("disabled")
        EquipmentHandler:EnableCategory(3, false)
        EquipmentHandler:EnableCategory(4, false)
      else
        self:print("enabled")
        EquipmentHandler:EnableCategory(3, true)
        EquipmentHandler:EnableCategory(4, true)
      end
    end,
    BuildItemString = function(ds, row)
      local item = ds:GetData(row, 0)
      local slotColumn = 8
      local isEquippable = 7
      local minRank = 21
      local isConsumable = 16
      for i = 1, ds:GetColumnCount() - 1 do
        if i ~= slotColumn and i ~= isEquippable and i ~= minRank and i ~= isConsmable then
          item = item .. "^" .. ds:GetData(row, i)
        elseif i == isEquippable then
          item = item .. "^" .. "1"
        elseif i == slotColumn then
          item = item .. "^" .. row
        elseif i == minRank then
          item = item .. "^" .. 1
        elseif i == isConsmable then
          item = item .. "^" .. "1"
        end
      end
      item = item .. ";"
      return item
    end,
    SetColumnNames = function(self, tbl)
      local count = #tbl
      local columnsString = tbl[1]
      for i = 2, count do
        columnsString = columnsString .. "^" .. tbl[i]
      end
      return columnsString
    end,
    print = function(self, message)
      if self.debug then
        print("[VehicleGarage]\t" .. message)
      end
    end
  }
end)()
;(function()
  VehicleBrowser = {
    DS_COLUMN_ID = 0,
    DS_COLUMN_NAME = 1,
    DS_COLUMN_DESCRIPTION = 2,
    DS_COLUMN_IMG_SET_ID = 3,
    DS_COLUMN_TINT_VALUE = 4,
    DS_COLUMN_QUANTITY = 5,
    DS_COLUMN_MEMBERS_ONLY = 6,
    DS_COLUMN_ACTIVE = 7,
    debug = false,
    browserHidePos = -400,
    currentGameType = 0,
    categoryMap = {9, 10},
    Populate = function(self, swfName, gameType)
      local swf = GfxCtrl.Find(Ui.GetName(swfName))
      swf:Invoke("SetMode", 5)
      swf:Invoke("hideCloseButton")
      if MiniGameHandler:GetMinigameType() and MiniGameHandler:GetMinigameType() ~= 0 and not VehicleGarage.visible then
        self.currentGameType = MiniGameHandler:GetMinigameType() - 9
      end
      self:print("EquipScreen.SetVehicleTypeFilter( " .. tostring(self.categoryMap[self.currentGameType]) .. ", self.currentGameType = " .. tostring(self.currentGameType) .. " )")
      EquipScreen.SetVehicleTypeFilter(self.currentGameType + 8)
      local ds = DsTable.Find(DataSources[DS_VEHICLE_LOADOUT_LIST])
      local firstItemGuid
      if ds then
        local rows = ds:GetRowCount()
        if rows > 0 then
          for index = 0, rows - 1 do
            local guid = ds:GetData(index, self.DS_COLUMN_ID)
            local icon = ds:GetData(index, self.DS_COLUMN_IMG_SET_ID)
            local name = ds:GetData(index, self.DS_COLUMN_NAME)
            local member = ds:GetData(index, self.DS_COLUMN_MEMBERS_ONLY)
            local active = ds:GetData(index, self.DS_COLUMN_ACTIVE)
            local tint = ds:GetData(index, self.DS_COLUMN_TINT_VALUE)
            swf:Invoke("AddVehicle", guid, icon, name, member, active, tint)
            if index == 0 then
              firstItemGuid = guid
            end
          end
        end
      end
      self:print("Game Type: " .. tostring(self.currentGameType))
      self:print("SelectItem, " .. tostring(Ui.GetActiveVehicleLoadout(self.currentGameType)))
      local selectedVehicle = Ui.GetActiveVehicleLoadout(self.currentGameType)
      if not selectedVehicle or selectedVehicle < 0 or selectedVehicle > 1000 then
        selectedVehicle = firstItemGuid
      end
      swf:Invoke("SelectItem", tostring(selectedVehicle))
      if self.expand then
        self.expand = nil
        self:ShowBrowser()
      end
    end,
    Show = function(self, gameType, title, expand)
      Logger:print("vehiclebrowser.lua", "showing browser")
      self:print(":Show( gameType: " .. tostring(gameType) .. ", title: " .. tostring(title) .. ", expand: " .. tostring(expand))
      NonModalContext:AddContext(self)
      BrowserHandler.windowName = "Vehicles"
      title = title or VehicleGarage.NavigationLabels[gameType + 1]
      if tonumber(gameType) > 8 then
        gameType = gameType - 9
      end
      self:print("GameType: " .. tostring(gameType))
      self.currentGameType = gameType
      self.expand = expand
      BrowserHandler:Show(VehicleBrowser, title, Ui.GetString("UI_Browser_Cartsubtext"), Ui.GetString("UI_Browser_ClickSwitchCarts"))
      BrowserHandler:Connect(self)
    end,
    CloseBrowser = function(self)
      BrowserHandler:CompressBrowser()
    end,
    ShowBrowser = function(self)
      BrowserHandler:ExpandBrowser()
    end,
    Hide = function(self)
      NonModalContext:RemoveContext(self)
      BrowserHandler:Hide(0, 1)
      self.currentGameType = 0
      BrowserHandler:Disconnect(self)
    end,
    GetRowCount = function(self, vehicleType)
      self:print("GetRowCount( " .. tostring(self.categoryMap[vehicleType]) .. " )")
      EquipScreen.SetVehicleTypeFilter(self.categoryMap[vehicleType])
      local ds = DsTable.Find(DataSources[DS_VEHICLE_LOADOUT_LIST])
      local rowCount = 0
      if ds then
        rowCount = ds:GetRowCount()
      end
      return rowCount
    end,
    BrowserOnUserEvent = function(self, a, b)
      self:CallDelegate("BrowserOnUserEvent", a, b)
      if a == "SelectVehicle" then
        self:print("GameType: " .. tostring(self.currentGameType) .. ", Select Vehicle: " .. tostring(b) .. ", Param Type: " .. tostring(type(b)))
        EquipScreen.SelectVehicle(self.currentGameType, b)
        VehicleGarage.LAST_EQUIPPED_VEHICLE = self.currentGameType + 8
        VehicleBrowser:Hide()
      elseif a == "CloseBrowser" then
        VehicleBrowser:Hide()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[VehicleBrowser]\t" .. tostring(message))
      end
    end
  }
  Delegate:AddSupportToClassObject(VehicleBrowser, "VehicleBrowser")
end)()
