      if MiniGameHandler.m_Mode == nil then
        return
      end
      MiniMap:Show()
      HUD:showMinigame()
      GameDock:Show()
      HotKeyEvents.override = false
    end,
    ClickedAbility = function(self, id)
      if self.underwater == false then
        Logger:print("Fishing.lua", " ### ClickedAbility(" .. tostring(id) .. ")")
        GraphicActionBar:setTimer(id, 500, 0)
        if id == 0 then
          FishFinder.myTab = "Fish"
        elseif id == 1 then
          FishFinder.myTab = "Lures"
        elseif id == 2 then
          FishFinder.myTab = "Rewards"
        end
        FishFinder:DataUpdated()
        FishFinder:Show()
      end
    end
  }
  FishFinder = {
    swf = Ui.GetName("Main.wndFishFinder.swfFishFinder"),
    wnd = Ui.GetName("Main.wndFishFinder"),
    fishDS = "BaseClient.FishingProcessor.FishTypes",
    luresDS = "BaseClient.FishingProcessor.FishingLures",
    rewardsDS = "BaseClient.FishingProcessor.FishScored",
    isShown = false,
    pane = nil,
    win = nil,
    curX = 0,
    curY = -500,
    numItems = 0,
    myTab = nil,
    usingLure = false,
    currentLure = nil,
    Show = function(self, showFlag)
      if self.isShown == true then
        self.pane:Invoke("bigWindowShow")
        return
      end
      self.isShown = true
      Logger:print("FishFinder.lua", " ### FishFinder Show()")
      NonModalContext:AddContext(self)
      self.pane = GfxCtrl.Find(self.swf)
      self.pane:Reset()
      self.pane:SetLimitAdvance(true)
      self:OnResize()
      if self.myTab == nil then
        self.myTab = "Fish"
      end
      self:DataUpdated()
    end,
    Hide = function(self)
      if self.pane == nil then
        return
      end
      self.isShown = false
      Logger:print("FishFinder.lua", " ### FishFinder Hide()")
      NonModalContext:RemoveContext(self)
      self.pane:Unload()
      Window.Find(Ui.GetName("Main.wndFishFinder")):Hide()
    end,
    OnResize = function(self)
      Logger:print("FishFinder.lua", " ### FishFinder OnResize()")
      self.win = Window.Find(self.wnd)
      local w, h = self.win:GetSize()
      local sw, sh = Window.GetCanvasSize()
      self.win:Show()
      self.curX = sw / 2 - w
      self.curY = sh - h + 75
      self.win:SetPosition(self.curX, self.curY)
    end,
    DataUpdated = function(self)
      Logger:print("FishFinder.lua", " ### FishFinder DataUpdated()")
      if self.currentLure ~= nil or self.usingLure == true then
        return
      end
      if self.isShown == false then
        return
      end
      self.pane:Invoke("clearItems")
      self.numItems = 0
      local dataType = 1
      local myDS = self.fishDS
      if self.myTab == "Lures" then
        self.pane:Invoke("setTitle", Ui.GetString("FishFinderTackle"), Ui.GetString("FishFinderTackleDesc"), Ui.GetString("FishFinderLevelUp"))
        myDS = self.luresDS
        dataType = 2
      elseif self.myTab == "Rewards" then
        self.pane:Invoke("setTitle", Ui.GetString("FishFinderRewards"), Ui.GetString("FishFinderRewardsDesc"), Ui.GetString("FishFinderLevelUp"))
        myDS = self.rewardsDS
        dataType = 3
      else
        self.pane:Invoke("setTitle", Ui.GetString("FishFinderFish"), Ui.GetString("FishFinderFishDesc"), Ui.GetString("FishFinderLevelUp"))
      end
      local ds = DsTable.Find(myDS)
      Logger:print("FishFinder.lua", "DataUpdated: " .. tostring(myDS))
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          local name, id, desc, quantity, iconID, guid
          local fishCatchable = 1
          if myDS == self.fishDS then
            name = tostring(ds:GetData(i, 1))
            id = tostring(ds:GetData(i, 0))
            guid = id
            iconID = tostring(ds:GetData(i, 2))
            fishCatchable = tostring(ds:GetData(i, 4))
            desc = tostring(ds:GetData(i, 5))
          elseif myDS == self.luresDS then
            name = tostring(ds:GetData(i, 2))
            guid = tostring(ds:GetData(i, 0))
            id = tostring(ds:GetData(i, 23))
            desc = tostring(ds:GetData(i, 3))
            quantity = tostring(ds:GetData(i, 4))
            iconID = tostring(ds:GetData(i, 1))
          elseif myDS == self.rewardsDS then
            name = tostring(ds:GetData(i, 0))
            id = tostring(ds:GetData(i, 1))
            iconID = tostring(ds:GetData(i, 1))
            guid = id
          end
          if name and id and tostring(name) ~= "-1" then
            self.numItems = self.numItems + 1
            self.pane:Invoke("addLineItem", dataType, name, "GUID" .. tostring(id), desc, quantity, iconID, "GUID" .. tostring(guid), fishCatchable)
          end
        end
      end
      if self.numItems == 0 then
        self.pane:Invoke("addLineItem", dataType, Ui.GetString("FishFinderEmpty"), "GUID-1", Ui.GetString("FishFinderEmpty"), -1, 4257, "GUID-1")
      end
      self:Show()
    end,
    LureEquipped = function(self)
      if self.currentLure ~= nil then
        print("FISHING assign lure to action bar")
        Ui.AssignToItemActionBar(0, self.currentLure)
        self.currentLure = nil
      else
        print("FISHING cliking ability 0, 2")
        self.usingLure = false
        Ui.ClickedAbility(0, 2)
      end
    end,
    OnUserEvent = function(self, a, b, c, d, e, f)
      Logger:print("FishFinder.lua", " ### FishFinder OnUserEvent() a(" .. tostring(a) .. ") b(" .. tostring(b) .. ") c(" .. tostring(c) .. ")")
      if tostring(a) == "playSound" then
        Lobby:OnUserEvent(a, b)
      elseif tostring(a) == "FishClick" then
        local type = tonumber(b)
        local fishID = string.sub(tostring(c), 5, -1)
        if fishID == "-1" then
          return
        end
        if type == 1 then
          print("Ui.FindSelectedFish(" .. fishID .. ")")
          Ui.FindSelectedFish(fishID)
        elseif type == 2 then
          QuickItem:Populate(0)
          self.usingLure = true
          self.currentLure = fishID
          print("FISHING assigning item to action bar (" .. fishID .. ") QuickItem.firstSlotPopulated(" .. tostring(QuickItem.firstSlotPopulated) .. ")")
          if QuickItem.firstSlotPopulated == true then
            Ui.AssignToItemActionBar(0, 0)
          else
            Ui.AssignToItemActionBar(0, self.currentLure)
            self.currentLure = nil
          end
        end
        self.isShown = false
        self.pane:Invoke("bigWindowHide")
      elseif tostring(a) == "tabSwitch" then
        self.myTab = tostring(b)
        self:DataUpdated()
      elseif tostring(a) == "WindowHide" then
        self:Hide()
      end
    end
  }
  function Main_wndFishFinder_swfFishFinder_OnUserEvent(a, b, c, d, e, f)
    FishFinder:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndFishFinder_swfFishFinder_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
