    end,
    Show = function(self, profileID, stringMappingID1, stringMappingID2)
      self:print("Show( " .. tostring(profileID) .. ", " .. tostring(stringMappingID1) .. ", " .. tostring(stringMappingID2) .. " )")
      self.jobSpecificM1 = stringMappingID1
      self.jobSpecificM2 = stringMappingID2
      NonModalContext:AddContext(self)
      Context:Push(self.CONTEXT_NAME, function()
        self:print("Context Locked")
      end)
      self.GetWindow():Show()
      self.GetSwf():Invoke("setDebug", tostring(self.debug))
      self:SetStrings(DsTable.Find(DataSources[DS_EXPIRED_JOB]):GetRowCount() > 0)
      local bundleId = -1
      local data = ""
      local profileName = JobBrowser.GetProfileData(profileID, ProfileDsColumns.Name)
      local profileIcon = JobBrowser.GetProfileData(profileID, ProfileDsColumns.Icon)
      data = data .. "ProfileName%%" .. profileName .. "|"
      data = data .. "ProfileIcon%%" .. profileIcon .. "|"
      data = data .. "ProfileId%%" .. profileID .. "|"
      if DsTable.Find(DataSources[DS_EXPIRED_JOB]):GetRowCount() > 0 then
        data = data .. DataSourceMethods:ParseDs(DataSources[DS_EXPIRED_JOB], "~~", "|", "%%")
        local ds = DsTable.Find(DataSources[DS_EXPIRED_JOB])
        if ds:GetColumnCount() > 5 then
          bundleId = ds:GetData(0, 5)
        end
      end
      self.GetSwf():Invoke("JobTrialWindow.show", data)
      Ui.IncrementClientLuaMetric("LLNag_show_" .. tostring(profileID) .. "_" .. tostring(bundleId))
      self.visible = true
      self:OnResize()
      self.GameDockState = GameDock:GetState()
    end,
    OnResize = function(self)
      local ww, wh = self.GetWindow():GetSize()
      if self.height then
        wh = self.height
      end
      local sw, sh = Window.GetCanvasSize()
      if ww then
        WindowTweener:Create(self.wndName, "X", nil, sw / 2 - ww / 2, 0.3)
      end
      if wh then
        WindowTweener:Create(self.wndName, "Y", nil, sh / 2 - wh / 2, 0.3)
      end
      Tutorial:GobblerHide()
      Tutorial:GobblerShow()
    end,
    Hide = function(self, mode)
      self:print("Hide( " .. tostring(mode) .. " )")
      local bundleId = -1
      local ds = DsTable.Find(DataSources[DS_EXPIRED_JOB])
      if ds:GetRowCount() > 0 and ds:GetColumnCount() > 5 then
        bundleId = ds:GetData(0, 5)
      end
      local accepted = 0
      if mode == 2 then
        accepted = 1
      end
      Ui.IncrementClientLuaMetric("LLNag_hide_" .. tostring(profileID) .. "_" .. tostring(bundleId) .. "_" .. tostring(accepted))
      NonModalContext:RemoveContext(self)
      Tutorial:GobblerHide()
      self.GetSwf():Unload()
      self.GetWindow():Hide()
      self.visible = false
      self.jobSpecificM1 = nil
      self.jobSpecificM2 = nil
      Ui.SetKeyboardEnabled(1)
      Ui.SetMovementEnabled(1)
      self.GameDockState = nil
      if Context:IsCurrent(self.CONTEXT_NAME) then
        Context:Pop()
      end
      if mode == 2 then
        MembershipHandler:Show()
      end
    end,
    SetHeight = function(self, height)
      self.height = height
      self:OnResize()
    end,
    SetJobSpecific = function(self, enabled)
      if not self.visible then
        return
      end
      self.m_JobSpecific = tonumber(enabled)
      self:SetStrings()
    end,
    SetStrings = function(self, specific)
      local STRING_CONTAINS = Ui.GetString("welcome_label_contains")
      local STRING_CONTAINS_INDEX = 0
      local STRING_UPGRADE = Ui.GetString("JobTrialExpiredUIBuyMembership")
      local STRING_UPGRADE_INDEX = 1
      local STRING_MESSAGE1 = Ui.GetString("419579")
      if self.m_JobSpecific == 1 or specific then
        STRING_MESSAGE1 = Ui.GetString(tostring(self.jobSpecificM1))
      end
      local STRING_MESSAGE1_INDEX = 2
      local STRING_MESSAGE2 = Ui.GetString("JobTrialExpiredUIUpgradePackage")
      if self.m_JobSpecific == 1 or specific then
        STRING_MESSAGE2 = Ui.GetString(tostring(self.jobSpecificM2))
      end
      local STRING_MESSAGE2_INDEX = 3
      local STRING_WINTITLE = Ui.GetString("JobTrialExpiredUIBecomeAMember")
      local STRING_WINTITLE_INDEX = 4
      self.GetSwf():Invoke("JobTrialWindow.setString", STRING_CONTAINS_INDEX, STRING_CONTAINS)
      self.GetSwf():Invoke("JobTrialWindow.setString", STRING_UPGRADE_INDEX, STRING_UPGRADE)
      self.GetSwf():Invoke("JobTrialWindow.setString", STRING_MESSAGE1_INDEX, STRING_MESSAGE1)
      self.GetSwf():Invoke("JobTrialWindow.setString", STRING_MESSAGE2_INDEX, STRING_MESSAGE2)
      self.GetSwf():Invoke("JobTrialWindow.setString", STRING_WINTITLE_INDEX, STRING_WINTITLE)
    end,
    OnUserEvent = function(a, b)
      if a == "hide" then
        JobTrialHandler:Hide(tonumber(b))
      elseif a == "PlaySound" or a == "playSound" then
        HUD:PlaySound(b)
      elseif a == "setHeight" then
        JobTrialHandler:SetHeight(tonumber(b))
      elseif a == "AS_Print" then
        JobTrialHandler:print(b)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[JobTrialHandler]\t" .. message)
      end
    end
  }
  Main_wndJobTrialExpired_swfJobTrialExpired_OnUserEvent = JobTrialHandler.OnUserEvent
  Main_wndJobTrialExpired_swfJobTrialExpired_OnFocus = JobTrialHandler.OnFocus
  BindCommandToLua("jobSpecificTrialMessage", "JobTrialHandler:SetJobSpecific")
end)()
;(function()
  BrokerHandler = {
    wndName = "Main.wndBroker",
    swfName = "Main.wndBroker.swfBroker",
    MODE_INVENTORY = 1,
    MODE_MY_ITEMS = 2,
    MODE_SHOPPING = 3,
    DISPLAY_MODE_DEFAULT = 1,
    visible = false,
    mode = 0,
    inputFocus = false,
    debug = false,
    BrokerItemGuidColumn = 28,
    selectedDS = DataSources[DS_BROKER_INVENTORY_ITEMS],
    m_SelectedCategory = 0,
    Dumpds = function(self, ds)
      local data = {
        DS_BROKER_INVENTORY_ITEMS,
        DS_BROKER_MY_ITEMS,
        DS_BROKER_SEARCH_ITEMS,
        DS_BROKER
      }
      if not data[ds] then
        return
      end
      Ui.ProcessChatCommand("/dumpds " .. tostring(DataSources[data[ds]]))
    end,
    Show = function(self)
      self:print("Show()")
      if not self.GetWindow() then
        return
      end
      HUD:ClearContextAndPreservePanes()
      Context:Push("BrokerHandlerHide", function()
        BrokerHandler:Hide()
      end)
      NonModalContext:AddContext(self)
      HUD:PlaySound("ShowWindow")
      local ds = DsTable.Find(DataSources[DS_BROKER_INVENTORY_ITEMS])
      if ds then
        ds:EnableScriptEvents()
      end
      local ds = DsTable.Find(DataSources[DS_BROKER_MY_ITEMS])
      if ds then
        ds:EnableScriptEvents()
      end
      local ds = DsTable.Find(DataSources[DS_BROKER_SEARCH_ITEMS])
      if ds then
        ds:EnableScriptEvents()
      end
      self:BuildNavigation()
      self:SetCategoryTree()
      self.visible = true
      self.GetWindow():Show()
      self:OnResize()
      HUD:hideMain()
      if self.GetSwf() then
        local ds = DsTable.Find(DataSources[DS_BROKER])
        self.GetSwf():Invoke("initializeBroker", ds:GetData(0, 0), ds:GetData(0, 1), ds:GetData(0, 2), ds:GetData(0, 3), ds:GetData(0, 4))
        self.GetSwf():Invoke("setDebugMode", tostring(self.debug))
        self.GetSwf():Invoke("setColumnNames", self:SetColumnsForSWF())
        self.GetSwf():Invoke("setMode", 1)
      end
    end,
    OnResize = function(self)
      self:print("OnResize()")
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      local x = sw / 2 - ww / 2
      local y = sh / 2 - wh / 2
      WindowTweener:Create(self.wndName, "X", nil, x, 0.3)
      WindowTweener:Create(self.wndName, "Y", nil, y, 0.3)
      self:BuildNavigation()
    end,
    Hide = function(self)
      self:print("Hide()")
      Context:Pop()
      Context:CallQuit()
      NonModalContext:RemoveContext(self)
      NavigationHandler:Hide()
      HUD:PlaySound("HideWindow")
      self.visible = false
      self.inputFocus = false
      if self.GetWindow() then
        self.GetSwf():Unload()
        local ds = DsTable.Find(DataSources[DS_BROKER_INVENTORY_ITEMS])
        if ds then
          ds:DisableScriptEvents()
        end
        local ds = DsTable.Find(DataSources[DS_BROKER_MY_ITEMS])
        if ds then
          ds:DisableScriptEvents()
        end
        local ds = DsTable.Find(DataSources[DS_BROKER_SEARCH_ITEMS])
        if ds then
          ds:DisableScriptEvents()
        end
        self.GetWindow():Hide()
        self.m_SelectedCategory = 0
      end
    end,
    SetCategoryTree = function(self)
      local ds = DsTree.Find(DataSourceTrees[DST_INVENTORY_CATEGORIES_DATA])
      local data = ""
      self.treeData = ""
      self.treeData = self.treeData .. self:SerializeTreeItem("0.1", MarketplaceStrings.ALL_ITEMS, "397", "0")
      self:TreeRecursion(ds:GetRootNode())
      self.GetSwf():Invoke("SetCategoryTree", self.treeData)
    end,
    TreeRecursion = function(self, node)
      if node:GetChildCount() == 0 then
        return
      end
      for i = 0, node:GetChildCount() - 1 do
        local child = node:GetChildNode(i)
        local catText = child:GetText()
        local catIcon = child:GetBitmapIndex()
        local catID = child:GetData(0)
        self.treeData = self.treeData .. self:SerializeTreeItem(catID, catText, catIcon, node:GetData(0))
        self:TreeRecursion(child)
      end
    end,
    SerializeTreeItem = function(self, catID, catText, catIcon, parentCatId)
      return "catId~" .. tostring(catID) .. "|catText~" .. tostring(catText) .. "|catIcon~" .. tostring(catIcon) .. "|parentCatId~" .. tostring(parentCatId) .. "~~"
    end,
    BuildNavigation = function(self)
      NavigationHandler:Disconnect(self)
      NavigationHandler:Connect(self)
      NavigationHandler:Show(nil, nil, 25)
      NavigationHandler:AddButton(9, "Search", self.MODE_SHOPPING)
      NavigationHandler:AddButton(6, "My Items", self.MODE_MY_ITEMS)
      NavigationHandler:AddButton(397, "My Inventory", self.MODE_INVENTORY)
    end,
    OnNavigationShown = function(self)
      NavigationHandler:SelectButton(self.MODE_INVENTORY)
    end,
    OnNavigationHidden = function(self)
      NavigationHandler:Disconnect(self)
    end,
    NavigationOnUserEvent = function(self, a, b)
      if a == "SwitchTo" then
        self:ChangeMode(tonumber(b))
      elseif a == "exitScreen" then
        self:Hide()
      end
    end,
    ChangeMode = function(self, newMode)
      self:print("ChangeMode( " .. tostring(newMode) .. " )")
      self.mode = newMode
      if newMode == self.MODE_INVENTORY then
        self.selectedDS = DataSources[DS_BROKER_INVENTORY_ITEMS]
        BrokerHandler.GetSwf():Invoke("setBrokerMode", self.MODE_INVENTORY)
      elseif newMode == self.MODE_MY_ITEMS then
        self.selectedDS = DataSources[DS_BROKER_MY_ITEMS]
        BrokerHandler.GetSwf():Invoke("setBrokerMode", self.MODE_MY_ITEMS)
      elseif newMode == self.MODE_SHOPPING then
        self.selectedDS = DataSources[DS_BROKER_SEARCH_ITEMS]
        BrokerHandler.GetSwf():Invoke("setBrokerMode", self.MODE_SHOPPING)
      end
    end,
    ChangeCategory = function(self, id)
      if self.mode == self.MODE_INVENTORY and Broker.SelectInventoryCategory then
        self.m_SelectedCategory = math.floor(id)
        Broker.SelectInventoryCategory(self.m_SelectedCategory)
      elseif self.mode == self.MODE_MY_ITEMS then
        self.m_SelectedCategory = math.floor(id)
        Broker.SelectInventoryCategory(self.m_SelectedCategory)
      elseif self.mode == self.MODE_SHOPPING then
        self.m_SelectedCategory = math.floor(id)
        Broker.SelectInventoryCategory(self.m_SelectedCategory)
      end
    end,
    UpdateData = function(self)
      self:print("UpdateData")
      if not self.visible then
        return
      end
      self.GetSwf():Invoke("setColumnNames", self:SetColumnsForSWF())
      self.GetSwf():Invoke("setMode", 1)
    end,
    RequestData = function(self, offset, count)
      if not self.selectedDS then
        return
      end
      self:Populate(tonumber(offset), tonumber(count), DsTable.Find(self.selectedDS))
    end,
    Populate = function(self, offset, count, ds)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if self.GetSwf() then
        if ds then
          local numRows = ds:GetRowCount()
          if numRows > 0 then
            local offset = math.max(offset, 0)
            local countTo = math.min(offset + count, numRows)
            for i = offset, countTo - 1 do
              str = str .. self:BuildItemString(ds, i)
            end
          end
          self.GetSwf():Invoke("setData", str, numRows)
        else
          self.GetSwf():Invoke("setData", str, 0)
        end
      end
    end,
    BuildItemString = function(self, ds, row)
      local item = ds:GetData(row, 0)
      for i = 1, ds:GetColumnCount() - 1 do
        if i ~= 19 and i ~= self.BrokerItemGuidColumn then
          item = item .. "^" .. ds:GetData(row, i)
        elseif i == self.BrokerItemGuidColumn then
          item = item .. "^_" .. ds:GetData(row, i)
        elseif i == 19 then
          item = item .. "^"
        end
      end
      item = item .. ";"
      return item
    end,
    SetColumnsForSWF = function(self)
      local ds = DsTable.Find(self.selectedDS)
      local catString = ""
      for i = 0, ds:GetColumnCount() - 1 do
        if i > 0 then
          catString = catString .. "^"
        end
        catString = catString .. ds:GetColumnName(i)
      end
      return catString
    end,
    GetWindow = function()
      return Window.Find(Ui.GetName(BrokerHandler.wndName))
    end,
    GetSwf = function()
      return GfxCtrl.Find(Ui.GetName(BrokerHandler.swfName))
    end,
    OnUserEvent = function(a, b, c, d, e, f, g, h, i)
      if a == BrokerEvent.CLOSE then
        BrokerHandler:Hide()
      elseif a == BrokerEvent.PLACE then
        Broker.Place(b, c, d)
      elseif a == BrokerEvent.CANCEL then
        Broker.Cancel(string.sub(b, 2))
      elseif a == BrokerEvent.BUY then
        Broker.Buy(string.sub(b, 2), "1")
      elseif a == BrokerEvent.RELIST then
        Broker.Relist(string.sub(b, 2), c)
      elseif a == BrokerEvent.SEARCH then
        c = tonumber(c)
        d = tonumber(d)
        e = tonumber(e)
        f = tonumber(f)
        g = tonumber(g)
        h = tonumber(h)
        b = b or " "
        if not c or c == 0 then
          c = -1
        end
        if not d or d == 0 then
          d = -1
        end
        if not e or e == 0 then
          e = -1
        end
        if not f or f == 0 then
          f = -1
        end
        if not g or g == 0 then
          g = BrokerHandler.m_SelectedCategory
        end
        if not h or h == 0 then
          h = -1
        end
        i = i or 0
        BrokerHandler:print("SearchParams: " .. tostring(b) .. ", " .. tostring(c) .. ", " .. tostring(d) .. ", " .. tostring(e) .. ", " .. tostring(f) .. ", " .. tostring(g) .. ", " .. tostring(h) .. ", " .. tostring(i))
        Broker.Search(b, c, d, e, f, g, h, i)
      elseif a == BrokerEvent.REQUEST_DATA then
        BrokerHandler:RequestData(b, c)
      elseif a == BrokerEvent.INPUT_FOCUS then
        if b == "true" then
          BrokerHandler.inputFocus = true
          BrokerHandler.GetWindow():SetFocus()
        else
          BrokerHandler.inputFocus = false
          Window.SetFocus()
        end
      elseif a == "setCurrentCategory" then
        BrokerHandler:ChangeCategory(b)
      elseif a == "AS_Print" then
        BrokerHandler:print(b)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" and BrokerHandler.inputFocus == false then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[BrokerHandler]\t" .. message)
      end
    end
  }
  BindCommandToLua("showBroker", "BrokerHandler:Show")
  Main_wndBroker_swfBroker_OnUserEvent = BrokerHandler.OnUserEvent
  Main_wndBroker_swfBroker_OnFocus = BrokerHandler.OnFocus
  BrokerEvent = {
    CLOSE = "closeWindow",
    PLACE = "place",
    CANCEL = "cancel",
    BUY = "buy",
    RELIST = "relist",
    SEARCH = "search",
    REQUEST_DATA = "requestData",
    INPUT_FOCUS = "setFocus"
  }
end)()
;(function()
