      InventoryScreen.SelectInventoryGenderFilter(Ui.GetGender())
      EquipmentHandler:Show(JobHandler.InventorySlotMap, 0, self.slotCount, 1, "BaseClient.Inventory.", "BaseClient.Inventory.CurrentlyEquipped", JobHandler:SetEquipmentColumnNames(JobHandler.EquipmentColumnsTable), true, Ui.GetUserOptionsValue("MyCharacterWindowOptions", "LastSelectedViewMode_StyleCards", "1"), self.SlotLabels)
      EquipmentHandler:SetMode(EquipmentModes.STYLE_CARDS)
      self:RestrictSlotsForRace()
      self:OnResize()
