        InventoryScreen.SelectInventoryCategory(self.INVENTORY_SUB_CATS[i].id)
        local ds = DsTable.Find(DataSources[DS_INVENTORY_ITEMS_DATA])
        if ds and self.ChangesTbl[i].row ~= "000000000000000" then
          EquipScreen.UseStyleCard(ds:GetData(self.ChangesTbl[i].row, 0))
          Ui.ClearItemNewFlag(ds:GetData(self.ChangesTbl[i].row, 0))
        end
      end
      InventoryScreen.SelectInventoryCategory(self.INVENTORY_SUB_CATS[EquipmentHandler.selectedSlot].id)
      self:ClearChanges()
      self:EquipmentPaneOnSetCurrentEquip()
    end,
    NewChangesTable = function(self)
      for i = 1, self.slotCount do
        self.ChangesTbl[i] = {}
        self.ChangesTbl[i].row = "000000000000000"
        self.ChangesTbl[i].itemString = self.BuildNoneItem(i)
      end
    end,
    ClearChanges = function(self)
      if not EquipmentHandler.selectedSlot then
        EquipmentHandler.selectedSlot = 1
      end
      local selectedInventoryCategory = self.INVENTORY_SUB_CATS[EquipmentHandler.selectedSlot].id
      for i = 1, self.slotCount do
        InventoryScreen.SelectInventoryCategory(self.INVENTORY_SUB_CATS[i].id)
        if self.ChangesTbl[i].row ~= "000000000000000" and self:GetSlotIDForRow(self.ChangesTbl[i].row) then
          self:print("--> " .. tostring(self:GetSlotIDForRow(self.ChangesTbl[i].row)))
          EquipScreen.ClearPreviewStyleCard(self:GetSlotIDForRow(self.ChangesTbl[i].row))
        end
      end
      InventoryScreen.SelectInventoryCategory(selectedInventoryCategory)
      self:NewChangesTable()
      self:EquipmentPaneOnSetCurrentEquip()
    end,
    AddToChanges = function(self, row)
      if not row then
        return
      end
      if "000000000000000" == row then
        EquipScreen.ClearPreviewStyleCard(EquipmentHandler.selectedSlot + 1)
        self.ChangesTbl[EquipmentHandler.selectedSlot].row = "000000000000000"
        self.ChangesTbl[EquipmentHandler.selectedSlot].itemString = self.BuildNoneItem(EquipmentHandler.selectedSlot)
        self.changed = true
      else
        local itemID = self:GetItemIDForRow(row)
        if itemID then
          self:print("AddToChanges()")
          EquipScreen.PreviewStyleCard(itemID)
        end
        local ds = DsTable.Find(DataSources[DS_INVENTORY_ITEMS_DATA])
        if ds then
          self.ChangesTbl[EquipmentHandler.selectedSlot].row = row
          self.ChangesTbl[EquipmentHandler.selectedSlot].itemString = self:BuildItemString(ds, row)
          self:print(self.ChangesTbl[EquipmentHandler.selectedSlot].itemString)
        end
      end
      self:EquipmentPaneOnSetCurrentEquip()
    end,
    PreviewChanges = function(self)
      if not EquipmentHandler.selectedSlot then
        return
      end
      local change = false
      for i = 1, self.slotCount do
        if self.ChangesTbl[i].row ~= "000000000000000" then
          change = true
        end
      end
      self.changed = change
    end,
    GetRowForGuid = function(self, guid)
      local ds = DsTable.Find(DataSources[DS_INVENTORY_ITEMS_DATA])
      for i = 0, ds:GetRowCount() - 1 do
        if tonumber(ds:GetData(i, 0)) == tonumber(guid) then
          return i
        end
      end
      return -1
    end,
    GetItemGUIDForRow = function(self, row)
      local ds = DsTable.Find(DataSources[DS_INVENTORY_ITEMS_DATA])
      if ds then
        return ds:GetData(row, 0)
      end
      return false
    end,
    GetItemIDForRow = function(self, row)
      local ds = DsTable.Find(DataSources[DS_INVENTORY_ITEMS_DATA])
      if ds then
        return ds:GetData(row, 23)
      end
      return false
    end,
    GetSlotIDForRow = function(self, row)
      local ds = DsTable.Find(DataSources[DS_INVENTORY_ITEMS_DATA])
      if ds and row ~= "000000000000000" then
        return ds:GetData(row, 8)
      end
      return false
    end,
    RestrictSlotsForRace = function(self)
      local race = Ui.GetRace()
      local gender = Ui.GetGender()
      local restrictSlots = {}
      if race == 1 then
        if gender == 1 then
          table.insert(restrictSlots, self.STYLE_WING_PATTERNS)
        else
          table.insert(restrictSlots, self.STYLE_WING_PATTERNS)
          table.insert(restrictSlots, self.STYLE_FACIAL_HAIR)
        end
      elseif race == 2 then
        if gender == 1 then
          table.insert(restrictSlots, self.STYLE_FACIAL_HAIR)
        else
          table.insert(restrictSlots, self.STYLE_FACIAL_HAIR)
        end
      end
      for i = 1, #restrictSlots do
        EquipmentHandler:EnableCategory(restrictSlots[i], false)
      end
    end,
    GetSlotLabels = function(self)
      if self.slotLabelsSet then
        return
      end
      local ds = DsTree.Find(DataSourceTrees[DST_INVENTORY_CATEGORIES_DATA])
      if not ds then
        return
      end
      local root = ds:GetRootNode()
      for i = 0, root:GetChildCount() - 1 do
        local child = root:GetChildNode(i)
        local catID = child:GetData(0)
        if tonumber(catID) == StyleCardHandler.INVENTORY_CAT_ID then
          local firstChildCatID
          local dontAdd = false
          for c = 0, child:GetChildCount() - 1 do
            local subChild = child:GetChildNode(c)
            local catText = subChild:GetText()
            local catIcon = subChild:GetBitmapIndex()
            local catID = subChild:GetData(0)
            if catID == firstChildCatID then
              dontAdd = true
            end
            if firstChildCatID == nil then
              firstChildCatID = catID
            end
            if dontAdd == false then
              for ii = 1, #self.INVENTORY_SUB_CATS do
                if self.INVENTORY_SUB_CATS[ii].id == tonumber(catID) then
                  self.INVENTORY_SUB_CATS[ii].label = catText
                end
              end
            end
          end
          self.slotLabelsSet = true
          return
        end
      end
      self.slotLabelsSet = false
    end,
    UpdateNavigation = function(self)
      if not self.visible then
        return
      end
      self:print("self.changed: " .. tostring(self.changed))
      if self.changed and not self.NavigationButtonsAdded then
        self.NavigationButtonsAdded = true
      elseif not self.changed then
        if Context:IsCurrent(self.CONTEXT_NAME) then
          Context:Pop()
        end
        self.NavigationButtonsAdded = false
      end
    end,
    ToggleNavigationButtons = function(self, value)
      self:print("ToggleNavigationButtons( " .. tostring(value) .. " )")
      for i = 1, #JobHandler.NavigationLabels do
        if (not JobHandler.ABILITIES_DISABLED or i ~= JobHandler.MODE_ABILITIES) and i ~= JobHandler.MODE_STYLE_CARDS then
          NavigationHandler:DisableNavigationButton(i, value)
        end
      end
    end,
    EquipmentPaneOnRequestData = function(self, offset, count)
      if EquipmentHandler.selectedSlot then
        local ds = DsTable.Find(DataSources[DS_INVENTORY_ITEMS_DATA])
        if ds then
          EquipmentHandler:Populate(offset, count, ds)
        end
      end
    end,
    EquipmentPaneOnPopulate = function(self, offset, count, ds)
      local slotID = EquipmentHandler.selectedSlot
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          count = tonumber(count)
          local offset = math.max(offset, 0)
          if offset == 0 then
            str = self.BuildNoneItem(slotID)
            count = count - 1
          else
            offset = offset - 1
          end
          local countTo = math.min(offset + count, numRows)
          for i = offset, countTo - 1 do
            str = str .. self:BuildItemString(ds, i)
          end
          numRows = numRows + 1
        else
          str = self.BuildNoneItem(slotID)
        end
        EquipmentHandler:PopulateWindow(str, numRows)
      else
        str = self.BuildNoneItem(slotID)
        EquipmentHandler:PopulateWindow(str, 1)
      end
    end,
    EquipmentPaneOnSetCurrentEquip = function(self)
      local countTo = 0
      local str = ""
      local ds = self.ChangesTbl
      if ds then
        for i = 1, self.slotCount do
          str = str .. self.ChangesTbl[i].itemString
        end
        EquipmentHandler:PopulateWindowCategories(str, numRows)
      end
      self:PreviewChanges()
      self:UpdateNavigation()
    end,
    BuildNoneItem = function(slotID)
      local item = "000000000000000^" .. EquipmentHandler.noneItemIcon .. "^" .. Ui.GetString("RestoreDefault") .. "^^^^0^^" .. slotID .. ";"
      return item
    end,
    BuildItemString = function(self, ds, row)
      local item = ds:GetData(row, 0)
      for i = 1, ds:GetColumnCount() - 1 do
        if i ~= 19 and i ~= 8 and i ~= 7 then
          item = item .. "^" .. ds:GetData(row, i)
        elseif i == 7 then
          item = item .. "^1"
        elseif i == 8 then
          item = item .. "^" .. ds:GetData(row, i) - 1
        elseif i == 19 then
          if tonumber(ds:GetData(row, i)) ~= nil then
            if 0 < tonumber(ds:GetData(row, i)) then
              local statDS = DsTable.Find(DataSources[DS_STAT_DEFINITIONS])
              if statDS then
                local rowCount = statDS:GetRowCount()
                if rowCount > 0 then
                  item = item .. "^" .. statDS:GetData(tonumber(ds:GetData(row, i)) - 1, 1)
                  item = item .. "^" .. statDS:GetData(tonumber(ds:GetData(row, i)) - 1, 2)
                end
              end
            else
              item = item .. "^^"
            end
          else
            item = item .. "^^"
          end
        end
      end
      item = item .. ";"
      return item
    end,
    EquipmentPaneOnUserEvent = function(self, a, b, c, d, e, f, ...)
      if a == "requestData" then
        EquipmentHandler:RequestData(b, c)
      elseif a == "onMembersOnly" then
        JobHandler:ExitToMarketPlace()
      elseif a == "changeSelectedCategory" then
        if b == nil or b == "undefined" then
          b = 1
        end
        EquipmentHandler.selectedSlot = tonumber(b)
        InventoryScreen.SelectInventoryCategory(self.INVENTORY_SUB_CATS[EquipmentHandler.selectedSlot].id)
      elseif a == "previewItem" then
        if type(tonumber(c)) == "number" then
          self.previewedSlot = tonumber(c) + 1
        end
        self:print("EquipmentPaneOnUserEvent(previewItem)")
        EquipScreen.PreviewStyleCard(b)
      elseif a == "clearPreview" then
        if self.previewedSlot == nil then
          return
        end
        EquipScreen.ClearPreviewStyleCard(self.previewedSlot)
        self:print("EquipmentPaneOnUserEvent(clearPreview)")
        if self.ChangesTbl[self.previewedSlot - 1] and self.ChangesTbl[self.previewedSlot - 1].row ~= "000000000000000" then
          local itemID
          self:print(self.ChangesTbl[self.previewedSlot - 1].row)
          if itemID then
            self:print("EquipmentPaneOnUserEvent(rePreview( " .. tostring(itemID) .. " ))")
            EquipScreen.PreviewStyleCard(itemID)
          end
        end
        self.previewedSlot = nil
      elseif a == "equipItem" then
        HUD:PlaySound("Selected")
        local itemGUID = b
        if itemGUID then
          Ui.ClearItemNewFlag(itemGUID)
        end
        local row = itemGUID
        if itemGUID ~= "000000000000000" then
          row = self:GetRowForGuid(tonumber(b))
        end
        self:AddToChanges(row)
      elseif a == "changeViewMode" then
        if b == "undefined" then
          return
        end
        EquipmentHandler.currentViewMode = b
        Ui.SetUserOptionsValue("MyCharacterWindowOptions", "LastSelectedViewMode_StyleCards", b)
      elseif a == "PlaySound" or a == "playSound" then
        HUD:PlaySound(b)
      elseif a == "AS_Print" then
        self:print(a .. "( " .. tostring(b) .. " )")
      elseif StyleCardHandler[a] then
        StyleCardHandler[a](StyleCardHandler, b, c, d, e, f, ...)
      elseif a == "CloseWindowPS3" then
        CharacterCreatePopups:Show()
        CharacterCreatePopups:DisplayText(Ui.GetString("PS3StyleCardsPrompt"), 4)
        CharacterCreatePopups:SetStyleCard()
      else
        self:print(a)
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[StyleCardHandler]\t" .. tostring(message))
      end
    end,
    printChanges = function(self)
      self:print("\t-Currently Applied Styles")
      for i = 1, #self.ChangesTbl do
        self:print("\t\t- " .. tostring(i) .. ") " .. tostring(self.ChangesTbl[i].row))
      end
    end,
    AddStyleCards = function(self)
      if not Admin then
        return
      end
      Ui.ProcessChatCommand("/item addrange 6826 6853")
      Ui.ProcessChatCommand("/item addrange 68817 68870")
      Ui.ProcessChatCommand("/item addrange 68850 68930")
      Ui.ProcessChatCommand("/item addrange 68937 68943")
    end
  }
end)()
;(function()
  PlayerInspect = {
    wndName = "Main.wndPlayerInspect",
    swfName = "Main.wndPlayerInspect.swfPlayerInspect",
    debug = false,
    visible = false,
    MODE_EQUIPMENT = 1,
    MODE_MISC = 2,
    GetWindow = function()
      return Window.Find(Ui.GetName(PlayerInspect.wndName))
    end,
    GetSwf = function()
      return GfxCtrl.Find(Ui.GetName(PlayerInspect.swfName))
    end,
    Show = function(self)
      Logger:print("playerinspect.lua", "show")
      self:print("Show")
      if not self.GetWindow() then
        return
      end
      self.visible = true
      HUD:ClearContextAndPreservePanes()
      Context:Push("PlayerInspectHide", function()
        PlayerInspect:Hide()
      end)
      NonModalContext:AddContext(self)
      self.GetSwf():Load()
      if HUD.inMiniGame == true then
        HUD:hideMinigame()
      else
        HUD:hideMain()
      end
      self:SetInfo()
      self:SetItems()
      self:SetJobs()
      self:BuildNavigation()
      self:OnResize()
      HUD:PlaySound("ShowWindow")
    end,
    OnResize = function(self)
      local w = self:GetWindow()
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      Ui.SetCameraOffset2D(-200, 40)
      w:SetPosition(110, sh / 2 - wh / 2)
    end,
    Hide = function(self)
      self:print("Hide")
      self.visible = false
      if not self.GetWindow() then
        return
      end
      Context:Pop()
      Context:CallQuit()
      self.GetWindow():Hide()
      self.GetSwf():Unload()
      NavigationHandler:Hide()
      Ui.StopInspecting()
      HUD:PlaySound("HideWindow")
    end,
    ShowPS3 = function(self)
      self.visible = true
      self.GetWindow():Show()
    end,
    HidePS3 = function(self)
      self.visible = false
      self.GetWindow():Hide()
    end,
    BuildNavigation = function(self)
      NavigationHandler:Connect(self)
      NavigationHandler:Show(nil, nil, 25)
      NavigationHandler:AddButton(635, JobHandler.NavigationLabels[JobHandler.MODE_EQUIPMENT], self.MODE_EQUIPMENT)
      NavigationHandler:AddButton(3756, Ui.GetString("miscString"), self.MODE_MISC)
      NavigationHandler:HighlightButton(1, 1)
    end,
    ModeSwitch = function(self, mode)
      if mode ~= 0 then
        self:ShowPS3()
      else
        self:HidePS3()
      end
      if mode == self.MODE_EQUIPMENT then
        self.GetSwf():Invoke("DisplayItems", 1, 2, 3, 4, 5, 6, 7)
      elseif mode == self.MODE_MISC then
        self.GetSwf():Invoke("DisplayItems", 12, 13, 8)
      end
    end,
    SetInfo = function(self)
      local ds = DsTable.Find(DataSources[DS_INSPECT])
      if not ds then
        return
      end
      self.GetSwf():Invoke("SetInfo", self:SerializeData(ds))
      self.GetSwf():Invoke("SetMemberStatus", tostring(Ui.IsMember()))
    end,
    SetItems = function(self)
      local ds = DsTable.Find(DataSources[DS_INSPECT_ITEMS])
      if not ds then
        return
      end
      local data = ""
      for i = 1, #JobHandler.EquipmentSlotLabels do
        if i > 1 then
          data = data .. "^"
        end
        data = data .. JobHandler.EquipmentSlotLabels[i]
      end
      self.GetSwf():Invoke("SetItemLabels", data)
      self.GetSwf():Invoke("SetItems", self:SerializeData(ds))
    end,
    SetJobs = function(self)
      local ds = DsTable.Find(DataSources[DS_INSPECT_JOBS])
      if not ds then
        return
      end
      self.GetSwf():Invoke("SetJobs", self:SerializeData(ds))
    end,
    SerializeData = function(self, ds)
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      for i = 0, ds:GetRowCount() - 1 do
        for c = 0, ds:GetColumnCount() - 1 do
          if c > 0 then
            data = data .. propDelim
          end
          data = data .. ds:GetColumnName(c) .. valueDelim .. ds:GetData(i, c)
        end
        if i < ds:GetRowCount() - 1 then
          data = data .. itemDelim
        end
      end
      return data
    end,
    SWFResize = function(self, width, height)
      self.GetSwf():SetProperty("Width", width)
      self.GetSwf():SetProperty("Height", height)
      self.GetWindow():SetProperty("Width", width + 100)
      self.GetWindow():SetProperty("Height", height)
    end,
    OnUserEvent = function(a, b, c)
      if a == "resize" then
        PlayerInspect:SWFResize(tonumber(b), tonumber(c))
      elseif a == "playSound" then
        HUD:PlaySound(b)
      elseif a == "onMembersOnly" then
        PlayerInspect:print(a .. tostring(b) .. " )")
        PlayerInspect:Hide()
        MembershipHandler:Show()
      elseif a == "onStoreItem" then
        PlayerInspect:print(a .. tostring(b) .. " )")
        PlayerInspect:Hide()
        InGamePurchaseStoreScreen.DisplayStoreItemsContainingPlayerInspectGameItem(tonumber(b))
      elseif a == "CloseWindowPS3" then
        PlayerInspect:ModeSwitch(0)
      elseif a == "AS_Print" then
        PlayerInspect:print(b)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    NavigationOnUserEvent = function(self, a, b)
      if a == "SwitchTo" then
        self:ModeSwitch(tonumber(b))
      elseif a == "exitScreen" then
        self:Hide()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[PlayerInspect]\t" .. tostring(message))
      end
    end
  }
  Main_wndPlayerInspect_swfPlayerInspect_OnUserEvent = PlayerInspect.OnUserEvent
  Main_wndPlayerInspect_swfPlayerInspect_OnFocus = PlayerInspect.OnFocus
end)()
;(function()
  function BaseClient_Matchmaking_Requests_OnDataUpdate()
    QuickMatch:DataUpdated()
  end
  function BaseClient_Matchmaking_Requests_OnUpdate()
    QuickMatch:DataUpdated()
  end
  QuickMatch = {
    swf = Ui.GetName("Main.wndQuickMatch.swfQuickMatch"),
    wnd = Ui.GetName("Main.wndQuickMatch"),
    reqsDS = "BaseClient.Matchmaking.Requests",
    pane = nil,
    win = nil,
    curX = 0,
    curY = -500,
    numItems = 0,
    max = false,
    modX = 0,
    isShown = false,
    Show = function(self, showFlag)
      Logger:print("quickMatch.lua", " ### QuickMatch Show(" .. tostring(self.isShown) .. ") loc(" .. self.curX .. ", " .. self.curY .. ")")
      if self.isShown == true then
        return
      end
      Matchmaking.PopulateQueues()
      if HUD.inMiniGame == true then
        self:Hide()
        return
      end
      if showFlag == nil or showFlag == false then
        self:DataUpdated()
        return
      end
      self.isShown = true
      NonModalContext:AddContext(self)
      self:OnResize()
    end,
    Hide = function(self)
      Logger:print("quickMatch.lua", " ### QuickMatch Hide(" .. tostring(self.isShown) .. ")")
      if self.isShown == false then
        local ctrl = GfxCtrl.Find(self.swf)
        if ctrl ~= nil then
          ctrl:Unload()
        end
        return
      end
      self.isShown = false
      if self.pane then
        self.pane:SoftInvoke("clearItems")
      end
      NonModalContext:RemoveContext(self)
      self.curY = -500
      WindowTweener:Create("Main.wndQuickMatch", "Y", nil, self.curY, 0.05, function()
        Window.Find(Ui.GetName("Main.wndQuickMatch")):Hide()
        GfxCtrl.Find(self.swf):Unload()
      end)
    end,
    Resized = function(self)
      if self.isShown == false then
        return
      end
      local oldModX = self.modX
      self.modX = 0
      if self.modX ~= oldModX then
        self:OnResize()
      end
    end,
    OnResize = function(self)
      Logger:print("quickMatch.lua", " ### QuickMatch OnResize(" .. tostring(self.isShown) .. ")")
      self.pane = GfxCtrl.Find(self.swf)
      self.pane:SetLimitAdvance(true)
      self.win = Window.Find(self.wnd)
      local w, h = self.win:GetSize()
      local sw, sh = Window.GetCanvasSize()
      if self.curX == 0 then
        self.curX = sw - w - 250 + self.modX
      end
      self.win:Show()
      local newX = sw - w - 250 + self.modX
      if self.curX == newX then
        self.win:SetPosition(self.curX, self.curY)
      else
        self.curX = newX
        WindowTweener:Create("Main.wndQuickMatch", "X", nil, self.curX, 0.3)
      end
      self.curY = 50
      WindowTweener:Create("Main.wndQuickMatch", "Y", nil, self.curY, 0.3, function()
        self.pane:Invoke("showTicker")
      end)
    end,
    ExitQueue = function(self)
      Logger:print("quickmatch.lua", "Exiting Queue")
      self.pane:Invoke("exitQueue")
    end,
    DataUpdated = function(self)
      Logger:print("quickMatch.lua", " ### QuickMatch DataUpdated(" .. tostring(self.isShown) .. ")")
      if HUD.inMiniGame == true then
        self:Hide()
        return
      end
      self.pane = GfxCtrl.Find(self.swf)
      self.pane:SoftInvoke("clearItems")
      self.numItems = 0
      local ds = DsTable.Find(self.reqsDS)
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          local qID = tostring(ds:GetData(i, 1))
          local cTime = tostring(ds:GetData(i, 4))
          local name, avgTime = Lobby:GetQueueNameWithID(qID)
          local timeDiff = os.difftime(os.time(), cTime)
          self.pane:Invoke("addItem", name, qID, timeDiff, avgTime)
          self.numItems = self.numItems + 1
        end
      end
      if self.numItems > 0 then
        self:Show(true)
        self.pane:Invoke("bigWindowShow")
      else
        Logger:print("quickMatch.lua", " ### QuickMatch DataUpdated() hiding window")
        WindowTweener:Create("Main.wndQuickMatch", "Y", nil, self.curY, 0.05, function()
          self:Hide()
        end)
      end
    end,
    ImInQueue = function(self, QID)
      local ds = DsTable.Find(self.reqsDS)
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          local qID = tonumber(ds:GetData(i, 1))
          local cTime = tostring(ds:GetData(i, 4))
          local timeDiff = os.difftime(os.time(), cTime)
          if tonumber(QID) == qID then
            return timeDiff
          end
        end
      end
      return -1
    end,
    OnUserEvent = function(self, a, b, c, d, e, f)
      if tostring(a) == "playSound" then
        Lobby:OnUserEvent(a, b)
      elseif tostring(a) == "leaveQ" then
        Logger:print("quickmatch.lua", "Leaving Queue " .. tostring(b))
        Matchmaking.LeaveQueue(tostring(b))
      elseif tostring(a) == "titlebarPressed" then
        Lobby:Show(true)
      elseif tostring(a) == "WindowShow" then
        self.max = true
        self:Resized()
      elseif tostring(a) == "WindowHide" then
        self.max = false
        self:Resized()
      end
    end
  }
  function Main_wndQuickMatch_swfQuickMatch_OnUserEvent(a, b, c, d, e, f)
    QuickMatch:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndQuickMatch_swfQuickMatch_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
;(function()
  PortraitButton = {
    windowName = "Main.wndPortraitButton",
    swfName = "Main.wndPortraitButton.swfPortraitButton",
    visible = false,
    Show = function(self)
      return
    end,
    Hide = function(self)
    end,
    HideFinale = function(self)
      local wnd = Window.Find(Ui.GetName(self.windowName))
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      if wnd then
        wnd:Hide()
        if swf then
          swf:Unload()
        end
      end
