    OnResize = function(self)
      local wnd = Window.Find(Ui.GetName(self.windowName))
      if wnd then
        local sw, sh = Window.GetCanvasSize()
        local width, height = wnd:GetSize()
        WindowTweener:Create(self.windowName, "X", nil, sw / 2 + width - 86, 0.3)
      end
    end,
    PortraitTaken = function(self)
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      if not swf then
        return
      end
      swf:Invoke("portraitTaken", Ui.GetString("PortraitCaptured"), 3)
      if JobHandler.isFromTCG == true then
        JobHandler:Hide()
      end
    end,
    OnUserEvent = function(a)
      if a == "capturePortrait" then
        if Ui.RequestPortrait then
          if JobHandler.isFromTCG == true then
            Ui.RequestPortrait(1)
          else
            Ui.RequestPortrait()
          end
          PortraitButton:PortraitTaken()
        end
