;(function()
  LevelProgressBar = {
    windowName = Ui.GetName("Main.wndLevelProgressPane"),
    movieName = Ui.GetName("Main.wndLevelProgressPane.swfLevelProgressPane"),
    isShown = false,
    isEnabled = true,
    SetData = function(self, id)
      local swf = GfxCtrl.Find(self.movieName)
      swf:Reset()
      local obj = self:Populate(id)
      swf:Invoke("setTitle", obj.title)
      swf:Invoke("setPercent", obj.expPct)
      swf:Invoke("setLevel", obj.rank)
      GroupHandler:SetJobLevelExp(obj.title, obj.rank, obj.expPct)
    end,
    Populate = function(self, activeProfileID)
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      local curProfileTbl = {}
      if ds then
        local rows = ds:GetRowCount()
        for index = 0, rows - 1 do
          local id = ds:GetData(index, ProfileDsColumns.ID)
          local name = ds:GetData(index, ProfileDsColumns.Name)
          local rank = ds:GetData(index, ProfileDsColumns.Rank)
          local exp = ds:GetData(index, ProfileDsColumns.RankPercent)
          if activeProfileID == tonumber(id) then
            if tonumber(rank) == 20 then
              exp = 100
            end
            curProfileTbl.title = name
            curProfileTbl.expPct = exp
            curProfileTbl.rank = tonumber(rank)
          end
        end
      end
      return curProfileTbl
    end,
    Show = function(self)
      if self.isEnabled == false then
        return
      end
      local sw, sh = Window.GetCanvasSize()
      local w = Window.Find(self.windowName)
      if w ~= nil then
        local width, height = w:GetSize()
        w:SetPosition(sw + 300, 270)
        w:Show()
        WindowTweener:Create("Main.wndLevelProgressPane", "X", nil, sw - width - 20, 0.3)
        self.isShown = true
      end
    end,
    RegisterDatasource = function(self)
      local ds = DsTable.Find(DataSources[DS_PROFILES])
      ds:EnableScriptEvents()
    end,
    Hide = function(self)
      local w1 = Window.Find(self.windowName)
      if w1 ~= nil then
        local sw, sh = Window.GetCanvasSize()
        WindowTweener:Create("Main.wndLevelProgressPane", "X", nil, sw + 300, 0.3, function()
          Window.Find(LevelProgressBar.windowName):Hide()
          GfxCtrl.Find(LevelProgressBar.movieName):Unload()
        end)
        self.isShown = false
      end
    end,
    ShowInJobBrowser = function(self)
      local sw, sh = Window.GetCanvasSize()
      local w = Window.Find(self.windowName)
      if w ~= nil and self.isShown == false then
        local width, height = w:GetSize()
        w:SetPosition(sw, height + 8)
        w:Show()
        w:MoveToFront()
        WindowTweener:Create("Main.wndLevelProgressPane", "X", nil, sw / 2 + width * 2 - 70, 0.3)
        if sh < 1000 then
        end
        self.isShown = true
      end
    end,
    HideInJobBrowser = function(self)
      local sw, sh = Window.GetCanvasSize()
      local w = Window.Find(self.windowName)
      if w ~= nil then
        local width, height = w:GetSize()
        WindowTweener:Create("Main.wndLevelProgressPane", "X", nil, sw, 0.3, function()
          Window.Find(self.windowName):Hide()
        end)
        self.isShown = false
      end
    end
  }
end)()
;(function()
  ConfirmationWindow = {
    wndName = "Main.wndConfirmationWindow",
    swfName = "Main.wndConfirmationWindow.swfConfirmationWindow",
    visible = false,
    debug = true,
    height = nil,
    tfActive = false,
    GetWindow = function()
      return Window.Find(Ui.GetName(ConfirmationWindow.wndName))
    end,
    GetSwf = function()
      return GfxCtrl.Find(Ui.GetName(ConfirmationWindow.swfName))
    end,
    Show = function(self, message, items, quantity, callback)
      if self.visible then
        return
      end
      Context:Push("ConfirmationWindowHide", function()
        ConfirmationWindow:HandleResponse(0)
      end)
      NonModalContext:AddContext(self)
      self.GetSwf():Load()
      self.GetSwf():Invoke("ConfirmationWindow.setText", message)
      if items then
        self.GetSwf():Invoke("ConfirmationWindow.setData", items, quantity)
      end
      self.GetWindow():Show()
      self.visible = true
      self:OnResize()
    end,
    OnResize = function(self)
      local ww, wh = self.GetWindow():GetSize()
      local sw, sh = Window.GetCanvasSize()
      if self.height ~= nil then
        wh = self.height
      end
      WindowTweener:Create(self.wndName, "X", nil, sw / 2 - ww / 2, 0.3)
      WindowTweener:Create(self.wndName, "Y", nil, sh / 2 - wh / 2, 0.3)
    end,
    Hide = function(self)
      Context:Pop()
      NonModalContext:RemoveContext(self)
      self.GetWindow():Hide()
      self.GetSwf():Unload()
      self.visible = false
      self.tfActive = false
      self.height = nil
    end,
    SetPasswordRequired = function(self, value)
      self.GetSwf():Invoke("ConfirmationWindow.setPasswordRequired", tostring(value))
    end,
    SetHeight = function(self, newHeight)
      self.height = newHeight
      self:OnResize()
    end,
    HandleResponse = function(self, response, password)
      self:Hide()
      self:CallDelegate("OnConfirmationResponse", tonumber(response), password)
    end,
    playSound = function(self, name)
      HUD:PlaySound(name)
    end,
    UpdateFocus = function(self, focus)
      if focus == 1 then
        self.tfActive = true
      else
        self.tfActive = false
      end
    end,
    OnUserEvent = function(event, ...)
      if event == "response" then
        ConfirmationWindow:HandleResponse(...)
      elseif event == "setHeight" then
        ConfirmationWindow:SetHeight(...)
      elseif event == "AS_Print" then
        ConfirmationWindow:print(...)
      elseif ConfirmationWindow[event] then
        ConfirmationWindow[event](ConfirmationWindow, ...)
      end
    end,
    OnFocus = function(focus)
      ConfirmationWindow:print(ConfirmationWindow.tfActive)
      if focus == "1" and ConfirmationWindow.tfActive == false then
        ConfirmationWindow:print("give Game focus")
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[ConfirmationWindow]\t" .. tostring(message))
      end
    end
  }
  Delegate:AddSupportToClassObject(ConfirmationWindow, "ConfirmationWindow")
  Main_wndConfirmationWindow_swfConfirmationWindow_OnUserEvent = ConfirmationWindow.OnUserEvent
end)()
