    Show = function(self, noTween)
      if self.isShown == true or self.isTweeningIn == true then
        return
      end
      ChatLog:Show()
      ChatLog:SetIsMember()
      self.startTime = os.time()
      self.launchedMinigame = false
      self.isTweeningIn = true
      Ui.ShowActivityPortalWindow(1)
      if self.bPickNewActivitiesOnNextShow == true then
        self:PickActivities()
        self.bPickNewActivitiesOnNextShow = false
      end
      Ui.IncrementClientLuaMetric("ActivityPortal_Show")
      self.pane = GfxCtrl.Find(self.swf)
      self.win = Window.Find(self.wnd)
      self.isShown = true
      NonModalContext:AddContext(self)
      Ui.SetMovementEnabled(0)
      InteractionPrompt:Disable()
      local ww, wh = self.win:GetSize()
      self.curY = -wh
      Ui.ObscureScene(0.7, 1000)
      HUD:PlaySound("WindowShow")
      if noTween then
        self:ShowNoTweenDisplay()
      else
        self:OnResize()
      end
      self:AddActivitiesToFlash()
      PowerHourButton:DetermineShow()
      local ds = DsTable.Find(PortalHandler.dsItemOfTheDay)
      ds:EnableScriptEvents()
      BaseClient_InGamePurchase_StoreItemOfTheDay_OnDataUpdate = self.PopulateItemOfTheDay
      InGamePurchaseStoreScreen.GetWalletInfo()
      self:UpdateCoinInfo()
      self:PopulateNews()
      self:PopulateWheelSpin()
      local m = GfxCtrl.Find(self.swf)
      local todayDay, todayMonth, todayYear = Ui.GetDayMonthYear()
      m:Invoke("setDateString_lua", todayMonth .. "/" .. todayDay .. "/" .. todayYear)
    end,
    ShowNoTween = function(self)
      self:Show(true)
    end,
    Hide = function(self)
      TutorialDialog:Hide()
      ToolTipHandler:HideToolTip()
      Ui.TriggerFirstTimeEvent("newPlayerFTE")
      if self.isShown == false or self.isTweeningIn == true then
        return
      end
      local ds = DsTable.Find(PortalHandler.dsItemOfTheDay)
      ds:DisableScriptEvents()
      local diffTime = os.difftime(os.time(), self.startTime)
      Ui.SetClientLuaMetric("ActivityPortal_duration", diffTime)
      local swfWindow = GfxCtrl.Find(self.swf)
      swfWindow:Invoke("OnPortalClose")
      self.isShown = false
      Ui.ShowActivityPortalWindow(0)
      NonModalContext:RemoveContext(self)
      Ui.SetMovementEnabled(1)
      InteractionPrompt:Enable()
      HUD:PlaySound("WindowHide")
      Ui.ObscureScene(0, 1000)
      GameDock:SetState(GameDock.NORMAL_STATE)
      NavigationHandler:EnableBar()
      GfxCtrl.Find(Ui.GetName("Main.wndActivityPortal.swfActivityPortal")):Unload()
      Window.Find(Ui.GetName("Main.wndActivityPortal")):Hide()
    end,
    OnResize = function(self)
      self.pane = GfxCtrl.Find(self.swf)
      self.win = Window.Find(self.wnd)
      local sw, sh = Window.GetCanvasSize()
      self.win:SetSize(sw, sh)
      local w, h = self.win:GetSize()
      self.curX = sw / 2 - w / 2
      self.win:Show()
      self.win:SetPosition(0, -h)
      self.curY = sh / 2 - h / 2
      if sw < 1200 then
        local m = GfxCtrl.Find(self.swf)
        m:Invoke("movePanel")
      end
      GameDock:SetState(GameDock.DISABLED_STATE)
      WindowTweener:Create("Main.wndActivityPortal", "Y", nil, self.curY, 0.3, function()
        ActivityPortal.isTweeningIn = false
        GameDock:SetState(GameDock.SUBMENU_STATE)
        if MinigameStartScreen:GetMinigameType() ~= -1 then
          QuestHandler:DismissAll()
        end
        ToolTipHandler:HideToolTip()
      end)
    end,
    ShowNoTweenDisplay = function(self)
      self.pane = GfxCtrl.Find(self.swf)
      self.win = Window.Find(self.wnd)
      local sw, sh = Window.GetCanvasSize()
      self.win:SetSize(sw, sh)
      local w, h = self.win:GetSize()
      self.curX = sw / 2 - w / 2
      self.win:Show()
      self.curY = sh / 2 - h / 2
      self.win:SetPosition(0, self.curY)
      ActivityPortal.isTweeningIn = false
      GameDock:SetState(GameDock.SUBMENU_STATE)
      if MinigameStartScreen:GetMinigameType() ~= -1 then
        QuestHandler:DismissAll()
      end
    end,
    PopulateWheelSpin = function(self)
      local m = GfxCtrl.Find(self.swf)
      m:Invoke("setWheelData_lua", Ui.GetRepeatingActivityCount("wheel"), Ui.GetRepeatingActivityNextTime("wheel"))
    end,
    PopulateItemOfTheDay = function()
      local ds = DsTable.Find(PortalHandler.dsItemOfTheDay)
      if ds and ds:GetRowCount() > 0 then
        local name = ds:GetData(0, 3)
        local disc = ds:GetData(0, 4)
        local itemId = ds:GetData(0, 0)
        local catId = ds:GetData(0, 2)
        local iconId = ds:GetData(0, 6)
        local tint = ds:GetData(0, 7)
        local orgPrice = ds:GetData(0, 5)
        local newPrice = ds:GetData(0, 35)
        local m = GfxCtrl.Find(ActivityPortal.swf)
        m:Invoke("setIOTDItem_lua", name, disc, itemId, catId, iconId, tint, orgPrice, newPrice)
      end
    end,
    UpdateWalletInfo = function(self, amount)
      local m = GfxCtrl.Find(self.swf)
