      for row = 0, rows - 1 do
        m:Invoke("addNewsItem_lua", WelcomeInfo:GetData(row, 0), WelcomeInfo:GetData(row, 1))
      end
    end,
    OnProfileChange = function(self)
      self.bPickNewActivitiesOnNextShow = true
    end,
    PickActivities = function(self)
      Ui.ClearActivityDatasource(self.PickedActivitiesDsName)
      self.nActivitiesAddedPerSection = {
        0,
        0,
        0,
        0,
        0,
        0,
        0,
        0
      }
      self.tActivitySectionTable = {}
      local dsPickedActivities = DsTable.Find(self.PickedActivitiesDsName)
      local dsTable = DsTable.Find(self.FeaturedActivitiesDsName)
      local numRows = dsTable:GetRowCount()
      for i = 0, numRows - 1 do
        self:PickActivityFromDS(self.FeaturedActivitiesDsName)
      end
      self:PickActivityFromDS(self.CombatActivitiesDsName)
      self:PickActivityFromDS("Activities.MemberOnly")
      self:PickActivityFromDS(self.FishingActivitiesDsName)
      self:PickActivityFromDS(self.ForgingActivitiesDsName)
      self:PickActivityFromDS(self.CookingActivitiesDsName)
      self:PickActivityFromDS(self.TowerDefenseActivitiesDsName)
      self:PickActivityFromDS(self.MiningActivitiesDsName)
      self:PickActivityFromDS(self.MeetingActivitiesDsName)
      self:PickActivityFromDS(self.SoccerActivitiesDsName)
      self:PickActivityFromDS(self.DerbyActivitiesDsName)
      self:PickActivityFromDS(self.RacingActivitiesDsName)
      self:PickActivityFromDS(self.TCGActivitiesDsName)
      self:PickActivityFromDS(self.MatchThreeActivitiesDsName)
      self:PickActivityFromDS(self.MiscActivitiesDsName)
    end,
    PickActivityFromDS = function(self, dsName)
      local dsTable = DsTable.Find(dsName)
      if dsTable then
        local numRows = dsTable:GetRowCount()
        if numRows > 0 then
          local startingIndex = math.random(1, numRows) - 1
          local activityId, activityPositioinId, isPreferred, isPickedAlready
          for i = 0, numRows - 1 do
            local currentIndex = (startingIndex + i) % numRows
            activityId = tonumber(dsTable:GetData(currentIndex, self.cDSColumnId))
            activityPositionId = tonumber(dsTable:GetData(currentIndex, self.cDSColumnActivityPositionId))
            bIsPreferred = tonumber(dsTable:GetData(currentIndex, self.cDSColumnPreferred)) == 1
            local tutorialId = tonumber(dsTable:GetData(currentIndex, self.cDSTutorialActivityId))
            if tutorialId > 0 then
              local tutorialDsTable = DsTable.Find(self.TutorialActivitiesDsName)
              if tutorialDsTable then
                local numRows2 = tutorialDsTable:GetRowCount()
                for n = 0, numRows2 - 1 do
                  if tutorialId == tonumber(tutorialDsTable:GetData(n, self.cDSColumnId)) then
                    activityId = tutorialId
                    activityPositionId = tonumber(tutorialDsTable:GetData(n, self.cDSColumnActivityPositionId))
                    bIsPreferred = tonumber(tutorialDsTable:GetData(n, self.cDSColumnPreferred)) == 1
                    break
                  end
                end
              end
            end
            bIsPickedAlready = self:IsActivityIdPickedAlready(activityId)
            if activityId > 0 and not bIsPickedAlready and bIsPreferred then
              if activityPositionId == 0 then
                activityPositionId = self:FindLeastPopulatedSectionId()
                if 0 < activityPositionId then
                  self.tActivitySectionTable[activityId] = activityPositionId
                end
              else
              end
              if 0 < activityPositionId and self.nActivitiesAddedPerSection[activityPositionId] and self.nActivitiesAddedPerSection[activityPositionId] < self.cMaxActivityPerSection then
                Ui.AddIdToActivityDatasource(self.PickedActivitiesDsName, activityId)
                self.nActivitiesAddedPerSection[activityPositionId] = self.nActivitiesAddedPerSection[activityPositionId] + 1
                return activityId
              else
              end
            else
            end
          end
        else
          print("No entry in ds: " .. dsName .. " to pick activity from.")
        end
      else
        print("DS table cannot be found: " .. dsName)
      end
      print("No activity added from " .. dsName)
      return 0
    end,
    FindLeastPopulatedSectionId = function(self)
      for i = 0, self.cMaxActivityPerSection do
        for sectionId = 1, self.cTotalSections do
          if self.nActivitiesAddedPerSection[sectionId] == i then
            return sectionId
          end
        end
      end
      return -1
    end,
    IsActivityIdPickedAlready = function(self, id)
      local dsPickedActivities = DsTable.Find(self.PickedActivitiesDsName)
      if dsPickedActivities == nil then
        return false
      end
      local numRows = dsPickedActivities:GetRowCount()
      for i = 0, numRows - 1 do
        if tonumber(id) == tonumber(dsPickedActivities:GetData(i, self.cDSColumnId)) then
          return true
        end
      end
      return false
    end,
    cDSColumnId = 0,
    cDSColumnDisplayNameId = 1,
    cDSColumnDisplayDescriptionId = 2,
    cDSColumnNameId = 3,
    cDSColumnDescriptionId = 4,
    cDSColumnCategory = 5,
    cDSColumnImageSetId = 6,
    cDSColumnActivityPositionId = 7,
    cDSColumnCanPlayerJoin = 8,
    cDSColumnFeatured = 9,
    cDSColumnPreferred = 10,
    cDSFeaturedRewardTooltipStrId = 11,
    cDSTutorialActivityId = 12,
    cDSAppSystemId = 13,
    cDSIsMembersOnly = 14,
    AddActivitiesToFlash = function(self)
      local dsPickedActivities = DsTable.Find(self.PickedActivitiesDsName)
      local swfWindow = GfxCtrl.Find(self.swf)
      if dsPickedActivities == nil or dsPickedActivities:GetRowCount() == 0 then
        self:PickActivities()
      end
      dsMemberActivities = DsTable.Find("Activities.MemberOnly")
      local mNumRows = dsMemberActivities:GetRowCount()
      local mIndex = math.random(1, mNumRows) - 1
      swfWindow:Invoke("setMemberActivity", tonumber(dsMemberActivities:GetData(mIndex, self.cDSColumnId)), tonumber(dsMemberActivities:GetData(mIndex, self.cDSAppSystemId)), Ui.GetStringById(tonumber(dsMemberActivities:GetData(mIndex, self.cDSColumnDisplayNameId))), tonumber(dsMemberActivities:GetData(mIndex, self.cDSColumnImageSetId)))
      dsPickedActivities = DsTable.Find(self.PickedActivitiesDsName)
      local numRows = dsPickedActivities:GetRowCount()
      swfWindow:Invoke("SetText", Ui.GetString("ActivityPortalTitleText"), Ui.GetString("ActivityPortalShuffleText"), Ui.GetString("ActivityPortalButtonPlay"), Ui.GetString("ActivityPortalButtonGo"))
      local activityId, activityName, activityDescription, activityCategoryId, activityImageSetId, activityPositioinId, activityCanPlayerJoin, activityIsFeatured
      for i = 0, numRows - 1 do
        local activityId = tonumber(dsPickedActivities:GetData(i, self.cDSColumnId))
        local activityName = Ui.GetStringById(tonumber(dsPickedActivities:GetData(i, self.cDSColumnDisplayNameId)))
        local activityTooltipName = Ui.GetStringById(tonumber(dsPickedActivities:GetData(i, self.cDSColumnNameId)))
        local featuredActivityTooltipDescription = Ui.GetStringById(tonumber(dsPickedActivities:GetData(i, self.cDSFeaturedRewardTooltipStrId)))
        local activityDescription = Ui.GetStringById(tonumber(dsPickedActivities:GetData(i, self.cDSColumnDisplayDescriptionId)))
        local activityCategoryId = tonumber(dsPickedActivities:GetData(i, self.cDSColumnCategory))
        local activityImageSetId = tonumber(dsPickedActivities:GetData(i, self.cDSColumnImageSetId))
        local activityPositionId = tonumber(dsPickedActivities:GetData(i, self.cDSColumnActivityPositionId))
        local activityCanPlayerJoin = tonumber(dsPickedActivities:GetData(i, self.cDSColumnCanPlayerJoin))
        local activityIsFeatured = tonumber(dsPickedActivities:GetData(i, self.cDSColumnFeatured))
        local tutorialActivityId = tonumber(dsPickedActivities:GetData(i, self.cDSTutorialActivityId))
        local activityAppSystemId = tonumber(dsPickedActivities:GetData(i, self.cDSAppSystemId))
        local isMembersOnly = 0
        if self.cDSIsMembersOnly < dsPickedActivities:GetColumnCount() then
          isMembersOnly = tonumber(dsPickedActivities:GetData(i, self.cDSIsMembersOnly))
        end
        if activityId == 1059 then
          isMembersOnly = 1
        end
        self.nActivityCounter = self.nActivityCounter % 8 + 1
        if activityPositionId == 0 then
          activityPositionId = self.tActivitySectionTable[activityId]
        end
        swfWindow:Invoke("AddActivity", activityId, activityName, activityCategoryId, activityImageSetId, activityPositionId, activityCanPlayerJoin, activityIsFeatured, activityTooltipName, featuredActivityTooltipDescription, 0, tutorialActivityId, activityAppSystemId, isMembersOnly)
      end
      swfWindow:Invoke("OnFinishedAddingActivities")
    end,
    SetAnimationType = function(self, type)
      local swfWindow = GfxCtrl.Find(self.swf)
      swfWindow:Invoke("SetAnimationType", type)
    end,
    SocialActivityTeleportStart = function(self)
      ActivityCalendar:Hide()
      ActivityPortal:Hide()
      HUD:showMain()
    end,
    Enable = function(self, bool)
      if bool == nil then
        bool = true
      end
      if bool then
        self:HideClickGobbler()
        if MinigameStartScreen.visible then
          GameDock:SetState(GameDock.SUBMENU_STATE)
          self.NavOriginalX = nil
          self.NavOriginalY = nil
        end
      else
        self:ShowClickGobbler()
        if MinigameStartScreen.visible then
          GameDock:SetState(GameDock.DISABLED_STATE)
          self.NavOriginalX, self.NavOriginalY = NavigationHandler.GetWindow():GetPosition()
          local sw, sh = Window.GetCanvasSize()
        end
      end
    end,
    GetGobblerWindow = function(self)
      return Window.Find("Main.wndClickGobbler")
    end,
    HideClickGobbler = function(self)
      self:GetGobblerWindow():Hide()
      GfxCtrl.Find(Ui.GetName("Main.wndClickGobbler.swfClickGobbler")):Unload()
    end,
    ShowClickGobbler = function(self)
      local sw, sh = Window.GetCanvasSize()
      self:GetGobblerWindow():Show()
      self:GetGobblerWindow():SetPosition(0, 0)
      self:GetGobblerWindow():SetSize(sw, sh)
    end,
    IsActivityInDS = function(self, activityId, dsName)
      local dsTable = DsTable.Find(dsName)
      if activityId and dsTable then
        activityId = tonumber(activityId)
        local numRows = dsTable:GetRowCount()
        for n = 0, numRows - 1 do
          if activityId == tonumber(dsTable:GetData(n, self.cDSColumnId)) then
            return true
          end
        end
      end
      return false
    end,
    OnJoinError = function(self, errorStrId)
      NotificationHandler:AlertMessage(Ui.GetStringById(errorStrId), nil, "0xFFFF00")
    end,
    DisableMouse = function(self)
      local swfWindow = GfxCtrl.Find(self.swf)
      swfWindow:Invoke("disableMouse")
    end,
    EnableMouse = function(self)
      local swfWindow = GfxCtrl.Find(self.swf)
      swfWindow:Invoke("enableMouse")
    end,
    OnUserEvent = function(self, a, b, c, d, e, f)
      if tostring(a) == "CloseMainManager" then
        self:Hide()
      elseif a == "gotoCoinStore" then
        ActivityPortal:Hide()
        MarketplaceHandler:Show(MarketplaceEnum.COIN_STORE)
      elseif a == "gotoSCStore" then
        ActivityPortal:Hide()
        MarketplaceHandler:Show(MarketplaceEnum.STORE_SC)
      elseif a == "calendarButtonPressed" then
        self:DisableMouse()
        ActivityCalendar:Show()
      elseif tostring(a) == "GetCategoryData" then
        self:GetCategoryData(b)
      elseif tostring(a) == "DebugMsg" then
      elseif tostring(a) == "RequestActivity" or a == "memberActivityButtonPressed" then
        print("RequestActivity a " .. tostring(a))
        print("RequestActivity b " .. tostring(b))
        print("RequestActivity c " .. tostring(c))
        print("RequestActivity d " .. tostring(d))
        if MinigameStartScreen:GetMinigameType() ~= -1 then
          return
        end
        if b then
          if c and tonumber(c) ~= 0 and not self:IsActivityInDS(b, self.FeaturedActivitiesDsName) then
            NotificationHandler:SystemMessage(Ui.GetString("426671"))
            local swfWindow = GfxCtrl.Find(self.swf)
            swfWindow:Invoke("ShuffleActivities")
            return 0
          end
          local bTutorial = 0
          if self:IsActivityInDS(b, self.TutorialActivitiesDsName) then
            bTutorial = 1
            self.bPickNewActivitiesOnNextShow = true
          end
          if tonumber(b) == 1059 then
            if Ui.IsMember() then
              ActivityPortal:Hide()
            else
              MembershipHandler:Show()
              return
            end
          end
          Ui.IncrementClientLuaMetric("ActivityPortal_PlayActivity_" .. tostring(b) .. "_" .. tostring(bTutorial))
          Ui.RequestToJoinActivity(b, bTutorial)
          if d then
            d = tonumber(d)
            if d == 3 then
            end
          end
        end
      elseif a == "startWheelMinigame" then
        ActivityPortal:Hide()
        MiniGameFlashC.StartWheel()
      elseif tostring(a) == "RequestShuffle" then
        print("Shuffling activities")
        Ui.IncrementClientLuaMetric("ActivityPortal_Shuffle")
        self:PickActivities()
        self:AddActivitiesToFlash()
        TutorialDialog:Hide()
      elseif a == "ExitButtonClicked" then
        ActivityPortal:Hide()
      elseif a == "MembershipButtonClicked" then
        MembershipHandler:Show()
      elseif tostring(a) == "PlaySound" then
        if tonumber(b) then
          local id = Ui.PlaySoundFromDefinition(tonumber(b), 100, 0)
        else
          HUD:PlaySound(b)
        end
      elseif a == "ASPrint" then
        print(a .. ">> " .. b)
      else
        print("Unhandle user event in ActivityPortal: " .. a)
      end
    end
  }
  function Main_wndActivityPortal_swfActivityPortal_OnUserEvent(a, b, c, d, e, f)
    ActivityPortal:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndActivityPortal_swfActivityPortal_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
;(function()
  MinigameStartScreen = {
    m_Enabled = true,
