    Show = function(self, mode)
      if Housing.isInInstance then
        Logger:print("minigamestartscreen", "isInInstance")
        return
      end
      if HousingPreviewHandler.isBuyingFromHousingPreview then
        Logger:print("minigamestartscreen", "isBuyingFromHousingPreview")
        return
      end
      if mode ~= self.MODE_SHOW_FROM_MARKETPLACE then
        if self.visible then
          return
        end
        self.visible = true
        self:print("Show( " .. tostring(mode) .. " )")
        NonModalContext:AddContext(self)
        DataSourceConnection:Connect("BaseClient.LeaderBoard", MinigameStartScreen, "OnLeaderBoardData")
        DataSourceConnection:Connect(DataSources[DS_MINI_GAME_REWARD_PREVIEW], MinigameStartScreen, "OnRewardsData")
        if ActivityPortal.isShown then
          ActivityPortal:Enable(false)
        else
          if TradeHandler.visible == true then
            Trade.Cancel()
          end
          HUD:hideMain()
        end
      end
      Ui.SetMovementEnabled(0)
      self.GetWindow():Show()
      self.GetSwf():Load()
      self.GetSwf():Invoke("window.setInitCompleteCallback")
      local sw, sh = Window.GetCanvasSize()
      if JobBrowser.isShown == true then
        JobBrowser:Hide()
      end
      if BrowserHandler.visible then
        sh = sh + self.yMod
      end
      self.GetWindow():SetSize(sw, sh)
      self.GetSwf():Invoke("window.move", sw * 0.5, -sh)
      self:CheckLoading()
      self:GetRewardsData()
      if self:GetHighScoreType(self:GetMinigameType()) == 2 then
        self.GetSwf():Invoke("setHighScoresString", Ui.GetString("FastestTime"))
      end
      self:GetHighScores(self:GetMinigameType(), self:GetMinigameId(), 500, 500)
      self:ParseMinigameStartData()
      TutorialDialog:Hide()
    end,
    OnResize = function(self)
      local sw, sh = Window.GetCanvasSize()
      if BrowserHandler.visible then
        sh = sh + self.yMod
      end
      self.GetWindow():SetSize(sw, sh)
    end,
    SetLegend = function(self, legend)
      Logger:print("minigamestartscreen", "Setting Legend to " .. legend)
      self.GetWindow():SetProperty("Legend", legend)
    end,
    Hide = function(self, mode, go)
      Logger:print("minigamestart", "hiding )")
      if tonumber(mode) == 1 then
        Logger:print("minigamestartscreen.lua", "clearing game dock nav bar")
        GameDock_PS3:NavigationExit()
        GameDock_PS3:SetVisibility(1)
      end
      if self ~= MinigameStartScreen then
        self = MinigameStartScreen
      end
      if not self.visible then
        return
      end
      self:print("Hide( " .. tostring(mode) .. " )")
      if tonumber(mode) == 0 then
        self.GetSwf():Invoke("window.closeFlyout", "FlyoutHidden")
        if self.closeFunction then
          self.closeFunction()
        end
      elseif tonumber(mode) == 1 then
        self.GetSwf():Invoke("window.closeFlyout", "HideToStartGame")
        if JobHandler.screenActive == true then
          JobHandler:ModeSwitch(0)
          JobHandler:Hide()
        end
        if Atlas.active == true then
          Atlas:Hide()
