    end,
    GetHighScores = function(self, gameType, gameId, pageSize, page, topRank)
      local url = "login=false"
      if not gameType or type(gameType) ~= "number" then
        return "(Error) Invalid[ gameType=" .. gameType .. " ]"
      end
      url = url .. "&leaderboardType=" .. self:GetHighScoreType(gameType)
      if not gameId or type(gameId) ~= "number" then
        return "(Error) Invalid[ gameId=" .. gameId .. " ]"
      end
      url = url .. "&leaderboardId=" .. gameId
      if not pageSize or type(pageSize) ~= "number" then
        pageSize = 10
      end
      url = url .. "&pageSize=" .. pageSize
      if not page or type(page) ~= "number" then
        page = 10
      end
      url = url .. "&page=" .. page
      if not topRank or type(topRank) ~= "boolean" then
        topRank = false
      end
      url = url .. "&topRank=" .. tostring(topRank)
      Ui.RequestLeaderBoardData(url)
    end,
    OnLeaderBoardData = function(self)
      self.leaderboardsUpdated = true
      self.GetSwf():Invoke("window.updateListData", self.MODE_SCORES_LIST, DsTable.Find("BaseClient.LeaderBoard.Entries"):GetRowCount())
    end,
    GetRewardsData = function(self)
      self.RewardsData = {}
      local ds = DsTable.Find(DataSources[DS_MINI_GAME_REWARD_PREVIEW_ENTRIES])
      if not ds then
        return
      end
      local rowCount = ds:GetRowCount()
      local columnCount = ds:GetColumnCount()
      for i = 0, ds:GetRowCount() - 1 do
        local item = {}
        local hiddenColumn = 11
        for c = 0, ds:GetColumnCount() - 1 do
          item[ds:GetColumnName(c)] = ds:GetData(i, c)
        end
        if tonumber(ds:GetData(i, hiddenColumn)) ~= 1 then
          table.insert(self.RewardsData, item)
        end
        if #self.RewardsData >= 4 then
          return
        end
      end
    end,
    OnRewardsData = function(self)
      self:print("OnRewardsData")
      self:GetRewardsData()
      self.GetSwf():Invoke("window.updateListData", self.MODE_REWARDS_LIST, #self.RewardsData)
    end,
    PopulateRewards = function(self, offset, count, ds, callback)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if #self.RewardsData > 0 then
        local numRows = #self.RewardsData
        if numRows > 0 then
          str = self:SerializeTableData(self.RewardsData, offset, count)
          self.GetSwf():Invoke(callback, str, numRows)
        else
          self.GetSwf():Invoke(callback, str, 0)
        end
      else
        self.GetSwf():Invoke(callback, str, 0)
      end
    end,
    SerializeTableData = function(self, tbl, offset, count)
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      local offset = math.max(offset, 0)
      local countTo = math.min(offset + count, #tbl)
      for i = offset, countTo - 1 do
        local c = 0
        for k, v in pairs(tbl[i + 1]) do
          if c > 0 then
            data = data .. propDelim
          end
          data = data .. k .. valueDelim .. v
          c = c + 1
        end
        if i < #tbl - 1 and count > 1 then
          data = data .. itemDelim
        end
      end
      return data
    end,
    SetupMarketAdInfo = function(self, referrerId, referrerContext)
      self.MarketplaceAdReferrerId = referrerId
      self.MarketplaceAdReferrerContext = referrerContext
      self:MarketDatasourceUpdate()
    end,
    MarketDatasourceUpdate = function(self)
      if MinigameStartScreen.isLoading == true or MinigameStartScreen.isStartDataParsed == false then
        MinigameStartScreen.isWaitingForAd = true
        return
      end
      local ds = DsTable.Find("BaseClient.MiniGame.MarketplaceAd")
      local rowCount = 0
      if ds then
        rowCount = ds:GetRowCount()
      end
      Logger:print("minigamestartscreen", "MarketDatasourceUpdate rowCount" .. rowCount)
      MinigameStartScreen.GetSwf():SoftInvoke("window.setupMarketData", rowCount)
    end,
    GetMarketItem = function(self, index, callback)
      local itemDelim = "[ITEM]"
      local propDelim = "[PROP]"
      local valueDelim = "[VAL]"
      local ds = DsTable.Find("BaseClient.MiniGame.MarketplaceAd")
      local data = ""
      local rowCount = ds:GetRowCount()
      local colCount = ds:GetColumnCount()
      if ds and rowCount > tonumber(index) then
        for c = 0, colCount - 1 do
          if c > 0 then
            data = data .. propDelim
          end
          data = data .. ds:GetColumnName(c) .. valueDelim .. ds:GetData(tonumber(index), c)
        end
      end
      Logger:print("minigamestartscreen", "rowCount" .. rowCount)
      Logger:print("minigamestartscreen", "data" .. data)
      self.GetSwf():Invoke(callback, data)
    end,
    GotoMarket = function(self, itemId)
