    end,
    FlyoutHiddenToMarket = function(self)
      local sw, sh = Window.GetCanvasSize()
      self.GetSwf():Invoke("window.moveTo", "undefined", -sh, "HideToMarket")
    end,
    HideToMarket = function(self)
      self.GetSwf():Unload()
      self.GetWindow():Hide()
