      MarketplaceHandler:ShowCustomView(self:GetMinigameName(), "BaseClient.MiniGame.MarketplaceAd", MinigameStartScreen.ShowFromMarket, tonumber(self.MarketplaceAdReferrerId), tonumber(self.MarketplaceAdReferrerContext), true)
      if ActivityPortal.isShown then
        QuestHandler.bringBackPortal = true
        ActivityPortal:Hide()
      end
    end,
    ShowFromMarket = function()
      if Housing.isInInstance then
        Logger:print("minigamestartscreen", "isInInstance")
        return
      end
      if HousingPreviewHandler.isBuyingFromHousingPreview then
        Logger:print("minigamestartscreen", "isBuyingFromHousingPreview")
        return
      end
      if QuestHandler.bringBackPortal then
        QuestHandler.bringBackPortal = false
        QuestHandler:Show()
        ActivityPortal:Enable(false)
      end
      MinigameStartScreen:print("ShowFromMarket")
      MinigameStartScreen:Show(MinigameStartScreen.MODE_SHOW_FROM_MARKETPLACE)
      MinigameStartScreen:MarketDatasourceUpdate()
      MinigameStartScreen:CheckLoading()
      MinigameStartScreen:OnRewardsData()
      if MinigameStartScreen.leaderboardsUpdated then
        MinigameStartScreen:OnLeaderBoardData()
      end
    end,
    RequestData = function(self, offset, count, view, callback)
      if tonumber(view) == self.MODE_REWARDS_LIST then
        self:PopulateRewards(tonumber(offset), tonumber(count), DsTable.Find(DataSources[DS_MINI_GAME_REWARD_PREVIEW_ENTRIES]), callback)
      elseif tonumber(view) == self.MODE_SCORES_LIST then
        if not self.leaderboardsUpdated then
          self.GetSwf():Invoke(callback, "", 0)
          return
        end
        self:Populate(tonumber(offset), tonumber(count), DsTable.Find("BaseClient.LeaderBoard.Entries"), callback, view)
      end
    end,
    Populate = function(self, offset, count, ds, callback, view)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if ds then
        local numRows = ds:GetRowCount()
        if numRows > 0 then
          local checkHidden = false
          if tonumber(view) == 0 then
            checkHidden = true
          end
          str = self:SerializeData(ds, offset, count, checkHidden)
          self.GetSwf():Invoke(callback, str, numRows)
        else
          self.GetSwf():Invoke(callback, str, 0)
        end
      else
        self.GetSwf():Invoke(callback, str, 0)
      end
    end,
    SerializeData = function(self, ds, offset, count, ignoreHidden)
      local hiddenCol = 11
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      local offset = math.max(offset, 0)
      local countTo = math.min(offset + count, ds:GetRowCount())
      for i = offset, countTo - 1 do
        if not ignoreHidden or ignoreHidden and tonumber(ds:GetData(i, hiddenCol)) == 0 then
          for c = 0, ds:GetColumnCount() - 1 do
            if c > 0 then
              data = data .. propDelim
            end
            data = data .. ds:GetColumnName(c) .. valueDelim .. ds:GetData(i, c)
          end
          if i < ds:GetRowCount() - 1 and count > 1 then
            data = data .. itemDelim
          end
        end
      end
      return data
    end,
    OnUserEvent = function(func, b, ...)
      if func == "playSound" or func == "PlaySound" then
        HUD:PlaySound(b)
      elseif func == "ShowBrowser" then
        Logger:print("minigamestartscreen.lua", "ShowBrowser" .. tostring(MinigameStartScreen:GetMinigameType()))
        if MinigameStartScreen:GetMinigameType() == 10 or MinigameStartScreen:GetMinigameType() == 11 or MinigameStartScreen:GetMinigameType() == 4 then
          MinigameStartScreen:ShowBrowser()
        end
      elseif func == "HideBrowser" then
        MinigameStartScreen:HideBrowser()
      elseif MinigameStartScreen[tostring(func)] then
        MinigameStartScreen[tostring(func)](MinigameStartScreen, b, ...)
      else
        MinigameStartScreen:print(func)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" and MinigameStartScreen.inputFocus == false then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[MinigameStartScreen]\t" .. message)
      end
    end
  }
  Main_wndMinigameStartScreen_swfMinigameStartScreen_OnUserEvent = MinigameStartScreen.OnUserEvent
  Main_wndMinigameStartScreen_swfMinigameStartScreen_OnFocus = MinigameStartScreen.OnFocus
end)()
