            table.insert(icon, iconID)
            table.insert(text, Ui.GetStringById(name))
          end
        end
        for ii = 0, 2 do
          if icon[ii] == nil then
            icon[ii] = ""
            text[ii] = ""
          end
        end
        Logger:print("ActivityCalendar.lua", "date(" .. self.curMonth .. "-" .. calDay .. "-" .. self.curYear .. ") epoch(" .. myLocalDate .. ")")
        self.pane:Invoke("setDay", i, icon[0], icon[1], icon[2], txt, "G" .. myLocalDate .. "/" .. dow, text[0], text[1], text[2])
      end
      self.pane:Invoke("setStartAndEndOfMonth", myWeekday, daysInMonth)
      Logger:print("ActivityCalendar.lua", "setStartAndEndOfMonth start(" .. tostring(myWeekday) .. ") daysInMonth(" .. tostring(daysInMonth) .. ")")
      if self.firstShow == true then
        self.firstShow = false
        if gotToday == true then
          Logger:print("ActivityCalendar.lua", "auto selecting today")
          self.pane:Invoke("selectCurrentDay")
        end
      end
