    GetCategoryData = function(self, catID)
      self.lastCatID = catID
      catID = string.sub(tostring(catID), 2)
      Logger:print("ActivityCalendar.lua", " ### ActivityCalendar GetCategoryData() " .. catID)
      local stringSplit = self:strsplit("/", catID)
      local m = stringSplit[1]
      local d = stringSplit[2]
      local y = stringSplit[3]
      local dow = stringSplit[4]
      self.pane:Invoke("setDayTitle", Ui.GetDateString(m, d, y, dow))
      catID = self:strjoin("/", {
        m,
        d,
        y
      })
      if self.activitiesForDay[catID] then
        for k, v in pairs(self.activitiesForDay[catID]) do
          local id, iconID, name, desc, startDate, startTime, secondsUntilStart, secondsUntilEnd, startTimeDisplay, longName, rewardTT = self:GetActivityDetails(v)
          local activeNow = 0
          longName = "[" .. startTimeDisplay .. "] " .. Ui.GetStringById(longName)
          if secondsUntilStart <= 0 and secondsUntilEnd >= 0 then
            activeNow = 1
          end
          Logger:print("ActivityCalendar.lua", "addMainItem(" .. tostring(iconID) .. ", " .. name .. ") toStart(" .. secondsUntilStart .. ") toEnd(" .. secondsUntilEnd .. ") active(" .. activeNow .. ") desc(" .. desc .. ") name(" .. longName .. ")")
          if activeNow == 1 then
            secondsUntilStart = secondsUntilEnd
          end
          self.pane:Invoke("addMainItem", iconID, longName, Ui.GetStringById(desc), id, activeNow, secondsUntilStart, rewardTT)
        end
