    GetActivitiesPerDay = function(self)
      Logger:print("ActivityCalendar.lua", " ### GetActivitiesPerDay")
      self.activitiesForDay = {}
      self.activityIdsForDay = {}
      if self.ds then
        local numRows = self.ds:GetRowCount()
        for i = 0, numRows - 1 do
          local epoch = ""
          local localDate = tostring(self.ds:GetData(i, DsCol.StartDateNonLocalized))
          local activityID = tostring(self.ds:GetData(i, DsCol.ActivityId))
          localDate = self:GetGoodDateString(localDate)
          if self.activitiesForDay[localDate] == nil then
            self.activitiesForDay[localDate] = {}
            self.activityIdsForDay[localDate] = {}
          end
          table.insert(self.activitiesForDay[localDate], i)
          table.insert(self.activityIdsForDay[localDate], activityID)
        end
        return activities
      end
