    GetGoodDateString = function(self, badDate)
      local stringSplit = self:strsplit("/", badDate)
      local m = stringSplit[1]
      local d = stringSplit[2]
      local y = stringSplit[3]
      m = string.gsub(m, " ", "")
      d = string.gsub(d, " ", "")
      m = string.sub("0" .. m, -2)
      d = string.sub("0" .. d, -2)
      return self:strjoin("/", {
        m,
        d,
        y
      })
    end,
    GetActivityDetails = function(self, rowNum)
      if self.ds then
        local id = tostring(self.ds:GetData(rowNum, DsCol.ActivityId))
        local iconID = tostring(self.ds:GetData(rowNum, DsCol.ImageSetId))
        local name = tostring(self.ds:GetData(rowNum, DsCol.DisplayNameId))
        local longName = tostring(self.ds:GetData(rowNum, DsCol.NameId))
        local desc = tostring(self.ds:GetData(rowNum, DsCol.DescriptionId))
        local startDate = tostring(self.ds:GetData(rowNum, DsCol.LocalStartDate))
        local displayStartTime = tostring(self.ds:GetData(rowNum, DsCol.DisplayStartTime))
        local endDate = tostring(self.ds:GetData(rowNum, DsCol.LocalEndDate))
        local displayEndTime = tostring(self.ds:GetData(rowNum, DsCol.DisplayEndTime))
        local secondsUntilStart = tonumber(self.ds:GetData(rowNum, DsCol.SecondsUntilStart))
        local secondsUntilEnd = tonumber(self.ds:GetData(rowNum, DsCol.SecondsUntilEnd))
        local startTime = tostring(self.ds:GetData(rowNum, DsCol.LocalStartTime))
        local endTime = tostring(self.ds:GetData(rowNum, DsCol.LocalEndTime))
        local rewardTT = tonumber(self.ds:GetData(rowNum, DsCol.FeaturedRewardTooltipStringId))
        if rewardTT > 0 then
          rewardTT = Ui.GetStringById(rewardTT)
        else
          rewardTT = ""
        end
        startTime = string.sub(startTime, 1, 5)
        endTime = string.sub(endTime, 1, 5)
        if string.sub(startTime, -1, -1) == ":" then
          startTime = string.sub(startTime, 1, -2)
        end
        if string.sub(endTime, -1, -1) == ":" then
          endTime = string.sub(endTime, 1, -2)
        end
        if startTime == "00:00" and endTime == "23:59" or displayStartTime == "12:00 AM" and displayEndTime == "11:59 PM" then
          displayStartTime = Ui.GetString("426329")
        end
        return id, iconID, name, desc, startDate, startTime, secondsUntilStart, secondsUntilEnd, displayStartTime, longName, rewardTT
      end
      return nil
    end,
    GetAppSystemIdForActivityWithId = function(self, id)
      local ds = DsTable.Find("Activities.All")
      if ds then
        local numRows = ds:GetRowCount()
        for i = 0, numRows - 1 do
          local myID = tonumber(ds:GetData(i, 0))
          local appSystemId = tonumber(ds:GetData(i, 13))
          if myID == tonumber(id) then
            return appSystemId
          end
        end
      end
      return nil
    end,
    IsActivityActiveToday = function(self, id)
      local todayDay, todayMonth, todayYear = Ui.GetDayMonthYear()
      local myLocalDate = self:GetGoodDateString(self:strjoin("/", {
        todayMonth,
        todayDay,
        todayYear
      }))
      if table.getn(self.activityIdsForDay) <= 0 or self.activityIdsForDay == nil then
        self:GetActivitiesPerDay()
      end
      if self.activityIdsForDay[myLocalDate] then
        for k, activityID in pairs(self.activityIdsForDay[myLocalDate]) do
          if tonumber(activityID) == tonumber(id) then
            return true
          end
        end
      end
      return false
    end,
    LaunchActivity = function(self, id)
      if self.isShown then
        function MinigameStartScreen.closeFunction()
          ActivityCalendar:Show()
        end
      end
      QuestHandler:Hide()
      if self:IsSocialActivity(id) then
        if self:IsActivityActiveToday(id) then
          QuestHandler:DismissAll()
          Ui.RequestToJoinActivity(id)
        else
          self:Show()
        end
      else
        Ui.RequestToJoinActivity(id)
      end
    end,
    IsSocialActivity = function(self, id)
      local appSystemId = self:GetAppSystemIdForActivityWithId(id)
      Logger:print("ActivityCalendar.lua", " ### IsSocialActivity id(" .. tostring(id) .. ") cat(" .. tostring(appSystemId) .. ")")
      if appSystemId == 3 then
        return true
      end
      return false
    end,
    strjoin = function(self, delimiter, list)
      local len = table.getn(list)
      if len == 0 then
        return ""
      end
      local string = list[1]
      for i = 2, len do
        string = string .. delimiter .. list[i]
      end
      return string
    end,
    strsplit = function(self, inSplitPattern, myStr)
      local outResults = {}
      local theStart = 1
      local theSplitStart, theSplitEnd = string.find(myStr, inSplitPattern, theStart)
      while theSplitStart do
        table.insert(outResults, string.sub(myStr, theStart, theSplitStart - 1))
        theStart = theSplitEnd + 1
        theSplitStart, theSplitEnd = string.find(myStr, inSplitPattern, theStart)
      end
      table.insert(outResults, string.sub(myStr, theStart))
      return outResults
    end,
    OnUserEvent = function(self, a, b, c, d, e, f)
      Logger:print("ActivityCalendar.lua", " ### ActivityCalendar OnUserEvent() a(" .. tostring(a) .. ") b(" .. tostring(b) .. ")")
      if tostring(a) == "playSound" or tostring(a) == "PlaySound" then
        if b == "DockOver" then
          HUD:PlaySound("DockOver")
          return
        end
        Lobby:OnUserEvent(a, b)
      elseif tostring(a) == "CloseMainManager" then
        QuestHandler:Hide()
      elseif tostring(a) == "GetCategoryData" then
        Ui.IncrementClientLuaMetric("ActivityCalendar_" .. tostring(a))
        self:GetCategoryData(b)
      elseif tostring(a) == "ResendCategoryData" then
        self:GetCategoryData(self.lastCatID)
      elseif tostring(a) == "ReadyToAcceptData" then
        self:PopulateCategories()
      elseif tostring(a) == "PreviousMonth" then
        Ui.IncrementClientLuaMetric("ActivityCalendar_" .. tostring(a))
        self:PopulateCategories(-1)
      elseif tostring(a) == "NextMonth" then
        Ui.IncrementClientLuaMetric("ActivityCalendar_" .. tostring(a))
        self:PopulateCategories(1)
      elseif tostring(a) == "PlayActivity" and b and Ui.RequestToJoinActivity then
        Ui.IncrementClientLuaMetric("ActivityCalendar_PlayActivity_" .. tostring(b))
        self:LaunchActivity(b)
      elseif a == "ExitButtonClicked" then
        QuestHandler:Hide()
        NavigationHandler:EnableBar()
      elseif a == "ASPrint" then
        print("ASPrint: " .. tostring(b))
      end
    end
  }
  function Main_wndActivityCalendar_swfActivityCalendar_OnUserEvent(a, b, c, d, e, f)
    ActivityCalendar:OnUserEvent(a, b, c, d, e, f)
  end
  function Main_wndActivityCalendar_swfActivityCalendar_OnFocus(a)
    if a == "1" then
      Window.SetFocus()
    end
  end
end)()
