        end
      end
      local lootWheelRewardBundleDS = DsTable.Find(DataSources[DS_MINI_GAME_REWARD_PREVIEW])
      if lootWheelRewardBundleDS then
        local coins = tonumber(lootWheelRewardBundleDS:GetData(0, 3))
        if coins > 0 then
          self.GetSwf():Invoke("AddLootWheelItemData", 22663, 0, coins, Ui.GetString("6513"))
        end
        local xpAmount = tonumber(lootWheelRewardBundleDS:GetData(0, 2))
        if xpAmount > 0 then
          self.GetSwf():Invoke("AddLootWheelItemData", 9, 0, xpAmount, Ui.GetString("426522"))
        end
      end
      self.GetSwf():Invoke("SetLootWheelText", Ui.GetString("Wheel_Congrats"), Ui.GetString("Wheel_YouWon"), Ui.GetString("ButtonClickHere"))
      self:SetStates()
      if showLootWheel then
        self.GetSwf():Invoke("ShowLootWheel")
        self.isLootWheelShown = true
      else
        self.GetSwf():Invoke("initializeState")
        self:LootWheelCompleted()
      end
    end,
    lootWheelIndex,
    StopLootWheelAt = function(self, index)
      if not index then
      end
      self.lootWheelIndex = tonumber(index)
    end,
    SpinLootWheel = function(self)
      local rds = DsTable.Find(DataSources[DS_MINI_GAME_REWARD_PREVIEW_ENTRIES])
      local lootWheelRewardBundleDS = DsTable.Find(DataSources[DS_MINI_GAME_REWARD_PREVIEW])
      if self.lootWheelIndex and rds and lootWheelRewardBundleDS and self.lootWheelIndex > rds:GetRowCount() - 1 then
        local coinsReward = tonumber(lootWheelRewardBundleDS:GetData(0, 3))
        local xpReward = tonumber(lootWheelRewardBundleDS:GetData(0, 2))
        if coinsReward > 0 and self.lootWheelIndex == rds:GetRowCount() then
          local item = {}
          item.Type = -1
          item.Name = Ui.GetString("CoinsScoreScreen")
          item.Description = -1
          item["Icon ID"] = 4809
          item.Quantity = coinsReward
          item["Tint Value"] = ""
          item["Item Id"] = -1
          item["Parameter 2"] = -1
          item.Rarity = -1
          item["Members Only"] = 0
          item.Guid = "Coins"
          item.Hidden = 0
          self:AddRewardItem(item)
        else
          if xpReward > 0 and (coinsReward == 0 and self.lootWheelIndex == rds:GetRowCount() or coinsReward > 0 and self.lootWheelIndex == rds:GetRowCount() + 1) then
            local item = {}
            item.Type = -1
            item.Name = Ui.GetString("StarsScoreScreen")
            item.Description = -1
            item["Icon ID"] = 9
            item.Quantity = xpReward
            item["Tint Value"] = ""
            item["Item Id"] = -1
            item["Parameter 2"] = -1
            item.Rarity = -1
            item["Members Only"] = 0
            item.Guid = "Stars"
            item.Hidden = 0
            self:AddRewardItem(item)
          else
          end
        end
      else
        if self.lootWheelIndex and self.lootWheelIndex >= 0 and self.lootWheelIndex < rds:GetRowCount() then
          local item = {}
          local typeColumn = 0
          local hiddenColumn = 11
          for c = 0, rds:GetColumnCount() - 1 do
            item[rds:GetColumnName(c)] = rds:GetData(self.lootWheelIndex, c)
          end
          if tonumber(rds:GetData(i, typeColumn)) == 1 then
            self:AddRewardItem(item)
          end
        else
        end
      end
      self.GetSwf():Invoke("StopLootWheelAt", self.lootWheelIndex)
      self.isLootWheelSpinning = true
    end,
    ParseScoreAndStatData = function(self)
      local ds = DsTable.Find(DataSources[DS_MINI_GAME_SCORE])
      local rowCount = ds:GetRowCount()
      for i = 0, rowCount - 1 do
        local tbl = self.ScoreData
        if tonumber(ds:GetData(i, 2)) > 100 then
          tbl = self.StatData
        end
        local obj = {}
        for c = 0, ds:GetColumnCount() - 1 do
          obj[ds:GetColumnName(c)] = ds:GetData(i, c)
        end
        table.insert(tbl, obj)
      end
    end,
    RequestRaceData = function(self, offset, count, callback)
      local ds = "BaseClient.VehicleRaceProcessor.RaceResults"
      self:PopulateRace(tonumber(offset), tonumber(count), DsTable.Find(ds), callback)
    end,
    PopulateRace = function(self, offset, count, ds, callback, type)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if #self.RaceData > 0 then
        local numRows = #self.RaceData
        if numRows > 0 then
          str = self:SerializeTableData(self.RaceData, offset, count)
          self.GetSwf():Invoke(callback, str, numRows)
        else
          self.GetSwf():Invoke(callback, str, 0)
        end
      else
        self.GetSwf():Invoke(callback, str, 0)
      end
    end,
    RequestDerbyData = function(self, offset, count, callback)
      local ds = ""
      self:PopulateDerby(tonumber(offset), tonumber(count), DsTable.Find(ds), callback)
    end,
    PopulateDerby = function(self, offset, count, ds, callback, type)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if #self.DerbyData > 0 then
        local numRows = #self.DerbyData
        if numRows > 0 then
          str = self:SerializeTableData(self.DerbyData, offset, count)
          self.GetSwf():Invoke(callback, str, numRows)
        else
          self.GetSwf():Invoke(callback, str, 0)
        end
      else
        self.GetSwf():Invoke(callback, str, 0)
      end
    end,
    RequestStatisticsData = function(self, offset, count, callback)
      local ds = DataSources[DS_MINI_GAME_SCORE]
      self:PopulateStatistics(tonumber(offset), tonumber(count), DsTable.Find(ds), callback)
    end,
    PopulateStatistics = function(self, offset, count, ds, callback, type)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if #self.StatData > 0 then
        local numRows = #self.StatData
        if numRows > 0 then
          str = self:SerializeTableData(self.StatData, offset, count)
          self.GetSwf():Invoke(callback, str, numRows)
        else
          self.GetSwf():Invoke(callback, str, 0)
        end
      else
        self.GetSwf():Invoke(callback, str, 0)
      end
    end,
    RequestScoreData = function(self, callback)
      local ds = DataSources[DS_MINI_GAME_SCORE]
      self:PopulateScore(callback)
    end,
    PopulateScore = function(self, callback)
      local str = ""
      if #self.ScoreData > 0 then
        local numRows = #self.ScoreData
        if numRows > 0 then
          str = self:SerializeTableData(self.ScoreData, 0, numRows)
          self.GetSwf():Invoke(callback, str, numRows)
        else
          self.GetSwf():Invoke(callback, str, 0)
        end
      else
        self.GetSwf():Invoke(callback, str, 0)
      end
    end,
    SerializeTableData = function(self, tbl, offset, count)
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      local offset = math.max(offset, 0)
      local countTo = math.min(offset + count, #tbl)
      for i = offset, countTo - 1 do
        local c = 0
        for k, v in pairs(tbl[i + 1]) do
          if c > 0 then
            data = data .. propDelim
          end
          data = data .. k .. valueDelim .. v
          c = c + 1
        end
        if i < #tbl - 1 and count > 1 then
          data = data .. itemDelim
        end
      end
      return data
    end,
    ParseRewards = function(self, status)
      local ds = DsTable.Find(DataSources[DS_MINI_GAME_REWARD])
      if ds and ds:GetRowCount() > 0 then
        local item = {}
        item.Type = -1
        item.Name = Ui.GetString("CoinsScoreScreen")
        item.Description = -1
        item["Icon ID"] = 4809
        item.Quantity = tonumber(ds:GetData(0, 3))
        item["Tint Value"] = ""
        item["Item Id"] = -1
        item["Parameter 2"] = -1
        item.Rarity = -1
        item["Members Only"] = 0
        item.Guid = "Coins"
        item.Hidden = 0
        if 0 < item.Quantity and status == 1 and not self.coinsAdded then
          self:AddRewardItem(item)
          self.coinsAdded = true
        end
        item = nil
        local item = {}
        item.Type = -1
        item.Name = Ui.GetString("StarsScoreScreen")
        item.Description = -1
        item["Icon ID"] = 9
        item.Quantity = tonumber(ds:GetData(0, 2))
        item["Tint Value"] = nil
        item["Item Id"] = -1
        item["Parameter 2"] = -1
        item.Rarity = -1
        item["Members Only"] = 0
        item.Guid = "Stars"
        item.Hidden = 0
        if 0 < item.Quantity and status == 1 and not self.starsAdded then
          self:AddRewardItem(item)
          self.starsAdded = true
        end
        item = nil
      end
      local ds = DsTable.Find(DataSources[DS_MINI_GAME_REWARD_ENTRIES])
      for i = 0, ds:GetRowCount() - 1 do
        local item = {}
        local typeColumn = 0
        local hiddenColumn = 11
        for c = 0, ds:GetColumnCount() - 1 do
          item[ds:GetColumnName(c)] = ds:GetData(i, c)
        end
        if tonumber(ds:GetData(i, typeColumn)) == 1 and tonumber(ds:GetData(i, hiddenColumn)) ~= 1 then
          self:AddRewardItem(item)
        end
      end
    end,
    AddRewardItem = function(self, item)
      local add = true
      for i = 1, #self.RewardsData do
        if item["Item Id"] ~= self.RewardsData[i]["Item Id"] or item.Guid == "Coins" or item.Guid == "Stars" then
        else
          for k, v in pairs(self.RewardsData[i]) do
            item[k] = v
          end
          add = false
        end
      end
      if add then
        Logger:print("scorescreen.lua", "add reward " .. tostring(item.Name) .. tostring(item["Icon ID"]) .. ":" .. tostring(item.Quantity))
        table.insert(self.RewardsData, item)
      end
    end,
    RequestRewardsData = function(self, offset, count, callback)
      local ds = DataSources[DS_MINI_GAME_REWARD_ENTRIES]
      self:PopulateRewards(tonumber(offset), tonumber(count), DsTable.Find(ds), callback)
    end,
    PopulateRewards = function(self, offset, count, ds, callback)
      if offset == nil or count == nil then
        return
      end
      local str = ""
      if #self.RewardsData > 0 then
        local numRows = #self.RewardsData
        if numRows > 0 then
          str = self:SerializeTableData(self.RewardsData, offset, count)
          self.GetSwf():Invoke(callback, str, numRows)
        else
          self.GetSwf():Invoke(callback, str, 0)
        end
      else
        self.GetSwf():Invoke(callback, str, 0)
      end
    end,
    SerializeData = function(self, ds, offset, count)
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      local offset = math.max(offset, 0)
      local countTo = math.min(offset + count, ds:GetRowCount())
      for i = offset, countTo - 1 do
        for c = 0, ds:GetColumnCount() - 1 do
          if c > 0 then
            data = data .. propDelim
          end
          data = data .. ds:GetColumnName(c) .. valueDelim .. ds:GetData(i, c)
        end
        if i < ds:GetRowCount() - 1 and count > 1 then
          data = data .. itemDelim
        end
      end
      return data
    end,
    GetSoccerState = function(self, callback)
      local state = 0
      if 0 < self.m_CurrentGameType then
        state = 1
      end
      self.GetSwf():Invoke(callback, state)
    end,
    RequestSoccerData = function(self, callback)
      local ds1 = "BaseClient.SoccerProcessor.SoccerTeamStats"
      local ds2 = "BaseClient.SoccerProcessor.SoccerPlayerStats"
      self:PopulateSoccer(DsTable.Find(ds1), DsTable.Find(ds2), callback)
    end,
    PopulateSoccer = function(self, ds1, ds2, callback)
      local str1 = ""
      local str2 = ""
      local numRows1 = 0
      local numRows2 = 0
      if ds1 then
        numRows1 = ds1:GetRowCount()
        if numRows1 > 0 then
          str1 = self:SerializeData(ds1, 0, numRows1)
        end
      end
      if ds2 then
        numRows2 = ds2:GetRowCount()
        if numRows2 > 0 then
          str2 = self:SerializeData(ds2, 0, numRows2)
        end
      end
      self.GetSwf():Invoke(callback, str1, str2)
    end,
    RequestMOBonusData = function(self, callback)
      local message = ""
      local isMember = tostring(Ui.IsMember())
      local ds = DsTable.Find("BaseClient.MiniGame.MemberReward")
      if 0 >= tonumber(ds:GetData(0, 3)) then
        self.GetSwf():Invoke(callback, message, isMember)
        return
      end
      local items = {}
      local item = {}
      item.Type = -1
      item.Name = Ui.GetString("CoinsScoreScreen")
      item.Description = -1
      item["Icon ID"] = 4809
      item.Quantity = tonumber(ds:GetData(0, 3))
      item["Tint Value"] = ""
      item["Item Id"] = -1
      item["Parameter 2"] = -1
      item.Rarity = -1
      item["Members Only"] = 0
      item.Guid = "Coins"
      item.Hidden = 0
      table.insert(items, item)
      message = self:SerializeTableData(items, 0, 1)
      self.GetSwf():Invoke(callback, message, isMember)
    end,
    GetString = function(self, stringId, callback, textField)
      self.GetSwf():Invoke(callback, Ui.GetString(stringId), textField)
    end,
    SwfEventsEnabled = function(self, value)
      if value then
        _G.Main_wndScoreScreen_swfScoreScreen_OnFocus = self.OnFocus
        Main_wndScoreScreen_swfScoreScreen_OnUserEvent = self.OnUserEvent
      else
        Main_wndScoreScreen_swfScoreScreen_OnFocus = nil
        Main_wndScoreScreen_swfScoreScreen_OnUserEvent = nil
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    OnUserEvent = function(a, b, c, ...)
      if a == "exitScreen" or a == "Hide" then
        ScoreScreen:ExitScreen()
      elseif a == "Upgrade" then
        ScoreScreen:HideToUpgrade()
      elseif a == "CountUpTextField" then
        if (MiniGameStatusHandler.currentMiniGameType == 10 or MiniGameStatusHandler.currentMiniGameType == 11) and ScoreScreen.sound16142Played == true then
          return
        end
        ScoreScreen.sound16142Played = true
        Ui.PlaySoundFromDefinition(16142)
      elseif a == "CountUpTotal" then
        Ui.PlaySoundFromDefinition(16143)
      elseif a == "LetterPop" then
        Ui.PlaySoundFromDefinition(16144)
      elseif a == "OnLootWheelSpinRequest" then
        if ScoreScreen.isLootWheelReady == true and ScoreScreen.isLootWheelSpinning == false then
          ScoreScreen:SpinLootWheel()
        end
      elseif a == "OnLootWheelRotationStopped" then
        Ui.SendLootWheelRotationStopPacket()
        ScoreScreen:LootWheelCompleted()
      elseif a == "playSound" or a == "PlaySound" then
        HUD:PlaySound(b)
      elseif tostring(a) == "ASPrint" then
        print("ASPrint: " .. b)
      elseif tostring(a) == "DebugMsg" then
      elseif tostring(a) == "WheelReady" then
        ScoreScreen.isLootWheelReady = true
      elseif a == "PlayLootWheelSound" then
        local id = Ui.PlaySoundFromDefinition(tonumber(b), 100, 0)
      else
        if ScoreScreen[a] then
          ScoreScreen[a](ScoreScreen, b, c, ...)
        else
        end
      end
    end,
    loggerprint = function(self, message)
      Logger:print("scorescreen.lua", message)
    end
  }
end)()
;(function()
  MinigameTitleBar = {
    wndName = "Main.wndMinigameTitleBar",
    swfName = "Main.wndMinigameTitleBar.swfMinigameTitleBar",
    debug = false,
    visible = false,
    instanceName = nil,
    GetWindow = function()
      return Window.Find(Ui.GetName(MinigameTitleBar.wndName))
    end,
    GetSwf = function()
      return GfxCtrl.Find(Ui.GetName(MinigameTitleBar.swfName))
    end,
    ShowForInstance = function(self, name)
      self.instanceName = name
      self:Show()
    end,
    Show = function(self)
      if self.visible then
        return
      end
      self.visible = true
      self:SwfEventsEnabled(true)
      NonModalContext:AddContext(self)
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      self.GetWindow():SetPosition(sw * 0.5 - ww * 0.5, -50)
      self.GetWindow():Show()
      self.GetSwf():Invoke("window.moveTo", "undefined", 50, "Initialize")
    end,
    OnResize = function(self)
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      self.GetWindow():SetPosition(sw * 0.5 - ww * 0.5, -50)
    end,
    Hide = function(self, mode)
      if mode == 1 then
        self.GetSwf():Invoke("window.moveTo", "undefined", 0, "Hide")
        HUD:showMain()
      else
        NonModalContext:RemoveContext(self)
        self.GetSwf():Unload()
        self.GetWindow():Hide()
        self:SwfEventsEnabled(false)
        self.visible = false
      end
      self.instanceName = nil
    end,
    Reveal = function(self)
      self:OnResize()
    end,
    Conceal = function(self)
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = self.GetWindow():GetSize()
      self.GetWindow():SetPosition(sw * 0.5 - ww * 0.5, -150)
    end,
    Initialize = function(self)
      self.GetSwf():Invoke("window.getData")
      self.GetSwf():Invoke("window.setExitString", Ui.GetStringById(103018))
    end,
    PauseGame = function(self)
      MiniGameFlash:Pause()
      if TutorialButton.visible then
        self.tutorialButtonVisible = true
        TutorialButton:Hide()
      end
      local wnd = Window.Find(Tutorial.wndClickGobbler)
      local sw, sh = Window.GetCanvasSize()
      wnd:Show()
      wnd:SetPosition(0, 0)
      wnd:SetSize(sw, sh)
    end,
    ResumeGame = function(self)
      MiniGameFlash:Resume()
      if self.tutorialButtonVisible then
        self.tutorialButtonVisible = nil
        TutorialButton:Show()
      end
      Window.Find(Tutorial.wndClickGobbler):Hide()
      GfxCtrl.Find(Ui.GetName("Main.wndClickGobbler.swfClickGobbler")):Unload()
    end,
    ExitGame = function(self)
      if HUD.isInStartingZone and not HUD.inMiniGame then
        FirstTimeEvent.DisableCloseButton = nil
        HUD:LeaveStartingZone()
        FirstTimeEventHandler:CloseDialog()
        Tutorial:ClearAllTutorialElements()
        return
      end
      if SoccerTutorial.SoccerIsActive == true then
        SoccerTutorial:CloseDialog()
      end
      self.tutorialButtonVisible = nil
      HUD.inMiniGame = false
      MiniGameStatusHandler.currentMiniGameType = -1
      if self.instanceName then
        Housing:Leave()
        self:Hide()
      else
        Ui.QuitMiniGame()
      end
      FunctionStack:PopAndRun("NagStack")
    end,
    GetMinigameData = function(self, callback)
      local ds = DsTable.Find("BaseClient.MiniGame")
      local gameName = ds:GetData(0, 0)
      local gameType = tonumber(ds:GetData(0, 4))
      local flashGame = 0
      if HUD.mMiniGameFlash and gameType ~= 6 and gameType ~= 7 then
        flashGame = 1
      end
      if self.instanceName then
        gameName = self.instanceName
      end
      self.GetSwf():Invoke(callback, gameName .. "::" .. flashGame)
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    OnUserEvent = function(func, b, ...)
      if MinigameTitleBar[func] then
        MinigameTitleBar[func](MinigameTitleBar, b, ...)
      elseif func == "playSound" or func == "PlaySound" then
        HUD:PlaySound(b)
      else
        MinigameTitleBar:print(func)
      end
    end,
    SwfEventsEnabled = function(self, value)
      if value then
        Main_wndMinigameTitleBar_swfMinigameTitleBar_OnFocus = self.OnFocus
        Main_wndMinigameTitleBar_swfMinigameTitleBar_OnUserEvent = self.OnUserEvent
      else
        Main_wndMinigameTitleBar_swfMinigameTitleBar_OnFocus = nil
        Main_wndMinigameTitleBar_swfMinigameTitleBar_OnUserEvent = nil
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[MinigameTitleBar]\t" .. tostring(message))
      end
    end
  }
end)()
;(function()
  MembershipHandler = {
    windowName = Ui.GetName("Main.wndMembership"),
    swfName = Ui.GetName("Main.wndMembership.swfMembership"),
    boolIsShown = false,
    Init = function(self)
      self:GetMembershipStatus()
    end,
    GetMembershipStatus = function(self)
      local swf = GfxCtrl.Find(self.swfName)
      Logger:print("Membership.lua", "member " .. tostring(Ui.IsMember()))
      swf:Invoke("setMembershipStatus", tostring(Ui.IsMember()))
    end,
    Show = function(self, mode, tocategory, bundleid, isGroup)
      self.boolIsShown = true
      local swf = GfxCtrl.Find(self.swfName)
      swf:Reset()
      local w = Window.Find(self.windowName)
      local width, height = w:GetSize()
      local screenWidth, screenHeight = Window.GetCanvasSize()
      w:SetProperty("Width", screenWidth)
      w:SetProperty("Height", screenHeight)
      swf:SetProperty("Width", screenWidth)
      swf:SetProperty("Height", screenHeight)
      w:SetPosition(0, -height)
      w:Show()
      MembershipHandler:Init()
      WindowTweener:Create("Main.wndMembership", "Y", nil, 0, 0.3)
    end,
    Hide = function(self)
      Logger:print("membership.lua", "Hide")
      if self.boolIsShown == false then
        return
      end
      Context:Pop()
      local w = Window.Find(self.windowName)
      local width, height = w:GetSize()
      local screenWidth, screenHeight = Window.GetCanvasSize()
      self.recipient = 0
      HUD:PlaySound("HideWindow")
      WindowTweener:Create("Main.wndMembership", "Y", nil, -height, 0.3, function()
        MembershipHandler:hide2()
      end)
      self.boolIsShown = false
    end,
    hide2 = function(self)
      Logger:print("membership.lua", "Hide2")
      local wnd = Window.Find(self.windowName)
      if wnd then
        wnd:Hide()
      end
      local swf = GfxCtrl.Find(self.swfName)
      if swf then
        swf:Unload()
      end
      if ActivityPortal.isShown then
        Logger:print("membership.lua", "Enabling Activity Portal")
        ActivityPortal:Enable(true)
      end
    end
  }
  function Main_wndMembership_swfMembership_OnUserEvent(a, b, c, d, ...)
    if a == "closeWindow" then
      MembershipHandler:Hide()
    elseif a == "playSound" or a == "PlaySound" then
      HUD:PlaySound(b)
    elseif a == "ASPrint" then
      Logger:print("Membership.lua", "ASPrint: " .. tostring(b) .. ", " .. tostring(c) .. ", " .. tostring(d))
    elseif a == "MembershipMarketplace" then
      if MembershipHandler.boolIsShown == false then
        Logger:print("Membership.lua", "Already closing membership")
      elseif InGamePurchaseStoreScreen.LaunchExternalStore() == false then
        NotificationHandler:ErrorMessage(MarketplaceStrings.ERROR_REQUEST_UNAVAILABLE)
      end
    else
      if a == "CloseWindowPS3" then
        MembershipHandler:Hide()
        NavigationHandler:EnableBar()
      else
      end
    end
  end
  Client.MembershipHandler = "MembershipHandler"
end)()
;(function()
  AbilitiesScreen = {
    wndName = "Main.wndAbilitiesScreen",
    swfName = "Main.wndAbilitiesScreen.swfAbilitiesScreen",
    visible = false,
    debug = false,
    GetWindow = function()
      return Window.Find(Ui.GetName(AbilitiesScreen.wndName))
