    GetSwf = function()
      return GfxCtrl.Find(Ui.GetName(AbilitiesScreen.swfName))
    end,
    Show = function(self)
      if self.visible then
        return
      end
      self.visible = true
      NonModalContext:AddContext(self)
      self.GetSwf():Load()
      self:SwfEventsEnabled(true)
      self.GetWindow():Show()
      Ui.TriggerFirstTimeEvent("JobsAbilities")
      local sw, sh = Window.GetCanvasSize()
      self.GetSwf():Invoke("window.move", -sw, sh * 0.5)
      self.GetWindow():SetSize(sw, sh)
    end,
    OnResize = function(self)
      local sw, sh = Window.GetCanvasSize()
      self.GetWindow():SetSize(sw, sh)
    end,
    Hide = function(self, mode)
      self:print("Hide( " .. tostring(mode) .. " )")
      self.visible = false
      NonModalContext:RemoveContext(self)
      self:SwfEventsEnabled(false)
      self.GetSwf():Unload()
      self.GetWindow():Hide()
    end,
    Exit = function(self)
      JobHandler:ModeSwitch(0)
    end,
    RequestCurrentEquippedWeaponData = function(self, callback)
      local ds = DsTable.Find("BaseClient.Inventory.CurrentlyEquipped")
      self.GetSwf():Invoke(callback, self:SerializeData(ds, 7, 1))
    end,
    SelectNextWeapon = function(self)
    end,
    SelectPreviousWeapon = function(self)
    end,
    ProfileCheck = function(self)
      if JobBrowser:GetCurrentJobType() == 2 then
        return true
      end
      return false
    end,
    RequestProfileAbilities = function(self, callback)
      local ds = DsTable.Find(DataSources[DS_ABILITY_LINES])
      local rowCount = ds:GetRowCount()
      local message = ""
      for i = 0, rowCount - 1 do
        for cN = 0, ds:GetColumnCount() - 1 do
          if ds:GetColumnName(cN) == "ProfileId" and tonumber(ds:GetData(i, cN)) == Ui.GetActiveProfileId() then
            if message ~= "" then
              message = message .. "##"
            end
            message = message .. self:SerializeData(ds, i, 1)
          end
        end
      end
      self.GetSwf():Invoke(callback, message)
    end,
    RequestWeaponAbilities = function(self, callback)
      local ds = DsTable.Find("BaseClient.Inventory.CurrentlyEquipped")
      local itemID = DataSourceMethods:GetDsVal("BaseClient.Inventory.CurrentlyEquipped", 7, "Item Guid")
      Ui.SetItemAbility(itemID)
      local ds = DsTable.Find("BaseClient.ItemAbilities")
      local rowCount = ds:GetRowCount()
      local message = self:SerializeData(ds, 0, rowCount)
      self.GetSwf():Invoke(callback, message)
    end,
    SerializeData = function(self, ds, offset, count)
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      local offset = math.max(offset, 0)
      local countTo = math.min(offset + count, ds:GetRowCount())
      for i = offset, countTo - 1 do
        for c = 0, ds:GetColumnCount() - 1 do
          if c > 0 then
            data = data .. propDelim
          end
          data = data .. ds:GetColumnName(c) .. valueDelim .. ds:GetData(i, c)
        end
        if i < ds:GetRowCount() - 1 and count > 1 then
          data = data .. itemDelim
        end
      end
      return data
    end,
    SwfEventsEnabled = function(self, value)
      if value then
        Main_wndAbilitiesScreen_swfAbilitiesScreen_OnFocus = self.OnFocus
        Main_wndAbilitiesScreen_swfAbilitiesScreen_OnUserEvent = self.OnUserEvent
      else
        Main_wndAbilitiesScreen_swfAbilitiesScreen_OnFocus = nil
        Main_wndAbilitiesScreen_swfAbilitiesScreen_OnUserEvent = nil
      end
    end,
    OnUserEvent = function(func, ...)
      if AbilitiesScreen[func] then
        AbilitiesScreen[func](AbilitiesScreen, ...)
      else
        AbilitiesScreen:print(func)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[AbilitiesScreen]\t" .. message)
      end
    end
  }
end)()
;(function()
  DataSourceConnection = {
    debug = false,
    m_Connections = {},
    Connect = function(self, datasource, tbl, callback)
      if not self.m_Connections[datasource] then
        self.m_Connections[datasource] = {}
        self:SetupNewConnection(self.m_Connections[datasource])
        local ds = DsTable.Find(datasource)
        ds:EnableScriptEvents()
        local dsEvent = string.gsub(datasource, "%.", "_")
        _G[dsEvent .. "_OnDataUpdate"] = self.m_Connections[datasource].OnDataUpdate
        _G[dsEvent .. "_OnDataChanged"] = self.m_Connections[datasource].OnDataChanged
      else
        for i = 1, #self.m_Connections[datasource] do
          if self.m_Connections[datasource][i].Object == tbl then
            self:print("Table[ " .. tostring(tbl) .. " ] already connected to DataSource[ " .. tostring(datasource) .. " ].")
            self:print("\tEvents currently trigger callback: " .. tostring(self.m_Connections[datasource][i].Callback))
            return
          end
        end
      end
      local obj = {}
      obj.Object = tbl
      obj.Callback = callback
      table.insert(self.m_Connections[datasource], obj)
    end,
    Disconnect = function(self, datasource, tbl)
      if self.m_Connections[datasource] then
        for i = 1, #self.m_Connections[datasource] do
          if self.m_Connections[datasource][i].Object == tbl then
            table.remove(self.m_Connections[datasource], i)
          end
        end
        if #self.m_Connections[datasource] == 0 then
          self.m_Connections[datasource] = nil
          local ds = DsTable.Find(datasource)
          ds:DisableScriptEvents()
        end
      end
    end,
    SetupNewConnection = function(self, connection)
      function connection.OnDataUpdate(...)
        DataSourceConnection:DispatchEvent(connection, ...)
      end
      function connection.OnDataChanged(...)
        DataSourceConnection:DispatchEvent(connection, ...)
      end
    end,
    DispatchEvent = function(self, connection, ...)
      for i = 1, #connection do
        connection[i].Object[connection[i].Callback](connection[i].Object, ...)
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[DataSourceConnection]\t" .. tostring(message))
      end
    end
  }
end)()
