        for i = 0, numRows - 1 do
          local id = tonumber(ds:GetData(i, 0))
          if ID == id then
            local entries = 0
            for c = 1, numCols - 1 do
              local key = ds:GetColumnName(c)
              if key ~= "Entry Collected" then
                item[key] = ds:GetData(i, c)
              end
            end
            break
          end
        end
      end
      return item
