        for i = 0, numRows - 1 do
          local item = {}
          for c = 0, numCols - 1 do
            local key = ds:GetColumnName(c)
            item[key] = ds:GetData(i, c)
          end
          table.insert(items, item)
        end
      end
      return items
    end,
    Populate = function(self, ID)
      local swf = self.GetSwf()
      local CollectionData = self:GetCollectionData(ID)
      swf:Invoke("displayCollectionData", CollectionData["Collection ID"], CollectionData.Name, CollectionData["Image ID"], CollectionData.Description, 1113, "???", CollectionData["Image Tint Value"])
      self:PopulateRewards()
    end,
    PopulateRewards = function(self)
      local ds1 = DsTable.Find(DataSources[DS_COLLECTION_REWARD_ENTRIES])
      local ds2 = DsTable.Find(DataSources[DS_COLLECTION_REWARD])
      self.GetSwf():Invoke("rewards.setData", self:SerializeData(ds1), self:SerializeData(ds2))
    end,
    SerializeData = function(self, ds)
      local itemDelim = "##"
      local propDelim = "::"
      local valueDelim = "^"
      local data = ""
      if ds then
        for i = 0, ds:GetRowCount() - 1 do
          for c = 0, ds:GetColumnCount() - 1 do
            if c > 0 then
              data = data .. propDelim
            end
            data = data .. ds:GetColumnName(c) .. valueDelim .. ds:GetData(i, c)
          end
          if i < ds:GetRowCount() - 1 then
            data = data .. itemDelim
          end
        end
      end
      return data
    end,
    print = function(self, message)
      if self.debug then
        print("[CollectionDetails]\t" .. tostring(message))
      end
    end
  }
end)()
