    end,
    OnResize = function(self)
      local ww, wh = self.GetWindow():GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create(self.wndName, "X", nil, 50, 0.3)
      WindowTweener:Create(self.wndName, "Y", nil, sh / 2 - wh / 2, 0.3)
