      self.visible = false
      NonModalContext:RemoveContext(self)
      local ww, wh = self.GetWindow():GetSize()
      local sw, sh = Window.GetCanvasSize()
      WindowTweener:Create(self.wndName, "X", nil, -500, 0.3, PetDetails.Hide2)
      WindowTweener:Create(self.wndName, "Y", nil, sh / 2 - wh / 2, 0.3)
    end,
    Hide2 = function()
      PetDetails.GetSwf():Unload()
      PetDetails.GetWindow():Hide()
    end,
    Populate = function(self)
      local petID = Pet.GetActivePetId()
      if petID >= 0 then
        local swf = self.GetSwf()
        local petData = PetsHandler:GetPetTableByID(petID)
        if not PetsHandler.activeMode or PetsHandler.activeMode > 1 then
        else
          swf:Invoke("setPetGender", tonumber(petData.sex) + 1)
          swf:Invoke("updatePool", 0, petData.mood)
          swf:Invoke("updatePool", 1, petData.food)
          swf:Invoke("updatePool", 2, petData.groom)
          swf:Invoke("updatePool", 3, petData.play)
          PetDetails:UpdateBarMotion(1, petData.food)
          PetDetails:UpdateBarMotion(2, petData.groom)
          PetDetails:UpdateBarMotion(3, petData.play)
        end
      end
    end,
    UpdateBarMotion = function(self, barId, value)
      local swf = self.GetSwf()
      local trend = self.PetPoolTrends[barId]
      local current = self.PetStoredPoolValues[barId]
      if tonumber(value) ~= 0 then
        if current > tonumber(value) then
          trend = trend - 1
        elseif current < tonumber(value) then
          trend = 25
        end
        if trend > 20 then
          swf:Invoke("setBarMotion", barId, 1)
        elseif trend > 0 then
          swf:Invoke("setBarMotion", barId, 0)
        else
          swf:Invoke("setBarMotion", barId, -0.25)
        end
        self.PetPoolTrends[barId] = tonumber(trend)
        self.PetStoredPoolValues[barId] = tonumber(value)
      end
    end,
    OnUserEvent = function(a, b, c)
      if a == "updatePetName" then
        PetTutorial:UpdatePetName()
        Pet.SetName(Pet.GetActivePetId(), tonumber(b), tonumber(c))
      elseif a == "doTrick" then
        Logger:print("petdetails.lua", "Doing pet trick " .. tonumber(b))
        if tonumber(b) == 0 then
          Pet.PlayWithToy()
        elseif tonumber(b) > 0 then
          local didTrick = Pet.PerformTrick(b)
          if didTrick then
            PetsHandler:PlaySound("Whistle" .. math.random(1, 3))
          end
        end
      elseif a == "PlaySound" then
        HUD:PlaySound(b)
      elseif a == "CloseWindowPS3" then
        Logger:print("PetDetails.lua", "Close Window Received")
        PetsHandler:ModeSwitch(0)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[PetDetails]\t" .. tostring(message))
      end
    end
  }
  Main_wndPetDetails_swfPetDetails_OnUserEvent = PetDetails.OnUserEvent
  Main_wndPetDetails_swfPetDetails_OnFocus = PetDetails.OnFocus
end)()
