      testTbl[2].iconID = 22867
      testTbl[2].message2 = Ui.GetString("FtesCombatBasic1")
      return testTbl
    end,
    Move = function(self, x, y)
      self._x = x
      self._y = y
      self.GetWindow():SetPosition(x, y)
    end,
    MoveTo = function(self, x, y)
      if x and type(x) == "number" then
        self._x = x
      end
      if y and type(y) == "number" then
        self._y = y
      end
      self:OnResize()
    end,
    OnResize = function(self)
      WindowTweener:Create(self.wndName, "X", nil, self._x, 0.3)
      WindowTweener:Create(self.wndName, "Y", nil, self._y, 0.3)
    end,
