      NonModalContext:RemoveContext(self)
      self.GetWindow():Hide()
      self.GetSwf():Unload()
      self:SwfEventsEnabled(false)
      self.visible = false
      self.SoundId = nil
      FirstTimeEventHandler:CloseDialog()
      self:CallDelegate("OnHideTutorialDialog")
    end,
    SetData = function(self, data)
      if type(data) == "table" then
        for i = 1, #data do
          if data[i].multiIcons then
            local sData = self:Serialize(data[i].multiIcons)
            data[i].multiIcons = sData
          end
          self.GetSwf():Invoke("window.AddPage", i, data[i].message1, data[i].message2, data[i].iconID, data[i].multiIcons)
        end
      elseif type(data) == "string" then
        self.GetSwf():Invoke("window.AddPage", 1, data)
      else
        self:print("{SetData}\tInvalid data type. Must be type table or string.")
      end
    end,
    Serialize = function(self, tbl)
      if type(tbl) ~= "table" then
        return tbl
      end
      local str = ""
      for i = 1, #tbl do
        str = str .. "iconId^^" .. tbl[i].iconId
        str = str .. "::"
        str = str .. "message^^" .. tbl[i].message
        if i < #tbl then
          str = str .. "##"
        end
      end
      return str
    end,
    CloseButtonEnabled = function(self, value, time)
      self.GetSwf():Invoke("window.CloseButtonEnabled", tostring(value), time)
    end,
    SwfEventsEnabled = function(self, value)
