      else
        Main_wndTutorialDialog_swfTutorialDialog_OnFocus = nil
        Main_wndTutorialDialog_swfTutorialDialog_OnUserEvent = nil
      end
    end,
    OnChangePage = function(self, page)
      self:CallDelegate("OnChangePageTutorialDialog", page)
