      if a == "PlaySound" or a == "playSound" then
        HUD:PlaySound(b)
      elseif a == "ChangePage" then
        TutorialDialog:OnChangePage(tonumber(b))
      elseif a == "Close" then
        TutorialDialog:Hide()
      else
        print(a)
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    print = function(self, message)
      if self.debug then
        print("[TutorialDialog]\t" .. tostring(message))
      end
    end
  }
  Delegate:AddSupportToClassObject(TutorialDialog, "TutorialDialog")
end)()
