    end,
    StopKey = function(self, childId, key)
      self.GetSwf(childId):Invoke("StopKey", key)
    end,
    SwfEventsEnabled = function(self, childId, value)
      if value then
        _G[self.children[childId].OnFocus] = self.OnFocus
        _G[self.children[childId].OnUserEvent] = self.OnUserEvent
      else
        _G[self.children[childId].OnFocus] = nil
        _G[self.children[childId].OnUserEvent] = nil
      end
    end,
    OnFocus = function(focus)
      if focus == "1" then
        Window.SetFocus()
      end
    end,
    OnUserEvent = function(func, ...)
      if TutorialKeys[func] then
        TutorialKeys[func](TutorialKeys, ...)
      else
        print(tostring(func))
      end
    end
  }
end)()
;(function()
  DemoDerbyTutorial = {
    MODE_BASIC = 1,
    MODE_ADVANCED = 2,
    m_CurrentMode = nil,
    m_CurrentPage = -1,
    Show = function(self, mode)
      local data
      if mode == self.MODE_BASIC then
        self.OnChangePageTutorialDialog = self.ChangeBasicPage
        data = self.GetBasicTutorial()
        PS3_tutorial:Show()
        PS3_tutorial:populateTutorial(11)
      elseif mode == self.MODE_ADVANCED then
        self.OnChangePageTutorialDialog = self.ChangeAdvancedPage
        data = self.GetAdvancedTutorial()
        TutorialDialog:Connect(self)
        TutorialDialog:Show(310, 60, true)
        TutorialDialog:SetData(data)
      else
        return
      end
      self.m_CurrentMode = mode
      self.OnHideTutorialDialog = self.Hide
      NonModalContext:AddContext(self)
      Ui.OnVehicleTutorialOpened()
    end,
    OnResize = function(self)
      if self.m_CurrentMode == self.MODE_BASIC then
        self:CenterControls()
      end
    end,
    Hide = function(self)
      self.m_CurrentPage = -1
      self.m_CurrentMode = nil
      PS3_tutorial:Hide()
      Tutorial:HideArrow()
      TutorialMouse:Hide()
      TutorialKeys:Hide()
      DemoScore:Hide()
      Window.Find(RacingTutorial.windowDemoCar):Hide()
      self:StopScoreUpdate()
      RacingTutorial:RestoreDemoDerbUi()
      GroupHandler:ModeSwitch(3)
      GroupHandler.Mode = 3
      GroupHandler:ActivateEncounterRequest(" ", 1)
      GroupHandler:EncounterButtonModeSwitch(1)
      NonModalContext:RemoveContext(self)
      Ui.OnVehicleTutorialClosed()
    end,
    HideOnExit = function(self)
      Logger:print("DEMODERBYTUTORIAL.LUA", "HideOnExit")
      self.m_CurrentPage = -1
      self.m_CurrentMode = nil
      PS3_tutorial:Hide(true)
      Tutorial:HideArrow()
      TutorialMouse:Hide()
      TutorialKeys:Hide()
      DemoScore:Hide()
      Window.Find(RacingTutorial.windowDemoCar):Hide()
      self:StopScoreUpdate()
      TutorialDialog:Disconnect(self)
      TutorialDialog:Hide()
      GroupHandler:ModeSwitch(3)
      GroupHandler.Mode = 3
      GroupHandler:ActivateEncounterRequest(" ", 1)
      GroupHandler:EncounterButtonModeSwitch(1)
      NonModalContext:RemoveContext(self)
    end,
    GetBasicTutorial = function()
      return Ui.GetString("DemoDerb1_PS3")
    end,
    GetAdvancedTutorial = function()
      local tutTbl = {}
      local page1 = {
        message1 = Ui.GetString("DemoDerbAdv1")
      }
      local page2 = {
        message1 = Ui.GetString("DemoDerbAdv2")
      }
      local page3 = {
        message1 = Ui.GetString("DemoDerbAdv3")
      }
      local page4 = {
        message1 = Ui.GetString("DemoDerbAdv4"),
        multiIcons = {
          {
            iconId = 11986,
            message = Ui.GetString("DdIcons1")
          },
          {
            iconId = 11984,
            message = Ui.GetString("DdIcons2")
          },
          {
            iconId = 11983,
            message = Ui.GetString("DdIcons3")
          },
          {
            iconId = 11987,
            message = Ui.GetString("DdIcons4")
          },
          {
            iconId = 11988,
            message = Ui.GetString("DdIcons5")
          }
        }
      }
      table.insert(tutTbl, page1)
      table.insert(tutTbl, page2)
      table.insert(tutTbl, page3)
      table.insert(tutTbl, page4)
      return tutTbl
    end,
    ChangeBasicPage = function(self, page)
      if self.m_CurrentPage ~= page and page == 1 then
        Tutorial:HideArrow()
        self:CenterControls()
      end
      self.m_CurrentPage = page
    end,
    ChangeAdvancedPage = function(self, page)
      if self.m_CurrentPage ~= page then
        local sw, sh = Window.GetCanvasSize()
        local mm = GfxCtrl.Find(Tutorial.swfTutorialMouse)
        local km = GfxCtrl.Find(Tutorial.swfTutorialWasd)
        local swfDemoCar = GfxCtrl.Find(RacingTutorial.swfTutorialDemoDerbCar)
        local wndDemoCar = Window.Find(RacingTutorial.windowDemoCar)
        local wndDemoCarX, wndDemoCarY = wndDemoCar:GetPosition()
        local wndDemoCarWidth, wndDemoCarHeight = wndDemoCar:GetSize()
        wndDemoCar:SetPosition(sw - wndDemoCarWidth - 100, 300)
        local demoHealth = Window.Find(RacingTutorial.windowDemo)
        local demoX, demoY = demoHealth:GetPosition()
        local demoWidth, demoHeight = demoHealth:GetSize()
        local myMovie = GfxCtrl.Find(RacingTutorial.movieDemo)
        local demoArrowYPos = demoY + demoHeight - 30
        local demoScore = Window.Find(RacingTutorial.windowDemoScore)
        local scoreX, scoreY = demoScore:GetPosition()
        local scoreWidth, scoreHeight = demoScore:GetSize()
        local myMovie = GfxCtrl.Find(RacingTutorial.movieDemoScore)
        local scoreArrowYPos = scoreY + scoreHeight - 20
        if page == 1 then
          DemoHealthBar:Show()
          DemoHealthBar:SetHealthandBoost(100, 100)
          Tutorial:ShowArrow(demoX, demoArrowYPos - 25, 90)
          self:StopScoreUpdate()
          DemoScore:Hide()
        elseif page == 2 then
          wndDemoCar:Hide()
          DemoHealthBar:Hide()
          DemoScore:Show()
          DemoScore:Set(2)
          self:StartScoreUpdate()
          Tutorial:ShowArrow(sw - scoreWidth + 175, scoreArrowYPos - 15, 90)
        elseif page == 3 then
          wndDemoCar:Show()
          Tutorial:HideArrow()
          self:StopScoreUpdate()
          DemoScore:Hide()
        elseif page == 4 then
          wndDemoCar:Hide()
        end
      end
      self.m_CurrentPage = page
    end,
    StartScoreUpdate = function(self)
      if UpdateList.DemoDerbyTutorial_ScoreUpdate == nil then
        UpdateList.DemoDerbyTutorial_ScoreUpdate = {}
        UpdateList.DemoDerbyTutorial_ScoreUpdate.currentScore = 2
        UpdateList.DemoDerbyTutorial_ScoreUpdate.maxScore = 20
        UpdateList.DemoDerbyTutorial_ScoreUpdate.scoreUpdateTick = 0
        UpdateList.DemoDerbyTutorial_ScoreUpdate.scoreUpdateTickMax = 60
        UpdateList.DemoDerbyTutorial_ScoreUpdate.Update = self.ScoreUpdate
      end
    end,
    SetScoreUpdateFrame = function(self, value)
      if type(value) == "number" and UpdateList.DemoDerbyTutorial_ScoreUpdate ~= nil then
        UpdateList.DemoDerbyTutorial_ScoreUpdate.scoreUpdateTickMax = value
      end
    end,
    ScoreUpdate = function(self)
      if self.scoreUpdateTick >= self.scoreUpdateTickMax then
        if self.currentScore >= self.maxScore then
          self.currentScore = 0
        else
          self.currentScore = self.currentScore + math.random(2) + 1
        end
        self.scoreUpdateTick = 0
      else
        self.scoreUpdateTick = self.scoreUpdateTick + 1
      end
      DemoScore:Set(self.currentScore)
    end,
    StopScoreUpdate = function(self)
      UpdateList.DemoDerbyTutorial_ScoreUpdate = nil
      DemoScore:Set(0)
    end,
    TestDialog5Icons = function(self, clear)
      local im = GfxCtrl.Find(Tutorial.swfTutorialDialog)
      if not clear then
        im:Invoke("nextPageDD5Icons", 11986, Ui.GetString("DdIcons1"), 11984, Ui.GetString("DdIcons2"), 11983, Ui.GetString("DdIcons3"), 11987, Ui.GetString("DdIcons4"), 11988, Ui.GetString("DdIcons5"))
      else
        im:Invoke("nextPageDD5Icons")
      end
    end,
    CenterControls = function(self)
      local sw, sh = Window.GetCanvasSize()
      local width, height = TutorialMouse.GetWindow():GetSize()
      local mod = -50
      if sw < 1280 then
        mod = -200
      end
      TutorialMouse:Move(sw - width - 15, sh / 2 - height / 2 + mod)
      local kw = Window.Find(Tutorial.wndTutorialWasd)
      local width2, height2 = TutorialKeys.GetWindow(TutorialKeys.CHILD_WASD):GetSize()
      mod = 125
      if sw > 1280 then
        mod = 250
      end
      TutorialKeys:Move(TutorialKeys.CHILD_WASD, sw - width + 25, sh / 2 - height2 / 2 + mod)
      local width4, height4 = TutorialKeys.GetWindow(TutorialKeys.CHILD_CTRL):GetSize()
      TutorialKeys:Move(TutorialKeys.CHILD_CTRL, 100, sh * 0.5 - height2 * 0.5 + 310)
      local width3, height3 = TutorialKeys.GetWindow(TutorialKeys.CHILD_SPACE):GetSize()
      TutorialKeys:Move(TutorialKeys.CHILD_SPACE, sw * 0.5 - width * 0.5, sh * 0.5 - height2 * 0.5 + 300)
    end
  }
end)()
;(function()
  CoinStoreReferrerElementEnum = {GAME_DOCK = 0, COIN_WHEEL = 1}
  CoinStoreHandler = {
    dsCategories = "BaseClient.InventoryCategoriesData",
    dsCoinStoreItems = "BaseClient.CoinStore.CoinStoreItems",
    dsCoinStoreItemsSell = "BaseClient.CoinStore.PlayerSell",
    dsCoinStoreItemsBuyBack = "BaseClient.CoinStore.TransactionHistory",
    dsCoinStoreGroupItems = "BaseClient.CoinStore.CoinStoreItemGroup",
    dsSearchResults = "BaseClient.CoinStore.SearchResults",
    dsFilterState = "BaseClient.CoinStore.ActiveFilters",
    treeData = "",
    currentViewDs = "",
    searchAfterInit = nil,
    hashItemsInView = {},
    currentViewDs = "",
    curSelectedCategory = "0",
    initializingSearchEngine = false,
    curSellItemGuid = nil,
    curSellItemQuantity = nil,
    firstItemId = "-1",
    curRequestOffset = 0,
    curRequestCount = 6,
    isNewCategory = false,
    selectedItemId = "-1",
    curBuyItemTintId = 0,
    curPreviewRow = 0,
    boolPreviewMode = false,
    previewQueueObject = nil,
    referrerId = -1,
    referrerContext = -1,
    multiItemConfirmation = nil,
    Init = function(self)
      MarketplaceHandler.displayMode = MarketplaceEnum.COIN_STORE
      if self.currentViewDs == "" then
        self:SetBuyMode()
      end
      self:SetSortOptions()
      self:SetCoinCount()
      self:GetFilterState()
      self:SetCategory(0)
      if CoinStoreScreen.OnCoinStoreOpened then
        CoinStoreScreen.OnCoinStoreOpened(self.referrerId, self.referrerContext)
      end
    end,
    SetMode = function(self, mode)
      if mode == "Sell" then
        if tonumber(self.curSelectedCategory) == -1 then
          self.curSelectedCategory = 0.1
          local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
          swf:Invoke("setCoinStoreCategory", self.curSelectedCategory)
        end
        self:SetSellMode()
      else
        self:SetBuyMode()
      end
      Logger:print("coinstore.lua", "SetMode , cat " .. self.curSelectedCategory)
      self:SetCategory(self.curSelectedCategory)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("selectCoinStoreCategory", self.curSelectedCategory)
    end,
    SetSellMode = function(self)
      BaseClient_CoinStore_CoinStoreItemGroup_OnDataChanged = nil
      self.currentViewDs = self.dsCoinStoreItemsSell
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("setCoinStoreMode", "Sell")
      self:handleDataUpdate()
    end,
    SetBuyMode = function(self)
      BaseClient_CoinStore_CoinStoreItemGroup_OnDataChanged = nil
      self.currentViewDs = self.dsCoinStoreItems
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("setCoinStoreMode", "Buy")
      self:handleDataUpdate()
    end,
    SetBuyBackMode = function(self)
      BaseClient_CoinStore_CoinStoreItemGroup_OnDataChanged = nil
      self.currentViewDs = self.dsCoinStoreItemsBuyBack
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("setCoinStoreMode", "Buy")
    end,
    SetDatasourceView = function(self, title, dsName)
      self.currentViewDs = dsName
      Logger:print("coinstore.lua", "SetDatasourceView , cat ")
      GfxCtrl.Find(MarketplaceHandler.swfName):Invoke("setCoinStoreCategory", "", title)
      self:handleDataUpdate()
    end,
    BuyItem = function(self, itemId, tintId, quantity)
      tintId = tonumber(tintId)
      self.curBuyItemTintId = tintId
      CoinStoreScreen.BuyItem(itemId, tonumber(quantity), tintId)
    end,
    OnPurchaseResponse = function(self, itemId)
      Logger:print("coinstore.lua", "OnPurchaseResponse: " .. itemId)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("showInquiryPanel", itemId)
    end,
    SetCurSelectedItem = function(self, itemId)
      self.selectedItemId = itemId
    end,
    CanPurchaseItem = function(self, itemId, tintId)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      if self.currentViewDs == self.dsCoinStoreItemsBuyBack then
        swf:Invoke("setCoinStoreCanPurchaseItem", "1", itemId, tintId, Ui.GetString("buyBackCat"))
        return
      end
      local maxPurchasable = EquipScreen.GetMaxItemsPurchasable(tonumber(itemId))
      if CoinStoreScreen.CanBuyItem(itemId, tintId) then
        swf:Invoke("setCoinStoreCanPurchaseItem", "1", itemId, tintId, maxPurchasable)
      else
        swf:Invoke("setCoinStoreCanPurchaseItem", "0", itemId, tintId, maxPurchasable)
      end
    end,
    SellItem = function(self, itemGuid, quantity)
      local ds = DsTable.Find(self.currentViewDs)
      local rowCount = ds:GetRowCount()
      local row = 0
      local index = -1
      while rowCount > row do
        if tonumber(ds:GetData(row, 0)) == tonumber(itemGuid) then
          index = row
          break
        end
        row = row + 1
      end
      local serialized = InventoryHandler:SerializeData(ds, index, 1)
      self.curSellItemGuid = itemGuid
      self.curSellItemQuantity = quantity
      BaseClient_CoinStore_PlayerSell_OnDataUpdate = CoinStoreHandler.RefreshDisplayAfterSell
      MarketplaceHandler:LockPages()
      self.multiItemConfirmation = false
      ConfirmationWindow:Show(MarketplaceStrings.COINSHOP_LABEL_SELL_CONFIRMATION, serialized, quantity)
    end,
    SellCategoryItems = function(self)
      local ds = DsTable.Find("BaseClient.CoinStore.PlayerSell")
      local totalItems = ds:GetRowCount()
      if not ds or math.floor(self.curSelectedCategory) == 0 then
        return
      end
      BaseClient_CoinStore_PlayerSell_OnDataUpdate = CoinStoreHandler.RefreshDisplayAfterSellCategory
      MarketplaceHandler:LockPages()
      local catIcon = self:GetCurrentCategoryData().catIcon
      local catName = self:GetCurrentCategoryData().catText
      local serialized = "Icon ID^" .. tostring(catIcon) .. "::Quantity^" .. totalItems
      local message = Ui.GetString("SellAllConfirmation")
      message = string.gsub(message, "%%category", "<font color='#FFCC00' >" .. catName .. "</font>")
      self.multiItemConfirmation = true
      ConfirmationWindow:Show(message, serialized, totalItems)
    end,
    OnConfirmationResponse = function(self, response)
      MarketplaceHandler:UnlockPages()
      response = tonumber(response)
      if self.multiItemConfirmation and response == 1 then
        local ds = DsTable.Find("BaseClient.CoinStore.PlayerSell")
        local rowCount = ds:GetRowCount()
        for i = 0, rowCount - 1 do
          CoinStoreScreen.SellItem(ds:GetData(i, 0), ds:GetData(i, 4))
        end
      elseif response == 1 then
        CoinStoreScreen.SellItem(self.curSellItemGuid, self.curSellItemQuantity)
      end
      self.multiItemConfirmation = nil
    end,
    RequestItemData = function(self, offset, count)
      local ds = DsTable.Find(self.currentViewDs)
      self.curRequestOffset = offset
      self.curRequestCount = count
      self:Populate(tonumber(offset), tonumber(count), ds, "setCoinStoreData")
    end,
    RequestDataForPreview = function(self, row, isUpdate)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local str = ""
      local ds = self.currentViewDs
      self.curPreviewRow = row
      if swf then
        str = self:BuildItemStringForPreview(DsTable.Find(ds), row)
        if str == false then
          self.previewQueueObject = {row = row, isUpdate = isUpdate}
          return
        end
        swf:Invoke("setPreviewDataForCoinStore", str, isUpdate)
      end
    end,
    BuildItemStringForPreview = function(self, ds, row)
      if not row or row < 0 or row > ds:GetRowCount() - 1 then
        return
      end
      local returnFalse = false
      local item = ""
      local i
      for i = 0, ds:GetColumnCount() - 1 do
        if ds:GetColumnName(i) == "Data Is Ready" and ds:GetData(row, i) == "0" then
          returnFalse = true
        end
        item = item .. ds:GetColumnName(i) .. ItemDisplay.keyvalDelim .. ds:GetData(row, i)
        if i < ds:GetColumnCount() - 1 then
          item = item .. ItemDisplay.propDelim
        end
      end
      if returnFalse then
        return false
      else
        return item
      end
    end,
    RefreshDisplayAfterSell = function(self)
      CoinStoreHandler:RefreshCurDisplay("1")
      CoinStoreHandler:SetCoinCount()
      BaseClient_CoinStore_PlayerSell_OnDataUpdate = nil
    end,
    RefreshDisplayAfterSellCategory = function(self)
      CoinStoreHandler:RefreshCurDisplay("1")
      CoinStoreHandler:SetCoinCount()
      if DsTable.Find("BaseClient.CoinStore.PlayerSell"):GetRowCount() == 0 then
        BaseClient_CoinStore_PlayerSell_OnDataUpdate = nil
      end
    end,
    handleDataUpdate = function()
      if MarketplaceHandler.displayMode ~= MarketplaceEnum.COIN_STORE or CoinStoreHandler.initializingSearchEngine == true or MarketplaceHandler.boolIsShown == false then
        return
      end
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("refreshCoinStore", "-1")
    end,
    handleDataChanged = function(row, col, newData)
      Logger:print("coinstore.lua", "handleDataChanged: " .. row .. ", " .. col .. " = " .. newData)
      if MarketplaceHandler.displayMode ~= MarketplaceEnum.COIN_STORE or CoinStoreHandler.initializingSearchEngine == true or MarketplaceHandler.boolIsShown == false or CoinStoreHandler.currentViewDs == CoinStoreHandler.dsCoinStoreItemsBuyBack then
        return
      end
      local ds = DsTable.Find(CoinStoreHandler.currentViewDs)
      local colName = ds:GetColumnName(tonumber(col))
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      if (colName == "Data Is Ready" and tostring(newData) == "1" or colName == "Quantity in Inventory") and CoinStoreHandler.initializingSearchEngine == false and (row >= tonumber(CoinStoreHandler.curRequestOffset) and row < tonumber(CoinStoreHandler.curRequestOffset) + tonumber(CoinStoreHandler.curRequestCount) or CoinStoreHandler.previewQueueObject) then
        if CoinStoreHandler.previewQueueObject and row == CoinStoreHandler.previewQueueObject.row then
          CoinStoreHandler:RequestDataForPreview(row, 1)
          CoinStoreHandler.previewQueueObject = nil
        end
        CoinStoreHandler:RefreshCurDisplay()
        if row <= ds:GetRowCount() - 1 then
          swf:Invoke("setCoinStoreDataChanged", ds:GetData(row, 0))
        end
      end
    end,
    RefreshCurDisplay = function(self, refreshCurItem)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("refreshCoinStoreCurDisplay", refreshCurItem)
    end,
    SetCategory = function(self, catId)
      CoinStoreHandler.isNewCategory = true
      if self.currentViewDs == self.dsSearchResults or self.currentViewDs == self.dsCoinStoreGroupItems or self.currentViewDs == self.dsCoinStoreItemsBuyBack and tonumber(catId) >= 0 then
        self:SetBuyMode()
      end
      self.curSelectedCategory = catId
      Logger:print("coinstore.lua", "SetMode , cat " .. self.curSelectedCategory)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("setCoinStoreCategory", self.curSelectedCategory, "")
      if self.currentViewDs == self.dsCoinStoreItems and tonumber(catId) >= 0 then
        CoinStoreScreen.SelectItemCategory(tonumber(catId))
      elseif tonumber(catId) >= 0 then
        CoinStoreScreen.SelectInventoryCategory(tonumber(catId))
      else
        self:SetBuyBackMode()
      end
      self:handleDataUpdate()
    end,
    BuildItemString = function(self, ds, row)
      local item = ds:GetColumnName(0) .. ItemDisplay.keyvalDelim .. ds:GetData(row, 0)
      self.hashItemsInView[tostring(ds:GetData(row, 0))] = true
      for i = 1, ds:GetColumnCount() - 1 do
        item = item .. ItemDisplay.propDelim .. ds:GetColumnName(i) .. ItemDisplay.keyvalDelim .. ds:GetData(row, i)
      end
      return item
    end,
    Populate = function(self, offset, count, ds, funcName)
      self.hashItemsInView = {}
      self.curOffset = offset
      self.curRowCount = count
      if offset == nil or count == nil then
        return
      end
      if self.currentViewDs == self.dsCoinStoreItemsBuyBack then
        self:PopulateBuyBack(offset, count, ds, funcName)
        return
      end
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local str = ""
      if swf then
        if ds then
          local numRows = ds:GetRowCount()
          if numRows == 0 then
            swf:Invoke("setEmptyData", "1")
          else
            swf:Invoke("setEmptyData", "0")
          end
          local numCols = ds:GetColumnCount()
          if numCols <= 0 then
            swf:Invoke(funcName, str, -1)
            return
          end
          if numRows > 0 then
            local offset = math.max(offset, 0)
            local countTo = math.min(offset + count, numRows)
            for i = offset, countTo - 1 do
              if 0 < #ds:GetData(i, 2) then
                str = str .. self:BuildItemString(ds, i) .. ItemDisplay.itemDelim
              end
            end
          end
          swf:Invoke(funcName, str, numRows)
        else
          swf:Invoke(funcName, str, 0)
        end
      end
    end,
    BuildBuyBackItemString = function(self, item)
      self.hashItemsInView[item.Id] = true
      local bbData = ""
      local transactionId = item.Id
      bbData = bbData .. ItemDisplay.propDelim .. "Item ID" .. ItemDisplay.keyvalDelim .. item.ItemId
      bbData = bbData .. ItemDisplay.propDelim .. "Coin Purchase Price" .. ItemDisplay.keyvalDelim .. item.Price
      bbData = bbData .. "|Coin Sell Price%%1|Quantity in Inventory%%0|Item Guid List%%-1|No Sale%%0|Can Preview%%0|Available Tints Group ID%%|Member Purchase Price%%" .. item.Price
      bbData = bbData .. ItemDisplay.propDelim .. "BuyBackQuantity" .. ItemDisplay.keyvalDelim .. item.Quantity
      bbData = bbData .. ItemDisplay.propDelim .. "BoughtBack" .. ItemDisplay.keyvalDelim .. item.BoughtBack
      bbData = bbData .. ItemDisplay.propDelim .. "Transaction Id" .. ItemDisplay.keyvalDelim .. transactionId
      Ui.SelectItemDefinition(tonumber(item.ItemId))
      ds = DsTable.Find("BaseClient.ItemDefinitionSelect")
      local item = ds:GetColumnName(0) .. ItemDisplay.keyvalDelim .. transactionId
      for i = 1, ds:GetColumnCount() - 1 do
        item = item .. ItemDisplay.propDelim .. ds:GetColumnName(i) .. ItemDisplay.keyvalDelim .. ds:GetData(0, i)
      end
      item = item .. ItemDisplay.propDelim .. bbData
      return item
    end,
    PopulateBuyBack = function(self, offset, count, ds, funcName)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local str = ""
      if not swf then
        return
      end
      local items = self:GetValidBuyBackItems()
      local numRows = #items
      if numRows == 0 then
        swf:Invoke("setEmptyData", "1")
        Logger:print("coinstore.lua", "setEmptyData ")
      else
        swf:Invoke("setEmptyData", "0")
      end
      if numRows > 0 then
        local offset = math.max(offset, 0)
        local countTo = math.min(offset + count, numRows)
        for i = offset, countTo - 1 do
          str = str .. self:BuildBuyBackItemString(items[i + 1]) .. ItemDisplay.itemDelim
        end
        swf:Invoke(funcName, str, numRows)
        return
      end
      swf:Invoke(funcName, str, 0)
    end,
    GetValidBuyBackItems = function(self)
      local ds = DsTable.Find(self.dsCoinStoreItemsBuyBack)
      if not ds or ds:GetRowCount() == 0 then
        return {}
      end
      local items = {}
      local rowCount = ds:GetRowCount()
      for i = 0, rowCount - 1 do
        if ds:GetData(i, 7) ~= "1" then
          local item = {}
          for c = 0, ds:GetColumnCount() - 1 do
            item[ds:GetColumnName(c)] = ds:GetData(i, c)
          end
          table.insert(items, item)
        end
      end
      return items
    end,
    SetCategoryTree = function(self)
      local datasource = self.dsCategories
      local ds = DsTree.Find(datasource)
      local data = ""
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      self.treeData = ""
      self.treeData = self.treeData .. self:SerializeTreeItem("0.1", MarketplaceStrings.ALL_ITEMS, "22665", "0")
      self.treeData = self.treeData .. self:SerializeTreeItem("-1", Ui.GetString("buyBackCat"), "7", "0")
      self:TreeRecursion(ds:GetRootNode())
      swf:Invoke("setCoinStoreCategoryTree", self.treeData)
    end,
    TreeRecursion = function(self, node)
      if not node or node:GetChildCount() == 0 then
        return
      end
      for i = 0, node:GetChildCount() - 1 do
        local child = node:GetChildNode(i)
        local catText = child:GetText()
        local catIcon = child:GetBitmapIndex()
        local catID = child:GetData(0)
        if tonumber(catID) ~= 199 and tonumber(catID) ~= Housing.HOUSING_FIXTURE_ID then
          self.treeData = self.treeData .. self:SerializeTreeItem(catID, catText, catIcon, node:GetData(0))
        end
        self:TreeRecursion(child)
      end
    end,
    SerializeTreeItem = function(self, catID, catText, catIcon, parentCatId, isGroup)
      if isGroup == nil then
        isGroup = "0"
      end
      local s = "catId~" .. tostring(catID) .. "|catText~" .. tostring(catText) .. "|catIcon~" .. tostring(catIcon) .. "|parentCatId~" .. tostring(parentCatId) .. "|isGroup~" .. isGroup .. "~~"
      return s
    end,
    GetCurrentCategoryData = function(self)
      local data = {}
      local ds = DsTree.Find(self.dsCategories)
      local curCat = math.floor(self.curSelectedCategory)
      local root = ds:GetRootNode()
      if not root or root:GetChildCount() == 0 then
        return
      end
      for i = 0, root:GetChildCount() - 1 do
        local child = root:GetChildNode(i)
        data.catID = child:GetData(0)
        data.catText = child:GetText()
        data.catIcon = child:GetBitmapIndex()
        if curCat == tonumber(data.catID) then
          return data
        end
        for c = 0, child:GetChildCount() - 1 do
          local childsChild = child:GetChildNode(i)
          if childsChild then
            data.catID = childsChild:GetData(0)
            data.catText = child:GetText() .. ">" .. childsChild:GetText()
            data.catIcon = childsChild:GetBitmapIndex()
            if curCat == tonumber(data.catID) then
              return data
            end
          end
        end
      end
      return data
    end,
    SetCoinCount = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("setPlayerCointCount", Ui.GetPlayerCoinCount())
    end,
    ShowPreview = function(self, mode, itemid, state, tintId)
      if MarketplaceHandler.boolIsShown == false then
        return
      end
      Logger:print("marketplace.lua", "ShowPreview: " .. tostring(mode) .. ", " .. tostring(state) .. ", " .. tostring(tintId))
      local nav = Window.Find("Main.wndNavigationBar")
      local sw, sh = Window.GetCanvasSize()
      local ww, wh = nav:GetSize()
      if mode == 0 then
        local wnd = Window.Find(Ui.GetName("Main.wndMarketplaceCoin"))
        if wnd then
          wnd:SetProperty("EnableCamera", 0)
        end
        MarketplaceHandler.winFocus = 1
        MarketplaceHandler:StealFocus()
        self.boolPreviewMode = false
        EquipScreen.ClearPreviewEquipItem()
        Context:Pop()
      else
        local wnd = Window.Find(Ui.GetName("Main.wndMarketplaceCoin"))
        if wnd then
          Logger:print("coinstore.lua", "Enabling Camera")
          wnd:SetProperty("EnableCamera", 1)
        end
        if state == "enter" then
          self.boolPreviewMode = true
          MarketplaceHandler.winFocus = 0
          MarketplaceHandler:StealFocus()
          Context:Push("CoinStoreItemPreview", function()
            CoinStoreHandler:HideItemPreview()
          end)
        end
        EquipScreen.ClearPreviewStyleCard()
        EquipScreen.PreviewEquipItemById(tonumber(itemid), tintId)
        Ui.SetCameraOffset2D(-150, 300)
      end
    end,
    HideItemPreview = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("hideItemPreviewForCoinStore")
    end,
    SetSortOption = function(self, sortId)
      Logger:print("coinstore.lua", " sort : " .. sortId)
      CoinStoreScreen.SortItems(tonumber(sortId), self.currentViewDs)
    end,
    SetSortOptions = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local res = DataSourceMethods:ParseDs(MarketplaceHandler.dsSortOptions, ItemDisplay.itemDelim, ItemDisplay.propDelim, ItemDisplay.keyvalDelim)
      local res2 = DataSourceMethods:ParseDs(MarketplaceHandler.dsSortState, ItemDisplay.itemDelim, ItemDisplay.propDelim, ItemDisplay.keyvalDelim)
      swf:Invoke("setSortOptionsForCoinStore", res, res2)
    end,
    SetSearch = function(self, terms)
      self.currentViewDs = self.dsSearchResults
      self.searchAfterInit = terms
      self:InitializeFilters()
    end,
    SetSearchCompleted = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("setSearchCompletedForCoinStore")
      self:handleDataUpdate()
    end,
    InitializeFilters = function(self)
      Logger:print("marketplace.lua", "init search engine")
      self.initializingSearchEngine = true
      CoinStoreScreen.InitializeSearchEngine()
    end,
    CheckSearchEngineInitialized = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      if tostring(CoinStoreScreen.IsSearchEngineInitialized()) == "true" then
        swf:Invoke("setSearchEngineInitializedForCoinStore")
      end
    end,
    GetFilterData = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local res = DataSourceMethods:ParseDs(MarketplaceHandler.dsFilters, ItemDisplay.itemDelim, ItemDisplay.propDelim, ItemDisplay.keyvalDelim)
      swf:Invoke("setFilterDataForCoinStore", res)
    end,
    GetFilterState = function(self)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      local dsName = self.dsFilterState
      local res = DataSourceMethods:ParseDs(dsName, ItemDisplay.itemDelim, ItemDisplay.propDelim, ItemDisplay.keyvalDelim)
      swf:Invoke("setFilterStateForCoinStore", res)
    end,
    AddItemFilter = function(self, filterId, optionId)
      CoinStoreScreen.AddSearchFilter(tonumber(filterId), tonumber(optionId))
    end,
    RemoveItemFilter = function(self, filterId, optionId)
      CoinStoreScreen.RemoveSearchFilter(tonumber(filterId), tonumber(optionId))
    end,
    ApplyItemFilters = function(self)
      CoinStoreScreen.ApplySearchFilters()
      self:handleDataUpdate()
      self:GetFilterState()
    end,
    ClearFilters = function(self)
      CoinStoreScreen.ClearAllSearchFilters()
      self:handleDataUpdate()
      self:GetFilterState()
    end,
    OnSell = function(self, result, itemGuid, itemId, quantity, price, tintId)
      CoinStoreHandler:SetCoinCount()
    end,
    OnBuy = function(self, result, itemGuid, itemId, quantity, price, tintId)
      self:RefreshCurDisplay()
      self:SetCoinCount()
      self:CanPurchaseItem(itemId, self.curBuyItemTintId)
    end,
    OnBuyBack = function(self, result, transactionId)
      self:RefreshCurDisplay()
      self:SetCoinCount()
    end,
    OnInitializeSearchEngine = function(self)
      CoinStoreHandler.initializingSearchEngine = false
      if CoinStoreHandler.searchAfterInit then
        CoinStoreScreen.SearchItems(CoinStoreHandler.searchAfterInit)
        CoinStoreHandler.searchAfterInit = nil
        CoinStoreHandler:SetSearchCompleted()
      end
      CoinStoreHandler:CheckSearchEngineInitialized()
    end,
    DisplayStoreItems = function(self, referrerId, referrerContext)
      self.referrerId = referrerId
      self.referrerContext = referrerContext
      DsTable.Find(self.dsCoinStoreGroupItems):EnableScriptEvents()
      BaseClient_CoinStore_CoinStoreItemGroup_OnDataChanged = self.handleDataChanged
      MarketplaceHandler:Show(MarketplaceEnum.COIN_STORE)
      self:SetDatasourceView("Coin Shop Items", CoinStoreHandler.dsCoinStoreGroupItems)
    end,
    DisplayStoreItemCategory = function(self, referrerId, referrerContext, categoryId)
      self.referrerId = referrerId
      self.referrerContext = referrerContext
      Logger:print("coinstore.lua", "DisplayStoreItemCategory , cat " .. categoryId)
      MarketplaceHandler:Show(MarketplaceEnum.COIN_STORE)
      local swf = GfxCtrl.Find(MarketplaceHandler.swfName)
      swf:Invoke("setCoinStoreCategory", categoryId, "")
      swf:Invoke("selectCoinStoreCategory", categoryId)
    end
  }
end)()
