        local sw, sh = Window.GetCanvasSize()
        local wndX, wndY = self.GetWindow():GetPosition()
        local wndW, wndH = self.GetWindow():GetSize()
        local toX
        local yValue = sh / 2 - wndH / 2
        if self.align == 0 then
          toX = 60
          self.GetWindow():SetPosition(60, yValue - 15)
        else
          toX = 60
          self.GetWindow():SetPosition(sw + 350, yValue - 15)
