      if focus == "1" then
        Window.SetFocus()
      end
    end
  }
  function Main_wndCharacterCreate_swfCharacterCreate_OnUserEvent(a, b, c, d, e, f)
    if a == "creationFinished" then
      HUD:PlaySound("Selected")
      Ui.CreationFinished()
    elseif a == "creationAborted" then
      HUD:PlaySound("Selected")
      Ui.CreationAborted()
    elseif a == "creationRequestButtonData" then
      Ui.CreationRequestButtonData(tonumber(b), tonumber(c))
    elseif a == "changeSelectedCategory" then
      Ui.CreationChangeCategory(tonumber(b))
    elseif a == "equipItem" then
      Ui.CreationChangeItem(tonumber(b), tonumber(c))
    elseif a == "PlaySound" or a == "playSound" then
      HUD:PlaySound(b)
    elseif a == "AS_Print" then
      self:print(a .. "( " .. tostring(b) .. " )")
    else
      self:print(a)
    end
  end
end)()
