      Logger:print("CharacterCreatePopups.lua", "acceptSelected")
      if CharacterCreatePopups.teleportPrompt == true then
        CharacterCreatePopups.teleportPrompt = false
        CharacterCreatePopups:Hide()
        Ui.TeleportMeToObjective()
      elseif CharacterCreatePopups.styleCardPrompt == true then
        CharacterCreatePopups.styleCardPrompt = false
        CharacterCreatePopups:Hide()
        StyleCardHandler:AcceptChanges()
        JobHandler:ModeSwitch(0)
      end
    elseif a == "backSelected" then
      Logger:print("CharacterCreatePopups.lua", "backSelected")
      if CharacterCreatePopups.teleportPrompt == true then
        CharacterCreatePopups.teleportPrompt = false
        CharacterCreatePopups:Hide()
      elseif CharacterCreatePopups.styleCardPrompt == true then
        CharacterCreatePopups.styleCardPrompt = false
        CharacterCreatePopups:Hide()
        StyleCardHandler:RevertChanges()
        JobHandler:ModeSwitch(0)
      end
    end
  end
end)()
