;(function()
  ActivityPortalPS3 = {
    swf = Ui.GetName("Main.wndActivityPortalNew.swfActivityPortalNew"),
    wnd = Ui.GetName("Main.wndActivityPortalNew"),
    FeaturedActivitiesDsName = "Activities.Featured",
    CombatActivitiesDsName = "Activities.Category1001",
    RacingActivitiesDsName = "Activities.Category1002",
    MatchThreeActivitiesDsName = "Activities.Category1003",
    CookingActivitiesDsName = "Activities.Category1004",
    TowerDefenseActivitiesDsName = "Activities.Category1005",
    MiscActivitiesDsName = "Activities.Category1009",
    FishingActivitiesDsName = "Activities.Category1010",
    SoccerActivitiesDsName = "Activities.Category1011",
    DerbyActivitiesDsName = "Activities.Category1013",
    MiningActivitiesDsName = "Activities.Category1014",
    ForgingActivitiesDsName = "Activities.Category1015",
    MeetingActivitiesDsName = "Activities.Category1",
    TutorialActivitiesDsName = "Activities.Category1021",
    PickedActivitiesDsName = "Activities.PickedActivities",
    pane = nil,
    win = nil,
    Y = 0,
    currentCategory = -1,
    Show = function(self)
      Ui.ShowActivityPortalWindow(1)
      self.pane = GfxCtrl.Find(self.swf)
      self.win = Window.Find(self.wnd)
      NonModalContext:AddContext(self)
      HUD:PlaySound("WindowShow")
      self:OnResize()
      self:AddCategoryDataToFlash()
      self:AddActivitiesToFlash(0, 11)
      WindowTweener:Create("Main.wndActivityPortalNew", "Y", nil, self.Y, 0.5, function()
        self.pane:Invoke("selectDefault")
      end)
    end,
    Hide = function(self)
      TutorialDialog:Hide()
      local swfWindow = GfxCtrl.Find(self.swf)
      Ui.ShowActivityPortalWindow(0)
      NonModalContext:RemoveContext(self)
      HUD:PlaySound("WindowHide")
      self.win:Hide()
      swfWindow:Unload()
    end,
    OnResize = function(self)
      self.pane = GfxCtrl.Find(self.swf)
      self.win = Window.Find(self.wnd)
      local sw, sh = Window.GetCanvasSize()
      local w, h = self.win:GetSize()
      self.win:Show()
      self.win:SetPosition(sw / 2 - w / 2, sh / 2 - h / 2)
      self.Y = sh / 2 - h / 2
    end,
    AddCategoryDataToFlash = function(self)
      local data
      data = "catId~1001|catText~S##LeaderboardCategoryCombat|catIcon~1345|parentCatId~0~~"
      data = data .. "catId~1004|catText~S##PS3_Cooking|catIcon~7546|parentCatId~0~~"
      data = data .. "catId~1013|catText~S##PS3_Demolition_Derby|catIcon~7549|parentCatId~0~~"
      data = data .. "catId~9999|catText~S##PS3_Featured|catIcon~397|parentCatId~0~~"
      data = data .. "catId~1010|catText~S##PS3_Fishing|catIcon~21061|parentCatId~0~~"
      data = data .. "catId~1015|catText~S##LeaderboardCategoryForging|catIcon~7552|parentCatId~0~~"
      data = data .. "catId~1003|catText~S##PS3_Matching|catIcon~7555|parentCatId~0~~"
      data = data .. "catId~1|catText~S##PS3_Meeting_Places|catIcon~28358|parentCatId~0~~"
      data = data .. "catId~1014|catText~S##PS3_Mining|catIcon~7561|parentCatId~0~~"
      data = data .. "catId~1009|catText~S##PS3_Miscellaneous|catIcon~28413|parentCatId~0~~"
      data = data .. "catId~1002|catText~S##PS3_Racing|catIcon~7567|parentCatId~0~~"
      data = data .. "catId~1011|catText~S##PS3_Soccer|catIcon~1317|parentCatId~0~~"
      data = data .. "catId~1005|catText~S##PS3_Tower_Defense|catIcon~7588|parentCatId~0~~"
      data = data .. "catId~1021|catText~S##PS3 Tutorial|catIcon~397|parentCatId~0"
      self.currentCategory = 1001
      self.pane:Invoke("SetCategoryTree", data)
      self.pane:Invoke("setMode", 1)
    end,
    AddActivitiesToFlash = function(self, offset, count)
      local data = ""
      local tmpData = ""
      local dsName
      if self.currentCategory == 1001 then
        dsName = self.CombatActivitiesDsName
      elseif self.currentCategory == 1004 then
        dsName = self.CookingActivitiesDsName
      elseif self.currentCategory == 1013 then
        dsName = self.DerbyActivitiesDsName
      elseif self.currentCategory == 9999 then
        dsName = self.FeaturedActivitiesDsName
      elseif self.currentCategory == 1010 then
        dsName = self.FishingActivitiesDsName
      elseif self.currentCategory == 1015 then
        dsName = self.ForgingActivitiesDsName
      elseif self.currentCategory == 1003 then
        dsName = self.MatchThreeActivitiesDsName
      elseif self.currentCategory == 1 then
        dsName = self.MeetingActivitiesDsName
      elseif self.currentCategory == 1014 then
        dsName = self.MiningActivitiesDsName
      elseif self.currentCategory == 1009 then
        dsName = self.MiscActivitiesDsName
      elseif self.currentCategory == 1002 then
        dsName = self.RacingActivitiesDsName
      elseif self.currentCategory == 1011 then
        dsName = self.SoccerActivitiesDsName
      elseif self.currentCategory == 1005 then
        dsName = self.TowerDefenseActivitiesDsName
      elseif self.currentCategory == 1021 then
        dsName = self.TutorialActivitiesDsName
      end
      local dsTable = DsTable.Find(dsName)
      local numRows = 0
      local rowsUsed = 0
      local useableRows = 0
      if dsTable then
        numRows = dsTable:GetRowCount()
        local lastRow = math.min(offset + count, numRows)
        Logger:print("apps3.lua", "Selecting Activities for Category " .. tostring(self.currentCategory) .. " with " .. tostring(numRows) .. " rows starting at offset " .. offset .. " and grabbing " .. count .. " rows")
        if numRows > 0 then
          for i = 0, numRows - 1 do
            if dsTable:GetData(i, 8) == "1" and tonumber(dsTable:GetData(i, 0)) ~= 510 and tonumber(dsTable:GetData(i, 0)) ~= 511 and tonumber(dsTable:GetData(i, 0)) ~= 512 and tonumber(dsTable:GetData(i, 0)) ~= 513 and tonumber(dsTable:GetData(i, 0)) ~= 1049 then
              useableRows = useableRows + 1
            end
          end
          for i = 0, numRows - 1 do
            if dsTable:GetData(i, 8) == "1" then
              rowsUsed = rowsUsed + 1
              if offset < rowsUsed and tonumber(dsTable:GetData(i, 0)) ~= 510 and tonumber(dsTable:GetData(i, 0)) ~= 511 and tonumber(dsTable:GetData(i, 0)) ~= 512 and tonumber(dsTable:GetData(i, 0)) ~= 513 and tonumber(dsTable:GetData(i, 0)) ~= 1049 then
                if string.len(tmpData) == 0 then
                  tmpData = "MiniGameId^" .. dsTable:GetData(i, 0) .. "::Name^" .. Ui.GetStringById(dsTable:GetData(i, 3))
                else
                  tmpData = "##MiniGameId^" .. dsTable:GetData(i, 0) .. "::Name^" .. Ui.GetStringById(dsTable:GetData(i, 3))
                end
                data = data .. tmpData
                Logger:print("  apps3.lua", tostring(i) .. " " .. tmpData)
                if rowsUsed == count + offset then
                  break
                end
              end
            end
          end
        end
      end
      self.pane:Invoke("setData", data, useableRows)
    end,
    OnUserEvent = function(self, a, b, c, d, e, f)
      if tostring(a) == "Hide" then
        self:Hide()
        NavigationHandler:EnableBar()
      elseif tostring(a) == "SetCurrentCategory" then
        Logger:print("apps3.lua", "Category Changed: " .. tonumber(b))
        self.currentCategory = tonumber(b)
        self:AddActivitiesToFlash(0, 11)
      elseif tostring(a) == "requestData" then
        Logger:print("apps3.lua", "requestData -> Offset: " .. tonumber(b) .. " Count: " .. tonumber(c))
        self:AddActivitiesToFlash(tonumber(b), tonumber(c))
      elseif tostring(a) == "SelectItem" and b then
        self:Hide()
        GameDock_PS3:NavigationExit()
        Ui.RequestToJoinActivity(b, false)
      end
    end
  }
  function Main_wndActivityPortalNew_swfActivityPortalNew_OnUserEvent(a, b, c, d, e, f)
    ActivityPortalPS3:OnUserEvent(a, b, c, d, e, f)
  end
end)()
