  }
  FriendsWidget = {
    windowShown = nil,
    windowVisible = nil,
    minimized = nil,
    height = 400,
    textFocus = 0,
    guildGuid = 0,
    showGuilds = 1,
    canCreateGuild = nil,
    isToggleOn = false,
    isInHouse = 0,
    isInOwnHouse = 0,
    m_groupNumRows = 0,
    FRIENDS_VISIBLE = "friend",
    AQUAINTANCES_VISIBLE = "aquaintances",
    IGNORE_VISIBLE = "ignore",
    GUILD_VISIBLE = "guild",
    GROUP_VISIBLE = "group",
    NONE_VISIBLE = "none",
    whichListVisible = NONE_VISIBLE,
    isShown = false,
    WaitingForFriendName = 0,
    waitingForIgnoreName = 0,
    WaitingForGuildInviteeName = 0,
    waitingForGuildRename = 0,
    waitingForGuildName = 0,
    movieName = Ui.GetName("Main.wndFriendsWidget.swfFriendsWidget"),
    OnUpdateGroupList = function(self)
      if self.whichListVisible == self.GROUP_VISIBLE then
        local ds = DsTable.Find("BaseClient.GroupMemberData")
        self:PopulateGroupList()
        local swf = GfxCtrl.Find(self.movieName)
        swf:SoftInvoke("displayListData", 5)
      end
    end,
