      if self.whichListVisible == self.FRIENDS_VISIBLE then
        Logger:print("friendswidget.lua", "OnUpdateFriendsList")
        self:PopulateFriendsList()
        local swf = GfxCtrl.Find(self.movieName)
        swf:SoftInvoke("displayListData", 1)
      end
    end,
    OnUpdateAquaintancesList = function(self)
      if self.whichListVisible == self.AQUAINTANCES_VISIBLE then
        self:PopulateAquaintancesList()
        local swf = GfxCtrl.Find(self.movieName)
        swf:SoftInvoke("displayListData", 2)
      end
    end,
    OnUpdateIgnoreList = function(self)
      if self.whichListVisible == self.IGNORE_VISIBLE then
        self:PopulateIgnoredList()
        local swf = GfxCtrl.Find(self.movieName)
        swf:SoftInvoke("displayListData", 4)
      end
    end,
    OnUpdateGuildList = function(self)
      ChatLog:SetGuildFilter()
      if self.whichListVisible == self.GUILD_VISIBLE then
        self:PopulateGuildList()
        local swf = GfxCtrl.Find(self.movieName)
        swf:SoftInvoke("displayListData", 3)
      end
    end,
    OnRemoveGuildMember = function(self, row)
      if self.whichListVisible == self.GUILD_VISIBLE then
        local swf = GfxCtrl.Find(self.movieName)
        swf:SoftInvoke("removeGuildMember", row)
        swf:SoftInvoke("displayListData", 3)
      end
    end,
    OnUpdateFriendsItem = function(self, row, column, value)
      if self.whichListVisible == self.FRIENDS_VISIBLE then
        local m = GfxCtrl.Find(self.movieName)
        m:SoftInvoke("updateFriend", row, column, value)
      end
    end,
    OnUpdateGuildItem = function(self, row, column, value)
      if self.whichListVisible == self.GUILD_VISIBLE then
        local m = GfxCtrl.Find(self.movieName)
        m:SoftInvoke("updateGuildMember", row, column, value)
      end
    end,
    PopulateGroupList = function(self)
      local m = GfxCtrl.Find(self.movieName)
      local ds = DsTable.Find("BaseClient.GroupMemberData")
      if ds then
        local numRows = ds:GetRowCount()
        m:Invoke("clearGroupMembers")
        for i = 0, numRows - 1 do
          local dsSub = DsTable.Find(DataSources[DS_PROFILES])
          local curProfileTbl = {}
          if dsSub then
            local isLocal, isLeader, isMuted
            local leaderString = ds:GetData(i, 7)
            if tonumber(Ui.GetPlayerGuid()) == tonumber(ds:GetData(i, 1)) then
              isLocal = 1
            else
              isLocal = 0
            end
            if leaderString == "Leader" or leaderString == "Solo" then
              isLeader = 1
            else
              isLeader = 0
            end
            if GroupScreen.IsPlayerMuted(ds:GetData(i, 1)) == true then
              isMuted = 1
            else
              isMuted = 0
            end
            local rows = dsSub:GetRowCount()
            for index = 0, rows - 1 do
              local id = dsSub:GetData(index, 0)
              local name = dsSub:GetData(index, 1)
              if tonumber(ds:GetData(i, 2)) == tonumber(id) then
                m:Invoke("addGroupMember", i, ds:GetData(i, 0), ds:GetData(i, 1), 1, ds:GetData(i, 5), name, ds:GetData(i, 4), ds:GetData(i, 3), isLocal, isLeader, isMuted, ds:GetData(i, 16))
              end
            end
          end
        end
        m_groupNumRows = numRows
      end
      self.whichListVisible = self.GROUP_VISIBLE
      self:SetCanvasSize()
    end,
    PopulateFriendsList = function(self)
      if self.isShown == 1 then
        self:setStrings()
        local m = GfxCtrl.Find(self.movieName)
        if HUD.isInStartingZone then
          m:SoftInvoke("SetIsInStartingZone", 1)
        else
          m:SoftInvoke("SetIsInStartingZone", 0)
        end
        self:SetIsInHouse(self.isInHouse, self.isInOwnHouse)
        local ds = DsTable.Find("BaseClient.FriendsList")
        if ds then
          local numRows = ds:GetRowCount()
          local numCols = ds:GetColumnCount()
          m:Invoke("clearFriends")
          for i = 0, numRows - 1 do
