          m:Invoke("ShowGuildSignup", tostring(canCreate))
          m:Invoke("setCount", Ui.GetString("NotInGuild"))
        else
          m:Invoke("HideGuildPage")
          local ds = DsTable.Find("BaseClient.GuildMembers")
          if ds then
            local numRows = ds:GetRowCount()
            local numCols = ds:GetColumnCount()
            for i = 0, numRows - 1 do
              if Ui.GetPlayerGuid() == ds:GetData(i, GuildMembersListDsColumns.Guid) then
                m:Invoke("SetPlayersGuild", guildsDs:GetData(0, GuildsListDsColumns.Name), ds:GetData(i, GuildMembersListDsColumns.Rank), "g" .. Ui.GetPlayerGuid())
