      if friendDs then
        friendDs:EnableScriptEvents()
      end
      local ds = DsTable.Find("BaseClient.IgnoreList")
      if ds then
        ds:EnableScriptEvents()
      end
      local ds2 = DsTable.Find("BaseClient.GuildMembers")
      if ds2 then
        ds2:EnableScriptEvents()
      end
      local ds3 = DsTable.Find("BaseClient.Guilds")
      if ds3 then
        ds3:EnableScriptEvents()
      end
      local ds4 = DsTable.Find("BaseClient.Housing.PlayerHouseList")
      if ds4 then
        ds4:EnableScriptEvents()
      end
      local ds5 = DsTable.Find("BaseClient.GroupMemberData")
      if ds5 then
        ds5:EnableScriptEvents()
      end
      self:SetGuild()
      if Housing.isInInstance then
        if Housing.allowEdit then
          self:SetIsInHouse(1, 1)
        else
          self:SetIsInHouse(1, 0)
