  GuildDialog = {
    MODE_CREATE_GUILD = 1,
    MODE_RENAME_GUILD = 2,
    waitingForGuildRename = 0,
    messages = {
      Ui.GetString("CreateGuildText"),
      Ui.GetString("RenameGuildText")
    },
    titles = {
      Ui.GetString("CreateGuildTitle"),
      Ui.GetString("RenameGuildTitle")
    },
    wndName = "Main.wndGuildDialog",
    swfName = "Main.wndGuildDialog.swfGuildDialog",
    Show = function(self, denial)
      local window = Window.Find(Ui.GetName(self.wndName))
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      local width, height = window:GetSize()
      local screenWidth, screenHeight = Window.GetCanvasSize()
      local centerX = screenWidth / 2 - width / 2
      local centerY = screenHeight / 2 - height / 2
      window:SetPosition(centerX, -height)
      window:Show()
      WindowTweener:Create(self.wndName, "Y", nil, centerY, 0.3)
      if denial then
        swf:Invoke("SetMode", self.MODE_RENAME_GUILD, self.titles[self.MODE_RENAME_GUILD], self.messages[self.MODE_RENAME_GUILD])
      else
        swf:Invoke("SetMode", self.MODE_CREATE_GUILD, self.titles[self.MODE_CREATE_GUILD], self.messages[self.MODE_CREATE_GUILD])
      end
    end,
    Hide = function(self)
      local window = Window.Find(Ui.GetName(self.wndName))
      local width, height = window:GetSize()
      Ui.SetMovementEnabled(1)
      Ui.SetKeyboardEnabled(1)
      WindowTweener:Create(self.wndName, "Y", nil, -height, 0.3, function()
        local w1 = Window.Find(Ui.GetName(GuildDialog.wndName))
        local swf = GfxCtrl.Find(Ui.GetName(GuildDialog.swfName))
        swf:Unload()
        w1:Hide()
      end)
    end,
    ShowNameDenied = function(self)
      self:Show(true)
    end,
    Rename = function(self, a)
      local swf = GfxCtrl.Find(Ui.GetName(self.swfName))
      swf:Invoke("SetNameText", a)
    end
  }
  function PS3_Keyboard_Text_Entered(a)
    BugHandler_Keyboard_Text_Entered(a)
    if FriendsWidget.waitingForFriendName == 1 then
      Ui.AddFriend(a)
      FriendsWidget.waitingForFriendName = 0
    end
    if FriendsWidget.waitingForIgnoreName == 1 then
      Ui.IgnorePlayer(a)
      FriendsWidget.waitingForIgnoreName = 0
    end
    if FriendsWidget.waitingForGuildInviteeName == 1 then
      Guild.Invite(FriendsWidget.guildGuid, 0, a)
      FriendsWidget.waitingForGuildInviteeName = 0
    end
    if FriendsWidget.waitingForGuildName == 1 then
      Guild.Create(a)
      FriendsWidget.waitingForGuildName = 0
    end
    if FriendsWidget.waitingForGuildRename == 1 then
      Guild.Rename(FriendsWidget.guildGuid, a)
      FriendsWidget.waitingForGuildRename = 0
    end
    if GuildDialog.waitingForGuildRename == 1 then
      GuildDialog:Rename(a)
      GuildDialog.waitingForGuildRename = 0
    end
  end
  function PS3_Keyboard_Cancelled()
    BugHandler_Keyboard_Cancelled()
    if FriendsWidget.waitingForFriendName == 1 then
      FriendsWidget.waitingForFriendName = 0
    end
    if FriendsWidget.waitingForIgnoreName == 1 then
      FriendsWidget.waitingForIgnoreName = 0
    end
    if FriendsWidget.waitingForGuildInviteeName == 1 then
      FriendsWidget.waitingForGuildInviteeName = 0
    end
    if FriendsWidget.waitingForGuildName == 1 then
      FriendsWidget.waitingForGuildName = 0
    end
    if FriendsWidget.waitingForGuildRename == 1 then
      FriendsWidget.waitingForGuildRename = 0
    end
    if GuildDialog.waitingForGuildRename == 1 then
      GuildDialog.waitingForGuildRename = 0
    end
  end
  function Main_wndFriendsWidget_swfFriendsWidget_OnUserEvent(a, b, c, d, e)
    if a == "CloseWindowPS3" then
      FriendsWidget:Hide()
      GameDock_PS3:SetVisibility(1)
    elseif a == "init" then
      FriendsWidget:Init()
    elseif a == "SetCurrentCategory" then
      local m = GfxCtrl.Find(FriendsWidget.movieName)
      if tonumber(b) == 1 then
        FriendsWidget:PopulateFriendsList()
      elseif tonumber(b) == 2 then
        FriendsWidget:PopulateAquaintancesList()
      elseif tonumber(b) == 3 then
        FriendsWidget:PopulateGuildList()
      elseif tonumber(b) == 4 then
        FriendsWidget:PopulateIgnoredList()
      elseif tonumber(b) == 5 then
        FriendsWidget:PopulateGroupList()
      end
      m:Invoke("displayListData", tonumber(b))
    elseif a == "addFriend" then
      if Ui.AddFriend then
        FriendsWidget:SetToFront()
        Ui.AddFriend(b)
      end
    elseif a == "inviteToGuild" then
      Guild.Invite(FriendsWidget.guildGuid, string.sub(b, 2), 0)
    elseif a == "showCreateGuild" then
      Ui.LuaRequestVirtualKeyboard(1, "", "Create Guild")
      FriendsWidget.waitingForGuildName = 1
    elseif a == "teleportPlayerToFriend" then
      if Ui.TeleportToFriend then
        FriendsWidget:Hide()
        GameDock_PS3:SetVisibility(1)
        Ui.TeleportToFriend(b)
      end
    elseif a == "startChat" then
      if Ui.IsChatAllowed() then
        FriendsWidget:Hide()
        GameDock_PS3:SetVisibility(1)
        Ui.LuaRequestVirtualKeyboard(0, "/tell \"" .. b .. "\" ", "Chat")
      else
        PopUpPrompt:Show()
        PopUpPrompt:SetLayout(PopUpPrompt.LT_CHAT_DISABLED)
      end
    elseif a == "locate" then
      FriendsWidget:Hide()
      Atlas:Show()
      Atlas:LocateFriend(b)
    elseif a == "ignore" then
      Ui.IgnorePlayer(b)
    elseif a == "unignore" then
      Ui.StopIgnoringPlayer(b)
    elseif a == "inviteToGroup" then
      Ui.InviteToGroup(b)
    elseif a == "removeFromGuild" then
      if Ui.GetPlayerGuid() == string.sub(b, 2) then
        Guild.Quit(FriendsWidget.guildGuid)
      else
        Guild.Kick(FriendsWidget.guildGuid, string.sub(b, 2))
      end
    elseif a == "promoteInGuild" then
      Guild.Promote(FriendsWidget.guildGuid, string.sub(b, 2))
    elseif a == "demoteInGuild" then
      Guild.Demote(FriendsWidget.guildGuid, string.sub(b, 2))
    elseif a == "addFriend" then
      if Ui.AddFriend then
        Ui.AddFriend(b)
      end
    elseif a == "removeFriend" then
      if Ui.RemoveFriend then
        Ui.RemoveFriend(b)
      end
    elseif a == "goToHouse" then
      House.RequestPlayerHouses(string.sub(b, 2), c)
    elseif a == "inviteToHouse" then
      House.InviteToHouse(string.sub(b, 2))
    elseif a == "disbandGroup" then
      GroupHandler:LeaveGroup()
    elseif a == "removeFromGroup" then
      GroupHandler:KickMember(b)
    elseif a == "mute" then
      GroupHandler:MuteMember(b)
    elseif a == "leaveGroup" then
      GroupHandler:LeaveGroup()
    elseif a == "addFriendManual" then
      Ui.LuaRequestVirtualKeyboard(1, "", "Add Friend")
      FriendsWidget.waitingForFriendName = 1
    elseif a == "ignoreManual" then
      Ui.LuaRequestVirtualKeyboard(1, "", "Ignore")
      FriendsWidget.waitingForIgnoreName = 1
    elseif a == "inviteToGuildByNameManual" then
      Ui.LuaRequestVirtualKeyboard(1, "", "Invite To Guild")
      FriendsWidget.waitingForGuildInviteeName = 1
    elseif a == "renameGuild" then
      Ui.LuaRequestVirtualKeyboard(1, "", "Rename Guild")
      FriendsWidget.waitingForGuildRename = 1
    elseif a == "ASPrint" then
      Logger:print("friendswidget.lua", b)
    elseif a == "addFriendPSN" then
      Ui.SendPSNFriendInvite(b)
    end
  end
  function Main_wndGuildDialog_swfGuildDialog_OnUserEvent(a, b, c, d, e)
    if a == "closeWindow" then
      GuildDialog:Hide()
    elseif a == "sendGuildName" then
      if FriendsWidget.guildGuid ~= 0 then
        Guild.Rename(FriendsWidget.guildGuid, b)
      else
        local guildsDs = DsTable.Find("BaseClient.Guilds")
        if guildsDs then
          local gnumRows = guildsDs:GetRowCount()
          if gnumRows ~= 0 then
            FriendsWidget.guildGuid = guildsDs:GetData(0, GuildsListDsColumns.rGuid)
          end
        end
        Guild.Rename(FriendsWidget.guildGuid, b)
      end
      GuildDialog:Hide()
    elseif a == "renameGuild" then
      Ui.LuaRequestVirtualKeyboard(1, "", "Rename Guild")
      GuildDialog.waitingForGuildRename = 1
    elseif a == "PlaySound" then
      HUD:PlaySound(b)
    end
  end
  function BaseClient_FriendsList_OnDataUpdate()
    FriendsWidget:OnUpdateFriendsList()
  end
