;(function()
  Leaderboards = {
    swfName = Ui.GetName("Main.wndLeaderboard.swfLeaderboard"),
    wndName = Ui.GetName("Main.wndLeaderboard"),
    swf = nil,
    wnd = nil,
    currentCategory = -1,
    currentCategorySubIndex = 0,
    processingCategoryQueries = false,
    waitingForDsUpdate = false,
    populatingWithMyRank = false,
    Show = function(self)
      self.swf = GfxCtrl.Find(self.swfName)
      self.wnd = Window.Find(self.wndName)
      NonModalContext:AddContext(self)
      self:OnResize()
      self.swf:Invoke("clearLeaderboardCategories")
      self:AddCategoryDataToFlash()
      DataSourceConnection:Connect("BaseClient.LeaderBoard", Leaderboards, "OnLeaderBoardData")
    end,
    Hide = function(self)
      NonModalContext:RemoveContext(self)
      self.wnd:Hide()
      self.swf:Unload()
    end,
    OnResize = function(self)
      local sw, sh = Window.GetCanvasSize()
      local w, h = self.wnd:GetSize()
      self.wnd:Show()
      self.wnd:SetPosition(sw / 2 - w / 2, sh / 2 - h / 2)
    end,
    AddCategoryDataToFlash = function(self)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryMyLeaderboards"), 1)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryArtifacts"), 35593)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryCheckers"), 3379)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryChess"), 3378)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryCooking"), 20226)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryDemolition"), 3383)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryForging"), 19201)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryGlobal"), 140966)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryHarvest"), 35591)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryMailSort"), 35595)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryMining"), 7910)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryScavenger"), 3374)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategorySmelting"), 15293)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategorySoccer"), 406401)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryTowerDefense"), 3386)
      self.swf:Invoke("addLeaderboardCategory", Ui.GetString("LeaderboardCategoryRacing"), 3382)
      self.swf:Invoke("setMode", 1)
      self.swf:Invoke("UpdateComboBox")
    end,
    SelectCategory = function(self, categoryID)
      Logger:print("leaderboards.lua", "Selecting Category " .. categoryID)
      self.currentCategory = categoryID
      if categoryID == 1 then
        local guid = Ui.GetPlayerGuid()
        local request = "guids=" .. tostring(guid)
        Logger:print("leaderboards.lua", "SelectCategory-> " .. request)
        Ui.RequestLeaderBoardData(request)
      else
        Ui.ClearCompiledEntries()
        self.processingCategoryQueries = true
        self:ProcessNextCategoryQuery()
      end
    end,
    SelectLeaderboard = function(self, leaderboardType, leaderboardId)
      local request = "leaderboardType=" .. leaderboardType .. "&leaderboardId=" .. leaderboardId .. "&topRank=false&page=1&pageSize=500"
      Ui.RequestLeaderBoardData(request)
    end,
    FindMyRank = function(self)
      Logger:print("leaderboards.lua", "Finding my rank...")
      local guid = Ui.GetPlayerGuid()
      local ds = DsTable.Find("BaseClient.LeaderBoard.Entries")
      local rows = ds:GetRowCount()
      if rows > 0 then
        for i = 0, rows - 1 do
          if ds:GetData(i, 2) == guid then
            Logger:print("leaderboards.lua", "My Rank found")
            self.populatingWithMyRank = true
            self:SendLeaderBoardDataToFlash(i, 10)
            return
          end
        end
      end
      Logger:print("leaderboards.lua", "My Rank NOT found")
      self.swf:Invoke("ClearLoadingIcon")
    end,
    ProcessNextCategoryQuery = function(self)
      local ds = DsTable.Find("BaseClient.LeaderBoard.DataTypes")
      local rows = ds:GetRowCount()
      local dataFound = false
      Logger:print("leaderboards.lua", "ProcessNextCategoryQuery " .. rows .. " rows")
      if rows > 0 then
        for i = self.currentCategorySubIndex, rows - 1 do
          if self.currentCategory == tonumber(ds:GetData(i, 5)) and tonumber(ds:GetData(i, 2)) == 1 then
            local request = "leaderboardType=" .. ds:GetData(i, 0) .. "&leaderboardId=" .. ds:GetData(i, 1) .. "&topRank=true"
            Logger:print("leaderboards.lua", "ProcessCategory-> " .. request)
            Ui.RequestLeaderBoardData(request)
            dataFound = true
            self.waitingForDsUpdate = true
            self.currentCategorySubIndex = i + 1
            return
          end
        end
        if dataFound == false then
          Logger:print("leaderboards.lua", "ProcessNextCategoryQuery no data found")
          Ui.SortCompiled()
          self:SendCategoryDataToFlash(0, 10)
          self.processingCategoryQueries = false
          self.currentCategorySubIndex = 0
        end
      end
    end,
    SendMyLeaderBoardDataToFlash = function(self, offset, count)
      local ds = DsTable.Find("BaseClient.LeaderBoard.Entries")
      local rows = ds:GetRowCount()
      Logger:print("leaderboards.lua", "OnLeaderBoardData " .. rows)
      local data
      if rows > 0 then
        local leaderboardName, rank, score, leaderboardId, leaderboardType
        local endCount = offset + count
        if rows < endCount then
          endCount = rows
        end
        for i = offset, endCount - 1 do
          leaderboardName = ds:GetData(i, 6)
          rank = ds:GetData(i, 0)
          score = ds:GetData(i, 3)
          leaderboardId = ds:GetData(i, 4)
          leaderboardType = ds:GetData(i, 5)
          local tag
          if tonumber(leaderboardType) == 0 then
            tag = "Stars: " .. score
          elseif tonumber(leaderboardType) == 1 then
            tag = "Score: " .. score
          elseif tonumber(leaderboardType) == 2 then
            tag = "Time: " .. math.floor(score / 60) .. "min " .. score % 60 .. "sec"
          elseif tonumber(leaderboardType) == 3 then
            tag = "Enemies: " .. score
          else
            tag = score
          end
          if i == offset then
            data = "LeaderBoardType^" .. leaderboardType .. "::LeaderBoardId^" .. leaderboardId .. "::ColumnOne^" .. leaderboardName .. "::ColumnTwo^" .. rank .. "::ColumnThree^" .. tag
          else
            data = data .. "##LeaderBoardType^" .. leaderboardType .. "::LeaderBoardId^" .. leaderboardId .. "::ColumnOne^" .. leaderboardName .. "::ColumnTwo^" .. rank .. "::ColumnThree^" .. tag
          end
        end
        self.swf:Invoke("setTitleBarMode", 1)
        self.swf:Invoke("setData", data, rows)
      end
    end,
    SendCategoryDataToFlash = function(self, offset, count)
      local ds = DsTable.Find("BaseClient.LeaderBoard.CompiledEntries")
      local rows = ds:GetRowCount()
      local data
      Logger:print("leaderboards.lua", "SendCategoryDataToFlash " .. rows .. " rows")
      if rows > 0 then
        local name, character, topscore, id
        local endCount = offset + count
        if rows < endCount then
          endCount = rows
        end
        for i = offset, endCount - 1 do
          leaderboardType = ds:GetData(i, 5)
          leaderboardId = ds:GetData(i, 4)
          leaderboardName = ds:GetData(i, 6)
          name = ds:GetData(i, 1)
          score = ds:GetData(i, 3)
          local tag
          if tonumber(leaderboardType) == 0 then
            tag = "Stars: " .. score
          elseif tonumber(leaderboardType) == 1 then
            tag = "Score: " .. score
          elseif tonumber(leaderboardType) == 2 then
            tag = "Time: " .. math.floor(score / 60) .. "min " .. score % 60 .. "sec"
          elseif tonumber(leaderboardType) == 3 then
            tag = "Enemies: " .. score
          else
            tag = score
          end
          if i == offset then
            data = "LeaderBoardType^" .. leaderboardType .. "::LeaderBoardId^" .. leaderboardId .. "::ColumnOne^" .. leaderboardName .. "::ColumnTwo^" .. name .. "::ColumnThree^" .. tag
          else
            data = data .. "##LeaderBoardType^" .. leaderboardType .. "::LeaderBoardId^" .. leaderboardId .. "::ColumnOne^" .. leaderboardName .. "::ColumnTwo^" .. name .. "::ColumnThree^" .. tag
          end
        end
        self.swf:Invoke("setTitleBarMode", 2)
        self.swf:Invoke("setData", data, rows)
      else
        Logger:print("leaderboards.lua", "SendCategoryDataToFlash clearing load icon")
        self.swf:Invoke("ClearLoadingIcon")
      end
    end,
    SendLeaderBoardDataToFlash = function(self, offset, count)
      local ds = DsTable.Find("BaseClient.LeaderBoard.Entries")
      local rows = ds:GetRowCount()
      local data
      if rows > 0 then
        local rank, name, score, leaderboardId, leaderboardType
        local endCount = offset + count
        if rows < endCount then
          endCount = rows
        end
        for i = offset, endCount - 1 do
          rank = ds:GetData(i, 0)
          name = ds:GetData(i, 1)
          score = ds:GetData(i, 3)
          leaderboardId = ds:GetData(i, 4)
          leaderboardType = ds:GetData(i, 5)
          local tag
          if tonumber(leaderboardType) == 1 then
            tag = score
          elseif tonumber(leaderboardType) == 2 then
            tag = math.floor(score / 60) .. "min " .. score % 60 .. "sec"
          else
            tag = score
          end
          if i == offset then
            data = "LeaderBoardType^" .. leaderboardType .. "::LeaderBoardId^" .. leaderboardId .. "::ColumnOne^" .. rank .. "::ColumnTwo^" .. name .. "::ColumnThree^" .. tag
          else
            data = data .. "##LeaderBoardType^" .. leaderboardType .. "::LeaderBoardId^" .. leaderboardId .. "::ColumnOne^" .. rank .. "::ColumnTwo^" .. name .. "::ColumnThree^" .. tag
          end
        end
        self.swf:Invoke("setTitleBarMode", 3)
        self.swf:Invoke("setData", data, rows)
        if self.populatingWithMyRank == true then
          self.swf:Invoke("LuaHighlightItem", offset)
          self.populatingWithMyRank = false
        end
      end
    end,
    OnLeaderBoardData = function(self)
      local ds = DsTable.Find("BaseClient.LeaderBoard.Entries")
      local rows = ds:GetRowCount()
      local data
      Logger:print("leaderboards.lua", "OnLeaderBoardData " .. rows .. " rows")
      if rows > 0 then
        if self.currentCategory == 1 then
          self:SendMyLeaderBoardDataToFlash(0, 10)
        elseif self.waitingForDsUpdate then
          self.waitingForDsUpdate = false
          Ui.CopyResponseToCompiled()
          self:ProcessNextCategoryQuery()
        else
          self:SendLeaderBoardDataToFlash(0, 10)
        end
      elseif self.waitingForDsUpdate then
        self.waitingForDsUpdate = false
        Ui.CopyResponseToCompiled()
        self:ProcessNextCategoryQuery()
      else
        self.swf:Invoke("ClearLoadingIcon")
      end
    end,
    OnUserEvent = function(self, a, b, c, d, e, f)
      if tostring(a) == "Hide" then
        JobHandler:ModeSwitch(0)
      elseif tostring(a) == "SelectCategory" then
        self:SelectCategory(tonumber(b))
      elseif tostring(a) == "LeaderboardQuery" then
        Logger:print("leaderboards.lua", "Querying Leaderboard Type " .. tonumber(b) .. " Id " .. tonumber(c))
        self:SelectLeaderboard(tonumber(b), tonumber(c))
      elseif tostring(a) == "requestData" then
        if tonumber(b) == 1 then
          self:SendMyLeaderBoardDataToFlash(tonumber(c), tonumber(d))
        elseif tonumber(b) == 2 then
          self:SendCategoryDataToFlash(tonumber(c), tonumber(d))
        elseif tonumber(b) == 3 then
          self:SendLeaderBoardDataToFlash(tonumber(c), tonumber(d))
        end
      elseif tostring(a) == "SelectItem" then
        self:SelectLeaderboard(tonumber(b), tonumber(c))
      elseif tostring(a) == "FindMyRank" then
        Logger:print("leaderboards.lua", "Requesting my rank in current leaderboard")
        self:FindMyRank()
      end
    end
  }
  function Main_wndLeaderboard_swfLeaderboard_OnUserEvent(a, b, c, d, e, f)
    Leaderboards:OnUserEvent(a, b, c, d, e, f)
  end
end)()
;(function()
  PopUpPrompt = {
    windowName = Ui.GetName("Main.wndPopUpPrompt"),
    movieName = Ui.GetName("Main.wndPopUpPrompt.swfPopUpPrompt"),
    isShown = false,
    LT_ASK_FOR_HELP = 1,
    LT_CHAT_DISABLED = 2,
    Show = function(self)
      local window = Window.Find(self.windowName)
      self.isShown = true
      if window ~= nil then
        window:Show()
      end
      NonModalContext:AddContext(self)
      self:OnResize()
    end,
    Hide = function(self)
      NonModalContext:RemoveContext(self)
      local window = Window.Find(self.windowName)
      if window ~= nil then
        window:Hide()
      end
      self.isShown = false
    end,
    OnResize = function(self)
      local window = Window.Find(self.windowName)
      local w, h = window:GetSize()
      local sw, sh = Window.GetCanvasSize()
      if window ~= nil then
        window:SetPosition(sw / 2 - w / 2, sh / 2 - h / 2)
      end
    end,
    SetLayout = function(self, id)
      Logger:print("popupprompt.lua", "setting layout " .. id)
      local movie = GfxCtrl.Find(self.movieName)
      if movie ~= nil then
        movie:Invoke("populatePrompt", id)
      end
    end,
    OnUserEvent = function(a, b)
      if a == "Close" then
        PopUpPrompt:Hide()
      elseif a == "Accept" then
        PopUpPrompt:Hide()
      elseif a == "Cancel" then
        PopUpPrompt:Hide()
      end
      PopUpPrompt:CallDelegate("PopUpPromptOnUserEvent", a, b)
    end
  }
  Delegate:AddSupportToClassObject(PopUpPrompt, "PopUpPrompt")
  Main_wndPopUpPrompt_swfPopUpPrompt_OnUserEvent = PopUpPrompt.OnUserEvent
end)()
;(function()
  BuffWindow = {
    visible = false,
    buffs = {},
    Show = function(self)
      local wnd = Window.Find(Ui.GetName("Main.wndBuffs"))
      local swf = GfxCtrl.Find(Ui.GetName("Main.wndBuffs.swfBuffs"))
      if wnd and self.visible == false then
        self.visible = true
        local ds = DsTable.Find("BaseClient.PlayerEffectTags")
        ds:EnableScriptEvents()
        wnd:Show()
        self:OnResize()
        swf:Load()
        self:BuffsUpdated(true)
      end
    end,
    OnResize = function(self)
      local wnd = Window.Find(Ui.GetName("Main.wndBuffs"))
      if wnd then
        local sw, sh = Window.GetCanvasSize()
        local width, height = wnd:GetSize()
        wnd:SetPosition(10, 10 - height)
        wnd:Show()
        WindowTweener:Create("Main.wndBuffs", "Y", nil, 10, 0.4)
      end
    end,
    Hide = function(self)
      local wnd = Window.Find(Ui.GetName("Main.wndBuffs"))
      if wnd then
        local sw, sh = Window.GetCanvasSize()
        local ds = DsTable.Find("BaseClient.PlayerEffectTags")
        ds:DisableScriptEvents()
        WindowTweener:Create("Main.wndBuffs", "Y", nil, -1000, 0.39, function()
          GfxCtrl.Find(Ui.GetName("Main.wndBuffs.swfBuffs")):Unload()
          Window.Find(Ui.GetName("Main.wndBuffs")):Hide()
        end)
        self.visible = false
      end
    end,
    BuffsUpdated = function(self, fromShow)
      if self.visible == false then
        return
      end
      local swf = GfxCtrl.Find(Ui.GetName("Main.wndBuffs.swfBuffs"))
      for k, v in pairs(self.buffs) do
        v.stale = true
      end
      local ds = DsTable.Find("BaseClient.PlayerEffectTags")
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local instanceID = ds:GetData(i, 0)
          if self.buffs[instanceID] then
            self.buffs[instanceID].stale = false
          end
        end
      end
      for k, v in pairs(self.buffs) do
        if v.stale == true then
          swf:Invoke("removeBuff", k)
          self.buffs[k] = nil
        end
      end
      if ds then
        local numRows = ds:GetRowCount()
        local numCols = ds:GetColumnCount()
        for i = 0, numRows - 1 do
          local instanceID = ds:GetData(i, 0)
          if self.buffs[instanceID] and fromShow == false then
            self.buffs[instanceID].stale = false
          else
            local iconID = ds:GetData(i, 1)
            local duration = ds:GetData(i, 2)
            local timeLeft = ds:GetData(i, 3)
            local name = ds:GetData(i, 4)
            local tooltip = ds:GetData(i, 5)
            local cancellable = ds:GetData(i, 6)
            local targetSelf = ds:GetData(i, 7)
            local canCancel = 0
            if cancellable == "1" or targetSelf == "1" then
              canCancel = 1
            end
            if tonumber(iconID) ~= 0 then
              swf:Invoke("addBuff", instanceID, name, tooltip, iconID, timeLeft, canCancel)
              self.buffs[instanceID] = {stale = false, name = name}
            end
          end
        end
      end
    end,
    OnUserEvent = function(a, b)
      if a == "closeWindow" then
        JobHandler:ModeSwitch(0)
      elseif a == "cancelBuff" then
        if not b then
          return
        end
        Ui.RequestStripEffect(tonumber(b))
      end
    end
  }
  Main_wndBuffs_swfBuffs_OnUserEvent = BuffWindow.OnUserEvent
end)()
